  FT["PH-H15134"] = {"id":"PH-H15134","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 269  An Act Converting the Bugo Barangay High School in the Municipality of San Bemigio, Province of Antique, Into a National School, to Be Known as the Bugo National School.","orig":"Batas Pambansa Blg. 269  An Act Converting the Bugo Barangay High School in the Municipality of San Bemigio, Province of Antique, Into a National School, to Be Known as the Bugo National School.","vi":"Đạo luật chuyển đổi Trường Trung học Bugo Barangay tại Thị trấn San Bemigio, Tỉnh Antique thành Trường Quốc gia với tên gọi Trường Bugo Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Bugo Barangay ในเทศบาล San Bemigio จังหวัด Antique เป็น โรงเรียนแห่งชาติในชื่อโรงเรียน Bugo แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Bugo Barangay di Kotamadya San Bemigio, Provinsi Antique menjadi Sekolah Nasional dengan nama Sekolah Bugo Nasional","ms":"Akta menukar status Sekolah Menengah Bugo Barangay di Perbandaran San Bemigio, Wilayah Antique kepada Sekolah Kebangsaan dengan nama Sekolah Bugo Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 269","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00269_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00269_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15134-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Bugo Barangay High School in the Municipality of San Remigio, Province of Antique, is\nconverted into a national school, to be known as the Bugo National School."}},{"id":"PH-H15134-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools. Thereafter, such sum as may be necessary for its operation and maintenance shall be\nincluded in the annual General Appropriations Act."}},{"id":"PH-H15134-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 13, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15135"] = {"id":"PH-H15135","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 270  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of Glan, Province of South Cotabato, to Be Known as Glan Municipal Hospital, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 270  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of Glan, Province of South Cotabato, to Be Known as Glan Municipal Hospital, and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 270","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00270_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00270_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15135-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister (Ministry of\nHealth), a municipal hospital in the Municipality of Glan, Province of South Cotabato, to be known as Glan\nMunicipality Hospital."}},{"id":"PH-H15135-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15135-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: November 13, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15136"] = {"id":"PH-H15136","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 271  An Act Converting the Quirino Provincial High School in the Municipality of Cabarroguis, Province of Quirino, Into a General High School to Be Known as the Quirino General High School, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 271  An Act Converting the Quirino Provincial High School in the Municipality of Cabarroguis, Province of Quirino, Into a General High School to Be Known as the Quirino General High School, and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 271","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00271_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00271_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15136-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Quirino Provincial High School in the Municipality of Cabarroguis, Province of Quirino, is\nhereby converted into a general high school to be known as the Quirino General High School."}},{"id":"PH-H15136-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriation authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be necessary for its\noperation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15136-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 13, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15137"] = {"id":"PH-H15137","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 272  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of San Andres, Province of Romblon, to Be Known as the San Andres Municipal Hospital, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 272  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of San Andres, Province of Romblon, to Be Known as the San Andres Municipal Hospital, and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 272","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00272_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00272_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15137-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister (Ministry of\nHealth), a municipal hospital in the Municipality of San Andres, Province of Romblon, to be known as the\nSan Andres Municipal Hospital."}},{"id":"PH-H15137-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15137-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be made operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: November 13, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15138"] = {"id":"PH-H15138","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 273  An Act Converting San Dionisio Municipal High School in the Municipality of San Dionisio, Province of Iloilo, Into a National High School, to Be Known as the San Dionisio National High School, and Authorizing the Appropriation of Funds","orig":"Batas Pambansa Blg. 273  An Act Converting San Dionisio Municipal High School in the Municipality of San Dionisio, Province of Iloilo, Into a National High School, to Be Known as the San Dionisio National High School, and Authorizing the Appropriation of Funds","vi":"Đạo luật chuyển đổi Trường Trung học San Dionisio Đô thị tại Thị trấn San Dionisio, Tỉnh Iloilo thành Trường Trung học Quốc gia với tên gọi Trường Trung học San Dionisio Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา San Dionisio เทศบาลในเทศบาล San Dionisio จังหวัด Iloilo เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา San Dionisio แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah San Dionisio Kotamadya di Kotamadya San Dionisio, Provinsi Iloilo menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah San Dionisio Nasional","ms":"Akta menukar status Sekolah Menengah San Dionisio Perbandaran di Perbandaran San Dionisio, Wilayah Iloilo kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah San Dionisio Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 273","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-13","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00273_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00273_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15138-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The San Dionisio Municipal High School in the Municipality of San Dionisio, Province of Iloilo,\nis converted into a national high school, to be known as the San Dionisio National High School."}},{"id":"PH-H15138-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education and Culture is directed to take the necessary steps as are necessary for\nthe conversion and operation of the school and immediate implementation of this Act."}},{"id":"PH-H15138-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriation authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be necessary for its\noperation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15138-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 13, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15139"] = {"id":"PH-H15139","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 274  An Act Converting the Iligan City High School in the City of Iligan Into a National High School to Be Known as the Iligan City National High School and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 274  An Act Converting the Iligan City High School in the City of Iligan Into a National High School to Be Known as the Iligan City National High School and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Thành phố Iligan tại Thành phố Iligan thành Trường Trung học Quốc gia với tên gọi Trường Trung học Iligan Thành phố Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษาเมือง Iligan ในเมือง Iligan เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Iligan เมืองแห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Kota Iligan di Kota Iligan menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Iligan Kota Nasional","ms":"Akta menukar status Sekolah Menengah Bandar Iligan di Bandar Iligan kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Iligan Bandar Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 274","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00274_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00274_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15139-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Iligan City High School in the City of Iligan is converted into a national high school, to be\nknown as the Iligan City National High School."}},{"id":"PH-H15139-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be necessary for its\noperation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15139-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 13, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15140"] = {"id":"PH-H15140","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 275  An Act Changing the Name of the Municipality of Montalban, Province of Rizal, to the Municipality of Rodriguez.","orig":"Batas Pambansa Blg. 275  An Act Changing the Name of the Municipality of Montalban, Province of Rizal, to the Municipality of Rodriguez."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 275","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-12","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00275_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00275_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15140-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Municipality of Montalban, Province of Rizal, is changed to the Municipality of"}},{"id":"PH-H15140-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 13, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15141"] = {"id":"PH-H15141","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 276  An Act Converting the Binalonan Community High School in the Municipality of Binalonan, Province of Pangasinan, Into a National School to Be Known as the Binalonan National High School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 276  An Act Converting the Binalonan Community High School in the Municipality of Binalonan, Province of Pangasinan, Into a National School to Be Known as the Binalonan National High School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Binalonan Community tại Thị trấn Binalonan, Tỉnh Pangasinan thành Trường Quốc gia với tên gọi Trường Trung học Binalonan Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Binalonan Community ในเทศบาล Binalonan จังหวัด Pangasinan เป็น โรงเรียนแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Binalonan แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Binalonan Community di Kotamadya Binalonan, Provinsi Pangasinan menjadi Sekolah Nasional dengan nama Sekolah Menengah Binalonan Nasional","ms":"Akta menukar status Sekolah Menengah Binalonan Community di Perbandaran Binalonan, Wilayah Pangasinan kepada Sekolah Kebangsaan dengan nama Sekolah Menengah Binalonan Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 276","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00276_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00276_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15141-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Binalonan Community High School in the Municipality of Binalonan, Province of\nPangasinan, is hereby converted into a national school to be known as the Binalonan National High School.\nSaid school shall offer general secondary curriculum, vocational curriculum, and other technical courses."}},{"id":"PH-H15141-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Minister of Education and Culture is hereby empowered to reorganize said school\naccordingly."}},{"id":"PH-H15141-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be necessary for its\noperation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15141-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15142"] = {"id":"PH-H15142","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 277  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of Jamindan, Province of Capiz, to Be Known as the Jamindan Municipal Hospital, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 277  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of Jamindan, Province of Capiz, to Be Known as the Jamindan Municipal Hospital, and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 277","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00277_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00277_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15142-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister (Ministry of\nHealth), a municipal hospital in the Municipality of Jamindan, Province of Capiz, to be known as the\nJamindan Municipal Hospital."}},{"id":"PH-H15142-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15142-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may necessary for its\noperation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15143"] = {"id":"PH-H15143","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 278  An Act Establishing a School of Arts and Trades in the Municipality of Cagwait, Province of Surigao Del Sur, to Be Known as Cagwait School of Arts and Trades, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 278  An Act Establishing a School of Arts and Trades in the Municipality of Cagwait, Province of Surigao Del Sur, to Be Known as Cagwait School of Arts and Trades, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật thành lập Trường Nghệ thuật và Thương mại tại Thị trấn Cagwait, Tỉnh Surigao Del Sur với tên gọi Trường Nghệ thuật và Thương mại Cagwait","th":"พระราชบัญญัติจัดตั้งโรงเรียนศิลปะและหัตถกรรมในเทศบาล Cagwait จังหวัด Surigao Del Sur ในชื่อโรงเรียนศิลปะและหัตถกรรม Cagwait","id":"Undang-Undang membentuk Sekolah Seni dan Keterampilan di Kotamadya Cagwait, Provinsi Surigao Del Sur dengan nama Sekolah Seni dan Keterampilan Cagwait","ms":"Akta menubuhkan Sekolah Seni dan Pertukangan di Perbandaran Cagwait, Wilayah Surigao Del Sur dengan nama Sekolah Seni dan Pertukangan Cagwait"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 278","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00278_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00278_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15143-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There is hereby established, under the supervision of the Director of Higher Education, a school\nof arts and trades in the Municipality of Cagwait, Province of Surigao del Sur, to be known as the Cagwait\nSchool of Arts and Trades. Academic, industrial and vocational courses shall be offered in said school."}},{"id":"PH-H15143-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred fifty thousand pesos for the operation of the school shall be funded\nout of the appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture\nintended for new national schools of trade. Thereafter, such sum as may be needed for its operations and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15143-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15144"] = {"id":"PH-H15144","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 279  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in Paquibato, Davao City, to Be Known as the Paquibato Municipal Hospital and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 279  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in Paquibato, Davao City, to Be Known as the Paquibato Municipal Hospital and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 279","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00279_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00279_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15144-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister (Ministry of\nHealth), a municipal hospital in Paquibato Davao City, to be known as the Paquibato Municipal Hospital."}},{"id":"PH-H15144-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15144-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be made operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15145"] = {"id":"PH-H15145","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 280  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of Barbaza, Province of Antique, to Be Known as the Barbaza Municipal Hospital and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 280  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of Barbaza, Province of Antique, to Be Known as the Barbaza Municipal Hospital and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 280","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00280_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00280_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15145-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister (Ministry of\nHealth), a municipal hospital in the Municipality of Barbaza, Province of Antique, to be known as the Barbaza\nMunicipal Hospital."}},{"id":"PH-H15145-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15145-A409","no":409,"noLabel":{"en":"Section 409"},"text":{"en":"Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be made operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15146"] = {"id":"PH-H15146","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":20,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 281  An Act Converting the Antique School of Arts and Trades in the Municipality of Sibalom, Province of Antique Into the Polytechnic state College of Antique.","orig":"Batas Pambansa Blg. 281  An Act Converting the Antique School of Arts and Trades in the Municipality of Sibalom, Province of Antique Into the Polytechnic state College of Antique.","vi":"Đạo luật chuyển đổi Trường Nghệ thuật và Thương mại Antique tại Thị trấn Sibalom, Tỉnh Antique thành Cao đẳng Bang Bách khoa Antique","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนศิลปะและหัตถกรรม Antique ในเทศบาล Sibalom จังหวัด Antique เป็น วิทยาลัยของรัฐโพลีเทคนิค Antique","id":"Undang-Undang mengubah Sekolah Seni dan Keterampilan Antique di Kotamadya Sibalom, Provinsi Antique menjadi Sekolah Tinggi Negeri Politeknik Antique","ms":"Akta menukar status Sekolah Seni dan Pertukangan Antique di Perbandaran Sibalom, Wilayah Antique kepada Kolej Negeri Politeknik Antique"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 281","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 20 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00281_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00281_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15146-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The present Antique School of Arts and Trades in the Municipality of Sibalom, Province of\nAntique, is hereby converted into the Polytechnic State College of Antique, hereinafter referred to in this Act\nas the College which shall offer courses leading to the titles of Associate in Business Education, Associate in\nCommerce, four-year courses leading to the degrees of Bachelor of Science in Agriculture, Bachelor of\nScience in Home Technology, Bachelor of Science in Agricultural Education, Bachelor of Science in\nEducation, Bachelor of Science in Business Education, Bachelor of Science in Industrial Arts, Bachelor of\nScience in Industrial Education, Bachelor of Science in Agricultural Engineering, Bachelor of Science in\nForestry, Bachelor of Science in Fisheries, and five-year courses leading to the degrees of Master of Science\nin Agriculture, Master of Science in Agricultural Education, and Master of Arts in Education."}},{"id":"PH-H15146-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The College shall primarily provide higher technological, professional and vocational instruction\nand training in science, agricultural and industrial fields, as well as short-term technical or vocational courses.\nIt shall promote research, advanced studies and progressive leadership in its areas of specialization."}},{"id":"PH-H15146-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"In addition to its present curricular offerings, the College shall offer undergraduate and graduate\ncourses in the fields of science, agriculture and industry as the Board of Trustees may deem necessary."}},{"id":"PH-H15146-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"No student shall be denied admission, to the College by reason of sex, ethnic considerations, or\nreligious belief or affiliation."}},{"id":"PH-H15146-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The head of the College shall be known as the President of the Polytechnic State College of\nAntique. He shall be appointed by the President of the Philippines upon recommendation of the Board of\nTrustees. His salary shall be fixed by the Board of Trustees and shall be comparable to that being received by\npresident of similar educational institutions of like enrollment and standing, subject to existing budget laws on\nhonoraria and allowances.\nThe powers and duties of the President of the College, in addition to those specifically provided for in this\nAct, shall be those usually pertaining to the office of the president of a college."}},{"id":"PH-H15146-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The College shall be governed by a Board of Trustees which shall composed of the Minister of\nEducation and Culture as chairman, the President of the Polytechnic State College of Antique, and five (5)\nprominent citizens of the Province of Antique to be appointed by the President of the Philippines as members.\nOf the five appointed members one shall be a representative for science, one for agriculture, two for arts and\ntrades, and one for technology: Provided, That at least one of the five appointed members shall be an alumnus\nof the former Antique School of Arts and Trades and at least another one shall be a member of the\nParents-Teacher Association of the College. Of the first group appointed, the President of the Philippines shall\ndesignate one to serve for one year; one to serve for two years; one to serve for three years; one to serve for\nfour years; and one to serve for five years. Thereafter, persons appointed to succeed such members shall hold\noffice for a term of five years and until their successors who should be experts in the same field shall have\nbeen appointed and qualified. In case of permanent vacancy, the position shall be filled by appointment by the\nPresident of the Philippines. Such appointee shall hold office for the unexpired term only.\nWhen the Minister of Education and Culture is unable to perform his duties as Chairman of the Board due to\nillness, absence or other cause, or in case of a vacancy in the office, the Deputy Minister of Education and\n\nCulture shall temporarily perform the functions of the Chairman of the said Board. The Chairman may assign\nqualified officials to represent him with full authority in the Board."}},{"id":"PH-H15146-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all the members holding office\nat the time a meeting is called. All processes against the Board of Trustees shall be served on the President or\nSecretary thereof."}},{"id":"PH-H15146-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"The members of the Board of Trustees shall be entitled to an allowance of one hundred pesos per\nmeeting actually attended but not more than three hundred pesos a month: Provided, That they shall be\nreimbursed for actual and necessary expenses incurred either in attendance upon meetings of the Board or\nupon their official business authorized by resolution of the Board, subject to existing budget laws on honoraria\nand allowances."}},{"id":"PH-H15146-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"The Board of Trustees shall have the following powers and duties in addition to its general\npowers of administration, and the exercise of all the powers of a corporation as provided in Section Thirty-six\nof Batas Pambansa Blg. 68, otherwise known as the Corporation Code of the Philippines.\n(a) To receive and appropriate for the purposes specified by law such sums as may be provided for the support\nof the College;\n(b) To confer degrees upon successful candidates for graduation of the College. It may also confer honorary\ndegrees upon persons in recognition of learning, statesmanship or eminence in any of the fields of\nspecialization of the College, or in recognition of public service: Provided, That such degrees shall not be\nconferred in consideration of or to reciprocate some personal favor;\n(c) To authorize the President of the College to award proficiency certificate or diplomas to students who have\ncompleted non-degree courses;\n(d) To appoint, on recommendation of the President of the College, a vice-president, deans, directors,\nsecretary of the College, registrar, heads of departments, professors, instructors, lecturers and other officials\nand employees of the College, to fix their compensation subject to Presidential Decree No. 985 and other\npertinent budget and compensation laws, hours of service, and such other duties and conditions as it may\ndeem proper, to grant to them at its discretion, leave of absence under such regulations as it may promulgate,\nany provisions of existing law to the contrary notwithstanding; to remove them for cause after an investigation\nand hearing; to establish Chairs in the College, and to provide for the maintenance or endowment of such\nChairs as may be necessary;\n(e) To approve the curricula and rules of discipline drawn by the College Council as hereinafter provided;\n(f) To provide fellowships for qualified faculty members and scholarships to deserving students;\n(g) To prescribe rules for its own government and to enact for the government of the College such rules and\nregulations, not contrary to law, as may be necessary to carry out the purposes and functions of the College;\n(h) To receive in trust legacies, gifts, and donations of real and personal property of all kinds, to administer\nthe same for the benefit of the College, or the departments thereof, or for aid to any student or students, in\naccordance with the directions and instructions of the donor, and in default thereof, in such manner as the\nBoard of Trustees may in its discretion determine. All such donations shall be exempt from all taxes and to be\nconsidered as deductible items from the income tax of donors; and\n(j) To authorize the establishment of other branches of the College and to designate as its branches other\nschools of secondary level within the Province of Antique: Provided, That the funds for the purpose shall\ncome from its appropriation."}},{"id":"PH-H15146-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"On or before the fifteenth day of the second month after the opening of regular classes each\nyear, the Board of Trustees shall file with the Office of the President of the Philippines a detailed report,\nsetting forth the progress, conditions and needs of the College."}},{"id":"PH-H15146-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"There shall be a College Council consisting of the President of the College and all members of\nthe faculty with the rank of professors. The Council shall have the power to prescribe the curricula and rules\nof discipline, subject to approval of the Board of Trustees. It shall fix the requirements for admission to the\nCollege, as well as for graduation and the conferring of degrees subject to review by the Board of Trustees.\nThe Council alone shall have the power to recommend students or others to be recipients of degrees. Through\nthe President of the College or its duly authorized committee, the Council shall have disciplinary power over\nthe students within the limits prescribed by the rules of discipline."}},{"id":"PH-H15146-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"The body of instruction and professors of the College shall constitute the faculty of the College.\nThe faculty shall be covered by the appropriate civil service rules and regulations."}},{"id":"PH-H15146-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"No member of the faculty of the College shall attempt directly or indirectly, under penalty of\ndismissal by the Board of Trustees, to influence students or any person in the College towards any ideology,\npolitical or otherwise, which preaches the overthrow of the government through violence or subversion."}},{"id":"PH-H15146-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"There shall be a Secretary of the College who shall be appointed by the Board of Trustees upon\nrecommendation of the President of the College. He shall also be the Secretary of the Board and shall keep\nsuch records of the College as may be determined by the Board of Trustees."}},{"id":"PH-H15146-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"The treasurer of the Philippines shall be ex officio treasurer of the College and all accounts and\nexpenses thereof shall be audited by the Commission on Audit or its duly authorized representatives."}},{"id":"PH-H15146-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"Heads of bureaus and offices of the National Government are hereby authorized to loan or\ntransfer, upon request of the President of the College, such apparatus, equipment, supplies or the services of\nsuch employees as can be spared without serious detriment to the public service. Employees so detailed shall\nperform such duty required under such detail and the time so employed shall be counted as part of their\nregular official service."}},{"id":"PH-H15146-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"All assets including the present appropriation of the Antique School of Arts and Trades whether\nfixed or movable, records and personnel, are hereby transferred to the Polytechnic State College of Antique.\nThereafter, funds for the maintenance and operation of the College shall be included in the annual General\nAppropriations Act."}},{"id":"PH-H15146-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"The Minister of Education and Culture is hereby directed to take such steps as are necessary for\nthe immediate implementation of this Act."}},{"id":"PH-H15146-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"All laws inconsistent with the provisions of this Act are hereby repeal or amended accordingly."}},{"id":"PH-H15146-A20","no":20,"noLabel":{"en":"Section 20"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15147"] = {"id":"PH-H15147","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 282  An Act Converting the Albuera Municipal High School in the Municipality of Albuera, Province of Leyte, Into a National School of Fishery, to Be Known as the Albuera National School of Fishery.","orig":"Batas Pambansa Blg. 282  An Act Converting the Albuera Municipal High School in the Municipality of Albuera, Province of Leyte, Into a National School of Fishery, to Be Known as the Albuera National School of Fishery.","vi":"Đạo luật chuyển đổi Trường Trung học Albuera Đô thị tại Thị trấn Albuera, Tỉnh Leyte thành Trường Fishery Quốc gia với tên gọi Trường Albuera Fishery Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Albuera เทศบาลในเทศบาล Albuera จังหวัด Leyte เป็น โรงเรียน Fishery แห่งชาติในชื่อโรงเรียน Albuera Fishery แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Albuera Kotamadya di Kotamadya Albuera, Provinsi Leyte menjadi Sekolah Fishery Nasional dengan nama Sekolah Albuera Fishery Nasional","ms":"Akta menukar status Sekolah Menengah Albuera Perbandaran di Perbandaran Albuera, Wilayah Leyte kepada Sekolah Fishery Kebangsaan dengan nama Sekolah Albuera Fishery Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 282","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00282_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00282_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15147-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Albuera Municipal High School in the Municipality of Albuera, Province of Leyte, is\nhereby converted into a national school of fishery, to be known as the Albuera National School of Fishery."}},{"id":"PH-H15147-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education and Culture shall take the necessary steps for the immediate\nimplementation of this Act."}},{"id":"PH-H15147-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be necessary for its\noperation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15147-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15148"] = {"id":"PH-H15148","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 283  An Act Constituting Sitio Maawi, in Barangay Alos, Municipality of Alaminos, Province of Pangasinan, Into a New Barangay to Be Known as Barangay","orig":"Batas Pambansa Blg. 283  An Act Constituting Sitio Maawi, in Barangay Alos, Municipality of Alaminos, Province of Pangasinan, Into a New Barangay to Be Known as Barangay"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 283","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00283_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00283_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15148-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Sitio of Maawi in Barangay Alos, Municipality of Alaminos, Province of Pangasinan, is\nhereby separated from said barangay and constituted into a distinct and independent barangay of said\nmunicipality, to be known as Barangay Maawi."}},{"id":"PH-H15148-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Barangay Maawi shall be bounded and described as follows:\n\"A proposed Barangay Maawi, being a portion of Barangay Alos, Municipality of Alaminos, Province of\nPangasinan, Island of Luzon, Bounded on the N., along line M.B.M. No. 14-B.B.M. No. 51 by Barangay\nBalayang; on the N.E. at B.B.M. No. 51 by Barangay Bolaney and along line B.B.M. No. 51-B.B.M. No. 52\nby Barangay Alos Norte; on the S.E. along line B.B.M. No. 52-B.B.M. No. 58-M.B.M. No. 12 M.B.M. No.\n14, by the Municipality of Mabini. Beginning at a point marked M.B.M. No. 14 on the prepared proposed\nMaawi Plan, being S. 36 deg., 47’W., 5,592.25 m. from BLLM No. 1, CAD-325-D Alaminos Cadastre;\nthence S. 84 deg., 19’E., 836.28 m. to point B.B.M. No. 51; thence S. 27 deg., 00’E., 1422.56 m. to point\nB.B.M. No. 52; thence S. 35 deg., 41’W., 1110.18 m. to point B.B.M. No. 58; thence N. 67 deg., 26’W.,\n1216.96 m. to point M.B.M. No. 12; thence N. 09 deg., 20’E., 1807.19 m. to point of beginning, containing an\narea of one hundred seventy three point nine thousand four hundred twenty-two hectares (173.9422). All\npoints referred to are indicated on the plan and market on the ground by M.B.M. No. 14, B.B.M. No. 51,\nB.B.M. No. 52, B.B.M. No. 58 and M.B.M. No. 12. Bearings true, date prepared February 18, 1982.\""}}],"pack":"ph-p156"};
  FT["PH-H15149"] = {"id":"PH-H15149","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 284  An Act Constituting the Sitios of Bolo, Ballog, and Pandan in the, Barangay of Telbang, Municipality of Alaminos, Province of Pangasinan, Into a New Barangay to Be Known as Barangay Pandan.","orig":"Batas Pambansa Blg. 284  An Act Constituting the Sitios of Bolo, Ballog, and Pandan in the, Barangay of Telbang, Municipality of Alaminos, Province of Pangasinan, Into a New Barangay to Be Known as Barangay Pandan."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 284","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00284_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00284_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15149-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Sitios of Bolo, Ballog, and Pandan in the Barangay of Telbang, Municipality of Alaminos,\nProvince of Pangasinan, are hereby separated from said barangay and constituted into a distinct and\nindependent barangay of said municipality, to be known as Barangay Pandan."}},{"id":"PH-H15149-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Barangay Pandan shall be bounded and described as follows:\n\"A proposed Barangay Pandan, being a portion of Barangay Telbang, Municipality of Alaminos, Province of\nPangasinan, Island of Luzon. Bounded on the N. E., along lines 1-2-3-4 by Bolo Creek and Barangay\nTelbang; on the S.W., along line 4-5 by the Municipality of Sual; on the S.E., along lines 5-6 by Barangay\nSabangan; and on the N.W., along lines 6-1 by Tombac Bay. Beginning at a point marked ‘1’ on the prepared\nplan of proposed Barangay Pandan, being N. 73 deg., 30’E., 7,732.60 m. from BLLM No. 1 CAD. 325-D\nAlaminos Cadastre; thence S. 57 deg., 40’W., 801.34 m. to point 2; thence S.03 deg., 32’W., 584.03 m. to\npoint 3; thence S. 53 deg., 37’E., 2,893.69 m. to point 4; thence S. 55 deg., 07’W., 1,950.00 m. to point 5;\nthence N. 49 deg., 22’W., 4,391.99 m. to point 6; thence N. 73 deg., 29’E., 3,458 m. to point of beginning,\ncontaining an area of seven hundred forty eight point thirty two (748.32) hectares. All points referred to are\nindicated on the prepared plan and marked on the ground as follows; points 1, 2, 3, 4, & 6 by P.S. cyl. Conc.\nMons (15 x 60 cm.). Point 5 by M.B.M. No. 3. Bearings true, date prepared March 3, 1982.\""}}],"pack":"ph-p156"};
  FT["PH-H15150"] = {"id":"PH-H15150","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 285  An Act Constituting Sitio Balinpusa of Barangay Inerangan in the Municipality of Alaminos, Province of Pangasinan, Into a New Barangay to Be Known as Barangay San Antonio.","orig":"Batas Pambansa Blg. 285  An Act Constituting Sitio Balinpusa of Barangay Inerangan in the Municipality of Alaminos, Province of Pangasinan, Into a New Barangay to Be Known as Barangay San Antonio."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 285","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00285_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00285_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15150-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Sitio of Balinpusa of Barangay Inerangan, in the municipality of Alaminos, Province of\nPangasinan, is hereby separated from Barangay Inerangan and constituted into a new barangay in said\nmunicipality to be known as Barangay San Antonio."}},{"id":"PH-H15150-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Barangay San Antonio shall be bounded as follows:\n\"Bounded on the N., along line 2-1 by river, on the N.E., along line 1-5 by San Jose; on the S.E., along line\n5-4-3 by Barangay Pugo; and along line 3-2 by Barangay Landoc. Beginning at a point marked \"1\" on the\nprepared plan of proposed Barangay San Antonio, being N. 47°, 47?W., 4,296.91 m. from BLLM No. 1, CAD\n325-D Alaminos Cadastre; thence S. 88°, 42?W., 646.32 m. to point 2; thence S. 23°, 33?E 1,434.05 m. to\npoint 3; thence N. 07°, 31?E., 164.07 m. to point 4; thence N. 68°, 38?E., 544.54 m. to point 5; thence N.\n25°, 12?W., 1,071.07 m. to point of beginning, containing an area of seventy-two point eight hundred\neighty-three (72.883) hectares. All points referred to are indicated on the prepared plan and marked on the\nground as follows: points 1, 5, & 4 are B.B.M. No. 34, B.B.M. No. 31, & B.B.M. No. 30, respectively. Points\n3 & 2 are P.S. cyl. Conc. Mons. Bearings true.\""}}],"pack":"ph-p156"};
  FT["PH-H15151"] = {"id":"PH-H15151","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 286  An Act Constituting Sitio Landoc of Barangay Inerangan in the Municipality of Alaminos, Province of Pangasinan, Into a New Barangay to Be Known as Barangay Landoc.","orig":"Batas Pambansa Blg. 286  An Act Constituting Sitio Landoc of Barangay Inerangan in the Municipality of Alaminos, Province of Pangasinan, Into a New Barangay to Be Known as Barangay Landoc."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 286","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00286_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00286_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15151-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Sitio of Landoc in Barangay Inerangan, Municipality of Alaminos, Province of Pangasinan,\nis hereby separated from Barangay Inerangan and constituted into a new barangay in said municipality to be\nknown as Barangay Landoc."}},{"id":"PH-H15151-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Barangay Landoc shall be bounded and described as follows:\n\"A proposed Barangay Landoc, being a portion of Barangay Inerangan, Municipality of Alaminos, Province\nof Pangasinan, Island of Luzon. Bounded on the N.E., along line 3-4 by proposed Barangay San Antonio; on\nthe S.E., along line 4-1 by Barangay Pugo (now), Barangay San Roque (before); at point 1, by Barangay\nAmambangan; and on the S.W., along line 1-2 by Barangay Tawin-Tawin; on the N.W., along line 2-3 by\nBarangay Inerangan. Beginning at a point marked \"1\" on the proposed plan of Barangay Landoc, being N.\n66°, 58?W., 3,559.77 m. from BLLM No. 1, CAD-325-D Alaminos Cadastre; thence N. 55°, 29?W., 154.43\nm. to point 2; thence N. 50°, 00?E., 940.00 m. to point 3; thence S. 23°, 33?E., 1,434.05 m. to point 4; thence\nS. 07 deg. 31?W., 164.40 m. to point of beginning, containing an area of seventy-six point zero one hundred\nthirty four hectares (76.0134). All points referred to are indicated on the prepared plan and marked on the\nground as follows: points 2, 3 & 4 are P.S. cyl. Conc. Mons. (15 x 60 cm.); point 1 by B.B.M. No. 29.\nBearings true, date prepared Feb. 18, 1982.\""}}],"pack":"ph-p156"};
  FT["PH-H15152"] = {"id":"PH-H15152","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 287  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of Tabango, Province of Leyte, to Be Known as Tabango Community Hospital, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 287  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of Tabango, Province of Leyte, to Be Known as Tabango Community Hospital, and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 287","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00287_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00287_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15152-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister, (Ministry of\nHealth), a ten-bed municipal hospital in the Municipality of Tabango, Province of Leyte, to be known as the\nTabango Community Hospital."}},{"id":"PH-H15152-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15152-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sums as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be made operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15153"] = {"id":"PH-H15153","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 288  An Act Converting the Dolores Provincial High School in the Municipality of Dolores, Province of Eastern Samar Into a National High School, to Be Known as the Dolores National High School.","orig":"Batas Pambansa Blg. 288  An Act Converting the Dolores Provincial High School in the Municipality of Dolores, Province of Eastern Samar Into a National High School, to Be Known as the Dolores National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Dolores Tỉnh tại Thị trấn Dolores, Tỉnh Eastern Samar thành Trường Trung học Quốc gia với tên gọi Trường Trung học Dolores Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Dolores จังหวัดในเทศบาล Dolores จังหวัด Eastern Samar เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Dolores แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Dolores Provinsi di Kotamadya Dolores, Provinsi Eastern Samar menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Dolores Nasional","ms":"Akta menukar status Sekolah Menengah Dolores Wilayah di Perbandaran Dolores, Wilayah Eastern Samar kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Dolores Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 288","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00288_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00288_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15153-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Dolores Provincial High School in the Municipality of Dolores, Province of Eastern Samar,\nin converted into a national high school, to be known as the Dolores National High School."}},{"id":"PH-H15153-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be necessary for its\noperation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15153-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15154"] = {"id":"PH-H15154","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 289  An Act Converting the Carmona Relocation Center High School in the Municipality of General Mariano Alvarez, Province of Cavite, Into a Vocational and Technical High School and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 289  An Act Converting the Carmona Relocation Center High School in the Municipality of General Mariano Alvarez, Province of Cavite, Into a Vocational and Technical High School and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 289","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00289_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00289_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15154-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The present Carmona Relocation Center High School in the Municipality of General Mariano\nAlvarez, Province of Cavite, is hereby converted into a vocational and technical high school to be known as\nthe General Mariano Alvarez Technical High School, hereinafter referred to in this Act as the School."}},{"id":"PH-H15154-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The School shall be under the control and supervision of the Ministry of Education and Culture\nwhich shall be responsible for the staffing, curricula development and the promulgation of rules and\nregulations on discipline."}},{"id":"PH-H15154-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"All employees of the School shall be covered by the civil service law on eligibility for\npermanent appointment pursuant to Presidential Decree Numbered Eight hundred seven and its implementing\nregulations."}},{"id":"PH-H15154-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"All assets of the Carmona Relocation Center High School, whether immovable or movable,\nrecords and personnel are hereby transferred to the General Mariano Alvarez Technical High School."}},{"id":"PH-H15154-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be necessary for its\noperation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15154-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15155"] = {"id":"PH-H15155","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 290  An Act Converting the Batu-Batu Barangay High School in the Municipality of Balimbing, Province of Tawi-Tawi, Into a National High School, to Be Known as Batu-Batu National High School, and Authorizing the Appropriation of Funds","orig":"Batas Pambansa Blg. 290  An Act Converting the Batu-Batu Barangay High School in the Municipality of Balimbing, Province of Tawi-Tawi, Into a National High School, to Be Known as Batu-Batu National High School, and Authorizing the Appropriation of Funds","vi":"Đạo luật chuyển đổi Trường Trung học Batu-Batu Barangay tại Thị trấn Balimbing, Tỉnh Tawi-Tawi thành Trường Trung học Quốc gia với tên gọi Trường Trung học Batu-Batu Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Batu-Batu Barangay ในเทศบาล Balimbing จังหวัด Tawi-Tawi เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Batu-Batu แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Batu-Batu Barangay di Kotamadya Balimbing, Provinsi Tawi-Tawi menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Batu-Batu Nasional","ms":"Akta menukar status Sekolah Menengah Batu-Batu Barangay di Perbandaran Balimbing, Wilayah Tawi-Tawi kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Batu-Batu Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 290","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00290_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00290_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15155-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Batu-Batu Barangay High School in the Municipality of Balimbing, Province of Tawi-Tawi,\nis hereby converted into a national high school, to be known as Batu-Batu National High School."}},{"id":"PH-H15155-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operations of the school shall be funded out\nof the appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture\nintended for new national schools: Provided, That the local government unit concerned shall continue to\nprovide its share in the cost of operating and maintaining said school. Thereafter, such sum as may be\nnecessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15155-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15156"] = {"id":"PH-H15156","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 291  An Act Changing the Name of the Municipality of Magsaysay, in the Province of Isabela, to the Municipality of Delfin Albano.","orig":"Batas Pambansa Blg. 291  An Act Changing the Name of the Municipality of Magsaysay, in the Province of Isabela, to the Municipality of Delfin Albano."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 291","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00291_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00291_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15156-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Municipality of Magsaysay, in the Province of Isabela, shall hereafter be known as the\nMunicipality of Delfin Albano."}},{"id":"PH-H15156-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15157"] = {"id":"PH-H15157","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 292  An Act Converting the Solsona Municipal High School in the Municipality of Solsona, Province of Ilocos Norte, Into a National High School to Be Known as the Solsona National High School, and Authorizing the Appropriation of Funds","orig":"Batas Pambansa Blg. 292  An Act Converting the Solsona Municipal High School in the Municipality of Solsona, Province of Ilocos Norte, Into a National High School to Be Known as the Solsona National High School, and Authorizing the Appropriation of Funds","vi":"Đạo luật chuyển đổi Trường Trung học Solsona Đô thị tại Thị trấn Solsona, Tỉnh Ilocos Norte thành Trường Trung học Quốc gia với tên gọi Trường Trung học Solsona Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Solsona เทศบาลในเทศบาล Solsona จังหวัด Ilocos Norte เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Solsona แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Solsona Kotamadya di Kotamadya Solsona, Provinsi Ilocos Norte menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Solsona Nasional","ms":"Akta menukar status Sekolah Menengah Solsona Perbandaran di Perbandaran Solsona, Wilayah Ilocos Norte kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Solsona Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 292","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00292_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00292_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15157-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Solsona Municipal High School in the Municipality of Solsona, Province of Ilocos Norte, is\nconverted into a national high school to be known as the Solsona National High School."}},{"id":"PH-H15157-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools; Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be necessary for its\noperation and maintenance shall be included in the annual General Appropriations Acts."}},{"id":"PH-H15157-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15158"] = {"id":"PH-H15158","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 293  An Act Converting the Bangui Provincial High School and Its Annexes and the Banban Barangay High School in the Municipality of Bangui, Province of Ilocos Norte, Into a National High School, and Authorizing the Appropriation of Funds","orig":"Batas Pambansa Blg. 293  An Act Converting the Bangui Provincial High School and Its Annexes and the Banban Barangay High School in the Municipality of Bangui, Province of Ilocos Norte, Into a National High School, and Authorizing the Appropriation of Funds"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 293","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00293_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00293_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15158-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Bangui Provincial High School and its annexes and the Banban Barangay High School in\nthe Municipality of Bangui, Province of Ilocos Norte, are converted into a national high school, to be known\nas the Bangui National High School."}},{"id":"PH-H15158-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"A curriculum which includes academic, industrial arts, ceramics, electricity, handicraft and other\nallied courses shall be offered."}},{"id":"PH-H15158-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Minister of Education and Culture shall reorganize the said schools accordingly."}},{"id":"PH-H15158-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Upon the organization of the new school, the assets, liabilities, personnel, equipment and records\nof the old schools shall be transferred to new national high school."}},{"id":"PH-H15158-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be necessary for its\noperation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15158-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15159"] = {"id":"PH-H15159","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 294  An Act Converting the City High School Located in the South Central School Campus in Barangay sto. Domingo, City of Iriga, Into a National Technical Vocational School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 294  An Act Converting the City High School Located in the South Central School Campus in Barangay sto. Domingo, City of Iriga, Into a National Technical Vocational School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Thành phố tại Barangay sto. Domingo, Thành phố Iriga thành Trường Kỹ thuật - Dạy nghề Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษาเมืองในบารังไกย์ sto. Domingo เมือง Iriga เป็น โรงเรียนเทคนิค-อาชีวศึกษาแห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Kota di Barangay sto. Domingo, Kota Iriga menjadi Sekolah Teknik-Kejuruan Nasional","ms":"Akta menukar status Sekolah Menengah Bandar di Barangay sto. Domingo, Bandar Iriga kepada Sekolah Teknikal-Vokasional Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 294","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00294_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00294_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15159-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The City High School located inside the South Central School campus in Barangay Sto.\nDomingo, City of Iriga, is hereby converted into a national technical vocational school to be known as the\nRinconada National Technical Vocational School."}},{"id":"PH-H15159-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Minister of Education and Culture shall be empowered to reorganize the school in order to\nfacilitate vocational and technological courses which shall be added to the general academic curriculum."}},{"id":"PH-H15159-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The transfer of all assets, records and personnel of the City High School to the Rinconada\nNational Technical Vocational School shall be coordinated by the Minister of Education and Culture."}},{"id":"PH-H15159-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be necessary for its\noperation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15159-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15160"] = {"id":"PH-H15160","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 295  An Act Converting the Quezon Provincial High School in the City of Lucena Into a National High School to Be Known as the Quezon National High","orig":"Batas Pambansa Blg. 295  An Act Converting the Quezon Provincial High School in the City of Lucena Into a National High School to Be Known as the Quezon National High"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 295","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00295_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00295_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15160-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Quezon Provincial High School in the City of Lucena is converted into a national high\nschool to be known as the Quezon National High School."}},{"id":"PH-H15160-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sums as may be necessary for its\noperation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15160-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15161"] = {"id":"PH-H15161","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 296  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of Upi, Province of Maguindanao, to Be Known as the Upi Municipal Hospital and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 296  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of Upi, Province of Maguindanao, to Be Known as the Upi Municipal Hospital and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 296","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00296_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00296_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15161-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister (Ministry of\nHealth), a ten-bed municipal hospital in the Municipality of Upi, Province of Maguindanao, to be known as\nthe Upi Municipal Hospital."}},{"id":"PH-H15161-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15161-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be made operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15162"] = {"id":"PH-H15162","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 297  An Act Establishing a Municipal Hospital in the Municipality of Manay, Province of Davao Oriental, to Be Known as Manay Emergency Hospital.","orig":"Batas Pambansa Blg. 297  An Act Establishing a Municipal Hospital in the Municipality of Manay, Province of Davao Oriental, to Be Known as Manay Emergency Hospital.","vi":"Đạo luật thành lập Bệnh viện Đô thị tại Thị trấn Manay, Tỉnh Davao Oriental với tên gọi Bệnh viện Cấp cứu Manay","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาลในเทศบาล Manay จังหวัด Davao Oriental ในชื่อโรงพยาบาลฉุกเฉิน Manay","id":"Undang-Undang membentuk Rumah Sakit Kotamadya di Kotamadya Manay, Provinsi Davao Oriental dengan nama Rumah Sakit Gawat Darurat Manay","ms":"Akta menubuhkan Hospital Perbandaran di Perbandaran Manay, Wilayah Davao Oriental dengan nama Hospital Kecemasan Manay"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 297","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00297_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00297_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15162-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister (Ministry of\nHealth), a ten-bed capacity municipal hospital in the Municipality of Manay, Province of Davao Oriental, to\nbe known as the Manay Emergency Hospital."}},{"id":"PH-H15162-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15162-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be made operational.\nSection 3. This Act shall take effect upon approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15163"] = {"id":"PH-H15163","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 298  An Act Establishing a School of Fisheries in the Municipality of Lupon, Province of Davao Oriental, to Be Known as the Lupon School of Fisheries.","orig":"Batas Pambansa Blg. 298  An Act Establishing a School of Fisheries in the Municipality of Lupon, Province of Davao Oriental, to Be Known as the Lupon School of Fisheries.","vi":"Đạo luật thành lập Trường Thủy sản tại Thị trấn Lupon, Tỉnh Davao Oriental với tên gọi Trường Thủy sản Lupon","th":"พระราชบัญญัติจัดตั้งโรงเรียนประมงในเทศบาล Lupon จังหวัด Davao Oriental ในชื่อโรงเรียนประมง Lupon","id":"Undang-Undang membentuk Sekolah Perikanan di Kotamadya Lupon, Provinsi Davao Oriental dengan nama Sekolah Perikanan Lupon","ms":"Akta menubuhkan Sekolah Perikanan di Perbandaran Lupon, Wilayah Davao Oriental dengan nama Sekolah Perikanan Lupon"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 298","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00298_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00298_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15163-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established a school of fisheries in the Municipality of Lupon, Province of Davao\nOriental, to be known as the Lupon School of Fisheries."}},{"id":"PH-H15163-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred fifty thousand pesos for the operation of the school shall be funded\nout of the appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture\nintended for new national schools: Provided, That the local government unit concerned shall continue to\nprovide its share in the cost of operating and maintaining said school. Thereafter, such sum as may be\nnecessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15163-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15164"] = {"id":"PH-H15164","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 299  An Act Establishing a Ten-Bed Capacity Municipal Hospital in the Municipality of Socorro, Province of Surigao Del Norte, to Be Known as Socorro Emergency Hospital, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 299  An Act Establishing a Ten-Bed Capacity Municipal Hospital in the Municipality of Socorro, Province of Surigao Del Norte, to Be Known as Socorro Emergency Hospital, and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 299","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00299_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00299_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15164-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the direct supervision of the Office of the Minister (Ministry of\nHealth), a ten-bed capacity municipal hospital in the Municipality of Socorro, Province of Surigao del Norte,\nto be known as the Socorro Emergency Hospital."}},{"id":"PH-H15164-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15164-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be made operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15165"] = {"id":"PH-H15165","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 300  An Act Establishing a Municipal Hospital in the Municipality of San Narciso, Province of Quezon, to Be Known as the San Narciso Municipal Hospital, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 300  An Act Establishing a Municipal Hospital in the Municipality of San Narciso, Province of Quezon, to Be Known as the San Narciso Municipal Hospital, and Appropriating Funds therefor.","vi":"Đạo luật thành lập Bệnh viện Đô thị tại Thị trấn San Narciso, Tỉnh Quezon với tên gọi Bệnh viện San Narciso Đô thị","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาลในเทศบาล San Narciso จังหวัด Quezon ในชื่อโรงพยาบาล San Narciso เทศบาล","id":"Undang-Undang membentuk Rumah Sakit Kotamadya di Kotamadya San Narciso, Provinsi Quezon dengan nama Rumah Sakit San Narciso Kotamadya","ms":"Akta menubuhkan Hospital Perbandaran di Perbandaran San Narciso, Wilayah Quezon dengan nama Hospital San Narciso Perbandaran"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 300","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00300_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00300_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15165-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the direct supervision of the Office of the Minister (Ministry of\nHealth), a ten-bed capacity hospital in the Municipality of San Narciso, Province of Quezon, to be known as\nthe San Narciso Municipal Hospital. This hospital shall be an extension of the Quezon Provincial Hospital."}},{"id":"PH-H15165-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Chief of the Quezon Provincial Hospital shall assign or detail medical personnel under him\nto the San Narciso Municipal Hospital."}},{"id":"PH-H15165-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15165-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be made operational.\nSection 4. This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15166"] = {"id":"PH-H15166","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 301  An Act Changing the Name of the National Orthopedic Hospital in Quezon City to National Orthopedic Hospital and Rehabilitation Medicine Center.","orig":"Batas Pambansa Blg. 301  An Act Changing the Name of the National Orthopedic Hospital in Quezon City to National Orthopedic Hospital and Rehabilitation Medicine Center."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 301","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00301_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00301_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15166-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the National Orthopedic Hospital in Quezon City is hereby changed to National\nOrthopedic Hospital and Rehabilitation Medicine Center."}},{"id":"PH-H15166-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15167"] = {"id":"PH-H15167","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 302  An Act Establishing a National General High School in the Municipality of Bangued, Province of Abra, to Be Known as the Abra High School and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 302  An Act Establishing a National General High School in the Municipality of Bangued, Province of Abra, to Be Known as the Abra High School and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 302","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00302_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00302_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15167-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established a national general high school in the Municipality of Bangued,\nProvince of Abra, to be known as the Abra High School."}},{"id":"PH-H15167-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The school shall be accommodated in the campus of the present Abra School of Arts and Trades."}},{"id":"PH-H15167-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The building owned by the old Abra High School before its conversion into the Abra National\nTrade School and finally into the Abra School of Arts And Trades shall be transferred to the new Abra High"}},{"id":"PH-H15167-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The amount of one hundred fifty thousand pesos for the operation of the school shall be funded\nout of the appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture\nintended for new national schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15167-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15168"] = {"id":"PH-H15168","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 303  An Act Establishing a Municipal Hospital in the Municipality of Barotac Nuevo Province of Iloilo, to Be Known as the Barotac Nuevo Municipal Hospital and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 303  An Act Establishing a Municipal Hospital in the Municipality of Barotac Nuevo Province of Iloilo, to Be Known as the Barotac Nuevo Municipal Hospital and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 303","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00303_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00303_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15168-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister (Ministry of\nHealth), a ten-bed municipal hospital in the Municipality of Barotac Nuevo, Province of Iloilo, to be known as\nthe Barotac Nuevo Municipal Hospital."}},{"id":"PH-H15168-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the Hospital shall be determined in accordance with"}},{"id":"PH-H15168-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be made operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15169"] = {"id":"PH-H15169","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":25,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 304  An Act Converting the Tiburcio Tancinco Memorial Vocational School in the City of Calbayog Into An Institute of Science and Technology to Be Known as the Tiburcio Tancinco Memorial Institute of Science and Technology, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 304  An Act Converting the Tiburcio Tancinco Memorial Vocational School in the City of Calbayog Into An Institute of Science and Technology to Be Known as the Tiburcio Tancinco Memorial Institute of Science and Technology, and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Tưởng niệm Dạy nghề Tiburcio Tancinco tại Thành phố Calbayog thành Học viện Khoa học và Công nghệ với tên gọi Học viện Khoa học và Công nghệ Tưởng niệm Tiburcio Tancinco","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนอนุสรณ์อาชีวศึกษา Tiburcio Tancinco ในเมือง Calbayog เป็น สถาบันวิทยาศาสตร์และเทคโนโลยีในชื่อสถาบันวิทยาศาสตร์และเทคโนโลยีอนุสรณ์ Tiburcio Tancinco","id":"Undang-Undang mengubah Sekolah Memorial Kejuruan Tiburcio Tancinco di Kota Calbayog menjadi Institut Sains dan Teknologi dengan nama Institut Sains dan Teknologi Memorial Tiburcio Tancinco","ms":"Akta menukar status Sekolah Memorial Vokasional Tiburcio Tancinco di Bandar Calbayog kepada Institut Sains dan Teknologi dengan nama Institut Sains dan Teknologi Memorial Tiburcio Tancinco"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 304","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 25 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00304_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00304_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15169-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Tiburcio Tancinco Memorial Vocational School in the City of Calbayog is converted into an\ninstitute of science and technology to be known as the Tiburcio Tancinco Memorial Institute of Science and\nTechnology, hereinafter referred to as the Institute."}},{"id":"PH-H15169-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Institute shall primarily provide higher technological, professional and vocational\ninstruction and training in trade, fishery, agriculture, science, education, commerce, and engineering. It shall\nalso promote research, advanced studies and progressive leadership in its areas of specialization."}},{"id":"PH-H15169-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"In addition to its present evening opportunity classes, short vocational courses, secondary\ncourses, and collegiate offerings in trade and industrial education, the Institute shall offer graduate courses\nleading to the degrees of Master of Arts in Industrial Education, Master of Arts in Vocational Education,\nMaster of Arts in Teaching Vocational Education, Master of Arts in Education; the five-year engineering\ncourses, particularly those leading to the degrees of Bachelor of Science in Civil Engineering, Industrial\nEngineering, Electrical Engineering, Mechanical Engineering, Marine Engineering, Mining Engineering,\nChemical Engineering, Architecture, and such collegiate courses as Commerce, Agriculture, Fishery, and\nother offerings in various fields of specialization as the Board of Trustees may deem necessary. Evening\nclasses in the above-mentioned courses shall be offered."}},{"id":"PH-H15169-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The governing body of the Institute shall be the Board of Trustees of the Tiburcio Tancinco\nMemorial Institute of Science and Technology, to be composed of the Minister of Education and Culture, who\nshall be the Chairman of the Board; the President of the Institute, Vice-Chairman; and, as members of the\nBoard, the Regional Director of Ministry of Education and Culture for Region VIII, the Regional Director of\nthe National Economic and Development Authority for Region VIII, the President of the Alumni Association\nof the Institute, and two prominent citizens of Region VIII who shall be appointed by the President of the\nPhilippines upon recommendation of the Minister of Education and Culture. Of the two appointed members,\none shall be an authority in science and technology, and the other, a successful industrialist of Region VIII. In\nthe absence of the Minister of Education and Culture or in the event that there is no incumbent Minister of\nEducation and Culture, his functions as Chairman of the Board shall be temporarily performed by the Deputy\nMinister of Education and Culture. In the absence or inability of both the Minister and the Deputy Minister of\nEducation and Culture or when these positions are vacant, the other members of the Board may elect from\namong themselves a temporary Chairman of the Board."}},{"id":"PH-H15169-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The Board of Trustees shall exercise policy-making functions in accordance with the general\npolicies, plans, and programs on education as may be formulated by the National Board of Education and the\nMinister of Education and Culture as well as the general policies, plans, and programs on national and\nregional development as may be issued by the National Economic and Development Authority."}},{"id":"PH-H15169-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Subject to the provisions of Section five hereof, the Board of Trustees shall have the following\nspecific powers and duties in addition to its general powers of administration and the exercise of all powers of\na corporation as provided in Section thirty-six of Batas Pambansa Blg. 68, otherwise known as the\n\nCorporation Code of Philippines:\na. To receive and appropriate for the purposes specified by law such amounts as may be provided for the\nsupport of the Institute;\nb. To confer degrees upon successful candidates for graduation from the Institute. It may also confer honorary\ndegrees upon persons in recognition of learning, statesmanship, or eminence in any of the fields of\nspecialization of the Institute, or in recognition of public service; Provided, That such degrees shall not be\nconferred in consideration or reciprocation of some personal favor;\nc. To authorize the President of the Institute to award certificates or diplomas to students who satisfactorily\ncomplete non-degree courses;\nd. To appoint, upon recommendation of the President of the Institute, the deans, directors, registrar, heads of\ndepartments, professors, assistant professors, instructors, lecturers, and other officials and employees of the\nInstitute; to fix their compensation subject to Presidential Decree No. 985 and other pertinent budget and\ncompensation laws, hours of service, and other duties or conditions as it may deem proper, to grant them, in\nits discretion, leaves of absence under such regulations as it may promulgate; and to remove them for cause\nafter an investigation and hearing pursuant to civil service law governing disciplinary action;\ne. To establish chairs in the Institute and to provide maintenance or endowment for them as may be necessary;\nf. To approve the curricula and rules of discipline drawn by the College Council;\ng. To provide fellowship for qualified faculty members and scholarship to deserving students.\nh. To prescribe rules for its own government and to enact for the government of the Institute such rules and\nregulations, not contrary to law, as may be necessary to carry out the purpose and functions of the Institute;\ni. To receive in trust legacies, gifts, and donations of real and personal property of all kinds and to administer\nsame for the benefit of the Institute or the departments thereof, in such manner as the Board of Trustees may,\nin its discretion, determine. All such donations shall be exempt from all taxes and shall be considered as\ndeductible items from the income tax of the donors;\nj. To authorize the President of the Institute to undertake the construction or repair of its buildings,\nmachineries, equipment, and other facilities: Provided, That funds for the purpose shall come from the\nauthorized appropriation of the Institute."}},{"id":"PH-H15169-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"The members and the Secretary of the Board of Trustees shall serve without compensation but\nshall be entitled to a per diem of two hundred pesos (P200.00) per meeting actually attended: Provided, That\nthe aggregate amount of per diem shall not exceed four hundred pesos (P400.00) during any month for each\nmember and the Secretary. The Institute shall reimburse them for actual and necessary expenses incurred\neither in attendance of meetings of the Board or on official business authorized by resolution of the Board,\nsubject to existing budget laws on honoraria and allowances."}},{"id":"PH-H15169-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"A quorum of the Board of Trustees shall consist of the majority of all members holding office at\nthe time the meeting of the Board is called."}},{"id":"PH-H15169-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"All processes against the Board of Trustees shall be served on the President of the Institute."}},{"id":"PH-H15169-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"On or before the fifteenth day of the second month after the opening of regular classes each\nyear, the Board of Trustees shall submit to the President of the Philippines, through the Minister of Education\nand Culture, a detailed report setting forth the progress, conditions, and the needs of the Institute."}},{"id":"PH-H15169-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"The head of the Institute shall be known as the President of the Tiburcio Tancinco Memorial\nInstitute of Science and Technology. He shall be appointed by the President of the Philippines upon\nrecommendation of the Board of Trustees. His salary shall be fixed by the Board, comparable to that being\nreceived by president of similar institutions, subject to Presidential Decree No. 985 and other pertinent budget\nand compensation laws. The powers and duties of the President of the Institute, in addition to those\n\nspecifically provided for in this Act, shall be those pertaining to the Office of the President of a state college."}},{"id":"PH-H15169-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"The Treasurer of the Republic of the Philippines shall be the ex officio Treasurer of the\nInstitute. All accounts and expenses of the Institute shall be audited by the Commission Audit or its duly\nauthorized representative."}},{"id":"PH-H15169-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"There shall be a Secretary of the Institute who shall be appointed by the Board of Trustees upon\nrecommendation of the President of the Institute. He shall also be the Secretary of the Board of Trustees and\nshall keep such records of the Institute as may de determined by the Board."}},{"id":"PH-H15169-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"There shall be a College Council consisting of the President of the Institute and all the members\nof the faculty with the rank of professor. The Council shall have the power to prescribe the curricula and rules\nof discipline, subject to the approval of the Board of Trustees. It shall fix the requirements for admission to,\nand graduation from, the Institute as well as the conferring of degrees, subject to review by the Board. The\nCouncil alone shall have the power to recommend students or others to be recipients of degrees. Through the\nPresident of the Institute or a duly authorized committee, the Council shall have disciplinary power over the\nstudents within the limits prescribed by the rules of discipline."}},{"id":"PH-H15169-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"The body of college deans, registrar, heads of departments, professors, and instructors shall\nconstitute the faculty of the Institute, with the President of the Institute as the presiding officer. Members of\nthe faculty shall be conveyed by the appropriate civil service rules and regulations.\nIn the appointment of members of the faculty, no party loyalty check or religious test shall be applied, nor\nshall religious opinion or affiliation be a matter of inquiry: Provided, That no member of the faculty shall\nteach for or against any particular church or religious sect."}},{"id":"PH-H15169-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"No member of the faculty of the Institute shall attempt directly or indirectly, under penalty of\ndismissal by the Board of Trustees, to influence students or any other person in the Institute towards any\nideology, political, or otherwise, which preaches the overthrow of the government through violence of\nsubversion."}},{"id":"PH-H15169-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"No student shall be denied admission to the Institute by reason of sex, ethnic consideration,\nreligion, or political affiliation."}},{"id":"PH-H15169-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"The President of the Institute, in cooperation with the City Schools Superintendent of\nCalbayog, may use once or more of the city elementary or secondary schools as training or laboratory for\nstudent teaching of the Institute."}},{"id":"PH-H15169-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"Heads of bureaus and offices of the national government are authorized to loan or transfer,\nupon request of the President of the Institute, such apparatus, supplies, equipment, and buildings as may be\nneeded by the Institute and to detail employees for duty therein, when in the judgment of the bureau or office\nsuch apparatus, supplies, equipment, buildings, or service of such employees can be spared without serious\ndetriment to the public service. Employees so detailed shall perform such duty as is required under such detail,\nand the time so employed shall be counted as part of their regular official service."}},{"id":"PH-H15169-A20","no":20,"noLabel":{"en":"Section 20"},"text":{"en":"In order not to disrupt the smooth functioning of the present curricula of the Tiburcio Tancinco\nMemorial Vocational School, the faculty and other personnel of said school shall be absorbed by the Institute\nwith the incumbent Vocational School Superintendent as the first President of the Institute until after such\ntime when the President of the Philippines appoints the head of the Institute upon recommendation of the\nBoard of Trustees sitting en banc. The salary of the first President of the Institute shall be fixed by the Board\nin accordance with Section eleven of this Act. Salaries of the personnel of the Institute shall be determined in\naccordance with Presidential Decree No. 985 and other pertinent budget and compensation laws. Salary\nincreases of office personnel, where their performance warrants, may be effected by the Board, subject to\nPresidential Decree No. 985 and other pertinent budget and compensation laws."}},{"id":"PH-H15169-A21","no":21,"noLabel":{"en":"Section 21"},"text":{"en":"All assets of the Tiburcio Tancinco Memorial Vocational School, whether fixed or movable, its\n\npresent sites as donated by the City of Calbayog, the timberland under rental by the school from the Bureau of\nForest Development, and its records are transferred to the Institute."}},{"id":"PH-H15169-A22","no":22,"noLabel":{"en":"Section 22"},"text":{"en":"The Ministry of Education and Culture is directed to take such steps as are necessary for the\nconversion of Tiburcio Tancinco Memorial Vocational School, the operation of the Institute, and the\nimmediate implementation of this Act."}},{"id":"PH-H15169-A23","no":23,"noLabel":{"en":"Section 23"},"text":{"en":"All existing appropriations for the Tiburcio Tancinco Memorial Vocational School are hereby\ntransferred to the Tiburcio Tancinco Memorial Institute of Science and Technology, to be disbursed in\naccordance with the provisions of this Act. The necessary sum for the operation and maintenance of the state\ncollege shall be provided for in subsequent General Appropriations Acts."}},{"id":"PH-H15169-A24","no":24,"noLabel":{"en":"Section 24"},"text":{"en":"All provisions of law inconsistent with this Act are repealed or modified accordingly."}},{"id":"PH-H15169-A25","no":25,"noLabel":{"en":"Section 25"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15170"] = {"id":"PH-H15170","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 305  An Act Converting the Culaba Barangay High School in the Municipality of Culaba, Sub-Province of Biliran, Province of Leyte, Into a National Vocational School to Be Known as the Culaba National Vocational School.","orig":"Batas Pambansa Blg. 305  An Act Converting the Culaba Barangay High School in the Municipality of Culaba, Sub-Province of Biliran, Province of Leyte, Into a National Vocational School to Be Known as the Culaba National Vocational School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 305","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00305_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00305_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15170-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Culaba Barangay High School in the Municipality of Culaba, Sub-province of Biliran,\nProvince of Leyte, is hereby converted into a national vocational school to be known as the Culaba National\nVocational School."}},{"id":"PH-H15170-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Culaba National Vocational School, in addition to offering general secondary,\ntechnological, forestry, and other vocational courses, is authorized to expand its curricular offerings, eye on\ncollegiate level, as may be deemed necessary by the Minister of Education and Culture who, for this purpose\nis hereby empowered to reorganize said school accordingly."}},{"id":"PH-H15170-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Minister of Education and Culture shall immediately implement the provisions hereof so as\nto make the Culaba National Vocational School in operation by the first school term after effectivity of this"}},{"id":"PH-H15170-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be necessary for its\noperation and maintenance, shall be provided for in the annual General Appropriations Act."}},{"id":"PH-H15170-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15171"] = {"id":"PH-H15171","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 306  An Act Converting the Calubian High School in the Municipality of Calubian, Province of Leyte, Into a National Vocational School to Be Known as the Calubian National Vocational School.","orig":"Batas Pambansa Blg. 306  An Act Converting the Calubian High School in the Municipality of Calubian, Province of Leyte, Into a National Vocational School to Be Known as the Calubian National Vocational School.","vi":"Đạo luật chuyển đổi Trường Trung học Calubian tại Thị trấn Calubian, Tỉnh Leyte thành Trường Dạy nghề Quốc gia với tên gọi Trường Dạy nghề Calubian Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Calubian ในเทศบาล Calubian จังหวัด Leyte เป็น โรงเรียนอาชีวศึกษาแห่งชาติในชื่อโรงเรียนอาชีวศึกษา Calubian แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Calubian di Kotamadya Calubian, Provinsi Leyte menjadi Sekolah Kejuruan Nasional dengan nama Sekolah Kejuruan Calubian Nasional","ms":"Akta menukar status Sekolah Menengah Calubian di Perbandaran Calubian, Wilayah Leyte kepada Sekolah Vokasional Kebangsaan dengan nama Sekolah Vokasional Calubian Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 306","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00306_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00306_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15171-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Calubian High School in the Municipality of Calubian, Province of Leyte, is hereby\nconverted into a national vocational school to be known as The Calubian National Vocational School."}},{"id":"PH-H15171-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Calubian National Vocational School, in addition to offering general secondary,\ntechnological, forestry and other vocational courses, is authorized to expand its curricular offerings, even on\ncollegiate level, as may be deemed necessary by the Minister of Education and Culture who, for this purpose,\nis hereby empowered to reorganize said school accordingly."}},{"id":"PH-H15171-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Minister of Education and Culture shall immediately implement the provisions hereof, so as\nto make The Calubian National Vocational School in operation by the first term after effectivity of this Act."}},{"id":"PH-H15171-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sums as may be necessary for its\noperation and maintenance shall be provided for in the annual General Appropriations Act."}},{"id":"PH-H15171-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15172"] = {"id":"PH-H15172","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 307  An Act Converting Iloilo High School in the City of Iloilo Into a National High School, to Be Known as the Iloilo National High School.","orig":"Batas Pambansa Blg. 307  An Act Converting Iloilo High School in the City of Iloilo Into a National High School, to Be Known as the Iloilo National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Iloilo tại Thành phố Iloilo thành Trường Trung học Quốc gia với tên gọi Trường Trung học Iloilo Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Iloilo ในเมือง Iloilo เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Iloilo แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Iloilo di Kota Iloilo menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Iloilo Nasional","ms":"Akta menukar status Sekolah Menengah Iloilo di Bandar Iloilo kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Iloilo Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 307","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00307_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00307_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15172-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Iloilo High School in the City of Iloilo is converted into a national school, to be known as\nthe Iloilo National High School."}},{"id":"PH-H15172-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, the amounts needed for its operation\nshall be included in the annual General Appropriations Act."}},{"id":"PH-H15172-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15173"] = {"id":"PH-H15173","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 308  An Act Changing the Name of sto. Tomas Elementary School in the Municipality of Passi, Province of Iloilo, Into Fidelidad J. Santibaez Memorial Elementary School.","orig":"Batas Pambansa Blg. 308  An Act Changing the Name of sto. Tomas Elementary School in the Municipality of Passi, Province of Iloilo, Into Fidelidad J. Santibaez Memorial Elementary School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 308","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00308_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00308_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15173-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of Sto. Tomas Elementary School in the Municipality of Passi, Province of Iloilo, is\nhereby changed to Fidelidad J. Santibanez Memorial Elementary School."}},{"id":"PH-H15173-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15174"] = {"id":"PH-H15174","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 309  An Act Directing the National Historical Institute to Transfer to and Provide for the Interment of the Mortal Remains of General Leandro Locsin Fullon in the Monument to Be Erected in His Honor At the Public Plaza in the Municipality of Hamtic, in the Province of Antique, and Providing Funds therefor.","orig":"Batas Pambansa Blg. 309  An Act Directing the National Historical Institute to Transfer to and Provide for the Interment of the Mortal Remains of General Leandro Locsin Fullon in the Monument to Be Erected in His Honor At the Public Plaza in the Municipality of Hamtic, in the Province of Antique, and Providing Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 309","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00309_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00309_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15174-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The National Historical Institute is directed to transfer the mortal remains of General Leandro\nLocsin Fullon, hero of Panay, from the present burial site in La Paz Cemetery in the Municipality of Hamtic,\nProvince of Antique, and provide for the interment in the monument to be erected in his honor at the public\nplaza in the Municipality of Hamtic, Province of Antique. The monument and the public plaza of Hamtic,\nAntique, shall thereafter be known as the General Leandro Locsin Fullon National Shrine."}},{"id":"PH-H15174-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The funds necessary for the implementation of this Act shall be charged to the appropriations of\nthe National Historical Institute in the current General Appropriations Act. In case of deficiency, the\nappropriations herein provided may be augmented from the special activities fund intended for special\npriorities currently authorized in the same Act."}},{"id":"PH-H15174-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15175"] = {"id":"PH-H15175","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 310  An Act Converting the Muoz Provincial High School in the Municipality of Muoz, Province of Nueva Ecija, Into a National High School, to Be Known as the Muoz National High School and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 310  An Act Converting the Muoz Provincial High School in the Municipality of Muoz, Province of Nueva Ecija, Into a National High School, to Be Known as the Muoz National High School and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Muoz Tỉnh tại Thị trấn Muoz, Tỉnh Nueva Ecija thành Trường Trung học Quốc gia với tên gọi Trường Trung học Muoz Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Muoz จังหวัดในเทศบาล Muoz จังหวัด Nueva Ecija เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Muoz แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Muoz Provinsi di Kotamadya Muoz, Provinsi Nueva Ecija menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Muoz Nasional","ms":"Akta menukar status Sekolah Menengah Muoz Wilayah di Perbandaran Muoz, Wilayah Nueva Ecija kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Muoz Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 310","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00310_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00310_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15175-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Muñoz Provincial High School in the Municipality of Muñoz, Province of Nueva Ecija, is\nconverted into a national high school, to be known as the Muñoz National High School."}},{"id":"PH-H15175-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, the amount needed for its operation\nshall be included in the annual General Appropriations Act."}},{"id":"PH-H15175-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15176"] = {"id":"PH-H15176","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 311  An Act Converting the Mataragan Barangay High School in the Municipality of Malibcong, Province of Abra, Into a National Agricultural School, to Be Known as the Mataragan National Agricultural School.","orig":"Batas Pambansa Blg. 311  An Act Converting the Mataragan Barangay High School in the Municipality of Malibcong, Province of Abra, Into a National Agricultural School, to Be Known as the Mataragan National Agricultural School.","vi":"Đạo luật chuyển đổi Trường Trung học Mataragan Barangay tại Thị trấn Malibcong, Tỉnh Abra thành Trường Nông nghiệp Quốc gia với tên gọi Trường Nông nghiệp Mataragan Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Mataragan Barangay ในเทศบาล Malibcong จังหวัด Abra เป็น โรงเรียนเกษตรกรรมแห่งชาติในชื่อโรงเรียนเกษตรกรรม Mataragan แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Mataragan Barangay di Kotamadya Malibcong, Provinsi Abra menjadi Sekolah Pertanian Nasional dengan nama Sekolah Pertanian Mataragan Nasional","ms":"Akta menukar status Sekolah Menengah Mataragan Barangay di Perbandaran Malibcong, Wilayah Abra kepada Sekolah Pertanian Kebangsaan dengan nama Sekolah Pertanian Mataragan Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 311","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00311_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00311_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15176-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Mataragan Barangay High School in the municipality of Malibcong, Province of Abra, is\nhereby converted into a national agricultural school to be known as the Mataragan National Agricultural"}},{"id":"PH-H15176-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be necessary for its\noperation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15176-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15177"] = {"id":"PH-H15177","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 312  An Act Changing the Name of Buendia Avenue in the Municipality of Makati and Pasay City, Both in Metro Manila, to Senator Gil J. Puyat","orig":"Batas Pambansa Blg. 312  An Act Changing the Name of Buendia Avenue in the Municipality of Makati and Pasay City, Both in Metro Manila, to Senator Gil J. Puyat"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 312","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00312_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00312_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15177-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of Buendia Avenue in the Municipality of Makati and Pasay City, both in Metro\nManila, is changed to Senator Gil J. Puyat Avenue."}},{"id":"PH-H15177-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15178"] = {"id":"PH-H15178","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 313  An Act Converting the Gumaca Provincial High School in the Municipality of Gumaca, Province of Quezon, Into a National High School, to Be Known as the Gumaca National High School.","orig":"Batas Pambansa Blg. 313  An Act Converting the Gumaca Provincial High School in the Municipality of Gumaca, Province of Quezon, Into a National High School, to Be Known as the Gumaca National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Gumaca Tỉnh tại Thị trấn Gumaca, Tỉnh Quezon thành Trường Trung học Quốc gia với tên gọi Trường Trung học Gumaca Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Gumaca จังหวัดในเทศบาล Gumaca จังหวัด Quezon เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Gumaca แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Gumaca Provinsi di Kotamadya Gumaca, Provinsi Quezon menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Gumaca Nasional","ms":"Akta menukar status Sekolah Menengah Gumaca Wilayah di Perbandaran Gumaca, Wilayah Quezon kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Gumaca Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 313","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00313_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00313_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15178-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Gumaca Provincial High School in the Municipality of Gumaca, Province of Quezon, is\nconverted into a national high school, to be known as the Gumaca National High School."}},{"id":"PH-H15178-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, the amount needed for its operation\nshall be included in the annual General Appropriations Act."}},{"id":"PH-H15178-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15179"] = {"id":"PH-H15179","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 314  An Act Establishing a Municipal Hospital in the Municipality of Quinapundan, Province of Eastern Samar, to Be Known as the Quinapundan Municipal Hospital, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 314  An Act Establishing a Municipal Hospital in the Municipality of Quinapundan, Province of Eastern Samar, to Be Known as the Quinapundan Municipal Hospital, and Appropriating Funds therefor.","vi":"Đạo luật thành lập Bệnh viện Đô thị tại Thị trấn Quinapundan, Tỉnh Eastern Samar với tên gọi Bệnh viện Quinapundan Đô thị","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาลในเทศบาล Quinapundan จังหวัด Eastern Samar ในชื่อโรงพยาบาล Quinapundan เทศบาล","id":"Undang-Undang membentuk Rumah Sakit Kotamadya di Kotamadya Quinapundan, Provinsi Eastern Samar dengan nama Rumah Sakit Quinapundan Kotamadya","ms":"Akta menubuhkan Hospital Perbandaran di Perbandaran Quinapundan, Wilayah Eastern Samar dengan nama Hospital Quinapundan Perbandaran"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 314","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00314_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00314_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15179-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister (Ministry of\nHealth), a ten-bed municipal hospital in the Municipality of Quinapundan, Province of Eastern Samar, to be\nknown as the Quinapundan Municipal Hospital."}},{"id":"PH-H15179-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15179-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be made operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15180"] = {"id":"PH-H15180","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 315  An Act Changing the Name of Dao Emergency Hospital in the Municipality of Tobias Fornier, Province of Antique, to Governor Mamerto Portillo Memorial District Hospital.","orig":"Batas Pambansa Blg. 315  An Act Changing the Name of Dao Emergency Hospital in the Municipality of Tobias Fornier, Province of Antique, to Governor Mamerto Portillo Memorial District Hospital."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 315","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00315_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00315_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15180-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Dao Emergency Hospital in the Municipality of Tobias Fornier, Province of\nAntique, is changed to Governor Mamerto Portillo Memorial District Hospital."}},{"id":"PH-H15180-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15181"] = {"id":"PH-H15181","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 316  An Act Establishing a Municipal Hospital in the Municipality of Inabanga, Province of Bohol, to Be Known as the Dagohoy Municipal Hospital.","orig":"Batas Pambansa Blg. 316  An Act Establishing a Municipal Hospital in the Municipality of Inabanga, Province of Bohol, to Be Known as the Dagohoy Municipal Hospital.","vi":"Đạo luật thành lập Bệnh viện Đô thị tại Thị trấn Inabanga, Tỉnh Bohol với tên gọi Bệnh viện Dagohoy Đô thị","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาลในเทศบาล Inabanga จังหวัด Bohol ในชื่อโรงพยาบาล Dagohoy เทศบาล","id":"Undang-Undang membentuk Rumah Sakit Kotamadya di Kotamadya Inabanga, Provinsi Bohol dengan nama Rumah Sakit Dagohoy Kotamadya","ms":"Akta menubuhkan Hospital Perbandaran di Perbandaran Inabanga, Wilayah Bohol dengan nama Hospital Dagohoy Perbandaran"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 316","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00316_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00316_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15181-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the direct supervision of the Office of the Minister (Ministry of\nHealth), a municipal hospital in the Municipality of Inabanga, Province of Bohol, to be known as the Dagohoy\nMunicipal Hospital."}},{"id":"PH-H15181-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15181-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter such sums as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be made operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15182"] = {"id":"PH-H15182","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 317  An Act Changing the Name of the Bohol Regional General Hospital in the City of Tagbilaran to Governor Celestino Gallares Memorial Hospital.","orig":"Batas Pambansa Blg. 317  An Act Changing the Name of the Bohol Regional General Hospital in the City of Tagbilaran to Governor Celestino Gallares Memorial Hospital."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 317","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00317_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00317_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15182-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Bohol Regional General Hospital in the City of Tagbilaran is changed to\nGovernor Celestino Gallares Memorial Hospital."}},{"id":"PH-H15182-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15183"] = {"id":"PH-H15183","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 318  An Act Changing the Name of the Celestino Gallares Hospital in the Municipality of Carmen, Province of Bohol, to Congressman Simeon G. Toribio Memorial Hospital.","orig":"Batas Pambansa Blg. 318  An Act Changing the Name of the Celestino Gallares Hospital in the Municipality of Carmen, Province of Bohol, to Congressman Simeon G. Toribio Memorial Hospital."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 318","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00318_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00318_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15183-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Celestino Gallares Hospital in the Municipality of Carmen, Province of Bohol,\nis changed to Congressman Simeon G. Toribio Memorial Hospital."}},{"id":"PH-H15183-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15184"] = {"id":"PH-H15184","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 319  An Act Changing the Name of the Davao Regional Medical and Training Center in the City of Davao to Davao Medical Center.","orig":"Batas Pambansa Blg. 319  An Act Changing the Name of the Davao Regional Medical and Training Center in the City of Davao to Davao Medical Center."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 319","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00319_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00319_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15184-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Davao Regional Medical and Training Center in the City of Davao is changed\nto Davao Medical Center."}},{"id":"PH-H15184-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15185"] = {"id":"PH-H15185","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 320  An Act Converting Certain Provincial Roads in the Province of Antique Into National Roads.","orig":"Batas Pambansa Blg. 320  An Act Converting Certain Provincial Roads in the Province of Antique Into National Roads."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 320","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00320_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00320_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15185-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The following provincial roads in the Province of Antique are converted into and declared as\nnational roads:\n(a) Anini-y-Tobias Fornier Hamtic Road\n(b) Bugasong Walderama Road\n(c) Bagumbayan-Pandan-Libertad to Aklan-Antique Boundary\n(d) Sibalom Egrana-Bia-an Hamtic Road."}},{"id":"PH-H15185-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Any provision of law, decree, order, rule or regulation inconsistent with this Act is repealed or\nmodified accordingly."}},{"id":"PH-H15185-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 14, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15186"] = {"id":"PH-H15186","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 321  An Act Converting the Wenceslao Trinidad Memorial High School in the Municipality of Laurel, Province of Batangas, Into a National High School, to Be Known as Wenceslao Trinidad Memorial National High School.","orig":"Batas Pambansa Blg. 321  An Act Converting the Wenceslao Trinidad Memorial High School in the Municipality of Laurel, Province of Batangas, Into a National High School, to Be Known as Wenceslao Trinidad Memorial National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Tưởng niệm Wenceslao Trinidad tại Thị trấn Laurel, Tỉnh Batangas thành Trường Trung học Quốc gia với tên gọi Trường Trung học Tưởng niệm Wenceslao Trinidad Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษาอนุสรณ์ Wenceslao Trinidad ในเทศบาล Laurel จังหวัด Batangas เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษาอนุสรณ์ Wenceslao Trinidad แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Memorial Wenceslao Trinidad di Kotamadya Laurel, Provinsi Batangas menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Memorial Wenceslao Trinidad Nasional","ms":"Akta menukar status Sekolah Menengah Memorial Wenceslao Trinidad di Perbandaran Laurel, Wilayah Batangas kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Memorial Wenceslao Trinidad Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 321","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00321_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00321_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15186-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Wenceslao Trinidad Memorial High School in the Municipality of Laurel, Province of\nBatangas, is hereby converted into a national high school to be known as the Wenceslao Trinidad Memorial\nNational High School, which shall be under the supervision of the Bureau of Secondary Education."}},{"id":"PH-H15186-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 for the Ministry of Education and Culture intended\nfor new national schools: Provided, That the local government unit concerned shall continue to provide its\nshare in the cost of operating and maintaining said school. Thereafter, such sum as may be needed for its\noperation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15186-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 18, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15187"] = {"id":"PH-H15187","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 322  An Act Creating Barangay Salman in the Municipality of Ampatuan, Province of Maguindanao.","orig":"Batas Pambansa Blg. 322  An Act Creating Barangay Salman in the Municipality of Ampatuan, Province of Maguindanao."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 322","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00322_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00322_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15187-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Sitios Salman, Masalay, Bual, Talpok, and Kabulnan are separated from Barangay Decalongan\nin the Municipality of Ampatuan, Province of Maguindanao, and constituted into a new barangay to be known\nas Barangay Salman."}},{"id":"PH-H15187-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The new barangay shall be bounded and described as follows:\n\"Bounded on the north by the municipalities of Dinaig and Maganoy on the east, by Lots 383, 384, 385, 386,\n387, 388, 389 and 390 all Pls-544-D; on the south by Kauran Creek, barangays Saniac and Tubak; on the west\nby the municipalities of Lebak and South Upi.\n\"Beginning at southwestern foot of Decalongan Bridge, going towards the northwestern corner of Lot 382,\nintersecting the Kabulnan River; thence going on a southwestern direction to the northeastern corner Lot 315,\nPls-544-D; thence going southwest direction to the northwestern corner of Lot 316, Pls-544-D; thence an\nimaginary line following the course of the Kauran Creek; thence S 61 deg. 00’W, 13,500 meters until it\nintersects the Kabulnan River; thence running due west, 8,400 meters; thence going towards due north, 11,200\nmeters until it reaches the boundary of the municipalities of Leback and South Upi; thence running due east,\nuntil it intersects the southwestern foot of Decalongan Bridge, point of beginning.\n\"Containing an area of twenty thousand three hundred nineteen (20,319) hectares more or less.\""}}],"pack":"ph-p156"};
  FT["PH-H15188"] = {"id":"PH-H15188","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":25,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 323  An Act Converting the Samar School of Arts and Trades in the Municipality of Catbalogan, Province of Samar, Into a state Polytechnic College to Be Known as the Samar state Polytechnic College and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 323  An Act Converting the Samar School of Arts and Trades in the Municipality of Catbalogan, Province of Samar, Into a state Polytechnic College to Be Known as the Samar state Polytechnic College and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Nghệ thuật và Thương mại Samar tại Thị trấn Catbalogan, Tỉnh Samar thành Cao đẳng Bách khoa Bang với tên gọi Cao đẳng Bách khoa Samar Bang","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนศิลปะและหัตถกรรม Samar ในเทศบาล Catbalogan จังหวัด Samar เป็น วิทยาลัยโพลีเทคนิคของรัฐในชื่อวิทยาลัยโพลีเทคนิค Samar ของรัฐ","id":"Undang-Undang mengubah Sekolah Seni dan Keterampilan Samar di Kotamadya Catbalogan, Provinsi Samar menjadi Sekolah Tinggi Politeknik Negeri dengan nama Sekolah Tinggi Politeknik Samar Negeri","ms":"Akta menukar status Sekolah Seni dan Pertukangan Samar di Perbandaran Catbalogan, Wilayah Samar kepada Kolej Politeknik Negeri dengan nama Kolej Politeknik Samar Negeri"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 323","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-18","completenessNote":"全文，共 25 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00323_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00323_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15188-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Samar School of Arts and Trades in the Municipality of Catbalogan, Province of Samar, is\nconverted into the Samar State Polytechnic College, hereinafter referred to as the State College."}},{"id":"PH-H15188-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The State College shall primarily provide higher vocational, professional and technological\ninstruction, and training in the fields of industry, agriculture, fishery, engineering and sciences, as well as\nshort term vocational-technical-continuing courses. It shall also promote research, advanced industrial\ntechnology including industrial education, arts service trades, agriculture including agricultural education,\nhome technology, fishery, forestry, engineering and sciences."}},{"id":"PH-H15188-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"In addition to the present secondary, post-secondary and graduate courses, the State College\nshall offer undergraduate and graduate courses in the fields of agricultural and industrial education, sciences,\nand engineering, such as: Bachelor of Science in Industrial Engineering, Agricultural Engineering, Mining\nEngineering, Marine Engineering, Industrial Management, Agricultural Economics, Agricultural Extension,\nHome Technology, Agricultural Technology, Fishery Technology, Forestry, Diploma in Veterinary\nTechnology, and Engineering Technology; post graduate courses leading to the degrees of Master of Science\nin Agriculture, Agricultural Education, Industrial Technology, and other degree courses and special vocational\ncourses as the Board of Trustees may deem necessary."}},{"id":"PH-H15188-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"No student shall be denied admission to the State College by reason of sex, ethnic consideration\nor religious beliefs or affiliation."}},{"id":"PH-H15188-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The head of the State College shall be known as the President of the Samar State Polytechnic\nCollege. His salary shall be fixed by the Board of Trustees which shall be comparable to that being received\nby the president of similar institutions of like standing, subject to Presidential Decree No. 985 and other\npertinent budget and compensation laws. He shall be appointed by the President of the Philippines upon the\nrecommendation of the Board of Trustees.\nThe powers and duties of the President of the Samar Polytechnic State College, in addition to those\nspecifically provided for in this Act, shall be those usually pertaining to the office of the president of a state"}},{"id":"PH-H15188-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The incumbent Vocational School Superintendent of the Samar School of Arts and Trades in\nSamar shall be the first President of the State College. The other officials of the State College shall be\nappointed by the Board of Trustees: Provided, That graduate studies and academic affairs shall be headed\npreferably by a bona fide resident of Samar with appropriate and adequate educational qualifications, training\nand experience, preferably a Doctor of Philosophy in Education."}},{"id":"PH-H15188-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"The governing body of the State College shall be the Board of Trustees of the Samar Polytechnic\nState College. It shall be composed of the Minister of Education and Culture as chairman, the President of the\nState College as the vice chairman, with the following as members: the Director, Ministry of Education and\nCulture, Region VIII, the Director, National Economic and Development Authority, the president of the\nalumni association, the Governor of the Province of Samar, and one bona fide resident of Samar with\n\nmanagement and technical expertise."}},{"id":"PH-H15188-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"A quorum of the Board of Trustees consists of a majority of all members holding office at the\ntime a meeting be called. All processes against the Board of Trustees shall be served on the President thereof."}},{"id":"PH-H15188-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"The members of the Board of Trustees shall be entitled to an allowance of two hundred pesos per\nmeeting actually attended: Provided, That they shall be reimbursed for actual and necessary travel expenses\nincurred in attending meetings of the Board, subject to existing budget laws on honoraria and allowances."}},{"id":"PH-H15188-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"The Board of Trustees shall have the following powers and duties in addition to its general\npowers of administration and the exercise of all powers of a corporation as provided in Section thirty-six of\nBatas Pambansa Blg. 68, otherwise known as the Corporation Code of the Philippines.\n(a) To receive and appropriate for the purpose specified by law such sum as may be provided for the support\nof the State College;\n(b) To confer a degree upon successful candidate for graduation of the State College. It may also confer\nhonorary degrees upon persons in recognition of learning, statesmanship or eminence in any of the fields of\nspecialization of the State College, or in recognition of public service: Provided, That such degrees shall not\nbe conferred in consideration of or reciprocation of some personal favor;\n(c) To authorize the President of the State College to award proficiency certificate or diplomas to students\nwho have completed non-degree courses;\n(d) Subject to civil service law, rules and regulations, to appoint upon recommendation of the President of the\nState College, vice president, deans, directors, secretary of the State College, registrar, heads of departments,\nprofessors, instructors, lecturers and other officials and employees of the State College, to fix their\ncompensation subject to Presidential Decree No. 985 and other pertinent budget and compensation laws; to\nprescribe hours of service, duties and conditions of work as it may deem proper; to grant to them in its\ndiscretion, leave of absence under such regulations as it may promulgate, any provision of law to the contrary\nnotwithstanding; and to remove them for cause after an investigation and hearing pursuant to civil service law\nand other governing rules, to provide chairs in the State College, and to provide for the maintenance or\nendowment of such chairs as may be necessary;\n(e) To approve the curricula and rules of discipline drawn up by the college council as hereinafter provided;\n(f) To provide fellowships for qualified faculty members and scholarships to deserving students;\n(g) To prescribe rules for its own government and to enact for the State College such rules and regulations, not\ncontrary to law, as may be necessary to carry out the purpose and function of the State College;\n(h) To receive in trust legacies, gifts, and donations of real and personal property of all kinds and to administer\nthe same for the benefit of the State College, or the department thereof, in such manner as the Board of\nTrustees may in its discretion determine. All such donations shall be exempt from all taxes and be considered\nas deductible items from the income tax of the donors;\n(i) To authorize the President of the State College to enter into contract and/or to negotiate for the\nconstruction, repair and acquisition of buildings, machineries, and equipment, and other physical facilities,\nand to contract loans for the improvements thereon."}},{"id":"PH-H15188-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"On or before the fifteenth day of the second month after the opening of regular classes each\nyear, the Board of Trustees shall file with the Office of the President of the Philippines a detailed report,\nsetting forth the programs, conditions, and needs of the State College."}},{"id":"PH-H15188-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"There shall be a college council consisting of the President of the State College, vice president,\ndeans, directors, and all members of the faculty with the rank of professor. The council shall have the power\nto prescribe the curricula and rules of discipline, subject to the approval of the Board of Trustees. It shall fix\nthe requirements for admission to the State College, as well as for graduation and the conferring of degrees\n\nsubject to review by the Board of Trustees. The council alone shall have the power to recommend students or\nothers to be recipients of degrees. Through the President of the State College or its duly authorized committee,\nthe council shall have disciplinary power over the students within the limits prescribed by the rules of\ndiscipline."}},{"id":"PH-H15188-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"The body of instructors and professors of the State College shall constitute the faculty of the\nState College."}},{"id":"PH-H15188-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"No member of the faculty of the State College shall attempt directly or indirectly, under penalty\nof dismissal by the Board of Trustees, to influence students or any person in the State College towards any\nideology, political or otherwise, which agitates the overthrow of the duty constituted government."}},{"id":"PH-H15188-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"There shall be a Secretary of the State College who shall be appointed by the Board of Trustees\nupon recommendation of the President of the State College. He shall also be the Secretary of the Board and\nshall keep such records of the State College as may be determined by the Board of Trustees."}},{"id":"PH-H15188-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"The Treasurer of the Philippines shall be ex officio treasurer of the State College and all\naccounts and expenses thereof shall be audited by the Commission on Audit or its duly authorized\nrepresentatives, and all disbursements shall be made in accordance with existing auditing rules and\nregulations."}},{"id":"PH-H15188-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"Heads of bureaus and offices of the national government are hereby authorized to loan or\ntransfer, upon request of the President of the State College, such apparatus, equipment or supplies or the\nservice of such employees can be spared without serious detriment to the public service. Employees so\ndetailed shall perform such duty as if required under such detail, and the time so employed shall be counted as\npart of their regular official service."}},{"id":"PH-H15188-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"The requirements provided in this Act as may prove adverse to the present faculty and\nemployees of the Samar School of Arts and Trades who may be absorbed by the Samar State Polytechnic\nCollege shall not apply to them. But future appointees to the said State College shall be subject to all the\nrequirements provided in this Act."}},{"id":"PH-H15188-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"All assets, obligations, and appropriations of the Samar School of Arts and Trades in Samar,\nwhether fixed or movable, records and personnel are hereby transferred and/or absorbed by the Samar State\nPolytechnic College."}},{"id":"PH-H15188-A20","no":20,"noLabel":{"en":"Section 20"},"text":{"en":"All existing appropriations for the Samar School of Arts and Trades are hereby transferred to\nthe Samar State Polytechnic College, to be disbursed in accordance with the provisions of this Act. The\nnecessary sum for the operation and maintenance of the State College shall provided for in subsequent\nGeneral Appropriations Acts."}},{"id":"PH-H15188-A21","no":21,"noLabel":{"en":"Section 21"},"text":{"en":"The Board of Trustees in fulfillment of the objectives of the Samar State Polytechnic College is\nempowered to establish satellite schools and/or extension schools and to integrate and make a part of the State\nCollege other national and vocational schools of the Province of Samar and nearby provinces: Provided, That\nthese schools will continue to offer their present curricular offerings that the Board of Trustees may in its\ndiscretion authorized."}},{"id":"PH-H15188-A22","no":22,"noLabel":{"en":"Section 22"},"text":{"en":"The Bureau of Lands, the Bureau of Fisheries, and Aquatic Resources, and the Bureau of Forest\nDevelopment are hereby directed to coordinate with the Samar Polytechnic State College for the endowment\nand/or expropriation of at least three hundred hectares out of the alienable and disposable areas of the\nProvince of Samar, Municipality of Catbalogan for the forestry and fishery programs of the State College."}},{"id":"PH-H15188-A23","no":23,"noLabel":{"en":"Section 23"},"text":{"en":"The Minister of Education and Culture is hereby directed to take such steps as are necessary for\nthe immediate implementation of this Act."}},{"id":"PH-H15188-A24","no":24,"noLabel":{"en":"Section 24"},"text":{"en":"All laws, executive orders contrary to or inconsistent with the provisions of this Act are hereby\nrepealed or amended accordingly."}},{"id":"PH-H15188-A25","no":25,"noLabel":{"en":"Section 25"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 18, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15189"] = {"id":"PH-H15189","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 324  An Act Creating the Municipality of Pandami in the Province of","orig":"Batas Pambansa Blg. 324  An Act Creating the Municipality of Pandami in the Province of"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 324","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-11-20","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00324_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00324_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15189-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Barangays Hambilan, Baligtang, Bud Sibaud, Kabbon, Lahi, Lapak, Mamanuk, Malanta, North\nManubul, Parian Dakulah, Sibaud, Sibaud Laud, Sigang-gang, South Manubul, Suba-Suba, Tingah Manubul,\nTapaan Island, Maninculat Island, Bubuan Island, Manibul Island, and Sirum Island, are separated from the\nMunicipality of Siasi, Province of Sulu, and constituted into an independent and distinct municipality of the\nprovince which shall be known as the Municipality of Pandami with the seat of government in the present site\nof Barangay Lapak."}},{"id":"PH-H15189-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Municipality of Pandami shall be bounded as follows:\nA parcel of land, situated in the original Municipality of Siasi, Island of Siasi, Province of Sulu, beginning\nfrom point 1 (Latitude 5 deg. 43’ 16\" Longitude 120 deg. 18’53\"), being\nDue south 21,600.00 m. to point 2; thence, S. 60\ndegree 30’ W., 23,600.00 m. to point 3 thence, N. 45\ndeg. 00’ W., 16,000.00 m. to point 4; thence, N. 0\ndeg. 39’ W., 11,833.80 m. to point 5; thence, S. 20\ndeg. 10’ E., 11,600.00 m. to point 6; thence, S. 88\ndeg. 20’ E., 28,000.00 m. to point of beginning\ncontaining an area of 8,699 has., more or less; bearings, true."}},{"id":"PH-H15189-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted by the\nCommission on Elections in the areas affected in the present Municipality of Siasi within the period of ninety\n(90) days after the approval of this Act, the President shall appoint the mayor and other officials to hold\nelective positions in the new Municipality of Pandami.\nThe expenditures for holding the plebiscite shall be chargeable to local funds."}},{"id":"PH-H15189-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 20, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15190"] = {"id":"PH-H15190","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 325  An Act Authorizing Heads of Ministries, Offices, Agencies and Commissions of the National Government, Including the Supreme Court and Constitutional Bodies, to Revise the Rates of Fees and Charges.","orig":"Batas Pambansa Blg. 325  An Act Authorizing Heads of Ministries, Offices, Agencies and Commissions of the National Government, Including the Supreme Court and Constitutional Bodies, to Revise the Rates of Fees and Charges."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 325","issuingBody":"Batasang Pambansa","promulgatedDate":"1982-12-27","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00325_1982_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00325_1982_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15190-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Coverage. (a) Any provision of existing laws to the contrary notwithstanding, heads of all\nministries, offices and agencies, and the commissions of the national government, the Supreme Court and\nconstitutional bodies, are hereby authorized to revise their fees and charges as hereinafter provided.\n(b) The fees and charges enforced and collected by government-owned and controlled corporations, local\ngovernments, those fees covered by international agreements to which the Philippines is a signatory, those\nimposed by state colleges and universities, government hospitals, medical centers and clinics shall continue to\nbe determined under existing laws, subject to the guidelines set forth in Section 2 hereof."}},{"id":"PH-H15190-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Determination of rates. The fees and charges shall be revised at just and reasonable rates\nsufficient to cover administrative costs and, wherever practicable, be uniform for similar or comparable\nservices and functions. The revision of rates shall be determined by the respective ministry heads or\nequivalent functionaries conformably with the rules and regulations of the Ministry of Finance issued pursuant\nto Section 4 hereof, upon recommendation of the imposing and collecting authorities concerned, subject to the\napproval of the Cabinet. Fees and charges imposed and collected by the courts and constitutional bodies shall\nbe determined respectively by the Supreme Court and the constitutional body concerned."}},{"id":"PH-H15190-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Accrual of proceeds. Unless otherwise provided by law, all collections from fees and charges\nshall accrue to the General Fund of the national government."}},{"id":"PH-H15190-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Rules and regulations. The Ministry of Finance shall issue the necessary rules and regulations to\neffectively implement the provisions of this Act, which shall be published once a week for two consecutive\nweeks in two newspapers of general circulation in the Philippines in lieu of publication in the Official Gazette\nand take effect fifteen days after the last publication."}},{"id":"PH-H15190-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Publication requirement. Upon review and approval by the Cabinet of the adjusted rates of fees\nor charges, the heads of ministries, offices, agencies or commissions concerned, including the courts and\nconstitutional bodies, shall each cause the revised schedule of fees and charges to be published once a week\nfor two consecutive weeks in two newspapers of general circulation in the Philippines in lieu of publication in\nthe Official Gazette and the same shall be effective fifteen days after the last publication."}},{"id":"PH-H15190-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Repealing clause. All laws, decrees, executive orders, rules and regulations and other issuances\nor parts thereof which are inconsistent with this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H15190-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Effectivity. This Act shall take effect on the first day of January, 1983.\nApproved: December 27, 1982"}}],"pack":"ph-p156"};
  FT["PH-H15191"] = {"id":"PH-H15191","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 326  An Act Changing the Name of Nagsangalan Elementary School in Barangay Talogtog, Municipality of Dolores, Province of Abra, to Don Rosalio Eduarte Elementary School.","orig":"Batas Pambansa Blg. 326  An Act Changing the Name of Nagsangalan Elementary School in Barangay Talogtog, Municipality of Dolores, Province of Abra, to Don Rosalio Eduarte Elementary School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 326","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-01-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00326_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00326_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15191-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of Nagsangalan Elementary School in Barangay Talogtog, Municipality of Dolores,\nProvince of Abra, is changed to Don Rosalio Eduarte Elementary School."}},{"id":"PH-H15191-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: January 19, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15192"] = {"id":"PH-H15192","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 327  An Act Transferring Barangays Bokiawan, Nanggulunan, Hapao and Loboong in the Municipality of Tinoc, Province of Ifugao, to the Municipality of Hungduan, Same Province.","orig":"Batas Pambansa Blg. 327  An Act Transferring Barangays Bokiawan, Nanggulunan, Hapao and Loboong in the Municipality of Tinoc, Province of Ifugao, to the Municipality of Hungduan, Same Province."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 327","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-01-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00327_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00327_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15192-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The barangays of Bokiawan, Nanggulunan, Hapao and Loboong all in the Municipality of Tinoc,\nProvince of Ifugao, are hereby transferred to the Municipality of Hungduan, same province."}},{"id":"PH-H15192-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Commission on Elections shall conduct and supervise the holding of the plebiscite in the\nareas affected within ninety days from the approval of this Act, the expenses of which shall be charged to\nlocal funds."}},{"id":"PH-H15192-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"All acts or parts thereof inconsistent with the provisions of this Act are hereby repealed or\nmodified accordingly."}},{"id":"PH-H15192-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: January 19, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15193"] = {"id":"PH-H15193","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 328  An Act Changing the Name of the Pangasinan College of Fisheries in the Municipality of Binmaley, Province of Pangasinan, to Binmaley School of","orig":"Batas Pambansa Blg. 328  An Act Changing the Name of the Pangasinan College of Fisheries in the Municipality of Binmaley, Province of Pangasinan, to Binmaley School of"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 328","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-01-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00328_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00328_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15193-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Pangasinan College of Fisheries, located in the Municipality of Binmaley,\nProvince of Pangasinan, is changed to Binmaley School of Fisheries."}},{"id":"PH-H15193-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: January 19, 1983"}}],"pack":"ph-p156"};
