  FT["PH-H15196"] = {"id":"PH-H15196","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 331  An Act Changing the Name of the Laud Sitangkai Elementary School in the Municipality of Sitangkai, Province of Tawi-Tawi, to Panglima Alare Elementary School.","orig":"Batas Pambansa Blg. 331  An Act Changing the Name of the Laud Sitangkai Elementary School in the Municipality of Sitangkai, Province of Tawi-Tawi, to Panglima Alare Elementary School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 331","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-01-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00331_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00331_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15196-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Laud Sitangkai Elementary School in the Municipality of Sitangkai, Province of\nTawi-Tawi, is changed to Panglima Alare Elementary School."}},{"id":"PH-H15196-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: January 19, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15197"] = {"id":"PH-H15197","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 332  An Act Changing the Name of the City of Roxas High School in the City of Roxas to Congressman Ramon A. Arnaldo High School.","orig":"Batas Pambansa Blg. 332  An Act Changing the Name of the City of Roxas High School in the City of Roxas to Congressman Ramon A. Arnaldo High School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 332","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-01-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00332_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00332_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15197-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the City of Roxas High School in the City of Roxas is changed to Congressman\nRamon A. Arnaldo High School."}},{"id":"PH-H15197-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: January 19, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15198"] = {"id":"PH-H15198","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 333  An Act Changing the Name of the Negros Occidental General Comprehensive High School in Bacolod City to Negros Occidental High School.","orig":"Batas Pambansa Blg. 333  An Act Changing the Name of the Negros Occidental General Comprehensive High School in Bacolod City to Negros Occidental High School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 333","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-01-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00333_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00333_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15198-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Negros Occidental General Comprehensive High School in Bacolod City is\nchanged to Negros Occidental High School."}},{"id":"PH-H15198-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: January 19, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15199"] = {"id":"PH-H15199","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 334  An Act Changing the Name of the Atok National High School in the Municipality of Atok, Province of Benguet, to Jose Mencio National High School.","orig":"Batas Pambansa Blg. 334  An Act Changing the Name of the Atok National High School in the Municipality of Atok, Province of Benguet, to Jose Mencio National High School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 334","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-01-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00334_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00334_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15199-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Atok National High School in the Municipality of Atok, Province of Benguet, is\nchanged to Jose Mencio National High School."}},{"id":"PH-H15199-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: January 19, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15200"] = {"id":"PH-H15200","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 335  An Act Creating the Municipality of Semirara in the Province of","orig":"Batas Pambansa Blg. 335  An Act Creating the Municipality of Semirara in the Province of"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 335","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-02-09","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00335_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00335_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15200-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be created the Municipality of Semirara in the Province of Antique out of all\nbarangays and sitios in the Islands of Semirara, Nagubat and Libagao, Province of Antique, and the\nsurrounding areas as described in Section 3 hereof, which are hereby detached and separated from the present\nMunicipality of Caluya, Province of Antique, and to form and constitute a distinct and independent\nmunicipality: Provided, That this Act shall not affect the legal existence of the Municipality of Caluya as such."}},{"id":"PH-H15200-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The seat of the municipal government of the newly created municipality shall be in Barangay\nSemirara, Island of Semirara."}},{"id":"PH-H15200-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The technical description of the territorial jurisdiction of the Municipality of Semirara shall be as\n\"The municipality shall include the areas bounded by the following coordinates: On the southwest corner 1\nwith latitude 11° 57’ 00\" and longitude 121° 18’ 00\", thence north to corner 2 with latitude 12° 09’ 11\" and\nlongitude 121° 18’ 00\", thence northeast to corner 3 with latitude 12° 14’ 00\", and longitude 121° 25’ 00\",\nthen east to corner 4 with latitude 12° 14’ 00\" and longitude 121° 27’ 00\", thence south to corner 5 with\nlatitude 11° 57’ 00\", and longitude 121° 27’ 00\", thence west to corner 1, covering the islands of Semirara,\nNagubat, and Libagao as per Philippine Coast and Geodetic Chart No. 2518, Edition 2, March 1974.\""}}],"pack":"ph-p156"};
  FT["PH-H15201"] = {"id":"PH-H15201","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 336  An Act Creating the Municipality of Salvador Benedicto in the Province of Negros Occidental.","orig":"Batas Pambansa Blg. 336  An Act Creating the Municipality of Salvador Benedicto in the Province of Negros Occidental."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 336","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-02-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00336_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00336_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15201-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Barangay Pandanon and Barangay Igmayaan in the Municipality of Murcia and portions of\nBarangay Lalong and Barangay Marcelo in the Municipality of Calatrava, all in the Province of Negros\nOccidental, and Barangay Bunga and Barangay Kumaliskis and a portion of Barangay Prosperidad, all in the\nCity of San Carlos, are separated from their respective municipalities and city and constituted into a distinct\nand independent municipality in the Province of Negros Occidental to be known as the Municipality of\nSalvador Benedicto."}},{"id":"PH-H15201-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The boundaries of the new municipality shall be as follows:\n\"Beginning from corner No. 1, being a point at the junction of Bago River and Pandanon River; thence\nfollowing Pandanon River upstream in a northeasterly direction about 4,550 meters to corner No. 2, being a\npoint at the junction of Pandanon River and a creek; thence N 68° 30’ E about 1,505 meters to corner No. 3,\nbeing a point at peak of Mt. Mandalagan; thence S 87 40’ E about 3,020 meters to corner No. 4, being a point\non top of a ridge; thence S 60° 25’ E about 1,800 meters to corner No. 5, being a point on side of the former\nILCO logging road; thence S 3° 30’ W about 1,445 meters to corner No. 6, being a point on top of a mountain\nridge; thence S 53° 00’ W about 2,930 meters, being a point at the junction of Bago River and Pinawayan\nCreek; thence following Bago River downstream in a south and north-westerly direction about 7,180 meters to\ncorner No. 1, a point in the beginning, whose tie line is identical to corner No. 1, a point at the junction of\nBago River and Pandanon River, containing an area of seventeen thousand fifty-six (17,056.0) hectares, more"}}],"pack":"ph-p156"};
  FT["PH-H15202"] = {"id":"PH-H15202","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":234,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 337  An Act Enacting a Local Government Code","orig":"Batas Pambansa Blg. 337  An Act Enacting a Local Government Code"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 337","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-02-10","completenessNote":"全文，共 234 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00337_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00337_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15202-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Title of Act. - This Act shall be known and referred to as the \"Local Government Code.\""}},{"id":"PH-H15202-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Declaration of Policy. - The State shall guarantee and promote the authority of local government\nunits to ensure their fullest development as self-reliant communities and make them more effective partners in\nthe pursuit of national development and social progress. To this end, the State shall constantly find and\neffectuate ways of enhancing their capabilities in discharging these responsibilities through a responsive and\naccountable local government structure instituted through a system of decentralization whereby local\ngovernments shall be given more powers, responsibilities and resources."}},{"id":"PH-H15202-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Scope of Application of Code. - This Code shall apply to all local governments and, to the extent\nherein provided, to officials, offices or agencies of the national government."}},{"id":"PH-H15202-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Rules of Interpretation. -\n(1) Any power of a barangay, municipality, city or province shall be liberally construed in its favor. Any fair\nand reasonable doubt as to the existence of the power shall be interpreted in favor of the local government unit\n(2) The general welfare provisions in this Code shall be liberally interpreted so as to give more power to local\ngovernments in promoting the economic uplift, social welfare and material progress of the people in the\n(3) Vested rights existing on the date of the effectivity of this Code arising out of contracts or any other source\nof obligation between a province, city, municipality or barangay and another party, shall be governed by the\noriginal terms and provisions of said contract or the law in force at the time such rights became vested and in\nno case shall this Code infringe on them.\n(4) When in the resolution of controversies arising under this Code no legal provision or jurisprudence can be\nfound to apply, resort may be had to the customs and traditions in the place where the controversy arose.\nGENERAL POWERS AND ATTRIBUTES OF LOCAL GOVERNMENT UNITS"}},{"id":"PH-H15202-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Creation and conversion; Political and Corporate Nature. -\n(1) As a general rule, the creation of a local government unit or its conversion from one level into another\nlevel of local government shall be based on factors relative to viability and projected capacity to provide\nservices which can be clearly shown by verifiable indicators.\n(2) Every local government unit created or recognized under this Code is a body politic and corporate\nendowed with powers to be exercised by and through its government in conformity with law. As such, it shall\n\nexercise powers as a subdivision of the government and as a corporate entity representing the inhabitants of its"}},{"id":"PH-H15202-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Beginning of Corporate Existence. - When a new local government unit is created, its corporate\nexistence shall commence upon the qualification of its chief executive and a majority of the members of its\nlegislative body or sanggunian unless some time is fixed therefor by law."}},{"id":"PH-H15202-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Government Powers in General. - Every local government unit shall exercise the powers\nexpressly granted, those necessarily implied therefrom, as well as powers necessary and proper for\ngovernance such as to promote health and safety, enhance prosperity, improve morals, and maintain peace and\norder in the local government unit, and preserve the comfort and convenience of the inhabitants therein."}},{"id":"PH-H15202-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Authority to Create Sources of Revenue. -\n(1) Each local government unit shall have the power to create its own sources of revenue and to levy taxes,\nsubject to such limitations as may be provided by law.\n(2) For purposes of taxation by local government units, the appraisal and assessment of real property, as well\nas the levy, collection and administration of real property taxes, shall be governed by the provisions of\nexisting laws insofar as they are not inconsistent with this Code."}},{"id":"PH-H15202-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"Eminent Domain. - A local government unit may, through its head and acting pursuant to a\nresolution of its head and acting pursuant to a resolution of its sanggunian, exercise the right of eminent\ndomain and institute condemnation proceedings for public use or purpose."}},{"id":"PH-H15202-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"Closure of Roads. - A local government unit may likewise, through its head acting pursuant to a\nresolution of its sangguniang and in accordance with existing law and the provisions of this Code, close any\nbarangay, municipal, city or provincial road, street, alley, park or square. No such way or place or any part\nthereof shall be closed without indemnifying any person prejudiced thereby. A property thus withdrawn from\npublic use may be used or conveyed for any purpose for which other real property belonging to the local unit\nconcerned might be lawfully used or conveyed."}},{"id":"PH-H15202-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"Effectivity of Ordinances; Publication. -\n(1) No ordinance enacted by a local government shall take effect until after the lapse of ten (10) days from the\ndate a copy of it is posted in a bulletin board located in a conspicuous place at the provincial, city, municipal\nor barangay hall, at the public market, and/or at the church or chapel.\n(2) In highly urbanized cities, the main features of the ordinance must, in addition thereto, be published in a\nnewspaper of general circulation in the city."}},{"id":"PH-H15202-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"Corporate Powers. - Every local government unit shall, as a corporation, have the following\n(1) To have continuous succession in its corporate name;\n(2) To sue and be sued;\n(3) To have and use a corporate seal;\n(4) To acquire and convey real or personal property;\n(5) To enter into contracts; and\n(6) To exercise such other powers as are granted to corporations, subject to limitations provided in this Code\nand other laws."}},{"id":"PH-H15202-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"Non-Liability for Damages. - Unless otherwise provided by law, no province, city, municipality\nor barangay shall be liable for injuries or damages to persons or property arising from the act or omission of\nany of its officers or employees while in the performance of their official functions.\n\nINTERGOVERNMENTAL RELATIONS\nARTICLE ONE\nNATIONAL GOVERNMENTAL AND LOCAL GOVERNMENTS"}},{"id":"PH-H15202-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"National Supervision over Local Governments. -\n(1) The President of the Philippines shall exercise general supervision over local governments to ensure that\nlocal affairs are administered according to law. General supervision includes the power to order an\ninvestigation of the conduct of local government officials whenever necessary. Such general supervision shall\nbe exercised primarily through the Ministry of Local Government.\n(2) All ministries and national offices having to do with local government administration shall be confined to\nthe setting of uniform standards and guidelines to obviate the need for requiring prior approval or preclearance\non regular and recurring transactions and other activities normal to local governments. In this regard, the\nMinistry of Local Government shall establish and maintain appropriate coordinative and consultative\narrangements with other ministries and national offices concerned with respect to the monitoring and securing\nof proper compliance with such standards and guidelines specially on matters which are highly technical in\nnature. Moreover, as a matter of general policy and whenever appropriate, the Ministry of Local Government\nshall exercise its supervisory authority over municipalities through the provinces, and barangays through\nmunicipalities and cities.\n(3) Where appropriate, ministries and national agencies with project implementation functions other than the\nMinistry of Local Government, shall coordinate with and secure the desired integration with allied national\ngovernment functions.\n(4) Unless the contrary is provided, the regional offices or appropriate field units of the various ministries and\nnational agencies in the region shall be the major points of contract and liaison between local governments\nand the national government. For this purpose, the national government shall, as a general policy and as much\nas practicable, effect the substantial delegation of authority and powers to the regional offices.\nARTICLE TWO\nPROVINCE AND CITY"}},{"id":"PH-H15202-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"Provincial-City Relations. - The province, through the provincial governor, shall see to it that\nevery component city within its territorial jurisdiction acts within the scope of its - assigned powers and\nfunctions. Highly urbanized cities shall be independent of the province."}},{"id":"PH-H15202-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"Loans, Grants or Subsidies between Province and Component Cities. -\n(1) The sangguniang panlalawigan may, out of the provincial funds, extends loans, grants or subsidies to\ncomponent cities geographically located within the province under such terms and conditions as it may\n(2) The sangguniang panlungsod of a component city may, out of city funds, likewise extend loans, grants or\nsubsidies to the province to which it belongs, subject to such terms and conditions as it may impose.\nARTICLE THREE\nPROVINCE AND MUNICIPALITY"}},{"id":"PH-H15202-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"Provincial Supervision over Municipal Affairs. - The province, through the provincial\ngovernor, shall have primarily responsibility for general supervision over the government of every\nmunicipality within its territorial jurisdiction to ensure that it acts within the scope of its assigned powers and"}},{"id":"PH-H15202-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"Submission of Questions to the Provincial Attorney or Fiscal. - In the absence of a municipal\nattorney, the municipal government may secure the opinion of the provincial attorney, if any, or the provincial\nfiscal on any legal question affecting the municipality."}},{"id":"PH-H15202-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"Certain Acts of the Sangguniang bayan Requiring Approval of the Sangguniang panlalawigan. -\nThe following acts of the sangguniang bayan shall be subject to the approval of the sangguniang\npanlalawigan:\n(1) Permanent closure of a public road, street, alley, park or square; and\n(2) Donation of municipal funds or property."}},{"id":"PH-H15202-A20","no":20,"noLabel":{"en":"Section 20"},"text":{"en":"Provincial Loans, Grants and Subsidies. - The sangguniang panlalawigan may, out of the\nprovincial funds, extend loans, grants and subsidies to municipalities of the province under such terms and\nconditions as it may impose.\nARTICLE FOUR\nCITY AND BARANGAY"}},{"id":"PH-H15202-A21","no":21,"noLabel":{"en":"Section 21"},"text":{"en":"City Supervision over Barangay Affairs. - The city, through the city mayor, shall have primary\nresponsibility for general supervision over the government of every barangay within its territorial jurisdiction\nto ensure that it acts within the scope of its assigned powers and functions."}},{"id":"PH-H15202-A22","no":22,"noLabel":{"en":"Section 22"},"text":{"en":"Review of Barangay Ordinances and Resolutions. - The Sangguniang panlungsod shall review\nall ordinances and resolutions duly approved by the sangguniang barangay to ensure that they are within the\npowers granted by law and in conformity with the city ordinances."}},{"id":"PH-H15202-A23","no":23,"noLabel":{"en":"Section 23"},"text":{"en":"Barangay Improvement; Recommendations. - The sangguniang barangay may submit to the\nsangguniang panlungsod such suggestions or recommendations as it may see fit for the improvement of the\nbarangay and for the welfare of its inhabitants.\nARTICLE FIVE\nMUNICIPALITY AND BARANGAY"}},{"id":"PH-H15202-A24","no":24,"noLabel":{"en":"Section 24"},"text":{"en":"Municipal Supervision over Barangay Affairs. - The Municipality, through the municipal\nmayor, shall have primary responsibility for general supervision over the government of every barangay\nwithin its territorial jurisdiction to ensure that it acts within the scope of its assigned powers and functions."}},{"id":"PH-H15202-A25","no":25,"noLabel":{"en":"Section 25"},"text":{"en":"Review of Barangay Ordinances and Resolutions. - The sangguniang bayan shall review all\nordinances and resolutions duly approved by the sangguniang barangay to ensure that they are within the\npowers granted by law and in conformity with municipal ordinances."}},{"id":"PH-H15202-A26","no":26,"noLabel":{"en":"Section 26"},"text":{"en":"Recommendations to the Sangguniang bayan. - The sangguniang barangay may submit to the\nsangguniang bayan such suggestions or recommendations as it may see fit for the improvement of the\nbarangay and for the welfare of its inhabitants.\nRELATION WITH OTHER OFFICES"}},{"id":"PH-H15202-A27","no":27,"noLabel":{"en":"Section 27"},"text":{"en":"The Ministry of Health. -\n(1) The present participation of local government units as well as their fund assistance for the delivery of\nhealth services within their respective areas shall continue until such time as the national integration of said\nservices shall have been fully implemented by the Ministry of Health.\n(2) Notwithstanding this integration, a local government unit may assist or augment the integrated national\nhealth services with local funds."}},{"id":"PH-H15202-A28","no":28,"noLabel":{"en":"Section 28"},"text":{"en":"The Ministry of Justice. - Whenever the agencies of the service warrant the creation of\npositions of additional lawyers to assist provincial and city fiscals in the discharge of their duties, positions of\nspecial counsel may be created by any province or city with salaries chargeable against provincial or city\nfunds. Special counsel shall be appointed by the Minister of Justice upon recommendation of the provincial\ngovernor or city mayor concerned, either on permanent or temporary basis."}},{"id":"PH-H15202-A29","no":29,"noLabel":{"en":"Section 29"},"text":{"en":"The Commission of Audit. - The Commission on Audit shall review and audit all accounts of\neach local government unit in accordance with the provisions of law relating to government accounts and\naccounting."}},{"id":"PH-H15202-A30","no":30,"noLabel":{"en":"Section 30"},"text":{"en":"The Ministry of Education, Culture and Sports. - The Ministry of Education, Culture and Sports\nshall exercise the same jurisdiction and powers over all educational institutions established or supported by\nany local government unit that it exercises over all other public schools."}},{"id":"PH-H15202-A31","no":31,"noLabel":{"en":"Section 31"},"text":{"en":"Participation of Local Governments in the Implementation of National Programs and Projects. -\n(1) Each ministry, office, agency or instrumentality of the national government shall involve local\ngovernments and secure their participation in the various substantive aspects of programs and projects, and the\nother corollary operational activities that should be carried out through local governments.\n(2) As a general policy and as much as practicable, the national government shall encourage and provide the\nnecessary authority for local governments in the supervision of appropriate national government operations\nand activities undertaken at the various levels of local government."}},{"id":"PH-H15202-A32","no":32,"noLabel":{"en":"Section 32"},"text":{"en":"Technical and Financial Assistance; Technical Supervision. -\n(1) Every ministry, office, agency, or instrumentality of the national government shall render technical and\nprovide financial assistance to local governments necessary to carry out national policies, plans, programs,\nprojects and activities.\n(2) Ministries may exercise technical supervision over local governments on technical aspects over which they\nare responsible on the national level."}},{"id":"PH-H15202-A33","no":33,"noLabel":{"en":"Section 33"},"text":{"en":"Transfer of Responsibility. - As a general policy and where appropriate, the national\ngovernment shall encourage and take the necessary measures for the transfer of responsibility and the\ncorresponding authority over service delivery functions from the national to the local governments or from a\nhigher to a lower level of local government: Provided, however, That such transfer need not be affected at the\nsame time and for all the units in any tier of local government, but may be done on the basis of the capability\nof the local unit or units concerned to assume and discharge the transferred responsibility.\nFISCAL MATTERS"}},{"id":"PH-H15202-A34","no":34,"noLabel":{"en":"Section 34"},"text":{"en":"Principles to be Observed. - The following principles shall be observed by all concerned\nrelative to the financial affairs, transactions and operations of every local government:\n(1) As a general rule, local governments shall be allowed as much authority and flexibility over the financial\naspects of their operations which are consistent with such standards and guidelines as may be prescribed by\ncompetent authorities.\n(2) No money shall be paid out of the treasury except in pursuance of a lawful appropriation or other specific\nstatutory authority. No funds shall be disbursed, and no checks shall be issued without the approval or\nsignature of the local chief executive.\n(3) Public funds and monies shall be spent solely for public purposes.\n(4) Revenue shall be obtainable from all sources, including the power to levy taxes, subject to such limitations\nas may be provided by law.\n(5) All monies officially received by a public officer shall be accounted for as government funds, except as\nmay otherwise be specially provided by law.\n(6) Trust funds shall not be paid out of the treasury except in fulfillment of the purpose for which the trust was\ncreated or the funds received.\n(7) Fiscal responsibility shall be shared by all those exercising authority over the financial affairs, transactions\n\nand operations of the local government unit concerned."}},{"id":"PH-H15202-A35","no":35,"noLabel":{"en":"Section 35"},"text":{"en":"Preparation, Approval and Review of Budget. - Budgets of local government units shall be\nprepared, approved and reviewed in conformity with the provisions of law, rules and regulations, taking into\naccount such limitations as are imposed on appropriations for salaries and rates of compensation, personnel\nmovement and administration, and appropriations for discretionary purposes of local executives."}},{"id":"PH-H15202-A36","no":36,"noLabel":{"en":"Section 36"},"text":{"en":"Accounting and Accountability. -\n(1) Every local government officer whose duties require the possession or custody of local government funds\nshall be accountable therefor and responsible and responsible for their safekeeping in conformity with the\nprovisions of law. Local treasurers and other accountable officers shall render their accounts within such time\nin such form, style and contents and under such regulations as the Commission on Audit may prescribe\npursuant to law.\n(2) The heads of local government units shall be responsible for the proper operation and maintenance of the\naccounting offices in their respective units. They shall see to it that all accounting records and books conform\nto the applicable provisions of this Code, and the pertinent laws, rules, regulations and reporting requirements\nof the Office of Budget and Management. Non-compliance with such laws, rules, regulations and reporting\nrequirements shall be sufficient ground for administrative action against the officials responsible therefor,\nincluding dismissal from the service."}},{"id":"PH-H15202-A37","no":37,"noLabel":{"en":"Section 37"},"text":{"en":"Auditorial Inspection. - The books of accounts, papers and cash of any local treasurer or other\naccountable local official shall at all times be open to the inspection of the Commissioner on Audit or its duly\nauthorized representative."}},{"id":"PH-H15202-A38","no":38,"noLabel":{"en":"Section 38"},"text":{"en":"Credit Financing for Local Governments. - The conduct and management of the credit\ntransactions and borrowings of local governments shall be governed by existing laws."}},{"id":"PH-H15202-A39","no":39,"noLabel":{"en":"Section 39"},"text":{"en":"Intergovernmental Fiscal Relations. - Intergovernmental sharing of funds between the national\nand local governments shall be governed by existing laws.\nREQUIREMENTS AND PROHIBITIONS APPLICABLE TO ALL LOCAL OFFICIALS AND"}},{"id":"PH-H15202-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"Statement of Assets. - Before assuming office, and official or employee of a local government\nunit shall file in the office of its chief official a sworn statement of assets, liabilities and property holdings."}},{"id":"PH-H15202-A41","no":41,"noLabel":{"en":"Section 41"},"text":{"en":"Officials not to Engage in business Transaction or Possess Pecuniary Interest. - It shall be\nunlawful for any local government official, directly or indirectly, individually or as a member of a firm:\n(1) To engage in any business transaction with the local government unit of which he is an official or over\nwhich he has the power of supervision, or with any of its authorized officials, boards, agents, or attorneys,\nwhereby money is to be paid, or property or any other thing of value is to be transferred, directly or indirectly,\nout of the resources of the local government unit to such person or firm;\n(2) To purchase any real estate or other property forfeited in favor of such unit which shall be sold for unpaid\ntaxes or assessment, or by virtue of legal process at the suit of said unit;\n(3) To be surety for any person having contract or doing business with the local government unit for the\nperformance of which surety may be required.\nELECTIVE OFFICIALS\nQUALIFICATIONS AND ELECTION"}},{"id":"PH-H15202-A42","no":42,"noLabel":{"en":"Section 42"},"text":{"en":"Qualifications. -\n\n(1) An elective local official must be a citizen of the Philippines, at least twenty-three years of age on election\nday, a qualified voter registered as such in the barangay, municipality, city or province where he proposes to\nbe elected, a resident therein for at least one year at the time of the filing of his certificate of candidacy, and\nable to read and write English, Pilipino, or any other local language or dialect.\n(2) Candidates for the position of punong barangay or member of the sangguniang barangay must be actual\nresidents in the barangay where they propose to be elected.\n(3) A candidate for chairmanship of the Kabataang barangay need not be of the minimum age required in this"}},{"id":"PH-H15202-A43","no":43,"noLabel":{"en":"Section 43"},"text":{"en":"Manner of Election. -\n(1) Unless otherwise provided by law, the governor, vice-governor, city mayor, city vice-mayor, municipal\nmayor, municipal vice-mayor, and barangay officials shall be elected at large in their respective units by the\nqualified voters therein. However, the kabataang barangay chairman for each barangay shall be elected by the\nregistered voters of the kabataang barangay assembly as hereinafter provided.\n(2) The members of the sangguniang panlalawigan, sangguniang panlungsod, and sangguniang bayan shall be\nelected at large in their respective units, but the representatives of the katipunan ng mga barangay and the\nkabataang barangay federation in said sanggunians shall be elected by their own respective organizations,\nsubject to the supervision of the Commission of Elections.\n(3) Unless otherwise provided by law, the present manner of election/appointment of representatives of the\nagricultural and industrial labor sectors to the sangguniang panlungsod or sangguniang bayan, as the case may\nbe, shall be maintained."}},{"id":"PH-H15202-A44","no":44,"noLabel":{"en":"Section 44"},"text":{"en":"Term of Office. - The term of office of all elective officials shall be six (6) years, starting from\nthe date provided by law."}},{"id":"PH-H15202-A45","no":45,"noLabel":{"en":"Section 45"},"text":{"en":"Change of Territory Affecting Tenure of Office. - When a part of a province, city, municipality,\nor barangay is detached from its mother unit to form a new local government unit, or is merged to an existing\nlocal government unit, any elective official of the mother unit residing in the detached or merged territory\nshall be entitled to continue to hold office in the mother province, city, municipality or barangay, as the case\nmay be, and exercise the functions thereof for the remainder of his term."}},{"id":"PH-H15202-A46","no":46,"noLabel":{"en":"Section 46"},"text":{"en":"Supervision over Local Elections by the Commission on Elections. - The Commission on\nElections shall, in addition to the powers and functions conferred upon it by the Constitution and other laws,\nhave supervision over local elections and plebiscites with powers to promulgate the necessary rules and\nregulations consistent with the provisions of this Code."}},{"id":"PH-H15202-A47","no":47,"noLabel":{"en":"Section 47"},"text":{"en":"Commutation of Leave Credits. - All elective local government officials shall be entitled to\nwhatever leave credits are granted to appointive officials under existing laws, and the commutation of the\nmoney value thereof.\nVACANCIES AND SUCCESSION"}},{"id":"PH-H15202-A48","no":48,"noLabel":{"en":"Section 48"},"text":{"en":"Permanent Vacancy in the Office of the Governor, City or Municipal Mayor. -\n(1) In case a permanent vacancy arises when a governor, city or municipal mayor refuses to assume office,\nfails to qualify, dies or is removed from office, voluntarily resigns, or is otherwise permanently incapacitated\nto discharge the functions of his office, the vice-governor, city or municipal vice-governor, as the case may\nbe, shall assume the office for the unexpired term of the former.\n(2) If the vice-governor, city or municipal vice-governor, as the case may be, likewise refuses to assume office\nor fails to qualify, dies or is removed from office, voluntarily resigns, or is otherwise permanently\nincapacitated to discharge the functions of the office, the member of the sangguniang panlalawigan,\nsangguniang panlungsod or sangguniang bayan, as the case may be, who obtained the highest number of votes\n\nin the election immediately preceding shall assume the office for the unexpired term of the governor, city or\nmunicipal mayor concerned.\n(3) If the sanggunian member concerned likewise refuses to assume office or fails to qualify, dies or is\nremoved from office, voluntarily resigns, or is otherwise permanently incapacitated to discharge the function\nof the office, the vacancy shall be filled by appointment of the President of the Philippines, upon\nrecommendation of the Minister of Local Government, for the unexpired term of the vacant office."}},{"id":"PH-H15202-A49","no":49,"noLabel":{"en":"Section 49"},"text":{"en":"Permanent Vacancy in the Office of the Vice-Governor, City or Municipal Vice-Mayor. -\n(1) In case a permanent vacancy arises when a vice-governor, city or municipal vice-mayor assumes the office\nof governor, city or municipal mayor, as the case may be, or refuses to assume office, fails to qualify, dies, is\nremoved from Office, voluntarily resigns or is otherwise permanently incapacitated to discharge the functions\nof his office, the sangguniang panlalawigan, sangguniang panlungsod or sangguniang bayan member who\nobtained the highest number of votes in the election immediately preceding, as the case may be, shall assume\nthe office for the unexpired term of the vice-governor, city or municipal vice-mayor concerned.\n(2) If the sanggunian member concerned likewise assume the office of governor, city or municipal mayor, as\nthe case may be, or refuses to assume office, fails to qualify, dies or is removed from office, voluntarily\nresigns or is otherwise permanently incapacitated to discharge the functions of the office, the vacancy shall be\nfilled by appointment of the President of the Philippines, upon recommendation of the Minister of Local\nGovernment, for the unexpired term of the vacant office."}},{"id":"PH-H15202-A50","no":50,"noLabel":{"en":"Section 50"},"text":{"en":"Permanent Vacancies in Local Sanggunians. - In case of permanent vacancy in the sangguniang\npanlalawigan, sangguniang panlungsod, sangguniang bayan, or sangguniang barangay, the President of the\nPhilippines, upon recommendation of the Minister of Local Government, shall appoint a qualified person to\nfill the vacancy in the sangguniang panlalawigan and the sangguniang panlungsod; the governor, in the case of\nsangguniang bayan members; or the city or municipal mayor, in the case of sangguniang barangay members.\nExcept for the sangguniang barangay, the appointee shall come from the political party of the sanggunian\nmember who caused the vacancy, and shall serve the unexpired term of the vacant office."}},{"id":"PH-H15202-A51","no":51,"noLabel":{"en":"Section 51"},"text":{"en":"Permanent Vacancy in the Office of Punong Barangay. -\n(1) In the event the Punong barangay refuses to assume office, fails to qualify, dies or is removed from office,\nvoluntarily resigns, or is otherwise permanently incapacitated to discharge the functions of his office, the\nmember of the sangguniang barangay who obtained the highest number of votes in the election immediately\npreceding shall assume the office for the unexpired term of the punong barangay.\n(2) If the sangguniang barangay member concerned likewise refuses to assume office, fails to qualify, dies or\nis removed from office, voluntarily resigns, or is otherwise permanently incapacitated to discharge the\nfunctions of his office, the vacancy shall be filled by the member of the sangguniang barangay who obtained\nthe next highest number of votes in the election immediately preceding. The successor shall assume the office\nof punong barangay for the unexpired term of the vacant office."}},{"id":"PH-H15202-A52","no":52,"noLabel":{"en":"Section 52"},"text":{"en":"Temporary Vacancy in the Office of Governor, City or Municipal Mayor, or Punong Barangay.\n-\n(1) In case of temporary in capacity of the governor, city or municipal mayor, or punong barangay to perform\nhis duties on account of physical or legal causes, or when he is one official leave of absence or on travel\noutside the territorial jurisdiction of the Republic of the Philippines, the vice-governor, city or municipal\nvice-mayor, or the sangguniang barangay number who obtained the highest number of votes in the election\nimmediately preceding, as the case may be, shall exercise the powers, duties and functions of the governor,\ncity or municipal mayor, or punong barangay, as the case may be, except the power to appoint, suspend or\ndismiss employees for a period corresponding to the temporary incapacity of the incumbent, or corresponding\nto the incumbent's official leave of absence or travel abroad, or for a period of not more than three months.\n(2) Upon the expiration of three months, should the temporary incapacity, official leave of absence, or travel\n\nabroad subsist, the vice-governor, city or municipal vice-mayor, or sangguniang barangay member concerned\nas the case may be, may exercise the power to appoint, suspend or dismiss employees for a period\ncorresponding to the temporary incapacity, official leave of absence, or travel abroad of the incumbent.\n(3) Nothing in this section shall be construed to mean automatic assumption of powers, duties and functions\non the part of the vice-governor, city or municipal vice-mayor, or sangguniang barangay member concerned,\nas the case may be, when the incumbent local executive is on official travel in connection with the discharge\nof the duties and functions of his office."}},{"id":"PH-H15202-A53","no":53,"noLabel":{"en":"Section 53"},"text":{"en":"Approval of Leave Privileges. - The leave privileges of local elective officials shall be\napproved as follows:\n(1) The leave privileges of the vice-governor, city or municipal vice-mayor and members of the sanggunian in\nall levels shall be approved by the local chief executive concerned;\n(2) Leave privileges of the municipal mayor shall be approved by the provincial governor; and\n(3) Leave privileges of the city mayor and the provincial governor shall be approved by the Minister of Local\nGovernment or his duly authorized representative."}},{"id":"PH-H15202-A54","no":54,"noLabel":{"en":"Section 54"},"text":{"en":"By whom Exercised; Requisites. -\n(1) The power of recall shall be exercised by the registered voters of the unit to which the local elective\nofficial subject to such recall belongs.\n(2) Recall shall be validly initiated only upon petition of at least twenty-five percent of the total number of\nregistered voters in the local government unit concerned based on the election in which the local official\nsought to be recalled was elected."}},{"id":"PH-H15202-A55","no":55,"noLabel":{"en":"Section 55"},"text":{"en":"Who May be Recalled; Ground for Recall; When Recall May not be Held. -\n(1) Any elective official may be recalled only once during his term of office for loss of confidence.\n(2) No recall shall take effect place within two years from the date of the official's assumption of office or one\nyear immediately preceding a regular local election."}},{"id":"PH-H15202-A56","no":56,"noLabel":{"en":"Section 56"},"text":{"en":"Form, Venue and Procedure for Recall. -\n(1) A written petition for recall duly signed before the election registrar or his representative, and in the\npresence of a representative of the petitioner and a representative of the official sought to be recalled, and in a\npublic place in the province, city, municipality or barangay, as the case may be, shall be filled with the\nCommission on Elections through its office in the local unit concerned. The Commission on elections or its\nduly authorized representative shall cause the publication of the petition in a public and conspicuous place for\na period of not less than ten days nor more than twenty days, for the purpose of verifying the authenticity and\ngenuineness of the petition and the required percentage of voters.\n(2) Upon the lapse of the aforesaid period, the Commission on Elections or its authorized representative shall\nannounce the acceptance of candidates to the position and thereafter prepare the list of candidates which shall\ninclude the name of the official sought to be recalled.\n(3) The Commission on Elections shall then set the date for the election which shall not be later than thirty\ndays after the announcement of the acceptance of candidates for the election on recall in the case of the city,\nmunicipal or barangay officials, and forty-five days in the case of provincial officials. The election shall then\nbe held on the date set, after which the winner shall be certified and proclaimed by the Commission on"}},{"id":"PH-H15202-A57","no":57,"noLabel":{"en":"Section 57"},"text":{"en":"Effectivity of Recall. - The recall of a local elective official shall be effective only upon the\nelection and proclamation of a successor in the person of the candidate receiving the highest number of votes\n\ncast during the election. Should the official sought to be recalled receive the highest number of votes,\nconfidence in him is hereby affirmed and he shall continue in office."}},{"id":"PH-H15202-A58","no":58,"noLabel":{"en":"Section 58"},"text":{"en":"Acts of the Commission on Elections. - All acts of the Commission on elections on all matters\npertaining to the recall of local elective officials shall be governed by the Constitution and the election laws."}},{"id":"PH-H15202-A59","no":59,"noLabel":{"en":"Section 59"},"text":{"en":"Supervision by the Commission on Elections. - The Commission on Elections shall conduct\nand supervise the process of and election on recall in the manner and time herein provided and, in pursuance\nthereof, promulgate the necessary rules and regulations.\nSUSPENSION AND REMOVAL"}},{"id":"PH-H15202-A60","no":60,"noLabel":{"en":"Section 60"},"text":{"en":"Suspension and Removal; Grounds. - An elective local official may be suspended or removed\nfrom office on any of the following grounds committed while in office:\n(1) Disloyalty to the Republic of the Philippines;\n(2) Culpable violation of the Constitution;\n(3) Dishonesty, oppression, misconduct in office and neglect of duty;\n(4) Commission of any offense involving moral turpitude;\n(5) Abuse of authority;\n(6) Unauthorized absence for three consecutive months."}},{"id":"PH-H15202-A61","no":61,"noLabel":{"en":"Section 61"},"text":{"en":"Form and Filing of Complaints. - Verified complaints against local elective officials shall be\npreferred as follows:\n(1) Against any elective provincial or city official, before the Minister of Local Government;\n(2) Against any elective municipal official, before the sangguniang panlalawigan;\n(3) Against any elective barangay official of a city or municipality, before the sangguniang panlungsod or the\nsangguniang bayan, as the case may be."}},{"id":"PH-H15202-A62","no":62,"noLabel":{"en":"Section 62"},"text":{"en":"Notice of hearing. - Within seven days after the complaint is filed, the minister of Local\nGovernment, or the sanggunian concerned, as the case may be, shall require the respondent to submit his\nverified answer within seven days from receipt of said complaint, and commence the hearing and\ninvestigation of the case within ten days after receipt of such answer of the respondent. No investigation shall\nbe held within ninety days immediately prior to an election, and no preventive suspension shall be imposed\nwithin the said period. If preventive suspension has been imposed prior to the aforesaid period, the preventive\nsuspension shall be lifted."}},{"id":"PH-H15202-A63","no":63,"noLabel":{"en":"Section 63"},"text":{"en":"Preventive Suspension. -\n(1) Preventive suspension may be imposed by the Minister of Local Government if the respondent is a\nprovincial or city official, by the provincial governor if the respondent is an elective municipal official, or by\nthe city or municipal mayor if the respondent is an elective barangay official.\n(2) Preventive suspension may be imposed at any time after the issuances are joined, when there is reasonable\nground to believe that the respondent has committed the act or acts complained of, when the evidence of\nculpability is strong, when the gravity of the offense so warrants, or when the continuance in office of the\nrespondent could influence the witnesses or pose a threat to the safety and integrity of the records and other\nevidence. In all cases, preventive suspension shall not extend beyond sixty days after the start of said\nsuspension shall not extend beyond sixty days after the start of said suspension.\n(3) At the expiration of sixty days, the suspended official shall be deemed reinstated in office without\nprejudice to the continuation of the proceedings against him until its termination. However, if the delay in the\nproceedings of the case is due to his fault, neglect or request, the time of the delay shall not be counted in\n\ncomputing the time of suspension."}},{"id":"PH-H15202-A64","no":64,"noLabel":{"en":"Section 64"},"text":{"en":"Rights of the Respondent. - The respondent shall be accorded full opportunity to appear and\ndefend himself in person or by counsel, to confront and cross-examine the witnesses against him, and to\nrequire the attendance of witnesses and the production of documentary evidence in his favor through the\ncompulsory process of subpoena or subpoena duces tecum."}},{"id":"PH-H15202-A65","no":65,"noLabel":{"en":"Section 65"},"text":{"en":"Form and Notice of Decision. -\n(1) Within thirty days after the end of the investigation, the Minister of Local Government, or provincial, city\nor municipal sanggunian, as the case may be, shall render a decision in writing stating clearly and distinctly\nthe facts and the reasons for such decision, copies of which shall immediately be furnished the respondent and\nall interested parties.\n(2) The penalty of suspension shall not exceed the unexpired term of the respondent, nor shall the penalty of\nsuspension or removal be a bar to the candidacy of the respondent so suspended or removed from an elective\npublic office as long as he meets the qualifications so required for the office."}},{"id":"PH-H15202-A66","no":66,"noLabel":{"en":"Section 66"},"text":{"en":"Administrative Appeals. -\n(1) Administrative appeals from the decision of suspension or removal shall be made within thirty days from\nthe date on which the same was received, to the following authorities whose decision shall be final:\n(a) The decision of the Minister of Local Government shall be appealable to the President.\n(b) The decision of the provincial, city or municipal sanggunian shall be appealable to the Minister of Local\nGovernment.\n(2) The provisions of this section be without prejudice to appropriate judicial remedies."}},{"id":"PH-H15202-A67","no":67,"noLabel":{"en":"Section 67"},"text":{"en":"Salary of Respondent Pending Suspension. - The respondent official suspended from office\npending an investigation of charges against him shall receive no salary or compensation during such\nsuspension; but, upon subsequent exoneration and reinstatement, he shall be paid full salary or compensation\nincluding such emoluments accruing during such suspension.\nTITLE THREE\nLOCAL SCHOOL BOARDS"}},{"id":"PH-H15202-A68","no":68,"noLabel":{"en":"Section 68"},"text":{"en":"Creation and Composition. -\n(1) In every province, city or municipality, there shall be established, respectively, a provincial school board,\ncity school board, or municipal school board, which shall be composed as follows:\n(a) In the case of the provincial school board, the governor as chairman, the division superintendent of schools\nas vice chairman, and the provincial treasurer, a representative of the sangguniang panlalawigan chosen by it\nfrom among its members, and the president or duly elected representative of the federation of parent-teachers\nassociations as members.\n(b) In the case of the city school board, the city mayor as chairman, the city superintendent of schools as vice\nchairman, and the city treasurer, the representative of the sangguniang panlungsod chosen by it from among\nits members, and the president or duly elected representative of the federation of parent-teachers associations,\n(c) In the case of the municipal school board, the municipal mayor as chairman, the district supervisor as vice\nchairman, and the municipal treasurer, the representative of the sangguniang bayan chosen by it from among\nits members, and the president or duly elected representative of the federation of parent-teachers associations,\n(2) In the event that a province or city has two or more school superintendents, and in the event that a\nmunicipality has two or more district supervisors, the vice-chairman of the local school board shall be\ndetermined as follows:\n\n(a) The regional director of the Ministry of Education Culture and Sports shall designate the vice-chairman for\nthe provincial and city school boards; and\n(b) The division superintendent of schools shall designate the district supervisor who will serve as\nvice-chairman of the municipal school board.\n(3) The performance of the duties and responsibilities of the above-mentioned officials in their respective\nschool boards shall not be delegated."}},{"id":"PH-H15202-A69","no":69,"noLabel":{"en":"Section 69"},"text":{"en":"Functions. - The provincial, city or municipal school board, shall:\n(1) Determine in accordance with the criteria set by the Ministry of Education, culture and sports, the annual\nsupplementary budgetary needs for the operation and maintenance of local public schools within the province,\ncity or municipality and the supplementary local cost of adequately meeting such needs which shall be\nreflected in the form of an annual school board budget corresponding to the board's share of the proceeds of\nthe additional real property tax. The approval by the Ministry of Education, Culture and Sports of said budget\nshall be ministerial.\n(2) Apply for a share in the stabilization portion of the fund established under existing laws creating the\nSpecial Education Fund, which share shall, upon approval of the application therefor be remitted to the\nprovincial, city or municipal treasurer concerned.\n(3) Authorize the provincial, city or municipal treasurer, as the case may be, to disburse funds from the\nprovincial, city or municipal share in the Special Education Fund pursuant to the budget prepared and in\naccordance with existing rules and regulations."}},{"id":"PH-H15202-A70","no":70,"noLabel":{"en":"Section 70"},"text":{"en":"Meetings and Quorum. -\n(1) The board shall meet at lease once a month or as often as the chairman or majority of the members find it\n(2) Three members shall constitute a quorum, but the chairman and vice-chairman must always be present\nwhen the school budget is being prepared and considered. The affirmative vote of three members shall be\nnecessary to approve the budget."}},{"id":"PH-H15202-A71","no":71,"noLabel":{"en":"Section 71"},"text":{"en":"Compensation and Remuneration. - The chairman and members of the provincial, city or\nmunicipal school boards shall perform their duties as such without compensation or remuneration. Members\nthereof who are not government officials shall be entitled to necessary travelling expenses chargeable against\nthe funds of the school board concerned.\nPERSONNEL ADMINISTRATION"}},{"id":"PH-H15202-A72","no":72,"noLabel":{"en":"Section 72"},"text":{"en":"Responsibility for Personnel Administration. - Each head of a local government unit shall be\nresponsible for personnel administration in his unit and shall take all personnel actions in accordance with the\nconstitutional provisions relative to the civil service and all laws and rules thereon, including such policies,\nguidelines and standards as the Civil Service Commission may establish."}},{"id":"PH-H15202-A73","no":73,"noLabel":{"en":"Section 73"},"text":{"en":"Appointment of personnel of Local Governments. - All officials and employees paid wholly out\nof provincial, city or municipal funds shall be appointed by the governor, city or municipal mayor, as the case\nmay be, except as otherwise provided in this Code."}},{"id":"PH-H15202-A74","no":74,"noLabel":{"en":"Section 74"},"text":{"en":"Promotion. - Promotions in local governments shall be in accordance with existing laws and\nrules on the matter. The head of a local government shall evolve his own screening process for determining\nemployees deserving promotion which may include tests of merit and fitness under standards and guidelines\nestablished by the Civil Service Commission."}},{"id":"PH-H15202-A75","no":75,"noLabel":{"en":"Section 75"},"text":{"en":"Salaries of Officials and Personnel. - The salaries of officials and employees of local\ngovernment shall be provided by law or ordinance: Provided, That the salaries or compensation of the\n\nvice-governor, vice-mayor, and members of the sanggunian in all levels and such other positions as are not\nincluded under existing laws shall be determined by the Joint commission on Local Government personnel\nAdministration established under Presidential Decree Numbered One Thousand one hundred thirty-six."}},{"id":"PH-H15202-A76","no":76,"noLabel":{"en":"Section 76"},"text":{"en":"Abolition of Position. - When the position of an official or employee under the civil service is\nabolished by law or ordinance, the official or employee so affected shall be reinstated in another vacant\nposition without diminution of salary. Should such position not be available, the official or employee affected\nshall be granted a separation of service over and above the monetary privileges granted to officials and\nemployees under existing laws."}},{"id":"PH-H15202-A77","no":77,"noLabel":{"en":"Section 77"},"text":{"en":"Administrative Discipline. - Investigation and adjudication of administrative complaints against\nappointive local officials and employees of local governments as well as their suspension and removal shall be\nin accordance with the civil service law and rules and other laws affecting the civil service. The results of such\nadministrative complaints and investigation shall be reported to the Civil Service Commission."}},{"id":"PH-H15202-A78","no":78,"noLabel":{"en":"Section 78"},"text":{"en":"Disciplinary Jurisdiction. -\n(1) Except as otherwise provided by law, the head of a local government unit shall have authority to remove,\nseparate, suspend and otherwise discipline officials and employees under his jurisdiction. If the penalty\nimposed is suspension without pay for not more than thirty days, his decision shall be final. If the penalty\nimposed is heavier, the decision shall be appealable to the Civil Service Commission which has final authority\nupon all matters relating to the conduct, discipline and efficiency of local government officials and employees.\nIf the respondent is in the career executive service, appeal shall be made to the Career Service Board.\n(2) An appeal shall not prevent a decision from becoming executory, and in case the penalty is suspension of\nremoval, the respondent shall be considered as having been under preventive suspension during the pendency\nof an appeal in the event he wins such appeal. However, the respondent shall be paid his salary corresponding\nto the period during which the appeal is pending in the event he is completely exonerated.\nSETTLEMENT OF MUNICIPAL AND BARANGAY BOUNDARY DISPUTES"}},{"id":"PH-H15202-A79","no":79,"noLabel":{"en":"Section 79"},"text":{"en":"Municipal Boundary Disputes. - Disputes as to the jurisdiction of municipal governments over\nareas or barangays shall be heard and decided by the sangguniang panlalawigan of the province where the\nmunicipalities concerned are situated. Where the areas or barangays in dispute are claimed by municipalities\nsituated in different provinces, the sangguniang panlalawigan of the provinces involved shall jointly hear and\ndecide the dispute, in no case no settlement is reached within sixty days from the date the dispute was referred\nto the sangguniang panlalawigan concerned, said dispute shall be elevated to the Regional Trial Court of the\nprovince which first took cognizance of the dispute. The case shall be decided by the said court within one\nyear from the start of proceedings and appeal may be taken from the decision within the time and in the\nmanner prescribed by the Rules of Court."}},{"id":"PH-H15202-A80","no":80,"noLabel":{"en":"Section 80"},"text":{"en":"Barangay Boundary Disputes. - Boundary disputes between barangays within the same city or\nmunicipality shall be heard and decided by the sangguniang panlungsod or sangguniang bayan concerned for\nthe purpose of affording the parties an opportunity to reach an amicable settlement. In case no amicable\nsettlement is reached within sixty days from the date the dispute was referred to the sangguniang panlungsod\nor the sangguniang bayan, as the case may be, the case shall be heard and decided by the Regional Trial Court\nof the province or city where the barangays concerned are located within one year from the start of court\nproceedings. Appeal may be taken within the time and in the manner prescribed by the Rules of Court.\nLOCAL GOVERNMENT UNITS\nTHE BARANGAY"}},{"id":"PH-H15202-A81","no":81,"noLabel":{"en":"Section 81"},"text":{"en":"Role of Barangays. - As the basic political unit, the barangay serves as the primary planning\nand implementing unit of government programs, projects and activities, and as a forum in which the collective\nviews of the people in the community may be crystalized and considered."}},{"id":"PH-H15202-A82","no":82,"noLabel":{"en":"Section 82"},"text":{"en":"Manner of Creation. - A barangay may be created, named, and its boundaries defined, altered or\nmodified, by an ordinance of the sangguniang panlalawigan or sangguniang panlungsod, as the case may be,\nsubject to the approval by a majority of the votes cast in a plebiscite called for the purpose by the Commission\non Elections to be held in the unit or units affected within such period of time as may be determined by the\nordinance creating said barangay.\nExisting barangays, and those which have been organized pursuant to existing laws, operating with their own\nset of officers, shall be considered as such, and shall be governed by the provisions of this Code."}},{"id":"PH-H15202-A83","no":83,"noLabel":{"en":"Section 83"},"text":{"en":"Requisites for Creation. -\n(1) A barangay may be created out of a contiguous territory which has a population of at least one thousand\ninhabitants, provided the creation thereof shall not reduce the population of the another barangay or barangays\nto less than one thousand inhabitants. The territory need not be contiguous if it comprises two or more islands.\n(2) The territorial jurisdiction of the new barangay shall be properly identified by metes and bounds or by\nnatural boundaries."}},{"id":"PH-H15202-A84","no":84,"noLabel":{"en":"Section 84"},"text":{"en":"Naming of Barangays. - The name of an existing barangay may not be changed unless for a\njustifiable reason and not more often than once every ten years. In no case shall a new barangay be named\nafter a living person."}},{"id":"PH-H15202-A85","no":85,"noLabel":{"en":"Section 85"},"text":{"en":"Boundaries of Barangays. - In determining the boundaries of a barangay, the sangguniang\npanlungsod or sangguniang bayan, as the case may be, shall be assisted by the provincial, city or municipal\nassessor and the Director of Lands or his deputies. In the absence of any documentary or technical basis for\nfixing the boundaries, the sangguniang panlungsod or sangguniang bayan, as the case may be, shall be guided\ninitially by commonly accepted boundaries. After sixty days from such determination, these boundary limits\nshall be deemed final, unless new barangays are created or formal proceedings for the relocation of boundaries\nhave been instituted in the meantime.\nBARANGAY OFFICIALS AND OFFICES IN GENERAL"}},{"id":"PH-H15202-A86","no":86,"noLabel":{"en":"Section 86"},"text":{"en":"Chief Officials and Offices. -\n(1) There shall be in each barangay a punong barangay, six (6) elective sangguniang barangay members, the\nkabataang barangay chairman, a barangay secretary and a barangay treasurer.\n(2) Executive officers of barangay brigades and such other positions or offices as may be deemed necessary to\ncarry out the purpose of the barangay government may be created by the sangguniang barangay, subject to\navailability of funds and the needs of public service.\n(3) The Ministry of Local Government shall prescribe minimum standards and guidelines with respect to the\norganizational structure, staffing pattern and other relevant operational aspects of barangays according to"}},{"id":"PH-H15202-A87","no":87,"noLabel":{"en":"Section 87"},"text":{"en":"Persons in Authority. - For purposes of the Revised Penal Code, the punong barangay shall be\ndeemed a person in authority, while sangguniang barangay members, barangay pook or district leaders,\nofficers and members of the barangay community brigades, and such other barangay members who may be\ndesignated by law and charged with the maintenance of public maintenance of public order, protection and\nsecurity of life and property, or the maintenance of a desirable and balanced environment, and any barangay\nmember who comes to the aid of persons in authority, shall be deemed agents of persons in authority.\nTHE PUNONG BARANGAY"}},{"id":"PH-H15202-A88","no":88,"noLabel":{"en":"Section 88"},"text":{"en":"Powers and Duties. -\n(1) The punong barangay shall be the head of the barangay government and shall exercise such powers, duties\nand functions as are provided in this Code and other laws.\n(a) Enforce all laws and ordinances which are operative within the barangay;\n(b) Negotiate, enter into, and sign contracts for and in behalf of the barangay, upon authorization of the\nsangguniang barangay;\n(c) Maintain public order in the barangay and assist the municipal or city mayor and the sangguniang bayan or\nsangguniang panlungsod members, who are assigned to take charge of their district, in the performance of\ntheir duties in such barangay;\n(d) Call and preside over the meetings of the sangguniang barangay and the barangay assembly, and vote to\n(e) Appoint or replace the barangay secretary and other officers of the barangay;\n(f) Upon approval by a majority of all the members of the sangguniang barangay, appoint or replace the\nbarangay treasurer;\n(g) Organize and lead an emergency group whenever the same may be necessary for the maintenance of peace\nand order within the barangay;\n(h) Prepare the annual and supplemental budgets of the barangay;\n(i) Approve vouchers relating to the disbursement of barangay funds;\n(j) Enforce laws and regulations relating to pollution and environmental control and effect arrests of violators\n(k) Exercise general supervision over the affairs of the kabataang barangay for purposes of coordination with\nthe sangguniang barangay;\n(l) Look after the general welfare of the barangay;\n(m) Exercise such other powers and perform such other duties and functions as may be provided by law or\n(3) In the performance of his peace and order functions, the punong barangay shall be entitled to possess and\ncarry the necessary firearms within his territorial jurisdiction, subject to existing rules and regulations on the\npossession and carrying of firearms."}},{"id":"PH-H15202-A89","no":89,"noLabel":{"en":"Section 89"},"text":{"en":"Compensation. - The punong barangay shall receive such compensation, allowances and other\nemoluments as may be authorized by the sangguniang barangay in accordance with the provisions of this\nTHE SANGGUNIANG BARANGAY"}},{"id":"PH-H15202-A90","no":90,"noLabel":{"en":"Section 90"},"text":{"en":"Composition. - The sangguniang barangay shall be the legislative body of the barangay and\nshall be composed of the punong barangay as presiding officer, and the six sangguniang barangay members\nelected at large and the chairman of the kabataang barangay, as members."}},{"id":"PH-H15202-A91","no":91,"noLabel":{"en":"Section 91"},"text":{"en":"Powers and Duties. -\n(1) The sangguniang barangay shall:\n(a) Enact such ordinance as may be necessary to carry into effect and discharge the responsibilities conferred\nupon it by law, and such as shall be necessary and proper to promote health and safety, enhance the prosperity\nand general welfare, improve the morals, and maintain peace and order in the barangay and preserve the\n\ncomfort and convenience of the inhabitants therein;\n(b) Provide for the construction and maintenance of barangay roads, bridges, viaducts, sidewalks, playgrounds\nand parks, school buildings, water supply system, drainage irrigation sewerage, public toilet facilities and\nother public works projects and facilities within the barangay and for this purpose, exercise the power of\neminent domain with the approval of the sangguniang bayan or the sangguniang panlungsod;\n(c) Assist in the establishment, organization and promotion of cooperative enterprises that will improve the\neconomic condition and well-being of the barangay residents. Such enterprises may include credit unions,\nstocks for the sale or purchase of commodities and produce, warehouses, activities relating to agricultural and\nlivestock production and marketing, fishing, home arts, barangay industries, and other activities which may\npromote the welfare of the barangay inhabitants;\n(d) Solicit or accept, in any or all the foregoing public works and cooperative enterprises, such cooperation as\nis made available by municipal, provincial, city, and national government agencies established by law to\nrender financial, technical and advisory assistance to barangays and to barangay residents: Provided, however,\nThat in soliciting or accepting such cooperation, the sangguniang barangay may not pledge any sum of money\nfor expenditure in excess of amounts currently in the barangay treasury or encumbered for the other purposes;\n(e) Provide compensation or reasonable per diems as well as travel expenses for sangguniang barangay\nmembers and other officials in the barangay, subject to the availability of funds: Provided, That the total\nexpenditures for these purposes shall not exceed sixty percent of the total annual income of the barangay, nor\nshould such compensation, per diems , and travel expenses exceed those granted to sangguniang bayan or\nsangguniang panlungsod members of the municipality or city to which such barangay belongs, or the\ncompensation, per diems, and travel expenses granted to the city or municipal mayor of the same city or\nmunicipality;\n(f) Submit to the sangguniang bayan or sangguniang panlungsod such suggestions or recommendations as it\nmay see fit for the improvement of the barangay or for the welfare of the inhabitants thereof;\n(g) Hold fund-raising activities for barangay purposes without securing permits from the Ministry of Social\nServices and Development or from the municipal or city mayor, except when said activities are undertaken\noutside the barangay, in which event, a permit therefor shall be secured from the city or municipal mayor, as\nthe case may be, who shall fix the period for such activities, and the proceeds from which shall be tax-exempt\nand shall accrue to the general fund of the barangay: Provided, That in the appropriation thereof, the specific\npurpose for which such activity has been held shall be first satisfied: Provided, further, That no benefits shall\nbe held in the barangay within a period of sixty days immediately preceding any national or local election;(h)\nRegulate the use of cement pavements, grain or copra driers or patios, communal irrigation, barangay\nwaterworks, barangay markets or similar projects constructed with government funds for public service within\nthe jurisdiction or the barangay and charge reasonable fees for such use;\n(i) Organize regular lectures, programs, and community assemblies to enlighten the people on the physical,\nsocio-cultural, moral, civic, political, educational an other matters of public interest;\n(j) Provide for the organization of such community brigades as may be authorized by law;\n(k) Enact the annual and supplemental budgets of the barangay in accordance with law;\n(l) Authorize the punong barangay to enter into contracts in behalf of the barangay;\n(m) Authorize the barangay treasurer to make direct purchases amounting to not more than three hundred\npesos at any one time for the ordinary and essential administrative needs of the barangay;\n(n) Act on the resignation of sangguniang barangay members and other officers of the barangay;\n(o) Recommend from time to time to the city or municipal assessor, through the sangguniang panlungsod or\nsangguniang bayan, the reassessment of real properties located in the barangay;\n\n(p) Whenever feasible, initiate the organization of a barangay high school in accordance with law;\n(q) Prescribe fines of not more than five hundred pesos for violation of barangay ordinances;\n(r) provide for the proper development and welfare of the children in the barangay and deal with the problem\nof juvenile delinquency in consonance with existing laws and, for this purpose, encourage the organization\nwithin the barangay of a local council in which the kabataang barangay shall be represented;\n(s) In coordination with the Ministry of Education, Culture and Sports, establish a non-formal education center\nin the barangay which shall provide education and training to adults and out-of-school youth to enable them to\nacquire skills for industry and agriculture; improve the literacy of those who cannot avail of the facilities of\nformal education; prepare them for productive activities by developing their self-reliance, proper attitude and\nbehavior towards work and implement the non-formal educational policies and programs work and implement\nthe non-formal educational policies and programs of the Ministry of Education, Culture and Sports and other\nagencies of the government;\n(t) Accept or solicit monies, materials and voluntary labor for specific public works and cooperative\nenterprises of the barangay from residents, landholders, produces and merchants in the barangay; monies from\ngrants-in-aid, subsidies, contributions, and revenues made available to the barangays from municipal, city,\nprovincial or national funds; and monies from private agencies and individuals: Provided, That monies or\nproperties donated by private agencies and individuals for specific purposes shall accrue to the barangay as a\nspecial trust fund for that purpose;\n(u) Exercise such powers as are necessary to carry out the foregoing provisions or which may be provided by\nlaw or ordinance.\n(2) The expenses for the construction and maintenance of public works projects referred to in subparagraph\n(b) of this section shall be chargeable to the barangay development fund or other funds actually available for\nthe purpose.\n(3) Any contract authorized under subparagraph (l) of this section conveying real property or interest therein\nor creating a lien upon the same, shall be approved by the mayor.\n(4) No contract involving the expenditure of two thousand pesos or more shall be entered into or authorized\nuntil the barangay treasurer shall have certified to the sangguniang barangay that funds have been duly\nappropriated for such purpose and the amount necessary to cover the proposed contract is available for\nexpenditure on account thereof. Such certificated shall be attached to the contract as part thereof and the sum\nso certified shall not thereafter be made available for expenditure for any other purpose until the said contract\nis lawfully abrogated or executed at no cost to the barangay."}},{"id":"PH-H15202-A92","no":92,"noLabel":{"en":"Section 92"},"text":{"en":"Review of Barangay Ordinances. -\n(1) Within ten days after its enactment, the sangguniang barangay shall furnish copies of the ordinance to the\nsangguniang panlungsod or sangguniang bayan, as the case may be, which shall have the power to review said\nordinance to determine whether it is consistent with law or city or municipal ordinances.\n(2) If the sangguniang panlungsod or sangguniang bayan, as the case may be, does not take action on the\nordinance within thirty days after its submission, it shall be presumed, consistent with law, and city or\nmunicipal ordinances.\n(3) If within thirty days the sangguniang panlungsod or sangguniang bayan, as the case may be, finds the\nordinance inconsistent with law or city or municipal ordinances, the sanggunian concerned shall return it to\nthe sangguniang barangay for adjustment, amendment, or modification, in which case the effectivity of the\nordinance is suspended.\n(4) In case the sangguniang barangay disagrees with the decision of the sangguniang panlungsod or the\nsangguniang bayan, as the case may be, the dispute shall be referred, in the case of municipalities, to the\nprovincial fiscal, and in the case of cities, to the city fiscal for final action.\n\n(5) The Minister of Finance shall have authority to suspend the effectivity of any tax ordinance within one\nhundred twenty days after its passage, if in his opinion the tax or free therein levied or imposed is unjust,\nexcessive, oppressive, confiscatory or contrary to law. In such event, the sangguniang barangay may contest\nthe decision of the Minister in the appropriate court. Until the decision of the Minister of Finance is set aside\nby final judgment, the effectivity of the tax ordinance shall remain suspended.\n(6) The Minister of Natural Resources shall have authority to suspend the effectivity or ordinances pertaining\nto fishing or fisheries promulgated by the sangguniang barangay within one hundred twenty days after its\npassage, upon due notice to the sanggunian g barangay may contest the decision of the Minister of Natural\nResources in the appropriate court. Until the decision of the Minister of Natural Resources is set aside by final\njudgment, the effectivity of the ordinance shall remain suspended."}},{"id":"PH-H15202-A93","no":93,"noLabel":{"en":"Section 93"},"text":{"en":"Duties of Sangguniang Barangay Members. - In addition to their duties as members of the\nsangguniang barangay, they shall:\n(1) Assist the punong barangay in the discharge of his duties;\n(2) Act as peace officers in the maintenance of public order or as agent of persons in authority in their\nbarangay; and\n(3) Perform such other duties as the Punong Barangay may delegate or as may be provided by law or"}},{"id":"PH-H15202-A94","no":94,"noLabel":{"en":"Section 94"},"text":{"en":"Privileges of Sangguniang Barangay Officials. -\n(1) In addition to their rights and privileges granted by law, the punong barangay, the sangguniang barangay\nmembers, the kabataang barangay chairman, the barangay treasurer and the barangay secretary shall:\n(a) Be entitled to per diems in such amount as may be determined by the sangguniang barangay, in accordance\nwith the rates provided by law, subject to availability of barangay funds after deducting statutory and\nmandatory budgetary expenditures;\n(b) Be entitled, during their incumbency, to insurance coverage, the premiums for which shall be shouldered\nby the national government;\n(c) Be entitled to reimbursement of actual traveling expenses and allowances as may be provided for by law,\nsubject to auditing rules and regulations;\n(d) be entitled to appropriate civil service eligibility on the basis of the number of years of service to the\nbarangay, and for this purpose the civil Service Commission is hereby empowered to issue rules and\nregulations to implement this provision;\n(e) be entitled to free medical care in any government hospital or institution; and\n(f) Be exempted during their incumbency from paying tuition and matriculation fees for a maximum of four of\ntheir legitimate dependent children attending public high schools and for a maximum of two of their\nlegitimate dependent children attending state colleges and universities.\n(2) Elective barangay officials shall have preference in appointments to any government position or in any\ngovernment-owned or controlled corporation after their tenure.\n(3) The surviving spouse or legal heirs of every barangay official who dies during his incumbency shall be\nentitled to burial benefits chargeable against the general fund of the barangay in an amount not less than five\nhundred pesos. In event the barangay funds are insufficient for this purpose, the same shall be chargeable\nagainst the funds of the city or municipality to which the barangay belongs.\nAPPOINTIVE BARANGAY OFFICIALS"}},{"id":"PH-H15202-A95","no":95,"noLabel":{"en":"Section 95"},"text":{"en":"The Barangay Secretary. -\n\n(1) The punong barangay shall appoint the barangay secretary who shall hold office at his pleasure and be\nentitled to a reasonable allowance to be determined by the sangguniang barangay.\n(2) No person shall be appointed barangay secretary if he is a sangguniang barangay member or a relative of\nthe punong barangay within the second civil degree of consanguinity or affinity.\n(a) Keep custody of all records of the sangguniang barangay and the barangay assembly meetings;\n(b) Prepare and keep the minutes of all meetings of the sangguniang barangay and the barangay assembly;\n(c) Prepare separate lists of the members of the barangay and the registered voters of the barangay assembly,\nand have the same posted in conspicuous places within the barangay;\n(d) Register all new members of the barangay;\n(e) Assist in the preparation of all necessary election forms and other forms necessary for the conduct of\nbarangay elections, referenda or plebiscites, in coordination with the Commission on Elections;\n(f) Assist the municipal civil registrar in the registration of births, deaths and marriages;\n(g) Keep a record of all inhabitants of the barangay containing the following items of information: name,\naddress, place and date of birth, sex, citizenship, occupation, and such other items of information as may be\ndeemed necessary; and\n(h) Exercise such other powers and perform such other duties and functions as may be prescribed by law or"}},{"id":"PH-H15202-A96","no":96,"noLabel":{"en":"Section 96"},"text":{"en":"The Barangay Treasurer. -\n(1) The punong barangay shall appoint the barangay treasurer with the concurrence of the sangguniang\nbarangay. He shall be entitled to a reasonable allowance to be determined by said sanggunian.\n(2) He shall be bonded in accordance with existing laws in an amount to be determined by the sangguniang\nbarangay, but not exceeding ten thousand pesos, premiums for which shall be defrayed by the city or\nmunicipality where the barangay belongs.\n(3) No person shall be appointed barangay treasurer if he is a sangguniang barangay member or a relative of\nthe punong barangay within the second civil degree of consanguinity or affinity.\n(a) Keep custody of barangay property and funds not deposited with the city or municipal treasurer;\n(b) Collect and receive taxes, fees, contributions, monies, materials, and all other resources accruing to the\nbarangay treasury and issue official receipts therefor;\n(c) Disburse funds in accordance with the financial procedures provided in this Code;\n(d) Submit to the punong barangay certified and detailed statements of actual receipts for the calendar year\nimmediately preceding for the preparation of the barangay budget within such period as may be provided by\nexisting laws;\n(e) Render a written accounting report after the end of each calendar year of all barangay funds and property\nunder his custody, which report shall be made available under his custody, which report shall be made\navailable to the public or to the members of the assemble and other government agencies concerned;\n(f) Certify to the availability of funds whenever necessary;\n(g) Plan and attend to the rural postal circuit within his own jurisdiction; and\n(h) Exercise such other powers and perform such other duties and functions as may be prescribed by law or"}},{"id":"PH-H15202-A97","no":97,"noLabel":{"en":"Section 97"},"text":{"en":"Other Appointive Officials. - The qualifications, duties and functions of all other barangay\nofficials appointed by the punong barangay shall be governed by the provisions of this code and other laws or\nby ordinance.\nTHE BARANGAY ASSEMBLY"}},{"id":"PH-H15202-A98","no":98,"noLabel":{"en":"Section 98"},"text":{"en":"Composition; Meetings. -\n(1) The barangay assembly shall be composed of all persons who have been actual residents of the barangay\nfor at least six months, fifteen years of age or over, citizens of the Philippines and duly registered in the list of\nbarangay assembly members kept by the barangay secretary.\n(2) The barangay assembly shall meet at least twice a year to hear and discuss the semestral report of the\nsangguniang barangay concerning its activities and finances. its meetings shall be held upon call of the\npunong barangay or at least four members of the sangguniang barangay or upon written petitioner of at least\none-tenth of its members.\n(3) No meeting of the barangay assembly shall take place unless notice is given one week prior to the meeting\nexcept on matters involving public safety or security in which case notice within a reasonable time shall be\nsufficient. The punong barangay, or, in his absence, the sangguniang barangay member acting as punong\nbarangay, or any assembly member selected during the meeting, shall act as presiding officer at all meetings\nof the assembly. The barangay secretary, or, in his absence, any member designated by the presiding officer to\nact secretary, shall discharge the duties of secretary of the barangay assembly.\n(4) For the purpose of conducting business and taking any official action in the barangay assembly, it is\nnecessary that at least one-tenth of its members be present to constitute a quorum. All actions shall require a\nmajority of those present and voting at a meeting, there being a quorum."}},{"id":"PH-H15202-A99","no":99,"noLabel":{"en":"Section 99"},"text":{"en":"Powers of the Barangay Assembly. - The barangay assembly shall:\n(a) Initiate legislative process by recommending to the sangguniang barangay the adoption of measures for the\nwelfare of the barangay;\n(b) Decide on the holding of plebiscite or a referendum in accordance with the next two sections, as well as on\nquestions and issues presented therein; and\n(c) Hear and pass upon the semestral report of the sangguniang barangay concerning its activities and"}},{"id":"PH-H15202-A100","no":100,"noLabel":{"en":"Section 100"},"text":{"en":"Plebiscite. -\n(1) A plebiscite may be held in the barangay when authorized by a majority vote of the members present in a\nbarangay assembly meeting, there being a quorum, or when called by at least our members of the sangguniang\nbarangay. No plebiscite shall be held until after thirty days from its approval by either body, and such has\nbeen given the widest publicity in the barangay, stating the date, time and peace thereof, the questions or\nissues to be decided, action to be taken by the voters, and such other information relevant to the holding of the\nplebiscite.\n(2) All duly registered barangay assembly members qualified to vote may in the plebiscite. Voting procedures\nmay be made either in writing as in a regular election, or by declaration by the voters to the board of election\ntellers duly organized for the purpose by the sangguniang barangay."}},{"id":"PH-H15202-A101","no":101,"noLabel":{"en":"Section 101"},"text":{"en":"Referenda. -\n(1) A referendum may be held on local issues affecting the barangay upon request of at least one-tenth of the\nmembers of the barangay assembly.\n(2) No referendum shall be held until it has been given the widest publicity in the barangay stating the date,\ntime, and place thereof, the questions or issues to be decided, action to be taken by the voters and such\ninformation relevant to the referendum.\n\n(3) All duty registered barangay assembly members qualified to vote may vote in the referendum, either in\nwriting or by declaration by the voters to the board of election tellers duly organized for the purpose by the\nsangguniang barangay.\n(4) The Ministry of Local Government shall supervise the calling of referenda on local issues in the barangay.\nACQUISITION AND DISPOSITION OF BARANGAY FUNDS"}},{"id":"PH-H15202-A102","no":102,"noLabel":{"en":"Section 102"},"text":{"en":"Taxing and Regulatory Powers of Barangays. - The power of the barangay to levy taxes,\nimpose fees and charges, and raise revenues shall be exercised through the sangguniang barangay subject to\nlimitations prescribed by law."}},{"id":"PH-H15202-A103","no":103,"noLabel":{"en":"Section 103"},"text":{"en":"Barangay Funds. -\n(1) Unless otherwise provided in this Code, all the income of the barangay from whatever source shall accrue\nto its general fund and shall be kept as trust fund in the custody of the city or municipal treasurer to be\ndisbursed in accordance with the provisions of this Code. Ten percent of the total general fund of the barangay\nshall be set aside for the kabataang barangay.\n(2) After deducting statutory and contractual obligations forty percent of the remainder of the general fund of\nthe barangay shall be set aside solely for development projects, the plan and corresponding program of work\nof which have been reviewed and approved by the city or municipal development council. Action thereon by\nthe said council shall be made in not more than thirty working days from submission, otherwise the barangay\ndevelopment plan and corresponding program of work thus submitted shall be considered approved.\n(3) Each province, city and municipality shall give an annual contribution in an amount not less than one\nhundred pesos to every barangay within their respective jurisdiction. A local government unit may grant\nadditional contribution to barangays within its jurisdiction through the sangguniang barangay.\n(4) Ten percent of all taxes collected on real property located within the barangay shall be allocated in\naccordance with existing provisions of law. The city or municipal treasurer may designate the barangay\ntreasurer as his deputy to collect said taxes. In case bond is required for the purpose, the city or municipal\ngovernment shall pay the premiums of bonds thereon in addition to the premiums of bonds that may be\nrequired by Section 96, paragraph (2) of this Code."}},{"id":"PH-H15202-A104","no":104,"noLabel":{"en":"Section 104"},"text":{"en":"Barangay Budget. -\n(1) The annual budget of the barangay shall consist of two parts:\n(a) The existing balances and estimate of income certified collectible by the city or municipal treasurer from\nlocal and national sources; and\n(b) The total appropriation covering current operating expenditures and capital outlays, if any.\n(2) For the purpose of subparagraph (a) hereof, the city or municipal treasurer shall issue the required\ncertifications on existing balances and estimates of income within such period as may be prescribed by\nexisting laws."}},{"id":"PH-H15202-A105","no":105,"noLabel":{"en":"Section 105"},"text":{"en":"Budgetary Appropriations. -\n(1) Upon receipt of the foregoing statements from the city or municipal treasurer, the punong barangay shall\nprepare the barangay budget in the manner and within the period prescribed under existing laws. Thereafter,\nthe punong barangay shall submit the annual barangay budget to the sangguniang barangay for legislative\nauthorization and/or enactment of the corresponding appropriation ordinance.\n(2) The annual budgetary appropriations shall not exceed the estimated tax receipts and/or income for the\nensuing calendar year certified as collectible by the city or municipal treasurer concerned. Provisions shall be\nmade for the statutory and current contractual obligations of the barangay official or employee shall receive\nper diems, wages or salaries and other compensation in excess of those provided for under existing laws and\n\nexecutive orders.\n(3) If the sangguniang barangay shall fail to enact the annual barangay budget within the prescribed period\nbefore the beginning of the ensuing calendar year, the annual barangay budget for the preceding calendar year\nshall be deemed reenacted. Changes in the annual barangay budget may be effected by supplemental budgets\nprepared and adopted in the same manner as the former.\n(4) Copies of the barangay budget shall be furnished the city or municipal budget officer within ten days from\nits approval, who shall have the power to review such budget in order to ensure that the above provisions are\ncomplied with. If within sixty days after the receipt of the barangay budget the city or municipal budget\nofficer takes no action thereon, the same shall be deemed to have been passed in accordance with law and\nshall continue to be in full force and effect. If within the same period the city or municipal budget officer\nconcerned shall have ascertained that the barangay budget contains appropriations in excess of the estimates\nof the income duly certified collectible or that the same has not fully provided for statutory or contractual\nobligations of the barangay, the budget shall be declared inoperative in its entirety. Items of appropriation in\nexcess of those provided in laws and executive orders shall be disallowed or reduced accordingly.\n(5) The city or municipal budget officer, within the period hereinabove fixed, shall return the barangay budget\nforthwith to the punong barangay through the barangay treasurer, with the advice of action thereon for proper\nadjustments, in which event the barangay shall operate on the previous year's budget until such time that a\nnew budget shall have met the objections presented. Upon receipt of such advice, it shall be unlawful for the\nbarangay treasurer or the city or municipal treasurer who has custody of the funds to make further\ndisbursement from any other items of appropriation declared inoperative, disallowed or reduced."}},{"id":"PH-H15202-A106","no":106,"noLabel":{"en":"Section 106"},"text":{"en":"Effectivity of the Barangay Budget. - The barangay budget approved by the sangguniang\nbarangay shall be operative and in full force and effect at the beginning of the calendar year. A barangay\nsupplemental budget shall take effect upon its approval or on the date fixed in the appropriation ordinance for\nits effectivity."}},{"id":"PH-H15202-A107","no":107,"noLabel":{"en":"Section 107"},"text":{"en":"Financial Procedures. -\n(1) The barangay treasurer shall collect all taxes due or unpaid including real property taxes, fees and other\ncharges and contributions accruing to the barangay treasury for which he shall issue official receipts and shall\ndeposit all collections with the city or municipal treasury within a period of one week after receipt thereof:\nProvided, That he collects the real property tax due in his own barangay after being deputized by the treasurer\nconcerned for the purpose. He shall disburse the same in accordance with the budget and upon resolution of\nthe sangguniang barangay, upon vouchers signed by the payee and approved by the punong barangay, and\nsubject to the availability of funds in the barangay treasury and to all existing and applicable auditing rules\nand regulations.\nAll other funds collected for a specific purposes shall be considered as special trust fund and may be deposited\nin the name of the barangay with the nearest depository bank in the area.\n(2) The barangay treasurer may be authorized by the sangguniang barangay to make direct purchases\namounting to not more than three hundred pesos at any time for the ordinary and essential needs of the\nbarangay. The petty cash that the barangay treasurer may be authorized to hold for the purpose shall not\nexceed twenty percent of the funds available and to the credit of the barangay treasury.\n(3) The financial records of the barangay shall be kept in the office of the city or municipal treasurer in\nsimplified manner as prescribed by the Commission on Audit Representatives of the Commission on Audit\nshall annually audit such accounts or as often as may be necessary and make a report of the audit to the\nsangguniang barangay and to the sangguniang bayan or sangguniang panlungsod, as the case may be. The\nCommission on Audit shall prescribe and put into effect simplified procedures for barangay finances within a\nreasonable time following the effectivity of this Code.\n\nKATIPUNAN NG MGA BARANGAY"}},{"id":"PH-H15202-A108","no":108,"noLabel":{"en":"Section 108"},"text":{"en":"The Katipunan ng mga Barangay. - There shall be an organization of all sangguniang\nbarangays to be known as follows: in municipalities, katipunang bayan; in cities, katipunang panlungsod; in\nprovinces, katipunang panlalawigan; in regions, katipunang pampook; and on the national level, katipunan ng\nmga barangay."}},{"id":"PH-H15202-A109","no":109,"noLabel":{"en":"Section 109"},"text":{"en":"Representation. - Every barangay shall be represented by the punong barangay, or in his\nabsence or incapacity, by his duly designated sangguniang barangay member, in all meetings and/or\ndeliberations called by the katipunang panlungsod or the katipunang bayan. Should the punong barangay fail\nto designate any representative to the katipunang panlungsod or the katipunang bayan, as the case may be, the\nsangguniang barangay member who obtained the highest number of votes in the election immediately\npreceding shall represent the barangay. In cases where the punong barangay, the designee, or the sangguniang\nbarangay member concerned is incapacitated, the sangguniang barangay shall elect from among its members\nthe representative of the barangay to the katipunan concerned."}},{"id":"PH-H15202-A110","no":110,"noLabel":{"en":"Section 110"},"text":{"en":"Organization. -\n(1) The katipunan at all levels shall be organized in the following manner:\n(a) The katipunan in each level shall elect a board of directors and a set of officers. The president of each level\nshall represent the katipunan concerned in the next higher level of organization.\n(b) The katipunan ng mga barangay shall be composed of the presidents of the katipunang pampook, which\nshall in turn composed of the presidents of the katipunang panlalawigan and the katipunang panlungsod. The\npresidents of the katipunang bayan in each province shall constitute the katipunang panlalawigan. The\nkatipunang panlungsod and the katipunang bayan shall be composed of the punong barangays of cities and\nmunicipalities, respectively.\n(2) A secretary general shall be chosen from among the members of the katipunan ng mga barangay, who\nshall be charged with the maintenance of the organization in the absence of the duly elected officials or upon\nthe dissolution of the organization.\n(3) The term of office of all officers of the katipunan in all levels shall be in accordance with the by-laws of\nthe organization, without prejudice, however, to their term of office as member of the sanggunian to which\nthey may be correspondingly appointed."}},{"id":"PH-H15202-A111","no":111,"noLabel":{"en":"Section 111"},"text":{"en":"Functions and Duties of Katipunan ng mga Barangay. - The katipunan ng mga barangay shall:\n(a) Adopt measures for the promotion of the welfare of the barangay officials;\n(b) Give priority to programs designed for the total development of the barangays, consistent with the policies,\nprograms and projects of the national government;\n(c) Assist in the education of barangay residents for the development of good citizenship, cooperation and\nunity, in order to promote a united and concerned action for the achievement of the country's development\n(d) Supplement the efforts of government in pointing out opportunities and creating an atmosphere conducive\nto gainful employment within the barangay;\n(e) Serve as a forum of barangay officials in seeking the necessary assistance of government and private\nentities for the common welfare of all barangays; and\n(f) Promote, assist and serve all the sangguniang barangays."}},{"id":"PH-H15202-A112","no":112,"noLabel":{"en":"Section 112"},"text":{"en":"Meetings. - The katipunan in each level shall meet on the dates and for as often as it may\ndetermine in its rules of procedure. The meetings shall not be in conflict with other meetings of the different\nkatipunans in each level. Their meetings shall be held in a place accessible to the public and equipped with the\nproper appurtenances for the conduct of the meetings."}},{"id":"PH-H15202-A113","no":113,"noLabel":{"en":"Section 113"},"text":{"en":"Funding of the Katipunan. -\n(1) The katipunan in all levels shall derive all its funds from fund raising campaigns or programs in the\npursuance of specific projects for the upliftment of the sangguniang barangays, without the necessity of\nsecuring permits therefor, subject, however, to the pertinent provisions of the Election Code.\n(2) All funds of the katipunan in all levels of organization shall be deposited as trust funds with their\nrespective municipal, city, provincial, regional or national katipunan treasurers, and be disbursed in\naccordance with approved resolutions by the katipunan concerned, subject to auditing rules and regulations.\nKATARUNGANG PAMBARANGAY"}},{"id":"PH-H15202-A114","no":114,"noLabel":{"en":"Section 114"},"text":{"en":"Amicable Settlement of Disputes on the Barangay Level. - There shall be a system of\namicable settlement of disputes on the barangay level which shall be governed by law.\nTHE KABATAANG BARANGAY"}},{"id":"PH-H15202-A115","no":115,"noLabel":{"en":"Section 115"},"text":{"en":"Creation. - There shall be in ever barangay a youth organization to be known as the kabataang"}},{"id":"PH-H15202-A116","no":116,"noLabel":{"en":"Section 116"},"text":{"en":"Composition and Membership. - (1) All Filipino citizens who are at least fifteen years but not\nmore than twenty-one years of age shall be members of the kabataang barangay.\n(2) A kabataang barangay official who during his term of office shall have passed the age of twenty-one shall\nretain his membership and continue to exercise his powers and perform his duties and enjoy all the rights and\nprivileges appurtenant to his office during such term."}},{"id":"PH-H15202-A117","no":117,"noLabel":{"en":"Section 117"},"text":{"en":"The Kabataang Barangay Assembly. - The kabataang barangay assembly shall be composed\nof all Filipino citizens actually residing in the barangay for at least six months, who are fifteen but not more\nthan twenty-one years of age, and who are duly registered in the list of the kabataang barangay assembly or in\nthe official barangay list in the custody of the barangay secretary."}},{"id":"PH-H15202-A118","no":118,"noLabel":{"en":"Section 118"},"text":{"en":"Meetings of the Kabataang Barangay Assembly. - The kabataang barangay assembly shall\nmeet at the call of the kabataang barangay chairman or upon written petition of at least one-tenth of its\nmembers to decide important issues affecting the youth of the barangay."}},{"id":"PH-H15202-A119","no":119,"noLabel":{"en":"Section 119"},"text":{"en":"The Kabataang Barangay Council. - There shall be in every barangay a kabataang barangay\ncouncil to be composed of a chairman, six councilors elected by the registered voters of the kabataang\nbarangay assembly in accordance with law, a secretary and a treasurer."}},{"id":"PH-H15202-A120","no":120,"noLabel":{"en":"Section 120"},"text":{"en":"Powers and Functions of the Council. - The kabataang barangay council shall have the\nfollowing powers and functions:\n(a) Promulgate resolutions necessary to carry out the objectives of the kabataang barangay in accordance with\napplicable provisions of this Code;\n(b) Initiate programs designed to enhance the social, political, economic, cultural, intellectual, moral spiritual\nand physical development of the kabataang barangay members;\n(c) Hold fund raising activities for kabataang barangay purposes, the proceeds of which shall be tax exempt\nand shall accrue to the general fund of the kabataang barangay: Provided, however, That in the appropriation\nthereof, the specific purpose for which such activity has been held shall be first satisfied;\n(d) Appropriate and administer its own funds, subject to existing and applicable auditing rules and regulations;\n(e) Create such bodies or committees as it may deem necessary to effectivity carry out kabataang barangay\nprograms and activities;\n(f) Perform such other functions and exercise such other powers as the sangguniang barangay may determine\n\nor delegate; and\n(g) Exercise such other powers and perform such other duties and functions as may be prescribed by law or"}},{"id":"PH-H15202-A121","no":121,"noLabel":{"en":"Section 121"},"text":{"en":"Meetings of the Council. - The kabataang barangay council shall meet regularly twice a month\non the date, time and place to be fixed by the said council. Special meetings may be called by the kabataang\nbarangay chairman or any three of its members by giving written notice to all members of the date, time and\nplace and agenda of the meeting at least one day in advance. Notices of regular or special meetings shall be\nfurnished the punong barangay and the sangguniang barangay.\nA majority of the members of the kabataang barangay council shall constitute a quorum to do business."}},{"id":"PH-H15202-A122","no":122,"noLabel":{"en":"Section 122"},"text":{"en":"Qualifications. - An elective official of the kabataang barangay council must, on the day of\nelection, be a Filipino citizen, a qualified voter of the kabataang barangay assembly, a resident of the barangay\nfor at least six months immediately prior to election, be enable to read and write Pilipino, English or the local\ndialect, must be at least fifteen years but not more than twenty-one years of age, and must not have been found\nguilty of any crime involving moral turpitude."}},{"id":"PH-H15202-A123","no":123,"noLabel":{"en":"Section 123"},"text":{"en":"Term of Office. - The kabataang barangay chairman and members of the kabataang barangay\ncouncil shall hold office for a period of three years unless sooner removed for cause as provided by law,\npermanently incapacitated, dies, or resigns from office."}},{"id":"PH-H15202-A124","no":124,"noLabel":{"en":"Section 124"},"text":{"en":"The Kabataang Barangay Chairman. - The registered voters of the kabataang barangay\nassembly shall elect a kabataang barangay chairman who shall automatically become an ex officio member of\nthe sangguniang barangay upon his assumption of office. As such, he shall exercise the same powers,\ndischarge the same duties and functions, and enjoy the same privileges as the regular sangguniang barangay\nmembers, and shall be the chairman of the committee on youth and sports development."}},{"id":"PH-H15202-A125","no":125,"noLabel":{"en":"Section 125"},"text":{"en":"Powers and Duties of the Kabataang Barangay Chairman. - Aside from the duties which may\nbe assigned to him by the sangguniang barangay, the kabataang barangay chairman shall:\n(a) Call and preside over all meetings of the kabataang barangay assembly and the kabataang barangay\n(b) Implement kabataang barangay policies, programs and projects within his jurisdiction in coordination with\nthe sangguniang barangay;\n(c) Exercise general supervision over the affairs and activities of the kabataang barangay and the official\nconduct of members of the kabataang barangay council and such other officers of the kabataang barangay\nwithin his jurisdiction;\n(d) Appoint from among the members of the kabataang barangay council, the secretary and treasurer, and such\nother officers as may be deemed necessary; and\n(e) Exercise such other powers and perform such other duties and functions as may be prescribed by law or"}},{"id":"PH-H15202-A126","no":126,"noLabel":{"en":"Section 126"},"text":{"en":"The Kabataang Barangay Secretary. - The kabataang barangay secretary shall:\n(a) Be the custodian of all records of the kabataang barangay assembly and council;\n(b) Prepare and keep the minutes of all meetings of the kabataang barangay assembly and council;\n(c) Prepare all forms necessary for the conduct of kabataang barangay registration, elections, referenda or\nplebiscites, in coordination with the barangay secretary and the Commission on Elections; and\n(d) Discharge such other duties as the kabataang barangay chairman and council may prescribe or direct."}},{"id":"PH-H15202-A127","no":127,"noLabel":{"en":"Section 127"},"text":{"en":"The Kabataang Barangay Treasurer. - The kabataang barangay treasurer shall:\n(a) Take custody of all kabataang barangay property and funds;\n\n(b) Collect and receive contributions, monies, materials and all other resources intended exclusively for the\nkabataang barangay;\n(c) Disburse funds in accordance with an approved budget of the kabataang barangay council;\n(d) Certify to the availability of funds whenever necessary;\n(e) Submit to the kabataang barangay council certified and detailed statements of actual receipts and\nexpenditures every end of the month, and to the sangguniang barangay every six months;\n(f) Render an accounting of funds and property under his custody and trust to the kabataang barangay council\nand the sangguniang barangay within one month before the termination of his term, unless sooner removed,\nresigned or suspended, in which case the accounting shall be made immediately before such removal,\nresignation or suspension; and\n(g) Perform such other duties and discharge such other functions as the kabataang barangay chairman or\ncouncil may direct."}},{"id":"PH-H15202-A128","no":128,"noLabel":{"en":"Section 128"},"text":{"en":"Privileges of Kabataang Barangay Council Officials. - The kabataang barangay chairman shall\nhave the same privileges enjoyed by other sangguniang barangay officials under this Code subject to such\nrequirements and limitations herein provided. Other kabataang barangay council officials shall enjoy\nexemption from tuition and matriculation fees for attending public secondary schools during their\nincumbency."}},{"id":"PH-H15202-A129","no":129,"noLabel":{"en":"Section 129"},"text":{"en":"Succession and Filling of Vacancies. -\n(1) In case a kabataang barangay chairman refuses to assume office, fails to qualify, is convicted of a felony,\nvoluntarily resigns, dies, is permanently incapacitated, is removed from office, or has been absent without\nauthorization for more than three consecutive months, the kabataang barangay council member who obtained\nthe highest number of votes in the election immediately preceding shall assume the position of kabataang\nbarangay chairman for the unexpired portion of the term, and shall discharge the powers and duties, and enjoy\nthe rights and privileges appurtenant to the office.\nIn case the kabataang barangay council member concerned refuses to assume the position or fails to qualify,\nthe council member obtaining the next highest number of votes shall assume the position of kabataang\nbarangay chairman for the unexpired portion of the term.\n(2) In case two or more councilors obtain identical highest number of votes, the kabataang barangay council,\nby a majority vote of all its member, shall elect the successor.\n(3) After the vacancy shall have been filed, the kabataang barangay chairman shall, with the approval of the\nkabataang barangay council, appoint any member of the kabataang barangay assembly of good standing, or\nupon resolution of the kabataang barangay council, call a special election to complete the membership of the\nsaid council. Such appointed or elected kabataang barangay councilor shall hold office for the unexpired\nportion of the term of the vacant seat.\n(4) In case of suspension of the kabataang barangay chairman, the successor, as determined in paragraphs (1)\nand (2) of this section, shall assume the position during the period of such suspension.\nTHE KABATAANG BARANGAY FEDERATION"}},{"id":"PH-H15202-A130","no":130,"noLabel":{"en":"Section 130"},"text":{"en":"The Kabataang Barangay Federation. -\n(1) There shall be an organization of all the kabataang barangay organizations to be known as follows: in\nmunicipalities, kabataang barangay municipal federation; in cities, kabataang barangay city federation; in\nregions, kabataang barangay regional federation; and on the national level, kabataang barangay national\n(2) The kabataang barangay federation shall at all levels be organized in the following manner:\n\n(a) The kabataang barangay federation in municipalities and cities shall consist of the kabataang barangay\nchairmen, who shall elect from among themselves the kabataang barangay municipal or city federation\npresident and such other officers as may be necessary.\n(b) The kabataang barangay provincial federation shall be composed of the kabataang barangay municipal and\ncity federation presidents who shall elect from among themselves a set of officers. The elected president shall\nrepresent the kabataang barangay provincial federation to the regional federation.\n(c) The kabataang barangay regional federation shall elect from among themselves a set of officers.\n(d) The kabataang barangay national council shall remain as presently constituted and shall elect its own set of\nofficers, unless otherwise provided by law."}},{"id":"PH-H15202-A131","no":131,"noLabel":{"en":"Section 131"},"text":{"en":"Term, Election, Removal and Suspension in the Kabataang Barangay Federation. - The term\nof office, manner of election, removal and suspension of the officers of the kabataang barangay federation at\nall levels shall be governed by the by-laws of the organization as may be adopted and promulgated by the\nkabataang barangay national council."}},{"id":"PH-H15202-A132","no":132,"noLabel":{"en":"Section 132"},"text":{"en":"Membership in Sanggunians. -\n(1) Upon his appointment by the President of the Philippines and during his tenure of office, the kabataang\nbarangay provincial, city or municipal federation president shall be a member of the provincial, city or\nmunicipal sanggunian, as the case may be.\n(2) As member of the sanggunian, the kabataang barangay provincial, city of municipal federation president\nshall automatically become the chairman of the committee on youth and sports development in said\nsanggunian.\nTHE MUNICIPALITY\nROLE AND CREATION OF MUNICIPALITIES"}},{"id":"PH-H15202-A133","no":133,"noLabel":{"en":"Section 133"},"text":{"en":"Role of Municipalities. - The municipality, consisting of a group of barangays, serves\nprimarily as a general-purpose government for the coordination and delivery of basic, regular and direct\nservices within its jurisdiction."}},{"id":"PH-H15202-A134","no":134,"noLabel":{"en":"Section 134"},"text":{"en":"Manner of Creation. - A municipality may be created, named and its boundaries defined,\naltered or modified only by an Act of the Batasang Pambansa, subject to the approval by a majority of the\nvotes cast in a plebiscite to be held in the unit or units affected. Except as may otherwise be provided in said\nAct, the plebiscite shall be conducted by the Commission on Elections within one hundred twenty days from\nthe date of its effectivity."}},{"id":"PH-H15202-A135","no":135,"noLabel":{"en":"Section 135"},"text":{"en":"Requisites for Creation. -\n(1) A municipality may be created out of a contiguous territory which has a population of at least ten\nthousand, as certified by the National Census and Statistics Office, and has an average estimated annual\nincome, as certified by the provincial treasurer, of at least two hundred thousand pesos for the last three\nconsecutive years, and the creation thereof shall not reduce the population and income of the mother\nmunicipality or municipalities at the time of said creation to less than the minimum requirements under this\nsection. The territory need not be contiguous if it comprises two or more islands.\n(2) The average estimated annual income shall include the income allotted for both the general fund and the\ninfrastructure funds, exclusive of trust funds, transfers and nonrecurring income.\n(3) The territorial jurisdiction of a new municipality shall be properly identified by metes and bounds or by\nnatural boundaries."}},{"id":"PH-H15202-A136","no":136,"noLabel":{"en":"Section 136"},"text":{"en":"Existing Municipal Districts. - The requirements of the immediately preceding section\n\nnotwithstanding, all existing municipal districts are hereby converted into municipalities.\nMUNICIPAL OFFICIALS IN GENERAL"}},{"id":"PH-H15202-A137","no":137,"noLabel":{"en":"Section 137"},"text":{"en":"Officials of the Municipal Government. -\n(1) There shall be in each municipality a mayor, a vice-mayor, sangguniang bayan members, a municipal\nsecretary, a municipal treasurer, a municipal assessor, a municipal budget officer, and a municipal planning\nand development coordinator.\n(2) Under the office of the municipal planning and development coordinator, a division, section or officer may\nbe provided for civil registration and general services whenever appropriate.\n(3) The sangguniang bayan may maintain existing offices not mentioned in paragraph (1) of this section or\ncreate such other offices as may be necessary to carry out the purposes of the municipal government, or may\nconsolidate the functions of any one such offices with those of another in the interest of efficiency and\n(4) The Minister of Local Government shall prescribe minimum standards and guidelines with respect to the\norganizational structures, staffing pattern and other relevant operational aspects of the governance of\nmunicipalities."}},{"id":"PH-H15202-A138","no":138,"noLabel":{"en":"Section 138"},"text":{"en":"Qualifications of Appointive Municipal Officials. - An appointive municipal official must be a\ncitizen of the Philippines, and must possess the minimum requirements and qualifications prescribed by this\nCode and other laws."}},{"id":"PH-H15202-A139","no":139,"noLabel":{"en":"Section 139"},"text":{"en":"Permission to Leave Official Station. - No municipal official engaged in the discharge of\nofficial duties shall leave the municipality without written permission from the mayor. National officials\nassigned in the municipality, when called upon by the heads of their respective ministries or when they are to\nleave their official stations on official business shall give prior written notice to the mayor."}},{"id":"PH-H15202-A140","no":140,"noLabel":{"en":"Section 140"},"text":{"en":"Custody of Oath of Office or Affirmation. - The oath of office or affirmations of the municipal\nheads of offices, upon being subscribed by them, shall be filed and preserved in the office of the municipal\nOFFICIALS AND OFFICES COMMON TO ALL MUNICIPALITIES\nARTICLE ONE\nTHE MUNICIPAL MAYOR"}},{"id":"PH-H15202-A141","no":141,"noLabel":{"en":"Section 141"},"text":{"en":"Powers and Duties. -\n(1) The mayor shall be the chief executive of the municipal government and shall exercise is such powers,\nduties and functions as provided in this Code and other laws.\n(a) Exercise control and supervision over all local administrative affairs in the municipality;\n(b) Subject to the provisions of the civil service law, rules and regulations, appoint all officers and employees\nof the municipal government, except those which are specifically provided in this Code;\n(c) Represent the municipality in its business transactions and sign in its behalf all contracts, obligations and\nofficial documents made in accordance with law or ordinance;\n(d) Coordinate the implementation of technical services rendered by national offices, including public works\nand road-and-bridge programs in the community;\n(e) Preside over the meetings of the sangguniang bayan with the right to vote only to break a tie;\n\n(f) Require all executive and administrative officers, agents and employees of the municipal, provincial and\nnational offices stationed therein, to make officially available to him such books, records and other papers in\ntheir custody, not otherwise classified by law as confidential, to facilitate the exercise of his executive power;\n(h) Call a meeting of any or all the municipal officials at such place and time as he may designate;\n(i) Direct the formulation of municipal development plans and programs, and once approved by the\nsangguniang bayan, supervise and direct the execution and implementation thereof;\n(j) Call upon any national official or employee stationed in the municipality to coordinate in the formulation\nand implementation of plans, programs and projects, and seek his advice and recommendation on matters\naffecting the municipality;\n(k) Grant licenses and permits in accordance with existing laws or municipal ordinances and revoke them for\nevaluation of the conditions upon which they have been granted;\n(l) Maintain peace and order in the municipality, and in pursuance thereof, he shall be entitled to possess and\ncarry the necessary firearms within his territorial jurisdiction, subject to existing rules and regulations on the\npossession and carrying of firearms;\n(m) At least ten and one-half months before the beginning of each calendar year, require each head of office to\nprepare and submit to him through the municipal budget officers, an estimate of the appropriation for the\noperation of each office during the ensuing calendar year, which estimate shall be prepared on the basis of\nprograms, projects, activities and workloads, and such estimates of appropriation, after evaluation, shall form\npart of the budget of the municipality;\n(n) Submit to the sangguniang bayan the annual budget of the municipality for the ensuing calendar year on or\nbefore the time fixed in local budgeting regulations of the Office of Budget and Management;\n(o) Enforce laws, municipal ordinances and resolutions and issue necessary orders for their faithful and proper\nenforcement and execution;\n(p) Ensure that all taxes and other revenues of the municipality are collected, and that municipal funds are\nspent in accordance with law, ordinances and regulations;\n(q) Adopt measures to safeguard all the lands, buildings, records, monies, credits, and other property rights of\nthe municipality;\n(r) Make known to the people of the municipality, by proclamation or communication delivered to the\nbarangays, all general laws or governmental orders affecting them;\n(s) Cause to be instituted administrative or judicial proceedings against any officer or employee of the\nmunicipality who may have committed any offense in the performance of his official duties;\n(t) Cause to be instituted judicial proceedings in connection with the violation of ordinances, for the collection\nof taxes, fees and charges, and for the recovery of property and funds of the municipality, and otherwise to\nprotect the interest of the municipality;\n(u) When the public interest so requires, call upon the Philippine Constabulary in the province to suppress\ndisorder, riot lawless violence, rebellious or seditious conspiracy or to apprehend violator of law;\n(v) Give such information and recommend such measures to the sangguniang bayan as he shall deem\nadvantageous to the municipality;\n(w) Allocate and assign rooms to municipal and other public officials who, by law or ordinance, are entitled to\noffice space in the municipal building;\n(x) Take appropriate action on vacation, sick and maternity leaves of officers and employees appointed by him\nand authorize the commutation of the money value thereof when proper;\n(y) Authorize trips outside the municipality of officers and employees appointed by him;\n\n(z) Approve the commutation of the transportation and representation allowances of chiefs of offices of the\nmunicipality as authorized by law;\n(aa) Furnish copies of executive orders issued by him to the provincial governor within seventy-two hours\nafter their issuance; and\n(bb) Perform such other duties and exercises such other powers as may be prescribed by law or ordinance."}},{"id":"PH-H15202-A142","no":142,"noLabel":{"en":"Section 142"},"text":{"en":"Execution of Deeds and Contracts. - When the government of a municipality is party to a deed\nor an instrument which conveys title to real property or any interest therein or which creates a lien upon it the\ndeed or instrument shall be executed on behalf of the municipal government by the mayor, upon resolution of\nthe sangguniang bayan and subject to review by the sangguniang panlalawigan."}},{"id":"PH-H15202-A143","no":143,"noLabel":{"en":"Section 143"},"text":{"en":"Authority of the Mayor to Conduct Preliminary Examination. -\n(1) In case of temporary absence of the judge assigned to the municipality, the mayor may conduct the\npreliminary examination in criminal cases, when, in his opinion the investigation cannot be delayed without\nprejudice to the interest of justice.\n(2) No examination shall be conducted unless the parties are assisted by lawyers.\n(3) In cases where he may conduct preliminary examination, the mayor shall, upon probable cause after\nexamination of witnesses, have authority to order the arrest of the accused and to grant him bail in the manner\nand cases provided in the Revised Rules of Court and order his provisional release.\n(4) The mayor shall make a report of any preliminary examination so made immediately after the return of the\njudge assigned in the area, or upon the designation of his replacement.\n(5) The judge assigned in the area may review, revise, alter or revoke the action taken by the municipal"}},{"id":"PH-H15202-A144","no":144,"noLabel":{"en":"Section 144"},"text":{"en":"Annual Report of the Municipal Government. - The mayor of each municipality shall prepare\nan annual report on the conditions prevailing in and of such matters concerning his municipality. The report\nshall be submitted to the sangguniang bayan and a copy shall be forwarded to the office of the provincial\nARTICLE TWO\nTHE VICE-MAYOR"}},{"id":"PH-H15202-A145","no":145,"noLabel":{"en":"Section 145"},"text":{"en":"Functions. -\n(1) The vice-mayor shall be an ex officio member of the sangguniang bayan with all the rights and duties of\nany other member.\n(a) Assume the office of the mayor in any of the cases provided for in Section 48, paragraph (1) of this Code;\n(b) Exercise the powers and perform the duties and functions of the mayor in the case provided for in Section\n52 of this Code;\n(c) Act as temporary presiding officer of the sangguniang bayan in the event of disability of the mayor to\npreside over a regular or special session on account of a trip on official business, absence on leave, sickness or\nany temporary incapacity; and\n(d) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE THREE\nTHE SANGGUNIANG BAYAN"}},{"id":"PH-H15202-A146","no":146,"noLabel":{"en":"Section 146"},"text":{"en":"Composition. -\n(1) The sangguniang bayan shall be the legislative body of the municipality and shall be composed of the\n\nmunicipal mayor, who shall be the presiding officer, the vice-mayor, who shall be the presiding officer pro\ntempore, eight members elected at large, and the members appointed by the President consisting of the\npresident of the katipunang bayan and the president of the kabataang barangay municipal federation.\n(2) In addition thereto, there shall be one representative each from the agricultural and industrial labor sectors\nwho shall be appointed by the President of the Philippines whenever, as determined by the sangguniang\nbayan, said sectors are of sufficient number in the municipality to warrant representation, after consultation\nwith associations and persons belonging to the sector concerned."}},{"id":"PH-H15202-A147","no":147,"noLabel":{"en":"Section 147"},"text":{"en":"Sessions. -\n(1) The sangguniang bayan shall hold at least two regular sessions a month on the days which shall be fixed\nby resolution. Special sessions may be called by the mayor or a majority of the members of the sangguniang\nbayan as often as necessary. No two sessions shall be held in one day.\n(2) In the event of inability of the vice-mayor to act as temporary presiding officer on account of a trip on\nofficial business, absence on leave, sickness, or any temporary incapacity, the members constituting a quorum\nshall choose from among themselves the temporary presiding officer.\n(3) The temporary presiding officer shall not vote even in case of tie but he shall certify within ten days to all\nordinances and resolutions enacted or adopted. If within said period the ordinances and resolutions were not\nsigned by the temporary presiding officer, said ordinances and resolutions shall be deemed to have been\nsigned and the municipal secretary shall forward them to the mayor for such action as may be authorized by\n(4) The sangguniang bayan shall adopt its own rules of procedure, keep a record of its proceedings and for\ndisorderly conduct during sessions, with the concurrence of two-thirds of all its members, reprimand, exclude\nfrom the session, or suspend for not more than sixty days an erring member.\n(5) The sessions of the sangguniang bayan shall be open to the public unless otherwise ordered by an\naffirmative vote of a majority of the members present, there being a quorum."}},{"id":"PH-H15202-A148","no":148,"noLabel":{"en":"Section 148"},"text":{"en":"Quorum. - A majority of all the members of the sangguniang bayan shall constitute a quorum\nfor the transaction of business. A smaller number may adjourn from day to day but may compel the immediate\nattendance of any member absent without good cause by issuing to the Integrated National Police assigned in\nthe area an order for his arrest and production at the session, or impose a fine upon him in such amount as\nshall have been previously prescribed by ordinance."}},{"id":"PH-H15202-A149","no":149,"noLabel":{"en":"Section 149"},"text":{"en":"Powers and Duties. -\n(1) The sangguniang bayan shall:\n(a) Enact such ordinances and issue such regulations as may be necessary to carry out and discharge the\nresponsibilities conferred upon it by law, and such as shall be necessary and proper to provide for the health,\nsafety, comfort and convenience, maintain peace and order, improve public morals, promote the prosperity\nand general welfare of the municipality and the inhabitants thereof, and insure the protection of property\n(b) Prescribe reasonable limits and restraints on the use of property;\n(c) For violation of municipal ordinances, provide for the imposition of a fine not exceeding one thousand\npesos or six months imprisonment, or both fine and imprisonment at the discretion of the court;\n(d) Levy taxes for general and specific purposes and fix the rates in accordance with the provisions of this\nCode and other laws;\n(e) Impose and fix reasonable fees and charges for all services rendered by the municipality to private parties;\n(f) Provide for the establishment and maintenance of public markets, ferries, wharves, abattoirs or\nslaughterhouses, pounds and cemeteries;\n\n(g) Upon the majority vote of all the members, authorize the municipal mayor to negotiate and contract loans\nand other forms of indebtedness subject to existing laws and regulations;\n(h) Grant the exclusive privilege of constructing fish corrals, or taking or catching fish or fry of any species\nfor propagation within any definite portion or area of the municipal waters, in accordance with law;\n(i) Grant loans or aids to other local government units or to national, provincial and municipal institutions of a\ncharitable, benevolent or educational character: Provided, that said funds for aids shall only be granted to\ninstitutions if they are operated and maintained within the municipality;\n(j) Upon recommendation of the municipal mayor, appropriate money for the promotion of the general\nwelfare of the municipality and its inhabitants;\n(k) Fix in accordance with law the number and rates of salaries of officials and employees of the municipality\npaid from municipal funds and provide for such expenditures as are necessary for the proper conduct of the\nactivities of the municipal government;\n(l) Provide funds for the construction and maintenance or rental of buildings for the use of the municipality;\n(m) Upon the majority vote of all the members, authorize the municipal mayor to lease to private parties\nmunicipal public buildings held in a proprietary capacity, subject to existing laws, rules and regulations;\n(n) Provide names of streets and buildings owned by the municipality and, for justifiable reasons, change not\nmore often than once every ten years, the names of streets and public buildings located within the boundaries\nof the municipality, and regulate the numbering of houses and buildings;\n(o) Provide for the maintenance of a waterworks system or district for supplying water to its inhabitants and\nfor the purification of the source of supply and places through which the same passes; regulate the\nconsumption and use of water and fix and collect charges therefor; provide for the construction, repair and use\nof hydrants, pumps, cisterns and reservoirs;\n(p) Review all ordinances approved by the sangguniang barangay to determine whether they are in conformity\nwith law or municipal ordinances;\n(q) Upon recommendation of the mayor, and in accordance with the provisions of this Code and other laws,\ncreate, consolidate, and reorganize municipal offices when deemed necessary in the interest of efficiency and\n(r) Regulate any business subject to municipal license tax or fees and prescribe the conditions under which a\nmunicipal license may be revoked;\n(s) Charge a reasonable fee upon any person engaged in any business or occupation in the municipality before\nissuing a municipal permit therefor, and provide conditions upon which the business or occupation may be\n(t) Regulate and fix the license fees for signs, signboards, and billboards displayed or maintained in any place\nexposed to public view, except those displayed at the place or places where the profession or business\nadvertised thereby is in whole or in part conducted;\n(u) Upon the majority vote of all the members, grant franchises to any person or corporation to do business\nwithin the municipality, to establish, construct, operate and maintain a ferry, wharf, market or slaughterhouse,\nor undertake such other activities as may be allowed by existing laws;\n(v) Regulate the inspection, weighing and measuring of articles of commerce;\n(w) Authorize the payment of compensation or additional compensation, as the case may be, to any officer or\nemployee, or to a person not in government service to temporarily fill a vacancy at a rate equal to that actually\nreceived by the regular incumbent;\n(x) Adopt zoning and subdivision ordinances or regulations, subject to the provisions of existing laws;\n\n(y) Provide for the care of the poor, the aged, the sick, or persons of unsound mind, delinquent and abandoned\nminors, as well as adult offenders and other disabled or handicapped persons;\n(z) Provide for the construction, improvement, repair and maintenance of municipal streets, avenues, alleys,\nsidewalks, bridges, parks and other public places, and regulate the use thereof, and prohibit the construction or\nplacing of obstacles or encroachments on them;\n(aa) Provide for the lighting, cleaning and sprinkling of streets and public places, prohibit littering thereon,\nand provide for the collection and disposal of garbage;\n(bb) Regulate the drilling and excavation of the ground for the laying of gas, water, sewer, and other pipes; the\nbuilding and repair of tunnels, sewers, drains and other similar structures; erecting of poles and the use of\ncrosswalks, curbs and gutters therein, and adopt measures to ensure public safety against open canals,\nmanholes, live wires and other similar hazards to life and property, and provide just compensation or relief for\npersons suffering from them;\n(cc) Provide for the establishment, maintenance, and regulation of the use of public drains, sewers and public\n(dd) Regulate the selling, giving away or dispensing of intoxicating malt, vinous, mixed or fermented liquors\nat retail outlets;\n(ee) Provide for the abatement of nuisance;\n(ff) Penalize habitual drunkenness in public places, vagrancy, mendicancy, prostitution, the establishment and\nmaintenance of houses of ill repute, gambling, and all fraudulent devices for the purpose of obtaining money\nor property, or the printing, circulation, exhibition or sale of obscene articles, pictures, books or publications;\n(gg) Provide for the suppression of riots, vandalism, tumultuous affrays, disturbances and disorderly\nassemblies;\n(hh) Provide for the impounding of stray animals;\n(ii) Adopt measures to prevent and penalize cruelty to animals;\n(jj) Adopt measures and regulations to protect the public from fires, floods, conflagration, typhoons, droughts,\nearthquakes, and other public calamities, and provide relief for persons suffering from them;\n(kk) Require owners, administrators, or tenants of buildings and premises to keep and maintain them in a\nsanitary condition and, should they fail to do so, cause them to be cleared and kept in a sanitary condition and\nthe cost thereof to be assessed against the owner, administrator or tenant, as the case may be, which cost shall\nconstitute a lien against the property;\n(ll) Provide for the regulation and inspection of meat, fruits, poultry, milk, fish, vegetables and other\nfoodstuffs for public consumption;\n(mm) Adopt quarantine regulations as are desirable or necessary to prevent the introduction and spread of\n(nn) Establish fire limits in populous centers and prescribe the kinds of buildings that may be constructed or\nrepaired within them;\n(oo) Regulate cockpits, cockfighting and the keeping or training of gamecocks, subject to existing guidelines\npromulgated by the Philippine Gamefowl Commission;\n(pp) Regulate garages and the keeping of conveyances for hire and designate stands to be occupied by public\nvehicles when not in use;\n(qq) Regulate the construction and operation of private markets, talipapa, or other similar buildings and\nphysical structures;\n(rr) Regulate cafes, restaurants, beer-houses, hotels, motels, inns, pension houses and lodging houses, except\n\ntravel agencies, tourist guides, tourist transports, hotels, resorts, de luxe restaurants, and tourist inns of\ninternational standards which shall remain under the licensing and regulatory power of the Ministry of\nTourism which shall exercise such authority without infringing on the taxing or regulatory powers of the\nmunicipality;\n(ss) Regulate public dancing schools, public dance halls and sauna baths or massage parlors;\n(tt) Regulate the establishment and operation of billiards pools, theatrical performances, circuses and other\nforms of entertainment;\n(uu) Regulate the establishment and provide for the inspection of steam boilers and storage of inflammable\nand combustible materials within the municipality;\n(vv) Establish a scholarship fund for poor but deserving students for the payment of tuition and other school\nfees, subject to such terms and conditions as may be determined by ordinance;\n(ww) Define boundaries, and change the names of barangays within the municipality; and\n(xx) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\n(2) Public utilities owned by the municipality may be operated by the municipality or may be leased to private\nparties under such terms and conditions that may be imposed by the sangguniang bayan.\n(3) When any ferry, market, or slaughterhouse belonging to a municipality is to be leased to a private party, it\nshall be awarded to the highest bidder for a period of not less than one year but not exceeding five years. The\nlease may be renewed for a period not exceeding the original lease and under such terms as the sangguniang\nbayan may impose.\nARTICLE FOUR\nTHE MUNICIPAL SECRETARY"}},{"id":"PH-H15202-A150","no":150,"noLabel":{"en":"Section 150"},"text":{"en":"Appointment, Compensation, Powers and Duties. -\n(1) There shall be a municipal secretary who shall be appointed by the municipal mayor with the concurrence\nof the sangguniang bayan, in accordance with civil service law, rules and regulations, whose compensation,\nallowances and other emoluments shall be determined by law or ordinance.\n(a) Attend meetings of the sangguniang bayan and keep a journal of its proceedings and record other acts of\nthe municipal government;\n(b) Record in a book kept for the purpose, all ordinances, resolutions and motions enacted or adopted by the\nsangguniang bayan, with the dates of their enactment and publication;\n(c) Forward to the sangguniang panlalawigan copies of approved resolutions or ordinances within seventy-two\nhours after their approval;\n(d) Forward to the mayor for appropriate action ordinances and resolutions enacted or adopted by the\nsangguniang bayan which have not been certified as such by the temporary presiding officer within ten days\nafter their enactment or adoption;\n(e) Keep and affix the corporate seal of the municipality on all ordinances and resolutions signed by the mayor\nand on all other official documents and papers of the municipal government as may be required by law or\n(f) Attest to all executive orders, proclamations, ordinances and resolutions signed by the mayor;\n(g) Translate into the dialect used by the majority of the people of the municipality all ordinances immediately\nafter their approval, and have the translation posted, together with the original, at the main entrance of the\nmunicipal building and in other conspicuous public places in the barangays of the municipality.\n\n(h) Furnish certified copies of all records and documents in his charge not otherwise classified as confidential,\nupon payment to the municipal treasurer of the fees prescribed by ordinances;\n(i) Keep his office and all records therein which are not a confidential character open to public inspection\nduring the usual business hours;\n(j) Act as custodian of the municipal library and archives, if any, and annually account for them; and\n(k) Exercise such other powers and perform such other duties and functions as may be prescribed by law or"}},{"id":"PH-H15202-A151","no":151,"noLabel":{"en":"Section 151"},"text":{"en":"Authentication of Ordinance and Resolutions. -\n(1) The affirmative votes of a majority of all the members of the sangguniang bayan shall be necessary for the\npassage of any ordinance, resolution or motion directing the payment of money or creating liability. Other\nmeasures shall prevail upon the majority vote of the members present and voting at any meeting duly called\nand held, there being a quorum.\n(2) The \"ayes\" and \"nays\" shall be taken and recorded upon the passage of all ordinances, upon resolutions or\nmotions directing the payment of money or creating liability, and, at the request of any member, upon any\nother resolution or motion. Each approved ordinance, resolution or motion shall be stamped with the seal of\nthe sangguniang bayan and recorded in a book kept for the purpose."}},{"id":"PH-H15202-A152","no":152,"noLabel":{"en":"Section 152"},"text":{"en":"Approval of Ordinances by the Mayor; Veto Power. -\n(1) Except as hereinbelow provided, every ordinance or resolution passed by the sangguniang bayan shall be\napproved and signed by the mayor.\n(2) Within ten days after the receipt of the ordinance, resolution or motion, the mayor shall return it with\neither his approval or his veto. If he does not return it within that time, it shall be deemed approved.\n(3) If he should consider the ordinance, resolution or motion prejudicial to the public welfare, he may veto it\nby signifying to the sangguniang bayan his disapproval thereof in writing. The sangguniang bayan may, by\ntwo-thirds vote of all members, pass an ordinance, resolution or motion over the veto of the mayor, in which\ncase it shall become effective without his approval.\n(4) The mayor shall have the power to veto any particular item or items of an appropriation ordinance or of an\nordinance or resolution directing the payment of money or creating liability, but the veto shall not affect the\nitem or items to which he does not object. The item or items objected to shall not take effect unless the\nsangguniang bayan overrides the veto in the manner provided in paragraph (3) of this section. The veto power\nof the mayor shall be exercised only once upon an ordinance or resolution or upon an item or items in an\nappropriation ordinance."}},{"id":"PH-H15202-A153","no":153,"noLabel":{"en":"Section 153"},"text":{"en":"Sangguniang Panlalawigan Review. -\n(1) Within thirty days after receiving copies of approved ordinances, resolutions and executive orders\npromulgated by the municipal mayor, the sangguniang panlalawigan shall examine the documents or transmit\nthem to the provincial attorney, or if there be none, to the provincial fiscal, who shall examine them promptly\nand inform the sangguniang panlalawigan in writing of any defect or impropriety which he may discover\ntherein and make such comments or recommendations as shall appear to him proper.\n(2) If the sangguniang panlalawigan shall find that any municipal ordinance, resolution or executive order is\nbeyond the power conferred upon the sangguniang bayan or the mayor, it shall declare such ordinance,\nresolution or executive order invalid in whole or in part, entering its actions upon the minutes and advising the\nproper municipal authorities thereof. The effect of such an action shall be to annul the ordinance, resolution or\nexecutive order in question in whole or in part. The action of the sangguniang panlalawigan shall be final.\n(3) Any attempt to enforce any ordinance, resolution or executive order after its disapproval shall be sufficient\nground for the suspension or dismissal of the officer attempting to enforce it.\n(4) If the sangguniang panlalawigan does not take action on the ordinance, resolution or executive order\n\nwithin thirty days after its submission, it shall be presumed consistent with law."}},{"id":"PH-H15202-A154","no":154,"noLabel":{"en":"Section 154"},"text":{"en":"Referral of Legal Questions. - The sangguniang bayan may secure the opinion of the\nmunicipal attorney or the provincial attorney, or if there be none, the provincial fiscal, on any legal question\naffecting the municipality.\nARTICLE FIVE\nTHE MUNICIPAL TREASURER"}},{"id":"PH-H15202-A155","no":155,"noLabel":{"en":"Section 155"},"text":{"en":"Appointment, Qualifications, Compensation, Powers, Duties and Functions. -\n(1) The municipal treasurer shall be appointed by the Minister of Finance upon recommendation of the\nmunicipal mayor, subject to civil service law, rules and regulations. He shall take charge of the municipal\ntreasury office and acts as the chief financial officer of the municipality.\n(2) No person shall be appointed municipal treasurer unless he is a citizen of the Philippines, of good moral\ncharacter, twenty-three years of age, a holder of a degree preferably in law, commerce, public administration\nor any other related course from a recognized college of university, a first grade civil service eligible or its\nequivalent, and has at least three years experience in the treasury or accounting service. The qualifications\nherein prescribed shall not be required of incumbent municipal treasurers: Provided, however, That an\nincumbent municipal treasurer may not be promoted unless he shall have completed at least two years of\ncollege education and has the required experience in treasury or accounting work herein specified.\n(3) The municipal treasurer shall receive such compensation, allowances and other emoluments as may be\nprovided by law or ordinance.\n(4) The municipal treasurer shall:\n(a) Collect all monies and revenues accruing to the municipality and issue proper receipts therefor showing\nthe date, the amount paid, the name of the person making the payment and the amount upon which it is paid;\n(b) Disburse all municipal funds and other funds entrusted to him by law or by competent authority, in\naccordance with duly authorized appropriations and upon properly executed vouchers bearing the approval of\nthe proper authorities;\n(c) Submit to the municipal mayor certified statements of actual and estimated income in connection with the\npreparation of annual and supplemental budgets of the municipality;\n(d) Advise the sangguniang bayan and other municipal officials concerned on the disposition of municipal\nfunds and on all municipal fiscal matters;\n(e) For taxation purposes inspect, under the supervision of the sangguniang bayan, the operation of public\nutilities belonging to, leased or operated by, the municipal government and all other commercial and industrial\nenterprises of the municipality;\n(f) Deposit all funds accruing to the municipality with the provincial treasurer concerned, who in turn shall\ndeposit the same with duly designated banks, and whenever any excess or idle portion thereof is placed in\ntime deposit or other investment accounts, interest earnings from these deposits shall accrue solely to the\nmunicipality: Provided, however, That in proper cases, the Minister of Finance may authorize the municipality\nto deposit its funds with the nearest provincial or city treasury or banks, when there is a duly authorized\ndepository bank in the municipality, or when public interest so requires;\n(g) Certify jointly with the barangay treasurers to the collectibility of the estimated tax receipts and income of\nthe barangay governments for the ensuing calendar year;\n(h) On or before the twentieth day of each month, furnish the mayor and the sangguniang bayan a statement of\nthe appropriations, actual expenditure and balance of all funds and accounts as of the last day of the preceding\n(i) Approve the registration of large cattle;\n\n(j) Perform, as deputy of the provincial treasurer in the municipality, such other duties not inconsistent with\nlaw as the provincial treasurer may assign to him;\n(k) Keep a detailed account of all monies received and pay or dispose of the same pursuant to lawful\n(l) Charge, at rates to be fixed by the sangguniang bayan, fees for public services and supplies made available\nby his office to private parties; and\n(m) Exercise such other powers and perform such other duties and functions as may be prescribed by law or"}},{"id":"PH-H15202-A156","no":156,"noLabel":{"en":"Section 156"},"text":{"en":"Temporary Disability. - In the event of inability of the treasurer to discharge the duties of his\noffice on account of a trip on official business, absence on leave, sickness, suspension or other temporary\ndisability, the assistant municipal treasurer or, in his absence, the treasury official next in rank in the\nmunicipality shall discharge the duties of the office subject to existing laws."}},{"id":"PH-H15202-A157","no":157,"noLabel":{"en":"Section 157"},"text":{"en":"Inspection of Municipal Treasurer's Accounts; Suspension of Delinquent Treasurer. - The\nbooks, accounts, papers and cash in the custody of the municipal treasurer shall at all times be open to\ninspection in accordance with existing laws.\nIn case an examination discloses a shortage in the cash which should be on hand or any misuse of the funds in\nviolation of the law, it shall be the duty of the examining officer to seize the cash, books, accounts and papers,\nverifying the amount of cash so seized in the presence of at least two municipal officers designated by the\nmayor, who shall certify to the amount so seized. Thereupon, the municipal mayor shall immediately report\nthe suspension to the Minister of Finance for the latter's appropriate action. The funds so seized shall be\ntreated as a municipal deposit in the account of the assistant municipal treasurer or the treasury official next in\nrank in the municipality until the municipal treasurer is restored or a new municipal treasurer is appointed to\nreplace him."}},{"id":"PH-H15202-A158","no":158,"noLabel":{"en":"Section 158"},"text":{"en":"Additional Compensation. - A municipal treasurer may receive for his services as deputy of\nthe provincial treasurer, such additional compensation as the sangguniang panlalawigan may fix upon the\nrecommendation of the provincial treasurer. The additional compensation shall be paid from provincial funds.\nARTICLE SIX\nTHE MUNICIPAL ASSESSOR"}},{"id":"PH-H15202-A159","no":159,"noLabel":{"en":"Section 159"},"text":{"en":"Appointment, Qualifications, Compensation, Powers, Duties and Functions. -\n(1) The municipal assessor shall be appointed by the Minister of Finance upon recommendation of the\nmunicipal mayor, subject to civil service law, rules and regulations.\n(2) No person shall be appointed municipal assessor unless he is a citizen of the Philippines, of good moral\ncharacter, at least twenty-three years of age, a holder of a degree preferably in law, civil or mechanical\nengineering, commerce or business administration or any other related course from a recognized college or\nuniversity, a first grade civil service eligible or its equivalent, and has at least three years experience in\nassessment work: Provided, however, that a two-year experience in assessment work may be substituted for\nevery year of deficiency in educational requirement: Provided, further, That the appointee shall have\ncompleted at least two years of any of the aforementioned college courses.\n(3) The municipal assessor shall receive such compensation, allowances and other emoluments as may be\nprovided by law or ordinance.\n(4) The municipal assessor shall submit a periodic report to the provincial assessor. He shall:\n(a) Establish a systematic method of assessment of real property in the manner prescribed by law and in\naccordance with rules and regulations issued by the Minister of Finance;\n(b) Install and maintain a real property identification and accounting system conforming to the standards\n\nprescribed by the Minister of Finance;\n(c) Prepare, install and maintain a system of tax mapping showing graphically all property subject to\nassessment in the municipality and gather all necessary data concerning the same;\n(d) Make frequent physical surveys to check and determine whether all real property within the municipality\nare listed in the assessment rolls;\n(e) Appraise all items of real property at current market value in accordance with law and conduct regular\nocular inspections to determine if all properties are assessed correctly;\n(f) Keep a correct record of all transfers, leases and mortgages of real property, rentals, insurance, and cost of\nconstruction of buildings and other improvements on land and land income for assessment purposes;\n(g) Apply uniformly the assessment levels fixed by law to the current market value of all property subject to\nassessment;\n(h) Cancel assessments, in case several assessments have been made for the same property, except the one\nproperly made, but if any assessee or his representative shall object to the cancellation of the assessment made\nin his name, such assessment shall not be cancelled but the fact shall be noted on the tax declaration and\nassessment rolls and other property books of records. Preference, however, shall be given to the assessment of\nthe person who has the best title to the property, or in default thereof, of the person who has possession of the\n(i) Eliminate from the assessment roll of taxable property those which have been destroyed or which, being\nexempted, have been improperly included in the same; decrease the assessment where property previously\nassessed has suffered a permanent loss of value by reason of storm, flood, fire or other calamity and increase\nthe assessment where improvements have been made upon the property subsequent to the last assessment;\n(j) Attend personally or through his duly authorized representative all sessions of the local board of\nassessment appeals and present any information or record in his possession as may be required by the board in\ndetermining the current assessment of the real property under appeal;\n(k) Issue certificates pertaining to, or issue certified copies of the assessment records of, real property and all\nother records relative to its assessment upon payment of a service charge or fee fixed therefor by the\nsangguniang bayan;\n(l) Make a report every semester of all assessments during said period and submit copies of said report to all\nthe officials of the municipal government including the sangguniang barangays; and\n(m) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE SEVEN\nTHE MUNICIPAL BUDGET OFFICER"}},{"id":"PH-H15202-A160","no":160,"noLabel":{"en":"Section 160"},"text":{"en":"Appointment, Qualifications, Compensation, Powers, Duties and Functions. -\n(1) The municipal budget officer shall be appointed by the municipal mayor, subject to civil service law, rules\nand regulations.\n(2) No person shall be appointed municipal budget officer unless he is a citizen of the Philippines, of good\nmoral character, at least twenty-three years of age, has completed at least two years of college education in a\nrecognized college or university, a first grade civil service eligible or its equivalent, and has acquired at least\nthree years of experience in budgeting or in any related field.\n(3) The municipal budget officer shall receive such compensation, emoluments and allowances as may be\nprovided by law or ordinance.\n(4) Under the general supervision and administrative control of the municipal mayor, the municipal budget\n\nofficer shall:\n(a) Exercise general supervision and control over the municipal budget office;\n(b) Provide technical and staff services to the mayor and other local officials on budget matters;\n(c) Prepare forms, orders and circulars embodying instructions on budgetary and appropriation matters for the\napproval of the municipal mayor;\n(d) Review and consolidate the budget estimates of the different of the municipal government and of the\nbarangays, and review budgets of barangays under the jurisdiction of the municipality;\n(e) Prepare the executive and special budgets of the municipality;\n(f) Evaluate allotment requests and prepare corresponding recommendations;\n(g) Study and evaluate budgetary implications of proposed legislation and submit comments and\nrecommendation thereon;\n(h) Submit budgetary reports to the Office of Budget and Management;\n(i) Coordinate with the municipal treasurer for purposes of municipal government budgeting; and\n(j) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE EIGHT\nTHE MUNICIPAL PLANNING AND DEVELOPMENT COORDINATOR"}},{"id":"PH-H15202-A161","no":161,"noLabel":{"en":"Section 161"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The municipal planning and development coordinator shall be appointed by the municipal mayor, subject\nto civil service law, rules and regulations.\n(2) No person shall be appointed municipal planning and development coordinator unless he is a citizen of the\nPhilippines, of good moral character, at least twenty-three years of age, a holder of a college degree,\npreferably in law, engineering, commerce, public administration or any related course from a recognized\ncollege or university, a first grade civil service eligible or its equivalent, and has at least three years\nexperience in planning or in any related field. The college degree herein prescribed shall not be required of the\nincumbent: Provided, however, That he shall have completed at least two years of college education and has\nsufficient experience in development planning that may be substituted for deficiency in educational attainment\nhereinbefore prescribed for the purpose.\n(3) The municipal planning and development coordinator shall receive such compensation, emoluments and\nallowances as may be provided by law or ordinance.\n(a) Formulate an integrated economic, social, physical and other development objectives and policies for the\nconsideration and approval of the sangguniang bayan and the municipal mayor;\n(b) Conduct continuing studies, researches, and relevant trainings necessary to evolve plans and programs for\nimplementation;\n(c) Integrate and coordinate all sectoral plans and studies undertaken by the different functional groups or\n(d) Monitor and evaluate the implementation of the different development programs, projects and activities in\nthe municipality;\n(e) Prepare municipal comprehensive plans and other development planning documents;\n(f) Analyze municipal income and expenditure patterns, and formulate and recommend fiscal plans and\npolicies for the consideration and approval of the sangguniang bayan and the municipal mayor;\n\n(g) Promote citizen participation through development planning at the barangay level;\n(h) Exercise general supervision and control of the day-to-day activities of the municipal planning and\ndevelopment office personnel and the divisions, sections or officers placed under its supervision; and\n(i) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\n(5) In the performance of the above functions, all personnel presently performing planning and development\nfunctions in the office of the mayor shall be given preference in the appointment to commensurate positions in\nthe office of the municipal planning and development coordinator.\nTITLE THREE\nROLE AND CREATION OF CITIES"}},{"id":"PH-H15202-A162","no":162,"noLabel":{"en":"Section 162"},"text":{"en":"Role of Cities. - As a political unit covering more urbanized and developed communities, the\ncity is akin to the municipality and serves as a general-purpose government for the coordination and delivery\nof all basic, regular and direct services within its jurisdiction."}},{"id":"PH-H15202-A163","no":163,"noLabel":{"en":"Section 163"},"text":{"en":"Manner of Creation. - A city may be created, divided, merged, abolished or its boundaries\naltered, only by an Act of the Batasang Pambansa in accordance with the criteria established in this Code, and\nsubject to the approval by a majority of the votes cast in a plebiscite in the unit or units affected. Except as\nmay otherwise be provided in such Act, the plebiscite shall be conducted by the Commission on elections\nwithin one hundred twenty days from the date of effectivity of said Act."}},{"id":"PH-H15202-A164","no":164,"noLabel":{"en":"Section 164"},"text":{"en":"Requisites for Creation. -\n(1) A municipality may be converted into a component city if it has a population of not less than one hundred\nthousand as certified by the National Census and Statistics Office, and an average regular annual income, as\ncertified by the Minister of Finance, of at least ten million pesos for the last three consecutive years. The\nterritory need not be contiguous if it comprises two or more islands.\n(2) The regular annual income shall include the income allotted for both the general and infrastructure funds\nexclusive of trust funds, transfers, and nonrecurring income.\n(3) Municipalities created as component cities under this section shall continue to share their income with\ntheir respective provinces in the same manner as municipalities."}},{"id":"PH-H15202-A165","no":165,"noLabel":{"en":"Section 165"},"text":{"en":"Cities, Classified. - A city may either be component or highly urbanized. Highly urbanized\ncities, as hereinafter provided, shall be independent of the province."}},{"id":"PH-H15202-A166","no":166,"noLabel":{"en":"Section 166"},"text":{"en":"Highly Urbanized Cities. -\n(1) Cities with a minimum population of one hundred and fifty thousand as certified by the National Census\nand Statistics Office, and with the latest annual income of at least thirty million pesos as certified by the\nMinister of Finance, shall be classified as highly urbanized cities.\n(2) Cities which do not meet the above requirements shall be considered component cities of the province in\nwhich they are geographically located. If a component city is located within the boundaries of two or more\nprovinces, said city shall be considered a component of the province of which it used to be a municipality."}},{"id":"PH-H15202-A167","no":167,"noLabel":{"en":"Section 167"},"text":{"en":"Criteria for Evaluation of a Component City to a Highly Urbanized City. - A component city\nmay become a highly urbanized city if it meets the criteria specified in the preceding section."}},{"id":"PH-H15202-A168","no":168,"noLabel":{"en":"Section 168"},"text":{"en":"Duty to Declare Highly Urbanized Status. - It shall be the duty of the Minister of Local\nGovernment to declare a city highly urbanized within thirty days after it shall have met the minimum\nrequirements prescribed in Section 166 hereof.\n\nCITY OFFICIALS IN GENERAL"}},{"id":"PH-H15202-A169","no":169,"noLabel":{"en":"Section 169"},"text":{"en":"Officials of the City Government. -\n(1) There shall be in each city a mayor, a vice-mayor, sangguniang panlungsod members, a city secretary, a\ntreasurer, an assessor, an engineer, a city budget officer and a city planning and development coordinator.\n(2) In highly urbanized cities, there shall be, in addition to the above, a city legal officer, a city civil registrar,\na city administrator, a city veterinarian, a city social services and development officer, and a city general\nservices officer, and, where appropriate, a city agriculturist, whose appointments, compensation, powers and\nduties shall be as hereinafter provided.\n(3) The sangguniang panlungsod may maintain existing offices not mentioned in paragraphs (1) and (2) of this\nsection, or create such other offices as may be necessary to carry out the purposes of the city government, or\nconsolidate the functions of any one of such offices with another in the interest of efficiency and economy.\n(4) The Minister of Local Government shall prescribe, in consultation with cities, minimum standards and\nguidelines with respect to their organizational structure, staffing pattern and other relevant operational aspects\naccording to needs."}},{"id":"PH-H15202-A170","no":170,"noLabel":{"en":"Section 170"},"text":{"en":"General Powers and Duties of City Officials. -\n(1) All offices of the city government shall be under the control and direction of the mayor, and the chiefs of\noffices shall exercise such powers as may be prescribed in this Code or by ordinance.\n(2) Each chief of office shall certify to the correctness of all payrolls and vouchers of his office covering the\npayment of money before payment thereof except as herein otherwise expressly provided.\n(3) At least ten and one-half months before the beginning of each calendar year, he shall prepare and present\nto the mayor an estimate of the receipts and appropriations necessary for the operation of his office for the\nensuing calendar year, and shall submit therewith such information for budget preparation purposes or for\ncomparison purposes as the mayor may desire. He shall submit to the mayor as often as required, reports\ncovering the operation of his office.\n(4) In case of absences, sickness, or incapacity of the chief of an office to act for any reason resulting in a\ntemporary vacancy, the assistant chief of office or the officer next in rank, shall perform the duties of the chief\nof office concerned.\n(5) No city official engaged in the discharge of official duties shall leave the city without written permission\nfrom the mayor. National officials assigned in the city, when called upon by the heads of their respective\nministries or when they are to leave their official stations on official business, shall give prior written notice to\nOfficials and Offices Common to All Cities\nARTICLE ONE\nThe City Mayor"}},{"id":"PH-H15202-A171","no":171,"noLabel":{"en":"Section 171"},"text":{"en":"Chief Executive; Compensation, Powers and Duties. -\n(1) The city mayor be the chief executive of the city government, and shall exercise such powers, duties and\nfunctions as provided in this Code and other laws. He shall receive such compensation, emoluments and\nallowances as may be prescribed by law or ordinance.\n(2) The city mayor shall:\n(a) Take care that the laws of the Philippines and the ordinances and resolutions of the city are duly observed\nand enforced;\n(b) Maintain peace and order in the city, and in pursuance thereof, he shall be entitled to possess and carry the\n\nnecessary firearms within its territorial jurisdiction, subject to existing rules and regulations on the possession\nand carrying firearms;\n(c) Prepare and submit to the sangguniang panlungsod the annual budget of the city for the ensuing calendar\nyear on the date and in the manner provided and prescribed by law;\n(d) See to it that executive officers and employees of the city faithfully discharge their respective duties, and\nfor the purpose, cause, if necessary, the institution and filing of appropriate criminal or administrative action;\n(e) Furnish the sangguniang panlungsod from time to time, such information and recommend such measures\nas he shall deem appropriate or necessary;\n(f) Examine the books, records, and papers of all offices, officers, agents or employees of the city;\n(g) Represent the city in its business transactions, and sign all warrants drawn on the city treasury and all\nbonds, contracts and obligations of the city;\n(h) Appoint, in accordance with civil service law, rules and regulations, all officers and employees of the city,\nwhose appointments are not otherwise provided in this Code;\n(i) Cause to be instituted judicial proceedings to recover property and funds of the city wherever found, and\ncause to be defended all suits against the city, or otherwise protect its interest;\n(j) As soon as possible but not later than March 31 of each year, prepare and submit to the Ministry of Local\nGovernment an annual report covering the operation of the city government during the preceding calendar\n(k) Ensure that all taxes and other revenues of the city are collected, and the city funds applied in accordance\nwith law or ordinance to the payment and settlement of the city expenses and obligations;\n(l) Exempt, upon the recommendation of the superintendent of city schools, deserving but financially\ndisadvantaged students from the payment of tuition and other school fees or any part thereof;\n(m) Take such emergency measures as may be necessary to protect the public from fires, prevent and mitigate\nthe effects of floods, storms, earthquakes and other public calamities;\n(n) Grant or refuse to grant, pursuant to law, city licenses or permits, and revoke the same for violation of law\nor ordinance or the conditions upon which they are granted;\n(o) Require owners of houses, buildings or other structures constructed without the necessary permit or in\nviolation of existing law or ordinance, to remove or demolish such houses, buildings or structures within thirty\ndays, or cause its removal or demolition at the expense of the owner;\n(p) Grant permits to hold benefits, excepting prohibited games of chance, for public and charitable purposes\nwithout requiring approval of the Ministry of Social Services and Development;\n(q) Act on the commutation of vacation, sick and maternity leaves and of trips outside the city of chiefs of\noffices appointed by him;\n(r) Initiate appropriate action or proceedings against any national government official or employee rendering\nservice within the city to draw the attention of the corresponding superior officer to the dereliction of the\nofficial or employee involved;\n(s) Authorize payment of medical attendance, necessary transportation, subsistence, and hospital fees or\nofficials and employees of the city who suffer any injury arising out of the or in the course of their\nemployment. Absence in such cases shall not be charged against any leave credit;\n(t) Approve the commutation of such transportation allowances as may be authorized by law for chiefs of\n(u) Direct the preparation and formulation of the development plan and program of the city, and upon\napproval by the sangguniang panlungsod, direct and supervise the implementation and execution of the same;\n\n(v) Call a meeting of any or all of the officers and employees of the city; and\n(w) Perform such other duties and exercises such other powers as may be prescribed by law or ordinance.\nARTICLE TWO\nTHE VICE-MAYOR"}},{"id":"PH-H15202-A172","no":172,"noLabel":{"en":"Section 172"},"text":{"en":"Functions and Compensation. -\n(1) The vice-mayor shall:\n(a) Be the presiding officer of the sangguniang panlungsod;\n(b) Assume the office of the city mayor for the unexpired term of the latter in the event of permanent vacancy;\n(c) Exercise the powers and perform the duties and functions of the city mayor in cases provided for in\nSection 52 of this Code; and\n(d) Exercise such other powers and perform such other duties as may be prescribed by law or ordinance;\n(2) The vice-mayor shall receive such compensation, emoluments and allowances as may be determined by\nlaw or ordinance.\nARTICLE THREE\nTHE SANGGUNIANG PANLUNGSOD"}},{"id":"PH-H15202-A173","no":173,"noLabel":{"en":"Section 173"},"text":{"en":"Composition and Compensation. -\n(1) The sangguniang panlungsod, as the legislative body of the city, shall be composed of the vice-mayor, as\npresiding officer, the elected sangguniang panlungsod members, and the members who may be appointed by\nthe President of the Philippines consisting of the presidents of the katipunang panlungsod ng mga barangay\nand the kabataang barangay city federation.\n(2) The members of the sangguniang panlungsod shall receive such compensation, emoluments and\nallowances as may be determined by law or ordinance.\n(3) Cities with a population of one hundred thousand to two hundred thousand shall elect eight (8) members of\nthe sangguniang panlungsod at large; cities with a population of more than two hundred to three hundred\nthousand shall be entitled to elect ten (10) members of the sangguniang panlungsod; and cities with a\npopulation of more than three hundred thousand shall be entitled to elect twelve (12) members of the said\nsanggunian. Existing cities with a population of less than one hundred thousand shall be entitled to elect six\n(6) sangguniang panlungsod members.\n(4) The above number of elected sangguniang panlungsod members shall not include the presidents of the\nkatipunang panlungsod ng mga barangay and the kabataang barangay city federation.\n(5) In addition thereto, there shall be one representative each from the agricultural and industrial labor sectors\nwho shall be appointed by the President of the Philippines whenever, as determined by the sangguniang\npanlungsod, said sectors are of sufficient number in the city to warrant representation, after consultation with\nassociations and persons belonging to the sector concerned."}},{"id":"PH-H15202-A174","no":174,"noLabel":{"en":"Section 174"},"text":{"en":"Sessions. -\n(1) The sangguniang panlungsod shall fix the time and place for its regular sessions which shall be held once a\nweek. Special sessions may be called by the city mayor when the public interest so demands.\n(2) In case the volume of business so requires, a session, regular or special, may be adjourned from day to day\nuntil the business is completed.\n(3) The sessions of the sangguniang panlungsod shall be open to the public unless otherwise ordered by\naffirmative vote of a majority of its members.\n(4) The sangguniang panlungsod shall adopt its own rules of procedure, keep a record of its proceedings and\nfor disorderly conduct during sessions, with the concurrence of two-thirds of all its members, reprimand,\n\nexclude from the session, or suspend for not more than sixty days an erring member."}},{"id":"PH-H15202-A175","no":175,"noLabel":{"en":"Section 175"},"text":{"en":"The Presiding Officer of the Sangguniang Panlungsod. -\n(1) The vice-mayor, as presiding officer of the sangguniang panlungsod, shall not vote except in case of a tie.\nHe shall sign within ten days from their adoption all ordinances, resolutions and motions enacted or adopted\nby the said sanggunian. If after the period of ten days an ordinance or resolution is not signed by the presiding\nofficer, the city secretary shall forward the same to the city mayor for appropriate action.\n(2) If the vice-mayor cannot preside over a regular or special session, the members present and constituting a\nquorum shall elect from among themselves a temporary presiding officer."}},{"id":"PH-H15202-A176","no":176,"noLabel":{"en":"Section 176"},"text":{"en":"Quorum. - A majority of all the members of the sangguniang panlungsod shall constitute a\nquorum for the transaction of business, but a smaller number may adjourn from day to day and compel the\nimmediate attendance of any member who is absent without good cause by issuing to the Integrated National\nPolice assigned in the area an order for his arrest and production at the session, subject to penalties prescribed"}},{"id":"PH-H15202-A177","no":177,"noLabel":{"en":"Section 177"},"text":{"en":"Powers and Duties. - The sangguniang panlungsod shall:\n(a) Enact such ordinances as may be necessary to carry into effect and discharge the responsibilities conferred\nupon it by law, and such as shall be necessary and proper to provide for the health and safety, comfort and\nconvenience, maintain peace and order, improve the morals, and promote the prosperity and general welfare\nof the community and the inhabitants thereof, and the protection therein;\n(b) Appropriate funds for expenses of the city government, and fix the salaries of its officers and employees\naccording to law;\n(c) Provide for the levy and collection of taxes and other city revenues and apply the same to the payment of\nthe expenses of the city in accordance with appropriations;\n(d) Regulate, fix the license fee for, and tax any business or profession being carried on and exercised within\nthe territorial jurisdiction of the city, except travel agencies, tourist guides, tourist transports, hotels, resorts,\nde luxe restaurants, and tourist inns of international standards which shall remain under the licensing and\nregulatory power of the Ministry of Tourism which shall exercise such authority without infringing on the\ntaxing and regulatory powers of the city government;\n(e) Construct, keep in good repair and regulate the use of streets and other public places; establish public\nplaces; establish bus stops and terminals; regulate garages and the operation of conveyances for hire; and\ndesignate stands to be occupied by public vehicles when not in use;\n(f) Provide for the construction, purchase and lease of buildings necessary for the use of the city;\n(g) Establish and maintain public elementary schools subject to such limitations as may be prescribed by law;\n(h) Establish fire limits or zones, determine the kinds of buildings and structures that may be erected within\nsaid limits or zones and regulate the manner of constructing and repairing the same, subject to applicable\nprovisions of law;\n(i) Make suitable provisions to protect the public from conflagrations and to prevent and mitigate the effects\nof famine, floods, storms and other public calamities, and provide relief to victims thereof;\n(j) Provide for the lighting, cleaning and sprinkling of streets and other public places; summarily remove\nencroachments and constructions on them; regulate their use, the putting up thereon of signs, signposts,\nawning and awning posts; prohibit littering, the placing, depositing, leaving or throwing of garbage, refuse or\nother filth and provide for their collection and disposition; regulate the digging and excavation for the laying\nof gas, water, power, and other pipelines, the building and repair of tunnels, sewers and drains, and all\nstructures thereunder; the placing, stringing, attaching, installing, repair and construction of all gas mains,\nelectric, telegraph and telephone wires, conduits, meters and other apparatus, and the correction,\ncondemnation or removal of the same when dangerous or defective;\n\n(k) Name and change the names of all streets and other public places not more often than once every ten\nyears; regulate traffic upon the same; construct, maintain and regulate the use of bridges, viaducts and\nculverts; and regulate amusements having the tendency to annoy persons, and in its discretion suspend,\nsuppress or prohibit said amusements in order to protect the social and moral welfare of the community;\n(l) Establish and maintain waterworks for the purpose or supplying water to the inhabitants of the city, purify\nthe source of supply, regulate the use and prevent the wastage of water, and fix and collect fees therefor;\nregulate the construction, repair, and use of hydrants, pumps, cisterns and reservoirs; and for the purpose of\nprotecting and ensuring the purity and quantity of the water supply of the city, extend its ordinances over all\nterritories within the drainage area of such water supply, and within one hundred meters of any reservoir,\nconduit, canal, aqueduct, pumping station or watershed used in connection with the water service.\n(m) Prohibit and penalize cruelty to animals, regulate their keeping and use, restrict or prohibit their running at\nlarge; establish and maintain a city pound and fix the fees for poundage; provide for the distraining,\nimpounding, killing or sale of the same; and impose penalties upon the owners of said animals for the\nviolation of any ordinance in relation thereto. Large cattle and all other animals of the bovine family shall be\ndisposed of in accordance with law;\n(n) Require any land or building which is in an unsanitary condition to be cleaned at the expense of the owner\nor tenant, and upon failure to comply with such an order, have the work done, and assess the expenses upon\nthe land or building;\n(o) Require the filling up to a grade necessary for proper sanitation, any and all lands and premises which may\nbe declared by competent authority to be unsanitary for being below such grade;\n(p) Construct and keep in repair public drains, sewers and cesspools, and regulate the construction and use of\nprivate water closets, privies, sewers, drains and cesspools;\n(q) Provide for the burial of the dead in such place and in such manner as prescribed by law or ordinance;\n(r) Establish and operate or authorize the establishment and operation of markets and slaughterhouses, and\nregulate preparation and sale of meat, poultry, fish, vegetables, fruits and other provisions or articles of food\noffered for sale;\n(s) Adopt measures to prevent the introduction and spread of disease;\n(t) Declare, prevent and abate nuisance;\n(u) Provide for an efficient machinery for the recording of births, marriages, deaths, and other acts affecting\ncivil status;\n(v) Suppress gambling houses, houses of ill fame, houses where prohibited drugs are unlawfully dispensed or\nused and other similar establishments;\n(w) Prohibit the printing, circulation, sale, distribution or exhibition of immoral and obscene pictures, films,\narticles, books or any other kind of pornographic publications;\n(x) Prevent and suppress riots, affrays, disturbances and disorderly assemblies, habitual drunkenness in public\nplaces, drug addiction, vagrancy, mendicancy, prostitution, gambling and other forms of disorderly or\nunlawful conduct, and adopt measures for the rehabilitation of drug addicts, alcoholics, vagrants, mendicants,\nprostitutes, gamblers and juvenile delinquents;\n(y) Fix the fees and/or charges for all services rendered by the city or any of its offices;\n(z) Establish or aid in the establishment and maintenance of secondary and vocational schools and other\ninstitutions of higher learning and, with the approval of the Ministry of Education, Culture and Sports, fix\nreasonable tuition and other school fees in the vocational schools and in other educational institutions\nsupported by the city;\n(aa) Appropriate money for purposes not specified by law, having in view the general welfare of the city and\n\nits inhabitants;\n(bb) Create, define boundaries, and change the names of barangays in the city pursuant to the requirements of\n(cc) Create, consolidate, and reorganize city offices and positions wholly supported by local funds;\n(dd) Review tax and appropriation ordinances, and if so required, other ordinances approved by the\nsangguniang-barangay to determine if they are within the powers conferred it by law;\n(ee) Authorize the payment of compensation or additional compensation, as the case may be, to any officer or\nemployee designated to fill a temporary vacancy at a rate equal to that actually received by the regular\n(ff) Provide for the care of the poor, the aged, the sick, persons of unsound mind and abandoned minors, and\nfor the care and rehabilitation of juvenile delinquents and disabled or handicapped persons;\n(gg) Float bonds for the purpose of raising funds to finance development projects, subject to applicable\nprovisions of law;\n(hh) Penalize violation of its ordinances by a fine or not more than one thousand pesos or imprisonment of not\nexceeding six months, or both such fine and imprisonment at the discretion of the court;\n(ii) Grant franchises to any person or corporation to do business within the city to establish, construct, operate\nand maintain a ferry or wharf, or undertake such other activities as may be allowed by law, subject to the\nconditions it may impose;\n(jj) Regulate cockpits, cockfights and the keeping or training of gamecocks, subject to existing guidelines\npromulgated by the Philippine Gamefowl Commission; and\n(kk) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE FOUR\nTHE CITY SECRETARY"}},{"id":"PH-H15202-A178","no":178,"noLabel":{"en":"Section 178"},"text":{"en":"Appointment, Compensation, Powers and Duties. -\n(1) There shall be a city secretary who shall be appointed by the city mayor with the concurrence of the\nsangguniang panlungsod, in accordance with civil service law, rules and regulations, whose compensation,\nallowances, and other emoluments shall be provided by law or ordinance.\n(2) The city secretary shall:\n(a) Be responsible for keeping a full record of the proceedings of the sangguniang panlungsod and filing all\ndocuments relative thereto as part of the public records of the city;\n(b) Record in a book kept for the purpose all ordinances, resolutions and motions adopted by the sangguniang\npanlungsod with the dates of their approval and publication;\n(c) Keep the seal of the sangguniang panlungsod and affix the same, with his signature, to all ordinances and\nofficial acts of the said sanggunian, which he shall present for signature to the presiding officer;\n(d) Keep the corporate seal of the city and affix the same with his signature on all ordinances and resolutions,\nand on all other official documents and papers signed by the city mayor, as may be required by law or\n(e) Attest to all executive orders, proclamations, ordinances and resolutions signed by the city mayor;\n(f) Upon request, furnish certified copies of all city records and documents in his charge which are not of a\nconfidential character, and charge such fees as may be prescribed by ordinance or resolution of the\nsangguniang panlungsod, to be paid directly to the city treasurer;\n\n(g) Keep his office and all records therein which are not of a confidential character open to the public during\nthe usual business hours; and\n(h) Exercise such other powers and perform such other duties and functions as may be prescribed by law or"}},{"id":"PH-H15202-A179","no":179,"noLabel":{"en":"Section 179"},"text":{"en":"Enactment of Ordinances. - The affirmative vote of a majority of the members of the\nsangguniang panlungsod shall be necessary for the passage of any ordinance, or of any resolution or motion\ndirecting the payment of money or creating liability, but other measures shall prevail upon the majority vote\nof the members present, there being a quorum, at any session duly called and held. The \"ayes\" and \"nays\"\nshall be taken and recorded upon the passage of all ordinances, upon all resolutions or motions directing the\npayment of money or creating liability, and at the request of any member, upon any other resolution or\nmotion. Each approved ordinance, resolution or motion shall be sealed with the seal of the sangguniang\npanlungsod and recorded in a book kept for the purpose and shall, on the day following its passage, be posted\nby the city secretary at the main entrance of the city hall and in at least two other public and conspicuous\nplaces, and shall take effect and be in force as provided in this Code unless otherwise stated in said ordinance,\nresolution or motion, or vetoed by the city mayor."}},{"id":"PH-H15202-A180","no":180,"noLabel":{"en":"Section 180"},"text":{"en":"Approval of Ordinances by the Mayor; Veto Power. -\n(1) All ordinances, and any resolution or motion directing the payment of money or creating liability, enacted\nor adopted by the sangguniang panlungsod shall be forwarded to the mayor. Within ten days after the receipt\nof the ordinance, resolution or motion, the mayor shall return it with his approval or veto. If he does not return\nit within that time, it shall be deemed approved. If he returns it with his veto, his reasons therefor in writing\nshall accompany it. A vetoed ordinance, if repassed by a two-thirds vote of all the members of the\nsangguniang panlungsod, shall take effect as provided in this Code.\n(2) The mayor shall have the power to veto any particular item or items of an appropriation ordinance, or of an\nordinance, resolution or motion directing the payment of money or creating liability, but the veto shall not\naffect the item or items to which he does not object. The item or items objected to shall not take effect except\nin the manner provided in the preceding section. Should an item or items in an appropriation ordinance be\ndisapproved by the mayor, the corresponding item or items in the appropriation ordinance of the previous year\nshall be deemed reenacted.\nARTICLE FIVE\nTHE CITY TREASURER"}},{"id":"PH-H15202-A181","no":181,"noLabel":{"en":"Section 181"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The city treasurer shall be appointed by the President of the Philippines, upon recommendation of the\nMinister of Finance, subject to civil service law, rules and regulations. The city treasurer shall take charge of\nthe city treasury office and act as the chief financial officer of the city.\n(2) No person shall be appointed city treasurer unless he is a citizen of the Philippines, of good moral\ncharacter, a holder of a college degree preferably in law, commerce or public administration from a\nrecognized college or university, a first grade civil service eligible or its equivalent, and has been in the\ntreasury or accounting service for at least five years, two of which as an assistant city treasurer.\n(3) The city treasurer shall receive such compensation, allowances and other emoluments as may be provided\nby law or ordinance.\n(4) The city treasurer shall:\n(a) Advise the city mayor, the sangguniang panlungsod, other city officials, and the national officers\nconcerned with the disposition of property of the city government;\n(b) Collect taxes throughout the city, including national, provincial and municipal taxes and other revenues\nauthorized by law;\n\n(c) Take custody of and exercise supervision over all city funds and property, including city buildings and\ngrounds and, subject to the approval of the city mayor, assign rooms to city officers and other public officials\nwho by law are entitled to office space in the city buildings;\n(d) Make annual reports to the mayor of all income disbursements, and acquisition and disposition of all assets\nof the city during the period, and furnish copies thereof to the sangguniang panlungsod and to all department\nheads of the city government;\n(e) Take charge of the disbursement of all city and other funds the custody of which may be entrusted to him\nby law or other competent authority;\n(f) Upon designation by the Minister of Finance, act as treasury fiscal examiner in the city under the\nadministrative authority of the Treasurer of the Philippines in accordance with pertinent rules and regulations;\n(g) Inspect, under the authority of the sangguniang panlungsod, the operation of public utilities belonging to,\nleased or operated by, the city government, such as telegraph and telephone, land and water transportation,\nwaterworks, electric-light plants, irrigation systems, bonded warehouses, ferries, slaughterhouses, and other\ncommercial and industrial enterprises of the city and all private commercial and industrial establishments\nwithin the city in relation to city tax ordinances; and\n(h) Perform such other duties as may be required by law or ordinance."}},{"id":"PH-H15202-A182","no":182,"noLabel":{"en":"Section 182"},"text":{"en":"The Assistant City Treasurer. -\n(1) There shall be an assistant city treasurer who shall be appointed by the Minister of Finance upon the\nrecommendation of the city mayor, subject to civil service law, rules and regulations. When the exigency of\nthe service so requires, additional positions for assistant city treasurers may be created.\n(2) No person shall be appointed assistant city treasurer unless he is a citizen of the Philippines, of good moral\ncharacter, a holder of a college degree preferably in law, commerce or public administration from a\nrecognized college or university, a first grade civil service eligible or its equivalent, and has had at least five\nyears experience in the treasury or accounting service, the last two years of which as administrative deputy or\nits equivalent.\n(3) The assistant city treasurer shall receive such compensation, allowances and other emoluments as may be\nprovided by law or ordinance.\n(4) The assistant city treasurer shall assist the city treasurer and perform such duties as the latter may assign to\nhim. He shall have authority to administer oaths concerning notices and notifications to those delinquent in the\npayment of the real property tax and concerning official matters relating to the accounts of the city treasurer or\notherwise arising in the offices of the city treasurer and the city assessor.\nARTICLE SIX\nTHE CITY ASSESSOR"}},{"id":"PH-H15202-A183","no":183,"noLabel":{"en":"Section 183"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The city assessor shall be appointed by the President of the Philippines upon recommendation of the\nMinister of Finance, subject to civil service law, rules and regulations.\n(2) No person shall be appointed city assessor unless he is a citizen of the Philippines, of good moral\ncharacter, a holder of a degree preferably in law, civil or mechanical engineering, commerce or any other\nrelated course from a recognized college or university, a first grade civil service eligible on its equivalent, and\nhas acquired experience in real property assessment work or in any related field for at least five years.\n(3) The city assessor shall receive compensation, allowances and other emoluments as may be provided by\nlaw or ordinance.\n(4) The city assessor shall:\n(a) Establish a systematic method of assessment of real property in the manner prescribed by law and in\n\naccordance with rules and regulations issued by the Minister of Finance;\n(b) Install and maintain a real property identification and accounting system conforming to the standards\nprescribed by the Minister of Finance;\n(c) Prepare, install and maintain a system of tax mapping showing graphically all property subject to\nassessment in the city and gather all necessary data concerning the same;\n(d) Make frequent physical surveys to check and determine whether all real property within the city are\nproperty listed in the assessment rolls;\n(e) Appraise all items of real property at current market value in accordance with law and conduct regular\nocular inspections to determine if all properties are assessed correctly;\n(f) Keep a correct record of all transfers, leases, and mortgages of real property, rentals, insurance, and cost of\nconstruction of buildings and other improvements on land and land income for assessment purposes;\n(g) Apply uniformly the assessment levels fixed by law to the current market value of all property subject to\nassessment;\n(h) Cancel assessments, in case several assessments have been made for the same property, except the one\nproperly made, but if any assessee or his representative shall object to the cancellation of the assessment made\nin his name, such assessment shall not be cancelled but the fact shall be noted on the tax declaration and\nassessment rolls and other property books and records. Preference, however, shall be given to the assessment\nof the person who has the best title to the property, or in default thereof, of the person who has possession of\nthe property;\n(i) Eliminate from the assessment roll of taxable property those which have been destroyed or which, being\nexempted, have been improperly included in the same; decrease the assessment where property previously\nassessed has suffered a permanent loss of value by reason of storm, flood, fire or other calamity; and increase\nthe assessment where improvements have been made upon the property subsequent to the last assessment;\n(j) Attend personally or through his duly authorized representative all sessions of the local board of\nassessment appeals and present any information or record in his possession may be required by the board in\ndetermining the correct assessment of the real property under appeal;\n(k) Issue certificates pertaining to, or issue certified copies of the assessment records of, real property and all\nother records relative to its assessment upon payment of a service charge or fee fixed therefor by the\nsangguniang panlungsod;\n(l) Make a report every semester of all assessments during said period and submit copies of said report to all\nthe officials of the city government including the sangguniang barangays; and\n(m) Exercise such other powers and perform such other duties and functions as may be prescribed by law or"}},{"id":"PH-H15202-A184","no":184,"noLabel":{"en":"Section 184"},"text":{"en":"The Assistant City Assessor. -\n(1) There shall be an assistant city assessor who shall be appointed by the Minister of Finance upon\nrecommendation of the city mayor, subject to civil service law, rules and regulations.\n(2) No person shall be appointed assistant city assessor unless he is a citizen of the Philippines, of good moral\ncharacter, a holder of a degree preferably in law, civil or mechanical engineering, commerce or any related\ncourse from a recognized college or university, a first grade civil service eligible or its equivalent, and has\nacquired experience in real property assessment work or in any related field for at least three years.\n(3) The assistant city assessor shall receive such compensation, allowances and other emoluments as may be\nprovided by law or ordinance.\n(4) The assistant city assessor shall assist the city assessor and perform such duties as the latter may assign to\nhim. He shall have the authority to administer oaths on all declarations of real property for purposes of\n\nassessment.\nARTICLE SEVEN\nTHE CITY ENGINEER"}},{"id":"PH-H15202-A185","no":185,"noLabel":{"en":"Section 185"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The city engineer shall be appointed by the city mayor, subject to civil service law, rules and regulations.\n(2) No person shall be appointed city engineer unless he is a citizen of the Philippines, of good moral\ncharacter, a licensed civil engineer, and has been an assistant city engineer or has engaged in the practice of\nhis profession for at least five years.\n(3) The city engineer shall receive such compensation, emoluments and allowances as may be determined by\nlaw or ordinance.\n(4) The city engineer shall:\n(a) Take charge of all the surveying and engineering works of the city, and perform such services in\nconnection with public improvements, or any work entered upon or projected by the city or any office thereof,\nas may require the skill and experience of a civil engineer;\n(b) Ascertain, record and establish monuments of the city surveys and from thereon extend the surveys of the\ncity, and locate, establish, and survey all city property and also private property abutting on the same,\nwhenever directed by the city mayor;\n(c) Prepare and submit plans, maps, specifications, and estimates for buildings, streets, bridges, docks, and\nother public works, and supervise the construction and repair of the same;\n(d) Make such tests and inspections of engineering materials used in construction and repair as may be\nnecessary to protect the city from the use of materials of a poor or dangerous quality;\n(e) Prevent the encroachment of private buildings and fences on the streets and public places of the city;\n(f) Conduct general supervision and inspection of all private docks and landing places and other property\nbordering on the rivers, esteros, and waterways of the city, and issue permits for the construction, repair and\nremoval of the same, and enforce all ordinances relating to the same;\n(g) Supervise the laying of mains and connections for the purpose of supplying gas to the residents of the city;\n(h) Periodically inspect and report on the conditions of public property and public works to the sangguniang\npanlungsod and the city mayor;\n(i) Regulate and supervise the location and use of engines, boilers, forges, and other manufacturing and\nheating appliances in accordance with law and ordinance relating thereto, and charge fees, at rates to be fixed\nby the sangguniang panlungsod for services and supplies furnished by his office;\n(j) Inspect and supervise the construction, repair, removal and safety of private buildings, and regulate and\nenforce the numbering of houses in accordance with ordinances of the city;\n(k) With the previous approval of the city mayor in each case, order the removal of materials employed in the\nconstruction or repair of any building or structure made in violation of law or ordinance, and cause buildings\nand structures dangerous to the public to be made secure or torn down;\n(l) File and preserve all maps, plans, notes, surveys and other papers and documents pertaining to his office;\n(m) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\n(5) In the absence of a city highways engineer, the Minister of Public Works and Highways may designate the\ncity engineer to act as ex officio city highways engineer.\n\nARTICLE EIGHT\nTHE CITY BUDGET OFFICER"}},{"id":"PH-H15202-A186","no":186,"noLabel":{"en":"Section 186"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The city budget officer shall be appointed by the city mayor subject to civil service law, rules and\nregulations.\n(2) No person shall be appointed city budget officer unless he is a citizen of the Philippines, of good moral\ncharacter, a holder of a degree preferably in law, commerce, public administration, or in any related course\nfrom a recognized college or university, a first grade civil service eligible or its equivalent, and has at least\nfive years experience in budgeting or in any related field.\n(3) The city budget officer shall receive such compensation, allowances and other emoluments as may be\ndetermined by law or ordinance.\n(4) The city budget officer shall take charge of the city budget office and provide technical and staff services\nto the city mayor and other city officials on budget matters. He shall:\n(a) Advice the city mayor on the orders and circulars to be issued on all budgetary and appropriation matters;\n(b) Consult and coordinate with the city treasurer on the projection of the estimated income of the city for the\nensuing calendar year;\n(c) Review and consolidate the budget proposals of the different offices of the city government and of the\nbarangays under the jurisdiction of the city;\n(d) Assist the city mayor in the preparation of the annual executive and special budgets;\n(e) Evaluate allotment requests and submit his recommendations to the city mayor;\n(f) Study and evaluate budgetary implications of proposed legislation and submit comments and\nrecommendations thereon;\n(g) Submit quarterly budgetary reports to the Office of Budget and Management; and\n(h) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE NINE\nTHE CITY PLANNING AND DEVELOPMENT COORDINATOR"}},{"id":"PH-H15202-A187","no":187,"noLabel":{"en":"Section 187"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The city planning and development coordinator shall be appointed by the city mayor, subject to civil\nservice law, rules and regulations.\n(2) No person shall be appointed city planning and development coordinator unless he is a citizen of the\nPhilippines, of good moral character, a holder of a degree preferably in law, civil engineering, commerce,\npublic administration or any related course from a recognized college or university, a first grade civil service\neligible or its equivalent, and has at least five years of experience in planning or in any related field.\n(3) The city planning and development coordinator shall receive such compensation, emoluments and\nallowances as may be determined by law or ordinance.\n(a) Formulate an integrated economic, social, physical and other development objectives and policies for the\nconsideration and approval of the sangguniang panlungsod and the city mayor;\n(b) Conduct continuing studies, researches, and relevant training necessary to evolve plans and programs for\nimplementation;\n(c) Integrate and coordinate all sectoral plans and studies undertaken by the different functional group or\n\n(d) Monitor and evaluate the implementation of the different development programs, projects and activities in\n(e) Prepare comprehensive plans and other development planning documents;\n(f) Analyze the city income and expenditure patterns, and formulate and recommend fiscal plans and policies\nfor the consideration and approval of the sangguniang panlungsod and the city mayor;\n(g) Promote citizen participation through development planning at the barangay level;\n(h) Exercise general supervision and control of the day-to-day activities of the city planning and development\noffice personnel; and\n(i) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\n(5) In the performance of the above functions, all personnel presently performing planning and development\nfunctions in the office of the city mayor shall be given preference in the appointment to commensurate\npositions in the office of the city planning and development coordinator.\nADDITIONAL MANDATORY OFFICIALS AND OFFICES IN HIGHLY URBANIZED CITIES\nARTICLE ONE\nTHE CITY LEGAL OFFICER"}},{"id":"PH-H15202-A188","no":188,"noLabel":{"en":"Section 188"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The city legal officer shall be appointed by the city mayor, subject to civil service law, rules and\nregulations.\n(2) No person shall be appointed city legal officer unless he is a citizen of the Philippines, of good moral\ncharacter, a member of the Philippine Bar, and has acquired experience in the practice of his profession for at\nleast five years.\n(3) The city legal officer shall receive such compensation, emoluments and allowances as may be determined\nby law or ordinance.\n(4) The city legal officer shall be the chief legal adviser of the city and all offices thereof, and as such shall:\n(a) Represent the city in all civil cases wherein the city or any officer thereof, in his official capacity, is a\n(b) When required, draft ordinances, contracts, bonds, leases and other instruments, involving any interest of\nthe city, and inspect and pass upon any such instruments already drawn;\n(c) Give his opinion in writing, when requested by the mayor or the sangguniang panlungsod, upon any\nquestion relating to the city or the rights or duties of any city officer;\n(d) Investigate or cause to be investigated any city officer for neglect or misconduct in office, or any person,\nfirm or corporation holding any franchise or exercising any public privilege from the city for failure to comply\nwith any condition, or to pay any consideration mentioned in the grant of such franchise or privilege, and\nrecommend appropriate action to the sangguniang panlungsod and the city mayor;\n(e) Institute and prosecute in the city's interest when directed by the mayor, a suit on any bond, lease, or other\ncontract upon any breach or violation thereof; and\n(f) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE TWO\n\nTHE CITY CIVIL REGISTRAR"}},{"id":"PH-H15202-A189","no":189,"noLabel":{"en":"Section 189"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. - There shall be a city civil\nregistrar who shall be appointed by the city mayor subject to civil service law, rules and regulations.\n(2) No person shall be appointed city civil registrar unless he is a citizen of the Philippines, of good moral\ncharacter, a holder of a college degree and a first grade civil service eligible or its equivalent.\n(3) The city civil registrar shall receive such compensation, emoluments and allowances as may be determined\nby law or ordinance.\n(4) The city civil registrar shall be responsible for the civil registration program in the city. Pursuant to the\ncivil registry law, the Civil Code, and other pertinent laws and rules and regulations issued to implement\nthem, he shall:\n(a) Accept all registrable documents including judicial decrees affecting the civil status of persons;\n(b) File, keep and preserve in a secure place the books required by law and transcribe and enter immediately\nupon receipt all registrable documents and judicial decrees affecting the civil status of persons in the\nappropriate civil registry book;\n(c) Transmit to the Office of the Civil Registrar General, within the prescribed period, duplicate copies of\nregistered documents required by law;\n(d) Issue certified transcripts or copies of any certificate or registered document upon payment of the\nprescribed fees to the city treasurer;\n(e) Receive applications for issuance of marriage license and, after determining that the requirements\nincluding supporting certificates and publication thereof for the prescribed period have been complied with,\nissue the license upon payment of the authorized fee to the city treasurer;\n(f) Collaborate with census officers of the National Census and Statistics Office in conducting educational\ncampaign for vital registration and assist in the preparation of demographic and other statistics for the city;\n(g) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE THREE\nTHE CITY ADMINISTRATOR"}},{"id":"PH-H15202-A190","no":190,"noLabel":{"en":"Section 190"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The city administrator shall be appointed by the city mayor, subject to the civil service law, rules and\nregulations.\n(2) No person shall be appointed city administrator unless he is a citizen of the Philippines, of good moral\ncharacter, a holder of a degree preferably in law, commerce or public administration from a recognized\ncollege or university, a first grade civil service eligible or its equivalent, and has acquired experience in the\ndischarge of management functions for at least five years.\n(3) The city administrator shall receive such compensation, emoluments and allowances as may be determined\nby law or ordinance.\n(4) The city administrator shall:\n(a) Assist in coordinating the work of all the officers of the city, under the supervision, direction, and control\nof the city mayor, and for this purpose, he may convene the chiefs of offices and other officials of the city;\n(b) Establish and maintain a sound personnel program for the city designed to promote career development\nand uphold the merit principle in the city government service;\n\n(c) Direct and supervise the continuing study and analysis of the internal organization, management practices\nand operational procedures of the city government offices with the end in view of instituting effective\nadministrative reforms;\n(d) Maintain direct administrative supervision over all market personnel except market collectors;\n(e) Maintain and supervise cleanliness and beautification of all public markets and premises;\n(f) Formulate plans and policies for the establishment of new public markets;\n(g) Enforce all ordinances, rules and regulations pertaining to or covering the administration and operation of\npublic markets; and\n(h) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE FOUR\nTHE CITY VETERINARIAN"}},{"id":"PH-H15202-A191","no":191,"noLabel":{"en":"Section 191"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The city veterinarian shall be appointed by the mayor subject to civil service law, rules and regulations.\n(2) No person shall be appointed veterinarian unless he is a citizen of the Philippines, of good moral character,\na licensed doctor of veterinary medicine and has experience in the practice of his profession for at least five\n(3) The city veterinarian shall receive such compensation, emoluments and allowances as may be determined\nby law or ordinance.\n(4) The city veterinarian shall:\n(a) Advise the city mayor on all matters and affairs pertaining to the inspection of animals to be slaughtered\nfor human consumption, and regulation of slaughterhouses;\n(b) License and regulate the keeping of domestic animals;\n(c) Regulate and inspect poultry, milk and dairy products sold in public markets and grocery stores;\n(d) Enforce all laws and regulations for the prevention of cruelty to animals;\n(e) Take all necessary measures to prevent all forms of animal diseases; and\n(f) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE FIVE\nTHE CITY SOCIAL SERVICES AND DEVELOPMENT OFFICER"}},{"id":"PH-H15202-A192","no":192,"noLabel":{"en":"Section 192"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The city social services and development officer shall be appointed by the city mayor, subject to civil\nservice law, rules and regulations.\n(2) No person shall be appointed city social services and development officer unless he is a citizen of the\nPhilippines, of good moral character, a holder of a degree preferably in social work or any related course from\na recognized college or university, a first grade civil service eligible or its equivalent, and has acquired\nexperience in social work for at least five years.\n(3) The city social services and development officer shall receive such compensation, emoluments and\nallowances as may be determined by law or ordinance.\n(4) The city social services and development officer shall:\n(a) Administer and supervise the social services of the city;\n\n(b) Execute and enforce all laws and ordinances relating to social services;\n(c) Recommend to the sangguniang panlungsod the passage of ordinances as he may deem necessary for the\nbetter and more adequate extension of social services in the city;\n(d) Cooperate with and assist all sectors, agencies and organizations, public and private, in the implementation\nof their welfare and relief programs and activities; and\n(e) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE SIX\nTHE CITY GENERAL SERVICES OFFICER"}},{"id":"PH-H15202-A193","no":193,"noLabel":{"en":"Section 193"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The city general services officer shall be appointed by the city mayor, subject to civil service law, rules\nand regulations.\n(2) No person shall be appointed city general services officer unless he is a citizen of the Philippines, of good\nmoral character, a holder of a college degree, a first grade civil service eligible or its equivalent, and has\nacquired experience as supply and property management officer for at least five years.\n(3) The city general services officer shall receive such compensation, emoluments and allowances as may\ndetermined by law or ordinance.\n(4) The city general services officer shall:\n(a) Advise the city mayor and other city officials and employees on matters relative to general services\nmanagement;\n(b) Develop and prepare plans, programs and activities relative to general services in coordination with other\ncity departments or office heads for submission to the sangguniang panlungsod through the city mayor;\n(c) Implement laws, and the rules, regulations, standards and policies set by the sangguniang panlungsod to\npromote the economical, efficient and effective management of general services of the city government;\n(d) Administer the properties of the city government relative to their acquisition, storage, delivery, utilization,\nmaintenance and disposal;\n(e) Perform supply and property procurement and maintenance functions, including non-personal services of\nthe city government, and such other general services activities as the exigency of the service may require;\n(f) Take custody of and be accountable for all properties, real or personal, owned by the city government and\nthose extended to it in the form of donation, reparation, assistance and counterpart of joint projects;\n(g) With the approval of the city mayor, assign building or land space to city officials or other public officials,\nwho, by law, are entitled to such space;\n(h) Determine the reasonableness of rentals of city\ngovernment-owned properties, real or personal, for lease to public or private entities by the city government;\n(i) Determine the reasonableness of rentals of private properties that may be leased for the official use of the\ncity government;\n(j) Maintain and supervise janitorial, security, landscaping and other related services in all city public\nbuildings and other real property whether owned or leased by the city government;\n(k) Perform all other functions pertaining to supply and property management heretofore performed by the\ncity treasurer under various laws, rules and regulations;\n(l) Enforce policies on records management relative to records creation and maintenance, and perform\ndisposal action on disposable records of the city government; and\n\n(m) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\n(5) In the performance of the above powers and duties, all personnel performing property and supply\nmanagement functions in different units, departments or offices of the city shall be transferred to the city\ngeneral services office.\n(6) The incumbent chief of the property and supply division or section, property custodian, or property clerk\nin charge of the property division or section in the city treasurer's office shall be given preference in the\nappointment to the position of city general services officer.\nARTICLE SEVEN\nTHE CITY AGRICULTURIST"}},{"id":"PH-H15202-A194","no":194,"noLabel":{"en":"Section 194"},"text":{"en":"Appointment, Qualifications, Compensation, Powers, Duties and Functions. -\n(1) The city agriculturist shall be appointed by the city mayor, subject to civil service laws, rules and\nregulations.\n(2) No person shall be appointed city agriculturist unless he is a citizen of the Philippines, of good moral\ncharacter, a holder of a degree in agriculture from a recognized college or university, a first grade civil service\neligible or its equivalent, and has experience in the practice of his profession for at least five years.\n(3) The city agriculturist shall receive such compensation, allowances and other emoluments as may be\nprescribed by law or ordinance.\n(4) The city agriculturist shall:\n(a) Initiate, review, and recommend changes in policies and objectives, plans and programs, techniques,\nprocedures and practices in agricultural promotion and production;\n(b) Advise the city mayor on matters pertaining to agriculture;\n(c) Plan, supervise, and coordinate all agricultural projects and activities of the city government;\n(d) Coordinate with regulatory governmental agencies and assist in basic research on crops and animals, on\npreventive control of diseases and pests, and on agricultural matters in general; and\n(e) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nTHE PROVINCE\nROLE AND CREATION OF PROVINCES"}},{"id":"PH-H15202-A195","no":195,"noLabel":{"en":"Section 195"},"text":{"en":"Role of Provinces. - As a political unit comprised of a group of municipalities and component\ncities, the province shall serve as an effective mechanism in the development process and assume basically\narea-wide functions, roles and activities."}},{"id":"PH-H15202-A196","no":196,"noLabel":{"en":"Section 196"},"text":{"en":"Manner of Creation. - A province may be created, named and its boundaries defined, altered\nor modified, only by an Act of the Batasang Pambansa and subject to the approval by a majority of the votes\ncast in a plebiscite to be held in the unit or units affected. The plebiscite shall be conducted by the\nCommission on Elections within one hundred twenty days from the date of effectivity of said Act, unless\notherwise provided therein."}},{"id":"PH-H15202-A197","no":197,"noLabel":{"en":"Section 197"},"text":{"en":"Requisites for Creation. - A province may be created if it has a territory of at least three\nthousand five hundred square kilometers, a population of at least five hundred thousand pesos, an average\nestimated annual income, as certified by the Ministry of Finance, of not less than ten million pesos for the last\nthree consecutive years, and its creation shall not reduce the population and income of the mother province or\n\nprovinces at the time of said creation to less than the minimum requirements under this section. The territory\nneed not be contiguous if it comprises two or more islands.\nThe average estimated annual income shall include the income allotted for both the general and infrastructure\nfunds, exclusive of trust funds, transfers and nonrecurring income."}},{"id":"PH-H15202-A198","no":198,"noLabel":{"en":"Section 198"},"text":{"en":"Transition, Period for Existing Sub-Provinces. - Existing sub-provinces shall have until ten\nyears from the date of effectivity of this Code within which to meet the requirements prescribed in the\nforegoing section as to population and income: Provided, however, That within said period, sub-provinces\nshall continue to be governed by existing laws. Those who fail to do so within said period shall be deemed\nabolished and their component municipalities shall form part of the mother province, unless otherwise\nprovided by law.\nPROVINCIAL OFFICIALS IN GENERAL"}},{"id":"PH-H15202-A199","no":199,"noLabel":{"en":"Section 199"},"text":{"en":"Officials of the Provincial Government. -\n(1) There shall be in each province a governor, a vice-governor, members of the sangguniang panlalawigan, a\nprovincial secretary, a provincial treasurer, a provincial assessor, a provincial budget officer, a provincial\nengineer, a provincial agriculturist and a provincial planning and development coordinator.\n(2) Under the office of the provincial planning and development coordinator, a division, section or officer may\nbe provided for general services whenever appropriate.\n(3) The sangguniang panlalawigan may maintain existing offices not mentioned in paragraph (1) of his\nsection, or create such other offices as may be necessary to carry out the purposes of the provincial\ngovernment, or may consolidate the functions of any one of such offices with those of another in the interest\nof efficiency and economy.\n(4) The Minister of Local Government shall prescribe, in consultation with provinces, minimum standards and\nguidelines with respect to the organizational structure, staffing pattern and other relevant operational aspects\nof provinces according to needs.\n(5) In cases of absence, sickness, or incapacity of the chief of an office to act for any reason, resulting in a\ntemporary vacancy, the assistant chief of office or the officer next in rank, shall perform the duties of the chief\nof office concerned."}},{"id":"PH-H15202-A200","no":200,"noLabel":{"en":"Section 200"},"text":{"en":"Residence and Office. - During the incumbency of the governor he shall have his official\nresidence in the capital of the province. All elective and appointive officials shall hold office in the provincial"}},{"id":"PH-H15202-A201","no":201,"noLabel":{"en":"Section 201"},"text":{"en":"Permission to Leave Official Station. - No provincial official engaged in the discharge of\nofficial duties shall leave the province without the written permission of the governor. National officials\nassigned in the province, when called upon by the heads of their respective ministries or when they are to\nleave their official stations on official business, shall give written notice to the governor."}},{"id":"PH-H15202-A202","no":202,"noLabel":{"en":"Section 202"},"text":{"en":"Oath of Office. - The oaths of office of the provincial heads of offices upon being subscribed\nby them, shall be filed and preserved in the provincial government except those of the governor,\nvice-governor and members of the sangguniang panlalawigan which shall be filed and preserved in the\nMinistry of Local Government.\nOFFICIALS AND OFFICES COMMON TO ALL PROVINCES\nARTICLE ONE\nTHE PROVINCIAL GOVERNOR"}},{"id":"PH-H15202-A203","no":203,"noLabel":{"en":"Section 203"},"text":{"en":"Provincial Governor as Chief Executive of the Province; Powers and Duties. -\n\n(a) The governor shall be the chief executive of the provincial government and shall exercise such powers and\nduties as provided in this Code and other laws.\n(2) The governor shall:\n(a) Control all services and offices of the provincial government;\n(b) Determine the guidelines of provincial policy and be responsible to the sangguniang panlalawigan for the\nprogram of government;\n(c) Direct the formulation of provincial development plans programs, and once approved by the sangguniang\npanlalawigan, direct the execution and implementation of the same;\n(d) On the first regular session of the sangguniang panlalawigan in every calendar year and from time to time\nthereafter, present the program of government and recommend for the consideration of the said sanggunian\nsuch measures as he may deem necessary and proper;\n(e) Appoint the heads of offices and other employees of the provincial government whose salaries are entitled\nor mainly paid out of provincial funds and whose appointments are not herein otherwise provided for, and\nthose whom he may be authorize by law to appoint;\n(f) Represent the province in all its business transactions and sign on its behalf all bonds, contracts and\nobligations and other official documents made in accordance with law or ordinance;\n(g) Upon recommendation of the division superintendent of schools, exempt poor but deserving students from\nthe payment of tuition and other school fees;\n(h) Grant licenses or permits in accordance with law or provincial ordinances or revoke the same for violation\nof the conditions upon which they are granted;\n(i) Allocate and assign rooms to provincial and other public officials and employees who, by law, are entitled\nto office in the provincial capitol.\n(j) Determine according to law or ordinance the time, manner and place of payments of the salaries and wages\nof the officers and employees of the province;\n(k) Ensure that the acts of component cities and municipalities are within the scope of their assigned powers\nand functions;\n(l) Coordinate the administration of services rendered by national offices and agencies in the province;\n(m) Call upon any national official or employee stationed in the province to advise him on matters affecting\nthe province and make recommendations thereon;\n(n) Call a convention or meeting of any or all the heads of component political units and other local officials\nin the province at such place and time as he may designate;\n(o) In aid of his executive and administrative powers, require all officers and employees stationed in the\nprovince to make available to him such books, records and other papers as are in their custody, except those\nclassified by law as confidential;\n(p) Enforce laws, provincial ordinances and resolutions and issue the necessary orders for their faithful and\nproper enforcement and execution, and in pursuance thereof, he shall be entitled to carry the necessary\nfirearms within his territorial jurisdiction, subject to existing rules and regulations on the possession and\ncarrying of fire arms;\n(q) At least ten and one-half months before the beginning of each calendar year, require each head of office or\ndepartment to prepare and submit to him through the provincial budget officer, an estimate of the\nappropriation for the operation of each office or department during the ensuing calendar year, which estimate\nshall be prepared on the basis of programs, projects, activities and workloads, and such estimates of\nappropriations, after evaluation, shall form part of the executive budget of the province;\n\n(r) Finalize and submit to the sangguniang panlalawigan the annual budget of the province for the ensuing\ncalendar year on or before the time fixed in local budgeting regulations of the Office of Budget and\nManagement;\n(s) Insure that officers and employees of the province properly discharge their respective functions and duties;\n(t) Adopt measures to safeguard all the lands, buildings, records, monies, credits and other property and rights\nof the province;\n(u) Make known to the people of the component units of the province all general laws or governmental orders\nwhich especially concern them;\n(v) Cause to be instituted in accordance with law, administrative and/or judicial proceedings against any\nofficer or employee of the province or any elective official of its component units who may have committed\nany offense in the performance of his official functions and duties;\n(w) Cause to be instituted administrative and/or judicial proceedings in connection with the violation of\nordinances for the collection of taxes, fees and charges and the recovery of property and funds of the province\nand cause to be defended all suits against it, and otherwise protect its interest;\n(x) Visit, at least once in six months, the component units of the province to acquaint himself with local\nconditions, advise authorities, receive complaints on the official conduct of local officials and for other\n(y) Act on vacation, sick and maternity leaves of officers and employees appointed by him and commutation\nof the money value thereof;\n(z) Authorize trips outside the province of provincial officers and employees for a period not exceeding thirty\n(aa) Approve the commutation of the transportation and representation allowances of heads of offices and\nother officials of the province as authorized by law;\n(bb) Submit an annual report to the Ministry of Local Government which shall contain a resume of all matters\npertinent to the administration and progress of the province and full information as to its social and economic\nconditions, and submit supplemental reports when unexpected events and occurrences arise which are of\nimportance to the general welfare of the province; and\n(cc) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE TWO\nTHE VICE-GOVERNOR"}},{"id":"PH-H15202-A204","no":204,"noLabel":{"en":"Section 204"},"text":{"en":"Powers, Duties and Privileges. -\n(1) The vice-governor shall be an ex officio member of the sangguniang panlalawigan with all the rights,\nduties and privileges of any member thereof.\n(a) Assume the office of the governor for the unexpired term of the latter in the cases provided for in Section\n48, paragraph (1) of this Code.\n(b) Exercise the powers and perform the duties and functions of the governor in the cases provided for in\nSection 52 of this Code.\n(c) Act as temporary presiding officer of the sangguniang panlalawigan in the event of inability of the\ngovernor to preside over a regular or special session on account of a trip on official business, absence on\nleave, sickness or any other temporary incapacity; and\n(d) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\n\nARTICLE THREE\nTHE SANGGUNIANG PANLALAWIGAN"}},{"id":"PH-H15202-A205","no":205,"noLabel":{"en":"Section 205"},"text":{"en":"Composition. -\n(1) Each provincial government shall have a provincial legislature hereinafter known as the sangguniang\npanlalawigan, upon which shall be vested the provincial legislative power.\n(2) The sangguniang panlalawigan shall be composed of the governor, the vice-governor, elective members of\nthe said sanggunian, and the presidents of the katipunang panlalawigan and the kabataang barangay provincial\nfederation who shall be appointed by the President of the Philippines.\n(3) Each province shall elect six (6) members of the sangguniang panlalawigan at large: Provided, That\nprovinces with a population of more than one million inhabitants shall have eight (8) elective sanggunian\nmembers: and Provided, further, That existing provinces with a population of less than one hundred\ninhabitants shall have four (4) elective sanggunian members."}},{"id":"PH-H15202-A206","no":206,"noLabel":{"en":"Section 206"},"text":{"en":"Sessions. -\n(1) The sangguniang panlalawigan shall hold regular sessions a month for the transaction of business on days\nwhich shall be fixed by resolution and such number of special sessions as may be called by the governor, but\nno two sessions shall be held in one day.\n(2) Meetings of the sangguniang panlalawigan shall be open to the public, unless otherwise ordered by an\naffirmative vote of the majority of all the members present, there being a quorum.\n(3) The governor, who shall be the presiding officer of the sangguniang panlalawigan, shall not be entitled to\nvote except in case of a tie.\n(4) The sangguniang panlalawigan shall adopt its own rules of procedure, keep a record of its proceeding and\nfor disorderly conduct during sessions, with the concurrence of two-thirds of all its members, reprimand,\nexclude from the session, or suspend for not more than sixty days an erring member."}},{"id":"PH-H15202-A207","no":207,"noLabel":{"en":"Section 207"},"text":{"en":"Quorum. - A majority of all the members of the sangguniang panlalawigan shall constitute a\nquorum for the transaction of business. A smaller number may adjourn from day to day but may compel the\nimmediate attendance of any member absent without good cause by issuing to the Integrated National Police\nof the city or municipality where the provincial capital is situated, and order for his arrest and appearance at\nthe session hall under pain or penalty as prescribed by ordinance,"}},{"id":"PH-H15202-A208","no":208,"noLabel":{"en":"Section 208"},"text":{"en":"Powers and Duties. - The sangguniang panlalawigan shall:\n(a) Enact such ordinances as may be necessary to carry into effect and discharge the responsibilities conferred\nupon it by law, and such as shall be necessary and proper to provide for the health, safety, comfort and\nconvenience, maintain peace and order, improve public morals, and promote the prosperity and general\nwelfare of the province and its inhabitants;\n(b) Prescribe reasonable limits and restraints on the use of property, and for violation of ordinances, provide\nfor imposition of a fine not exceeding one thousand pesos or six months imprisonment, or both such fine and\nimprisonment, at the discretion of the court;\n(c) Levy taxes for general and special purposes and fix the taxes thereof in accordance with the provisions of\n(d) Impose and fix reasonable fees and charges for all services rendered by the province to private parties;\n(e) Upon the majority vote of all the members, authorize the governor to negotiate and contract loans and\nother forms of obligations in accordance with the provisions of this Code, or to float bonds for development\nprojects, subject to such limitations as may be provided by law;\n(f) Upon recommendation of the provincial governor, appropriate money for purposes not specified by law\n\nwhich will promote the general welfare of the province and its inhabitants;\n(g) Fix in accordance with law the number and salaries of officials and employees of the province paid from\nprovincial funds and provide for expenditures that are necessary for the proper conduct of the activities of the\nprovincial government;\n(h) Provide funds for the construction and maintenance and rental of buildings for the use of the province;\n(i) Provide for the establishment and maintenance of an adequate provincial jail and detention center and\nappropriate sufficient funds for the subsistence of prisoners and detainees;\n(j) Regulate and fix the license fees for sealing and licensing of weights and measures in conformity with law;\n(k) Provide or facilitate the establishment and maintenance of a waterworks system or district waterworks for\nsupplying water to inhabitants of its component cities and municipalities;\n(l) Review ordinance approved by the sanggunian of component cities and municipalities with the authority\ngranted by law;\n(m) Authorize the payment of compensation or additional compensation, as the case may be, to any officer or\nemployee, or to any person not in the government service appointed temporarily to fill a vacancy at a rate of\nsalary authorized for the position pursuant to law;\n(n) Provide for the establishment and operation of secondary and vocational schools and colleges subject to\nexisting laws and regulations and, with the advice of the division superintendent of schools, fix reasonable\nfees for instruction therein;\n(o) Provide for the establishment and maintenance of centers and facilities for the rehabilitation and\nreformation of vagrants, drug addicts, alcoholics, mendicants, prostitutes, juvenile delinquents and convicts on\nprobation or parole or who have served their sentence;\n(p) Adopt measures and issue regulations to protect the public from floods, conflagrations, typhoons,\ndroughts, earthquakes and other calamities and provide relief for persons suffering from the same;\n(q) Adopt measures and safeguards against pollution for the preservation of the natural eco-systems in the\nprovince, in consonance with approved standards on human settlements and environmental sanitation;\n(r) Provide for the construction, improvement, repair and maintenance of roads, bridges, waterways, parks and\nplaygrounds, and other public works, and regulate the use thereof;\n(s) Make provisions within the financial capacity of the province, for the care of the poor, the aged, the sick,\nor persons of unsound mind, the care and rehabilitation of delinquent and abandoned minors and other\ndisabled or handicapped persons;\n(t) Provide for the suppression of riots, vandalism, tumultuous affrays, disturbances and disorderly assemblies;\n(u) Adopt measures on quarantine as may from time to time be deemed desirable or necessary to prevent the\nintroduction and spread of diseases;\n(v) Adopt such measures as would enhance the full implementation of the agrarian reform program of the\ngovernment in coordination with the Ministry of Agrarian Reform; and\n(w) Exercise such other powers and perform such other duties and functions as may be prescribed by law or"}},{"id":"PH-H15202-A209","no":209,"noLabel":{"en":"Section 209"},"text":{"en":"Approval of Ordinances by the Governor; Veto Power. -\n(1) Every ordinance or resolution passed by the sangguniang panlalawigan shall be forwarded to the governor.\n(2) Within fifteen days after receipt of the ordinance or resolution, the governor shall return it with either his\napproval or his veto. If he does not return it within that time, it shall be deemed approved.\n(3) If the governor should consider the ordinance or resolution prejudicial to the public welfare, he may veto it\n\nby signifying to the sangguniang panlalawigan his disapproval thereof in writing. The sangguniang\npanlalawigan may, by two-thirds vote of all its members, pass an ordinance or resolution over the veto of the\ngovernor, in which case it shall become effective without his approval.\n(4) The governor shall have the power to veto any particular item or items of an appropriation ordinance or of\nan ordinance or resolution directing the payment of money or creating liability, but the veto shall not affect the\nitem or items to which he does not object. The item or items objected to shall not take effect unless the\nsangguniang panlalawigan overrides the veto in the manner provided in paragraph (3) of this section. The veto\npower of the governor shall be exercised only once upon an ordinance or resolution or upon an item or items\nin an appropriation ordinance."}},{"id":"PH-H15202-A210","no":210,"noLabel":{"en":"Section 210"},"text":{"en":"Appropriations. -\n(1) The governor shall submit to the sangguniang panlalawigan within the period prescribed by the Office of\nBudget and Management, as the basis of the general appropriations proposal, a budget of receipts based on\nexisting and proposed revenue measures and of expenditures. The form, content, and manner of preparation of\nthe budget shall be prescribed by law.\n(2) No provision or enactment shall be embraced in the general appropriations proposal unless it relates\nspecifically to some particular appropriations thereof. Any such provision or enactment shall be limited in\noperation to the appropriation to which it relates.\n(3) The procedure in approving appropriations for the sangguniang panlalawigan shall strictly follow the\nprocedure for approving appropriations for other provincial services and offices.\n(4) If, by the end of any fiscal year, the sangguniang panlalawigan shall have failed to pass the general\nappropriations for the ensuing fiscal year, the general appropriations ordinance for the preceding fiscal year\nshall be deemed reenacted and shall remain in force and effect until the general appropriations proposal is\npassed by the said sanggunian.\n(5) The sangguniang panlalawigan may appropriate funds as aid to institutions of a charitable, benevolent, or\nexceptional character only if the institution to be assisted is operated and maintained in the province, or in its\ncomponent city or municipality, or their component barangays.\nARTICLE FOUR\nTHE PROVINCIAL SECRETARY"}},{"id":"PH-H15202-A211","no":211,"noLabel":{"en":"Section 211"},"text":{"en":"Powers, Duties and Functions. -\n(1) There shall be a provincial secretary who shall be appointed by the provincial governor with the\nconcurrence of the sangguniang panlalawigan, in accordance with civil service law, rules and regulations, and\nwhose compensation, allowances and other emoluments shall be prescribed by law or ordinance.\n(2) The provincial secretary shall:\n(a) Attend meetings of the sangguniang panlalawigan keep a journal of its proceedings, and record other acts\nof the provincial government;\n(b) Keep the seal of the province and affix the same with his signature to all ordinances and other official acts\nof the sangguniang panlalawigan and present the same to the presiding officer for his signature;\n(c) Forward to the governor copies of approved ordinances, resolutions and motions;\n(d) Furnish upon request of any interested party certified copies of records of public character in his charge,\nupon payment to the provincial treasurer of such fees as may be prescribed by ordinance;\n(e) Record in a book kept for the purpose, all ordinances, resolutions and motions directing the payment of\nmoney or creating liability, enacted or adopted by the sangguniang panlalawigan, with the dates of passage\nand publication of the same;\n(f) Cause each ordinance passed to be published as herein provided;\n\n(g) Exercise general supervision over the staff of the sangguniang panlalawigan; and\n(h) Exercise such other powers and perform such other duties and functions as may be provided by law or\nARTICLE FIVE\nTHE PROVINCIAL TREASURER"}},{"id":"PH-H15202-A212","no":212,"noLabel":{"en":"Section 212"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The provincial treasurer shall be appointed by the President of the Philippines upon recommendation of\nthe Minister of Finance, subject to civil service law, rules and regulations. The provincial treasurer shall take\ncharge of the provincial treasury office and act as the chief financial officer of the province.\n(2) No person shall be appointed provincial treasurer unless he is a citizen of the Philippines, of good moral\ncharacter, a holder of a degree preferably in law, commerce or public administration from a recognized\ncollege or university, a first grade civil service eligible or its equivalent, and has at least five years of\nexperience in the treasury or accounting service, two of which as an assistant city or provincial treasurer.\n(3) The provincial treasurer shall receive such compensation, allowances and other emoluments as may be\nprovided by law or ordinance.\n(4) The provincial treasurer shall:\n(a) Advise the governor, the sangguniang panlalawigan and other provincial and national officers concerned\nwith the disposition of provincial funds on all matters relative to public finance;\n(b) Collect taxes throughout the province including national, provincial and municipal taxes and other\nrevenues authorized by law;\n(c) Take custody of and exercise supervision over all provincial funds;\n(d) Take charge of the disbursement and accounting of all provincial funds and other funds the custody of\nwhich may be entrusted to him by law or other competent authority;\n(e) Exercise administrative supervision and control over all treasury offices of component municipalities;\n(f) Inspect, under the authority of the sangguniang panlalawigan, all commercial and industrial enterprises of\nthe province and all private commercial and industrial establishments within the province in relation to local\ntax ordinances; and\n(g) Exercise such other powers and perform such other duties and functions as may be prescribed by law or"}},{"id":"PH-H15202-A213","no":213,"noLabel":{"en":"Section 213"},"text":{"en":"The Assistant Provincial Treasurer. -\n(1) There shall be an assistant provincial treasurer who shall be appointed by the Minister of Finance upon\nrecommendation of the provincial governor, subject to civil service laws, rules and regulations. When the\nexigency of the service so requires, additional positions for assistant provincial treasurers may be created.\n(2) No person shall be appointed assistant provincial treasurer unless he is a citizen of the Philippines, of good\nmoral character, a holder of a college degree preferably in law, commerce or public administration from a\nrecognized college or university, a first grade civil service eligible or its equivalent, and has at least five years\nexperience in the treasury or accounting service.\n(3) The assistant provincial treasurer shall receive such compensation, allowances and other emoluments as\nmay be provided by law or ordinance.\n(4) The assistant provincial treasurer shall assist the provincial treasurer and perform such duties as the latter\nmay assign to him. He shall have authority to administer oaths concerning notices and notifications to those\ndelinquent in the payment of the real property tax and concerning official matters relating to the accounts of\nthe provincial treasurer or otherwise arising in the offices of the provincial treasurer and the provincial\n\nARTICLE SIX\nTHE PROVINCIAL ASSESSOR"}},{"id":"PH-H15202-A214","no":214,"noLabel":{"en":"Section 214"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The provincial assessor shall be appointed by the President of the Philippines upon recommendation of the\nMinister of Finance, subject to civil service laws, rules and regulations.\n(2) No person shall be appointed provincial assessor unless he is a citizen of the Philippines, of good moral\ncharacter, a holder of a degree preferably in law, civil or mechanical engineering, commerce or any other\nrelated course from a recognized college or university, a first grade civil service eligible or its equivalent, and\nhas acquired experience in real property assessment work or in any related field for at least five years.\n(3) The provincial assessor shall receive such compensation, allowances and other emoluments as may be\nprovided by law or ordinance.\n(4) The provincial assessor shall:\n(a) Initiate, review, and recommend changes in policies and objectives, plans and programs, techniques,\nprocedures and practices in the assessment and revision of real property values;\n(b) Establish a systematic method of assessment;\n(c) Install and maintain a real property identification and accounting system;\n(d) Prepare, install and maintain a system of tax-mapping, showing graphically all property subject to\nassessment and gather all data concerning the same;\n(e) Make frequent physical surveys to check and determine whether all real property within the locality are\nproperly listed in the assessment rolls;\n(f) Appraise all real property at current market value and conduct regular ocular inspection to determine if\nthey are assessed correctly;\n(g) Keep a record of all transfers, leases, and mortgages of real property; rentals, insurance, and cost of\nconstruction of buildings and other improvements on land for assessment purposes;\n(h) Apply uniformly the assessment levels for the current market value of all property subject to assessment;\n(i) Cancel all assessments, except those which are properly made, in case several assessments have been made\nfor the same property;\n(j) Cancel, raise, or lower, as the case may require, the assessment of any parcel or item of real property in the\n(k) Issue certified copies of assessment records of real property and all other records relative to its assessment\nupon payment of a service charge or fee to the provincial treasurer;\n(l) Submit a report every semester of all assessments as well as cancellations and modifications of assessments\ndone during the period, to the governor, each member of the sangguniang panlalawigan, and all mayors of\ncomponent cities and municipalities; and\n(m) Exercise such other powers and perform such other duties and functions as may be prescribed by law or"}},{"id":"PH-H15202-A215","no":215,"noLabel":{"en":"Section 215"},"text":{"en":"The Assistant Provincial Assessor. -\n(1) The assistant provincial assessor shall be appointed by the Minister of Finance upon recommendation of\nthe provincial governor, subject to civil service law, rules and regulations.\n(2) No person shall be appointed assistant provincial assessor unless he is a citizen of the Philippines, of good\nmoral character, a holder of a degree preferably in law, civil or mechanical engineering, commerce or any\n\nrelated course from a recognized college or university, a first grade civil eligible or its equivalent, and has\nacquired experience in real property assessment work or in any related field for at least five years.\n(3) The assistant provincial assessor shall receive such compensation, allowances and other emoluments as\nmay be provided by law or ordinance.\n(4) The assistant provincial assessor shall assist the provincial assessor and perform such duties as the latter\nmay assign to him. He shall have the authority to administer oaths on all declarations of real property for\npurposes of assessment.\nARTICLE SEVEN\nTHE PROVINCIAL BUDGET OFFICER"}},{"id":"PH-H15202-A216","no":216,"noLabel":{"en":"Section 216"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The provincial budget officer shall be appointed by the governor, subject to civil service law, rules and\nregulations.\n(2) No person shall be appointed provincial budget officer unless he is a citizen of the Philippines, of good\nmoral character, a holder of a degree preferably in law, commerce, public administration or any related course\nfrom a recognized college or university, a first grade civil service eligible or its equivalent, and has acquired at\nleast five years experience in budgeting or in any related field.\n(3) The provincial budget officer shall receive such compensation, emoluments and allowances as may be\ndetermined by law or ordinance.\n(4) The provincial budget officer:\n(a) Exercise general supervision over the provincial budget office;\n(b) Prepare forms, orders and circulars embodying instructions on budgetary and appropriation matters for the\nsignature of the governor;\n(c) Review and consolidate the budget estimates of the different offices of the provincial government;\n(d) Supervise the preparation of executive and special budgets;\n(e) Assist the governor during budget hearings;\n(f) Study and evaluate budgetary implications of proposed legislation and submit comments and\nrecommendations thereon;\n(g) Submit periodic budgetary reports to the Office of Budget and Management;\n(h) Coordinate with the provincial treasurer for purposes of local government budgeting; and\n(i) Exercise such other powers and perform such other duties and functions as may be prescribed by law or"}},{"id":"PH-H15202-A217","no":217,"noLabel":{"en":"Section 217"},"text":{"en":"Budget Preparation. - Each provincial office shall submit its request for appropriation to the\nprovincial budget officer on or before the date fixed in accordance with existing rules and budgetary\nregulations.\nARTICLE EIGHT\nTHE PROVINCIAL ENGINEER"}},{"id":"PH-H15202-A218","no":218,"noLabel":{"en":"Section 218"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The provincial engineer shall be appointed by the governor, subject to civil service law, rules and\nregulations.\n(2) No person shall be appointed provincial engineer unless he is a citizen of the Philippines, of good moral\ncharacter, a licensed civil engineer, and with adequate background and experience in his profession for at least\n\n(3) The provincial engineer shall receive such compensation, emoluments and allowances as may be\nprescribed by law or ordinance.\n(4) The provincial engineer shall:\n(a) Initiate, review, and recommend changes in policies and objectives, plans and programs, techniques,\nprocedures and practices in infrastructure development and public works in general of the provincial\ngovernment;\n(b) Advise the governor on infrastructure, public works and engineering matters;\n(c) Exercise general supervision over all engineering offices of component units;\n(d) Administer, coordinate, supervise and control the construction, maintenance, improvement and repair of\nroads, bridges, and other engineering and public works project of the provincial government;\n(e) Promulgate rules and regulations necessary to carry out office objectives, policies and functions;\n(f) Provide engineering services to the province and its component units as well as to the barangays, including\ninvestigations and surveys, architectural and engineering designs, feasibility studies, and project management;\n(g) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE NINE\nTHE PROVINCIAL AGRICULTURIST"}},{"id":"PH-H15202-A219","no":219,"noLabel":{"en":"Section 219"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The provincial agriculturist shall be appointed by the governor, subject to civil service law, rules and\nregulations.\n(2) No person shall be appointed provincial agriculturist unless he is a citizen of the Philippines, of good\nmoral character, a holder of a degree in agriculture or any related courses from a recognized college or\nuniversity, and has acquired experience in the practice of his profession for at least five years.\n(3) The provincial agriculturist shall receive such compensation, emoluments and allowances as may be\ndetermined by law or ordinance.\n(4) The provincial agriculturist shall:\n(a) Initiate, review, and recommend changes in policies and objectives, plans and programs, techniques,\nprocedures, and practices in agricultural promotion and production;\n(b) Advise the governor on matters pertaining to agriculture;\n(c) Plan, supervise, and coordinate all agricultural projects and activities of the provincial government;\n(d) Coordinate with regulatory governmental agencies and assist in basic research on crops and animals, on\npreventive control of diseases and pests, and on agricultural matters, in general; and\n(e) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nARTICLE TEN\nTHE PROVINCIAL PLANNING AND DEVELOPMENT COORDINATOR"}},{"id":"PH-H15202-A220","no":220,"noLabel":{"en":"Section 220"},"text":{"en":"Appointment, Qualifications, Compensation, Powers and Duties. -\n(1) The provincial planning and development coordinator shall be appointed by the governor, subject to civil\nservice law, rules and regulations.\n(2) No person shall be appointed provincial planning and development coordinator unless he is a citizen of the\nPhilippines, of good moral character, a holder of a degree preferably in law, civil engineering, commerce,\n\npublic administration or any related course from a recognized college or university, a first grade civil service\neligible or its equivalent, and has at least five years experience in planning or in any related field.\n(3) The provincial planning and development coordinator shall receive such compensation, emoluments and\nallowances as may be determined by law or ordinance.\n(4) The provincial planning and development coordinator shall:\n(a) Formulated an integrated economic, social and physical and other development objective and policies for\nthe consideration and approval of the sangguniang panlalawigan and the governor;\n(b) Conduct continuing studies, researches, and relevant trainings necessary to evolve plans and programs for\nimplementation;\n(c) Integrate and coordinate all sectoral plans and studies undertaken by the different functional groups or\n(d) Monitor and evaluate the implementation of the different development programs, projects and activities in\nthe province;\n(e) Prepare comprehensive plans and other development planning documents;\n(f) Analyze the provincial income and expenditure patterns, and formulate and recommend fiscal plans and\npolicies for the consideration and approval of the sangguniang panlalawigan and the governor;\n(g) Promote citizen supervision and control of the day-to-day activities of the provincial planning and\ndevelopment office personnel; and\n(h) Exercise such other powers and perform such other duties and functions as may be prescribed by law or\nMISCELLANEOUS AND FINAL PROVISIONS\nPENAL PROVISION"}},{"id":"PH-H15202-A221","no":221,"noLabel":{"en":"Section 221"},"text":{"en":"Engaging in Business Transactions or Possessing Pecuniary Interest. - Any local government\nofficial and any person or persons dealing with him who violate the prohibitions provided in Section 41\nhereof, shall be punished with prision correccional or fine of not less than three thousand pesos (P3,000.00)\nnor more than ten thousand pesos (P10,000.00), or both such imprisonment and fine, at the discretion of the\nPROVISIONS FOR IMPLEMENTATION"}},{"id":"PH-H15202-A222","no":222,"noLabel":{"en":"Section 222"},"text":{"en":"Promulgation of Implementation Details. - The Minister of Local Government shall\npromulgate in detail the implementing circulars and the rules and regulations to carry out the various\nadministrative actions required for the initial implementation of this Code in such a manner as will ensure the\nleast disruption of on-going programs and projects."}},{"id":"PH-H15202-A223","no":223,"noLabel":{"en":"Section 223"},"text":{"en":"Sectoral Representation. - Representation for the agricultural and industrial labor sectors in the\nsangguniang panlalawigan shall be provided for in appropriate legislation."}},{"id":"PH-H15202-A224","no":224,"noLabel":{"en":"Section 224"},"text":{"en":"Free Insurance Coverage. - The Government Service Insurance System shall establish and\nadminister an appropriate system under which the punong barangays and sangguniang barangay members\nshall enjoy free insurance coverage as provided in this Code."}},{"id":"PH-H15202-A225","no":225,"noLabel":{"en":"Section 225"},"text":{"en":"Implementing Powers of the Government Service Insurance System. - For purposes of\nperforming its duties under the preceding section, the Government Service Insurance System is hereby\n\nempowered to issue rules and regulations and determine the appropriation needed to support the system, the\npremiums for which shall be borne by the national government and shall be recommended for inclusion\nannually in the General Appropriations Act."}},{"id":"PH-H15202-A226","no":226,"noLabel":{"en":"Section 226"},"text":{"en":"Inventory of Infrastructure and Other Community Facilities. -\n(1) Each local government unit shall conduct a periodic inventory of infrastructure and other community\nfacilities and undertake the maintenance, repair, improvement, or reconstruction of these facilities, through a\ncloser cooperation among the various agencies of the government operating within the province so that\nmaximum performance is achieved with minimum resources.\n(2) No infrastructure or community project within the territorial jurisdiction of any local government unit shall\nbe undertaken without the knowledge of the local unit head.\nTITLE THREE\nTRANSITORY PROVISIONS"}},{"id":"PH-H15202-A227","no":227,"noLabel":{"en":"Section 227"},"text":{"en":"Personnel Retirement and/or Benefits. - Any official or employee of a local government unit\nseparated from the service as a result of the reorganization effected under this Code shall, if entitled under the\nlaws then in force, receive the retirement and other benefits accruing thereunder."}},{"id":"PH-H15202-A228","no":228,"noLabel":{"en":"Section 228"},"text":{"en":"Records and Properties. - All records, equipment, buildings, facilities, and other properties of\nany office or body of a local government unit abolished or reorganized under this Code shall be transferred to\nthe office or body to which its powers, functions and responsibilities substantially pertain."}},{"id":"PH-H15202-A229","no":229,"noLabel":{"en":"Section 229"},"text":{"en":"Qualifications of Incumbent Officials. - The qualifications required of heads of offices and\ntheir assistants herein prescribed shall not apply to the incumbents at the time of the approval of this Code."}},{"id":"PH-H15202-A230","no":230,"noLabel":{"en":"Section 230"},"text":{"en":"Continuance of present Provincial-City Relations. - Notwithstanding the provisions of Section\n15 hereof, the relationship of component cities with the provinces in which they are geographically located\nshall continue to be governed by the pertinent provisions of their respective city charters until the assumption\nof office of local officials elected in the first regular local elections following the approval of this Code."}},{"id":"PH-H15202-A231","no":231,"noLabel":{"en":"Section 231"},"text":{"en":"Repeal of Charter Obligations. - Any provision of law or ordinance authorizing loans and\ngrants and directing subsidies between provinces and existing cities are hereby repealed: Provided, That all\namounts due and payable as of the approval of this Act shall remain outstanding in the books of each local\ngovernment unit, unless condoned, and: Provided, further, That all loans, grants and subsidies between\nprovinces and cities shall, thereafter, be governed by Section 16 of this Act.\nFINAL PROVISIONS"}},{"id":"PH-H15202-A232","no":232,"noLabel":{"en":"Section 232"},"text":{"en":"Separability Clause. - If, for any reason or reasons, any part or provision of this Code shall be\nheld to be unconstitutional or invalid, other parts or provisions hereof which are not affected thereby shall\ncontinue to be in full force and effect."}},{"id":"PH-H15202-A233","no":233,"noLabel":{"en":"Section 233"},"text":{"en":"Repealing Clause; Metropolitan Manila and the Sangguniang Pampook of Regions IX and\n(1) Except as otherwise provided herein, all laws, acts, city charters, decrees, executive orders, proclamations\nand administrative regulations, or part or parts thereof which are inconsistent with this Code are hereby\nrepealed or modified accordingly.\n(2) Until otherwise provided by law, nothing in this Code shall be understood to amend or repeal the pertinent\nprovisions of Presidential Decree No. 824 and Batas Pambansa Blg. 20, and all presidential decrees and\nissuances relevant to Metropolitan Manila and the Sangguniang Pampook of Regions IX and XII."}},{"id":"PH-H15202-A234","no":234,"noLabel":{"en":"Section 234"},"text":{"en":"Effectivity Clause. - Unless otherwise specifically provided herein, this Code shall take effect\none month after its publication in the Official Gazette.\n\nApproved: February 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15203"] = {"id":"PH-H15203","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 338  An Act Changing the Name of the sta. Cruz Elementary School in the Municipality of Pandan, Province of Antique, to VIdal Gileto Memorial School.","orig":"Batas Pambansa Blg. 338  An Act Changing the Name of the sta. Cruz Elementary School in the Municipality of Pandan, Province of Antique, to VIdal Gileto Memorial School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 338","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-02-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00338_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00338_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15203-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Sta. Cruz Elementary School in the Municipality of Pandan, Province of\nAntique, is changed to Vidal Gileto Memorial School."}},{"id":"PH-H15203-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: February 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15204"] = {"id":"PH-H15204","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 339  An Act Expanding the Curricular Offerings of the San Mariano Junior National Agricultural High School in the Municipality of San Mariano, Province of Isabela, Which Shall Hereafter Be Known as the Delfin Albano Memorial School of Agriculture and Technology.","orig":"Batas Pambansa Blg. 339  An Act Expanding the Curricular Offerings of the San Mariano Junior National Agricultural High School in the Municipality of San Mariano, Province of Isabela, Which Shall Hereafter Be Known as the Delfin Albano Memorial School of Agriculture and Technology."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 339","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-02-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00339_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00339_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15204-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The San Mariano Junior National Agricultural High School in the Municipality of San Mariano,\nProvince of Isabela, which shall hereafter be known as the Delfin Albano Memorial High School of\nAgriculture and Technology, shall offer a two-year course associate in agriculture for college students and\nshort-term courses geared to the skilled manpower needs intended for the out-of-school youths."}},{"id":"PH-H15204-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The sum-needed for the implementation of this Act shall be included in the appropriations for\nthe Ministry of Education and Culture intended for the expanded curricular offerings in the annual General\nAppropriations Act starting in 1983."}},{"id":"PH-H15204-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: February 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15205"] = {"id":"PH-H15205","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 340  An Act Expropriating Specified Parcels of Private Land Located Along F. Rein-Del Pan streets From Taft Avenue to Roxas Boulevard in the City of Pasay, Metropolitan Manila, for the Construction of the Epifanio De Los Santos Avenue (Edsa) Extension, the Edsa Outfall of the Manila and Suburb Flood Control and Drainage Project, and the \"Cut-Off\" of Estero Tripa De Gallina, and for Other Purposes.","orig":"Batas Pambansa Blg. 340  An Act Expropriating Specified Parcels of Private Land Located Along F. Rein-Del Pan streets From Taft Avenue to Roxas Boulevard in the City of Pasay, Metropolitan Manila, for the Construction of the Epifanio De Los Santos Avenue (Edsa) Extension, the Edsa Outfall of the Manila and Suburb Flood Control and Drainage Project, and the \"Cut-Off\" of Estero Tripa De Gallina, and for Other Purposes."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 340","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-02-17","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00340_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00340_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15205-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Any provision of existing law to the contrary notwithstanding, the specified parcels of private\nland, including improvements thereon, along F. Rein-del Pan Streets from Taft Avenue to Roxas Boulevard,\nin the City of Pasay, Metropolitan Manila, the technical descriptions of which are hereinbelow described, are\nhereby expropriated:\n\"1. A parcel of land (a portion of Lot No. 852 of the Cadastral Survey of Pasay, Cadastral Case No. 23,\nG.L.R.O. Cadastral Record No. 1368), situated in the Barrio of San Rafael, City of Pasay, Metro Manila,\nBounded on the northwest, point 3-16 by the remaining portion of Lot 852; on the east, along line 16-1, by\nF.B. Harrison street; on the southeast, along line 1-2, by P. Lovina Street; on the southwest, along line 2-3, by\nthe affected portion of Lot No. 3544, Pasay Cadastre, Beginning at a point marked \"1\" on plan, being S. 10°\n01?E., 285.21 meters from BLLM No. 5, Pasay Cadastre; thence S. 77° 03?W., 118.89 m. to point \"2\"; thence\nN. 06° 46?W., 52.83 m. to point \"3\", thence N. 77° 26?E., 36.48 m. to point \"4\"; thence N. 77° 12?E., 5.82\nm. to point \"5\"; thence N. 77° 45?E., 10.38 m. to point \"6\"; thence N. 78° 28?E., 10.38 m. to point \"7\";\nthence N. 79° 11?E., 10.38 m. to point \"8\"; thence N. 79° 54?E., 10.38 m. to point \"9\"; thence N. 80° 37?E.,\n10.38 m. to point \"10\"; thence N. 81° 20?E., 10.38 m. to point \"11\"; thence N. 82° 55?E., 1.58 m. to point\n\"12\"; thence N. 69° 19?E., 3.83 m. to point \"13\"; thence N. 47° 14?E., 3.83 m. to point \"14\"; thence N. 25°\n10?E., 3.38 m. to point \"15\"; thence N. 03° 06?E., 3.83 m. to point \"16\"; thence S. 09° 39?E., 58.52 m. to the\npoint of beginning, containing an area of six thousand sixty-seven square meters (6,067.00 Sq. M.), more or\n\"2. A parcel of land (a portion of Lot No. 3544 of the Cadastral Survey of Pasay, Cadastral Case No. 23,\nG.L.R.O. Cadastral Record No. 1368), situated in the Barrio of San Rafael, City of Pasay, Metro Manila.\nBounded on the north, along line 3-4, by the remaining portion of Lot 3544; on the east, along line 4-1, by the\naffected portion of Lot No. 852, Pasay Cadastre; on the south, along line 1-2, by P. Lovina Street; on the west,\nalong line 2-3 by the affected portion of Lot No. 854; (both Cadastral Record No. 1368). Beginning at a point\nmarked \"1\" on plan, being S. 12° 10?W., 314.344 meters from BLLM No. 5, Pasay Cadastre; thence S. 77°\n37?W., 29.93 m. to point \"2\"; thence N. 06° 46?W., 52.84 m. to point \"3\"; thence N. 77° 06?E., 29.99 m. to\npoint \"4\"; thence S. 06° 46?E., 52.83 m. to the point of beginning, containing an area of one thousand five\nhundred seventy-five square meters (1,575.00 Sq. M.), more or less.\n\"3. A parcel of land (a portion of Lot No. 854 of the Cadastral Survey of Pasay, Cadastral Case No. 23,\nG.L.R.O. Cadastral Record No. 1368), situated in the Barrio of San Rafael, City of Pasay, Metro Manila.\nBounded on the north, along line 1-2, by the remaining portion of Lot 854; on the east, along line 2-3, by the\naffected portion of Lot No. 3544, Cadastral Case No. 23; on the south, along line 3-4, by P. Lovina Street\n(former Del Pan Avenue); on the west, along line 4-5, by Lot No. 858 and along line 5-1, by affected portion\nof Lot No. 857 both Cadastral Case No. 23. Beginning at a point marked \"1\" on plan, being S. 26° 00?W.,\n\n298.75 meters from BLLM No. 5, Pasay Cadastre; thence N. 77° 00?E., 30.00 m. to point \"2\"; thence S. 06°\n46?E., 52.84 m. to point \"3\"; thence S. 77° 00?W., 30.00 m. to point \"4\"; thence N. 06° 46?W., 39.97 m. to\npoint \"5\"; thence N. 06° 48?W., 12.81 m. to the point of beginning, containing an area of one thousand five\nhundred seventy-five square meters (1,575.00 Sq. M.), more or less.\n\"4. A parcel of land (a portion of Lot No. 857 of the Cadastral Survey of Pasay, Cadastral Case No. 23,\nG.L.R.O. Cadastral Record No. 1368), situated in the Barrio of San Rafael, City of Pasay. Bounded on the\nnorth-west, along line 1-6, by the remaining portion of Lot 857; on the east, along line 6-7, by the affected\nportion of Lot 854, Cadastral Case No. 23; on the south; along line 7-8, by Lot No. 858, Cadastral Case No.\n23; on the west, along line 8-1, by Roxas Boulevard. Beginning at a point marked \"1\" on plan, being S. 41°\n00?W., 378.14 m. from BLLM No. 5, Pasay Cadastre; thence S. 23° 43?E., 3.71 m. to point \"2\"; thence S.\n45° 05?E., 3.71 m. to point \"3\"; thence S. 66° 31?E., 3.71 m. to point \"4\"; thence S. 87° 54?E., 3.71 m. to\npoint \"5\"; thence N. 77° 00?E., 108.69 m. to point \"6\"; thence S. 06° 48?E., 12.81 m. to point \"7\"; thence S.\n77° 00?W., 118.63 m. to point \"8\"; thence N. 07° 45?W., 22.78 m. to the point of beginning containing an\narea of one thousand five hundred thirty-seven square meters (1,537 Sq. M.), more or less.\n\"5. A parcel of land (a portion of Lot No. 654-B of the subdivision plan Psd-11871, being a portion of the\nCadastral Survey of Pasay G.L.R.O., Cadastral Record No. 1368), situated in the Barrio of San Rafael, City of\nPasay, Metro Manila. Bounded on the southwest, along line 1-6, by the remaining portion of Lot No. 654-B;\non the North, along line 6-7, by the affected portion of Lot No. 655, Pasay Cadastre; on the southeast, along\nline 7-1 by Taft Avenue. Beginning at a point marked \"1\" on plan, being N. 30° 42?E., 245.029 meters from\nBBM No. 7, Pasay Cadastre; thence N. 03° 01?W., 190 m. to point \"2\"; thence N. 10° 39?W., 2.21 m. to\npoint \"3\"; thence N. 18° 11?W., 2.22 m. to point \"4\"; thence N. 25° 38?W., 2.22 m. to point \"5\"; thence N.\n35° 16?W., 2.22 m. to point \"6\"; thence N. 89° 21?E., 7.82 m. to point \"7\"; thence S. 23° 28?W., 10.99 m. to\nthe point of beginning, containing an area of thirty-three square meters (33.00 Sq. M.), more or less.\n\"6. A parcel of land (a portion of Lot No. 834 of the Cadastral Survey of Pasay, Cadastral Case No. 23,\nG.L.R.O. Cadastral Record No. 1368), situated in the City of Pasay, bounded on the southeast, along lines\n1-2-3 by Lot No. 833, Pasay Cadastre; and on the southwest, along lines 3-4-5 by Calle F.B. Harrison; and on\nthe north, points 5-17-17-1 by the remaining portion of Lot 834; beginning at point marked \"1\" on plan, being\nS. 32° 17? 44\"E., 267.187 meters from BLLM No. 5, Pasay Cadastre; thence S. 9° 11?E., 11.579 m. to point\n\"2\"; thence S. 82° 10?W., 87.390 m. to point \"3\"; thence N. 10° 45? 58??W., 11.82 m. to point \"4\"; thence N.\n10° 46?W., 15.568 m. to point \"5\"; thence S. 15° 37? 27\"E., 3.287 m. to point \"6\"; thence S. 34° 32? 27??E.,\n3.287 m. to point \"7\"; thence S. 53° 26?50??E., 3.287 m. to point \"8\"; thence S. 72° 22? 51??E., 3.287 m. to\npoint \"9\"; thence N. 88° 40? 32??E., 3.287 m. to point \"10\"; thence N. 72° 00? 53??E., 6.480 m. to point\n\"11\"; thence N. 84° 55? 05??E., 10.375 m. to point \"12\"; thence N. 85° 38? 14??E., 10.375 m. to point \"13\";\nthence N. 86° 21? 10??E., 10.375 m. to point \"14\"; thence N. 87° 04? 18\"E., 10.375 m. to point \"15\"; thence\nN. 87° 97? 06\"E., 10.375 m. to point \"16\"; thence N. 88° 30? 11\"E., 10.375 m. to point \"17\"; thence N. 89°\n12? 56\"E., 9.422 m. to the point of beginning, containing an area of one thousand three hundred eighty square\nmeters (1,380.00 Sq. M.), more or less.\n\"7. A parcel of land (a portion of Lot No. 832 of the Cadastral Survey of Pasay, Cadastral Case No. 23,\nG.L.R.O. Cadastral Record No. 1368), situated in the Barrio of San Rafael, City of Pasay, Metro Manila.\nBounded on the north, along line 2-3, by Lot No. 833, Pasay Cadastre; on the northeast, along line 3-4, by P.\nCelle Street; on the south, along line 4-5, by the affected portion of Lot No. 826 and 5-6 by the affected\nportion of Lot No. 828, both of Pasay Cadastre; on the southwest, points 6-12, by the affected portion of Lot\n832; bounded on the west, along line 1-2, by F.B. Harrison Street. Beginning at a point marked \"1\" on plan,\nbeing S. 12° 59?E., 263.84 meters from BLLM No. 5, Pasay Cadastre; thence N. 08° 10?W., 4.00 m. to point\n\"2\"; thence, N. 83° 09?E., 175.72 m. to point \"3\"; thence S. 09 deg., 17?E., 47.87 m. to point \"4\"; thence S.\n81° 57?W., 35.73 m. to point \"5\"; thence S. 81° 57?W., 14.76 m. to point \"6\"; thence S. 68° 53?E., 1.45 m. to\npoint \"7\"; thence N. 87° 12?W., 9.63 m. to point \"8\"; thence N. 87° 55?W., 9.63 m. to point \"9\"; thence N.\n88° 38?W., 9.63 m. to point \"10\"; thence N. 89° 21?W., 9.63 m. to point \"11\"; thence N. 68° 56?W., 1.45 m.\n\nto point \"12\"; thence N. 09° 11?W., 39.16 m. to point \"13\"; thence S. 83° 09?W., 87.53 m. to the point of\nbeginning, containing an area of four thousand five hundred forty-four square meters and seven square\ndecimeters (4,544.07 Sq. M.), more or less.\""}}],"pack":"ph-p156"};
  FT["PH-H15206"] = {"id":"PH-H15206","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 341  An Act Changing the Name of the Bohol National High School in the City of Tagbilaran to Dr. Cecilio Putong National High School.","orig":"Batas Pambansa Blg. 341  An Act Changing the Name of the Bohol National High School in the City of Tagbilaran to Dr. Cecilio Putong National High School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 341","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-02-25","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00341_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00341_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15206-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Bohol National High School in the City of Tagbilaran is changed to Dr. Cecilio\nPutong National High School."}},{"id":"PH-H15206-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: February 25, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15207"] = {"id":"PH-H15207","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 342  An Act Changing the Name of the Bohol School of Arts and Trades in Tagbilaran City to Dr. Nemesio Agunod School of Arts and Trades.","orig":"Batas Pambansa Blg. 342  An Act Changing the Name of the Bohol School of Arts and Trades in Tagbilaran City to Dr. Nemesio Agunod School of Arts and Trades."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 342","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-02-25","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00342_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00342_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15207-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Bohol School of Arts and Trades in Tagbilaran City is changed to Dr. Nemesio\nAgunod School of Arts and Trades."}},{"id":"PH-H15207-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: February 25, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15208"] = {"id":"PH-H15208","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 343  An Act Creating Barangay Batasan Hills in Quezon City, Metropolitan Manila.","orig":"Batas Pambansa Blg. 343  An Act Creating Barangay Batasan Hills in Quezon City, Metropolitan Manila."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 343","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-02-25","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00343_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00343_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15208-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"A portion of Barangay Matandang Balara in Quezon City, Metropolitan Manila, is separated\ntherefrom and constituted into a new barangay to be known as Barangay Batasan Hills."}},{"id":"PH-H15208-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The new barangay shall include the area which is bounded by the National Government\nCenter-Batasan Complex to the boundary line of Barangay Silangan on the north; by the Marikina River on\nthe east; by the Don Mariano Marcos Avenue on the west; and by the Capitol Homes to the Marikina River on"}},{"id":"PH-H15208-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the areas\naffected within one hundred twenty days from the approval of this Act, the President of the Philippines shall\nappoint the first officials of the new barangay who shall hold office until their successors shall have been duly\nelected and qualified."}},{"id":"PH-H15208-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite herein provided, the\nexpenses for which shall be charged to local funds."}},{"id":"PH-H15208-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: February 25, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15209"] = {"id":"PH-H15209","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 344  An Act to Enhance the Mobility of Disabled Persons By Requiring Certain Buildings, Institutions, Establishments, and Public Utilities to Install Facilities and Other Devices.","orig":"Batas Pambansa Blg. 344  An Act to Enhance the Mobility of Disabled Persons By Requiring Certain Buildings, Institutions, Establishments, and Public Utilities to Install Facilities and Other Devices."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 344","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-02-25","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00344_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00344_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15209-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"In order to promote the realization of the rights of disabled persons to participate fully in the\nsocial life and the development of the societies in which they live and the enjoyment of the opportunities\navailable to other citizens, no license or permit for the construction, repair or renovation of public and private\nbuildings for public use, educational institutions, airports, sports and recreation centers and complexes,\nshopping centers or establishments, public parking places, workplaces, public utilities, shall be granted or\nissued unless the owner or operator thereof shall install and incorporate in such building, establishment,\ninstitution or public utility, such architectural facilities or structural features as shall reasonably enhance the\nmobility of disabled persons such as sidewalks, ramps, railings and the like. If feasible, all such existing\nbuildings, institutions, establishments, or public utilities may be renovated or altered to enable the disabled\npersons to have access to them: Provided, however, That buildings, institutions, establishments, or public\nutilities to be constructed or established or which licenses or permits had already been issued may comply\nwith the requirements of this law: Provided, further, That in case of government buildings, streets and\nhighways, the Ministry of Public Works and Highways shall see to it that the same shall be provided with\narchitectural facilities or structural features for disabled persons.\nIn the case of the parking place of any of the above institutions, buildings, or establishments, or public\nutilities, the owner or operator shall reserve sufficient and suitable space for the use of disabled persons."}},{"id":"PH-H15209-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"In case of public conveyance, devices such as the prominent awareness of the rights of the\ndisabled and foster understanding of their special needs. Special bus stops shall be designed for disabled\npersons. Discriminating against disabled persons in the carriage or transportation of passengers is hereby\ndeclared unlawful."}},{"id":"PH-H15209-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Minister of Public Works and Highways and the Minister of Transportation and\nCommunications; in coordination with the National Commission Concerning Disabled Persons, shall prepare\nthe necessary rules and regulations to implement the provisions of this Act."}},{"id":"PH-H15209-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Any person violating any provision of this Act or of the rules and regulations promulgated\nhereunder shall, upon conviction by a court of competent jurisdiction, suffer the penalty of imprisonment of\nnot less than one month but not more than one year or a fine of P2,000 to P5,000 or both, at the discretion of\nthe court: Provided, That in the case of corporations, partnerships, cooperatives or associations, the president,\nmanager or administrator, or the person who has charge of the construction, repair or renovation of the\nbuilding, space or utilities shall be criminally responsible for any violation of this Act and/or rules and\nregulations promulgated pursuant thereto."}},{"id":"PH-H15209-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"All laws, executive and administrative orders, rules and regulations inconsistent with the\nforegoing provisions are hereby repealed or amended accordingly."}},{"id":"PH-H15209-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: February 25, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15210"] = {"id":"PH-H15210","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 345  An Act Creating the Municipality of Nagtipunan, in the Province","orig":"Batas Pambansa Blg. 345  An Act Creating the Municipality of Nagtipunan, in the Province"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 345","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-02-25","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00345_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00345_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15210-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Barangays San Dionisio II, Anak, Ponggo, Landingan, Wasid, Matmad, San Ramos, San Pugo,\nLa Conwap, Sangbay, Mattaddi, Guino, and Old Gumiad, all within the Municipality of Maddela, Province of\nQuirino, are hereby separated from said municipality and constituted into a distinct and independent\nmunicipality in the same province to be known as the Municipality of Nagtipunan. The seat of government of\nthe new municipality shall be in Barangay Ponggo."}},{"id":"PH-H15210-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Municipality of Nagtipunan shall be bounded as follows:\nBounded on the N & NE, by the municipalities of Maddela and Aglipay, Quirino; on the S by the Province of\nAurora; on the SW & W by the Municipality of Dupax del Norte, Province of Nueva Vizcaya; and on the NW\nby the Municipality of Kasibu, Province of Nueva Vizcaya. Beginning at a point marked \"1\" which is\nidentical to corner 10 of the old technical description of the Municipality of Maddela and corner 6 of the old\ntechnical description of the Municipality of Aglipay, pursuant to Executive Order No. 368 dated November\n11, 1950; thence following Addalem River upstream in a general SW, SE direction or of straight bearing and\ndistance of S25° 00?W., 7,100 meters to point \"2\", junction of Addalem River and Cabonian creek; thence\nfollowing Cabonian creek upstream to its source of mountain peak with elevation of 1593 meters in a general\nSE & SW direction or of straight bearing and distance of S28° 00?E., 4,720 meters to point \"3\", mountain\npeak with elevation of 1595 meters; thence following connecting ridgeline or divide between\nDiduyon-Nalongtotan-Addalem-Gawagan rivers in a general SE & NE direction and passing thru mountain\npeak with elevation 1405, 1326, 1220 or of straight bearing and distance of N69° 00?E., 8,700 meters to point\n\"4\", source of Lacab creek; thence following Lacab creek downstream in a general SE direction or of straight\nbearing and distance of S32° 00?E., 1,380 meters to point \"5\", junction of Lacab creek and a tributary; thence\nfollowing a straight line S76° 15?E., 1,250 meters to point \"6\", source of Dipantan creek; thence following\nDipantan creek downstream in a general SE & NE direction or of straight bearing and distance of S82° 00?E.,\n5,500 meters to point \"7\", junction of Cagayan river and Dipantan creek; thence following Cagayan river\ndownstream in a general NE direction or of straight bearing and distance of N54° 15?E., 1,250 meters to point\n\"8\", junction of Dipantan creek and Cagayan river; thence N80° 15?E., 4,520 meters to point \"9\", junction of\nDidongol creek and Manglad river; thence following Didongol creek upstream in a general SE & NE direction\nor of straight bearing and distance of S70° 15?E., 3,440 meters to point \"10\", source of Didongol creek on a\nsaddle at dividing ridge between Manglad and Ngilinan river; thence following a tributary of Ngilinan river\ndownstream in a general NE & SE direction or of straight bearing and distance of S80° 30?E., 2,200 meters to\npoint \"11\", junction of Ngilinan river and a tributary; thence following connecting ridgeline in a general SE &\nNE direction and passing thru mountain peaks with elevations in meters of 640, 1332, 1770, 1524, 1090 and\n1546 or of straight bearing and distance of S74° 30?E., 10,250 meters to point \"12\", identical to corner 4 of\nthe old technical description of Maddela, saddle between tributaries of Namal creek; thence following a\nstraight line S49° 40?W., 58,850 meters to point \"13\", identical to corners 5 and 4 of the old technical\ndescription of Maddela and Dupax, respectively; thence following a straight line N06° 00?W., 16,200 meters\nto point \"15\", identical to corners 7 and 2 of the old technical description of Maddela and Dupax, respectively;\nthence following a straight line N04° 50?W., 10,300 meters to point \"16\", identical to corners 8, 1 and 7 of\nthe old technical description of Maddela, Dupax, and Bambang (now Kasibu), respectively; thence following\nstraight line 67° 31?E., 17,285 meters to point \"17\", identical to corners 9, 7 and 6 of the old technical\ndescription of Maddela, Aglipay, and Bambang (now Kasibu), respectively; thence following straight line\nN75° 00?E., 10,000 meters to the point of beginning; containing an approximate area of 160,740 hectares,\n\nmore or less.\nStraight bearing and distance between corners were determined by protractor and millimeter scale with\nmilitary maps (Scale 1:50,000) Sheet Nos. 3267 I; 3268 I & II; 3269 II; 3367 IV; 3368 I, II, III & IV; 3369 II\n& III; 3468 III & IV; 3469 III & IV as base reference. All available BFD Land Classification Maps and\nTimber License maps were also utilized as cross references regarding the names of creeks, rivers, barangays,\nsitios, and etc. Area was computed by the use of ruler planimeter."}}],"pack":"ph-p156"};
  FT["PH-H15211"] = {"id":"PH-H15211","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 346  An Act Establishing the Barotac VIejo Municipal Hospital in the Municipality of Barotac VIejo, Province of Iloilo.","orig":"Batas Pambansa Blg. 346  An Act Establishing the Barotac VIejo Municipal Hospital in the Municipality of Barotac VIejo, Province of Iloilo.","vi":"Đạo luật thành lập Bệnh viện Barotac VIejo Đô thị tại Thị trấn Barotac VIejo, Tỉnh Iloilo.","th":"พระราชบัญญัติจัดตั้งโรงพยาบาล Barotac VIejo เทศบาลในเทศบาล Barotac VIejo จังหวัด Iloilo.","id":"Undang-Undang membentuk Rumah Sakit Barotac VIejo Kotamadya di Kotamadya Barotac VIejo, Provinsi Iloilo.","ms":"Akta menubuhkan Hospital Barotac VIejo Perbandaran di Perbandaran Barotac VIejo, Wilayah Iloilo."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 346","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00346_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00346_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15211-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There is hereby established, under the direct supervision of the Office of the Minister, Ministry\nof Health, a ten-bed capacity municipality hospital in the Municipality of Barotac Viejo, Province of Iloilo, to\nbe known as the Barotac Viejo Municipal Hospital."}},{"id":"PH-H15211-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15211-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may be necessary for\nits operation maintenance shall be included in the annual General Appropriations Act. The Minister of Health\nshall determine the manner by which said hospital shall be made operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: March 18, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15212"] = {"id":"PH-H15212","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 347  An Act Establishing a Ten-Bed Capacity Municipal Hospital in the Municipality of Magsaysay, Province of Misamis Oriental, to Be Known as Magsaysay Municipal Hospital and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 347  An Act Establishing a Ten-Bed Capacity Municipal Hospital in the Municipality of Magsaysay, Province of Misamis Oriental, to Be Known as Magsaysay Municipal Hospital and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 347","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00347_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00347_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15212-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct control and supervision of the Ministry of Health, a\nten-bed municipal hospital in the Municipality of Magsaysay, Province of Misamis Oriental, to be known as\nMagsaysay Municipal Hospital."}},{"id":"PH-H15212-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the operation of the hospital shall be determined in accordance with"}},{"id":"PH-H15212-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"of Presidential Decree No. 1177 and charged to the appropriations authorized by Batas Pambansa\nBlg. 131 for the Ministry of Health intended for new hospitals. Thereafter, such sum as may be necessary for\nits operation and maintenance shall be included in the annual General Appropriations Act. The Minister of\nHealth shall determine the manner by which said hospital shall be made operational.\nSection 3. This Act shall take effect upon its approval.\nApproved: March 18, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15213"] = {"id":"PH-H15213","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 348  An Act Establishing the Sarangani Municipal Hospital in Balut Island, Municipality of Jose Abad Santos, Province of Davao Del Sur, and Providing Funds","orig":"Batas Pambansa Blg. 348  An Act Establishing the Sarangani Municipal Hospital in Balut Island, Municipality of Jose Abad Santos, Province of Davao Del Sur, and Providing Funds"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 348","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00348_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00348_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15213-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed capacity municipal hospital in Balut Island, Municipality of Jose Abad Santos, Province of\nDavao del Sur, to be known as Sarangani Municipal Hospital."}},{"id":"PH-H15213-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 131\nand Batas Pambansa Blg. 230 for the Ministry of Health intended for new or expanded hospitals. Thereafter,\nsuch sum as may be necessary for its operation and maintenance shall be included in the annual General\nAppropriations Act."}},{"id":"PH-H15213-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 18, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15214"] = {"id":"PH-H15214","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 349  An Act Providing for the Establishment of a Municipal Hospital in the Municipality of Tongkil, Province of Sulu, to Be Known as Tongkil Municipal Hospital, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 349  An Act Providing for the Establishment of a Municipal Hospital in the Municipality of Tongkil, Province of Sulu, to Be Known as Tongkil Municipal Hospital, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật thành lập Bệnh viện Đô thị tại Thị trấn Tongkil, Tỉnh Sulu với tên gọi Bệnh viện Tongkil Đô thị","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาลในเทศบาล Tongkil จังหวัด Sulu ในชื่อโรงพยาบาล Tongkil เทศบาล","id":"Undang-Undang membentuk Rumah Sakit Kotamadya di Kotamadya Tongkil, Provinsi Sulu dengan nama Rumah Sakit Tongkil Kotamadya","ms":"Akta menubuhkan Hospital Perbandaran di Perbandaran Tongkil, Wilayah Sulu dengan nama Hospital Tongkil Perbandaran"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 349","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00349_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00349_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15214-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed municipal in the Municipality of Tongkil, Province of Sulu, to be known as Tongkil\nMunicipal Hospital. The hospital shall be located at the poblacion of the said municipality."}},{"id":"PH-H15214-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 131\nand Batas Pambansa Blg. 230 for the Ministry of Health intended for new or expanded hospitals. Thereafter,\nsuch sum as may be necessary for its operation and maintenance shall be included in the annual General\nAppropriations Act."}},{"id":"PH-H15214-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 18, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15215"] = {"id":"PH-H15215","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 350  An Act Providing for the Establishment of a Municipal Hospital in the Municipality of Tapul, Province of Sulu, to Be Known as Tapul Municipal Hospital, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 350  An Act Providing for the Establishment of a Municipal Hospital in the Municipality of Tapul, Province of Sulu, to Be Known as Tapul Municipal Hospital, and Appropriating Funds therefor.","vi":"Đạo luật thành lập Bệnh viện Đô thị tại Thị trấn Tapul, Tỉnh Sulu với tên gọi Bệnh viện Tapul Đô thị","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาลในเทศบาล Tapul จังหวัด Sulu ในชื่อโรงพยาบาล Tapul เทศบาล","id":"Undang-Undang membentuk Rumah Sakit Kotamadya di Kotamadya Tapul, Provinsi Sulu dengan nama Rumah Sakit Tapul Kotamadya","ms":"Akta menubuhkan Hospital Perbandaran di Perbandaran Tapul, Wilayah Sulu dengan nama Hospital Tapul Perbandaran"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 350","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00350_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00350_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15215-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister, Ministry of\nHealth, a municipal hospital in the Municipality of Tapul, Province of Sulu, to be known as Tapul Municipal"}},{"id":"PH-H15215-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 131\nand Batas Pambansa Blg. 230 for the Ministry of Health intended for new or expanded hospitals. Thereafter,\nsuch sum as may be necessary for its operation and maintenance shall be included in the annual General\nAppropriations Act."}},{"id":"PH-H15215-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 19, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15216"] = {"id":"PH-H15216","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 351  An Act Providing for the Establishment of a Ten-Bed Capacity Municipal Hospital in the Municipality of Tambulig, Province of Zamboanga Del Sur, to Be Known as Tambulig Municipal Hospital, and Authorizing the Appropriation of Funds","orig":"Batas Pambansa Blg. 351  An Act Providing for the Establishment of a Ten-Bed Capacity Municipal Hospital in the Municipality of Tambulig, Province of Zamboanga Del Sur, to Be Known as Tambulig Municipal Hospital, and Authorizing the Appropriation of Funds"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 351","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00351_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00351_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15216-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed capacity municipal hospital in the Municipality of Tambulig, Province of Zamboanga del\nSur, to be known as Tambulig Municipal Hospital. The hospital shall be located at the poblacion of the said\nmunicipality."}},{"id":"PH-H15216-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 131\nand Batas Pambansa Blg. 230 for the Ministry of Health intended for new or expanded hospitals. Thereafter,\nsuch sum as may be necessary for its operation and maintenance shall be included in the annual General\nAppropriations Act."}},{"id":"PH-H15216-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 19, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15217"] = {"id":"PH-H15217","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 352  An Act Establishing a Ten-Bed Municipal Hospital in Barangay Dualing, Municipality of Aleosan, Province of North Cotabato, to Be Known as Aleosan Municipal Hospital, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 352  An Act Establishing a Ten-Bed Municipal Hospital in Barangay Dualing, Municipality of Aleosan, Province of North Cotabato, to Be Known as Aleosan Municipal Hospital, and Appropriating Funds therefor.","vi":"Đạo luật thành lập Bệnh viện 10 giường Đô thị tại Barangay Dualing, Thị trấn Aleosan, Tỉnh North Cotabato với tên gọi Bệnh viện Aleosan Đô thị","th":"พระราชบัญญัติจัดตั้งโรงพยาบาล 10 เตียงเทศบาลในบารังไกย์ Dualing เทศบาล Aleosan จังหวัด North Cotabato ในชื่อโรงพยาบาล Aleosan เทศบาล","id":"Undang-Undang membentuk Rumah Sakit 10 tempat tidur Kotamadya di Barangay Dualing, Kotamadya Aleosan, Provinsi North Cotabato dengan nama Rumah Sakit Aleosan Kotamadya","ms":"Akta menubuhkan Hospital 10 tempat tidur Perbandaran di Barangay Dualing, Perbandaran Aleosan, Wilayah North Cotabato dengan nama Hospital Aleosan Perbandaran"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 352","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00352_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00352_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15217-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed municipal hospital in Barangay Dualing, Municipality of Aleosan, Province of North\nCotabato, to be known as Aleosan Municipal Hospital."}},{"id":"PH-H15217-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 131\nand Batas Pambansa Blg. 230 for the Ministry of Health intended for new or expanded hospitals. Thereafter,\nsuch sum as may be necessary for its operation and maintenance shall be included in the annual General\nAppropriations Act."}},{"id":"PH-H15217-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 19, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15218"] = {"id":"PH-H15218","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 353  An Act Converting the Burgos Provincial High School in the Municipality of Burgos, Province of Pangasinan, Into a National High School to Be Known as Burgos National High School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 353  An Act Converting the Burgos Provincial High School in the Municipality of Burgos, Province of Pangasinan, Into a National High School to Be Known as Burgos National High School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Burgos Tỉnh tại Thị trấn Burgos, Tỉnh Pangasinan thành Trường Trung học Quốc gia với tên gọi Trường Trung học Burgos Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Burgos จังหวัดในเทศบาล Burgos จังหวัด Pangasinan เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Burgos แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Burgos Provinsi di Kotamadya Burgos, Provinsi Pangasinan menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Burgos Nasional","ms":"Akta menukar status Sekolah Menengah Burgos Wilayah di Perbandaran Burgos, Wilayah Pangasinan kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Burgos Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 353","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00353_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00353_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15218-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Burgos Provincial High School in the Municipality of Burgos, Province of Pangasinan, is\nhereby converted into a national high school, to be known as Burgos National High School."}},{"id":"PH-H15218-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school be funded out of the\nappropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the\nannual General Appropriations Act."}},{"id":"PH-H15218-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 19, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15219"] = {"id":"PH-H15219","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 354  An Act Converting the San Isidro Municipal High School in the Municipality of San Isidro, Province of Davao Oriental, Into a National High School, to Be Known as the San Isidro National High School.","orig":"Batas Pambansa Blg. 354  An Act Converting the San Isidro Municipal High School in the Municipality of San Isidro, Province of Davao Oriental, Into a National High School, to Be Known as the San Isidro National High School.","vi":"Đạo luật chuyển đổi Trường Trung học San Isidro Đô thị tại Thị trấn San Isidro, Tỉnh Davao Oriental thành Trường Trung học Quốc gia với tên gọi Trường Trung học San Isidro Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา San Isidro เทศบาลในเทศบาล San Isidro จังหวัด Davao Oriental เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา San Isidro แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah San Isidro Kotamadya di Kotamadya San Isidro, Provinsi Davao Oriental menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah San Isidro Nasional","ms":"Akta menukar status Sekolah Menengah San Isidro Perbandaran di Perbandaran San Isidro, Wilayah Davao Oriental kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah San Isidro Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 354","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00354_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00354_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15219-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The San Isidro Municipal High School in the Municipality of San Isidro, Province of Davao\nOriental, is converted into a national high school, to be known as the San Isidro National High School."}},{"id":"PH-H15219-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the\nannual General Appropriations Act."}},{"id":"PH-H15219-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 19, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15220"] = {"id":"PH-H15220","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 355  An Act Converting the Maloma Barangay High School in the Municipality of San Felipe, Province of Zambales, Into a National High School, to Be Known as the Maloma National High School, and Authorizing the Appropriation of Funds","orig":"Batas Pambansa Blg. 355  An Act Converting the Maloma Barangay High School in the Municipality of San Felipe, Province of Zambales, Into a National High School, to Be Known as the Maloma National High School, and Authorizing the Appropriation of Funds","vi":"Đạo luật chuyển đổi Trường Trung học Maloma Barangay tại Thị trấn San Felipe, Tỉnh Zambales thành Trường Trung học Quốc gia với tên gọi Trường Trung học Maloma Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Maloma Barangay ในเทศบาล San Felipe จังหวัด Zambales เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Maloma แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Maloma Barangay di Kotamadya San Felipe, Provinsi Zambales menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Maloma Nasional","ms":"Akta menukar status Sekolah Menengah Maloma Barangay di Perbandaran San Felipe, Wilayah Zambales kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Maloma Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 355","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00355_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00355_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15220-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Maloma Barangay High School in the Municipality of San Felipe, Province of Zambales, is\nhereby converted into a national high school, to be known as the Maloma National High School."}},{"id":"PH-H15220-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the\nsucceeding General Appropriations Acts."}},{"id":"PH-H15220-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 19, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15221"] = {"id":"PH-H15221","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 356  An Act Converting the Municipal High School in Claver, Surigao Del Norte, Into a National High School, to Be Known as the Claver National High School.","orig":"Batas Pambansa Blg. 356  An Act Converting the Municipal High School in Claver, Surigao Del Norte, Into a National High School, to Be Known as the Claver National High School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 356","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00356_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00356_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15221-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The municipal high school in Claver, Surigao del Norte, is hereby converted into a national high\nschool, to be known as the Claver National High School."}},{"id":"PH-H15221-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, the amount needed for its operation and maintenance shall be included in the annual\nGeneral Appropriations Act."}},{"id":"PH-H15221-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 21, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15222"] = {"id":"PH-H15222","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 357  An Act Converting the Placer High School in the Municipality of Placer, Province of Surigao Del Norte, Into a National High School, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 357  An Act Converting the Placer High School in the Municipality of Placer, Province of Surigao Del Norte, Into a National High School, and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Placer tại Thị trấn Placer, Tỉnh Surigao Del Norte thành Trường Trung học Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Placer ในเทศบาล Placer จังหวัด Surigao Del Norte เป็น โรงเรียนมัธยมศึกษาแห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Placer di Kotamadya Placer, Provinsi Surigao Del Norte menjadi Sekolah Menengah Nasional","ms":"Akta menukar status Sekolah Menengah Placer di Perbandaran Placer, Wilayah Surigao Del Norte kepada Sekolah Menengah Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 357","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00357_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00357_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15222-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Placer High School in the Municipality of Placer, Province of Surigao del Norte, is\nconverted into a national high school, to be known as Placer National High School."}},{"id":"PH-H15222-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education, Culture and Sports is hereby directed to take such steps as are\nnecessary for the conversion and operation of the school and immediate implementation of this Act."}},{"id":"PH-H15222-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the\nannual General Appropriations Act.\nApproved: March 21, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15223"] = {"id":"PH-H15223","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 358  An Act Converting the Mainit National Agricultural High School in the Municipality of Mainit, Province of Surigao Del Norte, Into a College of Agriculture and Technology to Be Known as the Surigao Del Norte College of Agriculture and Technology and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 358  An Act Converting the Mainit National Agricultural High School in the Municipality of Mainit, Province of Surigao Del Norte, Into a College of Agriculture and Technology to Be Known as the Surigao Del Norte College of Agriculture and Technology and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Nông nghiệp Mainit Quốc gia tại Thị trấn Mainit, Tỉnh Surigao Del Norte thành Cao đẳng Nông nghiệp Công nghệ với tên gọi Cao đẳng Nông nghiệp Công nghệ Surigao Del Norte","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษาเกษตรกรรม Mainit แห่งชาติในเทศบาล Mainit จังหวัด Surigao Del Norte เป็น วิทยาลัยเกษตรศาสตร์เทคโนโลยีในชื่อวิทยาลัยเกษตรศาสตร์เทคโนโลยี Surigao Del Norte","id":"Undang-Undang mengubah Sekolah Menengah Pertanian Mainit Nasional di Kotamadya Mainit, Provinsi Surigao Del Norte menjadi Sekolah Tinggi Pertanian Teknologi dengan nama Sekolah Tinggi Pertanian Teknologi Surigao Del Norte","ms":"Akta menukar status Sekolah Menengah Pertanian Mainit Kebangsaan di Perbandaran Mainit, Wilayah Surigao Del Norte kepada Kolej Pertanian Teknologi dengan nama Kolej Pertanian Teknologi Surigao Del Norte"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 358","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-21","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00358_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00358_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15223-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Mainit National Agricultural High School in the Municipality of Mainit, Province of\nSurigao del Norte, is converted into a college of agriculture and technology to be known as the Surigao del\nNorte College of Agriculture and Technology."}},{"id":"PH-H15223-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The College shall primarily provide professional and advanced vocational instructions and\ntraining in agriculture, fisheries, forestry, and industrial technologies. It shall also promote research, advanced\nstudies, and progressive leadership in its field of specialization."}},{"id":"PH-H15223-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The College shall maintain in addition to a secondary education program, undergraduate and\ngraduate courses in the fields of agriculture, fisheries, forestry, and industrial technologies. It shall also offer\nshort-term vocational and technological courses."}},{"id":"PH-H15223-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The College shall be headed by a college superintendent who shall be responsible for its\nadministration and supervision."}},{"id":"PH-H15223-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"All personnel, assets, liabilities, records and appropriations of the Mainit National Agricultural\nHigh School are transferred to/absorbed by the Surigao del Norte College of Agriculture and Technology."}},{"id":"PH-H15223-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The existing appropriations for the Mainit National Agricultural High School are hereby\ntransferred to the Surigao del Norte College of Agriculture and Technology, to be disbursed in accordance\nwith the provisions of this Act. Thereafter, the necessary amount required for the operation and maintenance\nof the College shall be provided for in subsequent General Appropriations Acts, until which time the operation\nof the institution as a college shall be deferred, provided that its new name shall take effect upon approval of"}},{"id":"PH-H15223-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 21, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15224"] = {"id":"PH-H15224","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 359  An Act Converting the Sagay Municipal High School in the Municipality of Sagay, Province of Negros Occidental Into a Branch of the Iloilo state College of Fisheries, to Be Known as the Iloilo state College of Fisheries, Sagay Branch, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 359  An Act Converting the Sagay Municipal High School in the Municipality of Sagay, Province of Negros Occidental Into a Branch of the Iloilo state College of Fisheries, to Be Known as the Iloilo state College of Fisheries, Sagay Branch, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Sagay Đô thị tại Thị trấn Sagay, Tỉnh Negros Occidental thành Khoa Thủy sản Branch of the Iloilo Bang với tên gọi Cao đẳng Bang Iloilo Fisheries, Sagay Branch","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Sagay เทศบาลในเทศบาล Sagay จังหวัด Negros Occidental เป็น คณะประมง Branch of the Iloilo ของรัฐในชื่อวิทยาลัยของรัฐ Iloilo Fisheries, Sagay Branch","id":"Undang-Undang mengubah Sekolah Menengah Sagay Kotamadya di Kotamadya Sagay, Provinsi Negros Occidental menjadi Fakultas Perikanan Branch of the Iloilo Negeri dengan nama Sekolah Tinggi Negeri Iloilo Fisheries, Sagay Branch","ms":"Akta menukar status Sekolah Menengah Sagay Perbandaran di Perbandaran Sagay, Wilayah Negros Occidental kepada Fakulti Perikanan Branch of the Iloilo Negeri dengan nama Kolej Negeri Iloilo Fisheries, Sagay Branch"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 359","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-31","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00359_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00359_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15224-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Sagay Municipal High School in the Municipality of Sagay, Province of Negros Occidental,\nis hereby converted into a branch of the Iloilo State College of Fisheries, to be known as the Iloilo State\nCollege of Fisheries, Sagay Branch. The college shall primarily provide technological and vocational\ninstruction and training in fisheries science, as well as short term technical or vocational courses in fisheries to\nmeet the manpower needs of the region."}},{"id":"PH-H15224-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Minister of Education, Culture and Sports is hereby empowered to reorganize said school\naccordingly."}},{"id":"PH-H15224-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national schools: Provided, That the local government unit\nconcerned shall continue to provide funding for its share in the maintenance and operation of the school.\nThereafter, such sum as may be necessary for its operation and maintenance shall be included in the annual\nGeneral Appropriations Act."}},{"id":"PH-H15224-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 31, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15225"] = {"id":"PH-H15225","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 360  An Act Converting the Jalaud Barangay High School in the Municipality of Barotac Nuevo, Province of Iloilo, Into a National School, to Be Known as the Don Jose Susteguer Monfort Memorial National School.","orig":"Batas Pambansa Blg. 360  An Act Converting the Jalaud Barangay High School in the Municipality of Barotac Nuevo, Province of Iloilo, Into a National School, to Be Known as the Don Jose Susteguer Monfort Memorial National School.","vi":"Đạo luật chuyển đổi Trường Trung học Jalaud Barangay tại Thị trấn Barotac Nuevo, Tỉnh Iloilo thành Trường Quốc gia với tên gọi Trường Tưởng niệm Don Jose Susteguer Monfort Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Jalaud Barangay ในเทศบาล Barotac Nuevo จังหวัด Iloilo เป็น โรงเรียนแห่งชาติในชื่อโรงเรียนอนุสรณ์ Don Jose Susteguer Monfort แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Jalaud Barangay di Kotamadya Barotac Nuevo, Provinsi Iloilo menjadi Sekolah Nasional dengan nama Sekolah Memorial Don Jose Susteguer Monfort Nasional","ms":"Akta menukar status Sekolah Menengah Jalaud Barangay di Perbandaran Barotac Nuevo, Wilayah Iloilo kepada Sekolah Kebangsaan dengan nama Sekolah Memorial Don Jose Susteguer Monfort Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 360","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-31","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00360_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00360_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15225-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Jalaud Barangay High School in the Municipality of Barotac Nuevo, Province of Iloilo, is\nhereby converted into a national school, to be known as the Don Jose Susteguer Monfort Memorial National"}},{"id":"PH-H15225-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education, Culture and Sports shall take the necessary steps for the immediate\nimplementation of this Act."}},{"id":"PH-H15225-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the\nannual General Appropriations Act.\nApproved: March 31, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15226"] = {"id":"PH-H15226","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 361  An Act Providing for the Establishment of a School of Fisheries in the Municipality of Casiguran, Province of Aurora, to Be Known as the Aurora National Fishery School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 361  An Act Providing for the Establishment of a School of Fisheries in the Municipality of Casiguran, Province of Aurora, to Be Known as the Aurora National Fishery School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật thành lập Trường Thủy sản tại Thị trấn Casiguran, Tỉnh Aurora với tên gọi Trường Aurora National Fishery","th":"พระราชบัญญัติจัดตั้งโรงเรียนประมงในเทศบาล Casiguran จังหวัด Aurora ในชื่อโรงเรียน Aurora National Fishery","id":"Undang-Undang membentuk Sekolah Perikanan di Kotamadya Casiguran, Provinsi Aurora dengan nama Sekolah Aurora National Fishery","ms":"Akta menubuhkan Sekolah Perikanan di Perbandaran Casiguran, Wilayah Aurora dengan nama Sekolah Aurora National Fishery"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 361","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-03-31","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00361_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00361_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15226-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Bureau of Secondary Education, a\nschool of fisheries in the Municipality of Casiguran, Province of Aurora, to be known as the Aurora National\nFishery School."}},{"id":"PH-H15226-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred fifty thousand pesos for the operation of the school shall be funded\nout of the appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for new\nnational high schools: Provided, That the local government unit concerned shall continue to provide funding\nfor its share in the cost of maintenance and operation of the school. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15226-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 31, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15227"] = {"id":"PH-H15227","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 362  An Act Converting the VIctorias High School in the Municipality of VIctorias, Province of Negros Occidental, Into a National High School to Be Known as the VIctorias National High School.","orig":"Batas Pambansa Blg. 362  An Act Converting the VIctorias High School in the Municipality of VIctorias, Province of Negros Occidental, Into a National High School to Be Known as the VIctorias National High School.","vi":"Đạo luật chuyển đổi Trường Trung học VIctorias tại Thị trấn VIctorias, Tỉnh Negros Occidental thành Trường Trung học Quốc gia với tên gọi Trường Trung học VIctorias Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา VIctorias ในเทศบาล VIctorias จังหวัด Negros Occidental เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา VIctorias แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah VIctorias di Kotamadya VIctorias, Provinsi Negros Occidental menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah VIctorias Nasional","ms":"Akta menukar status Sekolah Menengah VIctorias di Perbandaran VIctorias, Wilayah Negros Occidental kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah VIctorias Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 362","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-07","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00362_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00362_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15227-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Victorias High School in the Municipality of Victorias, Province of Negros Occidental, is\nhereby converted into a national high school to be known as the Victorias National High School. The\ncurriculum of said school shall include both academic and vocational courses."}},{"id":"PH-H15227-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Minister of Education, Culture and Sports shall implement the provisions of this Act so as to\nmake the said Victorias National High School in operation during the first school term following the approval"}},{"id":"PH-H15227-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide for its share in the cost of maintenance and operation of the school.\nThereafter, such sum as may be necessary for its operation and maintenance shall be included in the annual\nGeneral Appropriations Act."}},{"id":"PH-H15227-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 7, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15228"] = {"id":"PH-H15228","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 363  An Act Converting the Basilan National Agro-Industrial School in the Municipality of Lamitan, Province of Basilan, Into An Agro-Industrial College to Be Known as the Basilan National Agro-Industrial College.","orig":"Batas Pambansa Blg. 363  An Act Converting the Basilan National Agro-Industrial School in the Municipality of Lamitan, Province of Basilan, Into An Agro-Industrial College to Be Known as the Basilan National Agro-Industrial College.","vi":"Đạo luật chuyển đổi Trường Nông-công nghiệp Basilan Quốc gia tại Thị trấn Lamitan, Tỉnh Basilan thành Cao đẳng Nông-công nghiệp với tên gọi Cao đẳng Nông-công nghiệp Basilan Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนเกษตรอุตสาหกรรม Basilan แห่งชาติในเทศบาล Lamitan จังหวัด Basilan เป็น วิทยาลัยเกษตรอุตสาหกรรมในชื่อวิทยาลัยเกษตรอุตสาหกรรม Basilan แห่งชาติ","id":"Undang-Undang mengubah Sekolah Agro-Industri Basilan Nasional di Kotamadya Lamitan, Provinsi Basilan menjadi Sekolah Tinggi Agro-Industri dengan nama Sekolah Tinggi Agro-Industri Basilan Nasional","ms":"Akta menukar status Sekolah Agro-Industri Basilan Kebangsaan di Perbandaran Lamitan, Wilayah Basilan kepada Kolej Agro-Industri dengan nama Kolej Agro-Industri Basilan Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 363","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-07","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00363_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00363_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15228-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Basilan National Agro-Industrial School in the Municipality of Lamitan, Province of\nBasilan, is converted into a college to be known as the Basilan National Agro-Industrial College."}},{"id":"PH-H15228-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"In addition to its present secondary and vocational curricular offerings, the college shall offer\nsuch collegiate courses as may be authorized by the Ministry of Education, Culture and Sports."}},{"id":"PH-H15228-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Ministry of Education, Culture and Sports is directed to take the necessary steps for the\nimmediate implementation of this Act."}},{"id":"PH-H15228-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The existing appropriations for Basilan National Agro-Industrial School are hereby transferred to\nthe Basilan National Agro-Industrial College, to be disbursed in accordance with the provisions of this Act.\nThereafter, the necessary amount required for the operation and maintenance of the College shall be provided\nfor in subsequent General Appropriations Acts, until which time the operation of the institution as a college\nshall be deferred, provided that its new name shall take effect upon approval of this Act."}},{"id":"PH-H15228-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 7, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15229"] = {"id":"PH-H15229","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 364  An Act Converting Pangutaran Barangay High School in the Municipality of Pangutaran, Province of Sulu, Into a National High School, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 364  An Act Converting Pangutaran Barangay High School in the Municipality of Pangutaran, Province of Sulu, Into a National High School, and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Pangutaran Barangay tại Thị trấn Pangutaran, Tỉnh Sulu thành Trường Trung học Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Pangutaran Barangay ในเทศบาล Pangutaran จังหวัด Sulu เป็น โรงเรียนมัธยมศึกษาแห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Pangutaran Barangay di Kotamadya Pangutaran, Provinsi Sulu menjadi Sekolah Menengah Nasional","ms":"Akta menukar status Sekolah Menengah Pangutaran Barangay di Perbandaran Pangutaran, Wilayah Sulu kepada Sekolah Menengah Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 364","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-07","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00364_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00364_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15229-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Pangutaran Barangay High School in the Municipality of Pangutaran, Province of Sulu, is\nhereby converted into a national high school to be known as the Pangutaran National High School."}},{"id":"PH-H15229-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education, Culture and Sports is hereby directed to take such steps as are\nnecessary for the conversion and operation of the school and immediate implementation of this Act."}},{"id":"PH-H15229-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the\nannual General Appropriations Act."}},{"id":"PH-H15229-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 7, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15230"] = {"id":"PH-H15230","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 365  An Act Changing the Name of the Municipality of Linamon in the Province of Lanao Del Norte to Tomas Cabili.","orig":"Batas Pambansa Blg. 365  An Act Changing the Name of the Municipality of Linamon in the Province of Lanao Del Norte to Tomas Cabili."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 365","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00365_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00365_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15230-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Municipality of Linamon in the Province of Lanao del Norte is changed to\nTomas Cabili."}},{"id":"PH-H15230-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 7, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15231"] = {"id":"PH-H15231","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 366  An Act Establishing a Ten-Bed Capacity Municipal Hospital in the Municipality of Bokod, Province of Benguet, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 366  An Act Establishing a Ten-Bed Capacity Municipal Hospital in the Municipality of Bokod, Province of Benguet, and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 366","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-07","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00366_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00366_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15231-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister (Ministry of\nHealth), a municipal hospital in the barrio of Daclan, Municipality of Bokod, Province of Benguet, to be\nknown as the Dennis Molintas Municipal Hospital."}},{"id":"PH-H15231-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Minister of Health shall determine the manner by which said hospital shall be operational."}},{"id":"PH-H15231-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 131\nand Batas Pambansa Blg. 230 for the Ministry of Health intended for new or expanded hospitals. Thereafter,\nsuch sum as may be necessary for its operation and maintenance shall be included in the annual General\nAppropriation Act."}},{"id":"PH-H15231-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 7, 1983"}}],"pack":"ph-p156"};
