  FT["PH-H15239"] = {"id":"PH-H15239","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 374  An Act Converting the Bintawan Barangay High School in the Municipality of VIllaverde, Province of Nueva VIzcaya, Into a National High School.","orig":"Batas Pambansa Blg. 374  An Act Converting the Bintawan Barangay High School in the Municipality of VIllaverde, Province of Nueva VIzcaya, Into a National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Bintawan Barangay tại Thị trấn VIllaverde, Tỉnh Nueva VIzcaya thành Trường Trung học Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Bintawan Barangay ในเทศบาล VIllaverde จังหวัด Nueva VIzcaya เป็น โรงเรียนมัธยมศึกษาแห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Bintawan Barangay di Kotamadya VIllaverde, Provinsi Nueva VIzcaya menjadi Sekolah Menengah Nasional","ms":"Akta menukar status Sekolah Menengah Bintawan Barangay di Perbandaran VIllaverde, Wilayah Nueva VIzcaya kepada Sekolah Menengah Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 374","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-07","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00374_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00374_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15239-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Bintawan Barangay High School in the Municipality of Villaverde, Province of Nueva\nVizcaya, is hereby converted into a national high school, to be known as the Bintawan National High School."}},{"id":"PH-H15239-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools; Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the\nannual General Appropriations Act."}},{"id":"PH-H15239-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 7, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15240"] = {"id":"PH-H15240","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 375  An Act Converting the Lamo Barangay High School in the Municipality of Dupax Del Norte, Province of Nueva VIzcaya, Into a National High School.","orig":"Batas Pambansa Blg. 375  An Act Converting the Lamo Barangay High School in the Municipality of Dupax Del Norte, Province of Nueva VIzcaya, Into a National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Lamo Barangay tại Thị trấn Dupax Del Norte, Tỉnh Nueva VIzcaya thành Trường Trung học Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Lamo Barangay ในเทศบาล Dupax Del Norte จังหวัด Nueva VIzcaya เป็น โรงเรียนมัธยมศึกษาแห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Lamo Barangay di Kotamadya Dupax Del Norte, Provinsi Nueva VIzcaya menjadi Sekolah Menengah Nasional","ms":"Akta menukar status Sekolah Menengah Lamo Barangay di Perbandaran Dupax Del Norte, Wilayah Nueva VIzcaya kepada Sekolah Menengah Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 375","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-07","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00375_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00375_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15240-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Lamo Barangay High School in the Municipality of Dupax del Norte, Province of Nueva\nVizcaya, is hereby converted into a national high school, to be known as the Lamo National High School."}},{"id":"PH-H15240-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the\nannual General Appropriations Act."}},{"id":"PH-H15240-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 7, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15241"] = {"id":"PH-H15241","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 376  An Act Converting Certain Provincial Roads in the Province of Iloilo Into National Roads.","orig":"Batas Pambansa Blg. 376  An Act Converting Certain Provincial Roads in the Province of Iloilo Into National Roads."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 376","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-07","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00376_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00376_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15241-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The following provincial roads in the province of Iloilo are converted into and declared as\nnational roads:\na) Concepcion-San Dionisio Road\nb) Ajuy-Fuente Bunglas-Jamulawon Road\nc) Passi-San Enrique-Garita Road"}},{"id":"PH-H15241-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Any provision of law, decree, order, rule or regulation inconsistent with this Act is repealed or\nmodified accordingly."}},{"id":"PH-H15241-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 7, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15242"] = {"id":"PH-H15242","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":18,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 377  An Act Converting the Marinduque School of Arts and Trades Into the Marinduque Institute of Science and Technology, Broadening for the Purpose Its Curricular Programs in Science and Technology.","orig":"Batas Pambansa Blg. 377  An Act Converting the Marinduque School of Arts and Trades Into the Marinduque Institute of Science and Technology, Broadening for the Purpose Its Curricular Programs in Science and Technology.","vi":"Đạo luật chuyển đổi Trường Nghệ thuật và Thương mại Marinduque thành Học viện Marinduque Science and Technology, Broadening","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนศิลปะและหัตถกรรม Marinduque เป็น สถาบัน Marinduque Science and Technology, Broadening","id":"Undang-Undang mengubah Sekolah Seni dan Keterampilan Marinduque menjadi Institut Marinduque Science and Technology, Broadening","ms":"Akta menukar status Sekolah Seni dan Pertukangan Marinduque kepada Institut Marinduque Science and Technology, Broadening"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 377","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-08","completenessNote":"全文，共 18 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00377_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00377_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15242-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The present Marinduque School of Arts and Trades, located in the Barangay of Tanza,\nMunicipality of Boac, Province of Marinduque, is hereby converted into the Marinduque Institute of Science\nand Technology, hereinafter referred to in this Act as the Institute."}},{"id":"PH-H15242-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Institute shall primarily provide higher vocational, professional, and technical instruction\nand training in science, agriculture and industrial fields. It shall also promote research, advanced studies and\nprogressive leadership in the fields of agricultural, mining, fishery and industrial education."}},{"id":"PH-H15242-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"In addition to the four-year secondary trade, the two-year trade technical curriculum, the\nfour-year Bachelor of Science in Industrial Education, the Institute may offer degree courses in agricultural\nand fishery education, mining and allied technological courses leading to degrees in engineering."}},{"id":"PH-H15242-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"No student shall be denied admission to the Institute by reason of sex, ethnic consideration,\nreligious belief, or political affiliation."}},{"id":"PH-H15242-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The head of the Institute shall be known as the President of the Marinduque Institute of Science\nand Technology. He shall be appointed by the President of the Philippines.\nThe powers and duties of the President of the Institute, in addition to those specifically provided for in this\nAct, shall be those usually pertaining to the office of the president of a college."}},{"id":"PH-H15242-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The governing body of the Institute shall be the Board of Trustees of the Marinduque Institute of\nScience and Technology. It shall be composed of the Ministry of Education, Culture and Sports, who shall be\nthe chairman, and the Regional Director of the Ministry of Education, Culture and Sports, the Regional\nDevelopment Council Director, the President of the Institute, the incumbent governor of the Province of\nMarinduque, the incumbent mayor of Boac, the president of the alumni association of the Institute, and four\nprominent residents of Marinduque who are holders of degrees relevant to the courses offered in the Institute,\nas members, who shall be appointed by the President of the Philippines.\nOf the first group appointed, the President of the Philippines shall designate one to serve for one year; one to\nserve for two years; one to serve for three years; and one to serve for four years. Thereafter, persons appointed\nto succeed such members shall hold office for a term of four years and until their successors shall have been\nappointed and qualified. In case of permanent vacancy, the position shall be filled by appointment by the\nPresident of the Philippines. Such appointee shall hold office for the unexpired term only.\nWhen the Minister of Education, Culture and Sports is unable to perform his duties as chairman of the Board\ndue to illness, absence or other cause, or in case of vacancy in the office, the Deputy Minister of Education,\nCulture and Sports shall temporarily perform the functions of the chairman of the said Board.\nWhen both the Minister and the Deputy Minister of Education, Culture and Sports are unable to exercise the\npowers of the Chairman of the Board of Trustees, the members of the Board shall elect from among\nthemselves a temporary chairman who shall act as chairman thereof."}},{"id":"PH-H15242-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"The members of the Board of Trustees shall serve without compensation but they shall be\nreimbursed for actual and necessary expenses incurred either in attendance upon meetings of the Board or\n\nupon other official business authorized by a resolution thereof, subject to existing budget laws on honoraria\nand allowances."}},{"id":"PH-H15242-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"In addition to its general powers of administration, the Board of Trustees shall have the\nfollowing powers and duties:\n(a) To receive and appropriate for the purpose specified by law such sums as may be provided for the support\nof the Institute;\n(b) To confer degrees upon successful candidates for graduation of the Institute. It may also confer honorary\ndegrees upon persons in recognition of learning, statesmanship, or eminence in agriculture, forestry, industry\nor public service related to such fields;\n(c) Subject to Civil Service law, rules and regulations, to appoint, upon recommendation of the President of\nthe Institute, the deans of the different schools of the Institute, the registrar, the heads of departments,\nprofessors, instructors, lectures, and other employees of the Institute; to fix, in accordance with the Office of\nCompensation and Position Classification rates, their compensation; to prescribe hours of service, duties and\nconditions of work as it may deem proper; to grant to them in its discretion, leaves of absence under such\nregulations as it may promulgate, any provision of law to the contrary notwithstanding, and to remove them\nfor cause after an investigation and hearing pursuant to Civil Service law governing disciplinary action;\n(d) To approve the curricula and rules of discipline drawn up by the Institute Council as hereinafter provided;\n(e) To provide fellowships and scholarships for deserving faculty and personnel in any of the institutions here\nand abroad; and further provide scholarship to honor students and also to poor but deserving students;\n(f) To prescribe rules and regulations for its own government and for this purpose to enact such regulations\nnot contrary to law, as may be necessary;\n(g) To receive in trust legacies, gifts and donations of real and personal property of all kinds, and to administer\nthe same for the benefit of the Institute or of a department thereof, or for aid to any student in accordance with\nthe directions and instructions of the donor, and in default thereof, in such manner as the Board of Trustees\nmay in its discretion determine;\n(h) To provide vocational training to adult citizens and out-of-school youth with the cooperation of other\ngovernment and private agencies."}},{"id":"PH-H15242-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all the members holding office\nat the time the meeting of the Board is called. All processes against the Board of Trustees shall be served on\nthe President or Secretary thereof."}},{"id":"PH-H15242-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"On or before the fifteenth day of the second month after the opening of regular classes each\nyear, the Board of Trustees shall submit to the President of the Philippines a detailed report, setting forth the\nprogress, condition and needs of the Institute."}},{"id":"PH-H15242-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"There shall be an Institute Council consisting of the President of the Institute and all members\nof the faculty of the Institute. The Council shall have the power to prescribe the curricula and rules of\ndiscipline, subject to the approval of the Board of Trustees. It shall fix the requirements for admission to the\nInstitute, as well as for graduation and conferring of degrees, subject to review by the Board of Trustees. The\nCouncil alone shall have the power to recommend students or others to be recipients of degrees. Through the\nPresident of the Institute or a duly authorized committee, the Council shall have disciplinary power over the\nstudents within the limits prescribed by the rules of discipline."}},{"id":"PH-H15242-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"The body of instructors and professors of the Institute shall constitute the faculty of the\nInstitute, with the President of the Institute as the presiding officer.\nNo member of the faculty of the Institute shall attempt directly or indirectly, under penalty of dismissal by the\nBoard of Trustees, to influence students or any person in the Institute towards any ideology, political or\n\notherwise, which preaches the overthrow of the government through violence or subversion."}},{"id":"PH-H15242-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"There shall be a secretary of the Institute who shall be appointed by the Board of Trustees upon\nrecommendation of the President of the Institute. He shall be the secretary of the Board and also of the\nInstitute, and shall keep such records of the Institute as may be determined by the Board of Trustees."}},{"id":"PH-H15242-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"The Treasurer of the Philippines shall be ex officio treasurer of the Institute. All accounts and\nexpenses therefor shall be audited by the Commission on Audit and all disbursements shall be made in\naccordance with existing auditing rules and regulations."}},{"id":"PH-H15242-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"Heads of the bureaus and offices of the national government are hereby authorized to loan, or\ntransfer, upon request of the President of the Institute, such apparatus, equipment or supplies as may be\nneeded by the Institute and to detail employees for the duty therein, when in the judgment of the head of the\nbureau or office, such apparatus, equipment, supplies or the services of such employees can be spared without\nserious detriment to the public service. Employees so detailed shall perform such duties as are required under\nsuch detail, and the time so employed shall be counted as part of their regular official service."}},{"id":"PH-H15242-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"All parcels of land, buildings, equipment and facilities owned by the Marinduque School of\nArts and Trades as well as obligations and appropriations thereof, shall be transferred to the Marinduque\nInstitute of Science and Technology."}},{"id":"PH-H15242-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"The existing appropriations for the Marinduque School of Arts and Trades are hereby\ntransferred to the Marinduque Institute of Science and Technology, to be disbursed in accordance with the\nprovisions of this Act. Thereafter, the maintenance of the state college shall be provided for in subsequent\nGeneral Appropriations Acts, until which time the operation of the institution as an institute shall be deferred:\nProvided, That its new name shall take effect upon approval of this Act."}},{"id":"PH-H15242-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 8, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15243"] = {"id":"PH-H15243","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 378  An Act Converting the Udiawan Barangay High School in the Municipality of Solano, Province of Nueva VIzcaya, Into a National High School.","orig":"Batas Pambansa Blg. 378  An Act Converting the Udiawan Barangay High School in the Municipality of Solano, Province of Nueva VIzcaya, Into a National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Udiawan Barangay tại Thị trấn Solano, Tỉnh Nueva VIzcaya thành Trường Trung học Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Udiawan Barangay ในเทศบาล Solano จังหวัด Nueva VIzcaya เป็น โรงเรียนมัธยมศึกษาแห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Udiawan Barangay di Kotamadya Solano, Provinsi Nueva VIzcaya menjadi Sekolah Menengah Nasional","ms":"Akta menukar status Sekolah Menengah Udiawan Barangay di Perbandaran Solano, Wilayah Nueva VIzcaya kepada Sekolah Menengah Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 378","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-08","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00378_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00378_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15243-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Udiawan Barangay High School in the Municipality of Solano, Province of Nueva Vizcaya,\nis hereby converted into a national high school, to be known as the Udiawan National High School."}},{"id":"PH-H15243-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the\nannual General Appropriations Act."}},{"id":"PH-H15243-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 8, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15244"] = {"id":"PH-H15244","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 379  An Act Converting the Manuel A. Roxas Memorial School of Fisheries in the Municipality of Daanbantayan, Province of Cebu, Into a College to Be Known as the Central VIsayas College of Fisheries and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 379  An Act Converting the Manuel A. Roxas Memorial School of Fisheries in the Municipality of Daanbantayan, Province of Cebu, Into a College to Be Known as the Central VIsayas College of Fisheries and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 379","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-08","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00379_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00379_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15244-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Manuel A. Roxas Memorial School of Fisheries in the Municipality of Daanbantayan,\nProvince of Cebu, is converted into a college of fisheries, to be known as the Central Visayas College of"}},{"id":"PH-H15244-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The college shall offer secondary, collegiate, and special courses and shall be headed by a\nsuperintendent."}},{"id":"PH-H15244-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The physical and financial assets, liabilities, personnel, equipment, and records of the Manuel A.\nRoxas Memorial School of Fisheries are hereby transferred to the Central Visayas College of Fisheries."}},{"id":"PH-H15244-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The existing appropriations for the Manuel A. Roxas Memorial School of Fisheries are hereby\ntransferred to the Central Visayas College of Fisheries, to be disbursed in accordance with the provisions of\nthis Act. Thereafter, the necessary amount required for the operation and maintenance of the college shall be\nprovided for in subsequent General Appropriations Acts, until which time the operation of the institution as a\ncollege shall be deferred, provided that its new name shall take effect upon approval of this Act."}},{"id":"PH-H15244-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 8, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15245"] = {"id":"PH-H15245","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 380  An Act Converting the San Jacinto High School in the Municipality of San Jacinto, Province of Masbate, Into a National High School, to Be Known as the San Jacinto National High School and Providing Funds therefor.","orig":"Batas Pambansa Blg. 380  An Act Converting the San Jacinto High School in the Municipality of San Jacinto, Province of Masbate, Into a National High School, to Be Known as the San Jacinto National High School and Providing Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học San Jacinto tại Thị trấn San Jacinto, Tỉnh Masbate thành Trường Trung học Quốc gia với tên gọi Trường Trung học San Jacinto Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา San Jacinto ในเทศบาล San Jacinto จังหวัด Masbate เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา San Jacinto แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah San Jacinto di Kotamadya San Jacinto, Provinsi Masbate menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah San Jacinto Nasional","ms":"Akta menukar status Sekolah Menengah San Jacinto di Perbandaran San Jacinto, Wilayah Masbate kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah San Jacinto Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 380","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-08","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00380_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00380_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15245-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The San Jacinto High School in the Municipality of San Jacinto, Province of Masbate, is\nconverted into a national high school, to be known as the San Jacinto National High School."}},{"id":"PH-H15245-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The high school curriculum which includes academic, industrial arts, ceramics, electricity,\nhandicraft and other allied courses shall be offered."}},{"id":"PH-H15245-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Minister of Education, Culture and Sports shall reorganize the said school accordingly."}},{"id":"PH-H15245-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Upon the organization of the new school, the assets, liabilities, personnel, equipment, and\nrecords of the old school shall be transferred to the new school."}},{"id":"PH-H15245-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national schools: Provided, That the local government unit\nconcerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the\nannual General Appropriations Act."}},{"id":"PH-H15245-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 8, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15246"] = {"id":"PH-H15246","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 381  An Act Changing the Name of the Municipality of Ponot in Zamboanga Del Norte to Jose Dalman.","orig":"Batas Pambansa Blg. 381  An Act Changing the Name of the Municipality of Ponot in Zamboanga Del Norte to Jose Dalman."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 381","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00381_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00381_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15246-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Municipality of Ponot in the Province of Zamboanga del Norte is hereby\nchanged to Jose Dalman."}},{"id":"PH-H15246-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 8, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15247"] = {"id":"PH-H15247","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 382  An Act Converting the Bitoon Barangay High School in the Municipality of Dumanjug, Province of Cebu, Into a National Vocational High School to Be Known as the Bitoon National Vocational High School.","orig":"Batas Pambansa Blg. 382  An Act Converting the Bitoon Barangay High School in the Municipality of Dumanjug, Province of Cebu, Into a National Vocational High School to Be Known as the Bitoon National Vocational High School.","vi":"Đạo luật chuyển đổi Trường Trung học Bitoon Barangay tại Thị trấn Dumanjug, Tỉnh Cebu thành Trường Trung học Dạy nghề Quốc gia với tên gọi Trường Trung học Dạy nghề Bitoon Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Bitoon Barangay ในเทศบาล Dumanjug จังหวัด Cebu เป็น โรงเรียนมัธยมศึกษาอาชีวศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษาอาชีวศึกษา Bitoon แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Bitoon Barangay di Kotamadya Dumanjug, Provinsi Cebu menjadi Sekolah Menengah Kejuruan Nasional dengan nama Sekolah Menengah Kejuruan Bitoon Nasional","ms":"Akta menukar status Sekolah Menengah Bitoon Barangay di Perbandaran Dumanjug, Wilayah Cebu kepada Sekolah Menengah Vokasional Kebangsaan dengan nama Sekolah Menengah Vokasional Bitoon Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 382","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-08","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00382_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00382_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15247-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Bitoon Barangay High School in the Municipality of Dumanjug, Province of Cebu, is\nconverted into a national vocational high school to be known as the Bitoon National Vocational High School."}},{"id":"PH-H15247-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the\nannual General Appropriations Act."}},{"id":"PH-H15247-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 8, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15248"] = {"id":"PH-H15248","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 383  An Act Naming the Highway Connecting the Municipalities of San Remigio and Tabuelan in the Province of Cebu as Antonio Y. De Pio Highway.","orig":"Batas Pambansa Blg. 383  An Act Naming the Highway Connecting the Municipalities of San Remigio and Tabuelan in the Province of Cebu as Antonio Y. De Pio Highway."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 383","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00383_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00383_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15248-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The highway connecting the Municipalities of San Remigio and Tabuelan in the Province of\nCebu shall be known as Antonio Y. de Pio Highway."}},{"id":"PH-H15248-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 8, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15249"] = {"id":"PH-H15249","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":17,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 384  An Act Converting the Sulu National Regional Agricultural School in the Municipality of Bongao, Province of Tawi-Tawi, Into a College to Be Known as the Tawi-Tawi Regional Agricultural College, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 384  An Act Converting the Sulu National Regional Agricultural School in the Municipality of Bongao, Province of Tawi-Tawi, Into a College to Be Known as the Tawi-Tawi Regional Agricultural College, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Nông nghiệp Sulu Quốc gia Vùng tại Thị trấn Bongao, Tỉnh Tawi-Tawi thành Cao đẳng với tên gọi Cao đẳng Nông nghiệp Tawi-Tawi Vùng","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนเกษตรกรรม Sulu แห่งชาติภูมิภาคในเทศบาล Bongao จังหวัด Tawi-Tawi เป็น วิทยาลัยในชื่อวิทยาลัยเกษตรกรรม Tawi-Tawi ภูมิภาค","id":"Undang-Undang mengubah Sekolah Pertanian Sulu Nasional Regional di Kotamadya Bongao, Provinsi Tawi-Tawi menjadi Sekolah Tinggi dengan nama Sekolah Tinggi Pertanian Tawi-Tawi Regional","ms":"Akta menukar status Sekolah Pertanian Sulu Kebangsaan Wilayah di Perbandaran Bongao, Wilayah Tawi-Tawi kepada Kolej dengan nama Kolej Pertanian Tawi-Tawi Wilayah"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 384","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-08","completenessNote":"全文，共 17 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00384_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00384_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15249-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Sulu National Regional Agricultural School in the Municipality of Bongao, Province of\nTawi-Tawi, is hereby converted into a college to be known as the Tawi-Tawi Regional Agricultural College,\nhereinafter referred to in this Act as the College."}},{"id":"PH-H15249-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"In addition to its present curricula, the College is authorized to offer the following collegiate and\ngraduate courses:\n(a) Four-year teacher education courses leading to the degrees of Bachelor of Science in Agricultural\nEducation and Bachelor of Science in Home Technology;\n(b) Four-year technical curriculum leading to the degree of Bachelor of Science in Agriculture;\n(c) Graduate course leading to the degree of Master of Science in Agricultural Education;\n(d) Graduate course leading to the degree of Master of Science in Home Technology; and\n(e) Graduate course leading to the degree of Master of Science in Agriculture."}},{"id":"PH-H15249-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The aim of the College shall be to provide professional, technical, and special training and\npromote research, extension services, and progressive leadership in the field of agriculture and home\ntechnology."}},{"id":"PH-H15249-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The head of the College shall be known as the President of the Tawi-Tawi Regional Agricultural\nCollege. He shall be appointed by the President of the Philippines upon recommendation of the Board of\nTrustees as hereinafter provided. He shall serve for a term of six years but he may be reappointed. The powers\nand duties of the President of the College, in addition to those specifically provided in this Act, shall be these\nusually pertaining to the office of the president of a college."}},{"id":"PH-H15249-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The Tawi-Tawi Regional Agricultural College shall have the general powers set out in Section\n36 of Batas Pambansa Bilang 68 and the government and administration of the College and the exercise of its\ncorporate powers are hereby vested in a Board of Trustees. The Board of Trustees shall be composed of the\nMinister of Education, Culture and Sports, who shall be ex officio Chairman of the Board, the Regional\nDirector of the National Economic and Development Authority, the President of the College, and four (4)\nprominent citizens of Region IX preferably from the Province of Tawi-Tawi, to be appointed by the President\nof the Philippines as members. When both the Minister and the Deputy Minister of Education, Culture and\nSports are unable to exercise the powers of the Chairman of the Board of Trustees, the members of the Board\nmay elect from among themselves a temporary chairman who shall act as Chairman of the Board of Trustees.\nThe non-ex officio members of the Board, except the President of the College who shall serve during the\nduration of his incumbency, shall hold office as follows: two to serve for two years and the other two to serve\nfor four years, the term of office of each to be specified in his appointment by the President. Thereafter,\npersons appointed to succeed such members shall hold office for a term of four years and until their\nsuccessors shall have been appointed and qualified.\n\nMembers of the Board of Trustees shall serve without compensation, other than actual and necessary expenses\nincurred either in attendance upon meetings of the Boards of Trustees or upon other official business\nauthorized by resolution of the Board, subject to existing budget laws on honoraria and allowances."}},{"id":"PH-H15249-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The Board of Trustees shall have the following powers and duties, in addition to its general\npowers of administration:\n(a) To receive and appropriate to the end specified by law such sums of money as may be provided by law for\nthe support of the College;\n(b) To confer, aside from the degrees now offered by the Sulu National Regional Agricultural School, the\ndegrees of Bachelor of Science Agricultural Education, Bachelor of Science in Home Technology, Bachelor\nof Science in Agriculture, Master of Science in Agricultural Education, Master of Science in Home\nTechnology, and Master of Science in Agriculture;\n(c) To appoint, on the recommendation of the President of the College, professors, instructors, lecturers,\nadministrative and supervisory officials, and other employees of the College, as may be necessary for the\neffective implementation of the college program; to fix their compensation, subject to Presidential Decree No.\n985 and other pertinent budget and compensation laws, hours of service and such other duties and conditions\nas it may deem proper; to grant them, in its discretion, leave of absence under regulations as it may\npromulgate, other provisions of law notwithstanding; to prescribe rules of academic discipline for the\neducational and professional growth of faculty members and other personnel; and to remove them for cause\nafter an investigation and hearing shall have been held;\n(d) To approve the curricula and rules of discipline drawn up by the College Council as hereinafter provided;\n(e) To provide fellowship for faculty members and scholarships to students showing special evidence of merit;\n(f) To provide rules for its government, and to enact for the government of the College such general\nordinances and regulations, not contrary to law, as are consistent with the purposes of the College, as defined\nin Section three of this Act;\n(g) To receive in trust legacies, gifts and donations of real and personal property of all kinds, and to administer\nthe same for the benefit of the College or for aid to any student, in accordance with the directions and\ninstructions of the donor, and in default thereof, in such manner as the Board of Trustees may, in its discretion\n(h) A quorum of the Board of Trustees shall consist of a majority of all its members holding office at the time\nthe meeting of the Board is called."}},{"id":"PH-H15249-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"On or before the fifteenth August of each year, the Board of Trustees shall file with the President\na detailed report, setting forth the progress, conditions and needs of the College."}},{"id":"PH-H15249-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"There shall be a College Council consisting of the President of the College as presiding officer\nand all professors and instructors of the College as members. The Council shall have the power to prescribe\nthe curricula and rules of discipline, subject to the approval of the Board of Trustees. It shall fix the\nrequirements for admission to the College, as well as for graduation and the receiving of a title or a degree.\nThe Council alone shall have the power to recommend students or others to be recipients of titles or degrees.\nThrough its president or committee, it shall have disciplinary power over the students within the limits\nprescribed by the rules of discipline approved by the Board of Trustees."}},{"id":"PH-H15249-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"The body of professors and instructors of the College shall constitute the faculty of the College.\nIn the appointment of professors or instructors of the College, no religious test shall be applied nor shall\nreligious opinions or affiliations of faculty of the College be made a matter of examination or inquiry:\nProvided, however, That no professor or instructor in the College shall inculcate sectarian teachings, nor\nattempt either directly or indirectly, under penalty of dismissal by the Board of Trustees, to influence students\nattending the College for or against any particular church or religious sect."}},{"id":"PH-H15249-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"Professors and other teaching personnel of the College shall be covered by the appropriate civil\nservice rules and regulations."}},{"id":"PH-H15249-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"There shall be a secretary of the College, appointed by the Board of Trustees. He shall be the\nsecretary of such Board and also of the College."}},{"id":"PH-H15249-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"To help the College achieve its educational, research and extension aims, the College Council\nis hereby empowered to negotiate or make arrangements with government colleges or universities, private\ncolleges and universities, other government agencies, and private or semi-private organizations for\ncooperative projects in instructions, research, and extension; and to seek the assistance of educational\nfoundations in promoting the programs of instruction, research, and extension."}},{"id":"PH-H15249-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"Heads of bureaus or offices of the national government are hereby authorized to loan, or\ntransfer, upon request of the President of the College, equipment, apparatus, or supplies as may be needed by\nthe College, and to detail employees for duty therein, when in the judgment of the head of the bureau or office\nsuch supplies or employees can be spared without serious detriment to the public service."}},{"id":"PH-H15249-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"The College, by arrangement with the Director of Technical and Vocational Education and\nDirector of Secondary Education, may use one or more vocational or general public schools as training or\nlaboratory schools of the College."}},{"id":"PH-H15249-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"The present faculty of the Sulu National Regional Agricultural School, as well as the\nadministrative and supervising officials and other personnel as well as the present buildings, equipment and\nfacilities and other properties, real and personal, shall be absorbed by the new college. Salaries of these\npersonnel shall be determined in accordance with Presidential Decree No. 985 and other pertinent budget and\ncompensation laws."}},{"id":"PH-H15249-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"All existing appropriations for the Sulu National Regional Agricultural School are hereby\ntransferred to the Tawi-Tawi Regional Agricultural College, to be disbursed in accordance with the provisions\nof this Act. The necessary sum for the operation and maintenance of the state college shall be provided for in\nsubsequent General Appropriations Acts, until which time the operation of the institution as a college shall be\ndeferred, provided that its new name shall take effect upon the approval of this Act."}},{"id":"PH-H15249-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 8, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15250"] = {"id":"PH-H15250","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 385  An Act Converting the Zamboanga Del Sur National Agricultural School in the Municipality of Dumingag, Province of Zamboanga Del Sur, Into a College to Be Known as the Zamboanga Del Sur Agricultural College.","orig":"Batas Pambansa Blg. 385  An Act Converting the Zamboanga Del Sur National Agricultural School in the Municipality of Dumingag, Province of Zamboanga Del Sur, Into a College to Be Known as the Zamboanga Del Sur Agricultural College.","vi":"Đạo luật chuyển đổi Trường Nông nghiệp Zamboanga Del Sur Quốc gia tại Thị trấn Dumingag, Tỉnh Zamboanga Del Sur thành Cao đẳng với tên gọi Cao đẳng Nông nghiệp Zamboanga Del Sur","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนเกษตรกรรม Zamboanga Del Sur แห่งชาติในเทศบาล Dumingag จังหวัด Zamboanga Del Sur เป็น วิทยาลัยในชื่อวิทยาลัยเกษตรกรรม Zamboanga Del Sur","id":"Undang-Undang mengubah Sekolah Pertanian Zamboanga Del Sur Nasional di Kotamadya Dumingag, Provinsi Zamboanga Del Sur menjadi Sekolah Tinggi dengan nama Sekolah Tinggi Pertanian Zamboanga Del Sur","ms":"Akta menukar status Sekolah Pertanian Zamboanga Del Sur Kebangsaan di Perbandaran Dumingag, Wilayah Zamboanga Del Sur kepada Kolej dengan nama Kolej Pertanian Zamboanga Del Sur"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 385","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00385_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00385_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15250-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Zamboanga del Sur National Agricultural School in the Municipality of Dumingag,\nProvince of Zamboanga del Sur, is hereby converted into a college to be known as the Zamboanga del Sur\nAgricultural College."}},{"id":"PH-H15250-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Zamboanga del Sur Agricultural College shall offer, in addition to its present curricular\nofferings, such collegiate courses as may be authorized by the Ministry of Education, Culture and Sports."}},{"id":"PH-H15250-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Ministry of Education, Culture and Sports shall take the necessary steps for the immediate\nimplementation of this Act."}},{"id":"PH-H15250-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The existing appropriations for the Zamboanga del Sur National Agricultural School are hereby\ntransferred to the Zamboanga del Sur Agricultural College, to be disbursed in accordance with the provisions\nof this Act. Thereafter, the necessary amount required for the operation and maintenance of the college shall\nbe provided for in subsequent General Appropriations Acts, until which time the operation of the institution as\na college shall be deferred, provided that its new name shall take effect upon approval of this Act.\nApproved: April 14, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15251"] = {"id":"PH-H15251","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 386  An Act Creating the Municipality of Marcos in the Province of","orig":"Batas Pambansa Blg. 386  An Act Creating the Municipality of Marcos in the Province of"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 386","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00386_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00386_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15251-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The barangays of Bunog, Iraan, Punta Baja, Capung Ulay, Ramsang, Candawag, Culasian,\nPanalingaan, Tabuin, Latud, and Canipaan are hereby separated from the Municipality of Quezon, Province of\nPalawan, and constituted into a distinct and independent municipality to be known as the Municipality of\nMarcos. The seat of government of the new municipality will be in Barangay Punta Baja."}},{"id":"PH-H15251-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Municipality of Marcos shall be bounded as follows:\n\"A parcel of land known as the proposed Municipality of Marcos, in the Province of Palawan, Luzon Island,\nbounded in the north along lines 11 and 1 in the Plan by the municipal boundary of Quezon, on the south\nalong lines 2 and 3 by Sulu Sea, on the east along lines 1 and 2 by the municipal boundary of Brooke’s Point,\non the west along lines 3 to 11 by the shoreline of the South China Sea. Beginning at the point marked 1 in the\nplan at latitude 8° 59’ 10\" T north, longitude 117° 50’ 32\"; thence S 62-00W 80,750 meters to point 2;\nthence N 85-00W 5,800 meters to point 3; thence N 31-29E 20,670.35 meters to point 4; thence N 46-13E\n8,298.46 meters to point 5; thence N 52-21E 6,137.67 meters to point 6; thence N 39-14E 9,594.37 meters to\npoint 7; thence N 37-45E 11,017.16 meters to point 8; thence N 53-08E 10,364.93 meters to point 9; thence N\n41-12E 14,556.17 meters to point 10; thence N 76-02E 6,509.60 meters to point 11; thence S 48-10E\n14,442.69 meters to point 12, containing an area of nine hundred seventy-seven million, two hundred\nsixty-one thousand two hundred square meters (977,261,200 square meters) or ninety-seven thousand seven\nhundred twenty-six and twelve hundredth hectares (97,726.12 hectares).\""}}],"pack":"ph-p156"};
  FT["PH-H15252"] = {"id":"PH-H15252","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 387  An Act Converting the Larena National Vocational School in the Municipality of Larena, Province of Siquijor, Into a College, to Be Known as the Larena National Vocational College.","orig":"Batas Pambansa Blg. 387  An Act Converting the Larena National Vocational School in the Municipality of Larena, Province of Siquijor, Into a College, to Be Known as the Larena National Vocational College.","vi":"Đạo luật chuyển đổi Trường Dạy nghề Larena Quốc gia tại Thị trấn Larena, Tỉnh Siquijor thành Cao đẳng với tên gọi Cao đẳng Dạy nghề Larena Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนอาชีวศึกษา Larena แห่งชาติในเทศบาล Larena จังหวัด Siquijor เป็น วิทยาลัยในชื่อวิทยาลัยอาชีวศึกษา Larena แห่งชาติ","id":"Undang-Undang mengubah Sekolah Kejuruan Larena Nasional di Kotamadya Larena, Provinsi Siquijor menjadi Sekolah Tinggi dengan nama Sekolah Tinggi Kejuruan Larena Nasional","ms":"Akta menukar status Sekolah Vokasional Larena Kebangsaan di Perbandaran Larena, Wilayah Siquijor kepada Kolej dengan nama Kolej Vokasional Larena Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 387","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00387_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00387_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15252-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Larena National Vocational School in the Municipality of Larena, Province of Siquijor, is\nhereby converted into a college to be known as the Larena National Vocational College."}},{"id":"PH-H15252-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"In addition to its secondary and vocational curricular offerings, the college shall offer such\ncollegiate courses as may be authorized by the Minister of Education, Culture and Sports."}},{"id":"PH-H15252-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Minister of Education, Culture and Sports is hereby directed to take the necessary steps for\nthe immediate implementation of this Act."}},{"id":"PH-H15252-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The existing appropriations for the Larena National Vocational School are hereby transferred to\nthe Larena National Vocational College, to be disbursed in accordance with the provisions of this Act.\nThereafter, the necessary amount required for the operation and maintenance of the college shall be provided\nfor in subsequent General Appropriations Acts, until which time the operation of the institution as a college\nshall be deferred, provided that its new name shall take effect upon approval of this Act."}},{"id":"PH-H15252-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act take effect upon its approval.\nApproved: April 14, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15253"] = {"id":"PH-H15253","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 388  An Act Converting the Pag-Asa Barangay High School in Barangay Rawis, City of Legaspi, Into a National High School, to Be Known as the Pag-Asa National High School.","orig":"Batas Pambansa Blg. 388  An Act Converting the Pag-Asa Barangay High School in Barangay Rawis, City of Legaspi, Into a National High School, to Be Known as the Pag-Asa National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Pag-Asa Barangay tại Barangay Rawis, Thành phố Legaspi thành Trường Trung học Quốc gia với tên gọi Trường Trung học Pag-Asa Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Pag-Asa Barangay ในบารังไกย์ Rawis เมือง Legaspi เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Pag-Asa แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Pag-Asa Barangay di Barangay Rawis, Kota Legaspi menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Pag-Asa Nasional","ms":"Akta menukar status Sekolah Menengah Pag-Asa Barangay di Barangay Rawis, Bandar Legaspi kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Pag-Asa Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 388","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00388_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00388_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15253-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Pag-asa Barangay High School in Barangay Rawis, City of Legaspi, is converted into a\nnational high school, to be known as the Pag-asa National High School."}},{"id":"PH-H15253-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, such sum as may be necessary for its operation and maintenance shall be included in the\nannual General Appropriations Act."}},{"id":"PH-H15253-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 14, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15254"] = {"id":"PH-H15254","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 389  An Act Converting the Silago Barangay High School in Central, Municipality of Silago, Province of Southern Leyte, Into a National Vocational High School to Be Known as Silago National Vocational High School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 389  An Act Converting the Silago Barangay High School in Central, Municipality of Silago, Province of Southern Leyte, Into a National Vocational High School to Be Known as Silago National Vocational High School, and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 389","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00389_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00389_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15254-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Silago Barangay High School in Central, Municipality of Silago, Province of Southern\nLeyte, is hereby converted into a national vocational high school to be known as Silago National Vocational\nHigh School."}},{"id":"PH-H15254-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, the amount needed for the operation and maintenance of the school shall be included in the\nannual General Appropriations Act."}},{"id":"PH-H15254-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 14, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15255"] = {"id":"PH-H15255","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 390  An Act Further Amending Section Four of Republic Act Numbered Forty Hundred Ninety-three, as Amended, Otherwise Known as the Private Development Banks' Act, Which Provides for the Organization of Private Development","orig":"Batas Pambansa Blg. 390  An Act Further Amending Section Four of Republic Act Numbered Forty Hundred Ninety-three, as Amended, Otherwise Known as the Private Development Banks' Act, Which Provides for the Organization of Private Development"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 390","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-14","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00390_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00390_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15255-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Section four of Republic Act Numbered Forty hundred and ninety-three, as amended, is further\namended to read as follows:\n\"Sec. 4. A private development bank shall be organized in the form of a stock corporation: Provided, That at\nleast seventy percent of the voting stock subscribed by the private sector shall be owned and held by citizens\nof the Philippines, except where a new bank is established as a result of the consolidation of existing private\ndevelopment banks in any of which there are foreign-owned voting stocks at the time of consolidation:\nProvided, however, That the Monetary Board may with the approval of the President of the Philippines reduce\nthe required minimum percentage of the Philippine ownership prescribed herein from seventy (70%) percent\nto sixty (60%) percent: Provided, further, That shares of stock subscribed by the Development Bank of the\nPhilippines under authority existing prior to the effectivity of Batas Pambansa Bilang 63 shall be preferred\nshares entitled to cumulative dividends at the yearly rate of one percent during the first five years, two percent\nduring the following five years, and three percent thereafter, shall be preferred as against common and other\npreferred stockholders in the distribution of assets in the event of liquidation, and shall be entitled to voting\nprivileges: Provided, still further, That such preferred shares of the bank may at any time be paid off at not\nless than par and retired in whole or in part if, in the opinion of the Monetary Board, the bank has accumulated\nenough capital strength to permit retirement of such shares, or sold at not less than par to private individuals\nwho are citizens of the Philippines, and in the sale thereof, the qualified registered stockholders shall have the\nright of pre-emption within one year from the date of offer in proportion to their respective holdings, but in\nthe absence of such buyers, preference shall be given to residents of the province or city where the\ndevelopment bank is located: Provided, finally, That such preferred shares may be converted to common\nshares when sold to private individuals. At least two-thirds of the members of the board of directors of the\nprivate development bank shall be citizens of the Philippines: Provided, however, That no appointive or\nelective public official, whether full-time or part-time, shall at the time serve as officer of any private\ndevelopment bank, except in cases where such service is incident to financial assistance provided by the\ngovernment or a government-owned or controlled corporation to the bank: Provided, further, That in the case\nof merger or consolidation of private development banks duly approved by the Monetary Board, the limitation\non the maximum number of corporate directors in a corporation, as provided for in Section 14 of the\nCorporation Code of the Philippines, shall not be applied so that membership in the new board may include up\nto the total number of directors provided for in the respective articles of incorporation of the merging or\nconsolidating private development banks.\""}}],"pack":"ph-p156"};
  FT["PH-H15256"] = {"id":"PH-H15256","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":15,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 391  An Act Declaring the 1983 Investment Incentives Policy By Modifying the System on the Grant of Investment Incentives, Amending Foe the Purpose Presidential Decree Numbered Seventeen Hundred and Eighty-Nine and Other Pertinent Laws on Investments.","orig":"Batas Pambansa Blg. 391  An Act Declaring the 1983 Investment Incentives Policy By Modifying the System on the Grant of Investment Incentives, Amending Foe the Purpose Presidential Decree Numbered Seventeen Hundred and Eighty-Nine and Other Pertinent Laws on Investments."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 391","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-04-28","completenessNote":"全文，共 15 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00391_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00391_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15256-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"This Act shall be known and referred to as the Investment Incentive Policy Act of 1983."}},{"id":"PH-H15256-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Declaration of Investment Policy. — It is the policy of the State to encourage private domestic\nand foreign investments in industry, agriculture, mining and other sectors of the economy which shall: provide\nsignificant employment opportunities relative to the amount of the capital being invested; increase\nproductivity of the land, minerals, forestry, aquatic and other resources of the country, and improve utilization\nof the products thereof; improve technical skills of the people employed in the enterprise; provide a\nfoundation for the future development of the economy; meet the tests of international competitiveness;\naccelerate development of less developed regions of the country; and result in increased volume and value of\nexports for the economy.\nIt is the policy of the State to extend to projects which will significantly contribute to the attainment of these\nobjectives, fiscal incentives without which said projects may not be established in the locales, number and/or\npace required for optimum national economic development. Fiscal incentive systems shall be devised to\ncompensate for market imperfections, reward performance of making contributions to economic development,\ncost-efficient and be simple to administer.\nThe fiscal incentives shall be extended to stimulate establishment and assist initial operations of the enterprise,\nand shall terminate after a period of not more than 10 years from registration or start-up of operation unless a\nspecific period is otherwise stated.\nThe foregoing declaration shall apply to all investment incentive schemes and in particular will supersede\nArticle 2 of Presidential Decree No. 1789."}},{"id":"PH-H15256-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"A new Article 18 is hereby inserted in Chapter 1 Title I, Book One of the Omnibus Investments\nCode, hereafter referred to as the Code, which shall read as follows:\n\"Art 18. (a) 'Registered Domestic Producer' shall mean a registered enterprise engaged in the production,\nmanufacturing or processing of goods or commodities primarily for the domestic market and inclusive of\nproduction services.\n\"(b) 'Registered Agricultural Producer' shall mean a registered enterprise engaged in agricultural production\nand/or services directly related to, and necessary for, such production.\""}},{"id":"PH-H15256-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Article 19 of the Code is hereby amended to read as follows:\n\"Art. 19. (a) 'Registered New or Expanding Export Producer' shall mean a registered enterprise proposing (1)\nto engage in or expand the production, manufacture or processing of export products as defined in Article 23\nof the Code; and (2) to directly export at least fifty percent (50%) of its products or sell them to an export\ntrader which subsequently exports said products.\n\n\"(b) 'Registered Existing Export Producer' shall mean a registered enterprise already engaged, at the time of\nregistration, in the production, manufacture or processing of export products as defined in Article 23 of the\nCode and directly exporting its products or selling them to an export trader which subsequently exports said\n\"(c) 'Registered Indirect Export Producer' shall mean an enterprise which sells its products to another\nproducer as raw materials for, or components to, an export product which is finally exported.\n\"(d) 'Registered Export Trader' shall mean an enterprise engaged or proposing to engage in the sale abroad of\nexport products bought by it from one or more export producers, and duly registered as such by the Board.\""}},{"id":"PH-H15256-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Article 22 of the Code is hereby amended to read as follows:\n\"Art. 22. 'Tax Credit' shall mean any of the credits against taxes and/or duties paid or would have been paid\nor based on a percentage of net value earned or of net local content of exports extended to a registered\nenterprise by this Code to evidence which a tax credit certificate shall be issued by the Minister of Finance or\nhis representative, except in cases of tax credits on net value earned and net local content which shall be\nissued by the Chairman of the Board or his representative. The tax credit certificates are transferable under\nsuch conditions as may be determined by the Board after consultation with the Ministry of Finance. However,\nthe tax credit based on net value earned or of net local content can be transferred only to domestic raw\nmaterials or component suppliers of the registered enterprise which in turn can transfer such certificates to its\nsuppliers, whether registered enterprises or not. The tax credit certificate shall be used to pay taxes, duties,\ncharges and fees due to the national government: Provided, That the tax credits issued under this Code shall\nnot form part of the gross income of the grantee/transferee for income tax purposes under Section 29 of the\nNational Internal Revenue Code and are therefore not taxable: Provided, further, That such tax credits shall be\nvalid only for a period of ten (10) years from date of issuance.\""}},{"id":"PH-H15256-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Article 28 of the Code is hereby repealed and, in lieu thereof, a new Article 28 is therein inserted\nto read as follows:\n\"Art. 28. 'Investment Priorities Plan' shall mean the over-all plan prepared by the Board and approved by the\nPresident which includes and contains:\n\"(a) The specific activities and generic categories of economic activity wherein investments are to be\nencouraged and the corresponding products and commodities to be grown, processed or manufactured\npursuant thereto for the domestic or export market;\n\"(b) Specific public utilities which can qualify for incentives under this Code and which shall be supported by\nstudies of existing and prospective regional demands for the services of such public utilities in the light of the\nlevel and structure of income, production, trade, prices and relevant economic and technical factors of the\nregions as well as the existing facilities to produce such services;\n\"(c) Specific activities where the potential for utilization of indigenous non-petroleum based fuels or sources\nof energy can be best promoted; and\n\"(d) Such other information, analysis, data, guidelines or criteria as the Board may deem appropriate.\n\"The specific and generic activities to be included in the Investment Priorities Plan with their status as pioneer\nor non-pioneer shall be determined by the Board in accordance with the criteria set forth in this Code.\""}},{"id":"PH-H15256-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Article 30 of the Code is hereby repealed and, in lieu thereof, a new Article 30 is therein\ninserted, to read as follows:\n\"Art. 30. Criteria in Investment Priority Determination. — No economic activity shall be included in the\nInvestment Priorities Plan unless it is shown to be economically, technically and financially sound after\nthorough investigation and analysis by the Board.\n\"The determination of preferred areas of investment to be listed in the Investment Priorities Plan shall be\nbased on long-run comparative advantage, taking into account the value of social objectives and employing\n\neconomic criteria along with market, technical, and financial analysis.\n\"The Board shall take into account the following:\n\"(a) Primarily, the economic soundness of the specific activity as shown by the real economic internal rate of\nreturn of the project;\n\"(b) The extent of contribution of an activity to a specific development goal;\n\"(c) Other indicators of comparative advantage;\n\"(d) Measured capacity as defined in Article 21 discounting inefficient existing capacities; and\n\"(e) The market and technical aspects and considerations of the activity proposed to be included.\n\"In any of the declared preferred areas of investment, the Board may designate as pioneer areas the specific\nproducts and commodities that meet the requirements of Article 16 of this Code and review yearly whether\nsuch activity as determined by the Board shall continue as pioneer, otherwise it shall be considered as\nnon-pioneer and accordingly listed as such in the Investment Priorities Plan or removed from the Investment\nPriorities Plan.\""}},{"id":"PH-H15256-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Article 39 of the Code is hereby amended to read as follows:\n\"Art. 39. Several Applicants for a Preferred Area. — Where several applicants are qualified for registration\nwith the Board but the total of their proposed combined production capacities exceeds the available measured\ncapacity of the preferred area of investments in which they are proposing to engage or of the identical or\nsubstantially identical products or commodities they propose to produce, the Board shall approve and register\nonly those that can be accommodated within the available measured capacity and are better suited to achieve\nthe objectives of the Code, primarily basing its choice on the economic rates of return of the competing\nprojects. When the economic rates of return of the projects are equal or the differences therein are\ninsubstantial, the Board shall base its choice on the following criteria:\n\"(a) The extent of ownership and control by Philippine citizens of the enterprises, giving priority to the\nenterprise which has more Filipino participation;\n\"(b) The cost factors and the economies of scale and competitiveness in the world market involved in their\n\"(c) The amount of foreign exchange earned, used, or saved in their operations;\n\"(d) The extent to which they employ, labor, materials and other resources obtained from indigenous sources;\n\"(e) The amount of their equity, and the degree to which the ownership of such equity is spread out and\ndiversified;\n\"(f) The extent to which they shall insure the maintenance of compensation within the industry; and\n\"(g) Such other criteria as the Board may determine.\""}},{"id":"PH-H15256-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"Chapter I of Title IV of the Code entitled \"Registered Producer Enterprises\" including Article 45\nis hereby amended to read as follows:\nRegistered Domestic Producers\n\"Art. 45. Incentives to Registered Domestic Producers. — All registered domestic producers may be granted\nthe following incentives to the extent that it will engage in new or expanded production capacity in preferred\narea of investment:\n\"(a) Tax and Duty Exemption on Imported Capital Equipment. — Within five (5) years from the date of\nregistration, importations of machinery and equipment and accompanying spare parts shall be exempt to the\nextent of fifty percent (50%) in case of non-pioneer domestic producer, or one hundred percent (100%) in case\n\nof pioneer producer, of the tariff duties and compensating tax payable thereon: Provided, That the amount of\nsuch tax and duty exemptions shall be deducted from the amount of the tax credits available to the registered\ndomestic producer under paragraphs (c) and (f) hereof in relation to paragraph (d) of Article 48: Provided,\nhowever, That in the event the tax credits on net value earned and on net local content computed on a yearly\nbasis for five (5) years from the date of commercial operation are not sufficient to pay yearly 20% of the taxes\nand duties on the equipment and spare parts, the domestic producer shall be required to pay the difference for\nthat particular year. This payment may be deferred to the succeeding year only, subject to the payment of\ninterest. The importation of machinery and equipment and accompanying spare parts shall comply with the\nfollowing conditions:\n\"(1) They are not manufactured domestically in sufficient quantity, of comparable quality and at reasonable\n\"(2) They are reasonably needed and will be used exclusively by the registered domestic producer in the\nmanufacture of its products, unless prior approval of the Board is secured for the part-time utilization of said\nequipment in a non-registered activity to maximize usage thereof or the appropriate taxes and duties are paid\non the specific equipment and machinery being permanently used for non-registered activities; and\n\"(3) The approval of the Board was obtained by the registered enterprise for the importation of such\nmachinery, equipment and spare parts.\n\"In granting the approval of the importations under this paragraph, the Board may require international\ncanvassing but if the total cost of the capital equipment or industrial plant exceeds US$5,000,000, the Board\nshall apply or adopt the provisions of Presidential Decree Numbered 1764 on international competitive\n\"If the registered domestic producer sells, transfers or disposes of these machinery, equipment and spare parts\nwhose taxes and duties have not been fully repaid with tax credits earned, without prior approval of the Board\nwithin five (5) years from date of acquisition, the registered domestic producer and the vendee, transferee, or\nassignee shall be solidarily liable to pay twice the amount of the tax exemption given it. However, the Board\nshall allow and approve the sale, transfer or disposition of the said items within the said period of five (5)\nyears if made:\n\"(aa) to another registered enterprise or registered domestic producer enjoying similar incentives;\n\"(bb) for reasons of proven technical obsolescence; or\n\"(cc) for purposes of replacement to improve and/or expand the operations of the registered domestic\n\"In such cases, the transferee shall not be subject to the taxes and duties waived on the said equipment, if any.\nIn case of disposition after the five-year period, the transferee shall not be subject to taxes and duties if it will\nundertake an economic project substantially carrying out the purposes for which such equipment has been\nimported, as determined by the Board.\n\"(b) Tax Credit on Domestic Capital Equipment. — A tax credit equivalent to the value of the compensating\ntaxes and customs duties that would have been waived on the machinery, equipment and spare parts, had these\nitems been imported shall be given to the registered domestic producer which purchases machinery,\nequipment and spare parts from a domestic manufacturer: Provided, That the amount of the tax credit granted\npursuant thereto shall be deducted from the amount of the tax credits available to the registered domestic\nproducer under paragraphs (c) and (f) hereof in relation to paragraph (d) of Article 48: Provided, however,\nThat in the event the tax credits on net value earned and on net local content computed on a yearly basis for\nfive (5) years from the date of commercial operation are not sufficient to pay yearly 20% of the taxes and\nduties on the equipment and spare parts, the domestic producer shall be required to pay the difference for that\nparticular year as provided in the immediately preceding article: and Provided, finally, (1) That the said\nequipment, machinery and spare parts are reasonably needed and will be used exclusively by the registered\n\ndomestic producer in the manufacture of its products, unless prior approval of the Board is secured for the\npart-time utilization of said equipment in a non-registered activity to maximise usage thereof; (2) that the\nequipment would have qualified for tax and duty-free importation under paragraph (a) hereof; (3) that the\napproval of the Board was obtained by the registered domestic producer; and (4) that the purchase is made\nwithin five (5) years from the date of registration of the registered domestic producer. If the registered\ndomestic producer sells, transfers or disposes of these machinery, equipment and spare parts, the provisions in\nthe preceding paragraph for such disposition shall apply.\n\"(c) Tax credit on net value earned. — For the first five (5) years of commercial operation, all registered\ndomestic producers shall be entitled to a tax credit equivalent to five percent (5%) of net value earned. Those\nengaged in pioneer projects shall be entitled to this incentive to the extent of ten percent (10%) of net value\nearned over the same period or coterminous with the remaining period of availment of the registrant who first\nstarts commercial operation in case there are several registered pioneer enterprises in the same activity,\nregardless of their respective dates of registration. For purposes of calculation of the tax credit, \"net value\nearned\" shall mean value of sales less cost of raw materials and components, supplies and utilities and\ndepreciation of capital equipment. For raw materials and components which are produced by the registered\nenterprise, allocated costs may be determined by the Board. asia dc\n\"(d) Net Operating Loss Carry-Over. — A net operating loss inclusive of financial charges of the registered\nactivity incurred in any of the first ten (10) years of operation may be carried over as a deduction from taxable\nincome from registered activities for the six (6) years immediately following the year of such loss. The entire\namount of the loss shall be carried over to the first of the six (6) taxable years following the loss, and any\nportion of such loss which exceeds the taxable income of such first year shall be deducted in like manner from\nthe taxable income of the next remaining five (5) years.\n\"(e) Tax Credit for Withholding Tax on Interest. — A tax credit for taxes withheld on interest payments on\nforeign loans entered into within the first 5 years of registration or commercial operation shall be given a\nregistered pioneer enterprise when (1) no such credit is available to the original lender-remittee in his country;\nand (2) the registered pioneer enterprise has assumed the liability for payment of the tax due from the\nlender-remittee.\n\"(f) Special Incentives for Exports. — To the extent that a domestic producer is engaged directly or indirectly\nin the export of a portion of its production, it shall be entitled to the incentives granted under paragraphs (d)\nand (i) of Article 48, in case of direct exporters and Article 48-B (1), in case of indirect exporters. The\nrepayment of the taxes and duties waived on imported machinery and equipment as required in the first\nprovisos of paragraphs (a) and (b) hereof shall be proportionately reduced based on the percentages of exports\nto domestic sales.\n\"(g) Employment of Foreign National. — Subject to the provisions of Section 29 of Commonwealth Act\nNumbered 613, as amended, a registered domestic producer may employ foreign nationals in supervisory,\ntechnical or advisory positions for a period not exceeding five (5) years from its registration, extendible for\nlimited periods at the discretion of the Board: Provided, however, That when the majority of the capital stock\nof a pioneer registered domestic producer is owned by foreign investors, the positions of president, treasurer\nand general manager or their equivalents may be retained by foreign nationals beyond the period set forth\n\"Foreign nationals under employment contract within the purview of this incentive, their spouses and\nunmarried children under twenty-one (21) years of age, who are not excluded by Section 29 of\nCommonwealth Act Numbered 613, as amended, shall be permitted to enter and reside in the Philippines\nduring the period of employment of such foreign nationals.\n\"A registered domestic producer shall train Filipinos as understudies of foreign nationals in administrative,\nsupervisory and technical skills and shall submit annual reports on such training to the Board.\n\n\"(h) Anti-Dumping Protection. — Upon recommendation of the Board, made after notice and hearing, the\nPresident shall issue a directive banning for a limited period the importation of goods or commodities which\nunfairly compete with those produced by registered domestic producers: Provided, (1) That the Board certifies\nto the satisfactory quality of the goods or commodities produced or manufactured by the registered domestic\nproducers; and (2) that the producers agree not to increase the price of these goods or commodities during this\nperiod unless, for good cause, the Board allows such an increase.\n\"(i) Protection from Government Competition. — No agency or instrumentality of the government shall import\nor allow the importation, tax and duty-free, of products or items that are being produced or manufactured by\nregistered domestic producers, except when the President determines that the national interest so requires or\nwhen international commitments require international competitive bidding.\n\"(j) Protection of Patents and other Proprietary Rights. — Patents, trademarks, copyrights, trade names and\nother proprietary rights registered with appropriate agencies of the Government of the Philippines are\nprotected from infringement.\n\"(k) Post-operative Tariff Protection. — Upon recommendation of the Board, after consultation with the Tariff\nCommission or the National Economic and Development Authority, the President may issue a certification\nthat a pioneer industry shall be entitled to post-operative tariff protection for a specified period of time to be\nstated therein and to such an extent that the total duty does not exceed fifty percent (50%) of the dutiable\nvalue of imported items similar to those manufactured or produced by a pioneer enterprise. Said tariff shall\ntake effect automatically upon certification by the Board that the pioneer enterprise is operating on a\ncommercial scale.\""}},{"id":"PH-H15256-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"Chapter II of Title IV of the Code, entitled \"Additional Incentives to Pioneer Enterprises\"\nincluding Article 46 in its entirety, is hereby repealed and, in lieu thereof, a new Chapter II is therein inserted\nwhich shall read as follows:\nOther Incentives\n\"Art. 46. The following incentives may be granted to certain registered enterprises and investors:\n\"(a) Incentives for Energy-Saving Projects. — Any project for the installation of equipment accredited as an\nenergy-saving device by the Board accordingly included in the Investment Priorities Plan shall be considered\nas replacement investment and shall be granted the incentives provided in paragraphs (a) and (b) of Article 45\nwithout repayment of the taxes and duties waived on the importation of machinery and equipment and\naccompanying spare parts or of the tax credit in case of purchase of domestic machinery, equipment or spare\n\"(b) Incentives for Industry Rationalization Programs. — Whenever a rationalization program for an industry is\ncarried out pursuant to the Investment Priorities Plan or involves a new or expanded production capacity of a\nproject under the program, the industry or project may be granted all the incentives provided in Article 45 of\nthis Code. However, if the rationalization program involves replacement investment, it shall be entitled only\nto the incentives mentioned in paragraphs (a) and (b) of the said Article without repayment.\n\"(c) Special Incentive for Investment in National Development Fund. — If an investment is made in national\ndevelopment fund certificates issued under Executive Order Numbered 842, in lieu of direct investment in\nregistered pioneer enterprises as provided in subparagraph (a), Article 44 of this Code, an investment\nallowance shall be allowed from taxable income but not to exceed ten percent (10%) thereof: Provided, That if\nthe certificates are transferred or redeemed by the fund upon the request of the investors within three years,\nthe taxpayer shall lose the benefit of this deduction and his income tax liability shall be recomputed and he\nshall pay whatever additional sum be due plus interest thereon within thirty (30) days from the date of the\nredemption.\""}},{"id":"PH-H15256-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"Article 48 of the Code is hereby repealed and, in lieu thereof, a new Article 48 is hereby\ninserted in Chapter IV of Title IV of the Code to read as follows:\n\"Art. 48. Incentives for Registered New or Expanding Export Producers. — All registered export producers,\nwhether pioneer or non-pioneer, shall be granted the following incentives to the extent engaged in new\ncapacity or expansion of capacity in a preferred area of investment:\n\"(a) Tax and Duty Exemption on Imported Capital Equipment. — Full tax and duty exemption on imported\ncapital equipment under the same conditions set forth in subparagraph (a), Article 45 except that the amount\nof such exemption shall not be deducted from the tax credits available to the registered export producer under\nparagraphs (c) and (d) hereof: Provided, That at least fifty percent (50%) of such higher percentage as may be\nrequired by the Board is exported or sold to a registered export under that subsequently exports said products.\nFor the first five (5) years of commercial operation, in any year in which this export commitment is not\ncomplied with, Twenty percent (20%) of the value of exemption shall be deducted from the value of the tax\ncredits due in that year under paragraphs (c) and (d) hereof: Provided, further, That if the tax credit is not\nsufficient, the penalty hereinabove provided for failure to comply with the export commitment shall be paid in\ncash or deferred for the succeeding year only subject to the payment of interest.\n\"(b) Tax Credit on Domestic Capital Equipment. — A tax credit equivalent to the value of the compensating\ntaxes and customs duties that would have been waived on the machinery, equipment and spare parts had these\nitems been imported shall be given to registered export producers under the same conditions set forth in\nsubparagraph (b), Article 45 except that the amount of such tax credit shall not be deducted from the tax\ncredits that may be available to registered export producers under paragraphs (c) and (d) hereof, subject to the\nsame proviso in paragraph (a).\n\"(c) Tax Credit on Net Value Earned. — For the same period and at the same rates provided for in\nsubparagraph (c), Article 45, a tax credit on net value earned shall be granted to registered export producers.\n\"(d) Tax Credit on Net Local Content of Exports. — For the first five (5) years of commercial operation or\nregistration, all registered new or expanding export producers shall be entitled to a tax credit equivalent to ten\npercent (10%) of net local content without prejudice to the further enjoyment of the incentive for another\nperiod of five (5) years immediately following the tax credit to be computed on the basis of the increment in\nthe real terms over the average net local content for the immediately preceding three years of enjoyment of\nthis incentive. For purposes of calculation for the tax credit, \"net local content\" shall mean value of export\nsales less depreciation of capital equipment and the value of imported raw materials and supplies and\nindigenous commodities which the Board may exclude if they are not anyway available under clearly more\nfavorable terms in the international market.\n\"(e) Net Operating Loss Carry-Over. — A net operating loss carry-over under the same conditions and for the\nsame period and produce provided in subparagraph (d), Article 45 shall be granted to registered export\n\"(f) Tax Credit on Withholding Tax on Interest. — Under the same conditions in subparagraph (e), Article 45, a\ntax credit for withholding tax on interest payments on foreign loans shall be granted to registered export\n\"(g) Employment of Foreign National. — Under the same conditions and requirements and for the same period\nas well as categories of positions in subparagraph (g), Article 45, registered export producers may employ\nforeign nationals.\n\"(h) Exemption from Export Tax, Duty, Impost and Fee. — The provisions of law to the contrary\nnotwithstanding, exports by a registered export producer of its non-traditional registered export products shall\nbe exempted from any export, tax, duty, impost and fee, including wharfage fee.\n\"(i) Tax Credit for Taxes and Duties on Raw Materials. — Every registered export producer shall enjoy a tax\ncredit equivalent to the sales, compensating and specific taxes and duties paid on the supplies, raw materials\n\nand semi-manufactured products used in the manufacture, processing or production of its export products and\nforming part thereof, exported directly by the registered export producer or sold to an export trader who\nsubsequently exports said product: Provided, however, That where the cost of certain supplies or raw\nmaterials constitutes at least forty percent (40%) of the cost of production of the registered export product, tax\ncredit on sales, specific taxes and duties paid thereon may also be granted even if they do not form part of the\nregistered export product: and Provided, further, That the taxes on the supplies, raw materials and\nsemi-manufactured products domestically purchased are indicated as a separate item in the sales invoice.\n\"Nothing herein shall be construed as to preclude the Board from setting a fixed percentage of export sales as\nthe approximate tax credit for taxes and duties of raw materials based on an average or standard usage for\nsuch materials in the industry.\n\"(j) Other Incentives. — In addition to the foregoing incentives, registered export producers shall be extended\nthe following: casia\n\"(I) Anti-dumping protection as provided in subparagraph (h), Article 45;\n\"(II) Protection from government competition as provided in subparagraph (i), Article 45; and\n\"(III) Protection of patents and other proprietary rights as provided in subparagraph (j), Article 45.\""}},{"id":"PH-H15256-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"New Articles 48-A and 48-B under Chapter IV of Title IV of the Code are therein inserted\nwhich shall read as follows:\n\"Art. 48-A. Incentives to Registered Existing Export Producers. — Registered existing export producers shall\nbe granted the following incentives:\n\"a) Tax Credit on Net Local Content. — For five (5) years from date of registration, a tax credit equivalent to\nten percent (10%) of net local of exports as defined in subparagraph (d) of Article 48 shall be granted to an\nexisting registered export producer without prejudice to the availment of this incentive for an additional period\nof five (5) years: Provided, That the net local content shall be based on the increment in real terms over the\naverage export sales during the three year period immediately preceding the date of registration. For the\nadditional five (5) years of the tax credit shall be based on the increment in real terms over the average net\nlocal content earned during the immediately preceding three years of enjoyment of this incentive.\n\"b) Exemption from Export Tax, Duty, Impost and Fee. — Registered existing export producers shall be\nentitled to exemption from export tax, duty, impost and fee as provided for in subparagraph (h) of Article 48.\n\"c) Tax Credit for Tax and Duties on Raw Materials. — The special tax credit for sales, compensating and\nspecific taxes and duties on supplies, raw materials and semi-manufactured products used in the manufacture,\nprocessing and production of export products shall be issued to a registered existing export producer under the\nsame condition or requirement provided in subparagraph (i) of Article 48.\n\"Art. 48-B. Incentives to Registered Indirect Export Producers. — Registered indirect export producers shall be\ngranted the following incentives: (1) special tax credits for taxes and duties on supplies, raw materials and\nsemi-manufactured products used in indirect export as provided in paragraph (c) of the immediately preceding\nArticle; and (2) a tax credit of 5% of net value earned as defined in subparagraph (c), Article 45 but limited to\nthat associated to the production of indirect exports: Provided, That the net value earned shall be based on the\nincrement in real terms over the average export sales during the three-year period immediately preceding the\navailment of incentives: Provided further, That a producer who sells to another producer who uses such\nproduct as input of his own product which is subsequently sold as an input of another export producer is\nentitled to the incentives hereunder.\""}},{"id":"PH-H15256-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"Pending the rationalization program for agricultural producers, registered agricultural producers\nshall continue to enjoy the same incentives granted to them as provided for under Article 47 and pertinent\narticles of the Code prior to the amendment herein."}},{"id":"PH-H15256-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"Subparagraph (d) of Article 49 of the Code is hereby amended to read as follows:\n\n\"(d) For the first five (5) years from registration or commercial operation, to deduct from its taxable income\nfrom the domestic and export sales as well as income from other registered operations, in addition to the\nnormal deduction allowed by the National Internal Revenue Code, an amount equivalent to twenty percent\n(20%) of its total export sales: Provided, That the Board upon application of the registered export trader may\ngrant to registered export producer exporting then one-half of this deduction: Provided, further, That the\ndeduction of the registered export producer shall be applicable to its registered operations only;\"\n\"Art. 48.-B. Incentives to Registered Indirect Export by repealed and, in lieu thereof, a new Article 62 is\ntherein inserted which shall read as follows:\n\"Art. 62. No Entitlement Under Other Investment Laws. — An enterprise registered under this Code, as\namended, shall not be entitled to fiscal incentives granted under other incentive laws.\"\n*Section 16. Article 77 under the Final Provisions of the Code is hereby repealed and, in lieu thereof, a new"}},{"id":"PH-H15256-A77","no":77,"noLabel":{"en":"Article 77"},"text":{"en":"is therein inserted which shall read as follows:\n\"Art. 77. Confidentiality of Applications. — All applications filed under Book One and Book Two of this Code\nshall be confidential and shall not be disclosed to any person, except with the consent of the applicant or on\norders of a court of competent jurisdiction.\"\nSection 17. The Board shall promulgate rules and regulations to implement the intent and provisions of this\nAct, and shall have the authority to impose such fines in amounts that are just and reasonable in cases of late\nsubmission or non-compliance on the part of registered enterprises with reporting and other requirements\nunder the Code and its implementing rules and regulations. Such rules and regulations shall take effect after\nfifteen days following its publication in a newspaper of general circulation in the Philippines.\nSection 18. All applications with the Board involving new or expansion projects, pending as of January\n1983 and approved and registered under Book One of the Code between January 1983 and the date of\neffectivity of this law, can transfer under this law as a new or expanding enterprise. The Board shall formulate\nthe necessary implementing rules and regulations covering such transitory matters for purposes of attaining\nthe objectives of this Act. casia\nSection 19. The provisions of this Act are hereby declared to be separable and, in the event any of such\nprovisions is declared unconstitutional, the other provisions which are not affected thereby shall remain in full\nforce and effect.\nSection 20. The following provisions are hereby repealed:\n1) Section 53, P.D. 463 (Mineral Resources Development Decree);\n2) Section 1, P.D. 666 (Shipbuilding and Ship Repair Industry);\n3) Section 6, P.D. 1101 (Radioactive Minerals);\n4) LOI 508 extending P.D. 791 and P.D. 924 (Sugar); and\n5) The following articles of Presidential Decree 1789: 2, 18, 19, 22, 28, 30, 39, 49(d), 62, and 77. Articles 45,\n46 and 48 are hereby amended only with respect to domestic and export producers.\nAll other laws, decrees, executive orders, administrative orders, rules and regulations or parts thereof which\nare inconsistent which the provisions of this Act are hereby repealed, amended or modified accordingly. casia\nAll other incentive systems which are not in any way affected by the provisions of this Act may be\nrestructured by the President so as to render them cost-efficient and to make them conform with the other\npolicy guidelines in the declaration of policy provided in Section 2 of this Act.\nSection 21. The provisions of the preceding section notwithstanding, existing enterprises which are\nenjoying the incentives under the laws repealed by this Act shall continue to enjoy such incentives for the\nperiod therein stated: Provided, however, That they may waive such incentives and opt to be governed by the\nprovisions of this Act, in which event, their period of availment of the incentives herein provided shall be\n\nreckoned from the original date of their entitlement to the incentives under the said laws.\nSection 22. This Act shall take effect immediately upon approval.\nApproved, April 28, 1983 (C.B. No. 54)"}}],"pack":"ph-p156"};
  FT["PH-H15257"] = {"id":"PH-H15257","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":18,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 392  An Act Converting the Lagangilang Agricultural College Into the Abra state Institute of Sciences and Technology, Expanding for this Purpose Its Curricular Programs in Agriculture, Sciences and Technology.","orig":"Batas Pambansa Blg. 392  An Act Converting the Lagangilang Agricultural College Into the Abra state Institute of Sciences and Technology, Expanding for this Purpose Its Curricular Programs in Agriculture, Sciences and Technology."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 392","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-05-18","completenessNote":"全文，共 18 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00392_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00392_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15257-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The present Lagangilang Agricultural College located in the Municipality of Lagangilang,\nProvince of Abra, is hereby converted into the Abra State Institute of Sciences and Technology, hereinafter\nreferred to in this Act as the College."}},{"id":"PH-H15257-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The College shall primarily provide technological, professional, technical and vocational\neducation and shall inspire leadership in the field of agriculture, forestry, home technology, agricultural\neducation and industry, through scientific research and extension."}},{"id":"PH-H15257-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"In addition to its present secondary agricultural course, undergraduate courses leading to the\ndegrees of Bachelor in Science in Agriculture and Bachelor of Science in Agricultural Education, two-year\ntechnician courses for agriculture and forest ranger, the College shall offer other courses leading to the\ndegrees of Bachelor of Science in Home Technology, Bachelor of Science in Forestry and Bachelor of\nScience in Agricultural Engineering; postgraduate courses leading to the degree of Master Science in\nAgricultural Education and such other courses as the Board of Trustees may deem wise and necessary."}},{"id":"PH-H15257-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"No student, provided he qualifies in the National College Entrance Examination test, shall be\ndenied admission to the College by reason of sex, ethnic considerations or religious belief. Those who do not\nqualify can be admitted in the two-year technical courses. All applicants for admission must have to pass the\nCollege entrance examination."}},{"id":"PH-H15257-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The head of the College shall be known as the President of the Abra State Institute of Sciences\nand Technology. He shall be appointed by the President of the Philippines.\nThe powers and duties of the President of the College, in addition to those specifically provided for in this\nAct, shall be those usually pertaining to the office of the president of a college."}},{"id":"PH-H15257-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The governing body of the College shall be the Board of Trustees of the Abra State Institute of\nSciences and Technology. It shall be composed of the Minister of Education, Culture and Sports who shall be\nthe chairman, the Director of Higher Education, the Director of Secondary Education, the President of the\nCollege and the Member of the Batasang Pambansa coming from Abra, as ex officio members and two\nprominent residents of Abra who are distinguished leaders in agriculture, forestry and other industrial fields.\nThe non-ex officio members of the Board of Trustees shall be appointed by the President of the Philippines.\nOf the first group appointed, the President shall designate one to serve for two years and the other to serve for\nfour years. Thereafter, persons appointed to succeed such members shall hold office for a term of four years\nand until their successors shall have been appointed and qualified. In case of permanent vacancy, the position\nshall be filled by appointment by the President of the Philippines. Such appointment shall hold office for the\nunexpired term only.\nWhen the Minister of Education, Culture and Sports is unable to perform his duties as Chairman of the Board\ndue to illness, absence or other causes, or in the case of vacancy in the office, the Deputy Minister of\nEducation, Culture and Sports shall temporarily perform the functions of the Chairman of the said Board.\nWhen both the Minister and the Deputy Minister of Education, Culture and Sports are unable to exercise the\npowers of the Chairman of the Board of Trustees, the Members of the Batasang Pambansa coming from Abra\n\nshall act as temporary chairman thereof."}},{"id":"PH-H15257-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"The members of the Board of Trustees shall serve without compensation other than a per diem of\none hundred pesos each per session of the Board and that expenses incurred either in attendance upon\nmeetings of the Board or upon other official business shall be reimbursed as authorized by resolution thereof,\nsubject to existing budget laws on honoraria and allowances."}},{"id":"PH-H15257-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"In addition to its general powers of administration, the Board of Trustees shall have the\nfollowing powers and duties:\n(a) To receive and appropriate for the purposes specified by law such sums as may be provided for the support\nof the College;\n(b) To confer degrees upon successful candidates for graduation of the College. It may also confer the usual\nhonorary degrees upon persons in recognition of learning, statesmanship or eminence in science, agriculture,\nforestry, industry or public service related to such fields;\n(c) Subject to Civil Service Law, rules and regulations, to appoint, upon recommendation of the President of\nthe College, the registrar, the deans of the different schools of the College, the heads of departments,\nprofessors, instructors, lecturers and other employees of the College and to fix their compensation, subject to\nPresidential Decree No. 985 and other pertinent budget and compensation laws; to prescribe hours of service,\nduties and the conditions of work as it may deem proper; to grant to them, in its discretion, leave of absence\nunder such regulations as it may promulgate, any provision of law to the contrary notwithstanding, and to\nremove them for cause after investigation and hearing pursuant to Civil Service Law governing disciplinary\n(d) To approve the curricula and rules of discipline drawn up by the College Council as hereinafter provided;\n(e) To provide fellowships and scholarships for deserving faculty members and students;\n(f) To prescribe rules for its own government and for this purpose, to enact such regulations not contrary to\nlaw, as may be necessary;\n(g) To receive in trust legacies, gifts and donations of the real and personal property of all kinds and to\nadminister the same for the benefit of the College or of a department thereof, or for aid to any student in\naccordance with the directions and instructions of the donors, and in default thereof, in such manner as the\nBoard of Trustees may in its discretion determine;\n(h) To provide vocational training and retraining of adult citizens and out-of-school-youths; and\n(i) To name after prominent Filipinos or heroes any building, annex, ground, or branch of the College."}},{"id":"PH-H15257-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all the members holding office\nat the time the meeting of the Board is called. All processes against the Board of Trustees shall be served on\nthe President or Secretary thereof."}},{"id":"PH-H15257-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"On or before the fifteenth day of June each year, the Board of Trustees shall submit to the\nPresident of the Philippines a detailed report, setting forth the program, condition, and needs of the College."}},{"id":"PH-H15257-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"There shall be a College Council composed of the President of the College as chairman and the\nfaculty of the College who teach collegiate courses as members. The council shall have the power to prescribe\nthe curricula and rules of discipline, subject to the approval of the Board of Trustees. It shall fix the\nrequirements for admission to the College, as well as for graduation and the conferring of degrees, subject to\nreview by the Board of Trustees. The council alone shall have the power to recommend students or others to\nbe recipients of degrees. Through the President of the College or a duly authorized committee, the council\nshall have the disciplinary power over the students within the limits prescribed by the rules of discipline."}},{"id":"PH-H15257-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"The body of instructors and professors of the College shall constitute the faculty of the College,\nwith the President of the College as the presiding officer.\n\nNo member of the faculty of the College shall attempt directly or indirectly, under penalty of dismissal by the\nBoard of Trustees, to influence students or employees of the College toward any ideology, political or\notherwise, which preaches the overthrow of the government through violence or subversion."}},{"id":"PH-H15257-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"There shall be a secretary of the College who shall be appointed by the Board of Trustees upon\nrecommendation of the President of the College. He shall be the secretary of the Board also of the College,\nand shall keep the records of the College as may be determined by the Board of Trustees."}},{"id":"PH-H15257-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"The Treasurer of the Philippines shall be ex officio treasurer of the College. All accounts and\nexpenses therefor shall be audited by the Commission on Audit and all disbursements shall be made in\naccordance with existing auditing rules and regulations."}},{"id":"PH-H15257-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"Heads of bureaus and offices of the national government are hereby authorized to loan or\ntransfer, upon request of the President of the College, such apparatus, equipment or supplies as may be needed\nby the College and to detail employees for duty therein when in the judgment of the head of the bureau or\noffice, such apparatus, equipment, supplies or the services of such employees can be spared without serious\ndetriment to the public service. Employees so detailed shall perform such duty as is required under such detail,\nand the time so employed shall be counted as part of their regular official service."}},{"id":"PH-H15257-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"The requirements provided in this Act as may prove adverse to the present faculty and\nemployees to the Lagangilang Agricultural College who may be absorbed by the Abra State Institute of\nSciences and Technology shall not apply to them, except for the position of the President of the College who\nshall be appointed by the President of the Philippines upon the recommendation of the Board of Trustees. The\nBoard shall nominate the best man in the Ilocos, particularly in Abra, who has the best qualifications, both in\neducation, training and experiences to be recommended as the President of the College. Future appointees to\nthe said College shall be subject to all the requirements provided in this Act."}},{"id":"PH-H15257-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"All parcels of land, buildings, equipment and facilities owned by the Lagangilang Agricultural\nCollege, as well as all obligations and appropriations thereof, shall be transferred to the Abra State Institute of\nSciences and Technology. The necessary sum for the operation and maintenance of the new state college shall\nbe provided for in subsequent General Appropriations Acts, until which the time the operation of the\ninstitution as an institute shall be deferred, provided that its new name shall take effect upon approval of this"}},{"id":"PH-H15257-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 18, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15258"] = {"id":"PH-H15258","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":21,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 393  An Act Converting the Romblon Agricultural College in the Municipality of Odiongan, Province of Romblon, Into a state College to Be Known as the Romblon state College, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 393  An Act Converting the Romblon Agricultural College in the Municipality of Odiongan, Province of Romblon, Into a state College to Be Known as the Romblon state College, and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Cao đẳng Nông nghiệp Romblon tại Thị trấn Odiongan, Tỉnh Romblon thành Cao đẳng Bang với tên gọi Cao đẳng Bang Romblon","th":"พระราชบัญญัติเปลี่ยนสถานะวิทยาลัยเกษตรกรรม Romblon ในเทศบาล Odiongan จังหวัด Romblon เป็น วิทยาลัยของรัฐในชื่อวิทยาลัยของรัฐ Romblon","id":"Undang-Undang mengubah Sekolah Tinggi Pertanian Romblon di Kotamadya Odiongan, Provinsi Romblon menjadi Sekolah Tinggi Negeri dengan nama Sekolah Tinggi Negeri Romblon","ms":"Akta menukar status Kolej Pertanian Romblon di Perbandaran Odiongan, Wilayah Romblon kepada Kolej Negeri dengan nama Kolej Negeri Romblon"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 393","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-05-18","completenessNote":"全文，共 21 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00393_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00393_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15258-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Romblon Agricultural College in the Municipality of Odiongan, Province of Romblon, is\nhereby converted into a state college to be known as the Romblon State College, hereinafter referred to as the\nCollege which shall offer courses leading to the titles of Associate in Business Education, Associate in\nCommerce, four-year courses leading to the degrees of Bachelor of Science in Agriculture, Bachelor of\nScience in Home Technology, Bachelor of Science in Agricultural Education, Bachelor of Science in\nEducation, Bachelor of Science in Business Education, Bachelor of Science in Industrial Arts, Bachelor of\nScience in Industrial Education, Bachelor of Science in Agricultural Engineering, Bachelor of Science in\nForestry, Bachelor of Science in Fisheries, and courses leading to the degrees of Master of Science in\nAgriculture, Master of Science in Agricultural Education and Master of Arts in Education."}},{"id":"PH-H15258-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The College shall primarily provide higher technological, professional and vocational instruction\nand training in science, agricultural and industrial fields, as well as short-term technical or vocational courses.\nIt shall promote research, advanced studies and progressive leadership in its areas of specialization."}},{"id":"PH-H15258-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"In addition to its present secondary and vocational curricular offerings, the College shall offer\nundergraduate and graduate courses in the fields of science, agriculture and industry as the Board of Trustees\nmay deem necessary."}},{"id":"PH-H15258-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"No student shall be denied admission to the College by reason of sex, ethnic considerations or\nreligious belief or affiliation."}},{"id":"PH-H15258-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The head of the College shall be known as the President of the Romblon State College. He shall\nbe appointed by the President of the Philippines upon recommendation of the Board of Trustees. His salary\nshall be fixed by the Board of Trustees comparable to that being received by the president of similar\neducational institutions of like enrolment and standing, subject to Presidential Decree No. 985 and other\npertinent budget and compensation laws.\nThe powers and duties of the President of the College, in addition to those specifically provided for in this\nAct, shall be those usually pertaining to the office of the president of a state college or university."}},{"id":"PH-H15258-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The governing body of the College shall be the Board of Trustees of the Romblon State College.\nIt shall be composed of the Minister of Education, Culture and Sports as chairman, the Regional Director of\nthe National Economic and Development Authority, the President of the Romblon State College, and four (4)\nprominent citizens of Region IV to be appointed by the President of the Philippines, as members.\nOf the four appointed members, one shall be a representative for science, one for agriculture, one for arts and\ntrades and one for technology: Provided, That at least one of the four appointed members shall be an alumnus\nof the former Romblon Agricultural College. Of the first group appointed, the President of the Philippines\nshall designate one to serve for one year, one to serve for two years, one to serve for three years, and one to\nserve for four years. Thereafter, persons appointed to succeed such members shall hold office for a term of\nfour years and until their successors who should be experts in the same field shall have been appointed and\nqualified. In case of permanent vacancy, the position shall be filled by appointment by the President of the\nPhilippines. Such appointee shall hold office for the unexpired term only.\n\nWhen the Minister of Education, Culture and Sports is unable to perform his duties as chairman of the board\ndue to illness, absence or other cause, or in case of a vacancy in the office, the Deputy Minister of Education,\nCulture and Sports shall temporarily perform the functions of the chairman of the said board. The chairman\nmay assign qualified officials to represent him with full authority in the board."}},{"id":"PH-H15258-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all the members holding office\nat the time a meeting is called. All processes against the Board of Trustees shall be served on the president or\nsecretary thereof."}},{"id":"PH-H15258-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"The members of the Board of Trustees shall be entitled to an allowance of one hundred pesos per\nmeeting actually attended but not more than three hundred pesos a month: Provided, That they shall be\nreimbursed for actual and necessary expenses incurred either in attendance upon meetings of the Board or\nupon other official business authorized by resolution of the Board, subject to existing budget laws on\nhonoraria and allowances."}},{"id":"PH-H15258-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"The Board of Trustees shall have the following powers and duties in addition to its general\npowers of administration, and the exercise of all the powers of a corporation as provided in Section 36 of\nBatas Pambansa Blg. 68, otherwise known as the Corporation Code of the Philippines:\n(a) To receive and appropriate for the purposes specified by law such sums as may be provided for the support\nof the Romblon State College;\n(b) To confer degrees upon successful candidates for graduation of the Romblon State College. It may also\nconfer honorary degrees upon persons in recognition of learning, statesmanship or eminence in any of the\nfields of specialization of the Romblon State College, or in recognition of public service: Provided, That such\ndegrees shall not be conferred in consideration of or to reciprocate some personal favor;\n(c) To authorize the President of the Romblon State College to award proficiency certificates or diplomas to\nstudents who have completed non-degree courses;\n(d) To appoint, on recommendation of the President of the Romblon State College, a vice-president, deans,\ndirectors, secretary of the Romblon State College, registrar, heads of departments, professors, instructors,\nlecturers and other officials and employees of the Romblon State College; to fix their compensation, subject to\nPresidential Decree No. 985 and other pertinent budget and compensation laws; hours of service, and such\nother duties and conditions as it may deem proper, to grant to them at its discretion, leave of absence under\nsuch regulations as it may promulgate, any provisions of existing law to the contrary notwithstanding, to\nremove them for cause after an investigation and hearing; to establish Chairs in the College, and to provide for\nthe maintenance or endowment of such Chairs as may be necessary;\n(e) To prove the curricular and the rules of discipline drawn by the College Council as hereinafter provided;\n(f) To provide fellowships for qualified faculty members and scholarships to deserving students;\n(g) To prescribe rules for its own government and to enact for the government of the College such rules and\nregulations, not contrary to law, as may be necessary to carry out the purposes and functions of the College;\n(h) To receive in trust legacies, gifts and donations of real and personal property of all kinds, to administer the\nsame for the benefit of the College, or the departments thereof, or for aid to any student or students, in\naccordance with the directions and instructions of the donor, and in default thereof, in such manner as the\nBoard of Trustees may in its discretion determine. All such donations shall be exempt from all taxes and to be\nconsidered as deductible items from income tax of the donors; and\n(i) To authorize the establishment of other branches of the College and to designate other schools of secondary\nlevels within the Province of Romblon: Provided, That the funds for the purpose shall come from its\nappropriation."}},{"id":"PH-H15258-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"On or before the fifteenth day of the second month after the opening of regular classes each\nyear, the Board of Trustees shall file with the Office of the President of the Philippines a detailed report,\n\nsetting forth the progress, conditions and needs of the College."}},{"id":"PH-H15258-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"There shall be a College Council consisting of the President of the College and all members of\nthe faculty teaching collegiate courses. The Council shall have the power to prescribe the curricula and rules\nof discipline, subject to the approval of the Board of Trustees. It shall fix the requirements for admission to the\nCollege, as well as for graduation and the conferring of degrees subject to review by the Board of Trustees.\nThe Council alone shall have the power to recommend students or others to be recipients of degrees. Through\nthe President of the College or its duly authorized committee, the Council shall have disciplinary power over\nthe students within the limits prescribed by the rules of discipline."}},{"id":"PH-H15258-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"The body of instructors and professors of the College shall constitute the faculty of the College."}},{"id":"PH-H15258-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"No member of the faculty of the College shall attempt directly or indirectly, under penalty of\ndismissal by the Board of Trustees, to influence students or any person in the College towards any ideology,\npolitical or otherwise, which preaches the overthrow of the government through violence or subversion."}},{"id":"PH-H15258-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"There shall be a secretary of the College who shall be appointed by the Board of Trustees upon\nrecommendation of the President of the College. He shall also be the secretary of the Board and shall keep\nsuch records of the College as may be determined by the Board of Trustees."}},{"id":"PH-H15258-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"The Treasurer of the Philippines shall be the ex officio treasurer of the College, and all\naccounts and expenses therefor shall be audited by the Commission on Audit or its duly authorized\nrepresentatives."}},{"id":"PH-H15258-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"Heads of bureaus and offices of the national government are hereby authorized to loan or\ntransfer, upon request of the President of the College, such apparatus, equipment, supplies or the services of\nsuch employees as can be spared without serious detriment to the public service. Employees so detailed shall\nperform such duty as required under such detail and the time so employed shall be counted as part of their\nregular official service."}},{"id":"PH-H15258-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"All assets of the Romblon Agricultural College, whether fixed or movable, records and\npersonnel, are hereby transferred to the Romblon State College."}},{"id":"PH-H15258-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"All existing appropriations for the Romblon State College, to be disbursed in accordance with\nthe provisions of this Act. The necessary sum for the operation and maintenance of the new state college shall\nbe provided for in subsequent General Appropriations Acts, until which time the operation of the institution as\na college shall be deferred, provided that its new name shall take effect upon approval of this Act."}},{"id":"PH-H15258-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"The Minister of Education, Culture and Sports is hereby directed to take such steps as are\nnecessary for the immediate implementation of this Act."}},{"id":"PH-H15258-A20","no":20,"noLabel":{"en":"Section 20"},"text":{"en":"All laws inconsistent with the provisions of this Act are hereby repealed or amended\naccordingly."}},{"id":"PH-H15258-A21","no":21,"noLabel":{"en":"Section 21"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 18, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15259"] = {"id":"PH-H15259","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":21,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 394  An Act Converting the Eastern Samar College of Agriculture in the Municipality of Borongan, Province of Eastern Samar, Into a state College to Be Known as the Eastern Samar state College and to Authorize the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 394  An Act Converting the Eastern Samar College of Agriculture in the Municipality of Borongan, Province of Eastern Samar, Into a state College to Be Known as the Eastern Samar state College and to Authorize the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 394","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-05-18","completenessNote":"全文，共 21 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00394_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00394_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15259-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Eastern Samar College of Agriculture in Borongan, Eastern Samar, is hereby converted into\na state college to be known as the Eastern Samar State College, hereinafter referred to in this Act as College."}},{"id":"PH-H15259-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The College shall primarily provide collegiate level technological, professional and vocational\ninstruction and training in science, agricultural and industrial fields, as well as short-term technical or\nvocational course. It shall promote research, advanced studies and progressive leadership in its areas of\nspecialization."}},{"id":"PH-H15259-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"In addition to its present secondary and agricultural curricular offerings, the College shall offer\nundergraduate and graduate courses in the fields of science, technology and industry as the Board of Trustees\nmay deem necessary."}},{"id":"PH-H15259-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"No student shall be denied admission to the College by reason of sex, ethnic consideration or\nreligious belief or affiliation."}},{"id":"PH-H15259-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The head of the College shall be known as the President of the Eastern Samar State College. He\nshall be appointed by the President of the Philippines upon recommendation of the Board of Trustees. His\nsalary shall be fixed by the Board of Trustees comparable to that being received by the president of similar\neducational institutions of like enrolment and standing, subject to Presidential Decree No. 985 and other\npertinent budget and compensation laws.\nThe powers and duties of the President of the College, in addition to those specifically provided for in this\nAct, shall be those usually pertaining to the office of the president of a state college."}},{"id":"PH-H15259-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The governing body of the College shall be the Board of Trustees of the Eastern Samar State\nCollege. It shall be composed of the Minister of Education, Culture and Sports as chairman, the Regional\nDirector of the National Economic and Development Authority, the President of the College, and four (4)\nprominent citizens of Region VIII to be appointed by the President of the Philippines, as members.\nOf the four appointed members, one shall be an authority in science, one in agriculture, one in arts and trades,\nand one in technology. Provided, That at least one of the four appointed members shall be an alumnus of the\nformer Eastern Samar College of Agriculture. Of the first group appointed, the President shall designate one\nto serve for one year, one to serve for two years, one to serve for three years, and one to serve for four years.\nThereafter, the persons appointed to succeed such members shall hold office for a term of four years and until\ntheir successors, who should be experts in the same field, shall have been appointed and qualified. In case of\npermanent vacancy, the position shall be filled by appointment by the President of the Philippines. Such\nappointee shall hold office for the unexpired term only.\nWhen the Minister of Education, Culture and Sports is unable to perform his duties as Chairman of the Board\ndue to illness, absence or other cause, or in case of a vacancy in the office, the Deputy Minister of Education,\nCulture and Sports shall temporarily perform the functions of the chairman of the said Board. The Chairman\nmay assign qualified officials to represent him with full authority in the Board."}},{"id":"PH-H15259-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all the members holding office\n\nat the time a meeting is called. All processes against the Board of Trustees shall be served on the President or\nSecretary thereof."}},{"id":"PH-H15259-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"The members of the Board of Trustees shall be entitled to an allowance of one hundred pesos a\nmonth: Provided, That they shall be reimbursed for actual and necessary expenses incurred either in\nattendance upon meetings of the Board or upon other official business authorized by resolution of the Board,\nsubject to existing budget laws on honoraria and allowances."}},{"id":"PH-H15259-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"The Board of Trustees shall have the following powers and duties in addition to its general\npowers of administration, and the exercise of all the powers of a corporation as provided in Section 36 of\nBatas Pambansa Blg. 68, otherwise known as the Corporation Code of the Philippines:\n(a) To receive and appropriate for the purposes specified by law such sums as may be provided for the support\nof the College;\n(b) To confer degrees upon successful candidates for graduation of the College. It may also confer honorary\ndegrees upon persons in recognition of learning, statesmanship or eminence in any of the fields of\nspecialization of the College, or in recognition of the public service: Provided, That such degrees shall not be\nconferred in consideration of or to reciprocate some personal favor;\n(c) To authorize the President of the College to award proficiency certificates or diplomas to students who\nhave completed non-degree courses;\n(d) To appoint, on recommendation of the President of the College, a vice-president, deans, directors,\nsecretary of the College, registrar, heads of departments, professors, instructors, lecturers and other officials,\nand employees of the College, to fix their compensation, subject to Presidential Decree No. 985 and other\npertinent budget and compensation laws, hours of service, and such other duties and conditions as it may\ndeem proper, to grant to them, in its discretion, leave of absence under such regulations as it may promulgate,\nany provisions of existing law to the contrary notwithstanding; to remove them for cause in the College, and\nprovide for the maintenance or endowment of such Chairs as may be necessary;\n(e) To approve the curricula and rules of discipline drawn by the College Council as hereinafter provided;\n(f) To provide fellowship for qualified faculty members and/or scholarships to deserving students;\n(g) To prescribe rules for its own government and to enact for the government of the College such rules and\nregulations, not contrary to law, as may be necessary to carry out the purposes and functions of the College;\n(h) To receive in trust legacies, gifts and donations of real and personal property of all kinds, to administer the\nsame for the benefit of the College, or the departments thereof, or for aid to any student or students, in\naccordance with the directions and instructions of the donor, and in default thereof, in such manner as the\nBoard of Trustees may in its discretion determine. All such donations shall be exempt from all taxes and to be\nconsidered as deductible items from the income tax of the donors."}},{"id":"PH-H15259-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"On or before the fifteenth day of the second month after the opening of regular classes each\nyear, the Board of Trustees shall file with the Office of the President of the Philippines a detailed report,\nsetting forth the progress, conditions and needs of the College."}},{"id":"PH-H15259-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"There shall be a College Council consisting of the President of the College and all members of\nthe faculty who teach collegiate courses. The Council shall have the power to prescribe the curricula and rules\nof discipline, subject to the approval of the Board of Trustees. It shall fix the requirements for admission to the\nCollege, as well as for graduation and the conferring of degrees subject to review by the Board of Trustees.\nThe Council alone shall have the power to recommend students or other to be recipients of degrees. Through\nthe President of the College or its duly authorized committee, the Council shall have disciplinary power over\nthe students within the limits prescribed by the rules of discipline."}},{"id":"PH-H15259-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"The body of instructors and professors of the College shall constitute the faculty of the College."}},{"id":"PH-H15259-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"No member of the faculty of the College shall attempt directly or indirectly, under penalty of\ndismissal by the Board of Trustees, to influence students or any person in the College towards any ideology,\npolitical or otherwise, which preaches the overthrow of the government through violence or subversion."}},{"id":"PH-H15259-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"There shall be a Secretary of the College who shall be appointed by the Board of Trustees upon\nrecommendation of the President of the College. He shall also be the Secretary of the Board and shall keep\nsuch records of the College as may be determined by the Board of Trustees."}},{"id":"PH-H15259-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"The Treasurer of the Philippines shall be ex officio treasurer of the College and all accounts\nand expenses therefor shall be audited by the Commission on Audit or its duly authorized representative."}},{"id":"PH-H15259-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"Heads of bureaus and offices of the national government are hereby authorized to loan or\ntransfer, upon request of the President of the College, such apparatus, equipment or supplies as may be needed\nby the College and to detail employees for duty therein, when in the judgment of the head of the bureau or\noffice such apparatus, equipment, supplies or the services of such employees can be spared without serious\ndetriment to the public service. Employees so detailed shall perform such duty as required under such detail\nand the time so employed shall be counted as part of their regular official service."}},{"id":"PH-H15259-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"All assets of the Eastern Samar College of Agriculture, whether fixed or movable, records and\npersonnel, are hereby transferred to the Eastern Samar State College."}},{"id":"PH-H15259-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"All existing appropriations for the Eastern Samar College of Agriculture are hereby transferred\nto the Eastern Samar State College, to be disbursed in accordance with this Act. The necessary sum for the\noperation and maintenance of the new college shall be provided for its subsequent General Appropriations\nActs, until which time the operation of the institution as a college is deferred, provided that its new name shall\ntake effect upon approval of this Act."}},{"id":"PH-H15259-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"The Minister of Education, Culture and Sports is hereby directed to take such steps as are\nnecessary for the immediate implementation of this Act."}},{"id":"PH-H15259-A20","no":20,"noLabel":{"en":"Section 20"},"text":{"en":"All laws inconsistent with the provisions of this Act are hereby repealed or amended\naccordingly."}},{"id":"PH-H15259-A21","no":21,"noLabel":{"en":"Section 21"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 18, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15260"] = {"id":"PH-H15260","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":19,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 395  An Act Converting the Iloilo School of Arts and Trades in Iloilo City, Into the Western VIsayas College of Science and Technology, and Expanding Its Curricular Programs.","orig":"Batas Pambansa Blg. 395  An Act Converting the Iloilo School of Arts and Trades in Iloilo City, Into the Western VIsayas College of Science and Technology, and Expanding Its Curricular Programs."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 395","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-05-18","completenessNote":"全文，共 19 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00395_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00395_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15260-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The present Iloilo School of Arts and Trades, located in the City of Iloilo, is hereby converted\ninto the Western Visayas College of Science and Technology, hereinafter referred to in this Act as the"}},{"id":"PH-H15260-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The College shall primarily provide a secondary and higher vocational, professional, scientific\nand technical education. It shall also promote research, advanced studies, and progressive leadership in the\nfields of trade, industrial, scientific and technological education."}},{"id":"PH-H15260-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"In addition to its present special trade curriculum, secondary trade curriculum, technical trade\ncourses and undergraduate courses leading to the degrees of Bachelor of Science in Practical Arts, Bachelor of\nScience in Industrial Education, Bachelor of Science in Industrial Technology and Master of Arts in Teaching\nVocational Education, the College shall offer undergraduate courses leading to the degrees of Bachelor of\nScience, Bachelor of Science in Community Development, Bachelor of Science in Home Technology,\npost-graduate courses leading to the degrees of Master of Science, Master of Science in Industrial Arts,\nMaster of Science in Industrial Education, Master of Science in Industrial Technology, Master of Science in\nHome Technology, and Master of Arts in Non-Formal Education, and such other degrees and post-graduate\ncourses and special courses as the Board of Trustees may be deem necessary. Other government tertiary\ninstitutions located in the City of Iloilo shall desist from offering new programs that are herein offered or to be\noffered by the College."}},{"id":"PH-H15260-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"No student shall be denied admission to the College by reason of sex, ethnic considerations, or\nreligious belief or affiliation."}},{"id":"PH-H15260-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The head of the Colleges shall be known as the President of the Western Visayas College of\nScience and Technology. He shall be appointed by the President of the Philippines.\nThe powers and duties of the President of the College in addition to those specifically provided for in this Act,\nshall be those usually pertaining to the office of the president of a college."}},{"id":"PH-H15260-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The Board of Trustees shall be the governing body of the College to be composed of the\nMinister of Education, Culture and Sports, chairman; Ministry of Education, Culture and Sports, Regional\nDirector, Region VI, vice-chairman; representative of the National Economic and Development Authority\n(NEDA), member; President of the College, member; president of the alumni association of the College,\nmember; and two members to be appointed by the President of the Philippines upon recommendation of the\nMinister of Education, Culture and Sports.\nThe first group of appointive trustees shall serve for two (2) years and four (4) years, respectively. Thereafter,\nthe appointees shall hold office for a term of four (4) years. In case of permanent vacancy, the appointee shall\nhold office for the unexpired term only.\nIn the absence of the Minister of Education, Culture and Sports, the Minister shall authorize a representative,\npreferably the Deputy Minister or at least a director, to sit in the meetings of the Board: Provided, however,\nThat during these meetings the Regional Director of the Ministry of Education, Culture and Sports, Region\nVI, shall preside as vice-chairman of the Board.\n\nWhen the Minister of Education, Culture and Sports is unable to perform his duties as chairman of the Board\ndue to illness, absence or other cause, or in case of vacancy in the Office, the Deputy Minister of Education,\nCulture and Sports shall temporarily perform the functions of the chairman of the said Board. When both the\nMinister and the Deputy Minister of Education, Culture and Sports are unable to exercise the powers of the\nchairman of the Board of Trustees, the members of the Board shall elect from among themselves a temporary\nchairman who shall act as chairman thereof."}},{"id":"PH-H15260-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"The members of the Board of Trustees shall be entitled to a per diem for every meeting attended\nsubject to pertinent budget laws, rules and regulations on compensation, honoraria, and allowances: Provided,\nThat they shall be reimbursed for actual and necessary expenses incurred either in attendance upon meetings\nof the Board or upon other official business authorized by the resolution of the Board subject to the\naforementioned laws, rules and regulations on compensation."}},{"id":"PH-H15260-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"In addition to its general powers of administration, the Board of Trustees shall have the\nfollowing powers and duties:\n(a) To receive and appropriate for the purpose specified by law such sums as may be provided for the support\nof the College;\n(b) To confer degrees upon successful candidates for graduation of the College. It may also confer honorary\ndegrees upon persons in recognition of learning, statesmanship, or eminence in science, industry, trade,\ntechnology or public service related to such fields;\n(c) To appoint, upon recommendation of the President of the College, the vice-president, the deans of the\ndifferent schools of the College, the secretary, the registrar, the heads of departments, supervisors, professors,\ninstructors, lecturers and administrative personnel, based on demonstrated ability, scholarship, research\nstudies made, and educational qualifications. To prescribe hours of service, duties and conditions of work as it\nmay deem proper; to grant to them, in its discretion, leave of absence under such regulations as it may\npromulgate, any provisions of law to the contrary notwithstanding, and to remove them for cause after an\ninvestigation and hearing pursuant to civil service law governing disciplinary action;\n(d) To approve the curricula and rules of discipline drawn up by the College Council as hereinafter provided;\n(e) To provide fellowships and scholarships for deserving faculty members and students;\n(f) To prescribe rules for its own government and for this purpose, to enact such regulations not contrary to\nlaw, as may be necessary;\n(g) To receive in trust legacies, gifts and donations of real and personal property of all kinds and to administer\nthe same for the benefit of the College or of a department thereof, or for aid to any student in accordance with\nthe directions and instructions of the donor, and in default thereof, in such manner as the Board of Trustees\nmay in its discretion determine;\n(h) To appropriate funds for research and development projects such as tools, machines, equipment, and new\nproducts and the publication of research studies made and books written by the faculty members of the\n(i) To provide non-formal education to adult citizens and out-of-school youth; and\n(j) To name after prominent Filipinos or heroes any hall, building, annex, ground, or branch of the College."}},{"id":"PH-H15260-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all members holding office at\nthe time the meeting of the Board is called. All processes against the Board of Trustees shall be served on the\nPresident or Secretary thereof."}},{"id":"PH-H15260-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"On or before the fifteenth day of November of each year, the Board of Trustees shall submit to\nthe President of the Philippines a detailed report, setting forth the processes, conditions, and needs of the"}},{"id":"PH-H15260-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"There shall be a College Council consisting of the President of the College and all members of\nthe faculty of the College teaching collegiate courses. The Council shall have the power to prescribe the\ncurricula and rules of discipline, subject to the approval of the Board of Trustees. It shall fix the requirements\nfor admission to the College, as well as for graduation and the conferring of degrees, subject to review by the\nBoard of Trustees. The Council alone shall have the power to recommend students or others to be recipients of\ndegrees. Through the President of the College, or a duly authorized committee, the Council shall have\ndisciplinary power over the students within the limits prescribed by the rules of discipline."}},{"id":"PH-H15260-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"The body of instructors and professors shall constitute the faculty of the College, with the\nPresident of the College as the presiding officer.\nNo member of the faculty of the College shall attempt directly or indirectly, under penalty of dismissal by the\nBoard of Trustees, to influence students or attendants at the College towards any ideology, political or\notherwise, which preaches the overthrow of the government through violence or subversion."}},{"id":"PH-H15260-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"There shall be a secretary of the College who shall be appointed by the Board of Trustees upon\nrecommendation of the President of the College. He shall be the secretary of the Board and also of the\nCollege, and shall keep such records of the College as may be determined by the Board of Trustees."}},{"id":"PH-H15260-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"The Treasurer of the Philippines shall be the ex officio treasurer of the College. All accounts\nand expenses therefor, shall be audited by the Commission on Audit and all disbursements shall be made in\naccordance with existing auditing rules and regulations."}},{"id":"PH-H15260-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"Heads of bureaus and offices of the national government are hereby authorized to loan or\ntransfer, upon request of the President of the College, such apparatus, equipment or supplies as may be needed\nby the College and to detail employees for duty therein, who in the judgment of the head of the bureau or\noffice, such apparatus, equipment, supplies or the services of such employees can be spared without serious\ndetriment to the public service. Employees so detailed shall perform such duty as is required under such detail,\nand the time so employed shall be counted as part of their regular official service."}},{"id":"PH-H15260-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"The requirements provided in this Act as may prove adverse to the present faculty and\nemployees of the Iloilo School of Arts and Trades who may be absorbed by the Western Visayas College of\nScience and Technology shall not apply to them. But future appointees to the said institution shall be\nsubjected to all requirements provided in this Act."}},{"id":"PH-H15260-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"All parcels of land, buildings, equipment and facilities owned by the Iloilo School of Arts and\nTrades, as well as all obligations and appropriations thereof, shall be transferred to the Western Visayas\nCollege of Science and Technology."}},{"id":"PH-H15260-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"The existing appropriations for the Iloilo School of Arts and Trades are hereby transferred to\nthe Western Visayas College of Science and Technology, to be disbursed in accordance with the provisions of\nthis Act. Thereafter, the necessary amount required for the operation and maintenance of the new state college\nshall be provided for in subsequent General Appropriations Act, until which time the operation of the\ninstitution as a college shall be deferred provided that its new name shall take effect upon approval of this Act."}},{"id":"PH-H15260-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 18, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15261"] = {"id":"PH-H15261","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 396  An Act Establishing An Extension Hospital in the Municipality of Talavera, Province of Nueva Ecija.","orig":"Batas Pambansa Blg. 396  An Act Establishing An Extension Hospital in the Municipality of Talavera, Province of Nueva Ecija.","vi":"Đạo luật thành lập Bệnh viện mở rộng tại Thị trấn Talavera, Tỉnh Nueva Ecija.","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลขยายในเทศบาล Talavera จังหวัด Nueva Ecija.","id":"Undang-Undang membentuk Rumah Sakit Perluasan di Kotamadya Talavera, Provinsi Nueva Ecija.","ms":"Akta menubuhkan Hospital Lanjutan di Perbandaran Talavera, Wilayah Nueva Ecija."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 396","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-05-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00396_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00396_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15261-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established a ten-bed capacity extension hospital in the Municipality of Talavera,\nProvince of Nueva Ecija, which shall be the extension of the Dr. P. J. Garcia Research and Medical Center, to\nbe known as the Talavera Extension Hospital."}},{"id":"PH-H15261-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Chief of Hospital of the Dr. P. J. Garcia Research and Medical Center shall assign or detail\nmedical personnel of the center to the Talavera Extension Hospital on rotation basis: Provided, however, That\nthe particular needs of both hospitals on certain occasions and situations shall be considered in making such\nassignments."}},{"id":"PH-H15261-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 131\nand Batas Pambansa Blg. 230 for the Ministry of Health intended for new or expanded hospitals. Thereafter,\nsuch sum as may be necessary for its operation and maintenance shall be included in the annual General\nAppropriations Act."}},{"id":"PH-H15261-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 18, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15262"] = {"id":"PH-H15262","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 397  An Act Converting the Luis Hervias High School in the City of Bacolod Into a National High School, to Be Known as the Luis Hervias National High School, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 397  An Act Converting the Luis Hervias High School in the City of Bacolod Into a National High School, to Be Known as the Luis Hervias National High School, and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Luis Hervias tại Thành phố Bacolod thành Trường Trung học Quốc gia với tên gọi Trường Trung học Luis Hervias Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Luis Hervias ในเมือง Bacolod เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Luis Hervias แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Luis Hervias di Kota Bacolod menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Luis Hervias Nasional","ms":"Akta menukar status Sekolah Menengah Luis Hervias di Bandar Bacolod kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Luis Hervias Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 397","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-05-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00397_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00397_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15262-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Luis Hervias High School in the City of Bacolod is converted into a national high school, to\nbe known as the Luis Hervias National High School."}},{"id":"PH-H15262-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education, Culture and Sports is directed to take such steps as are necessary for\nthe conversion and operation of the school and immediate implementation of this Act."}},{"id":"PH-H15262-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 131 and Batas Pambansa Blg. 230 for the Ministry of\nEducation, Culture and Sports intended for new national high schools: Provided, That the local government\nunit concerned shall continue to provide funding for its share in the cost of maintenance and operation of the\nschool. Thereafter, the amount needed for the operation of the school shall be included in the annual General\nAppropriations Act."}},{"id":"PH-H15262-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 18, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15263"] = {"id":"PH-H15263","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 398  An Act Amending Certain Sections Op Republic Act Numbered Forty-One Hundred and thirty-Six, Otherwise Known as the Land Transportation and Traffic","orig":"Batas Pambansa Blg. 398  An Act Amending Certain Sections Op Republic Act Numbered Forty-One Hundred and thirty-Six, Otherwise Known as the Land Transportation and Traffic"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 398","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-05-18","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00398_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00398_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15263-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Section nineteen of Republic Act Numbered Forty-one hundred and thirty six otherwise known\nas the Land Transportation and Traffic Code, is hereby amended to read as follows:\n\"Sec. 19. Duty to have license. Except as otherwise specifically provided in this Act, it shall be unlawful for\nany person to operate any motor vehicle without having in his possession a valid license to drive a motor\n\"The license shall be carried by the driver at all times when operating a motor vehicle, and shall be shown\nand/or surrendered for cause and upon demand to any person with authority under this Act to confiscate the"}}],"pack":"ph-p156"};
  FT["PH-H15264"] = {"id":"PH-H15264","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 399  An Act Abolishing the Additional Ten Percent Tax on the Taxable Net Income of Closely-Held Corporations, Repealing for the Purpose Paragraph (E) of Section Twenty-Four of the National Internal Revenue Code, as Amended.","orig":"Batas Pambansa Blg. 399  An Act Abolishing the Additional Ten Percent Tax on the Taxable Net Income of Closely-Held Corporations, Repealing for the Purpose Paragraph (E) of Section Twenty-Four of the National Internal Revenue Code, as Amended."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 399","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-05-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00399_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00399_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15264-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Paragraph (e) of Section twenty-four of the National Internal Revenue Code, as amended, is\nhereby repealed."}},{"id":"PH-H15264-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 18, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15265"] = {"id":"PH-H15265","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 400  An Act Amending Section Forty-Six of Batas Pambansa Bilang 232.","orig":"Batas Pambansa Blg. 400  An Act Amending Section Forty-Six of Batas Pambansa Bilang 232."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 400","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-03","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00400_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00400_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15265-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Section forty-six of Batas Pambansa Bilang 232 is amended to read as follows:\n\"Sec. 46. Relating to School Property. Real property, such as lands, buildings and other improvements thereon\nused actually, directly and exclusively for educational purposes, shall be subject to the real property tax based\non an assessment of fifteen percent of the market value of such property: Provided, That all the proceeds from\nthe payment thereof shall accrue to a special private education fund which shall be managed and disbursed by\na local private school board which shall be constituted in each municipality or chartered city with private\neducational institutions with the mayor or his representative as chairman and not more than two\nrepresentatives of the institutional taxpayers, and, likewise, not more than two residents of the municipality or\nchartered city who are alumni of any of the institutional taxpayers as members: Provided, finally, That in\nmunicipalities or chartered cities wherein the number of private institutions with individual enrollment of\npupils and students over five thousand exceeds fifteen, the members of the private school board shall be\nincreased to no more than fourteen members determined proportionately by the Minister of Education, Culture\nand Sports. The private school board shall adopt its own rules which shall enable it to finance the annual\nprograms and projects of each institutional taxpayers for the following purposes: student-pupil scholarships;\nimprovement of instructional, including laboratory facilities, and/or equipment; library books and periodicals\nacquisition; and extension service in the community, in that order of priority.\""}}],"pack":"ph-p156"};
  FT["PH-H15266"] = {"id":"PH-H15266","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":20,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 401  An Act Establishing the Central VIsayas Polytechnic College, Defining Its Powers, Functions and Duties, Appropriating Funds therefor, and for Other","orig":"Batas Pambansa Blg. 401  An Act Establishing the Central VIsayas Polytechnic College, Defining Its Powers, Functions and Duties, Appropriating Funds therefor, and for Other"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 401","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 20 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00401_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00401_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15266-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Establishment. There is hereby established in the Province of Negros Oriental, with a central site\nand administration office at Dumaguete City, a college which shall be known as the Central Visayas\nPolytechnic College, hereinafter referred to in this Act as College."}},{"id":"PH-H15266-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Conversion. The East Visayan School of Arts and Trades in Dumaguete City, the Guihulñgan\nVocational High School in Guihulñgan, and the Bais School of Fisheries at Okiot, Bais City, all national\nschools, are hereby merged into one college to be known as the Central Visayas Polytechnic College. The\nBoard of Trustees of the College is hereby authorized to effect its organization."}},{"id":"PH-H15266-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Purpose. The College shall primarily give professional and technical training in science and\ntechnology, and shall provide advanced and specialized instruction in literature, philosophy, arts and sciences,\nbesides providing for the promotion of scientific and technological researches."}},{"id":"PH-H15266-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Powers of the College. The following are the powers of the College:\n(a) It shall have the general powers as set forth in Section Thirty-six of Batas Pambansa Blg. 68. The exercise\nof its corporate powers is hereby vested exclusively in the Board of Trustees and in the President of the\nCollege insofar as authorized by the Board;\n(b) It shall have the power to acquire public lands for its expansion and/or beneficial use; and to purchase\nequipment, laboratory and library facilities which are required to carry out its educational objectives. It shall\noffer undergraduate courses in liberal arts, engineering, fisheries, agriculture, and short-term vocational\ncourses for development of middle level skills within the first five years from the approval of this Act; and\nmay, at the discretion of the Board, offer graduate courses thereafter;\n(c) It shall be authorized to undertake the construction of its buildings and other permanent improvements\nfrom such sums as may be necessary for the purpose, and included in the annual General Appropriations Act\nin the name of the East Visayan School of Arts and Trades, the Guihulñgan Vocational High School, and the\nBais School of Fisheries: Provided, That the construction of its buildings and other permanent improvements,\nas authorized in the Public Works Act of the Government, shall be undertaken by the College as herein\nprovided, any provision of existing laws to the contrary notwithstanding."}},{"id":"PH-H15266-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The Governing Board; Manner of Appointment.\n(a) Composition. The governing body of the College is vested in a Board of Trustees which shall be composed\nof nine members, five of whom are regular members and four are ex officio members. The regular members\nmust be Filipino citizens and residents of the Philippines, two of whom shall be well known educators in the\nRegion, two shall be successful businessmen or professionals of the Region who have shown and are showing\ninterest in the cause of education in the Region, and one shall be a successful alumnus of any of the schools to\nbe incorporated with and integrated into the College, upon recommendation of its alumni association, and who\nwill be replaced in due time, when available, by a successful alumnus of the College and upon\nrecommendation of its alumni association when this shall have been organized. The four ex officio members\nshall be the Minister of Education, Culture and Sports who shall be the ex officio Chairman of the Board, the\nRegional Director of the Ministry of Education, Culture and Sports, Region VII, the Director, Bureau of\nHigher Education, Ministry of Education, Culture and Sports, and the President of the College.\n\nThe regular members of the Board of Trustees, who shall serve a term of four years, shall be appointed by the\nPresident of the Philippines. Of the five regular members of the Board to be first appointed as above provided,\nthe President of the Philippines shall designate two to serve for two years, two to serve for three years, and\none to serve for four years.\nIn the absence or inability of the Minister of Education, Culture and Sports the other Members of the Board\nshall elect from among themselves a temporary chairman who shall act as Chairman. In case of a vacancy in\nthe regular membership of the Board, the President of the Philippines shall appoint a new member to serve for\nthe unexpired term only.\nNo person in the employ of the College or any other educational institution in the Region, except the President\nof the College shall be eligible for membership in the Board.\nThe regular members of the Board shall each receive, for every board meeting attended, a per diem of one\nhundred pesos: Provided, That in no case shall the total amount received by each exceed the sum of three\nhundred pesos for any one month. Besides the per diem, they and the ex officio members, shall be reimbursed\nfor actual and necessary expenses incurred in attendance upon meetings of the Board or upon performing\nother official business authorized by resolution of the Board, subject to existing budget laws on honoraria and\nallowances.\n(b) Quorum. A quorum of the Board shall consist of a majority of all the members holding office at the time\nthe meeting of the Board is called. All processes against the Board of Trustees shall be served on the chairman\nor secretary thereof.\n(c) Powers and duties of the Board. The Board of Trustees shall have the following powers and duties in\naddition to its general powers of administration and the exercise of the powers of the corporation:\n(1) To determine and fix the dates and time of their regular meetings, as well as special meetings as the need\nfor the same may arise: Provided, That such meetings shall not be more than three times in any one month,\nnor less than one time in any one quarter;\n(2) To recommend to the President of the Philippines candidates for the Presidency of the College who shall\nserve for a term of six years and who may be reappointed for another term not exceeding six years;\n(3) To fix the compensation of the President of the College;\n(4) To receive and appropriate to the ends specified by law such sums as may be provided by law for the\nsupport of the College;\n(5) To receive in trust legacies, gifts and donations of real and personal property of all kinds and to administer\nthe same for the benefit of the College or of a department thereof, or for aid to any student or students in\naccordance with the desire of the donor, and/or in default thereof, in such manner as the Board may in its\ndiscretion determine; all such donations shall be exempt from the income tax of the donors; to import\nduty-free commodities for educational purposes as an exception to existing laws;\n(6) To appoint, upon the recommendation of the President of the College, vice presidents, directors, deans,\nsecretary of the College, treasurer, professors, lecturers, instructors, registrar, department heads, division\nchiefs, and other employees of the College from among the qualified personnel of the merged schools at the\ntime this Act is approved. Only when there are no qualified personnel shall the Board recruit from the outside\nto fill vacancies;\n(7) To fix the compensation and term of service of all personnel and such other duties and conditions as it may\ndeem proper, subject to Presidential Decree No. 985 and other pertinent budget and compensation laws, rules\nand regulations;\n(8) To approve the courses of study and rules of discipline drawn up by the College and fix the required\ntuition fees, matriculation fees, fees for laboratory courses, diploma fees, and all special and other fees; and to\nutilize the income derived therefrom for the maintenance of the College, together with the annual\n\nappropriation provided for in Section seventeen hereof;\n(9) To provide fellowships to qualified faculty members and scholarships to deserving students;\n(10) To establish Chairs in the College and provide for the maintenance and endowment of such Chairs;\n(11) To confer honorary degrees upon persons other than graduates of the College in recognition of learning,\nstatesmanship or eminence in education, sciences, or arts: Provided, That such degrees shall not be conferred\nin consideration of the payment of money or other valuable consideration; and\n(12) To submit an annual report to the Minister of Education, Culture and Sports within two weeks after the\nclose of each school year, about the performance of the College in the school year just ended, its progress,\nneeds and problems."}},{"id":"PH-H15266-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The Administration. The administration of the College shall be vested in the President of the\nCollege who shall render full time service.\nThe College President shall be appointed by the President of the Philippines, upon the recommendation of the\nBoard. He shall be assisted by a Vice President for Academic Affairs who shall be appointed by the Board\nupon the recommendation of the College President. His compensation shall be fixed by the Board."}},{"id":"PH-H15266-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Powers of the President. The powers and duties of the President, in addition to those which are\nusually exercised by college presidents which are not inconsistent with the provisions of this law, are the\n(a) To recommend to the Board of Trustees for appointment, a vice president, deans, professors, instructors,\nlecturers, and other employees of the College;\n(b) To promulgate for the government of the College such general ordinances and regulations, not contrary to\nlaw, as are consistent with the purposes of the College; and\n(c) To suggest to the Chairman of the Board special meetings of the Board when the need arises."}},{"id":"PH-H15266-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"The Secretary of the College. The Board shall appoint a secretary who shall serve as such for\nboth the Board and the College, and shall keep all records and proceedings of the Board. He shall\ncommunicate to each Member of the Board notice of meetings."}},{"id":"PH-H15266-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"The College Council Powers. There shall be a College Council, under the chairmanship of the\nPresident of the College consisting of faculty members with the rank of dean, professor, associate professor,\nand assistant professor. Subject to existing laws and orders, the Council shall have the power to prescribe the\ncourses of study and rules of discipline; fix the requirements for admission to the College; serve as advisory\ncouncil to the President; and through a tribunal of not more than five members elected by the members of the\nCouncil, administers disciplinary measures among the student body and faculty of the College."}},{"id":"PH-H15266-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"College Centers. The President shall organize the following centers whose staff shall be\nselected among the members of existing faculty whose heads shall be known as Director of the Center;\n(a) Research and Planning Center. The Research and Planning Center is charged with the responsibility of\ncoordinating all researches of the College and planning for its expansion and development in line with the\nphilosophy of the College and the national goals of the Republic of the Philippines.\n(b) Guidance and Counseling Center. It shall be the duty of the Center to provide counseling and guidance\nprograms for the faculty, student and employees of the College.\n(c) Student Service Center. It shall be the duty of the Center to look after the interest of the student body,\nprovide them with facilities for development and organize them into social action groups to help in\ncountryside development."}},{"id":"PH-H15266-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"The Officers of the Administration. The Officers of the Administration of the College are the\nPresident, the Vice-President for Academic Affairs, the Deans of the different colleges, the Secretary of the\n\nCollege, Center Directors, and College Treasurer."}},{"id":"PH-H15266-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"The Faculty and Other Personnel of the College. The body of professors and instructors of each\ncollege shall constitute its faculty. They shall be appointed by the Board of Trustees upon the recommendation\nof the President of the College. In the recruitment of the professors, instructors, and other personnel of the\nCollege, no religious tests shall be required nor shall their religious opinion or affiliation be made a matter of\nexamination or inquiry: Provided, however, That no professor or instructor or any of its personnel shall\ninculcate sectarian tenets in any of their teachings."}},{"id":"PH-H15266-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"Civil Service Requirements. Except the President and the Vice President for Academic Affairs,\nall employees of the College shall be subject to the rules of the civil service. Highly technical positions may\nbe exempt from civil service eligibility upon approval of the Board as recommended by the President:\nProvided, however, That all shall be entitled to the privileges and rights of security of tenure, promotion in\npositions and salaries for meritorious service, leaves and retirement benefits, as in the government service as\nnow provided for by law."}},{"id":"PH-H15266-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"The Auditor of the College. The Commissioner on Audit of the Philippines shall be ex officio\nauditor of the College and shall designate his representative who must hold regular office therein to be able to\nperform his duties efficiently and satisfactorily as a regular official thereof. The designated representative\nshall be at least a Certified Public Accountant with the rank of Chief of a Division in the Commission on\nAudit whose salary shall vary and benefits shall be paid by the College."}},{"id":"PH-H15266-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"Loans or Transfers of Apparatus or Supplies; Detail of Employees for Duty in the College.\nHeads of bureaus and offices of the National Government are hereby authorized to loan or transfer, upon\nrequest of the President of the College, such apparatus or supplies as may be needed by the College and to\ndetail employees for duty therein when, in the judgment of the Bureau or Office, such supplies or employees\ncan be spared without serious detriment to the public service. Employees so detailed shall perform such duties\nas are required under such detail, and the time so employed shall count as part of their regular service."}},{"id":"PH-H15266-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"The Board of Visitors. The President of the Philippines, the Members of the Cabinet, and the\nSpeaker of the Batasang Pambansa or his designated representative shall constitute a Board of Visitors of the\nCollege, whose duty shall be to attend commencement exercises, to make visits at such other time as it may\ndeem proper, to examine the property, course of study, discipline, the state of finances of the College, to\ninspect all books and accounts of the institution, and to make reports to the President of the Philippines upon\nthe same, with such recommendations as it may favor."}},{"id":"PH-H15266-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"All existing appropriations for the East Visayan School of Arts and Trades in Dumaguete City,\nthe Guihulñgan Vocational High School in Guihulñgan, and the Bais School of Fisheries at Okiot, Bais City,\nare hereby transferred to the Central Visayas Polytechnic College, to be disbursed in accordance with the\nprovisions of this Act."}},{"id":"PH-H15266-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"Abolition and Transfer. The East Visayan School of Arts and Trades, the Guihulñgan\nVocational High School and the Bais School of Fisheries are hereby abolished and all their personnel\nunexpended appropriations, and all their assets, fixed and movable, are transferred to the Central Visayas\nPolytechnic College."}},{"id":"PH-H15266-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"General provisions. (a) The Minister of Education, culture and Sports is hereby directed to take\nsuch steps are necessary for the immediate implementation of this Act. (b) All laws inconsistent with the\nprovisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H15266-A20","no":20,"noLabel":{"en":"Section 20"},"text":{"en":"Effectivity. This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15267"] = {"id":"PH-H15267","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":21,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 402  An Act Converting the Claveria National Rural High School in the Municipality of Claveria, Province of Misamis Oriental, Into a state College to Be Known as the Misamis Oriental state College of Agriculture and Technology, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 402  An Act Converting the Claveria National Rural High School in the Municipality of Claveria, Province of Misamis Oriental, Into a state College to Be Known as the Misamis Oriental state College of Agriculture and Technology, and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Nông thôn Claveria Quốc gia tại Thị trấn Claveria, Tỉnh Misamis Oriental thành Cao đẳng Bang với tên gọi Cao đẳng Bang Nông nghiệp Công nghệ Misamis Oriental","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษาชนบท Claveria แห่งชาติในเทศบาล Claveria จังหวัด Misamis Oriental เป็น วิทยาลัยของรัฐในชื่อวิทยาลัยของรัฐเกษตรศาสตร์เทคโนโลยี Misamis Oriental","id":"Undang-Undang mengubah Sekolah Menengah Pedesaan Claveria Nasional di Kotamadya Claveria, Provinsi Misamis Oriental menjadi Sekolah Tinggi Negeri dengan nama Sekolah Tinggi Negeri Pertanian Teknologi Misamis Oriental","ms":"Akta menukar status Sekolah Menengah Luar Bandar Claveria Kebangsaan di Perbandaran Claveria, Wilayah Misamis Oriental kepada Kolej Negeri dengan nama Kolej Negeri Pertanian Teknologi Misamis Oriental"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 402","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 21 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00402_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00402_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15267-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Conversion of the Claveria National Rural High School into a State College. The present\nClaveria National Rural High School, located in the Municipality of Claveria, Province of Misamis Oriental,\nis hereby converted into a state college to be known as the Misamis Oriental State College of Agriculture and\nTechnology, hereinafter cited as the State College."}},{"id":"PH-H15267-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Purposes and Objectives. The State College shall primarily provide higher technological,\nprofessional, and vocational instruction and training in the fields of agriculture, industry as well as in the arts\nand sciences, consistent with the goals for national development. It shall also promote research, advanced\nstudies and progressive leadership in the various disciplines and areas of specialization."}},{"id":"PH-H15267-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Curriculum. In addition to its present secondary curriculum, the State College shall offer\nundergraduate and graduate courses in the fields of arts, sciences, education, agriculture, forestry, engineering,\nindustry, and such other courses as may be necessary to meet national and regional needs for trained"}},{"id":"PH-H15267-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Prohibition. No student shall be denied admission to the State College by reason of sex, ethnic\nconsideration, religious belief or affiliation."}},{"id":"PH-H15267-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The Vocational College Superintendent of the State College. The State College shall be headed\nby a Vocational School Superintendent who shall be appointed by the President of the Philippines upon the\nrecommendation of the Board of Trustees created under the next succeeding section hereof.\nThe powers and duties of the Vocational College Superintendent of the State College, in addition to those\nspecifically provided for in this Act, shall be those usually presiding to the office of a president of a state\ncollege. His salary shall be fixed by the Board of Trustees in an amount comparable to that being received by\npresidents of similar state colleges or educational institutions of like enrollment and standing."}},{"id":"PH-H15267-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The Board of Trustees. The State College shall be governed by a Board of Trustees to be\ncomposed of the Minister of Education, Culture and Sports as chairman and with the Regional Director of the\nNational Economic and Development Authority, the Vocational College Superintendent of the State College,\nand four (4) prominent citizens of Region X to be appointed by the President of the Philippines as members.\nOf the four appointed members, one shall be an authority in science, one in agriculture, one in arts and trades,\nand one in Psychology. Of the first group appointed, the President of the Philippines shall designate one to\nserve for one year, one to serve for two years, one to serve for three years, and one to serve for four years.\nThereafter, persons appointed to succeed such members shall hold office for a term of four years and until\ntheir successors, who should be experts in the same fields, shall have been appointed and qualified. In case of\npermanent vacancy, the position shall be filled by appointment by the President of the Philippines. Such\nappointee shall hold office for the unexpired term only.\nIn the event that the Minister of Education, Culture and Sports is unable to perform his duties as chairman of\nthe board due to illness, absence or other cause, or in case of a vacancy in the office, the Deputy Minister of\n\nEducation, Culture and Sports shall temporarily perform the functions of the chairman of the said board. The\nchairman may assign qualified officials to represent him with full authority in the board."}},{"id":"PH-H15267-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Quorum. A quorum of the Board of Trustees shall consist of a majority of all the members\nholding office at the time a meeting is called. All processes against the Board of Trustees shall be served on\nthe Vocational College Superintendent or Secretary thereof."}},{"id":"PH-H15267-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Allowances. The members of the Board of Trustees shall be entitled to an allowance of one\nhundred pesos per meeting actually attended but not more than three hundred pesos a month: Provided, That\nthey shall be reimbursed for actual and necessary expenses incurred either in attendance upon meetings of the\nboard or upon other official business authorized by resolution of the board subject to existing budget laws on\nhonoraria and allowances."}},{"id":"PH-H15267-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"Powers and duties of the Board of Trustees. The Board of Trustees shall have the following\npowers and duties, in addition to its general powers of administration and its powers exercised by boards of\ntrustees in corporations as provided in Section 36 of Batas Pambansa Blg. 68, otherwise known as the\nCorporation Code of the Philippines:\n(a) To receive and appropriate for the purposes specified by law such sums as may be provided for the support\nof the State College;\n(b) To confer degrees upon successful candidates for graduation of the State College. It may also confer\nhonorary degrees upon persons in recognition of learning, statesmanship, or eminence in any of the fields of\nspecialization of the State College, or in recognition of public service: Provided, That such degrees shall not\nbe conferred in consideration of or to reciprocate some personal favor;\n(c) To authorize the Vocational College Superintendent of the State College to award proficiency certificates\nor diplomas to students who have completed non-degree courses;\n(d) To appoint, on recommendation of the Vocational College Superintendent of the State College, vice\npresident, deans, directors, secretary of the State College, registrar, heads of departments, professors,\ninstructors, lecturers and other officials, and employees of the State College; to fix their compensation subject\nto P.D. No. 985 and other pertinent budget and compensation laws, hours of service, and such other duties and\nconditions as it may proper; to grant to them, in its discretion, leaves of absence under such regulations as it\nmay promulgate, any provision of existing law to the contrary notwithstanding; to remove them for cause after\nan investigation and hearing; to establish Chairs in the State College, and provide for the maintenance or\nendowment of such Chairs as may be necessary;\n(e) To approve the curricula and rules of discipline drawn by the College Council as hereinafter provided;\n(f) To provide fellowships for qualified faculty members and scholarships to deserving students;\n(g) To prescribe rules for its own government and enact for the government of the State College such rules\nand regulations, not contrary to law, as may be necessary to carry out the purposes and functions of the State\n(h) To receive in trust legacies, gifts, and donations of real and personal property of all kinds, to administer\nthe same for the benefit of the State College, or the departments thereof, or for aid to any student or students,\nin accordance with the directions and instructions of the donor, and in default thereof, in such manner as the\nBoard of Trustees may in its discretion determine. All such donations shall be exempt from all taxes and be\nconsidered as deductible items from the income tax of the donors;(i) To authorize the State College to\nundertake construction and/or repair of its buildings, machinery and equipment and other facilities, any\nprovision of law or executive order to the contrary notwithstanding: Provided, That the funds for the purpose\nshall come from its appropriation."}},{"id":"PH-H15267-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"Progress Report. On or before the fifteenth day of the second month after the opening of regular\nclasses each year, the Board of Trustees shall file with the Office of the President of the Philippines a detailed\n\nreport, setting forth the progress, conditions, and needs of the State College."}},{"id":"PH-H15267-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"The College Councils. There shall be a College Council consisting of the Vocational College\nSuperintendent of the State College and all members of the faculty with the rank of professor. The Council\nshall have the power to recommend students or others to be recipients of degrees. Through the Vocational\nCollege Superintendent of the State College or its duly authorized committee, the Council shall have\ndisciplinary power over the students within the limits prescribed by the rules of discipline."}},{"id":"PH-H15267-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"The Faculty. The body of instructors and professors of the State College shall constitute the\nfaculty of the State College.\nThe faculty shall be covered by appropriate civil service rules and regulations."}},{"id":"PH-H15267-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"Prohibitions. No member of the faculty of the State College shall attempt directly or indirectly,\nunder penalty of dismissal by the Board of Trustees, to influence students or any person in the State College\ntowards any ideology, political or otherwise, which preaches the overthrow of the government through\nviolence or subversion."}},{"id":"PH-H15267-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"The Secretary of the State College. There shall be a Secretary of the State College who shall be\nappointed by the Board of Trustees upon recommendation of the Vocational College Superintendent of the\nState College. He shall also be the secretary of the board and shall keep such records of the State College as\nmay be determined by the Board of Trustees."}},{"id":"PH-H15267-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"The Treasurer of the State College. The Treasurer of the Philippines shall be ex officio\ntreasurer of the State College and all accounts and expenses therefor shall be audited by the Commission on\nAudit or its duly authorized representative."}},{"id":"PH-H15267-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"Loans and transfers of equipment, supplies and personnel. Heads of bureaus and offices of the\nnational government are hereby authorized to loan or transfer, upon request of the Vocational College\nSuperintendent of the State College, such apparatus, equipment or supplies as may be needed by the State\nCollege and to detail employees for duty therein, when in the judgment of the head of the bureau or office\nsuch apparatus, equipment, supplies or the services of such employees can be spared without serious detriment\nto the public service. Employees so detailed shall perform such duty as required under such detail and the time\nso employed shall be counted as part of their regular official service."}},{"id":"PH-H15267-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"Transfer of Assets and Records. All assets of the Claveria National Rural High School, whether\nfixed or movable, records and personnel, are hereby transferred by the Misamis Oriental State College of\nAgriculture and Technology."}},{"id":"PH-H15267-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"All existing appropriations for the Claveria National Rural High School shall be transferred to\nthe Misamis Oriental State College of Agriculture and Technology, to be disbursed in accordance with the\nprovisions of this Act. The necessary sum for the operation and maintenance of the new state college shall be\nprovided for in subsequent General Appropriations Acts, until which time the operation of the institution as a\nstate college shall be deferred, provided that its new name shall take effect upon the approval of this Act."}},{"id":"PH-H15267-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"The Minister of Education, Culture and Sports shall promulgate rules and regulations and take\nsuch steps as are necessary for the immediate implementation of this Act."}},{"id":"PH-H15267-A20","no":20,"noLabel":{"en":"Section 20"},"text":{"en":"Repealing Clause. All laws inconsistent with the provisions of this Act are hereby repealed or\namended accordingly."}},{"id":"PH-H15267-A21","no":21,"noLabel":{"en":"Section 21"},"text":{"en":"Effectivity. This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15268"] = {"id":"PH-H15268","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 403  An Act Establishing An Agro-Industrial High School in the Municipality of Las Navas, Province of Northern Samar, to Be Known as the Las Navas Agro-Industrial High School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 403  An Act Establishing An Agro-Industrial High School in the Municipality of Las Navas, Province of Northern Samar, to Be Known as the Las Navas Agro-Industrial High School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật thành lập Trường Trung học Nông-công nghiệp tại Thị trấn Las Navas, Tỉnh Northern Samar với tên gọi Trường Trung học Nông-công nghiệp Las Navas","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาเกษตรอุตสาหกรรมในเทศบาล Las Navas จังหวัด Northern Samar ในชื่อโรงเรียนมัธยมศึกษาเกษตรอุตสาหกรรม Las Navas","id":"Undang-Undang membentuk Sekolah Menengah Agro-Industri di Kotamadya Las Navas, Provinsi Northern Samar dengan nama Sekolah Menengah Agro-Industri Las Navas","ms":"Akta menubuhkan Sekolah Menengah Agro-Industri di Perbandaran Las Navas, Wilayah Northern Samar dengan nama Sekolah Menengah Agro-Industri Las Navas"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 403","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00403_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00403_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15268-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There is hereby established under the superintendent of the Ministry of Education, Culture and\nSports an agro-industrial high school in the Municipality of Las Navas, Province of Northern Samar, to be\nknown as the Las Navas Agro-Industrial High School."}},{"id":"PH-H15268-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred and fifty thousand pesos for the operation of the school shall be\nfunded out of the appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education,\nCulture and Sports intended for new national high schools. Thereafter, the amount needed for its maintenance\nand operation shall be included in the annual General Appropriations Act."}},{"id":"PH-H15268-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15269"] = {"id":"PH-H15269","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 404  An Act Converting the Sugbongcogon Municipal High School in the Municipality of Sugbongcogon, Province of Misamis Oriental, Into a National School to Be Known as the Sugbongcogon National High School and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 404  An Act Converting the Sugbongcogon Municipal High School in the Municipality of Sugbongcogon, Province of Misamis Oriental, Into a National School to Be Known as the Sugbongcogon National High School and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Sugbongcogon Đô thị tại Thị trấn Sugbongcogon, Tỉnh Misamis Oriental thành Trường Quốc gia với tên gọi Trường Trung học Sugbongcogon Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Sugbongcogon เทศบาลในเทศบาล Sugbongcogon จังหวัด Misamis Oriental เป็น โรงเรียนแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Sugbongcogon แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Sugbongcogon Kotamadya di Kotamadya Sugbongcogon, Provinsi Misamis Oriental menjadi Sekolah Nasional dengan nama Sekolah Menengah Sugbongcogon Nasional","ms":"Akta menukar status Sekolah Menengah Sugbongcogon Perbandaran di Perbandaran Sugbongcogon, Wilayah Misamis Oriental kepada Sekolah Kebangsaan dengan nama Sekolah Menengah Sugbongcogon Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 404","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00404_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00404_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15269-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Sugbongcogon Municipal High School in the Municipality of Sugbongcogon, Province of\nMisamis Oriental, is hereby converted into a national school to be known as the Sugbongcogon National High\nSchool. Said school shall offer general secondary curriculum, vocational curriculum and other courses."}},{"id":"PH-H15269-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Minister of Education, Culture and Sports is hereby empowered to reorganize said school\naccordingly."}},{"id":"PH-H15269-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15269-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15270"] = {"id":"PH-H15270","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 405  An Act Converting the Hagonoy Municipal High School in the Municipality of Hagonoy, Province of Davao Del Sue, Into a National High School to Be Known as the Hagonoy National High School and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 405  An Act Converting the Hagonoy Municipal High School in the Municipality of Hagonoy, Province of Davao Del Sue, Into a National High School to Be Known as the Hagonoy National High School and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Hagonoy Đô thị tại Thị trấn Hagonoy, Tỉnh Davao Del Sue thành Trường Trung học Quốc gia với tên gọi Trường Trung học Hagonoy Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Hagonoy เทศบาลในเทศบาล Hagonoy จังหวัด Davao Del Sue เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Hagonoy แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Hagonoy Kotamadya di Kotamadya Hagonoy, Provinsi Davao Del Sue menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Hagonoy Nasional","ms":"Akta menukar status Sekolah Menengah Hagonoy Perbandaran di Perbandaran Hagonoy, Wilayah Davao Del Sue kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Hagonoy Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 405","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00405_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00405_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15270-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Hagonoy Municipal High School in the Municipality of Hagonoy, Province of Davao del\nSur, is hereby converted into a national high school, to be known as the Hagonoy National High School."}},{"id":"PH-H15270-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Hagonoy National High School shall offer a school curriculum which shall include\nacademic, industrial arts, ceramics, electricity, handicrafts and other allied courses. The Minister of Education,\nCulture and Sports is hereby empowered to reorganize the Hagonoy Municipal High School accordingly."}},{"id":"PH-H15270-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Upon the reorganization of the new school, the assets, liabilities, personnel, equipment and\nrecords of the Hagonoy Municipal High School shall be transferred to the Hagonoy National High School."}},{"id":"PH-H15270-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for the operation and\nmaintenance of the Hagonoy National High School shall be included in the annual General Appropriations"}},{"id":"PH-H15270-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15271"] = {"id":"PH-H15271","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 406  An Act Converting the Salogon Barangay High School Located in the Municipality of San Jose, Province of Camarines Sur, Into a Fisheries School to Be Known as San Jose Fisheries School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 406  An Act Converting the Salogon Barangay High School Located in the Municipality of San Jose, Province of Camarines Sur, Into a Fisheries School to Be Known as San Jose Fisheries School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Salogon Barangay tại Thị trấn San Jose, Tỉnh Camarines Sur thành Trường Thủy sản với tên gọi Trường Thủy sản San Jose","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Salogon Barangay ในเทศบาล San Jose จังหวัด Camarines Sur เป็น โรงเรียนประมงในชื่อโรงเรียนประมง San Jose","id":"Undang-Undang mengubah Sekolah Menengah Salogon Barangay di Kotamadya San Jose, Provinsi Camarines Sur menjadi Sekolah Perikanan dengan nama Sekolah Perikanan San Jose","ms":"Akta menukar status Sekolah Menengah Salogon Barangay di Perbandaran San Jose, Wilayah Camarines Sur kepada Sekolah Perikanan dengan nama Sekolah Perikanan San Jose"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 406","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00406_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00406_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15271-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Salogon Barangay High School located in the Municipality of San Jose, Province of\nCamarines Sur, is hereby converted into a fisheries school to be known as San Jose Fisheries School and\nhereinafter referred to in this Act as the School."}},{"id":"PH-H15271-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Minister of Education, Culture and Sports is hereby empowered to reorganize the school and\nto authorize said school to offer, in addition to the general academic curriculum, aquaculture and other\ntechnical or technological courses related to fisheries and marine resources."}},{"id":"PH-H15271-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"All assets of the Salogon Barangay High School whether immovable or movable, records and\npersonnel are hereby transferred to the San Jose Fisheries School."}},{"id":"PH-H15271-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for the operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15271-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15272"] = {"id":"PH-H15272","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 407  An Act Converting the Bikal Barangay High School Located At the Municipality of Caramoan, Province of Camarines Sur, Into a Fisheries School to Be Known as Bikal Fisheries School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 407  An Act Converting the Bikal Barangay High School Located At the Municipality of Caramoan, Province of Camarines Sur, Into a Fisheries School to Be Known as Bikal Fisheries School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Bikal Barangay tại Tỉnh Camarines Sur thành Trường Thủy sản với tên gọi Trường Thủy sản Bikal","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Bikal Barangay ในจังหวัด Camarines Sur เป็น โรงเรียนประมงในชื่อโรงเรียนประมง Bikal","id":"Undang-Undang mengubah Sekolah Menengah Bikal Barangay di Provinsi Camarines Sur menjadi Sekolah Perikanan dengan nama Sekolah Perikanan Bikal","ms":"Akta menukar status Sekolah Menengah Bikal Barangay di Wilayah Camarines Sur kepada Sekolah Perikanan dengan nama Sekolah Perikanan Bikal"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 407","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00407_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00407_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15272-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Bikal Barangay High School located at the Municipality of Caramoan, Province of\nCamarines Sur, is hereby converted into a fisheries school to be known as Bikal Fisheries School and\nhereinafter referred to in this Act as the School."}},{"id":"PH-H15272-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Minister of Education, Culture and Sports is hereby empowered to reorganize the School\nand to authorize said School to offer, in addition to the general academic curriculum, aquaculture and other\ntechnical or technological courses related to fisheries and marine resources."}},{"id":"PH-H15272-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"All assets of the Bikal Barangay High School whether immovable or movable, records and\npersonnel are hereby transferred to the Bikal Fisheries School."}},{"id":"PH-H15272-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15272-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15273"] = {"id":"PH-H15273","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 408  An Act Converting the Children'S Educational Foundation VIllage in Magpet, North Cotabato, Into a College to Be Known as the Cotabato Foundation College of Science and Technology, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 408  An Act Converting the Children'S Educational Foundation VIllage in Magpet, North Cotabato, Into a College to Be Known as the Cotabato Foundation College of Science and Technology, and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 408","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00408_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00408_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15273-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Children’s Educational Foundation Village in the sitios of Doroluman and Medlambid of\nArakan Valley in Magpet, North Cotabato, is hereby converted into a college, to be known as the Cotabato\nFoundation College of Science and Technology."}},{"id":"PH-H15273-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Cotabato Foundation College of Science and Technology shall primarily provide higher\ntechnological, professional, vocational training and industrial apprenticeship in the fields of science,\nagriculture and industry. It shall further promote research, advanced studies and progressive leadership in each\narea of specialization."}},{"id":"PH-H15273-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Cotabato Foundation College of Science and Technology is for the custodial care and\nvocational education of children of adversity at Doroluman and Medlambid, sitios of Arakan Valley, in the\nMunicipality of Magpet, Province of North Cotabato.\n\"Children\" as used in this Act shall mean and include orphans, homeless, neglected children, indigent children\nfrom broken homes and children from poverty-stricken families due to sickness, calamities and other\nmisfortunes."}}],"pack":"ph-p156"};
  FT["PH-H15274"] = {"id":"PH-H15274","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 409  An Act Providing for the Establishment of a Ten-Bed Municipal Hospital in the Municipality of Sergio Osmea, Sr., Province of Zamboanga Del Norte, to Be Known as the Sergio Osmea, Sr. Municipal Hospital.","orig":"Batas Pambansa Blg. 409  An Act Providing for the Establishment of a Ten-Bed Municipal Hospital in the Municipality of Sergio Osmea, Sr., Province of Zamboanga Del Norte, to Be Known as the Sergio Osmea, Sr. Municipal Hospital."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 409","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00409_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00409_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15274-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed municipal hospital in the Municipality of Sergio Osmeña, Sr., Province of Zamboanga del\nNorte, to be known as the Sergio Osmeña, Sr. Municipal Hospital."}},{"id":"PH-H15274-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15274-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15275"] = {"id":"PH-H15275","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 410  An Act Converting the Hinigaran High School in the Municipality of Hinigaran, Province of Negros Occidental, Into a National High School to Be Known as the Hinigaran National High School.","orig":"Batas Pambansa Blg. 410  An Act Converting the Hinigaran High School in the Municipality of Hinigaran, Province of Negros Occidental, Into a National High School to Be Known as the Hinigaran National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Hinigaran tại Thị trấn Hinigaran, Tỉnh Negros Occidental thành Trường Trung học Quốc gia với tên gọi Trường Trung học Hinigaran Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Hinigaran ในเทศบาล Hinigaran จังหวัด Negros Occidental เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Hinigaran แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Hinigaran di Kotamadya Hinigaran, Provinsi Negros Occidental menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Hinigaran Nasional","ms":"Akta menukar status Sekolah Menengah Hinigaran di Perbandaran Hinigaran, Wilayah Negros Occidental kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Hinigaran Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 410","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00410_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00410_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15275-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Hinigaran High School in the Municipality of Hinigaran, Province of Negros Occidental, is\nhereby converted into a national high school to be known as the Hinigaran National High School. The\ncurriculum of said school shall include both academic and vocational courses."}},{"id":"PH-H15275-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15275-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15276"] = {"id":"PH-H15276","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 411  An Act Converting the Ramon Torres Memorial High School in the City of Bago, Province of Negros Occidental, Into a National High School to Be Known as the Ramon Torres National High School.","orig":"Batas Pambansa Blg. 411  An Act Converting the Ramon Torres Memorial High School in the City of Bago, Province of Negros Occidental, Into a National High School to Be Known as the Ramon Torres National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Tưởng niệm Ramon Torres tại Thành phố Bago, Tỉnh Negros Occidental thành Trường Trung học Quốc gia với tên gọi Trường Trung học Ramon Torres Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษาอนุสรณ์ Ramon Torres ในเมือง Bago จังหวัด Negros Occidental เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Ramon Torres แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Memorial Ramon Torres di Kota Bago, Provinsi Negros Occidental menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Ramon Torres Nasional","ms":"Akta menukar status Sekolah Menengah Memorial Ramon Torres di Bandar Bago, Wilayah Negros Occidental kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Ramon Torres Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 411","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00411_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00411_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15276-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Ramon Torres Memorial High School in the City of Bago, Province of Negros Occidental,\nis hereby converted into a national high school to be known as the Ramon Torres National High School. The\ncurriculum of said school shall include both academic and vocational courses."}},{"id":"PH-H15276-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15276-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Minister of Education, Culture and Sports shall implement the provisions of this Act so as to\nmake the said Ramon Torres National High School in operation during the first school term following the\napproval of this Act."}},{"id":"PH-H15276-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15277"] = {"id":"PH-H15277","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":20,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 412  An Act Converting the Cebu School of Arts and Trades in Cebu City Into a Chartered College to Be Known as the Cebu state College of Science and Technology, Expanding Its Jurisdiction and Curricular Programs.","orig":"Batas Pambansa Blg. 412  An Act Converting the Cebu School of Arts and Trades in Cebu City Into a Chartered College to Be Known as the Cebu state College of Science and Technology, Expanding Its Jurisdiction and Curricular Programs."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 412","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 20 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00412_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00412_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15277-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The present Cebu School of Arts and Trades, located in Cebu City, is hereby converted into the\nCebu State College of Science and Technology (CSCST) with extension system that includes Sudlon\nAgricultural College in Cebu; Abellana National School, Cebu City; Danao Vocational School, Danao City;\nTuburan Vocational School, Tuburan, Cebu; Moalboal School of Fisheries, Moalboal, Cebu; Argao\nAgro-Industrial School, Argao, Cebu; Quirino School of Fisheries, Carmen, Cebu; Manuel A. Roxas\nMemorial School of Fisheries, Daanbantayan, Cebu; and Magsaysay School of Fisheries, San Francisco, Cebu\nare likewise converted as part of the state college, hereinafter referred to as the Cebu State College of Science\nand Technology System, with the CSCST, (formerly CSAT), in Cebu City as the State College proper."}},{"id":"PH-H15277-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The purpose of the said state college shall be to provide effective vocational-technical instruction\nand training in industrial, agricultural, fishery, distributive education, and apprenticeship training in\ncooperation with the Ministry of Labor, required for immediate entry into the occupations consistent with the\nmanpower requirements of the Region and to provide opportunities for higher education in the fields of\ntechnological, teacher education, physical and nature sciences; agriculture, fishery, forestry, nautical; and\nspecial programs to promote research, and graduate studies for a progressive executive leadership training."}},{"id":"PH-H15277-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Cebu State College of Science and Technology System shall offer courses in higher\ntechnological education leading to the degrees of Bachelor of Science in Civil Engineering, Electrical and\nMechanical Engineering, Electronics Engineering, Industrial Engineering, Forestry, Fishery, Nautical, and the\nphysical and natural sciences, in addition to its present curricular offerings in elementary (laboratory school),\nfour-year secondary trade curriculum, two-year technical education curriculum, evening opportunity trade\nclasses, degree courses leading to the degrees of Bachelor of Science in Industrial Education, Bachelor of\nScience in Industrial Technology, and other graduate degrees in science and technology."}},{"id":"PH-H15277-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The State College shall be headed by a President hereinafter referred to as the College President,\nassisted by a Vice-President for Technology and a Vice-President for Academic Affairs: Provided, That each\nof the extension units of the CSCST System mentioned in Section 1 of this Act shall be headed by a\nSuperintendent. The powers and duties of the College President in addition to these specially provided for in\nthis Act, shall be those pertaining to the office of a state college president in the Philippines."}},{"id":"PH-H15277-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The governance of the Cebu State Colleges of Science and Technology System is vested in a\nBoard of Trustees to be composed of the Minister of Education and Culture, who shall be the Chairman of the\nBoard, the College President, and the President of the Cebu State College of Science and Technology Alumni\nAssociation, the Regional Director, MEC Region VII, the Chairman of the Regional Development Council,\nRegion VII as members. In the absence or inability of the Minister of Education, the Deputy Minister of\nEducation and Culture or when these positions are vacant, the other members of the Board may select from\namong themselves a temporary chairman who shall act as Chairman.\nThe members of the Board of Trustees shall serve without compensation, but shall receive a per diem of fifty\npesos per meeting. All members of the Board of Trustees shall be entitled to reimbursement of actual\nnecessary expenses incurred either in attendance upon meetings of the Board or upon other official business\nauthorized by resolution of the Board, subject to existing budget laws on honoraria and allowances."}},{"id":"PH-H15277-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The Board of Trustees shall have the following powers and duties in addition to its general\ngoverning powers:\n(a) To appropriate such sums as may be provided by law for the operation and maintenance of the Cebu State\nCollege of Science and Technology System;\n(b) To confer titles or degrees in the fields of study stated in Sections two and three of this Act to successful\ncandidates for graduation;\n(c) To confer certificates and diplomas upon successful candidates for graduation on courses other than degree\n(d) To approve appointments submitted by the College President of all Superintendents of extension units, the\ndean of instruction, college deans, heads of departments, registrar, associate professors, professors, guest\nlecturers, instructors, teachers, and other employees of the State College system; to fix their compensation not\notherwise covered in Section thirteen hereof, subject to Presidential Decree No. 985 and other pertinent\nbudget and compensation laws, hours of service and such other duties and conditions as it may deem proper;\nto grant them in its discretion, leave of absence under such regulations as it may promulgate, any other\nprovision to the contrary notwithstanding, and to remove them for cause after an investigation and hearing\nshall have been held;\n(e) To approve the curricula and rules of discipline drawn up by the College Council as hereinafter provided;\n(f) To provide fellowship for faculty members and scholarships to students showing special evidence of merit;\n(g) To prescribe rules for its own governance, and to enact for the government of the State College system\nsuch rules and regulations, not contrary to law, as may be necessary to carry out the purpose and functions of\nthe State College system as defined in Sections two and three of this Act;\n(h) To approve the staffing pattern of the Cebu State College of Science and Technology proper and the\nextension unit as defined and submitted by their respective heads; and\n(i) To receive in trust legacies, gifts, and donations of real and personal property of all kinds and to administer\nthe same for the benefit of the State College system or of the departments thereof, or for aid to any student or\nstudents, in accordance with the directions and instructions of the donor, and in default thereof, in such\nmanner as the Board of Trustees may in its discretion determine."}},{"id":"PH-H15277-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all the members. All processes\nagainst the Board of Trustees shall be served on the Chairman or Secretary thereof."}},{"id":"PH-H15277-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"On or before the fifteenth day of June of each year, the Board of Trustees shall file with the\nPresident of the Philippines a detailed report, setting forth the programs, conditions, and needs of the State"}},{"id":"PH-H15277-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"There shall be a College Council, consisting of the College President, Vice-President for\nTechnology, Vice-President for Academic Affairs, Dean of Instruction, College Deans, Registrar, and\nDepartment Heads.\nThe Council shall have the power to prescribe the curricula, educational qualifications of professors,\ndepartment heads, deans, instructors, teachers, and key personnel and rules of discipline, subject to the\napproval of the Board of Trustees. It shall fix the requirement for admission to the College, as well as for\ngraduation and the receiving of title or degree. The College Council alone shall have the power to recommend\nstudents or others to be recipients of titles or degrees. Through its President or committee, it shall have\ndisciplinary power over the students within the limits prescribed by the rules of discipline approved by the\nBoard of Trustees."}},{"id":"PH-H15277-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"The body of teachers, instructors, professors, associate professors, department heads, registrar,\ncollege deans, and dean of instruction shall constitute the faculty of the College with the College President\n\nand/or in the latter’s absence, one of the Vice-Presidents of the college, as the presiding officer: Provided,\nThat no teacher, instructor, professor, or lecturer in the State College System shall inculcate sectarian tenets in\nany of their teachings, nor attempt directly, under penalty of dismissal by the Board of Trustees, to influence\nstudents or attendants for or against any particular church or religious sect."}},{"id":"PH-H15277-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"The administrative officer shall be at the same time the secretary of the Board of Trustees who\nshall keep such records of the State College as may be designated by the Board."}},{"id":"PH-H15277-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"The professors, associate professors, deans, registrar, and department heads, and\nsuperintendents of extension units shall be covered by the appropriate civil service rules and regulations."}},{"id":"PH-H15277-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"The compensation per annum of the following shall be fixed at the minimum as follows:\nCollege President forty-five thousand pesos; Vice-Presidents twenty-four thousand pesos each; administrative\nofficer who is the secretary of the Board of Trustees fifteen thousand pesos; Superintendents of extension\nunits eighteen thousand pesos; department heads fifteen thousand pesos; college registrar fifteen thousand\npesos; professors twelve thousand pesos; associate professors ten thousand four hundred pesos; lecturers fifty\npesos an hour. Those compensation may be determined in accordance with Presidential Decree No. 985 and\nother pertinent budget and compensation laws."}},{"id":"PH-H15277-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"The Board of Trustees shall fix the compensation of the employees and other personnel of the\nCollege not otherwise covered in Section thirteen hereof whose appointments shall be recommended by the\nPresident of the College, subject to Presidential Decree No. 985 and other pertinent budget and compensation"}},{"id":"PH-H15277-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"In the absence or inability of the College President or when this petition is vacant, the\nVice-President for Technology shall temporarily perform the duties of the College President until such time\nwhen he returns to duty or when another College President shall have been appointed."}},{"id":"PH-H15277-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"In order not to disrupt the present administrative operation of the Cebu School of Arts and\nTrades, and the schools to be converted as extension units, the faculty of the school as well as the other\npersonnel shall be absorbed by the new State College system: Provided, That the incumbent Vocational\nCollege Superintendent of Cebu Schools of Arts and Trades shall be appointed as the first College President\nwho, upon his assumption to the position shall recommend to the President of the Philippines the\nappointments of Vice-President for Technology and Vice-President for Academic Affairs; all other officials\nand personnel whose appointment specifically vested in the President of the Philippines shall be issued\nappointments by the College President consistent with the actual service needs of the converted State College\nSystem to be approved by the Board of Trustees. Subsequent salary increases of personnel shall be approved\nby the Board of Trustees upon the recommendation of the College President."}},{"id":"PH-H15277-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"The Treasurer of the Philippines shall be ex officio treasurer of the College and all accounts\nand expenses thereof shall be audited by the Commission on Audit or its duly authorized resident\nrepresentative."}},{"id":"PH-H15277-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"All the personnel, properties, including buildings, sites, and improvements thereof, records,\nobligations, monies and appropriations of the Cebu School of Arts and Trades and the schools mentioned in\nSection 1 to be converted as part of the CSCST System are hereby transferred to the converted Cebu State\nCollege System."}},{"id":"PH-H15277-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"All existing appropriations for the Cebu School of Arts and Trades are hereby transferred to the\nCebu State College of Science and Technology to be disbursed in accordance with provisions of this Act. The\nnecessary sum for the operation and maintenance of the state college shall be provided for in subsequent\nGeneral Appropriations Acts, until which time the operation of the institution as a college shall be deferred,\nprovided that its new name shall take effect upon approval of this Act. casia"}},{"id":"PH-H15277-A20","no":20,"noLabel":{"en":"Section 20"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15278"] = {"id":"PH-H15278","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 413  An Act Providing for the Establishment of a Ten-Bed Municipal Hospital in the Municipality of Lakewood, Province of Zamboanga Del Sur, to Be Known as the Lakewood Municipal Hospital.","orig":"Batas Pambansa Blg. 413  An Act Providing for the Establishment of a Ten-Bed Municipal Hospital in the Municipality of Lakewood, Province of Zamboanga Del Sur, to Be Known as the Lakewood Municipal Hospital.","vi":"Đạo luật thành lập Bệnh viện 10 giường Đô thị tại Thị trấn Lakewood, Tỉnh Zamboanga Del Sur với tên gọi Bệnh viện Lakewood Đô thị","th":"พระราชบัญญัติจัดตั้งโรงพยาบาล 10 เตียงเทศบาลในเทศบาล Lakewood จังหวัด Zamboanga Del Sur ในชื่อโรงพยาบาล Lakewood เทศบาล","id":"Undang-Undang membentuk Rumah Sakit 10 tempat tidur Kotamadya di Kotamadya Lakewood, Provinsi Zamboanga Del Sur dengan nama Rumah Sakit Lakewood Kotamadya","ms":"Akta menubuhkan Hospital 10 tempat tidur Perbandaran di Perbandaran Lakewood, Wilayah Zamboanga Del Sur dengan nama Hospital Lakewood Perbandaran"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 413","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00413_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00413_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15278-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed municipal hospital in the Municipality of Lakewood, Province of Zamboanga del Sur, to be\nknown as the Lakewood Municipal Hospital."}},{"id":"PH-H15278-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15278-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15279"] = {"id":"PH-H15279","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 414  An Act Establishing a Ten-Bed Capacity Municipal Hospital in the Municipality of Languyan, Province of Tawi-Tawi, to Be Known as the Languyan Municipal Hospital.","orig":"Batas Pambansa Blg. 414  An Act Establishing a Ten-Bed Capacity Municipal Hospital in the Municipality of Languyan, Province of Tawi-Tawi, to Be Known as the Languyan Municipal Hospital."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 414","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00414_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00414_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15279-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed capacity municipal hospital in the Municipality of Languyan, Province of Tawi-Tawi, to be\nknown as the Languyan Municipal Hospital."}},{"id":"PH-H15279-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Bilang\n230 for the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be\nnecessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15279-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15280"] = {"id":"PH-H15280","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 415  An Act Establishing a Ten-Bed Capacity Municipal Hospital in the Municipality of Caramoan, Province of Camarines Sur, to Be Known as the Caramoan Municipal Hospital, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 415  An Act Establishing a Ten-Bed Capacity Municipal Hospital in the Municipality of Caramoan, Province of Camarines Sur, to Be Known as the Caramoan Municipal Hospital, and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 415","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00415_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00415_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15280-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed capacity municipal hospital in the Municipality of Caramoan, Province of Camarines Sur, to\nbe known as the Caramoan Municipal Hospital."}},{"id":"PH-H15280-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Minister of Health shall promulgate rules and regulations as may be necessary to carry into\neffect the purpose of this Act."}},{"id":"PH-H15280-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 131\nand Batas Pambansa Blg. 230 for the Ministry of Health intended for new or expanded hospitals. Thereafter,\nsuch sum as may be necessary for its operation and maintenance shall be included in the annual General\nAppropriations Act."}},{"id":"PH-H15280-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15281"] = {"id":"PH-H15281","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 416  An Act Converting Pigcawayan Municipal High School, in the Municipality Op Pigcawayan, Province of North Cotabato, Into a National High School to Be Known as Pigcawayan National High School, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 416  An Act Converting Pigcawayan Municipal High School, in the Municipality Op Pigcawayan, Province of North Cotabato, Into a National High School to Be Known as Pigcawayan National High School, and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Pigcawayan Đô thị tại Thị trấn Op Pigcawayan, Tỉnh North Cotabato thành Trường Trung học Quốc gia với tên gọi Trường Trung học Pigcawayan Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Pigcawayan เทศบาลในเทศบาล Op Pigcawayan จังหวัด North Cotabato เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Pigcawayan แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Pigcawayan Kotamadya di Kotamadya Op Pigcawayan, Provinsi North Cotabato menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Pigcawayan Nasional","ms":"Akta menukar status Sekolah Menengah Pigcawayan Perbandaran di Perbandaran Op Pigcawayan, Wilayah North Cotabato kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Pigcawayan Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 416","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00416_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00416_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15281-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Pigcawayan Municipal High School in the Municipality of Pigcawayan, Province of North\nCotabato, is hereby converted into a national high school to be known as the Pigcawayan National High"}},{"id":"PH-H15281-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education, Culture and Sports is hereby directed to take the necessary steps for\nthe conversion, operation and immediate implementation of this Act."}},{"id":"PH-H15281-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15281-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15282"] = {"id":"PH-H15282","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 417  An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Malay, Province of Aklan, to Be Known as the Malay Municipal Hospital, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 417  An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Malay, Province of Aklan, to Be Known as the Malay Municipal Hospital, and Appropriating Funds therefor.","vi":"Đạo luật thành lập Bệnh viện 10 giường Đô thị tại Thị trấn Malay, Tỉnh Aklan với tên gọi Bệnh viện Malay Đô thị","th":"พระราชบัญญัติจัดตั้งโรงพยาบาล 10 เตียงเทศบาลในเทศบาล Malay จังหวัด Aklan ในชื่อโรงพยาบาล Malay เทศบาล","id":"Undang-Undang membentuk Rumah Sakit 10 tempat tidur Kotamadya di Kotamadya Malay, Provinsi Aklan dengan nama Rumah Sakit Malay Kotamadya","ms":"Akta menubuhkan Hospital 10 tempat tidur Perbandaran di Perbandaran Malay, Wilayah Aklan dengan nama Hospital Malay Perbandaran"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 417","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00417_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00417_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15282-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed municipal hospital in the Municipality of Malay, Province of Aklan, to be known as the\nMalay Municipal Hospital."}},{"id":"PH-H15282-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15282-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15283"] = {"id":"PH-H15283","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 418  An Act Establishing a National High School in the Municipality of Catarman, Province of Northern Samar, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 418  An Act Establishing a National High School in the Municipality of Catarman, Province of Northern Samar, and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 418","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00418_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00418_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15283-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established a national high school in the Municipality of Catarman, Province of\nNorthern Samar. The curriculum of said school shall include both academic and vocational courses."}},{"id":"PH-H15283-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Minister of Education, Culture and Sports who shall implement the provisions of this Act so\nas to make the aforementioned high school operational on the first school term after the approval hereof, is\nhereby empowered to promulgate rules and regulations in connection with the administration of the said"}},{"id":"PH-H15283-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred and fifty thousand pesos for the operation of the school shall be\nfunded out of the appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education,\nCulture and Sports intended for new national high schools. Thereafter, the amount needed for its maintenance\nand operation shall be in the forthcoming General Appropriations Acts."}},{"id":"PH-H15283-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15284"] = {"id":"PH-H15284","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 419  An Act Converting the Los Baos School of Fisheries in Los Baos, Laguna, Into a College to Be Known as the Los Baos College of Fisheries and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 419  An Act Converting the Los Baos School of Fisheries in Los Baos, Laguna, Into a College to Be Known as the Los Baos College of Fisheries and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 419","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00419_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00419_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15284-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Los Baños School of Fisheries in Los Baños, Laguna, is hereby converted into a college to\nbe known as the Los Baños College of Fisheries and shall be under the supervision of the Ministry of\nEducation, Culture and Sports."}},{"id":"PH-H15284-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Los Baños College of Fisheries shall, in addition to the secondary fishery curriculum and\nthe three-year course leading to the Diploma in Fishery Technology, offer the following collegiate courses:\n(a) Bachelor of Science in Fishery Education\n(b) Bachelor of Science in Fisheries"}},{"id":"PH-H15284-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Ministry of Education, Culture and Sports is hereby directed to take such steps as are\nnecessary for the conversion, operation and immediate implementation of this Act."}},{"id":"PH-H15284-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The existing appropriations for the Los Baños School of Fisheries are hereby transferred to the\nLos Baños College of Fisheries to be disbursed in accordance with the provisions of this Act. Thereafter, the\nnecessary amount required for the operation and maintenance of the new college shall be provided for in\nsubsequent General Appropriations Acts, until which time the operation of the institution as a college shall be\ndeferred, provided that its new name shall take effect upon approval of this Act."}},{"id":"PH-H15284-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15285"] = {"id":"PH-H15285","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 420  An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Balindong, Province of Lanao Del Sur, to Be Known as the Balindong Municipal Hospital, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 420  An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Balindong, Province of Lanao Del Sur, to Be Known as the Balindong Municipal Hospital, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật thành lập Bệnh viện 10 giường Đô thị tại Thị trấn Balindong, Tỉnh Lanao Del Sur với tên gọi Bệnh viện Balindong Đô thị","th":"พระราชบัญญัติจัดตั้งโรงพยาบาล 10 เตียงเทศบาลในเทศบาล Balindong จังหวัด Lanao Del Sur ในชื่อโรงพยาบาล Balindong เทศบาล","id":"Undang-Undang membentuk Rumah Sakit 10 tempat tidur Kotamadya di Kotamadya Balindong, Provinsi Lanao Del Sur dengan nama Rumah Sakit Balindong Kotamadya","ms":"Akta menubuhkan Hospital 10 tempat tidur Perbandaran di Perbandaran Balindong, Wilayah Lanao Del Sur dengan nama Hospital Balindong Perbandaran"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 420","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00420_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00420_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15285-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed municipal hospital in the Municipality of Balindong, Province of Lanao del Sur, to be\nknown as the Balindong Municipal Hospital."}},{"id":"PH-H15285-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15285-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15286"] = {"id":"PH-H15286","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 421  An Act Converting the Agno High School in the Municipality of Agno, Province of Pangasinan, Into a National High School.","orig":"Batas Pambansa Blg. 421  An Act Converting the Agno High School in the Municipality of Agno, Province of Pangasinan, Into a National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Agno tại Thị trấn Agno, Tỉnh Pangasinan thành Trường Trung học Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Agno ในเทศบาล Agno จังหวัด Pangasinan เป็น โรงเรียนมัธยมศึกษาแห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Agno di Kotamadya Agno, Provinsi Pangasinan menjadi Sekolah Menengah Nasional","ms":"Akta menukar status Sekolah Menengah Agno di Perbandaran Agno, Wilayah Pangasinan kepada Sekolah Menengah Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 421","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00421_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00421_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15286-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Agno High School in the Municipality of Agno, Province of Pangasinan, is hereby\nconverted into a national high school to be known as the Agno National High School."}},{"id":"PH-H15286-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education, Culture and Sports is hereby directed to take the necessary steps for\nthe conversion and operation of said school and the immediate implementation of this Act."}},{"id":"PH-H15286-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15286-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15287"] = {"id":"PH-H15287","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 422  An Act Converting the Dingle Community High School in the Municipality of Dingle, Province of Iloilo, Into a National High School to Be Known as the Dingle National High School.","orig":"Batas Pambansa Blg. 422  An Act Converting the Dingle Community High School in the Municipality of Dingle, Province of Iloilo, Into a National High School to Be Known as the Dingle National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Dingle Community tại Thị trấn Dingle, Tỉnh Iloilo thành Trường Trung học Quốc gia với tên gọi Trường Trung học Dingle Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Dingle Community ในเทศบาล Dingle จังหวัด Iloilo เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Dingle แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Dingle Community di Kotamadya Dingle, Provinsi Iloilo menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Dingle Nasional","ms":"Akta menukar status Sekolah Menengah Dingle Community di Perbandaran Dingle, Wilayah Iloilo kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Dingle Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 422","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00422_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00422_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15287-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Dingle Community High School in the Municipality of Dingle, Province of Iloilo, is hereby\nconverted into a national high school to be known as the Dingle National High School."}},{"id":"PH-H15287-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education, Culture and Sports is hereby directed to take the necessary steps for\nthe conversion and operation of said school and the immediate implementation of this Act."}},{"id":"PH-H15287-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15287-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15288"] = {"id":"PH-H15288","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 423  An Act Converting the Mina Community High School in the Municipality of Mina, Province of Iloilo, Into a National High School to Be Known as the Mina National High School.","orig":"Batas Pambansa Blg. 423  An Act Converting the Mina Community High School in the Municipality of Mina, Province of Iloilo, Into a National High School to Be Known as the Mina National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Mina Community tại Thị trấn Mina, Tỉnh Iloilo thành Trường Trung học Quốc gia với tên gọi Trường Trung học Mina Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Mina Community ในเทศบาล Mina จังหวัด Iloilo เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Mina แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Mina Community di Kotamadya Mina, Provinsi Iloilo menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Mina Nasional","ms":"Akta menukar status Sekolah Menengah Mina Community di Perbandaran Mina, Wilayah Iloilo kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Mina Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 423","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00423_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00423_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15288-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Mina Community High School in the Municipality of Mina, Province of Iloilo, is hereby\nconverted into a national high school to be known as the Mina National High School."}},{"id":"PH-H15288-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education, Culture and Sports is hereby directed to take the necessary steps for\nthe conversion and operation of said school and immediate implementation of this Act."}},{"id":"PH-H15288-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15288-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15289"] = {"id":"PH-H15289","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 424  An Act Converting the Binggawan Community High School in the Municipality of Binggawan, Province of Iloilo, Into a National High School to Be Known as Binggawan National High School.","orig":"Batas Pambansa Blg. 424  An Act Converting the Binggawan Community High School in the Municipality of Binggawan, Province of Iloilo, Into a National High School to Be Known as Binggawan National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Binggawan Community tại Thị trấn Binggawan, Tỉnh Iloilo thành Trường Trung học Quốc gia với tên gọi Trường Trung học Binggawan Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Binggawan Community ในเทศบาล Binggawan จังหวัด Iloilo เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Binggawan แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Binggawan Community di Kotamadya Binggawan, Provinsi Iloilo menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Binggawan Nasional","ms":"Akta menukar status Sekolah Menengah Binggawan Community di Perbandaran Binggawan, Wilayah Iloilo kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Binggawan Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 424","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00424_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00424_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15289-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Binggawan Community High School in the Municipality of Binggawan, Province of Iloilo,\nis hereby converted into a national high school to be known as Binggawan National High School."}},{"id":"PH-H15289-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education, Culture and Sports is hereby directed to take the necessary steps for\nthe conversion, operation and immediate implementation of this Act."}},{"id":"PH-H15289-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15289-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
