  FT["PH-H15317"] = {"id":"PH-H15317","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 452  An Act Converting the Passi High School in the Municipality Op Passi, Province of Iloilo, Into a National High School to Be Known as the Passi National High School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 452  An Act Converting the Passi High School in the Municipality Op Passi, Province of Iloilo, Into a National High School to Be Known as the Passi National High School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Passi tại Thị trấn Op Passi, Tỉnh Iloilo thành Trường Trung học Quốc gia với tên gọi Trường Trung học Passi Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Passi ในเทศบาล Op Passi จังหวัด Iloilo เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Passi แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Passi di Kotamadya Op Passi, Provinsi Iloilo menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Passi Nasional","ms":"Akta menukar status Sekolah Menengah Passi di Perbandaran Op Passi, Wilayah Iloilo kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Passi Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 452","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00452_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00452_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15317-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Passi High School in the Municipality of Passi, Province of Iloilo, is converted into a\nnational high school to be known as the Passi National High School."}},{"id":"PH-H15317-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15317-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15318"] = {"id":"PH-H15318","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 453  An Act Converting the VIctorino Salcedo High School in the Municipality of Sara, Province of Iloilo, Into a National High School to Be Known as the VIctorino Salcedo National High School, and Authorizing the Appropriation of Funds","orig":"Batas Pambansa Blg. 453  An Act Converting the VIctorino Salcedo High School in the Municipality of Sara, Province of Iloilo, Into a National High School to Be Known as the VIctorino Salcedo National High School, and Authorizing the Appropriation of Funds","vi":"Đạo luật chuyển đổi Trường Trung học VIctorino Salcedo tại Thị trấn Sara, Tỉnh Iloilo thành Trường Trung học Quốc gia với tên gọi Trường Trung học VIctorino Salcedo Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา VIctorino Salcedo ในเทศบาล Sara จังหวัด Iloilo เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา VIctorino Salcedo แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah VIctorino Salcedo di Kotamadya Sara, Provinsi Iloilo menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah VIctorino Salcedo Nasional","ms":"Akta menukar status Sekolah Menengah VIctorino Salcedo di Perbandaran Sara, Wilayah Iloilo kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah VIctorino Salcedo Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 453","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00453_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00453_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15318-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Victorino Salcedo High School in the Municipality of Sara, Province of Iloilo, is converted\ninto a national high school to be known as the Victorino Salcedo National High School."}},{"id":"PH-H15318-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15318-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15319"] = {"id":"PH-H15319","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 454  An Act Converting the Lemery Municipal High School in the Municipality of Lemery, Province of Iloilo, Into a National High School to Be Known as the Lemery National High School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 454  An Act Converting the Lemery Municipal High School in the Municipality of Lemery, Province of Iloilo, Into a National High School to Be Known as the Lemery National High School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Lemery Đô thị tại Thị trấn Lemery, Tỉnh Iloilo thành Trường Trung học Quốc gia với tên gọi Trường Trung học Lemery Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Lemery เทศบาลในเทศบาล Lemery จังหวัด Iloilo เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Lemery แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Lemery Kotamadya di Kotamadya Lemery, Provinsi Iloilo menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Lemery Nasional","ms":"Akta menukar status Sekolah Menengah Lemery Perbandaran di Perbandaran Lemery, Wilayah Iloilo kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Lemery Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 454","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00454_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00454_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15319-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Lemery Municipal High School in the Municipality of Lemery, Province of Iloilo, is\nconverted into a national high school to be known as the Lemery National High School."}},{"id":"PH-H15319-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15319-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15320"] = {"id":"PH-H15320","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 455  An Act Converting the San Rafael Barangay High School in the Municipality of San Rafael, Province of Iloilo, Into a National High School to Be Known as the San Rafael National High School.","orig":"Batas Pambansa Blg. 455  An Act Converting the San Rafael Barangay High School in the Municipality of San Rafael, Province of Iloilo, Into a National High School to Be Known as the San Rafael National High School.","vi":"Đạo luật chuyển đổi Trường Trung học San Rafael Barangay tại Thị trấn San Rafael, Tỉnh Iloilo thành Trường Trung học Quốc gia với tên gọi Trường Trung học San Rafael Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา San Rafael Barangay ในเทศบาล San Rafael จังหวัด Iloilo เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา San Rafael แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah San Rafael Barangay di Kotamadya San Rafael, Provinsi Iloilo menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah San Rafael Nasional","ms":"Akta menukar status Sekolah Menengah San Rafael Barangay di Perbandaran San Rafael, Wilayah Iloilo kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah San Rafael Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 455","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00455_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00455_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15320-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The San Rafael Barangay High School in the Municipality of San Rafael, Province of Iloilo, is\nconverted into a national high school to be known as the San Rafael National High School."}},{"id":"PH-H15320-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15320-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15321"] = {"id":"PH-H15321","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 456  An Act Converting the Present Parang Municipal High School in the Municipality of Parang, Province of Maguindanao, Into a National High School.","orig":"Batas Pambansa Blg. 456  An Act Converting the Present Parang Municipal High School in the Municipality of Parang, Province of Maguindanao, Into a National High School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 456","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00456_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00456_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15321-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The present Parang Municipal High School in the Municipality of Parang, Province of\nMaguindanao, is hereby converted into a national high school to be known as Parang National High School."}},{"id":"PH-H15321-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The institution shall offer such courses as may be necessary for the vocational upliftment of the\nstudent, in addition to courses being presently offered therein."}},{"id":"PH-H15321-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Minister of Education, Culture and Sports is hereby empowered to issue such rules and\nregulations as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H15321-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education, Culture and Sports\nintended for new national high schools and an additional amount corresponding to fifty percent of its share in\nthe budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15321-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"All buildings, equipment, or any property of the Parang Municipal High School as well as the\nadministration staff and faculty members thereof, shall be absorbed by the new institution, the Parang\nNational High School."}},{"id":"PH-H15321-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"All laws, orders and regulations, or parts thereof inconsistent with this Act are hereby modified\nor repealed accordingly."}},{"id":"PH-H15321-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15322"] = {"id":"PH-H15322","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 457  An Act Establishing a School of Fisheries in the Municipality of San VIcente Province of Northern Samar, to Be Known as the San VIcente School of Fisheries and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 457  An Act Establishing a School of Fisheries in the Municipality of San VIcente Province of Northern Samar, to Be Known as the San VIcente School of Fisheries and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 457","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00457_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00457_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15322-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the direct supervision of the Bureau of Secondary Education a\nschool of fisheries in the Municipality of San Vicente, Province of Northern Samar, to be known as the San\nVicente School of Fisheries."}},{"id":"PH-H15322-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Minister of Education, Culture and Sports shall promulgate such rules and regulations as are\nnecessary to implement the provisions of this Act. He shall determine the manner by which said school shall\nbe operational."}},{"id":"PH-H15322-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Such sum as may be necessary for the operation and maintenance of said school shall be\nprovided in subsequent General Appropriations Acts, until which time the operation of the institution as a\nnational high school shall be deferred."}},{"id":"PH-H15322-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15323"] = {"id":"PH-H15323","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 458  An Act Converting the Doa Francisca Lacsamana De Ortega Memorial Municipal High School in the Municipality of Bangar, Province of La Union, Into a National High School to Be Known as the Doa Francisca Lacsamana De Ortega Memorial National High School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 458  An Act Converting the Doa Francisca Lacsamana De Ortega Memorial Municipal High School in the Municipality of Bangar, Province of La Union, Into a National High School to Be Known as the Doa Francisca Lacsamana De Ortega Memorial National High School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Tưởng niệm Doa Francisca Lacsamana De Ortega Đô thị tại Thị trấn Bangar, Tỉnh La Union thành Trường Trung học Quốc gia với tên gọi Trường Trung học Tưởng niệm Doa Francisca Lacsamana De Ortega Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษาอนุสรณ์ Doa Francisca Lacsamana De Ortega เทศบาลในเทศบาล Bangar จังหวัด La Union เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษาอนุสรณ์ Doa Francisca Lacsamana De Ortega แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Memorial Doa Francisca Lacsamana De Ortega Kotamadya di Kotamadya Bangar, Provinsi La Union menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Memorial Doa Francisca Lacsamana De Ortega Nasional","ms":"Akta menukar status Sekolah Menengah Memorial Doa Francisca Lacsamana De Ortega Perbandaran di Perbandaran Bangar, Wilayah La Union kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Memorial Doa Francisca Lacsamana De Ortega Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 458","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00458_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00458_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15323-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Doña Francisca Lacsamana de Ortega Memorial High School in the Municipality of Bangar,\nProvince of La Union, is converted into a national high school to be known as the Doña Francisca Lacsamana\nde Ortega Memorial National High School."}},{"id":"PH-H15323-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15323-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15324"] = {"id":"PH-H15324","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 459  An Act Converting the Manolo Fortich Municipal High School in the Municipality of Manolo Fortich, Province of Bukidnon, Into a National High School and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 459  An Act Converting the Manolo Fortich Municipal High School in the Municipality of Manolo Fortich, Province of Bukidnon, Into a National High School and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Manolo Fortich Đô thị tại Thị trấn Manolo Fortich, Tỉnh Bukidnon thành Trường Trung học Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Manolo Fortich เทศบาลในเทศบาล Manolo Fortich จังหวัด Bukidnon เป็น โรงเรียนมัธยมศึกษาแห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Manolo Fortich Kotamadya di Kotamadya Manolo Fortich, Provinsi Bukidnon menjadi Sekolah Menengah Nasional","ms":"Akta menukar status Sekolah Menengah Manolo Fortich Perbandaran di Perbandaran Manolo Fortich, Wilayah Bukidnon kepada Sekolah Menengah Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 459","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00459_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00459_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15324-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Manolo Fortich Municipal High School in the Municipality of Manolo Fortich, Province of\nBukidnon, is converted into a national high school, to be known as Manolo Fortich National High School."}},{"id":"PH-H15324-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education, Culture and Sports is hereby directed to take such steps as are\nnecessary for the conversion and operation of the school and immediate implementation of this Act."}},{"id":"PH-H15324-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education, Culture and Sports\nintended for new national high schools and an additional amount corresponding to fifty percent of its share in\nthe budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools."}},{"id":"PH-H15324-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15325"] = {"id":"PH-H15325","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 460  An Act Converting the Luna Municipal High School in the Municipality of Luna, Province of La Union, Into a National High School to Be Known as the Luna National High School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 460  An Act Converting the Luna Municipal High School in the Municipality of Luna, Province of La Union, Into a National High School to Be Known as the Luna National High School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Luna Đô thị tại Thị trấn Luna, Tỉnh La Union thành Trường Trung học Quốc gia với tên gọi Trường Trung học Luna Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Luna เทศบาลในเทศบาล Luna จังหวัด La Union เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Luna แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Luna Kotamadya di Kotamadya Luna, Provinsi La Union menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Luna Nasional","ms":"Akta menukar status Sekolah Menengah Luna Perbandaran di Perbandaran Luna, Wilayah La Union kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Luna Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 460","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00460_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00460_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15325-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Luna Municipal High School in the Municipality of Luna, Province of La Union, is\nconverted into a national high school to be known as the Luna National High School."}},{"id":"PH-H15325-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15325-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
