  FT["PH-H15393"] = {"id":"PH-H15393","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 529  An Act Converting the sta. Maria Barangay High School in the Municipality of Potia, Province of Ifugao, Into a National High School to Be Known as the sta. Maria National High School.","orig":"Batas Pambansa Blg. 529  An Act Converting the sta. Maria Barangay High School in the Municipality of Potia, Province of Ifugao, Into a National High School to Be Known as the sta. Maria National High School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 529","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00529_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00529_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15393-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Sta. Maria Barangay High School in the Municipality of Potia, Province of Ifugao, is hereby\nconverted into a national high school to be known as the Sta. Maria National High School."}},{"id":"PH-H15393-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15393-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10,\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15394"] = {"id":"PH-H15394","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 530  An Act Establishing a Municipal Hospital in the Dasmarias Bagong Bayan Project in the Municipality of Dasmarias, Province of Cavite, to Be Known as the Dbb Municipal Hospital and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 530  An Act Establishing a Municipal Hospital in the Dasmarias Bagong Bayan Project in the Municipality of Dasmarias, Province of Cavite, to Be Known as the Dbb Municipal Hospital and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 530","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00530_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00530_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15394-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the direct supervision of the office of the Minister, Ministry of\nHealth, a ten-bed municipal hospital in Area A of the Dasmariñas, Bagong Bayan Project in the Municipality\nof Dasmariñas, Province of Cavite, to be known as the DBB Municipal Hospital."}},{"id":"PH-H15394-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15394-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15395"] = {"id":"PH-H15395","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":15,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 531  An Act Converting the San Jose National High School in the Municipality of San Jose, Province of Occidental Mindoro, Into Occidental Mindoro National College, Providing a Charter for this Purpose and Funds therefor.","orig":"Batas Pambansa Blg. 531  An Act Converting the San Jose National High School in the Municipality of San Jose, Province of Occidental Mindoro, Into Occidental Mindoro National College, Providing a Charter for this Purpose and Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học San Jose Quốc gia tại Thị trấn San Jose, Tỉnh Occidental Mindoro thành Cao đẳng Occidental Mindoro Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา San Jose แห่งชาติในเทศบาล San Jose จังหวัด Occidental Mindoro เป็น วิทยาลัย Occidental Mindoro แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah San Jose Nasional di Kotamadya San Jose, Provinsi Occidental Mindoro menjadi Sekolah Tinggi Occidental Mindoro Nasional","ms":"Akta menukar status Sekolah Menengah San Jose Kebangsaan di Perbandaran San Jose, Wilayah Occidental Mindoro kepada Kolej Occidental Mindoro Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 531","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 15 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00531_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00531_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15395-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The present San Jose National High School located in the Municipality of San Jose, Province of\nOccidental Mindoro, is hereby converted into Occidental Mindoro National College, hereinafter referred to in\nthis Act as the College."}},{"id":"PH-H15395-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The College, in addition to technical and vocational education, shall provide and offer\nbaccalaureate courses leading to the degrees of Bachelor of Science in Education, Bachelor of Science in\nElementary Education, Bachelor of Arts, Bachelor of Science in Commerce, Bachelor of Science in\nAgriculture, Bachelor of Science in Fishery, and Bachelor of Science in Forestry."}},{"id":"PH-H15395-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"No student, provided he/she qualifies in the NCEE test and passes the College Admission Test\nshall be denied admission to the College by reason of sex, ethnic consideration or religious beliefs."}},{"id":"PH-H15395-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The College shall be headed by a Superintendent to be appointed by the President of the\nPhilippines upon recommendation by the Minister of Education, Culture and Sports. His salary and other\nemoluments shall be fixed by the Board of Trustees, subject to P.D. No. 985 and other pertinent budget and\ncompensation laws.\nThe powers and duties of the Superintendent of the College, in addition to those specifically provided in this\nAct, shall be those usually pertaining to the office of the president of a state college."}},{"id":"PH-H15395-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The governing body of the College shall be the Board of Trustees, to be composed of the\nMinister of Education, Culture and Sports or his duly authorized representative as chairman, the Regional\nDirector of the National Economic and Development Authority, the Superintendent of the College, and four\n(4) other distinguished citizens of the Province of Occidental Mindoro, who shall be appointed by the\nPresident, as members. Of the four (4) appointed members, one shall be an authority in agriculture, one in\ntrade and technology, one in general education, and one in commerce and industry. Of the four members first\nappointed by the President of the Philippines, one shall serve for one (1) year, one to serve for two (2) years,\none to serve for three (3) years, and one to serve for four (4) years. Thereafter, persons appointed to succeed\nsuch members shall hold office for a term of four (4) years and until their successors shall have been\nappointed and qualified. In case of a permanent vacancy, the position shall be filled by the President of the\nPhilippines. Such appointee shall hold office for the unexpired term only."}},{"id":"PH-H15395-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all the members holding office\nat the time a meeting is called. All processes for the members of the Board of Trustees shall be served on the\nSuperintendent of the College or Secretary thereof."}},{"id":"PH-H15395-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"The members of the Board of Trustees shall serve without compensation but shall be entitled to\nan allowance of two hundred pesos (P200.00) per meeting actually attended, but not exceeding six hundred\npesos a month and to reimbursement of actual and necessary expenses on other official business as may be\nauthorized by the Board, subject to existing budget laws on honoraria and allowances."}},{"id":"PH-H15395-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"The Board of Trustees shall have the following powers and duties:\n(a) To receive and appropriate for the purposes specified by law such sum as may be provided for the support\nof the College;\n\n(b) To confer degrees upon successful candidates for graduation of the College, honorary degrees upon\npersons in recognition of learning, statesmanship and public service;\n(c) To prescribe, develop and update a College Admission Test for all applicants for enrollment;\n(d) Subject to Civil Service Law, rules and regulations, to confirm appointments made by the Superintendent\nof the College to the registrar, deans of the different schools or colleges, heads of departments, professors,\ninstructors, lecturers and other employees of the College;\n(e) To remove, dismiss or suspend, demote and impose any other penalty and all other disciplinary actions\nupon erring teachers and employees for cause after the proper investigation and hearing pursuant to the\nprovision of the Civil Service Law;\n(f) To prescribe, develop and approve the different curricula of the College upon approval by the Ministry of\nEducation, Culture and Sports;\n(g) To prescribe and modify rules of conduct and discipline for the teachers and employees of the College in\naccordance with the Civil Service Law, rules and regulations;\n(h) To prescribe rules for its government or such rules and regulations not contrary to law and as may be\ndeemed necessary to carry out the purpose and functions of the college."}},{"id":"PH-H15395-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"There shall be a secretary of the College who shall be appointed by the Superintendent of the\nCollege subject however to a confirmation of the Board of Trustees. He shall also be the secretary of the\nBoard of Trustees and shall keep the records of the College and perform duties as may be determined by the"}},{"id":"PH-H15395-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"Heads of bureaus and offices of the national government are hereby authorized to loan or\ntransfer upon request of the Superintendent of the College, such apparatus, equipment or supplies that may be\nneeded by the College and to detail employees for duty therein when in the judgment of the head of the bureau\nor office concerned, such apparatus, equipment, supplies or the services of such employees can be spared\nwithout serious detriment to their offices."}},{"id":"PH-H15395-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"All parcels of land, buildings, equipment and facilities owned by the San Jose National High\nSchool as well as all obligations are hereby transferred to and assumed by the Occidental Mindoro National"}},{"id":"PH-H15395-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"All existing appropriations for the San Jose National High School are hereby transferred to the\nOccidental Mindoro National College, to be disbursed in accordance with the provisions of this Act. The\nnecessary sum for the operation and maintenance of the new college shall be provided for in subsequent\nGeneral Appropriations Acts, until which time the operations of the institution as a college shall be deferred,\nprovided that its new name shall take effect upon approval of this Act."}},{"id":"PH-H15395-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"The Minister of Education, Culture and Sports is hereby directed to take such steps as are\nnecessary for the immediate implementation of this Act."}},{"id":"PH-H15395-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"All laws, decrees, executive orders or regulations contrary to or inconsistent herewith are\nhereby repealed or amended accordingly."}},{"id":"PH-H15395-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15396"] = {"id":"PH-H15396","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 533  An Act Providing for the Establishment, Operation and Maintenance of a Ten-Bed Municipal Hospital in the Municipality of Maddela, Province of Quirino, and Providing Funds therefor.","orig":"Batas Pambansa Blg. 533  An Act Providing for the Establishment, Operation and Maintenance of a Ten-Bed Municipal Hospital in the Municipality of Maddela, Province of Quirino, and Providing Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 533","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00533_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00533_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15396-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed municipal hospital in the Municipality of Maddela, Province of Quirino, to be known as the\nMaddela Municipal Hospital."}},{"id":"PH-H15396-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The hospital shall be constructed in a site to be determined by the Sangguniang Bayan of the\nMunicipality of Maddela, in consultation with the Office of the Minister, Ministry of Health."}},{"id":"PH-H15396-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sums as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15396-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15397"] = {"id":"PH-H15397","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 534  An Act Converting the Pinaripad Barangay High School in the Municipality of Aglipay, Province of Quirino, Into a National High School to Be Known as the Pinaripad National High School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 534  An Act Converting the Pinaripad Barangay High School in the Municipality of Aglipay, Province of Quirino, Into a National High School to Be Known as the Pinaripad National High School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Pinaripad Barangay tại Thị trấn Aglipay, Tỉnh Quirino thành Trường Trung học Quốc gia với tên gọi Trường Trung học Pinaripad Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Pinaripad Barangay ในเทศบาล Aglipay จังหวัด Quirino เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Pinaripad แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Pinaripad Barangay di Kotamadya Aglipay, Provinsi Quirino menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Pinaripad Nasional","ms":"Akta menukar status Sekolah Menengah Pinaripad Barangay di Perbandaran Aglipay, Wilayah Quirino kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Pinaripad Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 534","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00534_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00534_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15397-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Pinaripad Barangay High School in the Municipality of Aglipay, Province of Quirino, is\nconverted into a national high school to be known as the Pinaripad National High School."}},{"id":"PH-H15397-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education, Culture and Sports\nintended for new national high schools and an additional amount corresponding to fifty percent of its share in\nthe budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15397-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15398"] = {"id":"PH-H15398","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 535  An Act Converting the Siay Barangay High School in the Municipality of Siay, Province of Zamboanga Del Sur, Into a National High School to Be Known as the Siay National High School.","orig":"Batas Pambansa Blg. 535  An Act Converting the Siay Barangay High School in the Municipality of Siay, Province of Zamboanga Del Sur, Into a National High School to Be Known as the Siay National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Siay Barangay tại Thị trấn Siay, Tỉnh Zamboanga Del Sur thành Trường Trung học Quốc gia với tên gọi Trường Trung học Siay Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Siay Barangay ในเทศบาล Siay จังหวัด Zamboanga Del Sur เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Siay แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Siay Barangay di Kotamadya Siay, Provinsi Zamboanga Del Sur menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Siay Nasional","ms":"Akta menukar status Sekolah Menengah Siay Barangay di Perbandaran Siay, Wilayah Zamboanga Del Sur kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Siay Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 535","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00535_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00535_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15398-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Siay Barangay High School in the Municipality of Siay, Province of Zamboanga del Sur, is\nhereby converted into a national high school to be known as the Siay National High School."}},{"id":"PH-H15398-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15398-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15399"] = {"id":"PH-H15399","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 537  An Act Converting the Angadanan Vocational High School in the Municipality of Angadanan, Province of Isabela, Into An Agro-Industrial College to Be Known as the Angadanan Agro-Industrial College, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 537  An Act Converting the Angadanan Vocational High School in the Municipality of Angadanan, Province of Isabela, Into An Agro-Industrial College to Be Known as the Angadanan Agro-Industrial College, and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Dạy nghề Angadanan tại Thị trấn Angadanan, Tỉnh Isabela thành Cao đẳng Nông-công nghiệp với tên gọi Cao đẳng Nông-công nghiệp Angadanan","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษาอาชีวศึกษา Angadanan ในเทศบาล Angadanan จังหวัด Isabela เป็น วิทยาลัยเกษตรอุตสาหกรรมในชื่อวิทยาลัยเกษตรอุตสาหกรรม Angadanan","id":"Undang-Undang mengubah Sekolah Menengah Kejuruan Angadanan di Kotamadya Angadanan, Provinsi Isabela menjadi Sekolah Tinggi Agro-Industri dengan nama Sekolah Tinggi Agro-Industri Angadanan","ms":"Akta menukar status Sekolah Menengah Vokasional Angadanan di Perbandaran Angadanan, Wilayah Isabela kepada Kolej Agro-Industri dengan nama Kolej Agro-Industri Angadanan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 537","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00537_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00537_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15399-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Angadanan Vocational High School in the Municipality of Angadanan, Province of Isabela,\nis converted into an agro-industrial college to be known as the Angadanan Agro-Industrial College."}},{"id":"PH-H15399-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"All personnel, assets, liabilities, records and appropriations of the Angadanan Vocational High\nSchool are transferred to and absorbed by the Angadanan Agro-Industrial College."}},{"id":"PH-H15399-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The existing appropriations for the Angadanan Vocational High School are hereby transferred to\nthe Angadanan Agro-Industrial College, to be disbursed in accordance with the provisions of this Act.\nThereafter, the necessary amount required for the operation and maintenance of the college shall be provided\nfor in subsequent General Appropriations Acts, until which time the operation of the institution as a college\nshall be deferred, provided that its new name shall take effect upon approval of this Act."}},{"id":"PH-H15399-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15400"] = {"id":"PH-H15400","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 538  An Act Converting the Tandobanak Community High School in the Municipality of Sitangkai, Province of Tawi-Tawi, Into a National High School to Be Known as the Tandobanak National High School.","orig":"Batas Pambansa Blg. 538  An Act Converting the Tandobanak Community High School in the Municipality of Sitangkai, Province of Tawi-Tawi, Into a National High School to Be Known as the Tandobanak National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Tandobanak Community tại Thị trấn Sitangkai, Tỉnh Tawi-Tawi thành Trường Trung học Quốc gia với tên gọi Trường Trung học Tandobanak Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Tandobanak Community ในเทศบาล Sitangkai จังหวัด Tawi-Tawi เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Tandobanak แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Tandobanak Community di Kotamadya Sitangkai, Provinsi Tawi-Tawi menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Tandobanak Nasional","ms":"Akta menukar status Sekolah Menengah Tandobanak Community di Perbandaran Sitangkai, Wilayah Tawi-Tawi kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Tandobanak Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 538","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00538_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00538_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15400-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Tandobanak Community High School in the Municipality of Sitangkai, Province of\nTawi-Tawi, is converted into a national high school to be known as the Tandobanak National High School."}},{"id":"PH-H15400-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education, Culture and Sports\nintended for new national high schools and an additional amount corresponding to fifty per cent of its share in\nthe budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, the amount necessary for its operation and maintenance\nshall be included in the annual General Appropriations Act."}},{"id":"PH-H15400-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15401"] = {"id":"PH-H15401","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 539  An Act Converting the Piedad Barangay High School in the City of Davao Into a National High School to Be Known as the Doa Carmen Denia National High School.","orig":"Batas Pambansa Blg. 539  An Act Converting the Piedad Barangay High School in the City of Davao Into a National High School to Be Known as the Doa Carmen Denia National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Piedad Barangay tại Thành phố Davao thành Trường Trung học Quốc gia với tên gọi Trường Trung học Doa Carmen Denia Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Piedad Barangay ในเมือง Davao เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Doa Carmen Denia แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Piedad Barangay di Kota Davao menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Doa Carmen Denia Nasional","ms":"Akta menukar status Sekolah Menengah Piedad Barangay di Bandar Davao kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Doa Carmen Denia Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 539","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00539_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00539_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15401-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Piedad Barangay High School in the City of Davao is converted into a national high school\nto be known as the Doña Carmen Denia National High School."}},{"id":"PH-H15401-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15401-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15402"] = {"id":"PH-H15402","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 541  An Act Establishing a Ten-Bed Capacity Municipal Hospital in the Municipality of Barili Province of Cebu, to Be Known as the Barili Municipal Hospital.","orig":"Batas Pambansa Blg. 541  An Act Establishing a Ten-Bed Capacity Municipal Hospital in the Municipality of Barili Province of Cebu, to Be Known as the Barili Municipal Hospital."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 541","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00541_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00541_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15402-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed capacity municipal hospital in the Municipality of Barili, Province of Cebu, to be known as\nthe Barili Municipal Hospital."}},{"id":"PH-H15402-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Bilang\n230 for the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be\nnecessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15402-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15403"] = {"id":"PH-H15403","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 542  An Act Establishing a National Vocational High School in the City of Toledo to Be Known as the Toledo City National Vocational High School.","orig":"Batas Pambansa Blg. 542  An Act Establishing a National Vocational High School in the City of Toledo to Be Known as the Toledo City National Vocational High School.","vi":"Đạo luật thành lập Trường Trung học Dạy nghề Quốc gia tại Thành phố Toledo với tên gọi Trường Trung học Dạy nghề Toledo Thành phố Quốc gia","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาอาชีวศึกษาแห่งชาติในเมือง Toledo ในชื่อโรงเรียนมัธยมศึกษาอาชีวศึกษา Toledo เมืองแห่งชาติ","id":"Undang-Undang membentuk Sekolah Menengah Kejuruan Nasional di Kota Toledo dengan nama Sekolah Menengah Kejuruan Toledo Kota Nasional","ms":"Akta menubuhkan Sekolah Menengah Vokasional Kebangsaan di Bandar Toledo dengan nama Sekolah Menengah Vokasional Toledo Bandar Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 542","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00542_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00542_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15403-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established a vocational high school in the City of Toledo to be known as the\nToledo, City National Vocational High School."}},{"id":"PH-H15403-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Such sum as may be necessary for the operation and maintenance of said school shall be\nprovided in subsequent General Appropriations Acts until which time the operation of the institution as a\nnational high school shall be deferred."}},{"id":"PH-H15403-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15404"] = {"id":"PH-H15404","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 543  An Act Converting the Impig Barangay High School in the Municipality of Sipocot, Province of Camarines Sur, Into a National High School to Be Known as Impig National High School.","orig":"Batas Pambansa Blg. 543  An Act Converting the Impig Barangay High School in the Municipality of Sipocot, Province of Camarines Sur, Into a National High School to Be Known as Impig National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Impig Barangay tại Thị trấn Sipocot, Tỉnh Camarines Sur thành Trường Trung học Quốc gia với tên gọi Trường Trung học Impig Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Impig Barangay ในเทศบาล Sipocot จังหวัด Camarines Sur เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Impig แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Impig Barangay di Kotamadya Sipocot, Provinsi Camarines Sur menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Impig Nasional","ms":"Akta menukar status Sekolah Menengah Impig Barangay di Perbandaran Sipocot, Wilayah Camarines Sur kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Impig Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 543","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00543_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00543_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15404-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Impig Barangay High School in the Municipality of Sipocot, Province of Camarines Sur, is\nhereby converted into a national high school to be known as the Impig National High School."}},{"id":"PH-H15404-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15404-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15405"] = {"id":"PH-H15405","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 545  An Act Converting the La Carlota City High School in the City of La Carlota Into a National High School to Be Known as the Doa Hortencia Salas Benedicto National High School, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 545  An Act Converting the La Carlota City High School in the City of La Carlota Into a National High School to Be Known as the Doa Hortencia Salas Benedicto National High School, and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Thành phố La Carlota tại Thành phố La Carlota thành Trường Trung học Quốc gia với tên gọi Trường Trung học Doa Hortencia Salas Benedicto Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษาเมือง La Carlota ในเมือง La Carlota เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Doa Hortencia Salas Benedicto แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Kota La Carlota di Kota La Carlota menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Doa Hortencia Salas Benedicto Nasional","ms":"Akta menukar status Sekolah Menengah Bandar La Carlota di Bandar La Carlota kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Doa Hortencia Salas Benedicto Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 545","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00545_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00545_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15405-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The La Carlota City High School in the City of La Carlota is converted into a national high\nschool to be known as the Doña Hortencia Salas Benedicto National High School."}},{"id":"PH-H15405-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15405-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15406"] = {"id":"PH-H15406","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 546  An Act Creating Barangay Holy Spirit in Quezon City, Metropolitan Manila.","orig":"Batas Pambansa Blg. 546  An Act Creating Barangay Holy Spirit in Quezon City, Metropolitan Manila."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 546","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00546_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00546_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15406-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"A portion of Barangay Matandang Balara in Quezon City, Metropolitan Manila, is separated\ntherefrom and constituted into a new barangay to be known as Barangay High School."}},{"id":"PH-H15406-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The new barangay shall include the area which is bounded by the Republic Avenue on the north;\nby the Don Mariano Marcos Avenue on the east; by the Luzon Avenue on the west; and by the Don Antonio\nZuzuarregui Street on the south."}},{"id":"PH-H15406-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the areas\naffected within one hundred twenty days from the approval of this Act, the President of the Philippines shall\nappoint the first officials of the new barangay who shall hold office until their successors shall have been duly\nelected and qualified."}},{"id":"PH-H15406-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite herein provided, the\nexpenses for which shall be charged to local funds."}},{"id":"PH-H15406-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15407"] = {"id":"PH-H15407","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 547  An Act Converting the VIlla Jacinta Barangay High School in the Municipality of Macrohon, Province of Southern Leyte, Into a National Vocational High School to Be Known as the VIlla Jacinta National Vocational High School, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 547  An Act Converting the VIlla Jacinta Barangay High School in the Municipality of Macrohon, Province of Southern Leyte, Into a National Vocational High School to Be Known as the VIlla Jacinta National Vocational High School, and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học VIlla Jacinta Barangay tại Thị trấn Macrohon, Tỉnh Southern Leyte thành Trường Trung học Dạy nghề Quốc gia với tên gọi Trường Trung học Dạy nghề VIlla Jacinta Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา VIlla Jacinta Barangay ในเทศบาล Macrohon จังหวัด Southern Leyte เป็น โรงเรียนมัธยมศึกษาอาชีวศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษาอาชีวศึกษา VIlla Jacinta แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah VIlla Jacinta Barangay di Kotamadya Macrohon, Provinsi Southern Leyte menjadi Sekolah Menengah Kejuruan Nasional dengan nama Sekolah Menengah Kejuruan VIlla Jacinta Nasional","ms":"Akta menukar status Sekolah Menengah VIlla Jacinta Barangay di Perbandaran Macrohon, Wilayah Southern Leyte kepada Sekolah Menengah Vokasional Kebangsaan dengan nama Sekolah Menengah Vokasional VIlla Jacinta Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 547","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00547_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00547_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15407-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Villa Jacinta Barangay High School in the Municipality of Macrohon, Province of Southern\nLeyte, is hereby converted into a national vocational high school to be known as Villa Jacinta National\nVocational High School."}},{"id":"PH-H15407-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education, Culture and Sports\nintended for new national high schools and an additional amount corresponding to fifty percent of its share in\nthe budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15407-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15408"] = {"id":"PH-H15408","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 551  An Act Establishing a National High School in the Municipality of Kibungan, Province of Benguet, to Be Known as the Kibungan National High School, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 551  An Act Establishing a National High School in the Municipality of Kibungan, Province of Benguet, to Be Known as the Kibungan National High School, and Appropriating Funds therefor.","vi":"Đạo luật thành lập Trường Trung học Quốc gia tại Thị trấn Kibungan, Tỉnh Benguet với tên gọi Trường Trung học Kibungan Quốc gia","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาแห่งชาติในเทศบาล Kibungan จังหวัด Benguet ในชื่อโรงเรียนมัธยมศึกษา Kibungan แห่งชาติ","id":"Undang-Undang membentuk Sekolah Menengah Nasional di Kotamadya Kibungan, Provinsi Benguet dengan nama Sekolah Menengah Kibungan Nasional","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Perbandaran Kibungan, Wilayah Benguet dengan nama Sekolah Menengah Kibungan Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 551","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00551_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00551_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15408-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established in the Municipality of Kibungan, Province of Benguet, a national high\nschool to be known as the Kibungan National High School."}},{"id":"PH-H15408-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred fifty thousand pesos for the operation of the school shall be funded\nout of the appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education, Culture and\nSports intended for new national high schools and an additional amount corresponding to fifty percent of its\nshare in the budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, the amount needed for its operation and maintenance\nshall be included in the annual General Appropriations Act."}},{"id":"PH-H15408-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15409"] = {"id":"PH-H15409","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 553  An Act Converting the San Andres School of Fisheries and Forestry in the Municipality of San Andres, Province of Romblon, Into a College of Fisheries and Forestry, Integrating thereto Certain Secondary Schools in the Province and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 553  An Act Converting the San Andres School of Fisheries and Forestry in the Municipality of San Andres, Province of Romblon, Into a College of Fisheries and Forestry, Integrating thereto Certain Secondary Schools in the Province and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 553","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00553_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00553_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15409-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The San Andres School of Fisheries and Forestry in the Municipality of San Andres, Province of\nRomblon, is converted into a college to be known as the Romblon College of Fisheries and Forestry."}},{"id":"PH-H15409-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The following schools in the Province of Romblon are integrated into the College and shall\noperate as units or branches thereof:\nRomblon School of Fisheries and Concepcion Barangay High School, both in the Municipality of San\nSibuyan School of Fisheries in the Municipality of Cajidiocan;\nTanagan Barangay High School in the Municipality of San Andres;\nFerrol Barangay High School in the Municipality of Ferrol;\nSta. Fe Barangay High School in the Municipality of Sta. Fe; and\nCalatrava Barangay High School in the Municipality of Calatrava."}},{"id":"PH-H15409-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The College shall primarily provide professional and advanced vocational instruction in fisheries\nand forestry technology. It shall also promote research, advanced studies, and progressive leadership in its\nfield of specialization."}},{"id":"PH-H15409-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The College shall offer undergraduate and graduate courses and shall maintain a secondary\neducation program. It shall also offer short term vocational and technological courses."}},{"id":"PH-H15409-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"All personnel, assets, liabilities, records and appropriations of the San Andres School of\nFisheries and Forestry, the Sibuyan School of Fisheries, the Tanagan Barangay High School, the Ferrol\nBarangay High School, the Sta. Fe Barangay High School, the Calatrava Barangay High School and the\nConcepcion Barangay High School are transferred to/absorbed by the Romblon College of Fisheries and"}},{"id":"PH-H15409-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"All existing appropriations for the San Andres School of Fisheries and Forestry, the Sibuyan\nSchool of Fisheries, the Tanagan Barangay High School, the Ferrol Barangay High School, the Sta. Fe\nBarangay High School, the Calatrava Barangay High School and the Concepcion Barangay High School are\nhereby transferred to the Romblon College of Fisheries and Forestry to be disbursed in accordance with the\nprovisions of this Act. The necessary sum for the operation and maintenance of the state college shall be\nprovided for in subsequent General Appropriations Acts, until which time the operation of the institution as a\ncollege shall be deferred, provided that its new name shall take effect upon approval of this Act."}},{"id":"PH-H15409-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15410"] = {"id":"PH-H15410","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 554  Act An Changing the Name of the Nasunogan Elementary School in the Municipality of Ajuy, Province of Iloilo, to sto. Rosario Elementary School.","orig":"Batas Pambansa Blg. 554  Act An Changing the Name of the Nasunogan Elementary School in the Municipality of Ajuy, Province of Iloilo, to sto. Rosario Elementary School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 554","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00554_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00554_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15410-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Nasunogan Elementary School in the Municipality of Ajuy, Province of Iloilo,\nis changed to Sto. Rosario Elementary School."}},{"id":"PH-H15410-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15411"] = {"id":"PH-H15411","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 555  An Act Changing the Name of Kilogbog Elementary School in the Municipality of sta. Maria, Province of Davao Del Sur, to San Antonio Elementary","orig":"Batas Pambansa Blg. 555  An Act Changing the Name of Kilogbog Elementary School in the Municipality of sta. Maria, Province of Davao Del Sur, to San Antonio Elementary"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 555","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00555_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00555_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15411-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of Kilogbog Elementary School in the Municipality of Sta. Maria, Province of Davao\ndel Sur, is changed to San Antonio Elementary School."}},{"id":"PH-H15411-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15412"] = {"id":"PH-H15412","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 557  An Act Converting the Leonora S. Salapantan Municipal High School (Formerly San Miguel L. Salapantan Municipal High School) in the Municipality of San Miguel, Province of Iloilo, Into a National High School to Be Known as the Leonora S. Salapantan National High School.","orig":"Batas Pambansa Blg. 557  An Act Converting the Leonora S. Salapantan Municipal High School (Formerly San Miguel L. Salapantan Municipal High School) in the Municipality of San Miguel, Province of Iloilo, Into a National High School to Be Known as the Leonora S. Salapantan National High School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 557","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00557_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00557_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15412-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Leonora S. Salapantan Municipal High School in the Municipality of San Miguel, Province\nof Iloilo, is converted into a national high school to be known as the Leonora S. Salapantan National High"}},{"id":"PH-H15412-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education, Culture and Sports\nintended for new national high school and an additional amount corresponding to fifty percent of its share in\nthe budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15412-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15413"] = {"id":"PH-H15413","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 559  An Act Converting the Malitbog Barangay High School in the Municipality of Calinog, Province of Iloilo, Into a National High School to Be Known as the Malitbog National High School.","orig":"Batas Pambansa Blg. 559  An Act Converting the Malitbog Barangay High School in the Municipality of Calinog, Province of Iloilo, Into a National High School to Be Known as the Malitbog National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Malitbog Barangay tại Thị trấn Calinog, Tỉnh Iloilo thành Trường Trung học Quốc gia với tên gọi Trường Trung học Malitbog Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Malitbog Barangay ในเทศบาล Calinog จังหวัด Iloilo เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Malitbog แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Malitbog Barangay di Kotamadya Calinog, Provinsi Iloilo menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Malitbog Nasional","ms":"Akta menukar status Sekolah Menengah Malitbog Barangay di Perbandaran Calinog, Wilayah Iloilo kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Malitbog Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 559","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 6 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00559_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00559_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15413-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Malitbog Barangay High School in the Municipality of Calinog, Province of Iloilo, is\nhereby converted into a national high school to be known as the Malitbog National High School."}},{"id":"PH-H15413-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"A school curriculum which shall include academic, industrial arts, ceramics, electricity,\nhandicraft, and other allied courses shall be offered in the school."}},{"id":"PH-H15413-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The Minister of Education, Culture and Sports is hereby empowered to reorganize the said\nschool accordingly."}},{"id":"PH-H15413-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Upon reorganization of the school, the assets, liabilities, personnel, equipment and records of the\nold school shall be transferred to the Malitbog National High School."}},{"id":"PH-H15413-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15413-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15414"] = {"id":"PH-H15414","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 561  An Act Changing the Name of the Ungus Matata Elementary School in the Municipality of Tandubas, Province of Tawi-Tawi, to Hadji Abbas Jawad Elementary School.","orig":"Batas Pambansa Blg. 561  An Act Changing the Name of the Ungus Matata Elementary School in the Municipality of Tandubas, Province of Tawi-Tawi, to Hadji Abbas Jawad Elementary School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 561","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00561_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00561_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15414-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The the name of the Ungus Matata Elementary School in the Municipality of Tandubas,\nProvince of Tawi-Tawi, is hereby changed to Hadji Abbas Jawad Elementary School."}},{"id":"PH-H15414-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15415"] = {"id":"PH-H15415","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 563  An Act Converting the Bucal Barangay High School in the Municipality of Maragondon, Province of Cavite, Into a National High School to Be Known as the Bucal National High School.","orig":"Batas Pambansa Blg. 563  An Act Converting the Bucal Barangay High School in the Municipality of Maragondon, Province of Cavite, Into a National High School to Be Known as the Bucal National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Bucal Barangay tại Thị trấn Maragondon, Tỉnh Cavite thành Trường Trung học Quốc gia với tên gọi Trường Trung học Bucal Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Bucal Barangay ในเทศบาล Maragondon จังหวัด Cavite เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Bucal แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Bucal Barangay di Kotamadya Maragondon, Provinsi Cavite menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Bucal Nasional","ms":"Akta menukar status Sekolah Menengah Bucal Barangay di Perbandaran Maragondon, Wilayah Cavite kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Bucal Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 563","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00563_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00563_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15415-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Bucal Barangay High School in the Municipality of Maragondon, Province of Cavite, is\nconverted into a national high school to be known as the Bucal National High School."}},{"id":"PH-H15415-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education, Culture and Sports\nintended for new national high schools and an additional amount corresponding to fifty percent of its share in\nthe budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15415-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15416"] = {"id":"PH-H15416","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 567  An Act Changing the Name of the Manuk Mangkaw East Elementary School in the Municipality of Simunul, Province of Tawi-Tawi. to Hadji Imam Banjal Elementary School.","orig":"Batas Pambansa Blg. 567  An Act Changing the Name of the Manuk Mangkaw East Elementary School in the Municipality of Simunul, Province of Tawi-Tawi. to Hadji Imam Banjal Elementary School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 567","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00567_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00567_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15416-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Manuk Mangkaw East Elementary School in the Municipality of Simunul,\nProvince of Tawi-Tawi, is hereby changed to Hadji Imam Banjal Elementary School."}},{"id":"PH-H15416-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15417"] = {"id":"PH-H15417","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 571  An Act Increasing the Bed Capacity of the General Santos Emergency Hospital From Seventy-Five to One Hundred Beds.","orig":"Batas Pambansa Blg. 571  An Act Increasing the Bed Capacity of the General Santos Emergency Hospital From Seventy-Five to One Hundred Beds."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 571","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00571_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00571_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15417-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The bed capacity of the General Santos Emergency Hospital in the City of General Santos shall\nbe increased to one hundred beds."}},{"id":"PH-H15417-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15417-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15418"] = {"id":"PH-H15418","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 575  An Act Converting the Moscoso Rios Barangay High School in the Municipality of Hamtic, Province of Antique, Into a National High School to Be Known as the Governor VIllavert Jimenez National School.","orig":"Batas Pambansa Blg. 575  An Act Converting the Moscoso Rios Barangay High School in the Municipality of Hamtic, Province of Antique, Into a National High School to Be Known as the Governor VIllavert Jimenez National School.","vi":"Đạo luật chuyển đổi Trường Trung học Moscoso Rios Barangay tại Thị trấn Hamtic, Tỉnh Antique thành Trường Trung học Quốc gia với tên gọi Trường Governor VIllavert Jimenez Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Moscoso Rios Barangay ในเทศบาล Hamtic จังหวัด Antique เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียน Governor VIllavert Jimenez แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Moscoso Rios Barangay di Kotamadya Hamtic, Provinsi Antique menjadi Sekolah Menengah Nasional dengan nama Sekolah Governor VIllavert Jimenez Nasional","ms":"Akta menukar status Sekolah Menengah Moscoso Rios Barangay di Perbandaran Hamtic, Wilayah Antique kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Governor VIllavert Jimenez Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 575","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00575_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00575_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15418-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Moscoso Rios Barangay High School in the Municipality of Hamtic, Province of Antique, is\nconverted into a national high school to be known as the Governor Villavert Jimenez National School."}},{"id":"PH-H15418-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its shares of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15418-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15419"] = {"id":"PH-H15419","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 579  An Act Converting the Auitan Barangay High School in the Municipality of San Pablo, Province of Isabela, Into a Vocational and Industrial High School to Be Known as st. Paul Vocational and Industrial High School, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 579  An Act Converting the Auitan Barangay High School in the Municipality of San Pablo, Province of Isabela, Into a Vocational and Industrial High School to Be Known as st. Paul Vocational and Industrial High School, and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 579","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00579_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00579_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15419-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Auitan Barangay High School in the Municipality of San Pablo, Province of Isabela, is\nhereby converted into a vocational and industrial high school to be known as St. Paul Vocational and\nIndustrial High School."}},{"id":"PH-H15419-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation and maintenance of said school for the current fiscal year shall continue to be\nfunded out of local funds and from its share of national aid to local schools. The requirements for succeeding\nfiscal years shall be provided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15419-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15420"] = {"id":"PH-H15420","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 587  An Act Converting the General Trias Municipal High School and Two Barangay High Schools, All in the Municipality of General Trias, Province of Cavite, Into National High Schools, Integrating them Into One School to Be Known as the Governor Ferrer Memorial High School and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 587  An Act Converting the General Trias Municipal High School and Two Barangay High Schools, All in the Municipality of General Trias, Province of Cavite, Into National High Schools, Integrating them Into One School to Be Known as the Governor Ferrer Memorial High School and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 587","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00587_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00587_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15420-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The General Trias Municipal High School, the Buenavista Barangay High School and the\nBiclatan Barangay High School, all in the Municipality of General Trias, Province of Cavite, are converted\ninto national high schools."}},{"id":"PH-H15420-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The schools shall be integrated into one high school to be known as the Governor Ferrer\nMemorial High School, with the main campus at the present site of the General Trias Municipal High School."}},{"id":"PH-H15420-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The operations of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15420-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15421"] = {"id":"PH-H15421","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 588  An Act Converting the Bula Barangay High School in the Municipality of Bula, Province of Camarines Sur, Into a National High School to Be Known as the Bula National High School and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 588  An Act Converting the Bula Barangay High School in the Municipality of Bula, Province of Camarines Sur, Into a National High School to Be Known as the Bula National High School and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Bula Barangay tại Thị trấn Bula, Tỉnh Camarines Sur thành Trường Trung học Quốc gia với tên gọi Trường Trung học Bula Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Bula Barangay ในเทศบาล Bula จังหวัด Camarines Sur เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Bula แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Bula Barangay di Kotamadya Bula, Provinsi Camarines Sur menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Bula Nasional","ms":"Akta menukar status Sekolah Menengah Bula Barangay di Perbandaran Bula, Wilayah Camarines Sur kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Bula Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 588","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00588_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00588_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15421-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Bula Barangay High School in the Municipality of Bula, Province of Camarines Sur, is\nconverted into a national high school to be known as the Bula National High School."}},{"id":"PH-H15421-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15421-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15422"] = {"id":"PH-H15422","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 589  An Act Changing the Name of the Lookan Elementary School in the Municipality of Sapa-Sapa, Province of Tawi-Tawi, to Ladja E. Idanan Elementary","orig":"Batas Pambansa Blg. 589  An Act Changing the Name of the Lookan Elementary School in the Municipality of Sapa-Sapa, Province of Tawi-Tawi, to Ladja E. Idanan Elementary"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 589","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00589_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00589_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15422-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Lookan Elementary School in the Municipality of Sapa-Sapa, Province of\nTawi-Tawi, is hereby changed to Ladja E. Idanan Elementary School."}},{"id":"PH-H15422-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15423"] = {"id":"PH-H15423","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 590  An Act Establishing a National Agricultural School With the Kasibu Barangay High School as Its Nucleus in the Municipality of Kasibu, Province of Nueva VIscaya, to Be Known as the Kasibu National Agricultutral School and Providing Funds therefor.","orig":"Batas Pambansa Blg. 590  An Act Establishing a National Agricultural School With the Kasibu Barangay High School as Its Nucleus in the Municipality of Kasibu, Province of Nueva VIscaya, to Be Known as the Kasibu National Agricultutral School and Providing Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 590","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00590_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00590_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15423-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There is hereby established under the supervision of the Director of the Bureau of Secondary\nEducation a national agricultural school, with the Kasibu Barangay High School as its nucleus, in the\nMunicipality of Kasibu, Province of Nueva Viscaya, to be known as the Kasibu National Agricultural School."}},{"id":"PH-H15423-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"There shall be segregated from the Alloy Insular Reservation an area of twenty hectares for the\nschool site of the Kasibu National Agricultural School, to be determined by the Director of the Bureau of\nSecondary Education, in consultation with the Sangguniang Bayan of the Municipality of Kasibu, Province of\nNueva Viscaya."}},{"id":"PH-H15423-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The sum of one hundred fifty thousand pesos for the operation of the school shall be funded out\nof the appropriations authorized by Batas Pambansa Bilang 230 for the Ministry of Education, Culture and\nSports intended for new national schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15423-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15424"] = {"id":"PH-H15424","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 591  An Act Changing the Name of Bocaue Central School in the Municipality of Bocaue, Province of Bulacan, to Congressman Erasmo R. Cruz Memorial Central School.","orig":"Batas Pambansa Blg. 591  An Act Changing the Name of Bocaue Central School in the Municipality of Bocaue, Province of Bulacan, to Congressman Erasmo R. Cruz Memorial Central School."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 591","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00591_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00591_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15424-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Bocaue Central School established in the Municipality of Bocaue, Province of\nBulacan, is hereby changed to Congressman Erasmo R. Cruz Memorial Central School."}},{"id":"PH-H15424-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15425"] = {"id":"PH-H15425","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 592  An Act Converting the Naruangan Barangay High School in the Municipality of Tuao, Province of Cagayan, Into a National High School to Be Known as Tuao Vocational and Technical School, and Authorizing the Appropriation of Funds","orig":"Batas Pambansa Blg. 592  An Act Converting the Naruangan Barangay High School in the Municipality of Tuao, Province of Cagayan, Into a National High School to Be Known as Tuao Vocational and Technical School, and Authorizing the Appropriation of Funds","vi":"Đạo luật chuyển đổi Trường Trung học Naruangan Barangay tại Thị trấn Tuao, Tỉnh Cagayan thành Trường Trung học Quốc gia với tên gọi Trường Kỹ thuật Tuao Vocational","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Naruangan Barangay ในเทศบาล Tuao จังหวัด Cagayan เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนเทคนิค Tuao Vocational","id":"Undang-Undang mengubah Sekolah Menengah Naruangan Barangay di Kotamadya Tuao, Provinsi Cagayan menjadi Sekolah Menengah Nasional dengan nama Sekolah Teknik Tuao Vocational","ms":"Akta menukar status Sekolah Menengah Naruangan Barangay di Perbandaran Tuao, Wilayah Cagayan kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Teknikal Tuao Vocational"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 592","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00592_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00592_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15425-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Naruangan Barangay High School in the Municipality of Tuao, Province of Cagayan, is\nhereby converted into a national high school to be known as Tuao Vocational and Technical School."}},{"id":"PH-H15425-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15425-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15426"] = {"id":"PH-H15426","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 593  An Act Converting the Cabilauan Barangay High School in the Municipality of New Lucena, Province of Iloilo, Into a National High School to Be Known as the New Lucena National High School and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 593  An Act Converting the Cabilauan Barangay High School in the Municipality of New Lucena, Province of Iloilo, Into a National High School to Be Known as the New Lucena National High School and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 593","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00593_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00593_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15426-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Cabilauan Barangay High School in the Municipality of New Lucena, Province of Iloilo, is\nconverted into a national high school to be known as the New Lucena National High School."}},{"id":"PH-H15426-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15426-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15427"] = {"id":"PH-H15427","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 594  An Act Limiting the Collection of Contributions to the Assurance Fund Only Upon the Entry of a Certificate of Title in the Name of the Registered Owner and Upon the Original Registration on the Certificate of Title of a Building or Other Permanent Improvements on a Registered Land, Amending for the Purpose Certain Sections of the Property Registration Decree.","orig":"Batas Pambansa Blg. 594  An Act Limiting the Collection of Contributions to the Assurance Fund Only Upon the Entry of a Certificate of Title in the Name of the Registered Owner and Upon the Original Registration on the Certificate of Title of a Building or Other Permanent Improvements on a Registered Land, Amending for the Purpose Certain Sections of the Property Registration Decree."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 594","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00594_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00594_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15427-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Sections ninety-three and ninety-five of Presidential Decree Number Fifteen hundred and\ntwenty-nine, otherwise known as the Property Registration Decree, are hereby amended to read as follows:\n\"Sec. 93. Contribution to Assurance Fund. Upon the entry of a certificate of title in the name of the registered\nowner, and also upon the original registration on the certificate of title of a building or other improvements on\nthe land covered by said certificate, there shall be paid to the Register of Deeds one-fourth of one per cent of\nthe assessed value of the real estate on the basis of the last assessment for taxation purposes, as contribution to\nthe Assurance Fund. Where the land involved has not yet been assessed for taxation, its value for purposes of\nthis Decree shall be determined by the sworn declaration of two disinterested persons to the effect that the\nvalue fixed by them is to their knowledge, a fair valuation.\n\"Nothing in this Section shall in any way preclude the court from increasing the valuation of the property\nshould it appear during the hearing that the value stated is too small.\"\n\"Sec. 95. Action for compensation from funds. A person who, without negligence on his part, sustains loss or\ndamages, or is deprived of land or any estate or interest therein in consequence of the bringing of the land\nunder the operation of the Torrens system or arising after original registration of land, through fraud or in\nconsequence of any error, omission, mistake or misdescription in any certificate of title, and who by the\nprovisions of this Decree is barred or otherwise precluded under the provision of any law from bringing an\naction for the recovery of such land or estate or interest therein, may bring an action in any court of competent\njurisdiction for the recovery of damage to be paid out of the Assurance Fund.\""}}],"pack":"ph-p156"};
  FT["PH-H15428"] = {"id":"PH-H15428","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 595  An Act Converting the Lalawigan Municipal High School in the Municipality of Borongan, Eastern Samar, Into a National High School to Be Known as the Lalawigan National High School and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 595  An Act Converting the Lalawigan Municipal High School in the Municipality of Borongan, Eastern Samar, Into a National High School to Be Known as the Lalawigan National High School and Authorizing the Appropriation of Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Lalawigan Đô thị tại Thị trấn Borongan, Tỉnh Eastern Samar thành Trường Trung học Quốc gia với tên gọi Trường Trung học Lalawigan Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Lalawigan เทศบาลในเทศบาล Borongan จังหวัด Eastern Samar เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Lalawigan แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Lalawigan Kotamadya di Kotamadya Borongan, Provinsi Eastern Samar menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Lalawigan Nasional","ms":"Akta menukar status Sekolah Menengah Lalawigan Perbandaran di Perbandaran Borongan, Wilayah Eastern Samar kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Lalawigan Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 595","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00595_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00595_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15428-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Lalawigan Municipal High School in Barangay Lalawigan, Borongan, Eastern Samar, is\nhereby converted into a national high school to be known as the Lalawigan National High School."}},{"id":"PH-H15428-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15428-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15429"] = {"id":"PH-H15429","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 596  An Act Converting Caraga Municipal High School in the Municipality of Caraga, Province of Davao Oriental Into a National High School to Be Known as the Caraga National High School.","orig":"Batas Pambansa Blg. 596  An Act Converting Caraga Municipal High School in the Municipality of Caraga, Province of Davao Oriental Into a National High School to Be Known as the Caraga National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Caraga Đô thị tại Thị trấn Caraga, Tỉnh Davao Oriental thành Trường Trung học Quốc gia với tên gọi Trường Trung học Caraga Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Caraga เทศบาลในเทศบาล Caraga จังหวัด Davao Oriental เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Caraga แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Caraga Kotamadya di Kotamadya Caraga, Provinsi Davao Oriental menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Caraga Nasional","ms":"Akta menukar status Sekolah Menengah Caraga Perbandaran di Perbandaran Caraga, Wilayah Davao Oriental kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Caraga Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 596","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00596_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00596_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15429-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Caraga Municipal High School in the Municipality of Caraga, Province of Davao Oriental,\nis converted into a national high school to be known as the Caraga National High School."}},{"id":"PH-H15429-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education, Culture and Sports\nintended for new national high schools and an additional amount corresponding to fifty percent of its share in\nthe budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15429-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15430"] = {"id":"PH-H15430","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 597  An Act Establishing a Municipal Hospital in the Municipality of Bucay, Province of Abra, to Be Known as the Bucay Municipal Hospital.","orig":"Batas Pambansa Blg. 597  An Act Establishing a Municipal Hospital in the Municipality of Bucay, Province of Abra, to Be Known as the Bucay Municipal Hospital.","vi":"Đạo luật thành lập Bệnh viện Đô thị tại Thị trấn Bucay, Tỉnh Abra với tên gọi Bệnh viện Bucay Đô thị","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาลในเทศบาล Bucay จังหวัด Abra ในชื่อโรงพยาบาล Bucay เทศบาล","id":"Undang-Undang membentuk Rumah Sakit Kotamadya di Kotamadya Bucay, Provinsi Abra dengan nama Rumah Sakit Bucay Kotamadya","ms":"Akta menubuhkan Hospital Perbandaran di Perbandaran Bucay, Wilayah Abra dengan nama Hospital Bucay Perbandaran"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 597","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00597_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00597_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15430-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established a ten-bed municipal hospital in the Municipality of Bucay, Province of\nAbra, to be known as Bucay Municipal Hospital."}},{"id":"PH-H15430-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15430-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15431"] = {"id":"PH-H15431","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 598  An Act Establishing a National High School in the Municipality of San Isidro, Province of Isabela, to Be Known as the San Isidro National High School, Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 598  An Act Establishing a National High School in the Municipality of San Isidro, Province of Isabela, to Be Known as the San Isidro National High School, Appropriating Funds therefor.","vi":"Đạo luật thành lập Trường Trung học Quốc gia tại Thị trấn San Isidro, Tỉnh Isabela với tên gọi Trường Trung học San Isidro Quốc gia","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาแห่งชาติในเทศบาล San Isidro จังหวัด Isabela ในชื่อโรงเรียนมัธยมศึกษา San Isidro แห่งชาติ","id":"Undang-Undang membentuk Sekolah Menengah Nasional di Kotamadya San Isidro, Provinsi Isabela dengan nama Sekolah Menengah San Isidro Nasional","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Perbandaran San Isidro, Wilayah Isabela dengan nama Sekolah Menengah San Isidro Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 598","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00598_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00598_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15431-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There is established a national high school in the Municipality of San Isidro, Province of Isabela,\nto be known as the San Isidro National High School."}},{"id":"PH-H15431-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Such sum as may be necessary for the operation and maintenance of said school shall be\nprovided in subsequent General Appropriations Acts until which time the operation of the institution as a\nnational high school shall be deferred."}},{"id":"PH-H15431-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15432"] = {"id":"PH-H15432","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 599  An Act Converting the Trece Martires City High School in the City of Trece Martires Into a National High School, to Be Known as the Trece Martires City National High School, and Providing Funds therefor.","orig":"Batas Pambansa Blg. 599  An Act Converting the Trece Martires City High School in the City of Trece Martires Into a National High School, to Be Known as the Trece Martires City National High School, and Providing Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Thành phố Trece Martires tại Thành phố Trece Martires thành Trường Trung học Quốc gia với tên gọi Trường Trung học Trece Martires Thành phố Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษาเมือง Trece Martires ในเมือง Trece Martires เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Trece Martires เมืองแห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Kota Trece Martires di Kota Trece Martires menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Trece Martires Kota Nasional","ms":"Akta menukar status Sekolah Menengah Bandar Trece Martires di Bandar Trece Martires kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Trece Martires Bandar Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 599","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00599_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00599_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15432-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Trece Martires City High School in the City of Trece Martires is hereby converted into a\nnational high school, to be known as the Trece Martires City National High School."}},{"id":"PH-H15432-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operations of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15432-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15433"] = {"id":"PH-H15433","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 600  An Act Converting the Buayan Barangay High School in the Municipality of Kabasalan, Province of Zamboanga Into a National High School to Be Known as the Buayan National High School and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 600  An Act Converting the Buayan Barangay High School in the Municipality of Kabasalan, Province of Zamboanga Into a National High School to Be Known as the Buayan National High School and Appropriating Funds therefor.","vi":"Đạo luật chuyển đổi Trường Trung học Buayan Barangay tại Thị trấn Kabasalan, Tỉnh Zamboanga thành Trường Trung học Quốc gia với tên gọi Trường Trung học Buayan Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Buayan Barangay ในเทศบาล Kabasalan จังหวัด Zamboanga เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Buayan แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Buayan Barangay di Kotamadya Kabasalan, Provinsi Zamboanga menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Buayan Nasional","ms":"Akta menukar status Sekolah Menengah Buayan Barangay di Perbandaran Kabasalan, Wilayah Zamboanga kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Buayan Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 600","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00600_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00600_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15433-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Buayan Barangay High School in the Municipality of Kabasalan, Province of Zamboanga\ndel Sur, is converted into a national high school to be known as the Buayan National High School."}},{"id":"PH-H15433-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15433-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15434"] = {"id":"PH-H15434","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 601  An Act Converting the Anislag Barangay High School in the Municipality of Daraga, Province of Albay, Into a National High School to Be Known as the Anislag National High School.","orig":"Batas Pambansa Blg. 601  An Act Converting the Anislag Barangay High School in the Municipality of Daraga, Province of Albay, Into a National High School to Be Known as the Anislag National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Anislag Barangay tại Thị trấn Daraga, Tỉnh Albay thành Trường Trung học Quốc gia với tên gọi Trường Trung học Anislag Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Anislag Barangay ในเทศบาล Daraga จังหวัด Albay เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Anislag แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Anislag Barangay di Kotamadya Daraga, Provinsi Albay menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Anislag Nasional","ms":"Akta menukar status Sekolah Menengah Anislag Barangay di Perbandaran Daraga, Wilayah Albay kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Anislag Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 601","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00601_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00601_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15434-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Anislag Barangay High School in the Municipality of Daraga, Province of Albay, is hereby\nconverted into a national high school to be known as the Anislag National High School."}},{"id":"PH-H15434-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education, Culture and Sports\nintended for new national high schools and an additional amount corresponding to fifty percent of its share in\nthe budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15434-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15435"] = {"id":"PH-H15435","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 602  An Act Changing the Name of Barangay Ventinilla East in the Municipality of sta. Barbara, Province of Pangasinan, to Barangay Primicias.","orig":"Batas Pambansa Blg. 602  An Act Changing the Name of Barangay Ventinilla East in the Municipality of sta. Barbara, Province of Pangasinan, to Barangay Primicias."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 602","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00602_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00602_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15435-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of Barangay Ventinilla East in the Municipality of Sta. Barbara, Province of\nPangasinan, is changed to Barangay Primicias."}},{"id":"PH-H15435-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15436"] = {"id":"PH-H15436","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 603  An Act Converting Rizal Municipal High School Situated in the Municipality of Rizal, Province of Occidental Mindoro, Into a National High School to Be Known as Rizal National High School.","orig":"Batas Pambansa Blg. 603  An Act Converting Rizal Municipal High School Situated in the Municipality of Rizal, Province of Occidental Mindoro, Into a National High School to Be Known as Rizal National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Rizal Đô thị tại Thị trấn Rizal, Tỉnh Occidental Mindoro thành Trường Trung học Quốc gia với tên gọi Trường Trung học Rizal Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Rizal เทศบาลในเทศบาล Rizal จังหวัด Occidental Mindoro เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Rizal แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Rizal Kotamadya di Kotamadya Rizal, Provinsi Occidental Mindoro menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Rizal Nasional","ms":"Akta menukar status Sekolah Menengah Rizal Perbandaran di Perbandaran Rizal, Wilayah Occidental Mindoro kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Rizal Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 603","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00603_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00603_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15436-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Rizal Municipal High School situated in the Municipality of Rizal, Province of Occidental\nMindoro, is hereby converted into a national high school to be known as Rizal National High School."}},{"id":"PH-H15436-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Ministry of Education, Culture and Sports is hereby directed to take steps as are necessary\nfor the conversion, operation and immediate implementation of this Act."}},{"id":"PH-H15436-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The amount of one hundred thousand pesos for the operation of the school shall be funded out of\nthe appropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Education, Culture and Sports\nintended for new national high schools and an additional amount corresponding to fifty percent of its share in\nthe budgetary aid actually paid to it before such conversion shall be released for its operation from the\nnational assistance fund to local schools. Thereafter, such sum as may be necessary for its operation and\nmaintenance shall be provided in the annual General Appropriations Act."}},{"id":"PH-H15436-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
