  FT["PH-H15465"] = {"id":"PH-H15465","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 632  An Act Establishing a Municipal Hospital in Barangay Pamarawan in the Municipality of Malolos, Province of Bulacan, to Be Known as the Dr. Felix T. Reyes Memorial Hospital.","orig":"Batas Pambansa Blg. 632  An Act Establishing a Municipal Hospital in Barangay Pamarawan in the Municipality of Malolos, Province of Bulacan, to Be Known as the Dr. Felix T. Reyes Memorial Hospital."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 632","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00632_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00632_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15465-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed municipal hospital in Barangay Pamarawan, in the Municipality of Malolos, Province of\nBulacan, to be known as Dr. Felix T. Reyes Memorial Hospital."}},{"id":"PH-H15465-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15465-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15466"] = {"id":"PH-H15466","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 633  An Act Establishing a Municipal Hospital in Barangay VIllahermosa, Municipality of Rapu-Rapu, Province of Albay to Be Known as the VIllahermosa Municipal Hospital.","orig":"Batas Pambansa Blg. 633  An Act Establishing a Municipal Hospital in Barangay VIllahermosa, Municipality of Rapu-Rapu, Province of Albay to Be Known as the VIllahermosa Municipal Hospital.","vi":"Đạo luật thành lập Bệnh viện Đô thị tại Barangay VIllahermosa, Thị trấn Rapu-Rapu, Tỉnh Albay với tên gọi Bệnh viện VIllahermosa Đô thị","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาลในบารังไกย์ VIllahermosa เทศบาล Rapu-Rapu จังหวัด Albay ในชื่อโรงพยาบาล VIllahermosa เทศบาล","id":"Undang-Undang membentuk Rumah Sakit Kotamadya di Barangay VIllahermosa, Kotamadya Rapu-Rapu, Provinsi Albay dengan nama Rumah Sakit VIllahermosa Kotamadya","ms":"Akta menubuhkan Hospital Perbandaran di Barangay VIllahermosa, Perbandaran Rapu-Rapu, Wilayah Albay dengan nama Hospital VIllahermosa Perbandaran"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 633","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00633_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00633_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15466-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed municipal hospital in Barangay Villahermosa, Municipality of Rapu-Rapu, Province of\nAlbay, to be known as the Villahermosa Municipal Hospital."}},{"id":"PH-H15466-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15466-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15467"] = {"id":"PH-H15467","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":8,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 634  An Act Converting the Ifugao School of Arts and Trades in the Municipality of Lagawe, Province of Ifugao, Into a College to Be Known as the Ifugao College of Arts and Trades.","orig":"Batas Pambansa Blg. 634  An Act Converting the Ifugao School of Arts and Trades in the Municipality of Lagawe, Province of Ifugao, Into a College to Be Known as the Ifugao College of Arts and Trades.","vi":"Đạo luật chuyển đổi Trường Nghệ thuật và Thương mại Ifugao tại Thị trấn Lagawe, Tỉnh Ifugao thành Cao đẳng với tên gọi Cao đẳng Nghệ thuật và Thương mại Ifugao","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนศิลปะและหัตถกรรม Ifugao ในเทศบาล Lagawe จังหวัด Ifugao เป็น วิทยาลัยในชื่อวิทยาลัยศิลปะและหัตถกรรม Ifugao","id":"Undang-Undang mengubah Sekolah Seni dan Keterampilan Ifugao di Kotamadya Lagawe, Provinsi Ifugao menjadi Sekolah Tinggi dengan nama Sekolah Tinggi Seni dan Keterampilan Ifugao","ms":"Akta menukar status Sekolah Seni dan Pertukangan Ifugao di Perbandaran Lagawe, Wilayah Ifugao kepada Kolej dengan nama Kolej Seni dan Pertukangan Ifugao"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 634","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 8 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00634_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00634_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15467-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Ifugao School of Arts and Trades in the Municipality of Lagawe, Province of Ifugao, is\nconverted into a college to be known as the Ifugao College of Arts and Trades."}},{"id":"PH-H15467-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The College shall offer in addition to its secondary and technical trade curricula, any or all of the\nfollowing collegiate courses at the discretion of the Ministry of Education, Culture and Sports:\n(a) Four-year business education course leading to the degree of Bachelor of Science in Business Education as\nwell as the masteral degree thereof;\n(b) Four-year industrial arts course leading to the degree of Bachelor of Science in Industrial Arts as well as\nthe masteral degree thereof;\n(c) Four-year technical fishery course leading to the degree of Bachelor of Science in Fisheries;\n(d) Two-year business education course leading to the title of Associate in Business Education; and\n(e) Two year commerce course leading to the title of Associate in Commerce."}},{"id":"PH-H15467-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The purpose of the College is to provide higher profession and technical instruction and training\nin technology and the applied arts and sciences and to promote research, advanced studies and progressive\nleadership in these fields."}},{"id":"PH-H15467-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Ministry of Education, Culture and Sports is empowered to reorganize the school and is\nfurther authorized to prescribe such other courses it may deem necessary in the pursuance of the aims and\npurposes of the College."}},{"id":"PH-H15467-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The College shall be headed by a President who shall be appointed by the President of the\nPhilippines upon recommendation of the Minister of Education, Culture and Sports who shall have\nsupervision and administration over the College. The powers, duties and remuneration of the President of the\nCollege shall be the same as those of heads of similar colleges and embodied in circulars issued by the\nMinistry of Education, Culture and Sports."}},{"id":"PH-H15467-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"The College shall not deny admission to any student by reason of sex, ethnic consideration,\nreligious belief or affiliation."}},{"id":"PH-H15467-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"The existing appropriations for the Ifugao School of Arts and Trades are hereby transferred to\nthe Ifugao College of Arts and Trades to be disbursed in accordance with the provisions of this Act.\nThereafter, the necessary amount required for the operation and maintenance of the new college shall be\nprovided for in subsequent General Appropriations Acts, until which time the operation of the institution as a\ncollege shall be deferred, provided that its new name shall take effect upon approval of this Act."}},{"id":"PH-H15467-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15468"] = {"id":"PH-H15468","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 635  An Act Establishing a Municipal Hospital in the Municipality of Candelaria, Province of Quezon, to Be Known as the Candelaria Municipal Hospital, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 635  An Act Establishing a Municipal Hospital in the Municipality of Candelaria, Province of Quezon, to Be Known as the Candelaria Municipal Hospital, and Appropriating Funds therefor.","vi":"Đạo luật thành lập Bệnh viện Đô thị tại Thị trấn Candelaria, Tỉnh Quezon với tên gọi Bệnh viện Candelaria Đô thị","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาลในเทศบาล Candelaria จังหวัด Quezon ในชื่อโรงพยาบาล Candelaria เทศบาล","id":"Undang-Undang membentuk Rumah Sakit Kotamadya di Kotamadya Candelaria, Provinsi Quezon dengan nama Rumah Sakit Candelaria Kotamadya","ms":"Akta menubuhkan Hospital Perbandaran di Perbandaran Candelaria, Wilayah Quezon dengan nama Hospital Candelaria Perbandaran"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 635","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00635_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00635_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15468-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established a ten-bed municipal hospital in the Municipality of Candelaria,\nProvince of Quezon, to be known as the Candelaria Municipal Hospital."}},{"id":"PH-H15468-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15468-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15469"] = {"id":"PH-H15469","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 636  An Act Converting the Tarlac Provincial High School in the Municipality of Tarlac, Province of Tarlac, Into a National High School to Be Known as the Tarlac National High School.","orig":"Batas Pambansa Blg. 636  An Act Converting the Tarlac Provincial High School in the Municipality of Tarlac, Province of Tarlac, Into a National High School to Be Known as the Tarlac National High School.","vi":"Đạo luật chuyển đổi Trường Trung học Tarlac Tỉnh tại Thị trấn Tarlac, Tỉnh Tarlac thành Trường Trung học Quốc gia với tên gọi Trường Trung học Tarlac Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Tarlac จังหวัดในเทศบาล Tarlac จังหวัด Tarlac เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Tarlac แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Tarlac Provinsi di Kotamadya Tarlac, Provinsi Tarlac menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Tarlac Nasional","ms":"Akta menukar status Sekolah Menengah Tarlac Wilayah di Perbandaran Tarlac, Wilayah Tarlac kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Tarlac Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 636","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00636_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00636_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15469-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Tarlac Provincial High School in the Municipality of Tarlac, Province of Tarlac, is\nconverted into a national high school to be known as the Tarlac National High School."}},{"id":"PH-H15469-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Tarlac National High School shall continue to be operated and maintained by the provincial\ngovernment and from its share in the funds provided as budgetary assistance to local schools until such time\nas funds for its operation and maintenance as a national high school shall have been included in the annual\nGeneral Appropriations Act."}},{"id":"PH-H15469-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15470"] = {"id":"PH-H15470","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 637  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of Culaba, Sub-Province of Biliran, Province of Leyte, to Be Known as Culaba Community Hospital, and Authorizing the Appropriation of Funds therefor.","orig":"Batas Pambansa Blg. 637  An Act Establishing a Municipal Hospital With a Ten-Bed Capacity and Secondary Level Capability in the Municipality of Culaba, Sub-Province of Biliran, Province of Leyte, to Be Known as Culaba Community Hospital, and Authorizing the Appropriation of Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 637","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-24","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00637_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00637_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15470-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed municipal hospital in the Municipality of Culaba, Sub-province of Biliran, Province of\nLeyte, to be known as the Culaba Community Hospital."}},{"id":"PH-H15470-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15470-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15471"] = {"id":"PH-H15471","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 638  An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Valderama Province of Antique, to Be Known as the Valderama Municipal Hospital, and Appropriating Funds therefor.","orig":"Batas Pambansa Blg. 638  An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Valderama Province of Antique, to Be Known as the Valderama Municipal Hospital, and Appropriating Funds therefor."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 638","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00638_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00638_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15471-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There shall be established, under the direct supervision of the Office of the Minister, Ministry of\nHealth, a ten-bed municipal hospital in the Municipality of Valderama, Province of Antique, to be known as\nthe Valderama Municipal Hospital."}},{"id":"PH-H15471-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the construction and operation of the hospital not to exceed seven\nhundred fifty thousand pesos shall be funded out of the appropriations authorized by Batas Pambansa Blg. 230\nfor the Ministry of Health intended for new or expanded hospitals. Thereafter, such sum as may be necessary\nfor its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H15471-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15472"] = {"id":"PH-H15472","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 639  An Act Converting the Dr. Ramon De Santos Barangay High School in the Municipality of Cuyapo, Province of Nueva Ecija, Into a National High School to Be Known as the Dr. Ramon De Santos National High School and Appropriating Funds","orig":"Batas Pambansa Blg. 639  An Act Converting the Dr. Ramon De Santos Barangay High School in the Municipality of Cuyapo, Province of Nueva Ecija, Into a National High School to Be Known as the Dr. Ramon De Santos National High School and Appropriating Funds","vi":"Đạo luật chuyển đổi Trường Trung học Dr. Ramon De Santos Barangay tại Thị trấn Cuyapo, Tỉnh Nueva Ecija thành Trường Trung học Quốc gia với tên gọi Trường Trung học Dr. Ramon De Santos Quốc gia","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษา Dr. Ramon De Santos Barangay ในเทศบาล Cuyapo จังหวัด Nueva Ecija เป็น โรงเรียนมัธยมศึกษาแห่งชาติในชื่อโรงเรียนมัธยมศึกษา Dr. Ramon De Santos แห่งชาติ","id":"Undang-Undang mengubah Sekolah Menengah Dr. Ramon De Santos Barangay di Kotamadya Cuyapo, Provinsi Nueva Ecija menjadi Sekolah Menengah Nasional dengan nama Sekolah Menengah Dr. Ramon De Santos Nasional","ms":"Akta menukar status Sekolah Menengah Dr. Ramon De Santos Barangay di Perbandaran Cuyapo, Wilayah Nueva Ecija kepada Sekolah Menengah Kebangsaan dengan nama Sekolah Menengah Dr. Ramon De Santos Kebangsaan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 639","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-06-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00639_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00639_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15472-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Dr. Ramon de Santos Barangay High School in the Municipality of Cuyapo, Province of\nNueva Ecija, is converted into a national high school to be known as the Dr. Ramon de Santos National High"}},{"id":"PH-H15472-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The operation of said school for the current fiscal year shall continue to be funded out of local\nfunds and from its share of national aid to local schools. The requirements for succeeding fiscal years shall be\nprovided in the forthcoming General Appropriations Acts."}},{"id":"PH-H15472-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15473"] = {"id":"PH-H15473","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":42,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 640  An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines From January One to December thirty-One, Nineteen Hundred and Eighty-Four and for Other Purposes","orig":"Batas Pambansa Blg. 640  An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines From January One to December thirty-One, Nineteen Hundred and Eighty-Four and for Other Purposes"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 640","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-09-14","completenessNote":"全文，共 42 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00640_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00640_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15473-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Appropriation of funds. The following sums, or so much thereof as may be necessary, are hereby\nappropriated out of any funds in the National Treasury of the Philippines not otherwise appropriated, for the\noperation of the Government of the Republic of the Philippines from January one to December thirty-one,\nnineteen hundred and eighty-four except where otherwise specifically provided herein:\n[For the sake of brevity, the itemization under this Section of the funds appropriated for the operation of the\nGovernment had been deleted. Please refer to the unabridged version of the pertinent General Appropriations\nAct for the details.]\nGeneral Provisions\nRECEIPTS AND INCOME"}},{"id":"PH-H15473-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Fees, Charges and Assessments. All fees, charges, assessments and other receipts or revenues\ncollected by ministries, bureaus, offices or agencies in the exercise of their functions, at such rates as are now\nor may be approved by the Minister concerned, shall be deposited with the National Treasury and shall accrue\nto the General Fund pursuant to Section 50 of P.D. No. 1177 and Section 3 of B.P. Blg. 325: Provided, That\ncertain receipts may be recorded as income of a Special Fund, a Fiduciary or a Trust Fund, or a fund other\nthan the General Fund, when authorized by law and following such rules and regulations as may be issued by\nthe Permanent Committee created under Section 51 of P.D. No. 1177: Provided, further, That all revenues or\nincome accruing to special accounts in the General Fund may be made available for expenditures subject to\nthe Special Provisions in this Act for the agencies concerned and to Special Budgets required under Section 40\nof P.D. No. 1177: and Provided, finally, That whenever practicable and taking into account the cost reduction\nprogram of the government when an agency arranges with another government office for fabrication of\nfurniture or equipment, or for computer, printing or other services, the agency rendering such services may\nassess the requesting agency for the cost of production and services rendered and may utilize the said proceeds\nsubject to Sec. 40 of P.D. No. 1177, except as otherwise provided in this Act."}},{"id":"PH-H15473-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Revolving Fund. Receipts derived from business-type activities of ministries, bureaus, offices, or\nagencies which are authorized by law or by the Special Provisions in this Act to be constituted into a\nRevolving Fund shall be separately recorded and deposited in an authorized government depository bank,\nexcept as may otherwise be determined by the Permanent Committee created under Sec. 51 of P.D. No. 1177,\nand may be made available for operational expenses of the said activity of the agency concerned, subject to\nthe conditions prescribed under the Special Provisions of the agency concerned and the rules and regulations\nas may be prescribed by the aforementioned Permanent Committee. The Revolving Fund shall be considered\nself-perpetuating and self-liquidating and all obligations or expenditures incurred by virtue of said\nbusiness-type activities shall be charged against the Revolving Fund: Provided, That interest earned shall\naccrue to and form part of the Revolving Fund to be issued for the same purpose for which the fund is\nauthorized.\nThe Agency concerned shall submit to the Office of Budget and Management a monthly report of the income\n\nfrom the Fund and a quarterly report of expenditure. In case of failure to submit said requirements, the Office\nof Budget and Management shall order the suspension of all transactions on this account until such time that\nsaid requirements are complied with."}},{"id":"PH-H15473-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Trust Receipts. Receipts from non-tax sources authorized by law for specific purposes which are\ncollected/received by a government office or agency acting as a trustee, agent or administrator, or which have\nbeen received as guaranty for the fulfillment of an obligation, and all other collections classified by law or\nregulations as trust receipts shall be treated as a trust liability of the agency concerned and deposited in an\nauthorized government depository bank or in the National Treasury, as the case may be, subject to the\nconditions prescribed under the Special Provisions of the agency concerned and to the rules and regulations as\ndetermined by the Permanent Committee created under Section 51 of P.D. No. 1177: Provided, That deposits\nin authorized government depository banks shall be withdrawable on the joint signatures of the authorized\nrepresentatives of the agency and the Commission on Audit without the needs of Special Budget or the\nissuance of a Cash Disbursement Ceiling: Provided, further, That if the amount is deposited in a savings\naccount, the interest shall accrue to the General Fund which shall be remitted to the National Treasury at the\nend of each quarter."}},{"id":"PH-H15473-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Seminar and Conference Fee. Ministries, bureaus, offices or agencies which conduct training\nprograms approved jointly by the Office of Budget and Management and the Civil Service Commission are\nauthorized to collect seminar and conference fees from government and private agency participants, the rates\nof which shall be determined in accordance with Letter of Instructions No. 565. The proceeds derived from\nsuch seminars or conferences may be deposited in an authorized government depository bank as a trust\nliability and shall be made available for expenditure without the need for a Cash Disbursement Ceiling, to\ndefray the costs incurred for handouts, meals and other incidental expenses, including speakers’ honoraria at\nrates prescribed pursuant to P.D. No. 985, but not for entertainment or representation expenses, withdrawable\non the joint signatures of the authorized representatives of the agency concerned and the Commission on\nAudit: Provided, That if the income is deposited in a savings or time deposit account, the interest thereof shall\naccrue to the General Fund and shall be remitted to the National Treasury at the end of each quarter: Provided,\nfurther, That no appropriations authorized in this Act shall be used to support or augment expenses of\nseminars or conferences for which fees are collected: and Provided, finally, That any income remaining in the\nbank account at the end of the fiscal year shall be withdrawn and deposited with the National Treasury as\nincome of the General Fund. The Office of Budget and Management and the Commission on Audit shall\npromulgate the necessary rules and regulations to implement this provision.\nMinistries, bureaus, offices or agencies concerned shall submit to the Office of Budget and Management a\nmonthly report of collections and deposits and quarterly report of expenditures and financial status of its\ntraining operations, and in case of failure to submit said requirements, the Office of Budget and Management\nshall order the suspension of all withdrawals from the funds deposited until such time that said requirements\nare complied with."}},{"id":"PH-H15473-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Sale of Products. Ministries, bureaus, offices or agencies are authorized to sell products of\nagricultural, industrial or other projects, including official publications, and the proceeds derived therefrom\nshall be deposited with the National Treasury and accrue to the General Fund, pursuant to Section 50 of P.D.\nNo. 1177, unless otherwise provided by law or authorized by Special Provision in this Act."}},{"id":"PH-H15473-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Donations. Ministries, bureaus, offices, or agencies are authorized to accept donations,\ncontributions, grants bequests or gifts, in cash or in kind from foreign governments, international agencies,\nprivate entities or individuals for purposes relevant to their functions. Cash proceeds shall be deposited with\nthe National Treasury as a Special Account in the General Fund and shall be used or expended only in\naccordance with the wishes of, and purposes specified by the benefactor or donor, subject to Section 40 of\nP.D. No. 1177. Contributions or gifts in kind intended for specified beneficiaries, but which are perishable in\nnature and would require storage of distribution expenditures of more than forty per cent of their current\n\nmarket value may be sold at public auction and the proceeds derived therefrom shall be deposited in like\nmanner as if they were in cash, and shall be used or expended for the same purpose, subject to the conditions\nimposed by the donor and Section 40 of P.D. No. 1177. All such receipts, including equipment and other fixed\nassets shall be recorded in the books of the government and shall be subject to pertinent accounting and\nauditing rules and regulations.\nThe agency concerned shall submit to the Office of Budget and Management and to the Commission on Audit\nquarterly/monthly report of the proceeds from such donations, contributions, grants, bequests or gifts, in cash\nor in kind, including a quarterly report of expenditures or disbursements thereof."}},{"id":"PH-H15473-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Performance Bonds and Deposits. Performance bond and deposits filed or posted by private\npersons or entities with agencies of the government shall be deposited with an authorized government\ndepository bank as trust liabilities and under the name of the agency concerned. Upon faithful performance of\nthe undertaking or termination of the obligation for which the bond or deposit was required, any amount due\nshall be returned to the filing party and the office of the agency concerned, withdrawable on the joint\nsignatures of the authorized representatives of the agency and the Commission on Audit without the need for\nCash Disbursement Ceiling: Provided, That any interest accruing on deposit account and any forfeited\namounts shall be recorded as income of the General Fund and shall be remitted to the National Treasury at the\nend of each quarter. This provision shall apply to bonds posted in cash, such as bidder’s bond, guaranty\nbonds, bail bonds, judicial deposits for the benefit of clients, cash under litigation deposited in court or\nquasi-judicial bodies and other refundable and judicial bonds, and all bonds and deposits required by law,\nrules and regulations to be posted to ensure the faithful performance of an activity or undertaking.\nAUTHORIZED EXPENDITURES"}},{"id":"PH-H15473-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"Reorganization of the Executive Branch. The President may adjust, realign or modify key\nbudgetary inclusions and appropriations authorized in this Act as may be necessary to implement the\nreorganization of ministries and agencies of the government as approved by law or pursuant to Presidential\nDecree No. 1416 granting continuing authority to the President of the Philippines to reorganize the\nadministrative structure of the National Government: Provided, That the total amount as realigned does not\nexceed the grand total of all the appropriations of the ministries concerned."}},{"id":"PH-H15473-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"Use of Savings. Ministries, bureaus, offices and agencies are hereby authorized, subject to\nLetter of Implementation No. 29 and P.D. No. 1177, to use savings realized from appropriations actually\nreleased for the settlement of the following obligations and activities incurred during the current year:\na. Payment of hazard duty pay and of retirement gratuity or separation pay of employees who are entitled\nthereto under existing law or are laid off as a result of the elimination of their positions under authorized\nprocedures;\nb. Payment of the shares of the National Government in the salaries of officials and employees in newly\ncreated and/or reclassified local government units where no appropriation has been provided in this Act or\nwhere the authorized appropriations is not sufficient to cover the salaries of the said officials and employees;\nc. Provisions for social and economic opportunities and such other activities intended for the welfare of the\ncultural minorities as may be undertaken by the Presidential Assistant on National Minorities;\nd. Organization, activation, training operation of military units for the purpose of implementing agency\ndevelopment projects in areas adversely affected by peace and order problems, including salaries and\nallowances of all military personnel assigned thereto;\ne. Payment of obligations of the National Government or any of its ministries or agencies arising from\nperfected and valid contracts, or international agreements;\nf. Purchase or repair of equipment and furniture, including motor vehicles, to replace those lost or destroyed\nthrough theft or robbery, accident, fire, typhoon and other natural calamities, and to replace unserviceable and\n\ncondemned items;\ng. Expansion of essential facilities and services, including the opening of additional classes in elementary,\nsecondary and vocational schools, as may be approved by the President;\nh. Funding of foreign exchange and peso requirements of foreign-assisted projects; and\ni. Augmentation of operational expenses."}},{"id":"PH-H15473-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"Key Budgetary Inclusions. The Key Budgetary Inclusions (KBI) of ministries, bureaus, offices\nor agencies shall be released and used only for the indicated purposes and conditions, except as may be\notherwise approved by the President, pursuant to P.D. No. 1177: Provided, That the amounts herein\nappropriated and funded from loan proceeds or donations shall be released only to the extent of actual loan\navailments or receipts, as the case may be, and shall not be used for any purpose other than that specified in\nthe loan agreement or in the deed of donation."}},{"id":"PH-H15473-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"Expenditure Components. No change or modification shall be made in the expenditure items\nreferred to in the General Appropriations Act and other appropriations laws except by the act of the Batasang\nPambansa or of the President, as the case may be, upon recommendation of the Office of Budget and\nManagement."}},{"id":"PH-H15473-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"Cash Advances for Foreign-Assisted Projects. Any provision of law to the contrary\nnotwithstanding, cash advances may be authorized to meet the expenditure requirements of foreign-assisted\nprojects in cases where the approved project/loan agreement provides specifically for a reimbursement\nmechanism for expenses incurred, subject to the approval of the Office of Budget and Management and to\napplicable accounting and auditing regulations."}},{"id":"PH-H15473-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"Foreign Purchases and Other Importations. Purchases under foreign military sales agreements,\nheavy equipment imported for infrastructure projects and other importations of agencies which are financed\nby foreign borrowings or by Central Bank consolidated borrowing programs shall be subject to the\nrequirement of certification of availability of appropriations released for the purpose, to the requirements of\nLOI No. 880 and to applicable laws, rules and regulations."}},{"id":"PH-H15473-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"Foreign Exchange Requirements. Except as otherwise provided in this Act, the appropriations\nfor ministries, bureaus, offices or agencies allotted for maintenance and other operating expenses may be used\nfor foreign exchange requirements of duly approved activities, including payment of dues to international\norganizations, subject to the prior approval of the Office of Budget and Management."}},{"id":"PH-H15473-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"Condition on the Use of Regular Budgetary Allocations for Importations. Funds appropriated\nfor ministries, bureaus, offices, or agencies, state universities and colleges and government-owned and\ncontrolled corporations may be used to finance the importation of any commodity or service, including\npayments for equipment, supplies and consultancy fees only upon prior approval of a Special Budget for the\npurpose under Section 40 of P.D. No. 1177."}},{"id":"PH-H15473-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"Release and Disbursement of Funds for Foreign Mission. The maintenance and other operating\nexpenses of foreign missions an attaches shall be released and/or disbursed only in accordance with a Special\nBudget specifically intended for foreign posts and approved under Section 40 of P.D. No. 1177.\nFor this purpose, no personnel of any ministry, bureau, office or agency who is not included in said Special\nBudget shall be assigned or attached to foreign missions except upon prior approval of the Office of Budget\nand Management."}},{"id":"PH-H15473-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"Legal Assistance. With the approval of the President and upon recommendation of the Minister\nof Justice and the Presidential Commission on Reorganization, the funds herein appropriated for legal\nassistance activities, including those in the Ministry of Justice, Ministry of Labor and Employment, Ministry\nof Agrarian Reform, Ministry of Agriculture, and other agencies, may be realigned so as to ensure a fully\nintegrated legal assistance program."}},{"id":"PH-H15473-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"Purchase of Computer Equipment. The appropriations authorized in this Act for the purchase of\ncomputer equipment shall be released only with the approval of the President upon recommendation of the\nNational Computer Center and the Office of Budget and Management."}},{"id":"PH-H15473-A20","no":20,"noLabel":{"en":"Section 20"},"text":{"en":"Purchase of Motor Transport Equipment. No appropriations authorized in this Act shall be used\ndirectly or indirectly for the purchase of motor transport equipment unless otherwise directly authorized by the\nPresident or as approved by the Executive Committee upon recommendation of the Office of Budget and\nManagement as provided by Letter of Instructions No. 1220 and Letter of Implementation No. 29."}},{"id":"PH-H15473-A21","no":21,"noLabel":{"en":"Section 21"},"text":{"en":"Purchase of Supplies, Materials and Equipment Spare Parts. The stock on hand of supplies,\nmaterials and equipment spare parts, to be acquired thru ordinary purchase out of appropriations herein\nprovided, shall at no time exceed normal three-month requirements, subject to pertinent rules and regulations\nissued by competent authority: Provided, That heads of ministries, bureaus, offices or agencies of other\ninstrumentalities of the government may approve the build-up of stocks on hand of critical supplies and\nmaterials and defined or specified by the Office of Budget and Management in anticipation of cost increases,\nof requirements of a national emergency, or of an impending shortage in the items concerned; specifying\nmaximum quantities of individual items, but in no case shall these stocks exceed more than one year’s need,\nunless otherwise approved by the President, upon the joint recommendation of the Minister concerned and the\nChairman of the Commission on Audit."}},{"id":"PH-H15473-A22","no":22,"noLabel":{"en":"Section 22"},"text":{"en":"Emergency Purchases. Unless provided in this Act, ministries, bureaus, offices or agencies of\nthe National Government are authorized to make emergency purchases of supplies, materials and spare parts\nof motor transport equipment that are urgently needed for the repair of ambulances, motor vehicles, vessel and\naircrafts or to meet an emergency which may involve the loss of, or danger to, life and/or property, or are to\nbe used in connection with a project or activity which cannot be delayed without causing detriment to the\npublic service, in a monthly amount not exceeding four per centum of the annual agency expenditure program\nfor supplies and materials out of the appropriations allotted for maintenance and other operating expenses of\nthe agency concerned, except as may be authorized by the President, upon the joint recommendation of the\nOffice of Budget ad Management and the Commission on Audit."}},{"id":"PH-H15473-A23","no":23,"noLabel":{"en":"Section 23"},"text":{"en":"Repair of Buildings. Ministries, bureaus, offices or agencies, including public schools, courts of\njustice and hospitals may use their appropriations allotted for maintenance and other operating expenses for\nminor repairs of their offices and buildings which are government-owned."}},{"id":"PH-H15473-A24","no":24,"noLabel":{"en":"Section 24"},"text":{"en":"Cultural and Athletic Activities. An amount not exceeding ?15,000 per annum out of the\nappropriations each ministry, bureau, office or agency, and ?5,000 for each regional office of each\nregionalized ministry, bureau, office or agency, may be used for cultural and athletic activities, including\npurchase of uniforms at not more than P250 for each participant, and for supplies and necessary expenses for\nsaid activities. The amounts fixed in this section constitute the allowable maximum to be expended by any\nbureau, office or agency for its cultural and athletic activities, except as otherwise approved by the President:\nProvided, That these amounts may be pooled by the Minister concerned into one fund, programmed and\ncontrolled to best serve the needs all the offices, bureaus and agencies therein."}},{"id":"PH-H15473-A25","no":25,"noLabel":{"en":"Section 25"},"text":{"en":"Extraordinary and Miscellaneous Expenses. Appropriations herein authorized may be used for\nextraordinary expenses not exceeding: (a) ?30,000 for each Minister of equivalent; (b) ?10,000 for each\nDeputy Minister or equivalent; (c) ?4,000 for each Assistant Minister/Secretary or head of bureau or\norganization of equal rank to a bureau and for each Ministry Regional Director; and (d) ?2,000 for each\nBureau Regional Director. In addition, official entertainment and other miscellaneous expenses not exceeding\n?6,000 per annum shall be authorized for each of the following offices:\n1. Office of the Minister;\n2. Office of the Deputy Minister;\n3. Office of the Assistant Minister/Secretary;\n\n4. Bureau of Organizations of Equal Rank to a Bureau;\n5. Office of the Ministry Regional Director; and\n6. Office of the Bureau Regional Director.\nThese expenditures shall be payable on a reimbursement basis upon presentation of receipts and chargeable to\nappropriations allotted for maintenance and other operating expenses of the corresponding office.\nFor purposes of this Section, extraordinary and miscellaneous expenses shall include, but not limited to,\nexpenses incurred for or during meetings, seminars and conferences, official entertainment, public relation,\neducational, athletic and cultural activities, contributions to civic or charitable institutions, membership fees in\ngovernment associations, subscription to professional technical journals and informative magazines, library\nbooks and materials, office equipment and supplies and other similar expenses that are not supported by the\nregular budget allocation: Provided, That no portion of the amounts authorized herein shall be used for the\ncreation of positions, nor for salaries, wages, allowances, intelligence and confidential expenses."}},{"id":"PH-H15473-A26","no":26,"noLabel":{"en":"Section 26"},"text":{"en":"Release of Intelligence and Confidential Funds. Intelligence and confidential funds provided\nfor in the budgets of ministries, bureaus, offices or other agencies of the National Government, including\namounts from savings authorized by special provisions to be used for intelligence and counter-intelligence\nactivities, shall be released only on a project basis upon approval of the President."}},{"id":"PH-H15473-A27","no":27,"noLabel":{"en":"Section 27"},"text":{"en":"Information Outlay. The appropriations pertaining to information activities of the various\nministries, bureaus, offices or agencies shall be released upon presentation of an appropriate program of\nactivities prepared in coordination with the Office of Media Affairs, copies whereof shall be furnished the\nMembers of the Batasang Pambansa: Provided, That each ministry, bureau, office or agency shall include in\nits program of information dissemination, the administrative issuance for distribution to its lowest field\norganizational units, including those units over which it exercise, supervision; Provided, further, That\nassistance of the office of Media Affairs in printing such documents shall be made to achieve economical,\nefficient and effective dissemination thereof."}},{"id":"PH-H15473-A28","no":28,"noLabel":{"en":"Section 28"},"text":{"en":"Loans Outlay. The amounts authorized for loans outlay in the budgets of ministries, bureaus,\noffices and other agencies, including accumulated balances and receivables, shall be remitted to government\nfinancial institutions to be constituted and administered as a trust fund under such terms and conditions as may\nbe agreed upon by the head of the agency and the government financial institution concerned.\nThe rules and regulations governing the use of the trust fund shall be formulated by the Office of Budget and\nManagement."}},{"id":"PH-H15473-A29","no":29,"noLabel":{"en":"Section 29"},"text":{"en":"Funding of Contracts. Notwithstanding the availability of deferred payment terms, ministries,\nbureaus, offices or agencies concerned, before entering into a contract involving the expenditure of public\nfunds, including contracts for services or consultancy, contracts of lease, equipment rental, construction of\npartitions or improvements in leased buildings, or contracts involving an increase in the approved contract\nprice shall secure a certification of availability of funds for the purpose from the agency Chief Accountant,\nsubject to applicable rules and regulations as may be issued by the Office of Budget and Management and to"}},{"id":"PH-H15473-A46","no":46,"noLabel":{"en":"Section 46"},"text":{"en":"and 64, P.D. No. 1177: Provided, That the certification of availability of funds sufficient to cover\nthe cost of the contracted activities shall be contained in and made part of the contract duly signed by the\nChief Accountant of the contracting agency, as provided for by LOI No. 968.\nSection 30. Loan Agreement. Ministries, bureaus, offices, or agencies may enter into foreign or domestic\nloan agreements, whether in cash or in kind: Provided, That such loan agreements shall be in accordance with\nthe provisions of R.A. No. 245, as amended, LOI No. 880 and LOI No. 1307. Report of such agreement shall\nbe furnished the Members of the Batasang Pambansa.\nForeign borrowings shall not be incurred except for purposes and under conditions authorized under LOI No.\n\n1307 and R.A. No. 4860, as amended.\nSection 31. Contracts for Security and Janitorial Services. Ministries, bureaus, offices or agencies are\nauthorized to contract for security and janitorial services with private firms after public bidding of which the\ncost thereof may be paid from savings in the appropriations of the ministry, bureau, office or agency\nconcerned: Provided, That the execution of the contract for security and janitorial services shall not operate to\nautomatically abolish or render vacant any existing occupied security or janitorial position in the contracting\noffice or agency: Provided, further, That when said security or janitorial position shall subsequently become\nvacant, said position shall be considered automatically abolished.\nSection 32. Future Payment of Contractual Obligations. Ministries, bureaus, offices, or agencies, before\nentering into contracts for delivery of goods or services against future payment, shall first secure a\ncertification of the availability of the full contracted amount for such goods or services out of the agency’s\nappropriations. No contracts shall be entered into nor work shall be undertaken without such certification of\nfund availability.\nSection 33. Lease-Purchase Agreements. Ministries, bureaus, offices or agencies may enter into agreements\nfor lease-purchase of equipment to public bidding and to the approval of the Office of Budget and\nManagement, and other pertinent accounting and auditing regulations. Details of the payment shall be\nindicated in the lease-purchase agreement and accompanied with certification of availability of equipment\noutlay authorized for the agency in this Act to cover the full contract cost: Provided, That lease-purchase\nagreements may be entered into only for specialized equipment with high unit costs and not for such\nequipment as typewriters, adding machines, automobiles the purchase price of which is at least ?50,000.00:\nand Provided, further, That all lease-purchase agreements of equipment with a total value in excess of\nP200,000.00 shall be subject to the approval of the President.\nPERSONAL SERVICES BENEFITS\nSection 34. Funding of Personnel Benefits. The personnel benefits costs of government officials and\nemployees shall be charged against the respective funds from which their compensation and/or salaries are\nAll authorized supplementary/additional compensation, fringe benefits and other personal services costs of\nofficials and employees whose salaries are drawn from special accounts or special funds, such as salary\nincreases and adjustments, merit increases, incentive/service fees, vacation and sick leaves, retirement and life\ninsurance premiums, compensation insurance premiums, health insurance (Medicare) premiums, Pag-IBIG\ncontributions, hospitalization and medical benefits, scholarship and educational benefits, training and seminar\nexpenses, all kinds of allowances, whether commutable or reimbursable, in cash or in kind, and other\npersonnel benefits and privileges gratuities, separation pay and terminal leave benefits shall be charged\nagainst the corresponding fund from which their basic salaries are drawn and in no case shall such personnel\nbenefits costs be charged against the General Fund of the National Government.\nOfficial and employees on detail with other offices, including the representatives and support personnel of\nauditing units assigned to serve other offices or agencies, shall be paid their salaries, emoluments, allowances\nand the foregoing supplemental compensation, fringe benefits and other personal services costs from the\nappropriations of their parent agencies and in no case shall such be charged against the appropriations of the\nagencies where they are assigned or detailed, except when authorized by law.\nSection 35. Transportation and Representation Allowances. The following officials and those of equivalent\nrank as may be determined by the Office of Budget and Management are hereby granted monthly commutable\ntransportation and representation allowances payable from the programmed appropriations provided for their\nrespective offices, not exceeding the rates indicated below, which shall apply to each type of allowance:\na. At ?1,000 for Ministers;\nb. At ?750 for Career Executive Service Rank I officials,\n\nc. At ?650 for Career Executive Service Rank II Officials;\nd. At ?550 for Career Executive Service Rank III Officials;\ne. At ?475 for Career Executive Service Rank IV Officials;\nf. At ?400 for Career Executive Service Rank V Officials; and\ng. At ?325 for Chiefs of Divisions, identified as such in the Personal Services Itemization.\nThe transportation allowance herein authorized shall not be granted to officials who are assigned a\ngovernment vehicle or use government motor transportation, except as may be approved by the President.\nUnless otherwise provided by law, no amount appropriated in this Act shall be used to pay for representation\nand/or transportation allowances, whether commutable or reimbursable which exceed the rates authorized\nunder this Section. Previous administrative authorizations not consistent with the rates and conditions herein\nspecified shall no longer be valid and payment shall not be allowed.\nAllowances of those officials who are receiving salaries from special accounts or special funds shall be\ncharged against the corresponding fund from which their salaries are charged. Officials on detail with other\noffices, including officials of the Commission on Audit assigned to serve other offices or agencies, shall be\npaid the allowance herein authorized from the appropriations of their parent agencies.\nSection 36. Official Vehicles and Transport. Government motor transportation may be used by the\nfollowing officials, and those who may be specifically authorized by the President with costs chargeable to the\nappropriations authorized for their respective offices:\na. The President of the Philippines;\nb. The Prime Minister;\nc. The Speaker of the Batasang Pambansa;\nd. The Chief Justice of the Supreme Court;\ne. The Deputy Prime Minister;\nf. The Ministers, Deputy Ministers and officials of equivalent rank;\ng. The Ministers of State;\nh. The Presiding Justice of the Intermediate Appellate Court;\ni. Ambassadors, Ministers Plenipotentiary and Consuls in charge of Consulates, in their respective stations\nj. The Chief of Staff, the Vice Chief of Staff, and the Commanding Generals of the major services of the\nArmed Forces of the Philippines; and\nk. The Heads of Constitutional Offices.\nSection 37. Uniform/Clothing Allowance. The appropriations herein provided for each ministry, bureau or\noffice may be used for uniform and/or clothing allowance at not more than P250 each per annum of female\nemployees and employees occupying positions which require the wearing of specialized uniform such as\nsecurity guards, prison guards, customs police/guards, quarantine officers, letter carriers, hospital attendants,\nroad maintenance men, street sweepers, and other employees as may be determined by the Office of Budget\nand Management. Savings in the appropriations for each ministry, bureau of office may be used for this\npurpose where no amount is specifically appropriated in this Act.\nSection 38. Hazardous Duty Pay. Upon recommendation of the Ministry Head and approval of the Office\nof Budget and Management, hazard pay may be allowed to officials and employees who are actually assigned\nin hardship or difficult areas, strike-torn or embattled areas, distressed or isolated stations, prison camps,\nmental hospitals, radiation exposed clinics or laboratories or disease-infected areas which expose them to\n\ngreat danger, contagion, radiation, volcanic activity/eruption, occupational risks or perils to life, chargeable to\nsavings in the appropriations of the ministry/agency concerned, which shall not be less than ?50 nor more than\n?150 each per month, except in cases where the rates are specifically provided for under special shall govern:\nProvided, That hazard pay by reason of strifetorn or embattled areas shall be subject to the certification issued\nby the Minister of National Defense and the rates thereof shall be determined by the Office of Budget and\nManagement and the Minister of National Defense shall review from time to time authorizations for the\npayment of hazardous duty pay in strife-torn and embattled areas earlier issued and shall terminate such\nauthorizations in areas if conditions no longer justify the continuation of hazardous duty pay.\nSection 39. Honoraria. Ministries, bureaus, offices or agencies are authorized to use their respective\nappropriations for payment of honoraria as compensation for services rendered by researchers, experts and\nspecialists who are acknowledged authorities in their field of specialization, at such rates as the Office of\nBudget and Management may authorize, unless otherwise specifically provided by law.\nSection 40. Incentive or Service Fees. Incentive or service fees paid by the Government Service Insurance\nSystem or by private companies which are intended for employees servicing them shall be deposited with the\nNational Treasury and shall accrue to the General Fund, pursuant to Sec. 50 of P.D. No. 1177. Such fees may\nbe made available for payment of incentive or service fees of the employees of the agency in accordance with\nrates approved by the Minister concerned, subject to Section 40 of P.D. No. 1177: Provided, That the share of\nany employee may not, in the aggregate, exceed fifty per centum of his annual salary.\nSection 41. Special Counsel Allowance. Lawyer-personnel in the legal staffs of ministries, bureaus, offices\nor agencies of the National Government appearing in Court as special counsel in collaboration with the\nSolicitor-General and/or Fiscals concerned are hereby authorized an allowance of P100 for each appearance,\nchargeable to savings in the appropriations allotted for personal services of their respective offices, but not\nexceeding ?400 a month.\nSection 42. Quarters Allowance. Except as may be authorized by law, government officials and employees\nwho, by virtue of their positions, are furnished free quarters or are charged only a nominal rate in\ngovernment-owned buildings, such as dormitories or living quarters in hospitals, state colleges, universities\nand schools, foreign posts and elsewhere, shall forfeit entitlement to any quarters allowance. Where portions\nof rented private buildings are authorized to be utilized for officials quarters, the excess of rental cost over the\nquarters allowance of the official shall be borne by him. Those who enjoy free quarters in government-owned\nor rented buildings but who are not entitled to quarters privilege shall be charged the corresponding cost of\nrentals therefor. Unless fixed by law or regulations, the rate of quarters allowance or rental, as the case may be\nshall be determined by the Office of Budget and Management.\nSection 43. Compensation of Contractual Personnel. Heads of ministries, bureaus, offices or agencies,\nwhen authorized in their respective appropriations as provided under this Act, may hire consultants, experts\nand other contractual personnel to perform specific vital activities or services which cannot be provided by the\nregular staff of the agency, limited to such period when their services are reasonably required and to activities\nthat shall have a definite expected output. Such contractual personnel may be paid compensation inclusive of\nfees, honoraria, per diems and allowances not exceeding 120% of the minimum salary of an equivalent\nposition in the National Classification and Compensation Plan, except as may be authorized by the Office of\nBudget and Management in the following instances: (a) when the consultant or expert is an acknowledged\nauthority in his field of specialization, and (b) where the consultant or expert is hired to perform a specific\nactivity or service that requires technical skill and expertise which local labor force cannot provide, or if such\nexpertise is available, the supply is limited: Provided, That in no case shall such compensation exceed the\nsalary of his immediate superior, except as may be otherwise approved jointly by the Civil Service\nCommission and the Office of Budget and Management: Provided, further, That no amount appropriated in\nthis Act shall be used for payment or retirement gratuity under Section 12(c) of C.A. No. 186, as inserted by\nR.A. No. 1616, as amended, nor for leave benefits pertaining to services rendered under contractual\n\nemployment, nor use the compensation received for the same period as basis for computation of leave\nbenefits, except where specifically provided by law.\nFor purposes of this Section, appointments to positions funded from lump-sum appropriations for personal\nservices for the payment of consultants, technical, professional and expert services, confidential assistants or\nother similar positions, or from capital outlays, feasibility studies fund, subsidies, donations, special projects\nfund, either funded by the General Fund and/or supported by domestic or foreign loans, and other similar\nfunds which may be used for personal services, are considered contractual in nature. Appointments which are\nfunded from special lump-sum appropriations, subsidies and contributions from other agencies, shall likewise\nbe considered as contractual in nature, and subject to the above restrictions and limitations, except as may be\ndetermined by the Office of Budget and Management.\nSection 44. Restriction on the Use of Appropriations for Retirements Gratuity and Terminal Leave. Unless\notherwise authorized by law, no amount appropriated in this Act shall be used for payment of retirement\ngratuity under the provisions of Sec. 12(c) of C.A. No. 186, as inserted by R.A. No. 1616, as amended, and\nterminal leave benefits of retiring officials and employees which include in the computation thereof additional\ncompensation received for: (a) overtime services rendered beyond regular office of school hours; (b) per diem\nfor attendance in board or committee meetings or conferences or for travel outside official stations; (c)\nmid-year, Christmas, thirteenth month and other bonuses; (d) allowances for cost of living, subsistence,\nquarters, housing, laundry, clothing/uniform, family, education, hazardous, occupation, overseas duty,\npost/station, medical/dental/hospitalization, representation, transportation, extraordinary and miscellaneous,\namelioration; inflation, incentive and such other similar allowances; (e) fees on per capita basis as\nmembers/examiners of professional regulation and other examination boards; (f) honoraria as resource\nspeaker or lecturer in conferences or seminars or as instructors in classrooms for excess teaching loads granted\nover basic pay rendered at night or on Saturdays, holidays and summer vacation; (g) fees for consultancy or\nsimilar services rendered to committee, boards, offices or agencies; and (h) service fees for extra services and\nother similar compensation paid for rendition of additional services.\nSection 45. Unauthorized Pre-Retirement Promotions and Salary Increase. No portion of the appropriations\nprovided in this Act shall be used for automatic promotions or for salary increases and adjustments granted to\nretiring officials and employees, which are not authorized by law and duly formalized in the form of a\nNational Compensation Circular.\nSection 46. Personal Liability of Officials for Payment of Unauthorized Personal Services Cost. No official\nor employee of any ministry, bureau, office, agency, commission, board, state university or college, of the\nNational Government, including those of government-owned or controlled corporations shall be granted\nand/or paid any unauthorized compensation, either basic, additional or supplementary, or fringe benefits and\nallowances of any kind, including payment of retirement benefits and terminal leaves computed in violation of\nthe General Provisions in this Act or other existing laws, which are chargeable against the appropriations\nauthorized in this Act or under other appropriation laws or from other income of the Government.\nThe payment of any unauthorized compensation, allowance, fringe benefits or personal services costs made in\nviolation of the Section or of the General Provisions in this Act is null and void and is the personal liability of\nthe head of the office or agency who authorized such payment, the Resident Auditor, other officials and\nemployees who participated or took part therein, and the person who received such payments, who shall be\njointly and severally liable for the refund of the full amount so paid and received, in addition to any\ndisciplinary action that may be instituted against such erring officials under the provisions of Section 49 and\n87 of P.D. No. 1177 and to any criminal action under the Revised Penal Code and other penal laws.\nLOCAL GOVERNMENT UNITS"}},{"id":"PH-H15473-A47","no":47,"noLabel":{"en":"Section 47"},"text":{"en":"Sharing of National Revenues. The computation of appropriations herein authorized for local\ngovernment revenues sharing establishment under P.D. Nos. 144 and 436 (as amended) shall be based on\nrevenues excluding income recorded but charges to the General Fund Adjustments and Customs Duties Fund\n\nprovided in this Act assessed on otherwise tax-exempt government agencies and corporations. Compliance\nwith the sharing formula as provided by law shall be determined taking into account all funds allocated and\nreleased for local government units, except for the budgetary aid fund herein appropriated pursuant to Item\nADMINISTRATIVE PROCEDURES"}},{"id":"PH-H15473-A48","no":48,"noLabel":{"en":"Section 48"},"text":{"en":"Release of Funds for Training Programs. Ministries, bureaus, offices or agencies shall\nformulate and review their training programs in light of the need to train personnel in skills and attitudes. Such\ntraining programs shall be submitted to the Training Coordination Committee created under LOI No. 754,\nwhich shall review and evaluate the training activities. No appropriation for training shall be released without\nsuch review and evaluation."}},{"id":"PH-H15473-A49","no":49,"noLabel":{"en":"Section 49"},"text":{"en":"Direct Release of Funds to Regional Offices. Funds allotted for regional offices but included in\nthe budgets of their central offices or which are specifically allocated for the different regions shall be released\ndirectly to said regional offices when dictated by the need and urgency of regional activities, pursuant to Sec.\n38(e) of P.D. No. 1177. Imposition of any retention or deduction as reserves shall not be allowed except as\nmay be authorized by the Office of Budget and Management. For this purpose, the Office of Budget and\nManagement shall identify by region the expenditure programs of agencies in the national government budget\nand shall release funds intended for them in accordance with the approved regional distribution of\nexpenditures, specifying the region of destination."}},{"id":"PH-H15473-A50","no":50,"noLabel":{"en":"Section 50"},"text":{"en":"Prohibition Against Deduction/Retention of Allotment. Fund releases from appropriations\nprovided in this Act for any project or activity shall be transmitted intact or in full to the office or agency\nconcerned and no retention or deductions as reserves or overhead shall be made, except as authorized by law\nor upon direction of the President. The Commission on Audit shall ensure compliance with this provision of\nthe extent that sub-allotments by ministries and/or central agencies to their subordinate offices are in\nconformity with allocations in budgetary Advice of Allotments issued by the Office of Budget and\nManagement."}},{"id":"PH-H15473-A51","no":51,"noLabel":{"en":"Section 51"},"text":{"en":"Release of Appropriations to Local Government Units. Funds appropriated herein for local\ngovernment units shall be released only after the approval of their respective budgets pursuant to the\nprovisions of P.D. No. 1375, except as may be authorized jointly by the Ministry of Local Government and\nthe Office of Budget and Management."}},{"id":"PH-H15473-A52","no":52,"noLabel":{"en":"Section 52"},"text":{"en":"Administration of the Releases of Funds Allotted for Operating Expenses and Equity\nInvestments in Government Corporations. Funds herein appropriated for operating expenses contributions and\nequity investments in government-owned or controlled corporations and other public corporate bodies shall be\nunder the administration of the Office of Budget and Management. Said funds shall be directly released to the\nrecipient corporation through the Bureau of the Treasury on the basis of a Work and Financial Plan prepared\nand submitted by the Corporation concerned, subject to Sec. 40 of P.D. No. 1177 and Letter of\nImplementation No. 29."}},{"id":"PH-H15473-A53","no":53,"noLabel":{"en":"Section 53"},"text":{"en":"Corporate Equity Investments. The appropriations herein authorized for equity investments\nmay be used by the National Treasurer for the payment of loans relent to corporations, including the\nobligations incurred by the said corporations for the reimbursement of advances made by the National\nTreasury on obligations guaranteed by the Government of the Republic of the Philippines, subject to the\napproval of the President upon recommendation of the Office of Budget and Management."}},{"id":"PH-H15473-A54","no":54,"noLabel":{"en":"Section 54"},"text":{"en":"Submission of Financial Statement. All government-owned or controlled corporation shall\nsubmit to the Office of Budget and Management and to the Members of the Batasan their respective financial\nstatements, including plans, programs, targets and other reports as may be required from time to time. The\nannual reports shall be done and submitted as herein provided on or before March 31, of the succeeding year."}},{"id":"PH-H15473-A55","no":55,"noLabel":{"en":"Section 55"},"text":{"en":"Unauthorized Organizational Units. Unless otherwise created by law or directed by the\n\nPresident, no organizational unit in any ministry, bureau, office or agency shall be authorized in the respective\norganizational structures and be funded from appropriations provided by this Act, without authority from the\nPresidential Commission on Reorganization and the Office of Budget and Management. Organizational units\ncreated by administrative authorizations shall be considered as ad hoc arrangements that shall be staffed by\ncontractual personnel or staff members on detail."}},{"id":"PH-H15473-A56","no":56,"noLabel":{"en":"Section 56"},"text":{"en":"Implementation of Construction Projects. Construction projects funded from capital outlays\nauthorized in this Act under the various ministries, bureaus, offices or agencies of the National Government,\nincluding the construction of buildings for state universities, colleges, schools, hospitals, sanitaria, health\ncenters and health stations, roads and bridges, shall be implemented only in accordance with the appropriate\nstandards and specifications for the planning, survey, design and construction of the projects as prescribed by\nthe Ministry of Public Works and Highways or the Ministry of Transportation and Communications, through\neither of said ministries as the case may be. In addition, land use and zoning guidelines shall be prescribed by\nthe Ministry of Human Settlements. In the prosecution of the construction projects, Sections 2, 3, 4, 5, 6, 7, 9\nand 10 of Batas Pambansa Blg. 50 entitled \"An Act Appropriating Funds for Public Works and Highways\nProjects and for Other Purposes\", and other legislations on public works shall be strictly complied with\nwhenever applicable.\nConcluding Provisions"}},{"id":"PH-H15473-A57","no":57,"noLabel":{"en":"Section 57"},"text":{"en":"Separability Clause. If for any reason any section or provision of this Act is declared\nunconstitutional or invalid, other sections or provisions hereof which are not affected thereby shall continue to\nbe in full force and effect."}},{"id":"PH-H15473-A58","no":58,"noLabel":{"en":"Section 58"},"text":{"en":"Effectivity. The provisions of this Act shall take effect on January one, nineteen hundred and\neighty-four unless otherwise provided herein.\nApproved: June 24, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15474"] = {"id":"PH-H15474","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 641  An Act Changing the Name of the Oriental Mindoro National High School in the Municipality of Calapan, Province of Oriental Mindoro, to Jose J. Leido, Jr. National Memorial High School","orig":"Batas Pambansa Blg. 641  An Act Changing the Name of the Oriental Mindoro National High School in the Municipality of Calapan, Province of Oriental Mindoro, to Jose J. Leido, Jr. National Memorial High School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 641","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-10-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00641_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00641_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15474-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Oriental Mindoro National High School in the Municipality of Calapan,\nProvince of Oriental Mindoro, is changed to Jose J. Leido, Jr. National Memorial High School."}},{"id":"PH-H15474-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: October 13, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15475"] = {"id":"PH-H15475","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 642  An Act Authorizing the Issuance of Transfer Certificates of Title to Project Beneficiaries of the National Housing Authority Within the Tala Estate Reservation on the Basis of the Transfer Certificates of Title on File in the Registry of Deeds of Rizal And/Or in the Registry of Deeds of Caloocan City","orig":"Batas Pambansa Blg. 642  An Act Authorizing the Issuance of Transfer Certificates of Title to Project Beneficiaries of the National Housing Authority Within the Tala Estate Reservation on the Basis of the Transfer Certificates of Title on File in the Registry of Deeds of Rizal And/Or in the Registry of Deeds of Caloocan City"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 642","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-11-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00642_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00642_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15475-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Any provisions of law to the contrary notwithstanding, all registrable deeds of conveyance\nand/or mortgage and other documents executed by the National Housing Authority pursuant to Proclamation\nNo. 843 in favor of its intended project beneficiaries shall be registered in the Office of the Register of Deeds\nof Caloocan City without need of presenting the owner’s duplicate of the certificate of title covering the area\nthus conveyed or encumbered. In all cases of transfers of ownership to project beneficiaries of the Authority,\nthe Register of Deeds of Caloocan City is authorized to issue the corresponding new transfer certificates of\ntitle on the basis of the original copies of Transfer of Certificates of Title Nos. 34591 thru 34637 which are in\nthe custody of the Registry of Deeds of Rizal and/or the Register of Deeds of Caloocan City."}},{"id":"PH-H15475-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: November 21, 1983"}}],"pack":"ph-p156"};
  FT["PH-H15476"] = {"id":"PH-H15476","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 643  An Act to Submit to the Filipino People for Ratification or Rejection the Amendments to the Constitution of the Philippines Proposed By the Batasang Pambansa in Its Sixth Regular Session, Calling a Plebiscite for this Purpose, Appropriating Funds therefor and for Other Purposes","orig":"Batas Pambansa Blg. 643  An Act to Submit to the Filipino People for Ratification or Rejection the Amendments to the Constitution of the Philippines Proposed By the Batasang Pambansa in Its Sixth Regular Session, Calling a Plebiscite for this Purpose, Appropriating Funds therefor and for Other Purposes"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 643","issuingBody":"Batasang Pambansa","promulgatedDate":"1983-12-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00643_1983_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00643_1983_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15476-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"A plebiscite shall be held on January 27, 1984, pursuant to Article XVI, Sections 1(1) and 2 of\nthe Constitution, for the submission to the people of amendments to the Constitution of the Philippines\nproposed by the Batasang Pambansa during its Sixth Regular Session."}},{"id":"PH-H15476-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The said amendments shall be published at least once, in at least three newspapers of nationwide\ncirculation and once in at least one newspaper of provincial circulation in every province to be determined by\nraffle, the last publication to be made not later than January 7, 1984. Printed copies of the amendments shall\nbe posted in a conspicuous place in every provincial capitol, municipal, city and barangay hall or building not\nlater than January 7, 1984. Sufficient copies of the proposed amendments shall be furnished each voting\ncenter to be available for the qualified voters to read and study on the day of the plebiscite. Copies thereof in\nthe principal dialects shall also be printed and distributed to the electorate. The Commission on Elections is\nhereby empowered to promulgate rules and regulations to assure widest dissemination through the print and\nbroadcast media and other means of information on the proposed amendments and questions herein prescribed\nfor submission to the electorate."}},{"id":"PH-H15476-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The official ballots to be used in the plebiscite shall be printed in English and, in appropriate\ncases, in Arabic in accordance with the provisions of the Election Code, of 1973, in a form to be prescribed by\nthe Commission on Elections which shall include the questions and particulars hereunder stated to be printed\nin clearly readable type:\nOFFICIAL BALLOT\nThe Batasang Pambansa, in Resolutions Numbered 104, 105, 110, 111 and 112 has proposed that the\nConstitution of the Philippines be amended in the particulars hereinbelow stated.\nTo vote for the approval of each of the questions covering the proposed amendments, write the word \"Yes\" or\nits equivalent in the blank space provided for the purpose. A check mark shall not be considered as such\nequivalent.\nTo vote for the rejection thereof, write the word \"No\" or its equivalent in the blank space provided for the\npurpose. A cross or \"x\" mark shall not be considered as such equivalent.\nQUESTION NO. 1\nDo you vote for the approval of amendments to the Constitution proposed by the Batasang Pambansa in\nResolution Numbered 104 and 112 which, in substance, provides as follows:\n1. The Members of the Batasang Pambansa shall be elected by the different provinces with their component\ncities, by highly urbanized cities, and by the districts of Metropolitan Manila, instead of by the various\nregions. Each province, highly urbanized city and district of Metropolitan Manila shall be entitled to at least\none Member. The total number of Members of each province and city shall at least be the same as under the\n1935 Constitution.\n\n2. The Members of the Batasang Pambansa to be elected by the different provinces with their component\ncities, highly urbanized cities, and the districts of Metropolitan Manila shall be apportioned, unless otherwise\nprovided by law, as follows:\nNational Capital Region: Manila, 6; Quezon City, 4; Caloocan, 2; Pasay, 1; Pasig and Marikina, 2; Las Piñas\nand Parañaque, 1; Makati, 1; Malabon, Navotas and Valenzuela, 2; San Juan and Mandaluyong, 1; Taguig,\nPateros and Muntinglupa, 1.\nRegion I: Abra, 1; Benguet, 1; Ilocos Norte with Laoag City, 2; Ilocos Sur, 2; La Union, 2; Mountain\nProvince, 1; Pangasinan with the cities of Dagupan and San Carlos, 6; Baguio City, 1;\nRegion II: Batanes, 1; Cagayan, 3; Ifugao, 1; Isabela, 3; Kalinga-Apayao, 1; Nueva Vizcaya, 1; Quirino, 1;\nRegion III: Bataan, 1; Bulacan, 4; Nueva Ecija with the cities of Cabanatuan, Palayan and San Jose, 4;\nPampanga with Angeles City, 4; Tarlac, 2; Zambales, 1; Olongapo City, 1;\nRegion IV: Aurora, 1; Batangas with the cities of Batangas and Lipa, 4; Cavite with the cities of Cavite,\nTagaytay and Trece Martires, 3; Laguna with the San Pablo City, 4; Marinduque, 1; Occidental Mindoro, 1;\nOriental Mindoro, 2; Palawan with Puerto Princesa City, 1; Quezon with Lucena City, 4; Rizal, 2; Romblon,\n1;\nRegion V: Albay with Legaspi City, 3; Camarines Norte, 1; Camarines Sur with the cities of Iriga and Naga,\n4; Catanduanes, 1; Masbate, 2; Sorsogon, 2;\nRegion VI: Aklan, 1; Antique, 1; Capiz with Roxas City, 2; Iloilo with Iloilo City, 5; Negros Occidental with\nthe cities of Bacolod, Bago, Cadiz, La Carlota, San Carlos and Silay, 7;\nRegion VII: Bicol with Tagbilaran City, 3; Cebu with the cities of Danao, Lapu-Lapu, Mandaue and Toledo,\n6; Negros Oriental with the cities of Bais, Canlaon and Dumaguete, 3; Siquijor, 1; Cebu City, 2;\nRegion VIII: Leyte with the cities of Ormoc and Tacloban 5; Southern Leyte, 1; Eastern Samar, 1; Northern\nSamar, 1; Samar with Calbayog City, 2;\nRegion IX: Basilan, 1; Sulu, 1; Tawi-Tawi, 1; Zamboanga del Norte with the cities of Dapitan and Dipolog, 2;\nZamboanga del Sur with Pagadian City, 3; Zamboanga City, 1;\nRegion X: Agusan del Norte with Butuan City, 1; Agusan del Sur, 1; Bukidnon, 2; Camiguin, 1; Misamis\nOccidental with the cities of Oroquieta, Ozamis and Tangub, 1; Misamis Oriental with Gingoog City, 2;\nSurigao del Norte with Surigao City, 1; Cagayan de Oro City, 1;\nRegion XI: Surigao del Sur, 1; Davao del Norte 3; Davao Oriental, 1; Davao del Sur, 2; South Cotabato with\nGeneral Santos City, 3; Davao City, 2;\nRegion XII: Lanao del Norte, 1; Lanao del Sur with Marawi City, 2; Maguindanao with Cotabato City, 2;\nNorth Cotabato, 2; Sultan Kudarat, 1; Iligan City, 1.\nAny province that may hereafter be created or any component city that may hereafter be declared by or\npursuant to law as a highly urbanized city, shall be entitled in the immediately following election to at least\none Member or such number of Members as it may be entitled to on the basis of the number of its inhabitants\nand on the same uniform and progressive ratio used in the last preceding apportionment. The number of\nMembers apportioned to the province out of which the new province was created or where the new highly\nurbanized city is geographically located shall be correspondingly adjusted by the Commission on Elections\nbut such adjustment shall not be made within one hundred twenty days before the election.\n3. The foregoing appointment shall be appended as an Ordinance to the Constitution.\n4. The residence requirements in the political subdivision in which a Member of the Batasang Pambansa will\nbe elected is reduced from one year to six months immediately preceding the day of the election.\nQUESTION NO. 2\n\nDo you vote for the approval of amendments to the Constitution as proposed by the Batasang Pambansa in\nResolution Numbered 110 which, in substance, provide for a different mode of presidential succession with\nthe following salient features:\n1. Abolition of the Executive Committee and Creation of the Office of the Vice-President.\n(1) The Executive Committee provided in Section 3, Article IX of the Constitution is abolished.\n(2) The Office of the Vice-President is created. The Vice-President shall have the same qualifications and\nterm of office and may be removed from office in the same manner as the President. He may be appointed as a\nmember of the Cabinet and he may be nominated and elected as Prime Minister. He shall be elected with and\nin the same manner as the President. A vote for the President shall also be a vote for the Vice-President\nrunning under the same ticket of a political party, unless otherwise provided by law. The age qualification for\nPresident and Vice-President is reduced to 40 years old.\n2. Presidential succession before the election of 1987\n(1) In case a vacancy in the Office of President occurs before the presidential election of 1987, the Speaker of\nthe Batasang Pambansa shall act as President until a President and a Vice-President or either of them shall\nhave been elected and shall have qualified.\n(2) The Batasang Pambansa shall, at ten o’clock in the morning of the third day after the vacancy occurs,\nconvene in accordance with its Rules without need of a call and within seven days enact a law calling for a\nspecial election for President and Vice-President to be held not earlier than forty-five days and not later than\nsixty days from the time of such call. The convening of the Batasang Pambansa cannot be suspended nor the\nspecial election postponed. No special election shall be called if the vacancy occurs within seventy days\nbefore the date of the presidential election of 1987.\n(3) The tenure of office of the President and Vice-President elected in the special election shall commence at\nnoon of the tenth day following their proclamation, and shall end at noon on the thirtieth day of June of the\nsixth year thereafter.\n3. Limitations on the powers of the Speaker acting as President.\n(1) The Acting President may not declare martial law or suspend the privilege of the writ of habeas corpus\nwithout the prior consent of at least a majority of all the Members of the Batasang Pambansa.\n(2) He may not issue any decree, order or letter of instruction while the lawmaking power of the President is\n(3) He shall be deemed automatically on leave and the Speaker Pro-Tempore shall act as Speaker. While\nacting as President, the Speaker may not be removed.\n(4) He shall not be eligible for election in the immediately succeeding election for President and\nVice-President.\n(5) Appointments extended by the Acting President shall remain effective unless revoked by the newly elected\nPresident within ninety days from his assumption of office.\n4. Presidential succession after the election of 1987\n(1) If at the time fixed for the beginning of his term, the President-elect shall have died, the Vice-President\nelect shall become President. If a President shall not have been chosen before the time fixed for the beginning\nof his term, or if the President shall have failed to qualify, then the Vice-president shall act as President until a\nPresident shall have qualified.\n(2) In case of permanent disability, death, removal from office or resignation of the President, the\nVice-President shall become the President to serve the unexpired term.\n5. Statutory succession\n\n(1) The Batasang Pambansa shall by law provide who shall act as President or the manner in which one who is\nto act shall be elected if neither a President-elect nor a Vice-President-elect shall have been chosen nor shall\nhave qualified, or both shall have, died at the time fixed for the beginning of their term.\n(2) The Batasang Pambansa shall by law provide for the death, pertinent disability or resignation of the\nSpeaker at the time the vacancy in the Office of the President occurs or subsequently thereafter, declaring who\nshall serve as President until the President and the Vice-President shall have been elected and qualified,\nsubject to the same restrictions of powers and disqualifications as the Speaker when acting as President.\nQUESTION NO. 3\nDo you vote for the approval of amendments to the Constitution as proposed by the Batasang Pambansa in\nResolution Numbered 105 which, in substance, provide that grant shall be an additional mode for the\nacquisition of lands belonging to the public domain and that the agrarian reform program may include the\ngrant or distribution of alienable lands of the public domain to qualified tenants, farmers and other landless"}}],"pack":"ph-p156"};
  FT["PH-H15477"] = {"id":"PH-H15477","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 644  An Act Further Amending Section Two of Republic Act Numbered Eighteen Hundred and Sixty-Two, as Amended","orig":"Batas Pambansa Blg. 644  An Act Further Amending Section Two of Republic Act Numbered Eighteen Hundred and Sixty-Two, as Amended"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 644","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-01-05","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00644_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00644_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15477-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Section two of Republic Act Numbered Eighteen hundred and sixty-two, as amended, is further\namended to read as follows:\n\"Sec. 2. Person who were retired and paid gratuity under said Republic Act Numbered Three hundred forty\nand/or Republic Act Numbered Sixteen hundred sixteen as amended, with the effective date of retirement\nafter June twenty-two, nineteen hundred fifty-seven but before September ten, nineteen hundred seventy-nine,\nand who come within the purview of clauses (a) and (b) of the preceding section may, at their option, elect to\nreceive, in lieu of such gratuity paid to them, the annual retirement pay as provided in Section two of Republic\nAct Numbered Three Hundred forty, as amended; and upon making such election, said persons shall, subject\nto the provisions and limitations hereinafter provided, be entitled to receive the annual retirement pay as\nprovided in Section two of Republic Act Numbered Three hundred forty, as amended. The option herein\ngranted may be exercised within five years from the date of the approval of this later amendatory Act by the\nwidows and/or minor children of the said retirees who could not exercise the said option by reason of death.\nNothing in this section shall be construed as authorizing payment of retirement pay which have accrued prior\nto the approval of this later amendatory Act.\""}}],"pack":"ph-p156"};
  FT["PH-H15478"] = {"id":"PH-H15478","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 646  An Act Changing the Name of the San Pedro Elementary School in Barangay San Pedro, Municipality of San Jose, Province of Antique, to Assemblyman Segundo Moscoso Memorial School","orig":"Batas Pambansa Blg. 646  An Act Changing the Name of the San Pedro Elementary School in Barangay San Pedro, Municipality of San Jose, Province of Antique, to Assemblyman Segundo Moscoso Memorial School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 646","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00646_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00646_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15478-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the San Pedro Elementary School in Barangay San Pedro, Municipality of San Jose,\nprovince of Antique, is changed to Assemblyman Segundo Moscoso Memorial School."}},{"id":"PH-H15478-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15479"] = {"id":"PH-H15479","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 648  An Act Naming What Is Commonly Known as the Cebu South Expressway And/Or the Cebu South Road in Cebu City and Cebu Province as the Natalio B. Bacalso South National Highway","orig":"Batas Pambansa Blg. 648  An Act Naming What Is Commonly Known as the Cebu South Expressway And/Or the Cebu South Road in Cebu City and Cebu Province as the Natalio B. Bacalso South National Highway"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 648","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00648_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00648_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15479-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The National Highway starting from the corner of Leon Kilat Street, along the bus terminal, the\nsouth expressway in Cebu City in what is commonly known as the Cebu South Expressway and/or the Cebu\nSouth Road in Cebu City and Province of Cebu up to the Municipality of Santander, Cebu, shall be known as\nthe Natalio B. Bacalso South National Highway."}},{"id":"PH-H15479-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Any law, ordinance, administrative order or designation or identification shall be considered\nrepealed or modified accordingly."}},{"id":"PH-H15479-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15480"] = {"id":"PH-H15480","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 649  An Act Exempting From Payment of Donor'S Tax, Donations of Private Agricultural Lands And/Or Homelots and Waivers of Compensation Under the Agrarian Reform Program, and for Other Purposes","orig":"Batas Pambansa Blg. 649  An Act Exempting From Payment of Donor'S Tax, Donations of Private Agricultural Lands And/Or Homelots and Waivers of Compensation Under the Agrarian Reform Program, and for Other Purposes"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 649","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 7 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00649_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00649_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15480-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The provisions of existing laws to the contrary notwithstanding, donations of private agricultural\nlands and/or homelots not covered by Operation Land Transfer (OLT) under Presidential Decree Numbered\nTwenty-seven, as amended, made to or in favor of tenant-farmers, actual tillers and/or occupants, pursuant to\nthe agrarian reform program of the government, shall be exempt from the payment of donor’s tax. Claims for\nexemption under this provision shall be allowed upon certification by the Ministry of Agrarian Reform that\nthe donee is a tenant-farmer, actual tiller and/or occupant of the land donated which, in no case, shall exceed a\nfamily-size farm and/or homelot area and that the donation conforms with the agrarian reform program of the\ngovernment. For purposes of this Act, the terms \"family-size farm and/or homelot area\" and \"tenant-farmer,\nactual tiller and/or occupant\" shall be understood in the sense that they are defined in existing laws, rules,\nregulations and guidelines establishing and implementing the land reform program of the government.\nThe certification shall be issued within sixty days from receipt of the request therefor.\nIn case the land donated is tenanted, in no case shall the security of tenure of the tenant be violated."}},{"id":"PH-H15480-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"No land and/or homelot donated under the provisions of this Act shall be further transferred to\nanybody except by hereditary succession or to the government. Any violation of this provision will subject the\ndonee to liability for the payment of the donor’s tax."}},{"id":"PH-H15480-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The tax exemption provided under Section 1 hereof can also be availed of by a landowner\ncovered by Operation Land Transfer (OLT) or his successor-in-interest who waives his right to receive the\nwhole or the balance of the compensation due him from the Land Bank of the Philippines or the\nfarmer-beneficiary, as the case may be, and in such case the tenant-farmer shall be relieved of the obligation\nto pay the amount waived. Claims for exemption under this provision shall be allowed upon certification by\nthe Ministry of Agrarian Reform that the compensation waived has been determined to be in accordance with\nthe provisions of Presidential Decree Numbered Twenty-seven, as amended, and its implementing guidelines,\nwhich certification shall be issued within the period provided for in Section one hereof."}},{"id":"PH-H15480-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Fifty percent of the fair market value of the property donated as determined in the tax declaration\nof such property at least one year prior to the donation shall be a deduction against taxable income of the\ndonor in the year the donation is made. If the donation is in accordance with the immediately preceding\nsection, the deduction shall be the whole amount waived."}},{"id":"PH-H15480-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"The Minister of Finance, in consultation with the Minister of Agrarian Reform, and upon\nrecommendation of the Commissioner of Internal Revenue, shall promulgate the necessary rules and\nregulations for the effective implementation of this Act."}},{"id":"PH-H15480-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Any provision of this Act or any part thereof which may be declared unconstitutional shall not\naffect the other provisions hereof."}},{"id":"PH-H15480-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15481"] = {"id":"PH-H15481","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 650  An Act Changing the Name of the San Jose City National High School in the Province of Nueva Ecija to Constancio Padilla National High School","orig":"Batas Pambansa Blg. 650  An Act Changing the Name of the San Jose City National High School in the Province of Nueva Ecija to Constancio Padilla National High School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 650","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00650_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00650_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15481-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the San Jose City National High School in the Province of Nueva Ecija is changed\nto Constancio Padilla National High School."}},{"id":"PH-H15481-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15482"] = {"id":"PH-H15482","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 651  An Act Changing the Name of the Malita Agri-Business and Marine and Aquatic School of Technology to Southern Philippines Agri-Business and Marine and Aquatic School of Technology","orig":"Batas Pambansa Blg. 651  An Act Changing the Name of the Malita Agri-Business and Marine and Aquatic School of Technology to Southern Philippines Agri-Business and Marine and Aquatic School of Technology"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 651","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00651_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00651_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15482-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Malita Agri-Business and Marine and Aquatic School of Technology in the\nMunicipality of Manila, Province of Davao del Sur, is changed to Southern Philippines Agri-Business and\nMarine and Aquatic School of Technology."}},{"id":"PH-H15482-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
