  FT["PH-H15500"] = {"id":"PH-H15500","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 669  An Act Changing the Name of the North Central Elementary School in the Municipality of sta. Cruz, Province of Zambales, to Don Marcelo C. Marty Elementary School","orig":"Batas Pambansa Blg. 669  An Act Changing the Name of the North Central Elementary School in the Municipality of sta. Cruz, Province of Zambales, to Don Marcelo C. Marty Elementary School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 669","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00669_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00669_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15500-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the North Central Elementary School in the Municipality of Sta. Cruz, Province of\nZambales, is hereby changed to Don Marcelo C. Marty Elementary School, any law ordinance or regulation to\nthe contrary notwithstanding."}},{"id":"PH-H15500-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15501"] = {"id":"PH-H15501","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 670  An Act Changing the Name of Tiaong East Elementary School in the Municipality of Tiaong, Province of Quezon, to Escueta Memorial Elementary School","orig":"Batas Pambansa Blg. 670  An Act Changing the Name of Tiaong East Elementary School in the Municipality of Tiaong, Province of Quezon, to Escueta Memorial Elementary School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 670","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00670_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00670_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15501-A1","no":1,"noLabel":{},"text":{"en":"BATAS PAMBANSA Blg. 670\nAn Act Changing the Name of Tiaong East Elementary School in the Municipality of Tiaong, Province of\nQuezon, to Escueta Memorial Elementary School\nWHEREAS, the late Moises A. Escueta, former congressman for the First Congressional District of Quezon\nProvince and former mayor of the Municipality of Tiaong, Quezon, had done quite a greater deal in improving\nthe peace and order condition of the Municipality of Tiaong during his incumbency, which made Tiaong the\nmost peaceful town in Quezon Province;\nWHEREAS, the late mayor and congressman had spared no efforts in promoting the welfare of his\nconstituents, most particularly in the scholarship program for the poor but deserving students;\nWHEREAS, it is but fitting and proper that the late Moises A. Escueta, an energetic and devoted public\nservant, be honored and his memory perpetuated at least among the residents of the Municipality of Tiaong,\nQuezon: Now, therefore,"}}],"pack":"ph-p156"};
