  FT["PH-H15506"] = {"id":"PH-H15506","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 676  An Act Changing the Name of Lapulapu street in Danao City to Paulo G. Almendras street","orig":"Batas Pambansa Blg. 676  An Act Changing the Name of Lapulapu street in Danao City to Paulo G. Almendras street"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 676","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00676_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00676_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15506-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The street in Danao City, in the island of Cebu, Philippines, now known as Lapulapu Street, is\nhereby renamed, and shall be known as Paulo G. Almendras Street."}},{"id":"PH-H15506-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15507"] = {"id":"PH-H15507","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 678  An Act Amending Section One of Republic Act Numbered Twenty-One Hundred and Ninety-Five","orig":"Batas Pambansa Blg. 678  An Act Amending Section One of Republic Act Numbered Twenty-One Hundred and Ninety-Five"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 678","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00678_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00678_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15507-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Section one of the Republic Act Numbered Twenty-one hundred and ninety-five is amended to\nread as follows:\n\"Sec. 1. The barrios of Sibuco and Malayal and the sitios of Cawit-Cawit, Anungan, Parang-Parang, Mantibo,\nPanganuran, Sarawagan, Lawi-Lawi, Tigbuaya, Pantamalitog, Maga, Pangian, Malog, Paniran, Lintangan,\nLimason and Siluput in the Municipality of Siocon, Province of Zamboanga del Norte, are separated from said\nmunicipality to be known as the Municipality of Sibuco, same province, with the seat of government at the\npresent site of the barrio of Sibuco.\""}}],"pack":"ph-p156"};
