  FT["PH-H15513"] = {"id":"PH-H15513","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 684  An Act Changing the Name of Barangay Salvador Poblacion in the Municipality of Salvador, Province of Lanao Del Norte, to Barangay Balimbing","orig":"Batas Pambansa Blg. 684  An Act Changing the Name of Barangay Salvador Poblacion in the Municipality of Salvador, Province of Lanao Del Norte, to Barangay Balimbing"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 684","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00684_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00684_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15513-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of Barangay Salvador Poblacion in the Municipality of Salvador, Province of Lanao\ndel Norte, is changed to Barangay Balimbing."}},{"id":"PH-H15513-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15514"] = {"id":"PH-H15514","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 685  An Act Renaming Timog Avenue and East Avenue as Carlos P. Garcia Avenue","orig":"Batas Pambansa Blg. 685  An Act Renaming Timog Avenue and East Avenue as Carlos P. Garcia Avenue"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 685","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00685_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00685_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15514-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"It is hereby declared to be the policy of the government to honor former presidents in some\nappropriate manner, such as, but not limited to, naming streets, roads, avenues, boulevards, parks and other\npublic places and structures in their honor."}},{"id":"PH-H15514-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"In giving expression to this policy, two avenues in Quezon City, one known as Timog Avenue,\nfrom Quezon Boulevard Extension to Epifanio de los Santos Avenue, and the second, known as East Avenue,\nfrom the said Epifanio de los Santos Avenue to the Quezon Memorial Circle are hereby renamed \"President\nCarlos P. Garcia Avenue.\""}},{"id":"PH-H15514-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15515"] = {"id":"PH-H15515","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 686  An Act Changing the Name of 10th Avenue (East and West) in the City of Caloocan, Metropolitan Manila, to Daang Macario B. Asistio, Sr.","orig":"Batas Pambansa Blg. 686  An Act Changing the Name of 10th Avenue (East and West) in the City of Caloocan, Metropolitan Manila, to Daang Macario B. Asistio, Sr."},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 686","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00686_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00686_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15515-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of 10th Avenue (East and West) in the City of Caloocan, Metropolitan Manila, is\nchanged to Daang Macario B. Asistio, Sr."}},{"id":"PH-H15515-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
