  FT["PH-H15517"] = {"id":"PH-H15517","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 688  An Act Renaming Barangay Gintong Silahis of Quezon City to Barangay N.S. Amoranto","orig":"Batas Pambansa Blg. 688  An Act Renaming Barangay Gintong Silahis of Quezon City to Barangay N.S. Amoranto"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 688","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00688_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00688_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15517-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"In due recognition to the outstanding contributions of the late Quezon City Mayor Norberto S.\nAmoranto in the improvement of barangays and the development of Quezon City into a modern metropolis,\nBarangay Gintong Silahis in the first district of Quezon City is hereby renamed Barangay N. S. Amoranto."}},{"id":"PH-H15517-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
