  FT["PH-H15522"] = {"id":"PH-H15522","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 693  An Act Naming the National Road starting From the Junction in Carmen, Rosales, Pangasinan and Ending At the Junction of the Macarthur Highway in Binmaley, Pangasinan, the Speaker Eugenio Perez National Road","orig":"Batas Pambansa Blg. 693  An Act Naming the National Road starting From the Junction in Carmen, Rosales, Pangasinan and Ending At the Junction of the Macarthur Highway in Binmaley, Pangasinan, the Speaker Eugenio Perez National Road"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 693","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00693_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00693_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15522-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The National road from Barangay Carmen, Municipality of Rosales to the Municipality of\nBinmaley, both in the Province of Pangasinan traversing the municipalities of Sto. Tomas, Alcala, Bautista,\nBayambang, Malasiqui, Binmaley and San Carlos City is hereby named the Speaker Eugenio Perez National"}},{"id":"PH-H15522-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15523"] = {"id":"PH-H15523","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 694  An Act Authorizing the Honorable General Carlos P. Romulo, Former Minister for Foreign Affairs, to Display the National Colors and Affix the Great Seal of the Republic of the Philippines in Prominent Places At His Residence","orig":"Batas Pambansa Blg. 694  An Act Authorizing the Honorable General Carlos P. Romulo, Former Minister for Foreign Affairs, to Display the National Colors and Affix the Great Seal of the Republic of the Philippines in Prominent Places At His Residence"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 694","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00694_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00694_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15523-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Honorable General Carlos P. Romulo, former Minister for Foreign Affairs, is authorized to\ndisplay the national colors and the Great Seal of the Republic of the Philippines in prominent places at his\nresidence at all times for as long as he lives."}},{"id":"PH-H15523-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15524"] = {"id":"PH-H15524","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 695  An Act Changing the Name of the Old Provincial Capitol Building of the Province of Antique to Justice Calixto O. Zaldivar Memorial Hall of Justice","orig":"Batas Pambansa Blg. 695  An Act Changing the Name of the Old Provincial Capitol Building of the Province of Antique to Justice Calixto O. Zaldivar Memorial Hall of Justice"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 695","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00695_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00695_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15524-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The old provincial capitol building of the Province of Antique located in the Municipality of San\nJose shall hereafter be known and referred to as the Justice Calixto O. Zaldivar Memorial Hall of Justice."}},{"id":"PH-H15524-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15525"] = {"id":"PH-H15525","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 696  An Act Converting the Bacolod Murcia-Pandanon-Don Salvador Benedicto-Calatrava Road in the Province of Negros Occidental Into a National Road","orig":"Batas Pambansa Blg. 696  An Act Converting the Bacolod Murcia-Pandanon-Don Salvador Benedicto-Calatrava Road in the Province of Negros Occidental Into a National Road"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 696","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-09","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00696_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00696_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15525-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Bacolod Murcia-Pandanon-Don Salvador Benedicto-Calatrava Road in the Province of\nNegros Occidental is converted into a national road."}},{"id":"PH-H15525-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the improvement and maintenance of said road shall continue to be\nfunded out of the lump sum appropriation authorized under Batas Pambansa Blg. 640 for the repair and\nmaintenance of local roads until shall time that the maintenance funds for said road shall have been provided\nfor in the succeeding appropriations acts."}},{"id":"PH-H15525-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15526"] = {"id":"PH-H15526","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":42,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 697  An Act to Govern the Election of Members of the Batasang Pambansa on May 14, 1984 and the Selection of Sectoral Representatives thereafter, Appropriating Funds therefor and for Other Purposes","orig":"Batas Pambansa Blg. 697  An Act to Govern the Election of Members of the Batasang Pambansa on May 14, 1984 and the Selection of Sectoral Representatives thereafter, Appropriating Funds therefor and for Other Purposes"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 697","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-14","completenessNote":"全文，共 42 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00697_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00697_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15526-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Title and applicability. This Act shall be known and cited as \"The Law on the 1984 Batasang\nPambansa Election.\" It shall govern the election for the regular Batasang Pambansa which shall be held on\nMay 14, 1984, and the selection of sectoral representatives thereafter as provided by the Constitution."}},{"id":"PH-H15526-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Election and campaign periods. Unless otherwise fixed by the Commission on Elections,\nhereinafter referred to as the Commission, in special cases, the election period shall commence ninety days\nbefore the day of the election and shall end thirty days thereafter.\nThe campaign period for the election on May 14, 1984 shall commence on March 27 and shall end at\nmidnight of May 12, 1984. Campaigning shall be prohibited on Holy Thursday, Good Friday, the day before\nthe election and on election day.\nElection of Members from the Provinces and their Component Cities,\nHighly Urbanized Cities and Districts in Metropolitan Manila"}},{"id":"PH-H15526-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Voting by province and its component cities, by highly urbanized city or by district in\nMetropolitan Manila. All candidates shall be voted at large by the registered voters of their respective\nconstituencies. The candidates corresponding to the number of Member or Members to be elected in a\nconstituency who receive the highest number of votes shall be declared elected.\nArticle III\nSelection of Sectoral Representatives"}},{"id":"PH-H15526-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"Sectoral representatives. There shall be three sectors to be represented in the Batasang\nPambansa, namely: (1) youth; (2) agricultural labor; and (3) industrial labor whose representatives shall be\nselected by the President from the nominees of their respective sectors in the manner herein provided. Each\nsector shall be entitled to four representatives, two of whom shall come from Luzon, one from Vizayas, and\none from Mindanao: Provided, That the youth sector shall be entitled to two additional sectoral representatives\nwho shall be selected from any part of the country."}},{"id":"PH-H15526-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"Scope of the Sectors. The agricultural labor sector covers all persons who personally and\nphysically till the land as their principal occupation. It includes agricultural tenants and lessees, rural, workers\nand farm employees, owner-cultivators, settlers and small fishermen.\nThe industrial labor sector includes all non-agricultural workers and employees.\nThe youth sector embraces persons not more than twenty-five years of age."}},{"id":"PH-H15526-A6","no":6,"noLabel":{"en":"Section 6"},"text":{"en":"Selection of sectoral representatives. Not later than twenty days after the election of provincial,\ncity or district representatives, the most representative and generally recognized organizations or\n\naggroupments of members of the agricultural labor, industrial labor, and youth sectors, as attested to by the\nMinister of Labor and Employment, and the Ministers of Local Government and of Education, Culture and\nSports, respectively, shall in accordance with the procedures of said organizations or President their respective\nnominees for each slot allotted from each sector. The President shall appoint from among the nominees\nsubmitted by the aforementioned organizations or aggroupments the representatives of each sector.\nIn recognizing the most representative and generally recognized organizations or aggroupments, the Ministers\nof Agrarian Reform and of Agriculture, the Minister of Labor and Employment, and the Ministers of Local\nGovernment and of Education, Culture and Sports shall consider:\na) The extent of membership and activity of the organization or aggroupment which should be national;\nb) The responsiveness of the organization or aggroupment to the legitimate aspirations of its sector;\nc) The militancy and consistency of the organization or aggroupment in espousing the cause and promoting\nthe welfare of the sector consistent with that of the whole country;\nd) The observance by such organization or aggroupment of the rule of law; and\ne) Other analogous factors.\nThe President of the Philippines shall in writing notify the Secretary-General of the Batasang Pambansa of the\nappointment made by him of any sectoral representative.\nExcept as herein otherwise provided, sectoral representatives shall have the same functions, responsibilities,\nrights, privileges, qualifications and disqualifications as the representatives from the provinces and their\ncomponent cities, highly urbanized cities or district of Metropolitan Manila.\nRights of Political Parties"}},{"id":"PH-H15526-A7","no":7,"noLabel":{"en":"Section 7"},"text":{"en":"Political party. \"Political party\" or \"party\", when used in this Act, means an organized group of\npersons pursuing the same ideology, political ideals of platform of government and includes its branches and\ndivisions. To acquire juridical personality and to entitle it to the rights and privileges herein provided for\npolitical parties, a political party shall first be duly registered with the Commission. Any registered political\nparty that singly or in coalition with others fails to obtain at least three percent of the votes cast in the\nconstituency in which it nominated and supported a candidate or candidates in the election next following its\nregistration shall, after notice and hearing, be deemed to have forfeited such status as a registered political\nparty, in such constituency."}},{"id":"PH-H15526-A8","no":8,"noLabel":{"en":"Section 8"},"text":{"en":"Registration. Any organized group of persons seeking registration as a political party may file\nwith the Commission a verified petition attaching thereto its constitution, by-laws, program of government\nand such other relevant information as may be required by the Commission.\nThe Commission shall, after due notice and hearing, resolve the petition within ten days from the date it is\nsubmitted for decision.\nNo religious sect, and no organization that seeks to achieve its goals through violence shall be registered as a\npolitical party.\nExisting registered political parties need not register anew."}},{"id":"PH-H15526-A9","no":9,"noLabel":{"en":"Section 9"},"text":{"en":"Selection of party candidates. Any registered political party or coalition or political parties may\nhold its convention, caucus, consensus, conference or any such other methods to select its official candidates\nat any time before March 27, 1984."}},{"id":"PH-H15526-A10","no":10,"noLabel":{"en":"Section 10"},"text":{"en":"Submission of party nomination. The nomination of the official candidates of a registered\npolitical party or coalition of political parties, duly signed and attested under oath by its President or\nChairman, Secretary-General or any other party official duly authorized to do so, shall be personally filed by\nthe party officers concerned or their duly authorized representatives with the Commission or other officials\n\nauthorized by the Commission to receive such nominations, not later than March 27, 1984.\nNothing in this Act shall be construed as in any manner impairing the prerogative of any registered political\nparty or coalition of political parties to make changes in its official ticket at any time: Provided, however, That\nany candidate whose nomination has been withdrawn, revoked, recalled, set aside, or candidacy, remain as an\nindividual candidate and may be voted upon and elected. The inclusion of a candidate in the official ticket of a\nregistered political party shall not be given due course unless such candidate has filed a certificate of\ncandidacy not later than the date fixed herein, except as provided under Section 18 hereof."}},{"id":"PH-H15526-A11","no":11,"noLabel":{"en":"Section 11"},"text":{"en":"Coalition of political parties. Registered political parties shall have the right to coalesce and\ncombine or unite their forces and present common candidates in any constituency.\nNotice of such coalition or agreement to unite political forces of registered political parties shall be filed\npersonally by the party officers concerned or their duly authorized representatives with the Commission not\nlater than March 27, 1984 in the case of existing coalitions or agreements and thereafter within five days from\nsuch coalition or agreement.\nA political party may nominate and/or support candidates not belonging to it.\nEligibility of Candidates and Certificates of Candidacy"}},{"id":"PH-H15526-A12","no":12,"noLabel":{"en":"Section 12"},"text":{"en":"Qualifications of Members of the Batasang Pambansa. No person shall be elected Member of\nthe Batasang Pambansa unless he is a natural-born, is at least twenty-five years of age, able to read and write,\na registered voter in the political subdivision in which he shall be elected and a resident thereof for a period of\nnot less than six months immediately preceding the day of the election.\nA sectoral representative shall be a natural-born citizen of the Philippines, able to read and write, a resident of\nthe Philippines for a period of not less than one year immediately preceding the day of the election, a\nbona-fide member of the sector he seeks to represent, a registered voter, and on the day of the election, at least\ntwenty-five years of age, except the youth sector representative who should be at least eighteen and not more\nthan twenty-five years of age: Provided, however, That any youth sector representative who attains the age of\ntwenty-five years during his term shall continue in office until the expiration of his term."}},{"id":"PH-H15526-A13","no":13,"noLabel":{"en":"Section 13"},"text":{"en":"Effects of filing of certificate of candidacy. (1) Any person holding a public appointive office\nor position, including active officers and members of the Armed Forces of the Philippines and the Integrated\nNational Police, as well as officials and employees of government-owned and government-controlled\ncorporations and their subsidiaries, shall ipso facto cease in office or position as of the time he filed his\ncertificate of candidacy: Provided, however, That the Prime Minister the Deputy Prime Minister, the Members\nof the Cabinet, and the Deputy Ministers shall continue in the offices they presently hold notwithstanding the\nfiling of their certificates of candidacy.\n(2) Governors, mayors, members of the various sanggunians or barangay officials shall, upon filing a\ncertificate of candidacy, be considered on forced leave of absence from office."}},{"id":"PH-H15526-A14","no":14,"noLabel":{"en":"Section 14"},"text":{"en":"Change of political affiliation. Any person, including an elective official, may change his party\naffiliation for purposes of the election herein provided for.\nCases for disqualification based on change of political party affiliation or guest candidacy pending in the\nCommission or the Supreme Court shall not be affected by the provisions of this section."}},{"id":"PH-H15526-A15","no":15,"noLabel":{"en":"Section 15"},"text":{"en":"Certificate of candidacy. No person shall be eligible for election as Member of the Batasang\nPambansa unless he files a sworn certificate of candidacy not later than March 27, 1984.\nNo fee shall be collected for the filing thereof.\nNo person shall be eligible to be a candidate in more than one constituency and if he files certificates of\ncandidacy for more than one constituency, he shall not be eligible for any of them. However, before midnight\n\nof March 27, 1984, the person who has filed more than one certificate of candidacy may declare under oath\nthe constituency for which he desires to be a candidate and such declaration shall ipso facto cancel the\ncertificate of candidacy for the other constituency or constituencies.\nThe filing of a certificate of candidacy shall not affect whatever civil, criminal or administrative liabilities a\ncandidate may have incurred: Provided, however, That hearings of the case involving the same shall be\nsuspended during the election period, unless such hearings are sought by the candidate himself."}},{"id":"PH-H15526-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"Contents of certificate of candidacy. The certificate of candidacy shall state that the person\nfiling it is announcing his candidacy for the office of Member of the Batasang Pambansa and that he is eligible\nfor said office; the province and its component city or cities, highly urbanized city, or the district in\nMetropolitan Manila which he seeks to represent, as the case may be; the political party or coalition of\npolitical parties to which he belongs, if any, and whether he is the official candidate of such political party or\ncoalition, if such be the case; civil status, and if married, the full name of his or her spouse; his date of birth,\nresidence, and his post office address for all election purposes; his profession or occupation; the voting center\nwhere he is duly registered; that he will support and defend the Constitution of the Republic of the Philippines\nand will maintain true faith and allegiance thereto; that he will obey the laws and legal orders promulgated by\nthe duly constituted authorities; that the obligation imposed by his oath is assumed voluntarily, without mental\nreservation or purpose of evasion; and that the facts stated in the certificate of candidacy are true of his own\npersonal knowledge.\nA candidate may use in his certificate of candidacy the name by which he has been baptized, or the name\nregistered in the office of the local civil registrar, or any other name allowed under the provisions of existing\nlaws: Provided, That when there are two or more candidates for an office with the same name and surname,\neach candidate, upon being made aware of such fact, shall state his paternal and maternal surnames, except the\nincumbent who may continue to use the name and surname stated in his certificate of candidacy when he was\nelected. He may also include one nickname or stage name by which he is generally or popularly known in the\nThe person filing a certificate of candidacy shall also affix his latest passport-size photograph and a statement\nin duplicate containing his bio-data.\nIn case a candidate has a pending petition for his inclusion as a voter in the constituency where he seeks to be\nelected or is the respondent in a petition for exclusion, his certificate of candidacy shall be allowed and given\ndue course subject to the outcome of the petition. Any decision on a petition for inclusion or exclusion which\naffects the qualification of a candidate may be elevated for review to the Commission on Elections."}},{"id":"PH-H15526-A17","no":17,"noLabel":{"en":"Section 17"},"text":{"en":"Filing and distribution of a certificate of candidacy. (a) The certificate of candidacy of a person\nrunning for election as representative of a province and its component city or cities, highly urbanized city, or\ndistrict in Metropolitan Manila, shall be filed in five legible copies on any day not later than March 27, 1984\nwith the Provincial Election Supervisor, City or Municipal Election Registrar or the Commission, as the case\nmay be: Provided, That in cases of postponement or failure of election, no additional certificate of candidacy\nshall be accepted except in cases of substitution of candidates as prescribed in this Act. In case there are two\nor more election registrars in a district of Metropolitan Manila, the Commission shall designate the election\nregistrar authorized to receive certificates of candidacy.\nThe candidate shall, in addition, file legible copies of his certificate of candidacy equivalent to double the\nnumber of voting centers in the province and its component city or cities, highly urbanized city of district in\nMetropolitan Manila, as the case may be.\n(b) The Provincial Election Supervisor or Election Registrar, as the case may be, shall immediately forward\nthe certificate of candidacy by registered mail to the Commission. The additional copies of the certificate of\ncandidacy shall be distributed to the voting center within his territorial jurisdiction through the municipal or\ncity treasurer, together with the official ballots, election returns and other election forms or paraphernalia."}},{"id":"PH-H15526-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"Candidates in case of death, withdrawal or disqualification of another. If after the last day for\nthe filing of certificates of candidacy, an official candidate of a registered political party or coalition of\npolitical parties should die, withdraw or become disqualified for any cause, only a person belonging to, and\ncertified by the same political party or coalition of political parties may file a certificate of candidacy to\nreplace the candidate who died, withdrew or became disqualified. The substitute candidate nominated by the\npolitical party or coalition of political parties concerned may file his certificate of candidacy for the office\naffected in accordance with the preceding sections on or before mid-day of the day of the election. In the case\nof independent or partyless candidates, the provisions of Section 28 of Presidential Decree No. 1296, the 1978\nElection Code, shall apply.\nIf the death, withdrawal or disqualification should occur between the day before the election and mid-day of\nelection day, said certificate may be filed with any citizens election committee in the political subdivision\nwhere he is a candidate. The fact of such filing shall be disseminated by the Commission to all the voting\ncenters within the said political subdivision by and through all possible means."}},{"id":"PH-H15526-A19","no":19,"noLabel":{"en":"Section 19"},"text":{"en":"Withdrawal or cancellation of certificates of candidacy. No certificates of candidacy shall be\nconsidered withdrawn or cancelled unless the candidate files with the office with which he filed the same or\nwith the Commission, a sworn statement of withdrawal or cancellation at any time before the day of election.\nA certificate of candidacy shall be considered ipso facto cancelled from the moment the candidate concerned\naccepts, assumes or discharges any office or employment in the government or any of its subdivisions,\ninstrumentalities or agencies, or in any government-owned or controlled corporation, including its\nsubsidiaries.\nThe fact of such withdrawal or cancellation shall be disseminated by the Commission to the public and all\nvoting centers within the political subdivisions concerned by and through all possible means."}},{"id":"PH-H15526-A20","no":20,"noLabel":{"en":"Section 20"},"text":{"en":"Ministerial duty of receiving and acknowledging receipts. The Commission, Provincial\nElection Supervisor or City or Municipal Election Registrar shall have the ministerial duty to receive the\ncertificates of candidacy referred to herein as well as nominations of registered political parties or coalition of\nsuch parties and to immediately acknowledge receipt thereof: Provided, That in all cases the Commission may\nmotu proprio or upon a verified of a candidate or an interested party or registered political party or coalition of\npolitical parties, refuse to give due course to a certificate of candidacy if it is shown, after the person who filed\nsuch certificate shall have been given the opportunity to be heard, that said certificate has been presented and\nfiled to cause confusion among the voters by the similarity of the names of the registered candidates, together\nwith other circumstances which demonstrate that the candidate has no bona fide intention to run for the office\nfor which the certificate of candidacy has been filed and thus prevent a faithful determination of the true will\nof the electorate: and Provided, finally, That no case shall be initiated either motu proprio by the Commission\nor by verified petition after April 2, 1984; and all cases duly initiated or filed shall be decided by the\nCommission as expeditiously as possible.\nRegistration, Preparation of Lists of Voters and Voting Centers"}},{"id":"PH-H15526-A21","no":21,"noLabel":{"en":"Section 21"},"text":{"en":"Registration, preparation of lists and voting centers. The registration, preparation of the list and\nthe procedures for the inclusion and exclusion of voters, and such other matters in connection therewith shall\nbe governed by Presidential Decree No. 1896, dated January 11, 1984. The voting centers used for purposes of\nthe registration of voters under the said Decree shall be used for the election on May 14, 1984, without\nprejudice to such transfers, mergers or splitting of voting centers and establishment of new ones as may be\nauthorized by the Commission: Provided, however, That no voting center shall be transferred, merged, split,\ncreated or established within thirty days before May 14, 1984.\nEach voting center shall as far as practicable comprise a unit of contiguous and compact territory in every\nbarangay. Not later than March 17, 1984, the Commission shall, through its duly authorized representative,\n\npost in the city hall or municipal building, the office of the election registrar and as far as practicable in every\nbarangay hall a map of the city or municipality showing its division into territorial units corresponding to each\nvoting center with their respective boundaries and indicating therein all streets and alleys in populous areas\nand the location of each voting center. This map shall be kept posted until after the election.\nEach voting center shall be, as far as practicable at, ground level, of sufficient size to comfortably\naccommodate forty voters at a time outside the guard rail for the committee. It shall be located as far as\npracticable along a public road at the center of the barangay. A public school building, having the requirement\nprescribed herein, shall be preferred for use as a voting center. If no public school building is available, any\nother public building, a private school building, or any other private building having the prescribed\nrequirements may be used, in that order of preference: Provided, however, That no voting center shall be\nlocated in a building owned, leased, or occupied by any candidate or of any person who is related to any\ncandidate within the third civil degree of consanguinity or affinity, or of any officer of the government,\nincluding barangay officials, or of any officer or leader of any political party: Provided, further, That no\nvoting center shall be located inside a military camp."}},{"id":"PH-H15526-A22","no":22,"noLabel":{"en":"Section 22"},"text":{"en":"Posting of list of candidates. The Commission shall post inside each polling booth above the\nwriting board and in some other conspicuous places in the voting center on the day before the election a\ncertified list containing the names of all the candidates to be voted for, arranged in such a manner as shall not\ngive undue advantage to any candidate, and printed in bold and legible form, and shall at all times during the\nvoting period keep such list posted in said places. It shall be unlawful for any person to deface, tear, mutilate,\ndestroy or remove such list."}},{"id":"PH-H15526-A23","no":23,"noLabel":{"en":"Section 23"},"text":{"en":"Transfer of voting centers due to conditions of peace and order. In case the Commission finds\nmotu proprio or upon verified petition if any candidate, registered political party or coalition of political\nparties, or a majority of the registered voters in the affected voting center, or of the citizens election\ncommittee, and after due notice and hearing that the conditions of peace and order in a locality where the\nvoting center is located or its immediate vicinity are not conducive to the free, orderly and honest conduct of\nthe election and the exercise by the voters therein of their right of suffrage, or would expose them or other\nelection officials to danger to life and limb, it may order the voting centers to be transferred to another venue\nwithin the same locality, or if warranted, to the closest adjacent locality in the city or municipality or another\nadjacent city or municipality: Provided, That sufficient notice of such transfer shall be made to the voters,\ncandidates, political parties and coalition of political parties affected.\nArticle VII\nCitizens Election Committee"}},{"id":"PH-H15526-A24","no":24,"noLabel":{"en":"Section 24"},"text":{"en":"Composition and appointment of citizens election committee. The provisions of Presidential\nDecree No. 1896 providing for the composition and appointment of citizens election committee shall be\napplicable for purposes of the election on May 14, 1984: Provided, however, That subparagraph one of the\nsecond paragraph of Section 13 of Presidential Decree No. 1896 is hereby amended to read as follows:\n\"(1) Capability of the political party or coalition or aggroupment of political parties to wage a bona fide\ncampaign in the political subdivision or subdivisions concerned, as evidenced by its organization, the number\nand quality of its candidates and the number and quality of the parties in the coalition or aggroupment.\""}},{"id":"PH-H15526-A25","no":25,"noLabel":{"en":"Section 25"},"text":{"en":"Right to copy the list of the members of the citizens election committees. A registered political\nparty, coalition of political parties, candidate, or any civic, religious, business, professional, service, youth or\nany similar organizations duly authorized by the Commission to appoint watchers, or its or his duly authorized\nrepresentative shall have the right to copy the list of the members of every citizens election committee in any\nconstituency. Any change in the composition or membership of every citizens election committee shall be\ncommunicated to the former, Any violation of this right shall constitute an election offense.\nArticle VIII"}},{"id":"PH-H15526-A26","no":26,"noLabel":{"en":"Section 26"},"text":{"en":"Official watchers of candidates. Every registered political party, coalition of political parties\nand every independent candidate shall each be entitled to two watchers in every voting center. However, only\none of the two may serve at any given time.\nNo person shall be appointed watcher unless he is a qualified voter of the city or municipality, of good\nreputation and shall not have been convicted by final judgment of any election offense or of any other crime,\nmust know how to read and write Pilipino, English, Spanish or any of the prevailing local dialects, and not\nrelated within the fourth civil degree of consanguinity or affinity to the chairman or any member of the\ncitizens election committee in the voting center where he seeks appointment as a watcher.\nEach candidate, political party or coalition of political parties shall designate in every province, highly\nurbanized city or district in the Metropolitan Manila are, a representative authorized to appoint watchers,\nfurnishing the Provincial Election Supervisor or the City Election Registrar, as the case may be, the names of\nsuch representatives. The Provincial Election Supervisors shall furnish the Municipal Election Registrars and\nelection registrars of component cities with the list of such representatives.\nIn the case of Metropolitan Manila, the designations of the persons authorized to appoint watchers shall be\nfiled with the Commission on Elections, which shall furnish the list of such representative to the respective\nCity and Municipal Election Registrars."}},{"id":"PH-H15526-A27","no":27,"noLabel":{"en":"Section 27"},"text":{"en":"Other Watchers. Civic, religious, professional, business, service, youth and any other similar\norganizations, with prior authority of the Commission, shall be entitled collectively to appoint two watchers,\nin every voting center: Provided, however, That only one of the two may serve at any given time."}},{"id":"PH-H15526-A28","no":28,"noLabel":{"en":"Section 28"},"text":{"en":"Rights and duties of watchers. Upon entering the voting center, the watchers shall present and\ndeliver to the chairman of the citizens election committee his appointment, and forthwith, his name shall be\nrecorded in the minutes. The appointment of the watcher shall bear the personal signature or the facsimile\nsignature of the candidate or the duly authorized representative of the political party of coalition of political\nparties who appointed him or of organizations authorized by the Commission under Section 27. The watchers\nshall have the right to stay in the space reserved for them inside the voting center. They shall have the right to\nwitness and inform themselves of the proceedings of the citizens election committee, including its proceedings\nduring the registration of voters, to take notes of what they may see or hear, to take photographs of the\nproceedings and incidents, if any, during the counting of votes, as well as of election returns, tally boards and\nballot boxes, to file a protest against any irregularity or violation of law which they believe may have been\ncommitted by the committee or by any of its members or by any persons, to obtain from the committee a\ncertificate as to the filing of such protest or of the resolution thereon, to read the ballots after they shall have\nbeen read by the chairman, as well as the election returns after they shall have been completed and signed by\nthe members of the committee without touching them, but they shall not speak to any member of the\ncommittee, or to any voter, or among themselves, in such a manner as would distract the proceedings, and to\nbe furnished with a certificate of the number of votes cast for each candidate duly signed by all the members\nof the committee. Refusal of the members of the committee to sign and furnish such certificate shall constitute\nan election offense and shall be penalized under the 1978 Election Code.\nOfficial Ballots and Election Returns"}},{"id":"PH-H15526-A29","no":29,"noLabel":{"en":"Section 29"},"text":{"en":"Official ballots. The official ballots for the May 14, 1984 election shall be of uniform size and\ncolor and shall be provided at public expense. They shall be printed on a special paper with watermarks or\nother marks that will readily distinguish the ballot paper from ordinary paper and will prevent its imitation."}},{"id":"PH-H15526-A30","no":30,"noLabel":{"en":"Section 30"},"text":{"en":"Emergency ballots. The municipal treasurer shall not undertake the preparation of emergency\nballots, unless the political parties, coalition of political parties, candidates and the organizations collectively\nauthorized by the Commission to designate watchers have been sufficiently notified to send their\n\nrepresentatives."}},{"id":"PH-H15526-A31","no":31,"noLabel":{"en":"Section 31"},"text":{"en":"Distribution of official ballots and election returns. The official ballots and the election returns\nshall be distributed by the Commission to each province with its component cities, highly urbanized city and\ndistrict in Metropolitan Manila at the rate of one and one-half ballots for every voter registered in each voting\ncenter; and for election returns, at the rate of one set each for every voting center.\nThe provincial, city or municipal treasurer shall respectively keep a record of the official ballots and election\nreturns furnished the various provinces with their component cities, highly urbanized cities, districts and\nvoting centers, as the case may be, copy of which record shall be furnished the Commission immediately after\nthe distribution is made.\nNo official ballot or election return shall be delivered to the citizens election committee earlier than the first\nhour of election day: Provided, however, That the Commission, after notice to the registered political parties\nor coalition of political parties, and the candidates, may, for justifiable reasons, authorize the delivery of\nofficial ballots and election returns to the committee of any particular voting center at an earlier time."}},{"id":"PH-H15526-A32","no":32,"noLabel":{"en":"Section 32"},"text":{"en":"Committee on printing and distribution of official ballots and election returns. The Commission\nshall appoint a committee of five members, two of whom shall be from among its personnel, the third to be\ndesignated by the Commission on Audit, and the last two to be designated by the political parties entitled to\nappoint inspectors pursuant to Presidential Decree Nos. 1896 and 1898, to act as its representatives in\nsupervising the printing of official ballots and election returns.\nUpon the request of any candidate, political party or coalition of political parties, or of civic, religious,\nprofessional, business, service, youth, or any similar organizations collectively designated by the Commission,\nthe latter shall allow any person designated by any of the former as watcher to observe the proceedings of the\ncommittee on the printing of official ballots and election returns, file objections, if any, witness the printing of\nthe ballots and the returns and guard the premises of the printer.\nThe ballots and election returns shall be printed by the Government Printing Office, but should the\nGovernment Printing Office not have the necessary facilities and materials and if for lack of time it cannot\nmeet the requirements of the Commission, the Commission may engage the services of a reputable printer\nafter hearing following due notice to registered political parties, coalition of political parties and such\norganizations are allowed watchers in the printing and distribution of ballots and election returns. In no case\nshall the Government Printing Office subcontract the printing of the ballots and the election returns."}},{"id":"PH-H15526-A33","no":33,"noLabel":{"en":"Section 33"},"text":{"en":"Duties of the committee on printing of official ballots and election returns. Under such orders\nor instructions as the Commission may issue, and in addition to general supervision and control over the\nprinting and shipment of official ballots and election returns, the committee on printing of official ballots and\nelection returns shall (a) paraphernalia used in the printing of official ballots and election returns are stored\nand where printed official ballots and election returns are packed and prepared for shipment, (b) supervise all\naspects relating to the printing, storage and shipment of official ballots and election returns and report to the\nCommission any irregularity which they believe may have been committed, and (c) perform such other related\nfunctions as the Commission may direct."}},{"id":"PH-H15526-A34","no":34,"noLabel":{"en":"Section 34"},"text":{"en":"Representatives of candidates, registered political parties or coalition of political parties in the\nverification and distribution of official ballots and election returns. Thirty days before election day,\ncandidates, registered political parties or coalition of political parties or their respective duly authorized\nrepresentatives in the different provinces with their component cities, highly urbanized cities and districts in\nthe Metropolitan Manila area shall submit the names of their respective watchers who, together with the\nrepresentative of the Commission and the provincial, city and municipal treasurer, shall verify the contents of\nthe boxes containing the shipment of official ballots, election returns and sample official ballots received by\nthe said treasurers. The provincial treasurer shall keep a record of their receipt and distribution to each\nmunicipal treasurer, while the city and municipal treasurers shall each keep a record of their distribution to the\n\ncitizens election committees.\nCasting of Votes"}},{"id":"PH-H15526-A35","no":35,"noLabel":{"en":"Section 35"},"text":{"en":"Voting hours. The casting of votes shall start at seven o’clock in the morning and shall end at\nfour o’clock in the afternoon, except when there are voters present within thirty meters in front of the voting\ncenter who have not yet cast their votes, in which case the voting shall continue but only to allow said voters\nto cast their votes without interruption. The poll clerk shall, without delay, prepare a complete list containing\nthe names of said voters consecutively numbered, and the voters shall be called to vote in the order in which\nthey are listed. Any voter in the list who is not present when his name is called out shall not be permitted to"}},{"id":"PH-H15526-A36","no":36,"noLabel":{"en":"Section 36"},"text":{"en":"Persons allowed in and around the voting center. On election day, no person shall be allowed\ninside the voting center, except the members of the election committee, the watchers, the representatives of\nthe Commission, the voters casting their votes, the voters waiting for their turn to get inside the booth whose\nnumber shall not exceed twice the number of booths and the voters waiting for their turn to cast their votes\nwhose numbers shall not exceed twenty at any one time. The watchers shall stay only in the space reserved for\nIt shall be unlawful for any officer or member of the Armed Forces of the Philippines, including the Philippine\nConstabulary, or the Integrated National Police or peace officer or any armed person belonging to any\nextralegal police agency, special forces, reaction forces, strike forces, home defense forces, barangay\nself-defense units, barangay tanods, or other similar forces, or para-military forces, including special guards,\nsecurity agents, special policemen, and all other kinds of armed or unarmed extralegal police officers or\npersonnel to enter any voting center, unless it is his voting center where he will vote but in such case he\nshould immediately leave the voting center, and within a radius of fifty meters from such voting center; and\nno policeman or peace officer shall be allowed to enter or stay inside the voting center except when there is an\nactual disturbance of the peace and order therein. However, the committee, upon a majority vote, if it deem\nnecessary, for the detail of a policeman or any peace officer for their protection or for the protection of the\nelection documents and paraphernalia, in which case, the said policeman or peace officer shall stay outside the\nvoting center within a radius of thirty meters near enough to be easily called by the committee at any time, but\nnever inside the voting center or at the door thereof and in no case shall the said policeman or peace officer\nhold any conversation with any voter or disturb or prevent or in any manner obstruct the free access of the\nvoters to the voting center. It shall likewise be unlawful for any barangay official to enter and stay inside any\nvoting center except to vote, in which case, he shall leave the voting center immediately after voting, except as\nwatcher, inspector, or when summoned by the committee upon a majority vote for the same purpose as stated\nin this section."}},{"id":"PH-H15526-A37","no":37,"noLabel":{"en":"Section 37"},"text":{"en":"Thumbprinting on minutes of voting and counting of votes. Every member of the citizens\nelection committee shall likewise affix the imprint of the thumb of his right hand on the minutes of voting and\ncounting of votes."}},{"id":"PH-H15526-A38","no":38,"noLabel":{"en":"Section 38"},"text":{"en":"Rights of watchers to obtain copies of the minutes of voting and counting. The duly authorized\nwatchers of candidates, political parties or coalition of political parties and of civic, religious, professional,\nbusiness, youth, service or any other similar organization collectively authorized by the Commission to\ndesignate watchers shall have the right to obtain certified copies, duly signed by all the members of the\ncommittee, of the minutes of voting and counting. Denial of this right shall constitute an election offense."}},{"id":"PH-H15526-A39","no":39,"noLabel":{"en":"Section 39"},"text":{"en":"Illiterate of disabled voters. A registered voter who is illiterate or physically unable to prepare\nthe ballot by himself may enlist the assistance of a relative within the fourth degree of consanguinity or the\npoll clerk of the citizens election committee or any public of private school teacher in the preparation of his\nballot. The person thus chosen shall, before being allowed to assist the illiterate or disabled voter, bind himself\nin a formal document under oath to fill out the ballot strictly in accordance with the instructions of the voter\n\nand not to reveal the contents of the ballot prepared by him. Thereafter, he shall accompany the illiterate or\ndisabled voter inside the voting booth and there proceed to prepare the ballot for the latter. No person shall be\nallowed to vote as an illiterate voter unless his voter’s affidavit shows that he had registered himself as such.\nOther than those herein authorized, no government official or employee, elective or appointive, including\nbarangay tanods and members of barangay brigades, may be allowed to assist illiterate or disabled voters to\nCounting of Votes"}},{"id":"PH-H15526-A40","no":40,"noLabel":{"en":"Section 40"},"text":{"en":"Rules for appreciation of ballots. In addition to the rules for the appreciation of the ballots\nprovided under Section 155 of the 1978 Election Code, the following rules shall be included:\n(1) Where only the first name of a candidate is written on the ballot, which when read, has a sound similar to\nthe surname of another candidate, the vote shall be counted in favor of the candidate with such surname. If\nthere are two or more candidates with the same full name, first name or surname and one of them is the\nincumbent, and on the ballot is written only such full name, first name or surname, the vote shall be counted in\nfavor of the incumbent.\n(2) In case the candidate is a woman who uses her maiden or married surname or both and there is another\ncandidate with the same surname, a ballot bearing only such surname shall be counted in favor of the\ncandidate who is an incumbent.\n(3) When two or more words are written on the same line on the ballot, all of which are the surnames of two\nor more candidates, the same shall not be counted for any of them, unless one is a surname of an incumbent in\nwhich case it shall be counted in favor of the latter.\nThe rules Section 140, 154, and 155 of the 1978 Election Code, as amended, referring to block voting,\nincluding the requirement on the printing of the names of candidates in the official ballot, shall not be\napplicable in the election of the regular Batasang Pambansa on May 14, 1984."}},{"id":"PH-H15526-A41","no":41,"noLabel":{"en":"Section 41"},"text":{"en":"Election Returns. The citizens election committee shall prepare the statement of the count\ncommonly known as the election returns, simultaneously with the counting of the votes as prescribed in"}},{"id":"PH-H15526-A154","no":154,"noLabel":{"en":"Section 154"},"text":{"en":"of the 1987 Election Code, as amended. The statement shall be prepared in sextuplicate. Each\nvote read shall be recorded by the poll clerk on the election returns by means of a vertical line, and every fifth\nvote for the same candidate shall be tallied with a diagonal line across the four vertical lines previously tallied.\nThe entry of votes in words and in figures in parenthesis for each candidate shall be closed with the signature\nand the clear imprint of the thumb of the right hand of all the members present, likewise to be affixed in full\nview of the public immediately after the last vertical line, or immediately after the name of the candidate who\ndid not receive any vote.\nThe statement shall also show the date of the election, the name of the municipality and the number of the\nvoting center in which it was held, the total number of ballots found in the compartment for valid ballots, the\ntotal number of ballots withdrawn from the compartment for spoiled ballots because they were erroneously\nplaced therein, the total number of excess ballots, the total number of rejected ballots, and the total number of\nvotes polled by each candidate, writing out the said number in words and figures, and, at the end of the\nstatement, the committee shall make a certificate signed by all its members present that the contents are\ncorrect. The statement should be contained, if possible, in a single sheet of paper, but, if this is not possible,\neach additional sheet of every copy shall be prepared in the same manner as the first sheet and likewise signed\nby all the members of the committee.\nThe Commission shall take steps to ensure that the original copy of the election returns is clearly reproduced\nin its entirely in one instance on the second, third, fourth, fifth, and sixth copies thereof, and for this purpose\nthe Commission shall acquire, if necessary, a special kind of carbon paper or chemically-treated paper.\nImmediately upon the accomplishment of the election returns, each copy thereof shall in the presence of the\n\nwatchers and the public be placed in the envelope especially designed for the purpose, and distributed as\nprovided herein.\nSection 42. Disposition of election returns. The original of the election returns shall be delivered to the\nelection registrar of the city or municipality for transmittal to the Chairman of the Provincial Board of\nCanvassers in the provinces, and direct to the chairman of the city or district board of canvassers in the\nurbanized cities and the district of Metropolitan Manila, as the case may be, for use in the canvass. The second\ncopy shall be deposited in the compartment for valid ballots. The fourth copy shall be kept by the election\nregistrar for use in the tabulation of the advance results of the election in the city or municipality. The fifth\nand sixth copies shall each, respectively, be delivered to the members representing the political parties\nrepresented in the citizens election committee.\nSection 43. Preservation of the list of voters with voting records. The list of voters with the voting record of\neach voting center shall be delivered to the election registrar who shall have custody of the same, keeping\nthem in a safe place, subject to the instruction of the Commission.\nArticle XII\nCanvass and Proclamation\nSection 44. Board of canvassers. There shall be a board of canvassers for each province, highly urbanized\ncity and district of Metropolitan Manila to be composed as follows:\n(1) The Provincial Board of Canvassers shall be composed of the Provincial Election Supervisor, as chairman,\nthe Provincial Fiscal, as vice-chairman, and the Provincial Superintendent of Schools, and one representative\nfrom each of the ruling party and the dominant opposition political party in the constituency concerned\nentitled to be presented, as members.\n(2) The City Board of Canvassers shall be composed of the City Election Registrar or a lawyer of the\nCommission, as chairman, and the City Fiscal and the City Superintendent of Schools, and one representative\nfrom each of the ruling party and the dominant opposition political party entitled to be represented, as\n(3) The District Board of Canvassers in the case of Metropolitan Manila shall be composed of a lawyer of the\nCommission, as chairman, and a ranking fiscal in the district and the most senior district school supervisor in\nthe district to be appointed upon consultation with the Ministry of Justice and the Ministry of Education,\nCulture and Sports, respectively, and one representative from each of the ruling party and the dominant\nopposition political party in the constituency concerned, as members.\nA majority of the members of the Board shall constitute a quorum for the transaction of business.\nIn no case shall the chairman and the members of the provincial, city, or district board of canvassers, as the\ncase may be, be related within the fourth civil degree of consanguinity or affinity to any of the candidates in\ntheir respective jurisdiction.\nIn all three cases, the provisions of Presidential Decree No. 1896, as amended, on the manner of determining\nthe dominant opposition political party in any particular constituency shall apply. For purposes of the election\nherein provided for, the term \"dominant opposition political party\" includes a coalition or aggroupment of\nopposition political parties.\nSection 45. Watchers. Each candidate, political party or coalition of political parties shall be entitled to\nappoint watchers to be present at, and take note of, all the proceedings of the Board of Canvassers. The\nwatchers shall have the right to file a protest in any case of irregularity.\nSection 46. Manner of delivery and of transmittal of election returns. The copy of the election returns of a\nvoting center intended for the Board of Canvassers, duly placed inside a sealed envelope signed and affixed\nwith the imprint of the thumb of the right hand of all the members of the committee, shall be personally\ndelivered by the members of the committee to the election registrar for transmittal to the Board of Canvassers.\n\nThe watchers of the political parties, coalition of political parties and the candidates shall have the right to\naccompany the members of the committee in making the delivery.\nThe election registrar concerned shall place have all the returns intended for the Board of Canvassers inside a\nballot box provided with three padlocks whose keys shall be kept as follows: one by the election registrar,\nanother by the representative of the ruling party, and the third by the representative of the dominant political\nopposition party.\nFor this purpose, the two political parties shall designate their representatives, whose names shall be submitted\nto the election registrar concerned on or before the tenth day preceding the election. The three in possession of\nthe keys shall personally transmit the ballot box, properly locked, containing the election returns to the Board\nof Canvassers. Watchers of political parties, coalition of political parties, and of organizations collectively\nauthorized by the commission to designate watchers shall have the right to accompany transmittal of the ballot\nboxes containing the election returns.\nIt shall be unlawful for any person to delay, obstruct, impede or prevent through force, violence, coercion,\nintimidation or by any means which vitiates consent, the transmittal of the election returns or to take away,\nabscond with, destroy, deface or mutilate or substitute the election returns or the envelope or the ballot box\ncontaining the election returns or to violate the right of the watchers.\nSection 47. Safekeeping of transmitted election returns. The Board of Canvassers shall keep the ballot\nboxes containing the election returns in a safe and secure room before and after the canvass. The door to the\nroom must be padlocked by three locks with the keys thereof kept as follows: one with the chairman, the other\nwith the representative of the ruling party, and the other with the representative of the dominant opposition\npolitical party. The watchers of candidates, political parties, coalition of political parties an organizations\ncollectively authorized by the Commission to appoint watchers shall have the right to guard the room.\nViolation of this right shall constitute an election offense.\nSection 48. Canvass by the board. The Board of Canvassers shall meet not later than seven o’clock in the\nevening of election day at the place designated by the Commission to canvass the election returns that may\nhave already been received. It shall meet continuously from day to day until the canvass is completed, and\nmay adjourn but only for the purpose of awaiting the other election. Each time the board adjourns, it shall\nmake a total of all the votes canvassed so far for each candidate affixing their signatures, and thumbmarks\nafter each total, furnishing the Commission in Manila by the fastest means of communication a certified copy\nthereof, and making available the data contained therein to the mass media and other interested parties. As\nsoon as the other election returns as delivered the board shall immediately resume canvassing until the returns\nhave been canvassed.\nThe respective Board of Canvassers shall prepare a certificate of canvass, duly signed and affixed with the\nimprint of the thumb of the right hand of each member, supported by a statement of the votes received by each\ncandidate in each voting center and on the basis thereof, shall proclaim as elected the candidates who obtained\nthe highest number of votes.\nSection 49. Persons not allowed inside the canvassing room. It shall be unlawful for any officer or member\nof the Armed Forces of the Philippines, including the Philippine Constabulary, or the Integrated National\nPolice or any peace officer or any armed or unarmed persons belonging to an extra-legal police agency,\nspecial forces, reaction forces, strike forces, home defense forces, barangay self-defense units, barangay\ntanods, except those designated as members of the Board or as watchers, or of any member of the security or\nthe police organizations of government ministries, commissions, councils, bureaus, offices, instrumentalities,\nor government-owned or controlled corporations or their subsidiaries or of any member of a privately-owned\nor operated security, investigative, protective or intelligence agency performing identical or similar functions\nto enter the room where the canvassing of the election returns are held by the Board of Canvassers and within\na radius of fifty meters from such room: Provided, however, That the committee, by a majority vote, if it\ndeems necessary, may make a call in writing for the detail of policemen or any peace officers for their\n\nprotection or for the protection of the election documents and paraphernalia in the possession of the board, or\nfor the maintenance of peace and order, in which case said policemen of peace officer, who shall be in proper\nuniform, shall stay outside the room within a radius of thirty meters near enough to be easily called by the\nboard at any time.\nArticle XIII\nPre-Proclamation Controversy\nSection 50. Definition. Pre-proclamation controversy refers to any question pertaining to or affecting the\nproceedings of the Board of Canvassers which may be raised by any candidate, political party or coalition of\npolitical parties before the board or directly with the Commission.\nThe Commission on Election shall be the sole judge and shall have exclusive jurisdiction over all\npre-proclamation controversies.\nThe Commission is hereby vested with exclusive authority to hear and decide petitions for certiorari,\nprohibition and mandamus involving election cases.\nSection 51. Issues that may be raised in pre-proclamation controversy. The following shall be proper issues\nthat may be raised in a pre-proclamation controversy:\n(a) Illegal composition or proceedings of the Board of Canvassers;\n(b) Canvassed election returns are incomplete, contain material defects, appear to be tampered with or\nfalsified, of contain discrepancies in the same returns or other authentic copies thereof;\n(c) When the election returns were prepared under duress, threats, coercion, or intimidation, or are obviously\nmanufactured, or not authentic;\n(d) When substitute, fictitious or illegal voters, constituting a majority of the registered voters in the voting\ncenter, were able to vote; or\n(e) Other matters related to or in connection with the canvass of election returns or proclamation of any\nSection 52. Issues not proper in pre-proclamation controversy. The following are not proper issues that may\nbe raised in a pre-proclamation controversy;\n(a) Frauds, terrorism, irregularities or illegal acts committed before or during the casting and counting of\nvotes, except as provided in paragraph (b), (c) and (d) of the preceding section;\n(b) Disqualification of candidates under any existing laws; or\n(c) Any other matter not related to or not in connection with the canvass of election returns or proclamation of\nany candidate, or issues that properly pertain to an election protest or quo warranto proceedings.\nSection 53. Contested composition or proceedings of the board. When the composition or proceedings of\nthe board is contested, it shall immediately make a ruling thereon with notice to the party contesting who, if\nadversely affected, may after the matter to the Commission within five days after the ruling, with proper\nnotice to the board. The Commission, after due notice and hearing, shall decide the case within ten days from\nthe filing of the case. During the pendency of the case, the board shall suspend the canvass unless the\nCommission orders the continuation or resumption thereof.\nSection 54. Contested election returns. Any candidate, political party or coalition of political parties,\ncontesting the exclusion or inclusion in the canvass of any election returns shall submit their written\nobjections to the Chairman of the Board of Canvassers. The board shall defer the canvass of the contested\nreturns and shall not make any ruling thereon until after all the uncontested election returns have been\ncanvassed. The board shall not proclaim any winning candidate unless authorized by the Commission, and any\nproclamation made in violation hereof shall be void ab initio.\n\nThe ruling of the board may be elevated to the Commission by the party adversely affected, by filing a\nverified petition within five days from notice thereof. After due notice and hearing, the Commission shall\ndecide the case within ten days after the case has been submitted for resolution.\nSection 55. Summary proceedings before the Commission. All pre-proclamation controversies shall be\nheard summarily by the Commission after notice and hearing, and its decisions shall be immediately\nexecutory unless restrained by the Supreme Court.\nSection 56. Partial proclamation. Notwithstanding the pendency of any pre-proclamation controversy, the\nCommission may motu proprio, or upon the filing of a verified petition and after due notice and hearing, order\nthe proclamation of any winning candidate whose election will not be affected by the outcome of the\ncontroversy.\nSection 57. Effect of filing petition to annul or to suspend the proclamation. The filing with the\nCommission of a petition to annul or to suspend the proclamation of any candidate shall suspend the running\nof the period within which to file an election protest or quo warranto proceedings.\nArticle XIV\nElection Contests\nSection 58. Jurisdiction of the Commission. The Commission shall be the sole judge of all contests relating\nto the election, returns, selection or appointment, and qualifications of all Members of the Batasang\nSection 59. Election contests for Batasang Pambansa. A sworn petition contesting the election, selection or\nappointment of any Member of the Batasang Pambansa shall be filed with the Commission by any candidate\nwho has duly filed a valid and subsisting certificate of candidacy for the same office, or in case of sectoral\nrepresentatives, by any other aspirant for nomination to the office, within ten days after the proclamation of\nthe results of the election or the issuance of the appointment, as the case may be.\nSection 60. Petition for quo warranto. Any voter contesting the election, selection or appointment of any\nMember of the Batasang Pambansa on the ground of ineligibility or of disloyalty to the Republic of the\nPhilippines shall file a sworn petition for quo warranto with the Commission within ten days after the\nproclamation of the results of the election.\nSection 61. Suspension of period. The filing of a pre-proclamation petition shall suspend the running of the\nten-day period mentioned in Section 60 hereof.\nSection 62. Procedure in election contests. The Commission shall prescribed the rules to govern the\nprocedure and other matters relating to election contests pertaining to the Members of the Batasang Pambansa.\nSuch rules shall provide a simple and inexpensive procedure for the expeditious disposition of election\nSection 63. Decision by the Commission. The Commission shall decide all election contests within ninety\ndays from the date of their submission for decision. The decision of the Commission shall become final ten\ndays after promulgation, unless a motion for reconsideration shall have been filed. Motions for\nreconsideration shall be resolved within thirty days from its filing.\nElection Offenses\nSection 64. Prohibited acts. In addition to the prohibited acts provided in the 1978 Election Code, or\ndeclared unlawful or as an election offense in the preceding articles of this Act, the following shall be guilty\nof an election offense:\n(a) Wearing of uniform and bearing arms by military units. During the campaign period, on the day before, on\nelection day, and ending thirty days thereafter, any members of the Armed Forces of the Philippines, Special\nForces, Home Defense Forces, Barangay Self-Defense Unit and all other para-military units that now exist or\n\nwhich may hereafter be organized who wears his uniform or bears arms outside the camp, garrison or barracks\nto which he is assigned or detailed or outside his home, in case of members of Home Defense Forces,\nBarangay Self-Defense Units, and other para-military units, unless (1) the President of the Philippines shall\nhave given previous authority therefor, and the Commission notified thereof in writing, or (2) the Commission\nauthorizes him to do so, which authority it shall give only when necessary to assist it in maintaining free,\norderly and honest elections, and only after notice and hearing. All personnel of the Armed Forces authorized\nby the President or the Commission to bear arms or wear their uniforms outside their camps and all police and\npeace officers shall bear their true name, rank and serial number, if any, stitched in block letters on a white\nbackground on the left breast of their uniform, in letters and numbers of a clearly legible design at least two\ncentimeters tall, which shall at all times remain visible and uncovered.\nDuring the election period, whenever the Commission finds it necessary for the promotion of free, honest,\norderly and peaceful elections in a specific area, it shall confiscate or order the confiscation of firearms of any\nmember or members of the Armed Forces of the Philippines, Police Forces, Special Forces, Home Defense\nForces, Barangay Self-Defense Units, and all other para-military units that now exist or may hereafter be\norganized, or of any member or members of the security or police organization of government ministries,\ncommissions, councils, bureaus, offices, instrumentalities, or government-owned or controlled corporations\nand their subsidiaries, or of any member or members of privately-owned or operated security, investigative,\nprotective or intelligence agencies performing identical or similar functions.\n(b) Organization or maintenance of reaction forces, strike forces, or other similar forces. Any person who\norganizes or maintains or joins a reaction force, strike force or similar force during the election period.\nThe heads of all reaction forces, strike forces, or similar forces shall, not later than forty-five days before the\nelection, submit to the Commission a complete list of all members thereof with such particulars as the\nCommission may require.\n(c) Prohibition against release, disbursement or expenditure of public funds. Any public official or employee\nincluding barangay officials and those of government-owned or controlled corporations and their subsidiaries,\nwho, during forty-five days before the election day on May 14, 1984, releases, disburses or expends any\npublic funds for;\n(1) And any all kinds of public works, except the following:\n(aa) Maintenance of existing and/or completed public works projects: Provided, That not more than the\naverage number of laborers or employees already employed therein during the six-month period immediately\nprior to the beginning of the forty-five day period before election day shall be permitted to work during such\ntime: Provided, further, That no additional laborers shall be employed for maintenance work within the said\nperiod of forty-five days;\n(bb) Work undertaken by contract through public bidding held, or by negotiated contract awarded, before the\nforty-five day period before election: Provided, That work for the purpose of this section undertaken under the\nso-called \"takay\" or \"paquiao\" system shall not be considered as work contact;\n(cc) Payment for the usual cost of preparation of working drawings, specifications, bills of materials,\nestimates and other procedures preparatory to actual constitution including the purchase of materials and\nequipment, and all incidental expenses for wages of watchmen and other laborers employed for such work in\nthe central office and field storehouse before the beginning of such period: Provided, That the number of such\nlaborers shall not be increased over the number hired when the project or projects were commenced; and\n(dd) Emergency work necessitated by the occurrence of a public calamity, but such work shall be limited to\nthe restoration of the damaged facility.\nNo payment shall be made within five days before the date of election to laborers who have rendered services\nin projects or work except those falling under subparagraphs (aa), (bb), (cc), and (dd) of this paragraph.\n\nThis prohibition shall not apply to on-going public works projects commenced before the campaign period or\nsimilar projects under foreign agreements. For purposes of this provisions, it shall be the duty of the\ngovernment officials or agencies concerned to report to the Commission the list of all such projects being\nundertaken by them.\n(2) The Ministry of Social Services and Development and any other office in any other ministry of the\nGovernment performing functions similar to said Ministry, except for salaries of personnel, and for such other\nroutine and normal expenses, and for such other expenses as the Commission may authorized, after due notice\nand hearing. Should a calamity or disaster occur, all releases normally or usually coursed through the said\nministries and offices shall be turned over to, and administered and disbursed by, the Philippine National Red\nCross, subject to the supervision of the Commission on Audit or its representatives, and no candidate or his or\nher spouse or member of his or her family within the second degree of consanguinity or affinity shall\nparticipate, directly or indirectly, in the distribution of any relief of other goods to the victims of the calamity\nof disaster; and\n(3) The Ministry of human Settlements and any office in any other ministry of the Government performing\nfunction similar to said ministry, except for salaries of personnel and for such other necessary administrative\nor other expenses as the Commission may authorize after due notice and hearing.\n(d) Prohibition against construction of public works, delivery of materials for public works and issuance of\ntreasury warrants and similar devices. During the period of forty-five days preceding the election of May 14,\n1984, any person who (a) undertakes the construction of any public works, except for projects or works\nexempted in the preceding section; or (b) issues, uses or avails of treasury warrants or any device undertaking\nfuture delivery of money, goods or other things of value chargeable against public funds; or (c) who thereafter\nreceives any payment for the prohibited construction.\n(e) Suspension of elective provincial, city, municipal or barangay officer. During the election period, any\npublic official who suspends, without prior approval of the Commission, any elective provincial, city,\nmunicipal, or barangay official, unless said suspension will be for purposes of applying the \"Anti-Graft and\nCorrupt Practices Act\" in relation to the suspension and removal of elective officials, in which case the\nprovision of this section shall be inapplicable.\nSection 65. Increased penalty for specific election offenses. For purposes of the May 14, 1984 election, the\npenalty for the crimes defined in the following paragraphs of Section 178 of the 1978 Election Code,\nPresidential Decree No. 1296:\n(a) Vote buying and vote selling;\n(e) Threats, terrorism, use of fraudulent device and other forms of coercion; and\n(m) Use of armored land, water or air craft; is hereby increased to prision mayor, or six years and one day to\ntwelve years, with perpetual disqualification to hold public office or exercise the right of suffrage; Provided,\nThat if the commission of the crime should result in the death of any person, the penalty shall be reclusion\nperpetua to death.\nIf the offender is a public official or employee, he shall forfeit all benefits, gratuities or pensions due him from\nthe government by reason of his service.\nSection 66. Prosecution. The Commission shall have the exclusive power to investigate or prosecute all\nelection offenses punishable under this Act or other election laws. For this purpose, the Commission may\navail of the assistance of, and authorize other agencies of the government: Provided, however, That in the\nevent that the Commission fails to act on any compliant within six months from its filing, the complaint may\nfile the complaint with the office of the fiscal or with the Ministry of Justice for proper investigation and\nprosecution, if warranted.\nSection 67. Offenses committed during and in connection with the election campaign. No person shall be\n\narrested and/or detained at any time for any alleged offense committed during and in connection with the\nelection of Members of the Batasang Pambansa on May 14, 1984 through any act or language tending to\nsupport or oppose any candidate, political party, or coalition of political parties, under or pursuant to any order\nor whatever name or nature and by whatsoever issued, except only upon a warrant of arrest issued by a\ncompetent judge after all the requirement of the Constitution shall have been strictly complied with.\nIf the offense charged is punishable under a presidential decree, whether originally or by amendment of a\nprevious law, the death penalty shall not be imposed upon the offender except where murder, rape, or arson is\ninvolved. In all cases, the penalty shall not be higher than reclusion perpetua, and the offender shall be entitled\nto reasonable bail and sufficient sureties to be granted speedily by the competent court. Moreover, loss of the\nrightly or citizenship confiscation of property shall not be imposed.\nAny officer or person who shall violate any provision of this section shall be punishable by imprisonment of\nnot less than six years and one day nor more than twelve years, with the accessory penalties for election\noffenses. The provisions of section 66 of this Act shall not apply to prosecutions under this section.\nArticle XVI\nTransitory Provisions\nSection 68. Pending actions. Actions arising or already pending before the effectivity of this Act shall be\ngoverned by the laws then in force.\nSection 69. Reorganization of the Commission on Elections. In order to promote maximum efficiency in\ncarrying out its constitutional duty to insure free, orderly and honest elections and in discharging its judicial\npowers and functions under the Constitution, the Commission is hereby authorized, for purposes of the May\n14, 1984 election, to reorganize its offices, divisions or units, redistribute functions and reassign personnel,\nchange designations of existing positions subject to pertinent existing laws and salaries of its subordinate\nofficials and employees subject to the laws and regulations on civil service and compensation, position\nclassification and standardization of salaries: Provided, That no permanent official or employee already in the\nservice of the Commission, upon approval of this Act, shall be laid off or demoted in rank or salary: Provided,\nfurther, That there shall be no transfer of provincial election supervisors, election registrars, and other\nemployees of the Commission on Elections from one station to another within thirty days before the election,\nexcept for cause and after due notice and hearing.\nSection 70. Appropriations. The costs of holding the election of Members of the Batasang Pambansa shall\nbe funded out of the current appropriations of the Commission on Elections, provided for this purpose. In case\nof deficiency, the funds so provided for this purpose may be augmented from the Special Activities Fund\nintended for special priority activities authorized in the current General Appropriations Act.\nArticle XVII\nFinal Provisions\nSection 71. Separability clause. If for any reason any section of provision of this Act, or any portion\nthereof, or the application of such section, provision or portion is declared invalid or unconstitutional, the\nremainder thereof shall not be effected by such declaration.\nSection 72. Applicability of Election Code of 1978 and other statutes. All provisions of the Election Code\nof 1978 and other electoral statutes not inconsistent with the provisions of this Act shall apply to the election\nherein provided for.\nSection 73. Repealing clause. All laws or parts or laws inconsistent herewith are hereby deemed repealed or\nmodified accordingly.\nSection 74. Effectivity of this Act. This Act takes effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15527"] = {"id":"PH-H15527","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 698  An Act Converting the Miag-Ao National Vocational High School in the Municipality of Miag-Ao, Province of Iloilo, Into a National Polytechnic College, to Be Known as the Southern Iloilo Polytechnic College and for Other Purposes","orig":"Batas Pambansa Blg. 698  An Act Converting the Miag-Ao National Vocational High School in the Municipality of Miag-Ao, Province of Iloilo, Into a National Polytechnic College, to Be Known as the Southern Iloilo Polytechnic College and for Other Purposes","vi":"Đạo luật chuyển đổi Trường Trung học Dạy nghề Miag-Ao Quốc gia tại Thị trấn Miag-Ao, Tỉnh Iloilo thành Cao đẳng Bách khoa Quốc gia với tên gọi Cao đẳng Bách khoa Southern Iloilo, và cho các mục đích khác","th":"พระราชบัญญัติเปลี่ยนสถานะโรงเรียนมัธยมศึกษาอาชีวศึกษา Miag-Ao แห่งชาติในเทศบาล Miag-Ao จังหวัด Iloilo เป็น วิทยาลัยโพลีเทคนิคแห่งชาติในชื่อวิทยาลัยโพลีเทคนิค Southern Iloilo และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang mengubah Sekolah Menengah Kejuruan Miag-Ao Nasional di Kotamadya Miag-Ao, Provinsi Iloilo menjadi Sekolah Tinggi Politeknik Nasional dengan nama Sekolah Tinggi Politeknik Southern Iloilo, dan untuk tujuan lain","ms":"Akta menukar status Sekolah Menengah Vokasional Miag-Ao Kebangsaan di Perbandaran Miag-Ao, Wilayah Iloilo kepada Kolej Politeknik Kebangsaan dengan nama Kolej Politeknik Southern Iloilo, dan untuk tujuan lain"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 698","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-03-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00698_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00698_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15527-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Miag-ao National Vocational High School in the Municipality of Miag-ao, Province of\nIloilo, is converted into a national polytechnic college to be known as the Southern Iloilo Polytechnic College."}},{"id":"PH-H15527-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"In addition to the secondary vocational course, the college shall offer undergraduate and\ngraduate courses, industrial technology, sciences, arts, and other courses as may be authorized by the Ministry\nof Education, Culture and Sports. It shall also offer short-term vocational courses."}},{"id":"PH-H15527-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"All personnel, assets, liabilities, records, and appropriations of the Miag-ao National Vocational\nHigh School are transferred to and shall be absorbed by the Southern Iloilo Polytechnic College."}},{"id":"PH-H15527-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The amount necessary for the operation and maintenance of the College shall be charged to the\nappropriations in Batas Pambansa Bilang 230 intended for the Miag-ao National Vocational High School\nunder the ministry of Education, Culture and Sports. Thereafter, such sum as may be necessary for the same\npurpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H15527-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 7, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15528"] = {"id":"PH-H15528","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 699  An Act Creating the Municipality of Cardinal Rosales in the Province of Samar","orig":"Batas Pambansa Blg. 699  An Act Creating the Municipality of Cardinal Rosales in the Province of Samar"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 699","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-02","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00699_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00699_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15528-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Barangays Bacjao, Burgos, Cabilisan, Calawan-an, Candugue, Canloloy, Cansaganay,\nGuindaponan, Guintamipilan, Iquiran, Mabini, Macalpe, Mandoyocan, Mayabay, Pondang, Poso, Saugan,\nSua, Tuga, and Ubo, including the islets of Bascal and Agutay, all in the Municipality of Daram, Province of\nSamar are hereby separated from the said municipality in the same province to be known as the Municipality\nof Cardinal Rosales. The seat of the municipal government shall be in the present site of Barangay"}},{"id":"PH-H15528-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The new Municipality of Cardinal Rosales shall be bounded as follows:\n\"From the BBM No. 41 facing Samar Sea in the west portion (point 1); thence N 59-20 W, 1,395 M. to point\n2; thence N 43-15 W, 1,150 M. to point 3; thence N 19-20 E, 1,220 M. to point 4; thence S 49-50 E; 3,000 M.\nto point 5, (coconut tree along Burabod Creek); thence N 15-30 W, 995 M. to point 6; thence S 78-30 E, 1,850\nM. to point 7; thence N 35-60 W, 3,620 M. to point 8; thence S 47-30 N, 3,025 M. to point 9; thence N 66-97\nE, 1,220 M. to common point to Barangay Birawan, Talisay and Ubo (going up to the hills of Talisay); thence\nS 62-00 E, 900 M. to point 11 of Barangay Mabini; thence S 18-15 E, 930 M. to point 12 of Barangay\nMayabay; thence S 03-00 E, 1,150 M. to point 13 (San Roque Creek); thence S 30-59 E, 3,010 to point 14 of\nBarangay Real; thence S 12-10 E, 1,041 M. to point 15 (Timber Land); thence S 88-30, 1,300 M. to point 16\nof Barangay Sua; thence S 64-15 E, 1,320 M. to point 17 of Barangay Pondang; thence S 35-17 E, 1,320 M. to\npoint 18 of Barangay Campilipa; thence N 50-50 E, 740 M. to point 19 (junction to Pondang creek to\nLinpundon Bay); thence S 78-30 E, 640 M. to point 20 (along Daram channel); thence due S 440 M. to point\n21 (along Daram channel); thence N 78-15 W, 680 M. to point 22 (along Daram channel); thence S 28-40 E,\n970 M. to point 23 (along Daram channel); thence S 85-35 W, 520 M. to point 24 (along Daram channel);\nthence 17-10 E, 2,232 M. to point 25 (along Daram channel); thence S 39-20 W, 1,450 M. to point 26 (along\nDaram channel); thence S 60-15 W, 844 M. to point 27 (along the seashore); thence N 81-57 W, 660 M. to\npoint 28 (along the seashore); thence N 60-39 W, 2,838 M. to point 29 (along the seashore); thence N 19-32\nW, 1,920 M. to point 30 (along the seashore); thence N 88-20 E, 2,804 M. to point 31 (along the seashore);\nthence N 08-W, 719 M. to point 32 (junction of Sua creek); thence N 75-10 W, 1.310 M. to point 33 (along\nthe seashore); thence S 64-58 W, 630 M. to point 34 (along the seashore), thence to point 1, point of\nbeginning being N 62-40 W, 2,470 M. containing an area of 4,000 Has. (APPROX).\"\n\"It includes the islets of Bacsal and Agutay which are both bounded by the Samar Sea.\""}}],"pack":"ph-p156"};
  FT["PH-H15529"] = {"id":"PH-H15529","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 700  An Act Amending Sections 318 and 319 of the National Internal Revenue Code, as Amended, So as to Reduce the Period of Limitation for Assessment of Internal Revenue Taxes From Five to three (3) Years","orig":"Batas Pambansa Blg. 700  An Act Amending Sections 318 and 319 of the National Internal Revenue Code, as Amended, So as to Reduce the Period of Limitation for Assessment of Internal Revenue Taxes From Five to three (3) Years"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 700","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-05","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00700_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00700_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15529-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Section 318 of the National Internal Revenue Code, as amended, is hereby amended to read as\n\"Sec. 318. Period of limitation upon assessment and collection. Except as provided in the succeeding section,\ninternal revenue taxes shall be assessed within three years after the last day prescribed by law for the filing of\nthe return, and no proceeding in court without assessment for the collection of such taxes shall be begun after\nthe expiration of such period: Provided, That in a case where a return is filed beyond the period prescribed by\nlaw, the three-year period shall be counted from the day the return was filed. For the purposes of this section,\na return filed before the last day prescribed by law for the filing thereof shall be considered as filed on such"}}],"pack":"ph-p156"};
  FT["PH-H15530"] = {"id":"PH-H15530","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 701  An Act Amending Section thirty-Six of Presidential Decree Numbered Seven Hundred Five, Otherwise Known as \"the Revised Forestry Code of the Philippines","orig":"Batas Pambansa Blg. 701  An Act Amending Section thirty-Six of Presidential Decree Numbered Seven Hundred Five, Otherwise Known as \"the Revised Forestry Code of the Philippines"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 701","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-05","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00701_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00701_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15530-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Section thirty-six of Presidential Decree Numbered Seven hundred five is amended by adding\nanother paragraph after paragraph (h) to read as follows:\n\"In addition to the incentives under this section, private landowners who engage in tree farming on areas fifty\nhectares or below by planting their lands with Ipil-Ipil and other fast-growing trees shall be exempt from the\ninventory requirement and other requirements before harvest as provided in this Decree for lessees of forest\nlands of the public domain: Provided, That the transport of trees cut shall be accompanied by the\ncorresponding certificate of origin duly issued by the authorized forest officer.\""}}],"pack":"ph-p156"};
  FT["PH-H15531"] = {"id":"PH-H15531","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 702  An Act Prohibiting the Demand of Deposits or Advance Payments for the Confinement or Treatment of Patients in Hospitals and Medical Clinics in Certain Cases","orig":"Batas Pambansa Blg. 702  An Act Prohibiting the Demand of Deposits or Advance Payments for the Confinement or Treatment of Patients in Hospitals and Medical Clinics in Certain Cases"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 702","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-05","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00702_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00702_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15531-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"It shall be unlawful for any director, manager or any other officer of a hospital or medical clinic\nto demand any deposit or any other form of advance payment for confinement or treatment in such hospital or\nmedical clinic in emergency or serious cases."}},{"id":"PH-H15531-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Any director, manager or any other officer of a hospital or medical clinic who violates Section 1\nof this Act shall be punished by a fine of not less than one thousand pesos but not more than two thousand\npesos or imprisonment for not less than fifteen days but not more than thirty days, or both such fine and\nimprisonment."}},{"id":"PH-H15531-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"Any person convicted under this Act shall not be entitled to probation under the provisions of\nPresidential Decree No. 968, as amended, otherwise known as the Probation Law of 1976."}},{"id":"PH-H15531-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Ministry of Health shall promulgate the necessary rules and regulations to carry out the\nprovisions of this Act."}},{"id":"PH-H15531-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without executive approval, April 5, 1984."}}],"pack":"ph-p156"};
  FT["PH-H15532"] = {"id":"PH-H15532","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 703  An Act to Amend Presidential Decree Numbered Ten Hundred and Forty-Nine (Re: Retirement Benefits of Commissioned Officers of the Bureau of Coast and Geodetic Survey)","orig":"Batas Pambansa Blg. 703  An Act to Amend Presidential Decree Numbered Ten Hundred and Forty-Nine (Re: Retirement Benefits of Commissioned Officers of the Bureau of Coast and Geodetic Survey)"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 703","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-05","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00703_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00703_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15532-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The following rates of monthly base pay is hereby authorized and prescribed for commissioned\nofficers of the Bureau of Coast and Geodetic Survey in each grade as indicated effective January 1, 1976:\nProvided, That the rates of pay hereunder prescribed shall not be the basis of incentive and additional pays of\nthe commissioned officers of the Bureau of Coast and Geodetic Survey except in longevity pay: Provided,\nfurther, That the increase in longevity pay for the year 1976 shall be subject to the availability of funds and the\napproval of the Minister of National Defense:\nRear Admiral\n2,500.00\n2,000.00\n1,700.00\nLieutenant Commander\n1,400.00\nLieutenant (Senior Grade)\n1,100.00\nLieutenant (Junior Grade)\n900.00\n700.00"}},{"id":"PH-H15532-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The retirement gratuity or pension for commissioned officers of the Bureau of Coast and\nGeodetic Survey shall be based on the current monthly base pay authorized and prescribed for officers of the\nBureau of Coast and Geodetic Survey."}},{"id":"PH-H15532-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The funds necessary for the implementation of this Amendatory Act shall be charged against\n(may be taken from) the \"Coast Survey Officers’ Retirement and Separation Benefits Fund\" provided in"}},{"id":"PH-H15532-A16","no":16,"noLabel":{"en":"Section 16"},"text":{"en":"of Republic Act No. 5976 to be augmented by savings from programmed allotments of the Bureau\nof Coast and Geodetic Survey.\"\nSection 4. This Act shall take effect upon its approval.\nApproved: April 5, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15533"] = {"id":"PH-H15533","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 704  An Act Amending Sections Ten and Twelve of Presidential Decree Numbered Eleven Hundred Forty-Six, Otherwise Known as the \"Revised Government Insurance Act of 1977","orig":"Batas Pambansa Blg. 704  An Act Amending Sections Ten and Twelve of Presidential Decree Numbered Eleven Hundred Forty-Six, Otherwise Known as the \"Revised Government Insurance Act of 1977"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 704","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-05","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00704_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00704_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15533-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Section ten of Presidential Decree Numbered Eleven hundred forty-six is amended to read as\n\"Sec. 10. Computation of Service. The computation of service for calculating the pension shall be from the\ndate of original service with an employer including:\n\"(1) periods of honorable service in the Philippines under the authority of the United States Government if\nrendered prior to July four, nineteen hundred and forty-six; and\n\"(2) period from January one, nineteen hundred and forty-two, to February twenty-eight, nineteen hundred\nand forty-six for those who were in the service on December eight, nineteen hundred and forty-one; but\n\"(i) period of military service for which an employee receives separation, retirement or disability pay; and\n\"(ii) periods of service rendered after June sixteen, nineteen hundred and fifty-one during which contribution\nwere not then required, unless the contributions with interest be later on paid to the System.\n\"For the purpose of this section all services rendered in the government by an employee who was separated\nfrom office not for cause but due to government reorganization and subsequently reinstated in another office\nshall be considered in the computation of his retirement benefit. The term service shall include only full time\nservice with compensation: Provided, That part-time and other services with compensation may be included\nunder such rules and regulations prescribed by the System.\""}}],"pack":"ph-p156"};
  FT["PH-H15534"] = {"id":"PH-H15534","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 705  An Act to Change the Name of Eighteenth Avenue Elementary School Located At Barangay San Roque, Quezon City, to Doa Josefa Edralin Marcos Elementary School","orig":"Batas Pambansa Blg. 705  An Act to Change the Name of Eighteenth Avenue Elementary School Located At Barangay San Roque, Quezon City, to Doa Josefa Edralin Marcos Elementary School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 705","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00705_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00705_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15534-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Eighteenth Avenue Elementary School located at Barangay San Roque, Quezon City, is hereby\nrenamed Doña Josefa Edralin Marcos Elementary School in honor of Doña Josefa Edralin Marcos."}},{"id":"PH-H15534-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15535"] = {"id":"PH-H15535","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 706  An Act Converting Certain Roads in the Province of Rizal Into National Roads","orig":"Batas Pambansa Blg. 706  An Act Converting Certain Roads in the Province of Rizal Into National Roads"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 706","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00706_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00706_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15535-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The following provincial roads in the Province of Rizal are converted into and declared as\nnational roads:\n(a) Pililla Junction-Jalajala Road\n(b) Tanay-Sampaloc Road\n(c) Antipolo-Hinulugang TakTak Road\n(d) Antipolo Diversion Road No. 1\n(e) Antipolo Diversion Road No. 2\n(f) Montalban-San Jose-Quezon City\n(g) Daang Cainta Road\n(h) Marikina-Diversion Road"}},{"id":"PH-H15535-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the improvement and maintenance of said roads shall continue to be\nfunded out of the lump sum appropriation authorized under Batas Pambansa Blg. 640 for the repair and\nmaintenance of local roads until such time that the maintenance funds for said roads shall have been provided\nfor in the succeeding appropriations acts."}},{"id":"PH-H15535-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15536"] = {"id":"PH-H15536","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 707  An Act to Change the Name of Concepcion Elementary School Unit I in the Municipality of Marikina, Metro Manila, to H. Bautista Elementary School","orig":"Batas Pambansa Blg. 707  An Act to Change the Name of Concepcion Elementary School Unit I in the Municipality of Marikina, Metro Manila, to H. Bautista Elementary School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 707","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00707_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00707_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15536-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Concepcion Elementary School Unit I located at J.P. Rizal Street, Barangay\nConcepcion, Municipality of Marikina, Metro Manila, is hereby changed to H. Bautista Elementary School in\nhonor of one of the heroes of the Philippine Revolution, General Hermogenes \"Menes\" Bautista."}},{"id":"PH-H15536-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15537"] = {"id":"PH-H15537","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 708  An Act to Change the Name of Dr. Sixto Antonio Elementary School Unit I in Barangay Bambang, Municipality of Pasig, Metro Manila, to Bambang Elementary School","orig":"Batas Pambansa Blg. 708  An Act to Change the Name of Dr. Sixto Antonio Elementary School Unit I in Barangay Bambang, Municipality of Pasig, Metro Manila, to Bambang Elementary School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 708","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00708_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00708_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15537-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of Dr. Sixto Antonio Elementary School Unit I in Barangay Bambang, Pasig, Metro\nManila, is hereby changed to Bambang Elementary School."}},{"id":"PH-H15537-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15538"] = {"id":"PH-H15538","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 709  An Act to Change the Name of Jolo Elementary School Unit I in Barangay Barangka Drive, Municipality of Mandaluyong, Metro Manila, to Bonifacio Javier Elementary School","orig":"Batas Pambansa Blg. 709  An Act to Change the Name of Jolo Elementary School Unit I in Barangay Barangka Drive, Municipality of Mandaluyong, Metro Manila, to Bonifacio Javier Elementary School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 709","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00709_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00709_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15538-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Jolo Elementary School Unit I located at Barangay Barangka Drive, Municipality of\nMandaluyong, Metro Manila, is hereby renamed Bonifacio Javier Elementary School in honor of the late\nBonifacio Javier, Mayor of Mandaluyong from 1961 to 1965."}},{"id":"PH-H15538-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15539"] = {"id":"PH-H15539","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 710  An Act to Change the Name of Pasig Elementary School Unit I Located At Kapitan Ato street, Municipality of Pasig, Metropolitan Manila, to Liberato Damian Elementary School","orig":"Batas Pambansa Blg. 710  An Act to Change the Name of Pasig Elementary School Unit I Located At Kapitan Ato street, Municipality of Pasig, Metropolitan Manila, to Liberato Damian Elementary School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 710","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00710_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00710_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15539-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Pasig Elementary School Unit I is located at Kapitan Ato Street, Municipality of Pasig,\nMetropolitan Manila, is hereby named Liberato Damian Elementary School in honor Liberato Damian, the\n\"Cabeza de Barangay\" of the area during the Spanish regime and early American occupation."}},{"id":"PH-H15539-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15540"] = {"id":"PH-H15540","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 711  An Act Creating the Mariano Marcos National Forests Park","orig":"Batas Pambansa Blg. 711  An Act Creating the Mariano Marcos National Forests Park"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 711","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00711_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00711_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15540-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"There is hereby created in Northern Luzon a national park, to be known as the Mariano Marcos\nNational Forests Park, which shall consist of the forest lands of the public domain is Sumiling, Municipality\nof Sarat, in the municipalities of Pagudpud, Adams and Bumalneg all in the Province of Ilocos Norte, the\nmunicipalities of Claveria and Santa Praxedes in the Province of Cagayan, the Municipality of Calanasan in\nthe Province of Kalinga-Apayao and the islands of Calayaan, Camiguin and Fuga. The Minister of Natural\nResources shall cause to be surveyed, delineated and segregated the territory constituting the Mariano Marcos\nNational Forests park, and territory so segregated shall become a permanent forest reserve."}},{"id":"PH-H15540-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Nothing in this Act shall be construed to affect adversely or prejudice any right or rights existing\non the date of the effectivity hereof."}},{"id":"PH-H15540-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15541"] = {"id":"PH-H15541","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 712  An Act Converting the Argao-Moalboal Provincial Road in the Province of Cebu Into a National Road","orig":"Batas Pambansa Blg. 712  An Act Converting the Argao-Moalboal Provincial Road in the Province of Cebu Into a National Road"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 712","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00712_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00712_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15541-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Argao-Moalboal Provincial Road in the Province of Cebu is hereby converted into and is\ndeclared as a national road."}},{"id":"PH-H15541-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the improvement and maintenance of said road shall continue to be\nfunded out of the lump sum appropriation authorized under Batas Pambansa Blg. 640 for the repair and\nmaintenance of local roads until such time that the maintenance funds for said road shall have been provided\nfor in the succeeding appropriations acts."}},{"id":"PH-H15541-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15542"] = {"id":"PH-H15542","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 713  An Act Changing the Name of Basilan City Emergency Hospital in the Municipality of Lamitan, Province of Basilan, to Lamitan District Hospital","orig":"Batas Pambansa Blg. 713  An Act Changing the Name of Basilan City Emergency Hospital in the Municipality of Lamitan, Province of Basilan, to Lamitan District Hospital"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 713","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00713_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00713_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15542-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of Basilan City Emergency Hospital in the Municipality of Lamitan, Province of\nBasilan, is hereby changed of Lamitan District Hospital."}},{"id":"PH-H15542-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15543"] = {"id":"PH-H15543","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 714  An Act Changing the Name of the Talibon Provincial Hospital in the Municipality of Talibon, Province of Bohol, to Congressman Maximino Garcia Memorial Hospital","orig":"Batas Pambansa Blg. 714  An Act Changing the Name of the Talibon Provincial Hospital in the Municipality of Talibon, Province of Bohol, to Congressman Maximino Garcia Memorial Hospital"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 714","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00714_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00714_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15543-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Talibon Provincial Hospital in the Municipality of Talibon, Province of Bohol,\nis changed to Congressman Maximino Garcia Memorial Hospital."}},{"id":"PH-H15543-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15544"] = {"id":"PH-H15544","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 715  An Act Changing the Name of the Kayapa Field Hospital in the Municipality of Kayapa, Province of Nueva VIzcaya, to Lt. Tidang Memorial Hospital","orig":"Batas Pambansa Blg. 715  An Act Changing the Name of the Kayapa Field Hospital in the Municipality of Kayapa, Province of Nueva VIzcaya, to Lt. Tidang Memorial Hospital"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 715","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00715_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00715_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15544-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Kayapa Field Hospital in the Municipality of Kayapa, Province of Nueva\nVizcaya, is hereby change to Lt. Tidang Memorial Hospital."}},{"id":"PH-H15544-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15545"] = {"id":"PH-H15545","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 716  An Act Converting the National Highway-Lamao Port Provincial Road in the Municipality of Liloy, Province of Zamboanga Del Norte, Into a National Road","orig":"Batas Pambansa Blg. 716  An Act Converting the National Highway-Lamao Port Provincial Road in the Municipality of Liloy, Province of Zamboanga Del Norte, Into a National Road"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 716","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00716_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00716_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15545-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The National Highway-Lamao Port Provincial Road in the Municipality of Liloy, Province of\nZamboanga del Norte, connecting a three and a half kilometer (3.5) road from the Port of Lamao to the\nnational highway, is hereby converted into a national road."}},{"id":"PH-H15545-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the improvement and maintenance of said road shall continue to be\nfunded out of the lump sum appropriation authorized under Batas Pambansa Blg. 640 for the repair and\nmaintenance funds for said road shall have been provided for in the succeeding appropriations acts."}},{"id":"PH-H15545-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15546"] = {"id":"PH-H15546","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 717  An Act Converting the Gubat-Casiguran Provincial Road in the Province of Sorsogon Into a National Road","orig":"Batas Pambansa Blg. 717  An Act Converting the Gubat-Casiguran Provincial Road in the Province of Sorsogon Into a National Road"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 717","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00717_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00717_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15546-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Gubat-Casiguran provincial road in the Province of Sorsogon is converted into a national"}},{"id":"PH-H15546-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the improvement and maintenance of said road shall continue to be\nfunded out of the lump sum appropriation authorized under Batas Pambansa Blg. 640 for the repair and\nmaintenance of local roads until such time that the maintenance funds for said road shall have been provided\nfor in the succeeding appropriations acts."}},{"id":"PH-H15546-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15547"] = {"id":"PH-H15547","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 718  An Act Constituting Sitios in the Municipality of Malimono, Sur1Gao Del Norte, Into New Barangays, to Be Known as Barangays VIlla Riza, Cansayong, and Can-Aga","orig":"Batas Pambansa Blg. 718  An Act Constituting Sitios in the Municipality of Malimono, Sur1Gao Del Norte, Into New Barangays, to Be Known as Barangays VIlla Riza, Cansayong, and Can-Aga"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 718","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00718_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00718_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15547-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The sitios of Villa Riza, Cansayong and Can-aga are hereby separated from their respective\nmother barangay and constituted into three (3) new separate barangays to be respectively known as Barangay\nVilla Riza, Barangay Cansayong and Barangay Can-aga, all in the Municipality of Malimono, Province of\nSurigao del Norte."}},{"id":"PH-H15547-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the areas\naffected, within a period of ninety (90) days after the approval of this Act, the President shall appoint the\nofficials of the new barangays. Said official shall hold office until their successors shall have been duly\nelected and qualified."}},{"id":"PH-H15547-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The barangays herein created shall begin to exist upon appointment and qualification of their\nrespective officers."}},{"id":"PH-H15547-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Commission on Elections shall conduct and supervise the holding of the plebiscite and the\nexpenses for such plebiscite shall be charged to the appropriations of the Commission on Elections for said"}},{"id":"PH-H15547-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15548"] = {"id":"PH-H15548","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 719  An Act Converting the Pico-Lamtang Provincial Road in the Municipality of La Trinidad, Province of Benguet, Into a National Road","orig":"Batas Pambansa Blg. 719  An Act Converting the Pico-Lamtang Provincial Road in the Municipality of La Trinidad, Province of Benguet, Into a National Road"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 719","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00719_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00719_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15548-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Pico-Lamtang Provincial Road in the Municipality of La Trinidad, Province of Benguet, is\nhereby converted into a national road."}},{"id":"PH-H15548-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the improvement and maintenance of said road shall continue to be\nfunded out of the lump sum appropriation authorized under Batas Pambansa Blg. 640 for the repair and\nmaintenance of local roads until such time that the maintenance funds for said road shall have been provided\nfor in succeeding appropriations acts."}},{"id":"PH-H15548-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
