  FT["PH-H15610"] = {"id":"PH-H15610","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 781  An Act Changing the Name of the Glan Vocational High School in the Municipality of Glan, Province of South Cotabato, to Glan School of Arts and Trades","orig":"Batas Pambansa Blg. 781  An Act Changing the Name of the Glan Vocational High School in the Municipality of Glan, Province of South Cotabato, to Glan School of Arts and Trades"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 781","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00781_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00781_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15610-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Glan Vocational High School in the Municipality of Glan, Province of South\nCotabato, is changed to Glan School of Arts and Trades."}},{"id":"PH-H15610-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15611"] = {"id":"PH-H15611","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 782  An Act Changing the Name of the Chinese Pier Primary School in the Municipality of Jolo, Province of Sulu, to Mababang Paaralan Ng Rasul","orig":"Batas Pambansa Blg. 782  An Act Changing the Name of the Chinese Pier Primary School in the Municipality of Jolo, Province of Sulu, to Mababang Paaralan Ng Rasul"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 782","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00782_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00782_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15611-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Chinese Pier Primary School in the Municipality of Jolo, Province of Sulu, is\nchanged to Mababang Paaralan ng Rasul."}},{"id":"PH-H15611-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 13, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15612"] = {"id":"PH-H15612","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 783  An Act Changing the Name of the Pasay Road Extending From the Municipality of Makati to Pasay City Both in Metropolitan Manila, to Antonio S. Arnaiz","orig":"Batas Pambansa Blg. 783  An Act Changing the Name of the Pasay Road Extending From the Municipality of Makati to Pasay City Both in Metropolitan Manila, to Antonio S. Arnaiz"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 783","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00783_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00783_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15612-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of Pasay Road extending from the Fort-Bonifacio Road (station 12.820) in the\nMunicipality of Makati, to Roxas Boulevard-Libertad intersection (station 4.330) in Pasay City both in\nMetropolitan Manila, is changed to Antonio S. Arnaiz Avenue."}},{"id":"PH-H15612-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15613"] = {"id":"PH-H15613","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 784  An Act Creating Barangay Capri in Quezon City, Metro Manila","orig":"Batas Pambansa Blg. 784  An Act Creating Barangay Capri in Quezon City, Metro Manila"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 784","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 4 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00784_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00784_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15613-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Capri in Barangay Nagkaisang Nayon, Quezon City, Metro Manila, is hereby separated from the\nsaid barangay and constituted into a distinct and independent barangay of said city to be known as Barangay\nCapri with the following technical description: north Tullahan Creek and Lot 165-B of Nagkaisang Nayon;\neast Lots 161-New C and 161-New B of Nagkaisang Nayon; south Tullahan River; west Tullahan Creek."}},{"id":"PH-H15613-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The first officials of the said barangay shall be those who were elected during the barangay\nelections held last May 17, 1982 and proclaimed by the Commission on Elections thru the Board of\nCanvassers and shall hold office until their successors shall have been elected or appointed and qualified."}},{"id":"PH-H15613-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"The new barangay shall exist when majority of the votes cast in a plebiscite to be conducted in\nthe unit affected under the supervision of the Commission on Elections within six months from the effectivity\nof this Act favors the creation of Barangay Capri. The expenses for such plebiscite shall be charged to local"}},{"id":"PH-H15613-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15614"] = {"id":"PH-H15614","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 785  An Act Changing the Name of Tandang Sora Elementary School in Barangay Talipapa, Quezon City, to Placido Del Mundo Memorial School","orig":"Batas Pambansa Blg. 785  An Act Changing the Name of Tandang Sora Elementary School in Barangay Talipapa, Quezon City, to Placido Del Mundo Memorial School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 785","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00785_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00785_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15614-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Tandang Sora Elementary School in Barangay Talipapa in Quezon City is hereby changed to\nPlacido del Mundo Memorial School in honor of Mr. Placido del Mundo, the philanthropist and civic-minded\nperson of the said barangay."}},{"id":"PH-H15614-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15615"] = {"id":"PH-H15615","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 786  An Act Constituting Sitios of Paalaman, Tatlong Pulo, Calumpit, Supot, Bukal and La Mesang Bato, All in Barangay Special District, Municipality of Jala-Jala, Province of Rizal, Into a New Barangay to Be Known as Barangay Paalaman","orig":"Batas Pambansa Blg. 786  An Act Constituting Sitios of Paalaman, Tatlong Pulo, Calumpit, Supot, Bukal and La Mesang Bato, All in Barangay Special District, Municipality of Jala-Jala, Province of Rizal, Into a New Barangay to Be Known as Barangay Paalaman"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 786","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00786_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00786_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15615-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The sitios of Paalaman, Tatlong Pulo, Calumpit, Supot, Bukal and La Mesang Bato, all in\nBarangay Special District, Municipality of Jalajala, Province of Rizal, are hereby separated from Barangay\nSpecial District and constituted into a new barangay of the said municipality to be known as Barangay"}},{"id":"PH-H15615-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Barangay Paalaman shall include the area bounded by: N Eastern part of Barangay Sipsipin, E\nBarangay Bagumbong, W Barangay Special District, S Barangay Lubo."}},{"id":"PH-H15615-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the area\naffected within one hundred twenty days from the approval of this Act, the President of the Philippines shall\nappoint the first officials of Barangay Paalaman who shall hold office until their successors shall have been\nelected and qualified in the next regular barangay election."}},{"id":"PH-H15615-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite herein provided. The\nexpenses for such plebiscite shall be charged to the appropriations of the Commission on Elections provided\nin the current annual General Appropriations Act for plebiscites."}},{"id":"PH-H15615-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15616"] = {"id":"PH-H15616","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 787  An Act Constituting Sitio of Beverly Hills in Barangay San Roque, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay Beverly Hills","orig":"Batas Pambansa Blg. 787  An Act Constituting Sitio of Beverly Hills in Barangay San Roque, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay Beverly Hills"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 787","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00787_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00787_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15616-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The sitio of Beverly Hills in Barangay San Roque, Municipality of Antipolo, Province of Rizal,\nis hereby separated from Barangay San Roque and constituted into a new barangay of the said municipality to\nbe known as Barangay Beverly Hills."}},{"id":"PH-H15616-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Barangay Beverly Hills shall include the area bounded by: N Antipolo-Taytay Road, E\nPinagbangkaan Creek, SW Municipality of Taytay."}},{"id":"PH-H15616-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the area\naffected within one hundred twenty days from the approval of this Act, the President of the Philippines shall\nappoint the first officials of Barangay Beverly Hills who shall hold office until their successors shall have\nbeen elected and qualified in the next regular barangay election."}},{"id":"PH-H15616-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite herein provided. The\nexpenses for such plebiscite shall be charged to the appropriations of the Commission on Elections provided\nin the current annual General Appropriations Act for plebiscites."}},{"id":"PH-H15616-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15617"] = {"id":"PH-H15617","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 788  An Act Constituting Sitios of Nayong Silangan, Aba Homes, Dalig and Tipolo All in Barangay San Jose, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay Dalig","orig":"Batas Pambansa Blg. 788  An Act Constituting Sitios of Nayong Silangan, Aba Homes, Dalig and Tipolo All in Barangay San Jose, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay Dalig"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 788","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00788_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00788_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15617-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The sitios of Nayong Silangan, Aba Homes, Dalig and Tipolo all in Barangay San Jose,\nMunicipality of Antipolo, Province of Rizal, are hereby separated from Barangay San Jose and constituted\ninto a new barangay of the said municipality to be known as Barangay Dalig."}},{"id":"PH-H15617-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Barangay Dalig shall include the area bounded by: N Antipolo-Teresa National Road, E\nMunicipality of Teresa, S municipalities of Teresa and Angono, W Antipolo-Darangan Road."}},{"id":"PH-H15617-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the area\naffected within one hundred twenty days from the approval of this Act, the President of the Philippines shall\nappoint the first officials of Barangay Dalig who shall hold office until their successors shall have been\nelected and qualified in the next regular barangay election."}},{"id":"PH-H15617-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite herein provided. The\nexpenses for such plebiscite shall be charged to the appropriations of the Commission on Elections provided\nin the current annual General Appropriations Act for plebiscites."}},{"id":"PH-H15617-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15618"] = {"id":"PH-H15618","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 789  An Act Constituting Sitios of Bagong Nayon, Cogeo VIllage, Makulis, Upper Kamias, Lower Kamias, Bulusukin and Sapang Papasak, All in Barangay Dela Paz, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay Bagong Nayon","orig":"Batas Pambansa Blg. 789  An Act Constituting Sitios of Bagong Nayon, Cogeo VIllage, Makulis, Upper Kamias, Lower Kamias, Bulusukin and Sapang Papasak, All in Barangay Dela Paz, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay Bagong Nayon"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 789","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00789_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00789_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15618-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The sitios of Bagong Nayon, Cogeo Village, Makulis, Upper Kamias, Lower Kamias, Bulusukin\nand Sapang Papasak all in Barangay Dela Paz, Municipality of Antipolo, Province of Rizal, are hereby\nseparated from Barangay Dela Paz and constituted into a new barangay of the said municipality to be known\nas Barangay Bagong Nayon."}},{"id":"PH-H15618-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Barangay Bagong Nayon shall include the area bounded by: N Tulakin River, E Inalsan Road, S\nMarcos Highway, Barangay Sta. Cruz, W Barangay Cupang and Nangka River."}},{"id":"PH-H15618-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the area\naffected within one hundred twenty days from the approval of this Act, the President of the Philippines shall\nappoint the first officials of Barangay Bagong Nayon who shall hold office until their successors shall have\nbeen elected and qualified in the next regular barangay election."}},{"id":"PH-H15618-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite herein provided. The\nexpenses for such plebiscite shall be charged to the appropriations of the Commission on Elections provided\nin the current annual General Appropriations Act for plebiscites."}},{"id":"PH-H15618-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15619"] = {"id":"PH-H15619","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 790  An Act Constituting Sitios of Buntong Palay, Dirakpan, Kay Ugat, Palilingan, Tinging, Bungkawi, Bana, Labrahan, Tulakin, Bubom Amak, Inalsan, Inc, and Kay Suso Bangko All in Barangay Dela Paz, San Isidro and Cupang, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay San Juan","orig":"Batas Pambansa Blg. 790  An Act Constituting Sitios of Buntong Palay, Dirakpan, Kay Ugat, Palilingan, Tinging, Bungkawi, Bana, Labrahan, Tulakin, Bubom Amak, Inalsan, Inc, and Kay Suso Bangko All in Barangay Dela Paz, San Isidro and Cupang, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay San Juan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 790","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00790_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00790_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15619-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The sitios of Buntong Palay, Dirakpan, Kay Ugat, Palilingan, Tinging, Bungkawi, Bana,\nLabrahan, Tulakin, Bubom Amak, Inalsan, INC, and Kay Suso Bangko, all in Barangay Dela Paz, San Isidro\nand Cupang, Municipality of Antipolo, Province of Rizal, are hereby separated from Barangay Dela Paz, San\nIsidro, and Cupang and constituted into a new barangay of the said municipality to be known as Barangay San"}},{"id":"PH-H15619-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"Barangay San Juan shall include the area bounded by: N municipalities of Montalban and San\nMateo, E Antipolo-San Mateo Road, W Kay Tamban Creek, Barangay Cupang, S Tulakin Creek, SE Army\nRoad to Mt. Yabang."}},{"id":"PH-H15619-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the area\naffected within one hundred twenty days from the approval of this Act, the President of the Philippines shall\nappoint the first officials of Barangay San Juan who shall hold office until their successors shall have been\nelected and qualified in the next regular barangay election."}},{"id":"PH-H15619-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite herein provided. The\nexpenses for such plebiscite shall be charged to the appropriations of the Commission on Elections provided\nin the current annual General Appropriations Act for plebiscites."}},{"id":"PH-H15619-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15620"] = {"id":"PH-H15620","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 791  An Act Constituting Sitios of sta. Cruz, Nagpuso, Cavaliers, Kay Baiya, Mahal Na Poon, Tawid-Tawid, Uulan, Makatubong, Mini, Tagisan and Seven Hills, All in Barangay Dela Paz, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay sta. Cruz","orig":"Batas Pambansa Blg. 791  An Act Constituting Sitios of sta. Cruz, Nagpuso, Cavaliers, Kay Baiya, Mahal Na Poon, Tawid-Tawid, Uulan, Makatubong, Mini, Tagisan and Seven Hills, All in Barangay Dela Paz, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay sta. Cruz"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 791","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00791_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00791_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15620-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The sitios of Sta. Cruz, Nagpuso, Cavaliers, Kay Baiya, Mahal na Poon, Tawid-Tawid, Uulan,\nMakatubong, Mini, Tagisan and Seven Hills all in Barangay Dela Paz, Municipality of Antipolo, Province of\nRizal, are hereby separated from Barangay Dela Paz and constituted into a new barangay of the said\nmunicipality to be known as Barangay Sta. Cruz."}},{"id":"PH-H15620-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Barangay Sta. Cruz shall include the area bounded by:\nN Marcos Highway, Sumulong Highway and Lukban Road E Barangay Dela Paz, W Barangay Mambugan to\nMarcos Highway near Nangka River."}},{"id":"PH-H15620-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the area\naffected within one hundred twenty days from the approval of this Act, the President of the Philippines shall\nappoint the first officials of Barangay Sta. Cruz who shall hold office until their successors shall have been\nelected and qualified in the next regular barangay election."}},{"id":"PH-H15620-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite herein provided. The\nexpenses for such plebiscite shall be charged to the appropriations of the Commission on Elections provided\nin the current annual General Appropriations Act for plebiscites."}},{"id":"PH-H15620-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15621"] = {"id":"PH-H15621","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 792  An Act Constituting Sitios of Muntindilaw, Bulao, San Berga, Mahayhay, Napindan, Dagatan, Valley Golf Club, and Part of VIctoria Valley in Barangay Mambugan and Dela Paz, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay Muntindilaw","orig":"Batas Pambansa Blg. 792  An Act Constituting Sitios of Muntindilaw, Bulao, San Berga, Mahayhay, Napindan, Dagatan, Valley Golf Club, and Part of VIctoria Valley in Barangay Mambugan and Dela Paz, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay Muntindilaw"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 792","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00792_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00792_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15621-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The sitios of Muntindilaw, Bulao, San Berga, Mahayhay, Napindan, Dagatan, Valley Golf Club\nand part of Victoria Valley in Barangay Mambugan and Dela Paz, Municipality of Antipolo Province of Rizal,\nare hereby separated from Barangay Mambugan and Dela Paz and constituted into a new barangay of the said\nmunicipality to be known as Barangay Muntindilaw."}},{"id":"PH-H15621-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Barangay of Muntindilaw shall include the area bounded by: N Bulao Creek, Barangay\nMambugan, E Victoria Valley Avenue, S Municipalities of Taytay and Cainta, W Municipality of Cainta."}},{"id":"PH-H15621-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the area\naffected within one hundred twenty days from the approval of this Act, the President of the Philippines shall\nappoint the first officials of Barangay Muntindilaw who shall hold office until their successors shall have been\nelected and qualified in the next regular barangay election."}},{"id":"PH-H15621-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite herein provided. The\nexpenses for such plebiscite shall be charged to the appropriations of the Commission on Elections provided\nin the current annual General Appropriations Act for plebiscites."}},{"id":"PH-H15621-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15622"] = {"id":"PH-H15622","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 793  An Act Constituting Sitios of San Luis, Part of Sitio Kay Ampaula, Part of Sitio Kay Naog, Biga, Kay Bagsik. Susugin, Dao Creek, Part of Pinagminahan Mountain Range, Pinagkaliruhan, Part of Bubukal Cave, Culasisi, Banaba, Puting Bato, Nilulubugan and Tesorero, All in Barangay San Isidro, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay San Luis","orig":"Batas Pambansa Blg. 793  An Act Constituting Sitios of San Luis, Part of Sitio Kay Ampaula, Part of Sitio Kay Naog, Biga, Kay Bagsik. Susugin, Dao Creek, Part of Pinagminahan Mountain Range, Pinagkaliruhan, Part of Bubukal Cave, Culasisi, Banaba, Puting Bato, Nilulubugan and Tesorero, All in Barangay San Isidro, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay San Luis"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 793","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00793_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00793_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15622-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The sitios of San Luis, part of Sitio Kay Ampaula, part of Sitio Kay Naog, Biga, Kay Bagsik,\nSusugin, Dao Creek, part of Pinagminahan Mountain Range, Pinagkaliruhan, part of Bubukal Cave, Culasisi,\nBanaba, Puting Bato, Nilulubugan and Tesorero all in Barangay San Isidro, Municipality of Antipolo,\nProvince of Rizal, are hereby separated from Barangay San Isidro and constituted into a new barangay of the\nsaid municipality to be known as Barangay San Luis."}},{"id":"PH-H15622-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Barangay of San Luis shall include the area bounded by: N Marcos Highway, E Dao Creek\nand Tagbae River, S Kay Naog Road, Maguey Road and San Luis Road, W Buliran Road, Barangay San"}},{"id":"PH-H15622-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the area\naffected within one hundred twenty days from the approval of this Act, the President of the Philippines shall\nappoint the first officials of Barangay San Luis who shall hold office until their successors shall have been\nelected and qualified in the next regular barangay election."}},{"id":"PH-H15622-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite herein provided. The\nexpenses for such plebiscite shall be charged to the appropriations of the Commission on Elections provided\nin the current annual General Appropriations Act for plebiscites."}},{"id":"PH-H15622-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15623"] = {"id":"PH-H15623","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 794  An Act Constituting Sitios of Inarawan, Inuman, Buyag, Maagay, Binitinan, Gulugod Baboy All in Barangay San Isidro, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay Inarawan","orig":"Batas Pambansa Blg. 794  An Act Constituting Sitios of Inarawan, Inuman, Buyag, Maagay, Binitinan, Gulugod Baboy All in Barangay San Isidro, Municipality of Antipolo, Province of Rizal, Into a New Barangay to Be Known as Barangay Inarawan"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 794","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00794_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00794_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15623-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The sitios of Inarawan, Inuman, Buyag, Maagay, Binitinan, Gulugod Baboy all in Barangay San\nIsidro, Municipality of Antipolo, Province of Rizal, are hereby separated from Barangay San Isidro and\nconstituted into a new barangay of the said municipality to be known as Barangay Inarawan."}},{"id":"PH-H15623-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Barangay of Inarawan shall include the area bounded by: N Army Road, Barangay San\nJuan, E Antipolo-San Mateo Road, S Marcos Highway, W Inalsan- Boso-Boso Road."}},{"id":"PH-H15623-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the area\naffected within one hundred twenty days from the approval of this Act, the President of the Philippines shall\nappoint the first officials of Barangay Inarawan who shall hold office until their successors shall have been\nelected and qualified in the next regular barangay election."}},{"id":"PH-H15623-A4","no":4,"noLabel":{"en":"Section 4"},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite herein provided. The\nexpenses for such plebiscite shall be charged to the appropriations of the Commission on Elections provided\nin the current annual General Appropriations Act for plebiscites."}},{"id":"PH-H15623-A5","no":5,"noLabel":{"en":"Section 5"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15624"] = {"id":"PH-H15624","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 795  An Act Changing the Name of the Tondo High School in the City of Manila to Aurelio V. Tolentino High School","orig":"Batas Pambansa Blg. 795  An Act Changing the Name of the Tondo High School in the City of Manila to Aurelio V. Tolentino High School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 795","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00795_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00795_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15624-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Tondo High School in the City of Manila is changed to Aurelio V. Tolentino\nHigh nynySchool."}},{"id":"PH-H15624-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15625"] = {"id":"PH-H15625","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 796  An Act Changing the Name of the Margarita Roxas Elementary School in sta. Ana, Manila, to Margarita Roxas De Ayala Elementary School","orig":"Batas Pambansa Blg. 796  An Act Changing the Name of the Margarita Roxas Elementary School in sta. Ana, Manila, to Margarita Roxas De Ayala Elementary School"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 796","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00796_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00796_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15625-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Margarita Roxas Elementary School in Sta. Ana, Manila, is hereby changed to\nthe Margarita Roxas de Ayala Elementary School."}},{"id":"PH-H15625-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15626"] = {"id":"PH-H15626","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 797  An Act Changing the Name of the Palawan Teacher'S College in Puerto Princesa City to the Palawan state College and Authorizing the Same to Continue Offering Its Present Collegiate Courses","orig":"Batas Pambansa Blg. 797  An Act Changing the Name of the Palawan Teacher'S College in Puerto Princesa City to the Palawan state College and Authorizing the Same to Continue Offering Its Present Collegiate Courses"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 797","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00797_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00797_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15626-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Palawan Teacher’s College in Puerto Princesa City to the Palawan, is changed\nto Palawan State College."}},{"id":"PH-H15626-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Palawan State College is authorized to continue offering its present collegiate courses and\nother courses in arts, sciences and technology."}},{"id":"PH-H15626-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15627"] = {"id":"PH-H15627","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 798  An Act Changing the Name of the Palawan School of Arts and Trades in the Municipality of Cuyo, Province of Palawan, to Palawan College of Arts and","orig":"Batas Pambansa Blg. 798  An Act Changing the Name of the Palawan School of Arts and Trades in the Municipality of Cuyo, Province of Palawan, to Palawan College of Arts and"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 798","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00798_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00798_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15627-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Palawan School of Arts and Trades in the Municipality of Cuyo, Province of\nPalawan, is hereby changed to Palawan College of Arts and Trades."}},{"id":"PH-H15627-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The Palawan College of Arts and Trades is authorized to continue offering the present collegiate\ncourses of the Palawan School of Arts and Trades."}},{"id":"PH-H15627-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15628"] = {"id":"PH-H15628","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 799  An Act Placing All Waterworks and Sewerage Systems in the Entire Province of Rizal Under the Jurisdiction, Supervision and Control of the Metropolitan Waterworks and Sewerage System Amending for the Purpose Republic Act Numbered Sixty-Two Hundred and thirty-Four, as Amended","orig":"Batas Pambansa Blg. 799  An Act Placing All Waterworks and Sewerage Systems in the Entire Province of Rizal Under the Jurisdiction, Supervision and Control of the Metropolitan Waterworks and Sewerage System Amending for the Purpose Republic Act Numbered Sixty-Two Hundred and thirty-Four, as Amended"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 799","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00799_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00799_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15628-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Subsection (c) of Section two of Republic Act Numbered Sixty-Two hundred and thirty four, as\namended, is hereby amended to read as follows:\n\"(c) The System shall own and/or have jurisdiction, supervision and control over all waterworks and sewerage\nsystems in the territory comprising the cities of Manila, Pasay, Quezon, Cavite and Caloocan, the\nmunicipalities of Las Piñas, Makati, Malabon, Mandaluyong, Marikina, Navotas, Parañaque, Pasig, Pateros,\nSan Juan, Taguig, Valenzuela, all of Metropolitan Manila, the entire province of Rizal, and the municipalities\nof Bacoor, Imus, Kawit, Noveleta, Rosario, all of Cavite Province. The System shall also own and/or have\njurisdiction, supervision and control over all waterworks and sewerage systems in Lungsod Silangan,\nMuntinlupa and, subject to the approval of the President, other areas that may come within the development\npath of the expanding Metropolitan Manila Area, which areas the Board of Metropolitan Waterworks and\nSewerage System may, from time to time, determine and declare as contiguous to its service area requiring\nimmediate attention by the System, under such terms and conditions as may be agreed upon by the parties\nconcerned. All other waterworks and sewerage systems now under the supervision and control of the\nMetropolitan Waterworks and Sewerage System (MWSS), are hereby returned, ceded, transferred and turned\nover to the provinces, cities and municipalities for their supervision, control and administration, until such\ntime that they qualify within the program of development under the Local Water Utilities Administration\n(LWUA). The transfer and turnover to the local governments concerned shall be completed within the period\nof ninety (90) days from the promulgation of the decree.\""}}],"pack":"ph-p156"};
  FT["PH-H15629"] = {"id":"PH-H15629","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 800  An Act Converting Certain Provincial Roads in the Province of Quezon Into National Roads","orig":"Batas Pambansa Blg. 800  An Act Converting Certain Provincial Roads in the Province of Quezon Into National Roads"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 800","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00800_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00800_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15629-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The following provincial roads in the Province of Quezon are hereby converted into national\n(1) Pagbilao-Padre Burgos Road;\n(2) Padre Burgos-Agdañgan Road;\n(3) Agdañgan-Unisan Road; and\n(4) Unisan-Pototanin-Pitogo Road."}},{"id":"PH-H15629-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the improvement and maintenance of said roads shall continue to be\nfunded out of the lump sum appropriation authorized under Batas Pambansa Blg. 640 for the repair and\nmaintenance of local roads until such time that the maintenance funds for said roads shall have been provided\nfor in the succeeding appropriations acts."}},{"id":"PH-H15629-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15630"] = {"id":"PH-H15630","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 801  An Act Changing the Name of the Dumeles Elementary School in the Municipality of San Enrique, Province of Iloilo, to Don Pedro M. Fernandez Elementary","orig":"Batas Pambansa Blg. 801  An Act Changing the Name of the Dumeles Elementary School in the Municipality of San Enrique, Province of Iloilo, to Don Pedro M. Fernandez Elementary"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 801","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 2 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00801_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00801_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15630-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The name of the Dumeles Elementary School in the Municipality of San Enrique, Province of\nIloilo, is changed to Don Pedro M. Fernandez Elementary School."}},{"id":"PH-H15630-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15631"] = {"id":"PH-H15631","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 802  An Act Converting Certain Provincial Roads in the Province of Antique Into National Roads and Appropriating Funds therefor","orig":"Batas Pambansa Blg. 802  An Act Converting Certain Provincial Roads in the Province of Antique Into National Roads and Appropriating Funds therefor"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 802","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00802_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00802_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15631-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The following provincial roads in the Province of Antique are converted into national roads:\n(a) Batayan-San Pedro-Pantao Road in the Municipality of San Jose.\n(b) Buhang-Malandog Road in the Municipality of Hamtic\n(c) Poblacion-Pisanan Road in the Municipality of Sibalom\n(d) Poblacion-Alangan Road in the Municipality of Sibalom\n(e) Poblacion-Bugo Road in the Municipality of San Remegio\n(f) Bugo-General Fullon Road in the Municipality of San Remegio\n(g) Atabay-Inubusan Road, San Jose-Hamtic\n(h) Pacita Drive, La Paz, Hamtic."}},{"id":"PH-H15631-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the improvement and maintenance of said roads shall continue to be\nfunded out of the lump sum appropriation authorized under Batas Pambansa Blg. 640 for the repair and\nmaintenance of local roads until such time that the maintenance funds for said roads shall have been provided\nfor in the succeeding appropriations acts."}},{"id":"PH-H15631-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15632"] = {"id":"PH-H15632","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Batas Pambansa Blg. 803  An Act Correcting Certain Errors in Batas Pambansa Numbered Five Hundred Forty-Four Entitled \"An Act Integrating and Converting Certain Schools in the Province of Surigao Del Sur Into a National Institute of Technology to Be Known as the Surigao Del Sur Institute of Technology","orig":"Batas Pambansa Blg. 803  An Act Correcting Certain Errors in Batas Pambansa Numbered Five Hundred Forty-Four Entitled \"An Act Integrating and Converting Certain Schools in the Province of Surigao Del Sur Into a National Institute of Technology to Be Known as the Surigao Del Sur Institute of Technology"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 803","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00803_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00803_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15632-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"Section one of Batas Pambansa Bilang 544 is corrected to read as follows:\n\"Sec. 1. The Cantilan National School of Arts and Trades, the Cantilan Municipal High School and the\nCantilan Barangay High School, all in the Municipality of Cantilan, the Lanuza Municipal High School in the\nMunicipality of Lanuza, the Burgos Barangay High School in the Municipality of Cortes, the Panikian\nBarangay High School in the Municipality of Carrascal and the Carmen Barangay High School in the\nMunicipality of Carmen, all in the Province of Surigao del Sur, are hereby integrated and converted into a\nnational institute of technology under the Ministry of Education, Culture and Sports to be known as the\nSurigao del Sur Institute of Technology. The principal office of the Institute shall be at the present site of the\nCantilan National School of Arts and Trades and the other schools integrated hereunder shall be maintained\nand operated as branches of the Institute.\""}}],"pack":"ph-p156"};
  FT["PH-H15633"] = {"id":"PH-H15633","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 804  An Act Converting Certain Provincial Roads in the City of Surigao Into National Roads","orig":"Batas Pambansa Blg. 804  An Act Converting Certain Provincial Roads in the City of Surigao Into National Roads"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 804","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00804_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00804_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15633-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The following provincial roads in the City of Surigao are converted into and declared as national\n(a) Surigao City-San Juan Coastal Road\n(b) Jct. National Road-Quezon-Mapawa-Capalayan-Espina Extension-Navarro Street."}},{"id":"PH-H15633-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the improvement and maintenance of said roads shall continue to be\nfunded out of the lump sum appropriation authorized under Batas Pambansa Blg. 640 for the repair and\nmaintenance of local roads until such time that the maintenance funds for said roads shall have been provided\nfor in the succeeding appropriations act."}},{"id":"PH-H15633-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15634"] = {"id":"PH-H15634","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 805  An Act Reclassifying the Western VIsayas Regional Hospital in the Municipality of Pototan, Province of Iloilo, Into a Provincial Hospital to Be Known as the Iloilo Provincial Hospital","orig":"Batas Pambansa Blg. 805  An Act Reclassifying the Western VIsayas Regional Hospital in the Municipality of Pototan, Province of Iloilo, Into a Provincial Hospital to Be Known as the Iloilo Provincial Hospital"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 805","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00805_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00805_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15634-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Western Visayas Regional Hospital in the Municipality of Pototan, Province of Iloilo, is\nreclassified into a provincial hospital to be known as the Iloilo Provincial Hospital."}},{"id":"PH-H15634-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the implementation of this Act shall be funded out of the\nappropriations authorized by Batas Pambansa Blg. 230 for the Ministry of Health intended for new or\nexpanded hospitals. Thereafter, such sum as may be necessary for its operation and maintenance shall be\nincluded in the annual General Appropriations Act."}},{"id":"PH-H15634-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
  FT["PH-H15635"] = {"id":"PH-H15635","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 806  An Act Converting Certain Provincial Roads in the Province of Romblon Into National Roads","orig":"Batas Pambansa Blg. 806  An Act Converting Certain Provincial Roads in the Province of Romblon Into National Roads"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 806","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00806_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00806_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15635-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The Ferrol-Buenavista Looc Provincial Road, the Linawan-Mablaran Falls Provincial Road both\nin the Island of Tablas and the Magdiwang-Agtiwa-San Fernando Provincial Road in the Island of Sibuyan, all\nin the Province of Romblon, are converted into national roads."}},{"id":"PH-H15635-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount necessary for the improvement and maintenance of said roads shall continue to be\nfunded out of the lump sum appropriation authorized under Batas Pambansa Blg. 640 for the repair and\nmaintenance of local roads until such time that the maintenance funds for said roads shall have been provided\nfor in the succeeding appropriations acts."}},{"id":"PH-H15635-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
