  FT["PH-H15654"] = {"id":"PH-H15654","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (source has HTML full text only)","fetchedAt":"2026-10-28","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"Batas Pambansa Blg. 825  An Act Reclassifying Certain Hospitals in Region VI, Appropriating Funds therefor","orig":"Batas Pambansa Blg. 825  An Act Reclassifying Certain Hospitals in Region VI, Appropriating Funds therefor"},"level":"law","status":"active","docNumber":"Batas Pambansa Blg. 825","issuingBody":"Batasang Pambansa","promulgatedDate":"1984-04-27","completenessNote":"全文，共 3 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 BP_00825_1984_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/08_国民议会法令_BP/BP_00825_1984_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H15654-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"en":"The following hospitals in Region VI are reclassified as follows:\nIloilo Provincial Hospital in the City of Iloilo to a medical center to be known as the Western Visayas Medical\nDoña Corazon Montelibano Locsin Memorial Hospital in the City of Bacolod to a regional hospital to be\nknown as the Doña Corazon Locsin Montelibano Memorial Regional Hospital."}},{"id":"PH-H15654-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"en":"The amount needed for the implementation of this Act shall charged to the appropriations of the\nMinistry of Health provided in Batas Pambansa Blg. 640. Thereafter, the amount necessary for the same\npurpose shall be included in subsequent annual general appropriations acts."}},{"id":"PH-H15654-A3","no":3,"noLabel":{"en":"Section 3"},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 27, 1984"}}],"pack":"ph-p156"};
