  FT["PH-H16558"] = {"id":"PH-H16558","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1936/eo_11_1936.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"Designating the Chief of Staff and Transferring the Philippine Constabulary to the Army of the Philippines.","orig":"Designating the Chief of Staff and Transferring the Philippine Constabulary to the Army of the Philippines."},"level":"law","status":"active","docNumber":"Executive Order No. 11","issuingBody":"President of the Philippines","promulgatedDate":"1936-01-10","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00011_1936_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00011_1936_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16558-A1","no":1,"noLabel":{},"text":{"en":"MALACAÑAN PALACE\nBY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 11, January 11, 1936 ]\nDESIGNATING THE CHIEF OF STAFF AND TRANSFERRING THE PHILIPPINE CONSTABULARY\nTO THE ARMY OF THE PHILIPPINES\n1. Under authority contained in sections twenty-two and twenty-three of Commonwealth Act Numbered One,\nknown as “The National Defense Act” the following assignments to the General Staff Corps of the Army of\nthe Philippines are hereby announced:\n(a) Jose de los Reyes, appointed today a Brigadier General in the Regular Force, is hereby designated Acting\nChief of Staff.\n(b) General Basilio J. Valdes and Colonel Guillermo B. Francisco, of the Philippine Constabulary, are hereby\ndesignated Acting Assistant Chiefs of Staff."}}],"pack":"ph-p156"};
  FT["PH-H16559"] = {"id":"PH-H16559","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"LawPhil (HTML full text only)  |  https://lawphil.net/executive/execord/eo1944/eo_11-w_1944.html","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"W  Extending Further the Suspension of Granting Geological Exploration and Petroleum Drilling Leases","orig":"W  Extending Further the Suspension of Granting Geological Exploration and Petroleum Drilling Leases"},"level":"law","status":"active","docNumber":"Executive Order No. 11","issuingBody":"President of the Philippines","promulgatedDate":"1944-03-31","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00011_1944_html.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00011_1944_html.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16559-A1","no":1,"noLabel":{},"text":{"en":"BY THE PRESIDENT OF THE PHILIPPINES\n[ EXECUTIVE ORDER NO. 11-W, March 31, 1944 ]\nEXTENDING FURTHER THE SUSPENSION OF GRANTING GEOLOGICAL EXPLORATION AND\nPETROLEUM DRILLING LEASES\nWHEREAS as the National Assembly has by law (Commonwealth Act. No. 433) suspended for a period of\nfive years the granting of Geological Exploration and Petroleum Drilling Leases under the provisions of Act\nNumbered Two thousand nine hundred thirty-two and the rules and regulations promulgated thereunder:\nWHEREAS the period of suspension provided for by law will expire on May 31, 1944;\nWHEREAS the Congress of the Philippines under the present war situation cannot act on this matter;\nNOW, THEREFORE, in order to safeguard the interest of the Government of the Commonwealth of the\nPhilippines, I, MANUEL L. QUEZON, President of the Philippines, by virtue of the power vested in me by\nthe Constitution and existing law, do hereby suspended the granting of such Geological Exploration and\nPetroleum Drilling Lease for another five years from May 3, 1944, or until the Congress of the Philippines\nshall have otherwise provide by law.\nDone at the City of Miami Beach, State of Florida, United States of America, this thirty-first day of March, in\nthe year of Our Lord, nineteen hundred and forty-four, and of the Commonwealth of the Philippines, the ninth.\nMANUEL L. QUEZON\nPresident of the Philippines"}}],"pack":"ph-p156"};
