  FT["PH-H16588"] = {"id":"PH-H16588","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALACAÑANG PMS, LIBRARY PROVIDING FOR THE EXTENSION OF THE TERM OF THE TASK FORCE 'TO COMPLETE THE WIND-UP OF ACTIVITIES OF THE MT. PINATUBO ASSISTANCE, REHABILITATION AND DEVELOPMENT COMMISSION","orig":"MALACAÑANG PMS, LIBRARY PROVIDING FOR THE EXTENSION OF THE TERM OF THE TASK FORCE 'TO COMPLETE THE WIND-UP OF ACTIVITIES OF THE MT. PINATUBO ASSISTANCE, REHABILITATION AND DEVELOPMENT COMMISSION"},"level":"law","status":"active","docNumber":"Executive Order No. 13","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00013_2001.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00013_2001.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16588-A1","no":1,"noLabel":{"en":"SEC I"},"text":{"en":"The term of the Task Force created under EO No. 4 is extended until"}},{"id":"PH-H16588-A2","no":2,"noLabel":{"en":"SEC 2"},"text":{"en":"The DBM is authorized to retain the number of personnel necessary to\ncomplete the wind-up activities and disburse funds to support the operating expenses of\nthe Task Force and undertake the remaining works to be done to the newly constructed\n1,000 housing units located in the Resettlement Sites in Pandacaqui, Sta. Lucia and\nMadapdap, such as the development of roadnets and utilities which include electricity\nPGMA Outgoing 02088\n0 000\n\nand water systems, chargeable against the unutilized PARD funds previously authorized\nto be transferred to the DBM."}},{"id":"PH-H16588-A3","no":3,"noLabel":{"en":"SEC 3"},"text":{"en":"The Chairman of the MPC is authorized to execute all the MOAs\nimplementing the transfers of MPC functions to the appropriate successor agencies."}},{"id":"PH-H16588-A4","no":4,"noLabel":{"en":"SEC 4"},"text":{"en":"All other provisions under EO No. 4 not mentioned herein shall remain"}},{"id":"PH-H16588-A5","no":5,"noLabel":{"en":"SEC 5"},"text":{"en":"This Order shall take effect immediately upon signing.\nDone in the City of Manila, this 23rd day of April in the year of Our Lord, two\nthousand and one.\nBy the President:\nWALDO Q FLORES\nSenior Deputy EXecutive Secretary\nFMS LIBRARY\nPGMA Outgolng # 02089\nPMS LIBRARY BCODE001982"}}],"pack":"ph-p156"};
