  FT["PH-H16636"] = {"id":"PH-H16636","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":1,"structureMode":"WHOLE","title":{"zh":null,"en":"J1E PRESIDENT PJIILIPP1NES","orig":"J1E PRESIDENT PJIILIPP1NES"},"level":"law","status":"active","docNumber":"Executive Order No. 18","issuingBody":"President of the Philippines","completenessNote":"全文，共 1 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00018_1992.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00018_1992.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16636-A18","no":18,"noLabel":{"en":"Section 18"},"text":{"en":"of Executive\nOrder No. 239, dated\nJuly 24, 1987, is hereby deemed modified as\nto substitute\nthe words \"Technical\nAssistance\nwith the words \"Technical\nCooperation\nCouncil of the Philippines.\"\n3\nThis Executive\nOrder shall take effect immediately.\nDone in the City of Manila, this\nday of SeptE:.'ITlber\nin the year of Our Lord,\nnineteen hundred\nar1d ninety-two.\nBy the President.:\n\"~- ~.-'-\n/\n-\n~\n.-'\n/~\nONIS ii) C. DE LA SERNA\nDeputy Executive\nPMS LIBRARY BCODEOO5906"}}],"pack":"ph-p156"};
  FT["PH-H16637"] = {"id":"PH-H16637","coverage":"full","language":"en","sourceName":"The LawPhil Project — Arellano Law Foundation","sourceUrl":"","fetchedAt":"2026-10-28","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"MALAC.\\:r\\T AN PALACE INCREASING THE SUBSISTENCE ALLOWANCE OF OFFICERS AND ENLISTED PERSONNEL OF THE ARMED FORCES OF THE PHILIPPINES, DRAFTEES, TRAINEES PROBA nONARY LIEUTENANTS/ENSIGNS UNDERGOING CADETS ON SUMMER CAMP TRAINING AND RESERVE OFFICERS AND RESERVISTS UNDERGOING ASSEMBLY /MOBILJZA nON TEST AND CADETS OF mE PHILIPPINE Mll..ITARY ACADEMY AND PHILIPPINE AIR FORCE FLYING SCHOOL.","orig":"MALAC.\\:r\\T AN PALACE INCREASING THE SUBSISTENCE ALLOWANCE OF OFFICERS AND ENLISTED PERSONNEL OF THE ARMED FORCES OF THE PHILIPPINES, DRAFTEES, TRAINEES PROBA nONARY LIEUTENANTS/ENSIGNS UNDERGOING CADETS ON SUMMER CAMP TRAINING AND RESERVE OFFICERS AND RESERVISTS UNDERGOING ASSEMBLY /MOBILJZA nON TEST AND CADETS OF mE PHILIPPINE Mll..ITARY ACADEMY AND PHILIPPINE AIR FORCE FLYING SCHOOL."},"level":"law","status":"active","docNumber":"Executive Order No. 18","issuingBody":"President of the Philippines","completenessNote":"全文，共 5 条；逐字取自 LawPhil PDF 文本化成果（第三方 OCR，非机翻），原始文件 EO_00018_1998.txt","textQuality":"ocr-vendor","sourceFile":"菲律宾/法律原文/07_行政命令_EO/EO_00018_1998.txt","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H16637-A1","no":1,"noLabel":{"en":"SECTION 1"},"text":{"en":"The subsistence allowance for officers and enlisted personnel of the\nArmed Forces of the Philippines, including draftees, trainees and Probationary Second\nLieutenants/Ensigns undergoing military training, CMT cadets on summer camp training\nand reserve officers and enlisted reservists undergoing training and assembly/mobilization\ntest and cadets of Philippine Military Academy and Philippine Air Force Flying School, is\nhereby increased from Thirty Pesos (P30.00) to Sixty Pesos (P60.00) per day effective"}},{"id":"PH-H16637-A2","no":2,"noLabel":{"en":"SECTION 2"},"text":{"en":"Fund3 needed to implement this Executive Order in CY 1998 shall be\nsupported from DBM Reserve Control Account and in CY 1999 and beyond shall be\nincluded in the Annual Appropriations of the Armed Forces of the Philippines."}},{"id":"PH-H16637-A3","no":3,"noLabel":{"en":"SECTION 3"},"text":{"en":"The Secretary of National Defense shall issue such implementing\ninstructions as are necessary and proper to carry out the intent of this Executive Order."}},{"id":"PH-H16637-A4","no":4,"noLabel":{"en":"SECTION 4"},"text":{"en":"All rules and regulations and other issuances or parts thereof that are\nin conflict with this Executive Order are hereby repealed or modified accordingly."}},{"id":"PH-H16637-A5","no":5,"noLabel":{"en":"SECTION 5"},"text":{"en":"This Executive Order shall take eff~t September 1, 1998.\nDone in the City of Manila, this 25th day of August, in the year of Our Lord,\nnineteen hundred and ninety-eight.\n?\"\"\"'~\nBy the President:\nRONALDO B. ZAMORA\nExecutive Secretary"}}],"pack":"ph-p156"};
